UPDATE qr_tafsir_entries SET content_ar = 'القول في تأويل قوله تعالى: ﴿وَلَقَدْ أَرْسَلْنَا مِنْ قَبْلِكَ فِي شِيَعِ الأوَّلِينَ (١٠) وَمَا يَأْتِيهِمْ مِنْ رَسُولٍ إِلا كَانُوا بِهِ يَسْتَهْزِئُونَ (١١) ﴾ يقول تعالى ذكره لنبيه محمد ﷺ: ولقد أرسلنا يا محمد من قبلك في الأمم الأوّلين رسلا وترك ذكر الرسل اكتفاء بدلالة قوله ﴿وَلَقَدْ أَرْسَلْنَا مِنْ قَبْلِكَ﴾ عليه، وعنى بشيع الأوّلين: أمم الأوّلين: واحدتها شيعة، ويقال أيضا لأولياء الرجل: شيعته. وبنحو الذي قلنا في ذلك، قال أهل التأويل. ذكر من قال ذلك: ⁕ حدثني المثنى، قال: ثنا عبد الله، قال: ثني معاوية، عن عليّ، عن ابن عباس: ﴿وَلَقَدْ أَرْسَلْنَا مِنْ قَبْلِكَ فِي شِيَعِ الأوَّلِينَ﴾ يقول: أمم الأولين. ⁕ حدثني المثنى، قال: أخبرنا إسحاق، قال: ثنا هشام، عن عمرو، عن سعيد، عن قتادة، في قوله ﴿وَلَقَدْ أَرْسَلْنَا مِنْ قَبْلِكَ فِي شِيَعِ الأوَّلِينَ﴾ قال: في الأمم. * * وقوله ﴿وَمَا يَأْتِيهِمْ مِنْ رَسُولٍ إِلا كَانُوا بِهِ يَسْتَهْزِئُونَ﴾ يقول: وما يأتي شيع الأوّلين من رسول من الله يرسله إليهم بالدعاء إلى توحيده، والإذعان بطاعته،إلا كانوا به يستهزءون: يقول: إلا كانوا يسخرون بالرسول الذي يرسله الله إليهم عتُوّا منهم وتمرّدا على ربهم. * * القول في تأويل قوله تعالى: ﴿كَذَلِكَ نَسْلُكُهُ فِي قُلُوبِ الْمُجْرِمِينَ (١٢) لا يُؤْمِنُونَ بِهِ وَقَدْ خَلَتْ سُنَّةُ الأوَّلِينَ (١٣) ﴾ يقول تعالى ذكره: كما سلكنا الكفر في قلوب شيع الأولين بالاستهزاء بالرسل، كذلك نفعل ذلك في قلوب مشركي قومك الذين أجرموا بالكفر بالله ﴿لا يُؤْمِنُونَ بِهِ﴾ يقول: لا يصدّقون بالذكر الذي أنزل إليك، والهاء في قوله ﴿نَسْلُكُهُ﴾ من ذكر الاستهزاء بالرسل والتكذيب بهم. كما:- ⁕ حدثنا القاسم، قال: ثنا الحسين، قال: ثني حجاج، عن ابن جريج ﴿كَذَلِكَ نَسْلُكُهُ فِي قُلُوبِ الْمُجْرِمِينَ﴾ قال: التكذيب. ⁕ حدثنا محمد بن عبد الأعلى، قال: ثنا محمد بن ثور، عن معمر، عن قتادة ﴿كَذَلِكَ نَسْلُكُهُ فِي قُلُوبِ الْمُجْرِمِينَ﴾ لا يؤمنون به، قال: إذا كذبوا سلك الله في قلوبهم أن لا يؤمنوا به. ⁕ حدثنا الحسن بن يحيى، قال: أخبرنا عبد الرزاق، قال: أخبرنا الثوري، عن حميد، عن الحسن، في قوله ﴿كَذَلِكَ نَسْلُكُهُ فِي قُلُوبِ الْمُجْرِمِينَ﴾ قال: الشرك. ⁕ حدثني المثنى، قال: ثنا الحجاج بن المنهال، قال: ثنا حماد بن سلمة، عن حميد، قال: قرأت القرآن كله على الحسن في بيت أبي خليفة، ففسره أجمع على الإثبات، فسألته عن قوله ﴿كَذَلِكَ نَسْلُكُهُ فِي قُلُوبِ الْمُجْرِمِينَ﴾ قال: أعمال سيعملونها لم يعملوها. ⁕ حدثني المثنى، قال: ثنا سويد، قال: أخبرنا ابن المبارك عن حماد بن سلمة، عن حميد الطويل، قال: قرأت القرآن كله على الحسن، فما كان يفسره إلا على الإثبات، قال: وقفته على نسلكه، قال: الشرك، قال: ابن المبارك: سمعت سفيان في قوله ﴿نَسْلُكُهُ﴾ قال: نجعله. ⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد في قوله ﴿كَذَلِكَ نَسْلُكُهُ فِي قُلُوبِ الْمُجْرِمِينَ لا يُؤْمِنُونَ بِهِ﴾ قال: هم كما قال الله، هو أضلهم ومنعهم الإيمان، يقال منه: سلكه يسلكه سلكا وسلوكا، وأسلكه يسلكه إسلاكا، ومن السلوك قول عديّ بن زيد: وكنْت لِزَازَ خَصْمِكَ لَمْ أعرّدْ ... وَقَدْ سَلَكوكَ فِي يَوْم عَصِيبٍ [[البيت لعدي بن زيد العبادي، وقد تقدم واستشهد المؤلف به عند قوله تعالى في سورة هود "وقال هذا يوم عصيب " فراجعه في الجزء الثاني عشر . والشاهد فيه هنا: أنه اشتق سلكوك من المصدر الثلاثي (السلك) .]] ومن الإسلاك قول الآخر: حتى إذَا أسْلَكُوهُمْ في قُتَائِدَةٍ ... شَلا كَما تَطْرد الجَمالَة الشردَا [[البيت لعبد مناف بن ربعي الهذلي (اللسان: جمل) استشهد به المؤلف على أن " أسلكوهم " بالهمزة في أوله لغة مثل سلوكهم التي وردت في البيت السابق من شعر عدي بن زيد، والبيت أيضا في (خزانة الأدب للبغدادي ٣: ١٧٠) شاهد على أن جواب إذا عند الرضى شارح كافية ابن الحاجب محذوف لتفخيم الأمر، والتقدير: بلغوا أملهم؛ أو أدركوا ما أحبوا ونحو ذلك، وقيل فيه وجهان آخران، قال البغدادي وأسلك: لغة في سلك، يقال أسلكت الشيء في الشيء، مثل سلكته فيه، بمعنى أدخلته فيه، وقتائدة: ثنية، وقال البكري: جبل بين المنصرف والروحاء، والشل: الطرد، والجمالة: فاعلي تطرد، وهم أصحاب الجمال، كما يقال الحمارة لأصحاب الحمير، والشرد: جمع شرود، أي من الجمال.]] * * وقوله ﴿وَقَدْ خَلَتْ سُنَّةُ الأوَّلِينَ﴾ يقول تعالى ذكره: لا يؤمن بهذا القرآن قومك الذين سلكت في قلوبهم التكذيب ﴿حَتَّى يَرَوُا الْعَذَابَ الألِيمَ﴾ أخذا منهم سنة أسلافهم من المشركين قبلهم من قوم عاد وثمود وضربائهم من الأمم التي كذّبت رسلها، فلم تؤمن بما جاءها من عند الله حتى حلّ بها سخط الله فهلكت. وبنحو الذي قلنا في ذلك، قال أهل التأويل. ذكر من قال ذلك: ⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله ﴿كَذَلِكَ نَسْلُكُهُ فِي قُلُوبِ الْمُجْرِمِينَ لا يُؤْمِنُونَ بِهِ وَقَدْ خَلَتْ سُنَّةُ الأوَّلِينَ﴾ وقائع الله فيمن خلا قبلكم من الأمم.',     source_page = '82',     updated_at  = datetime('now') WHERE id = 'QR:TE:2198b24051dbe749c828ec5d';
UPDATE qr_tafsir_entries SET content_ar = 'القول في تأويل قوله تعالى: ﴿وَمِنْ ثَمَرَاتِ النَّخِيلِ وَالأعْنَابِ تَتَّخِذُونَ مِنْهُ سَكَرًا وَرِزْقًا حَسَنًا إِنَّ فِي ذَلِكَ لآيَةً لِقَوْمٍ يَعْقِلُونَ (٦٧) ﴾ يقول تعالى ذكره: ولكم أيضًا أيها الناس عِبرةٌ فيما نسقيكم من ثمرات النخيل والأعناب ما تتخذون منه سكرا ورزقا حسنا، مع ما نسقيكم من بطون الأنعام من اللبن الخارج من بين الفرث والدم. وحذف من قوله ﴿وَمِنْ ثَمَرَاتِ النَّخِيلِ وَالأعْنَابِ﴾ الاسم، والمعنى ما وصفت، وهو: ومن ثمرات النخيل والأعناب ما تتخذون منه لدلالة "مِن" عليه، لأن "من" تدخل في الكلام مُبَعِّضة، فاستغني بدلالتها ومعرفة السامعين بما يقتضي من ذكر الاسم معها. وكان بعض نحويِّي البصرة يقول في معنى الكلام: ومن ثمرات النخيل والأعناب شيء تتخذون منه سكرا، ويقول: إنما ذكرت الهاء في قوله ﴿تَتَّخِذُونَ مِنْهُ﴾ لأنه أريد بها الشيء، وهو عندنا عائد على المتروك، وهو "ما". * * وقوله ﴿تَتَّخِذُونَ﴾ من صفة "ما" المتروكة. واختلف أهل التأويل في معنى قوله ﴿تَتَّخِذُونَ مِنْهُ سَكَرًا وَرِزْقًا حَسَنًا﴾ فقال بعضهم: عني بالسَّكَر: الخمر، وبالرزق الحسن: التمر والزبيب، وقال: إنما نزلت هذه الآية قبل تحريم الخمر، ثم حُرّمت بعد. ذكر من قال ذلك: ⁕ حدثني محمد بن عبيد المحاربيّ، قال: ثنا أيوب بن جابر السُّحَيْمي، عن الأسود، عن عمرو بن سفيان، عن ابن عباس، قوله ﴿تَتَّخِذُونَ مِنْهُ سَكَرًا وَرِزْقًا حَسَنًا﴾ قال: السَّكَر: ما حُرِّم من شرابه، والرزق الحسن: ما أحلّ من ثمرته. ⁕ حدثنا ابن وكيع وسعيد بن الربيع الرازي، قالا ثنا ابن عيينة، عن الأسود بن قيس، عن عمرو بن سفيان، عن ابن عباس ﴿تَتَّخِذُونَ مِنْهُ سَكَرًا وَرِزْقًا حَسَنًا﴾ قال: الرزق الحسن: ما أحلّ من ثمرتها، والسكر: ما حرّم من ثمرتها. ⁕ حدثنا ابن وكيع، قال: ثنا أبي، عن سفيان، عن الأسود، عن عمرو بن سفيان، عن ابن عباس مثله. ⁕ حدثنا الحسن بن يحيى، قال: أخبرنا عبد الرزاق، قال: أخبرنا الثوري، عن الأسود بن قيس، عن عمرو بن سفيان، عن ابن عباس، بنحوه. ⁕ حدثني المثنى، قال: ثنا أبو نعيم الفضل بن دكين، قال: ثنا سفيان، عن الأسود بن قيس، عن عمرو بن سفيان، عن ابن عباس بنحوه. ⁕ حدثنا ابن المثنى، قال: ثنا محمد بن جعفر، قال: ثنا شعبة، عن الأسود بن قيس، قال: سمعت رجلا يحدّث عن ابن عباس في هذه الآية ﴿تَتَّخِذُونَ مِنْهُ سَكَرًا وَرِزْقًا حَسَنًا﴾ قال: السكر: ما حُرِّم من ثمرتيهما، والرزق الحسن: ما أحلّ من ثمرتيهما. ⁕ حدثنا أحمد بن إسحاق، قال: ثنا أبو أحمد، قال: ثنا الحسن بن صالح، عن الأسود بن قيس، عن عمرو بن سفيان، عن ابن عباس، بنحوه. ⁕ حدثني المثنى، قال: ثنا أبو غسان، قال: ثنا زهير بن معاوية، قال: ثنا الأسود بن قيس، قال: ثني عمرو بن سفيان، قال: سمعت ابن عباس يقول، وذكرت عنده هذه الآية (وَمِنْ ثَمَرَاتِ النَّخِيلِ وَالأعْنَابِ تَتَّخِذُونَ مِنْهُ سَكَرًا وَرِزْقًا حَسَنًا) قال: السكر: ما حرّم منهما، والرزق الحسن: ما أحلّ منهما. ⁕ حدثني يونس، قال: أخبرنا سفيان، عن الأسود بن قيس، عن عمرو بن سفيان البصري، قال: قال ابن عباس، في قوله ﴿تَتَّخِذُونَ مِنْهُ سَكَرًا وَرِزْقًا حَسَنًا﴾ قال: فأما الرزق الحسن: فما أحلّ من ثمرتهما، وأما السكر: فما حرّم من ثمرتهما. ⁕ حدثني المثنى، قال: أخبرنا الحمَّاني، قال: ثنا شريك، عن الأسود، عن عمرو بن سفيان البصريّ، عن ابن عباس ﴿تَتَّخِذُونَ مِنْهُ سَكَرًا وَرِزْقًا حَسَنًا﴾ قال: السَّكَر: حرامه، والرزق الحسن: حلاله. ⁕ حدثني المثنى، قال: أخبرنا العباس بن أبي طالب، قال: ثنا أبو عوانة، عن الأسود، عن عمرو بن سفيان، عن ابن عباس قال: السَّكَر: ما حرّم من ثمرتهما، والرزق الحسن: ما حلّ من ثمرتهما. ⁕ حدثنا أحمد بن إسحاق، قال: ثنا أبو أحمد، قال: ثنا إسرائيل، عن أبي حصين، عن سعيد بن جبير، عن ابن عباس، قال: الرزق الحسن: الحلال، والسَّكَر: الحرام. ⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا سفيان، عن أبي حصين، عن سعيد بن جبير ﴿تَتَّخِذُونَ مِنْهُ سَكَرًا وَرِزْقًا حَسَنًا﴾ قال: ما حرم من ثمرتهما، وما أحلّ من ثمرتهما. ⁕ حدثنا أحمد، قال: ثنا أبو أحمد، قال: ثنا سفيان، عن أبي حصين، عن سعيد بن جبير، قال: السَّكَر خمر، والرزق الحسن الحلال. ⁕ حدثنا ابن وكيع، قال: ثنا أبي، عن مسعر وسفيان، عن أبي حصين، عن سعيد بن جبير، قال: الرزق الحسن: الحلال، والسَّكَر: الحرام. ⁕ حدثني المثنى، قال: ثنا أبو نعيم، قال: ثنا سفيان، عن أبي حصين، عن سعيد بن جبير، بنحوه. ⁕ حدثنا ابن بشار، قال: ثنا محمد بن جعفر، قال: ثنا شعبة، عن أبي بشر، عن سعيد بن جبير، في هذه الآية ﴿تَتَّخِذُونَ مِنْهُ سَكَرًا وَرِزْقًا حَسَنًا﴾ قال: السَّكَر: الحرام، والرزق الحسن: الحلال. ⁕ حدثنا ابن حميد، قال: ثنا جرير، عن مغيرة، عن أبي رزين ﴿تَتَّخِذُونَ مِنْهُ سَكَرًا وَرِزْقًا حَسَنًا﴾ قال: نزل هذا وهم يشربون الخمر، فكان هذا قبل أن ينزل تحريم الخمر. ⁕ حدثنا محمد بن المثنى، قال: ثنا عبد الرحمن بن مهدي، قال: ثنا شعبة، عن المُغيرة، عن إبراهيم والشعبيّ وأبي رزين، قالوا: هي منسوخة في هذه الآية ﴿تَتَّخِذُونَ مِنْهُ سَكَرًا وَرِزْقًا حَسَنًا﴾ ⁕ حدثنا الحسن بن عرفة، قال: ثنا أبو قطن، عن سعيد، عن المغيرة، عن إبراهيم والشعبي، وأبي رزين بمثله. ⁕ حدثني المثنى، قال: ثنا عمرو بن عون، قال: أخبرنا هشيم، عن مغيرة، عن إبراهيم، في قوله ﴿تَتَّخِذُونَ مِنْهُ سَكَرًا وَرِزْقًا حَسَنًا﴾ قال: هي منسوخة نسخها تحريم الخمر. ⁕ حدثنا محمد بن بشار، قال: ثنا هوذة، قال: ثنا عوف، عن الحسن، في قوله ﴿تَتَّخِذُونَ مِنْهُ سَكَرًا وَرِزْقًا حَسَنًا﴾ قال: ذكر الله نعمته في السكر قبل تحريم الخمر ⁕ حدثني المثنى، قال: ثنا عمرو بن عون، قال: أخبرنا هشيم، عن منصور وعوف، عن الحسن، قال السكر: ما حرم الله منه، والرزق: ما أحلّ الله منه. ⁕ حدثنا ابن وكيع، قال: ثنا أبي، عن أبي جعفر، عن الربيع، عن الحسن، قال: الرزق الحسن: الحلال، والسَّكَر: الحرام. ⁕ حدثنا ابن وكيع، قال: ثنا أبي، عن سلمة، عن الضحاك، قال: الرزق الحسن: الحلال، والسَّكَر: الحرام. ⁕ حدثنا ابن وكيع، قال: ثنا أبو أسامة، عن أبي كدينة يحيى بن المهلب، عن ليث، عن مجاهد قال: السَّكر: الخمر، والرزق الحسن، الرُّطب والأعناب. ⁕ حدثنا أحمد بن إسحاق، قال: ثنا أبو أحمد، قال: ثنا شريك، عن ليث، عن مجاهد ﴿تَتَّخِذُونَ مِنْهُ سَكَرًا﴾ قال: هي الخمر قبل أن تحرّم. ⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء وحدثني المثنى، قال: ثنا أبو حُذيفة، قال: ثنا شبل جميعا، عن ابن أبي نجيح، عن مجاهد ﴿تَتَّخِذُونَ مِنْهُ سَكَرًا﴾ قال: الخمر قبل تحريمها، ﴿وَرِزْقًا حَسَنًا﴾ قال: طعاما. ⁕ حدثنا القاسم، قال: ثنا الحسين، قال: ثني حجاج، عن ابن جريج، عن مجاهد بنحوه. ⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله ﴿وَمِنْ ثَمَرَاتِ النَّخِيلِ وَالأعْنَابِ تَتَّخِذُونَ مِنْهُ سَكَرًا وَرِزْقًا حَسَنًا﴾ أما السَّكَر: فخمور هذه الأعاجم، وأما الرزق الحسن: فما تنتبذون، وما تُخَلِّلون، وما تأكلون، ونزلت هذه الآية ولم تحرّم الخمر يومئذ، وإنما جاء تحريمها بعد ذلك في سورة المائدة. ⁕ حدثنا ابن وكيع، قال: ثنا عبدة بن سليمان، قال: قرأت على ابن أبي عُذرة، قال: هكذا سمعت قتادة ﴿تَتَّخِذُونَ مِنْهُ سَكَرًا وَرِزْقًا حَسَنًا﴾ ثم ذكر نحو حديث بشر. ⁕ حدثنا محمد بن عبد الأعلى، قال: ثنا محمد بن ثور، عن معمر، عن قتادة ﴿سَكَرًا﴾ قال: هي خمور الأعاجم، ونُسِخت في سورة المائدة، والرزق الحسن قال: ما تنتبذون وتُخَلِّلون وتأكلون. ⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس ﴿وَمِنْ ثَمَرَاتِ النَّخِيلِ وَالأعْنَابِ تَتَّخِذُونَ مِنْهُ سَكَرًا وَرِزْقًا حَسَنًا﴾ وذلك أن الناس كانوا يسمُّون الخمر سكرا، وكانوا يشربونها، قال ابن عباس [[قوله: قال ابن عباس إلى يرجعوا منه. كذا في النسخ. وهو كالمقحم وسط الكلام، وقد أسقطه السيوطي من الدر المنثور حين روى هذا الحديث.]] مرّ رجال بوادي السكران الذي كانت قريش تجتمع فيه، إذا تَلَقَّوا مسافريهم إذا جاءوا من الشام، وانطلقوا معهم يشيعونهم حتى يبلغوا وادي السكران ثم يرجعوا منه، ثم سماها الله بعد ذلك الخمر حين حرمت، وقد كان ابن عباس يزعم أنها الخمر، وكان يزعم أن الحبشة يسمون الخلّ السَّكَر. * * قوله ﴿وَرِزْقًا حَسَنًا﴾ يعني بذلك: الحلال التمر والزبيب، وما كان حلالا لا يسكر. وقال آخرون: السَّكَر بمنزلة الخمر في التحريم، وليس بخمر، وقالوا: هو نقيع التمر والزبيب إذا اشتدّ وصار يُسْكِر شاربه. ذكر من قال ذلك: ⁕ حدثنا ابن حميد، قال: ثنا الحكم بن بشير، قال: ثنا عمرو، في قوله ﴿وَمِنْ ثَمَرَاتِ النَّخِيلِ وَالأعْنَابِ تَتَّخِذُونَ مِنْهُ سَكَرًا وَرِزْقًا حَسَنًا﴾ قال ابن عباس: كان هذا قبل أن ينزل تحريم الخمر والسكر حرام مثل الخمر؛ وأما الحلال منه، فالزبيب والتمر والخل ونحوه. ⁕ حدثني المثنى، وعلي بن داود، قالا ثنا عبد الله بن صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، قوله ﴿تَتَّخِذُونَ مِنْهُ سَكَرًا﴾ فحرّم الله بعد ذلك، يعني بعد ما أنزل في سورة البقرة من ذكر الخمر، والميسر والأنصاب والأزلام، السَّكَر مع تحريم الخمر لأنه منه، قال ﴿وَرِزْقًا حَسَنًا﴾ فهو الحلال من الخلّ والنبيذ، وأشباه ذلك، فأقرّه الله وجعله حلالا للمسلمين. ⁕ حدثنا أحمد، قال: ثنا أبو أحمد، قال: ثنا إسرائيل، عن موسى، قال: سألت مرّة عن السَّكَر، فقال: قال عبد الله: هو خمر. ⁕ حدثنا أحمد، قال: ثنا أبو أحمد، قال: ثنا إسرائيل، عن أبي فروة، عن أبي عبد الرحمن بن أبي ليلى، قال: السَّكَر: خمر. ⁕ حدثنا أحمد، قال: ثنا أبو أحمد، قال: ثنا سفيان، عن أبي الهيثم، عن إبراهيم، قال: السَّكَر: خمر. ⁕ حدثنا أحمد، قال: ثنا أبو أحمد، قال: ثنا حسن بن صالح، عن مغيرة، عن إبراهيم وأبي رزين، قالا السَّكَر: خمر. ⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله ﴿تَتَّخِذُونَ مِنْهُ سَكَرًا﴾ يعني: ما أسكر من العنب والتمر ﴿وَرِزْقًا حَسَنًا﴾ يعني: ثمرتها. ⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله ﴿تَتَّخِذُونَ مِنْهُ سَكَرًا وَرِزْقًا حَسَنًا﴾ قال: الحلال ما كان على وجه الحلال حتى غيروها فجعلوا منها سَكَرا. وقال آخرون: السَّكَر: هو كلّ ما كان حلالا شربه، كالنبيذ الحلال والخلّ والرطَب. والرزق الحسن: التمر والزبيب. ذكر من قال ذلك: ⁕ حدثني داود الواسطيّ، قال: ثنا أبو أسامة، قال أبو رَوْق: ثني قال: قلت للشعبيّ: أرأيت قوله تعالى ﴿تَتَّخِذُونَ مِنْهُ سَكَرًا﴾ أهو هذا السكر الذي تصنعه النَّبَط؟ قال: لا هذا خمر، إنما السَّكَر الذي قال الله تعالى ذكره: النبيذ والخلّ والرزق الحسن: التمر والزبيب. ⁕ حدثني يحيى بن داود، قال: ثنا أبو أسامة، قال: وذكر مجالد، عن عامر، نحوه. ⁕ حدثني أحمد بن إسحاق، قال: ثنا أبو أحمد، قال: ثنا مندل، عن ليث، عن مجاهد ﴿تَتَّخِذُونَ مِنْهُ سَكَرًا وَرِزْقًا حَسَنًا﴾ قال: ما كانوا يتخذون من النخل النَّبيذ، والرزق الحسن: ما كانوا يصنعون من الزبيب والتمر. ⁕ حدثنا أحمد، قال: ثنا أبو أحمد، قال: ثنا مندل، عن أبي رَوْق، عن الشعبيّ، قال: قلت له: ما تتخذون منه سَكَرا؟ قال: كانوا يصنعون من النبيذ والخلّ قلت: والرزق الحسن؟ قال: كانوا يصنعون من التمر والزبيب. ⁕ حدثنا ابن وكيع، قال: ثنا أبو أسامة وأحمد بن بشير، عن مجالد، عن الشعبيّ، قال: السَّكَر: النبيذ والرزق الحسن: التمر الذي كان يؤكل، وعلى هذا التأويل، الآية غير منسوخة، بل حكمها ثابت. وهذا التأويل عندي هو أولى الأقوال بتأويل هذه الآية، وذلك أن السَّكَر في كلام العرب على أحد أوجه أربعة: أحدها: ما أسكر من الشراب. والثاني: ما طُعِم من الطعام، كما قال الشاعر: جَعَلْتُ عَيْبَ الأكْرَمِينَ سَكَرَا [[تقدم الكلام على هذا الشاهد في من هذا الجزء. وقال أبو عبيدة في مجاز القرآن (١: ٣٦٣) عند قوله تعالى: "تتخذون منه سكرا": أي طعما، وهذا له سكر: أي طعم. وقال جندل "جعلت عيب الأكرمين من سكرا". قال: وله موضع آخر، مجازه سكنا. وروايته البيت في اللسان: جَعَلْتَ أعْرَاضَ الكَرامِ سَكَرَا أي جعلت ذمهم طعما لك.]] أي طعما. والثالث: السُّكُون، من قول الشاعر: جَعَلْتُ عَيْنَ الحَرُورِ تَسْكُرُ [[تقدم الكلام على هذا الشاهد في صفحة؟ من هذا الجزء واستشهد به أبو عبيدة في مجاز القرآن (١: = ٣٦٣) بعد الشاهد السابق، وعطفه عليه بقوله: وقال: جاء الشتاء واجتأل القنبر ... وجعلت عين الحرور تسكر أي يكسن حرها ويخبو. ويقال: ليلة ساكرة: أي ساكنة. وقال: تريد الليالي في طولها ... وليست بطلق ولا ساكرة ويروي: تزيد ليالي في طولها. أهـ. وفي (اللسان: سكر) : تزاد.]] وقد بيَّنا ذلك فيما مضى. والرابع: المصدر من قولهم: سَكَر فلان يَسْكَر سُكْرا وسَكْرا وسَكَرا، فإذا كان ذلك كذلك، وكان ما يُسْكِر من الشراب حراما بما قد دللنا عليه في كتابنا المسمى: "لطيف القول في أحكام شرائع الإسلام" وكان غير جائز لنا أن نقول: هو منسوخ، إذ كان المنسوخ هو ما نفى حكمه الناسخ، وما لا يجوز اجتماع الحكم به وناسخه، ولم يكن في حكم الله تعالى ذكره بتحريم الخمر دليل على أن السَّكَر الذي هو غير الخمر، وغير ما يسكر من الشراب، حرام، إذ كان السكر أحد معانيه عند العرب، ومن نزل بلسانه القرآن هو كلّ ما طعم، ولم يكن مع ذلك، إذ لم يكن في نفس التنزيل دليل على أنه منسوخ، أو ورد بأنه منسوخ خبر من الرسول، ولا أجمعت عليه الأمة، فوجب القول بما قلنا من أن معنى السَّكَر في هذا الموضع: هو كلّ ما حلّ شربه، مما يتخذ من ثمر النخل والكرم، وفسد أن يكون معناه الخمر أو ما يسكر من الشراب، وخرج من أن يكون معناه السَّكَر نفسه، إذ كان السَّكَر ليس مما يتخذ من النَّخْل والكَرْم، ومن أن يكون بمعنى السكون. * * وقوله ﴿إِنَّ فِي ذَلِكَ لآيَةً لِقَوْمٍ يَعْقِلُونَ﴾ يقول: فيما إن وصفنا لكم من نعمنا التي آتيناكم أيها الناس من الأنعام والنخل والكرم، لدلالة واضحة وآية بينة لقوم يعقلون عن الله حججه، ويفهمون عنه مواعظه، فيتعظون بها.',     source_page = '13',     updated_at  = datetime('now') WHERE id = 'QR:TE:10dd6d1f2c398c9f6f42d420';
UPDATE qr_tafsir_entries SET content_ar = 'القول في تأويل قوله تعالى: ﴿وَاللَّهُ جَعَلَ لَكُمْ مِنْ أَنْفُسِكُمْ أَزْوَاجًا وَجَعَلَ لَكُمْ مِنْ أَزْوَاجِكُمْ بَنِينَ وَحَفَدَةً وَرَزَقَكُمْ مِنَ الطَّيِّبَاتِ أَفَبِالْبَاطِلِ يُؤْمِنُونَ وَبِنِعْمَةِ اللَّهِ هُمْ يَكْفُرُونَ (٧٢) ﴾ يقول تعالى ذكره ﴿وَاللَّهُ﴾ الذي ﴿جَعَلَ لَكُمْ﴾ أيها الناس ﴿مِنْ أَنْفُسِكُمْ أَزْوَاجًا﴾ يعني أنه خلق من آدم زوجته حوّاء، ﴿وَجَعَلَ لَكُمْ مِنْ أَزْوَاجِكُمْ بَنِينَ وَحَفَدَةً﴾ . كما:- ⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَاللَّهُ جَعَلَ لَكُمْ مِنْ أَنْفُسِكُمْ أَزْوَاجًا﴾ : أي والله خلق آدم، ثم خلق زوجته منه ثم جعل لكم بنين وحفدة. واختلف أهل التأويل في المعنيين بالحفدة، فقال بعضهم: هم الأختان، أختان الرجل على بناته. ذكر من قال ذلك: ⁕ حدثنا أبو كريب وابن وكيع، قالا ثنا أبو معاوية، قال: ثنا أبان بن تغلب، عن المنهال بن عمرو، عن ابن حبيش، عن عبد الله ﴿بَنِينَ وَحَفَدَةً﴾ قال: الأختان. ⁕ حدثنا أبو كريب، قال: ثنا أبو بكر، عن عاصم، عن ورقاء سألت عبد الله: ما تقول في الحَفَدَة؟ هم حَشَم الرجل يا أبا عبد الرحمن؟ قال: لا ولكنهم الأختان. ⁕ حدثنا محمد بن بشار، قال: ثنا عبد الرحمن؛ وحدثنا أحمد بن إسحاق، قال: ثنا أبو أحمد، قالا جميعا: ثنا سفيان، عن عاصم بن بَهْدَلة، عن زِرّ بن حُبَيْش، عن عبد الله، قال: الحَفَدَة: الأختان. ⁕ حدثنا ابن وكيع، قال: ثنا أبي. عن سفيان بإسناده عن عبد الله، مثله. ⁕ حدثنا ابن بشار وأحمد بن الوليد القرشي وابن وكيع وسوار بن عبد الله العنبريّ ومحمد بن خلف بن خراش والحسن بن خلف الواسطيّ، قالوا: ثنا يحيى بن سعيد القطان، عن الأعمش، عن أبي الضحى، قال: الحَفَدَة: الأختان. ⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا هشيم، عن المغيرة، عن إبراهيم، قال: الحَفَدَة: الأختان. ⁕ حدثنا أحمد بن إسحاق، قال: ثنا أبو أحمد، قال: ثنا إسرائيل، عن عطاء بن السائب، عن سعيد بن جبير ﴿بَنِينَ وَحَفَدَةً﴾ قال: الحَفَدَة: الأختان. ⁕ حدثنا ابن حميد، قال: ثنا جرير، عن مغيرة، عن إبراهيم، قال: الحَفَدَة: الخَتْن. ⁕ حدثنا ابن وكيع، قال: ثنا ابن عيينة، عن عاصم، عن زِرّ، عن عبد الله، قال: الأختان. ⁕ حدثنا ابن وكيع، قال: ثنا حفص، عن أشعث، عن عكرمة، عن ابن عباس، قال: الأختان. ⁕ وحدثني المثنى، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ عن ابن عباس، قوله ﴿وَحَفَدَةً﴾ قال: الأصهار. ⁕ حدثني المثنى، قال: ثنا الحجاج، قال: ثنا حماد، عن عاصم، عن زِرّ، عن ابن مسعود، قال: الحَفَدَة: الأختان. ⁕ حدثنا الحسن بن يحيى، قال: أخبرنا عبد الرزاق، قال: أخبرنا ابن عيينة، عن عاصم بن أبي النجود، عن زرّ بن حبيش، قال: قال لي عبد الله بن مسعود: ما الحَفَدَة يا زِرّ؟ قال: قلت: هم أحفاد الرجل من ولده وولد ولده. قال: لا هم الأصهار. وقال آخرون: هم أعوان الرجل وخدمه. ذكر من قال ذلك: ⁕ حدثني محمد بن خالد بن خداش، قال: ثني سليم بن قتيبة، عن وهب بن حبيب الأسَدي، عن أبي حمزة، عن ابن عباس سئل عن قوله ﴿بَنِينَ وَحَفَدَةً﴾ قال: من أعانك فقد حَفَدك، أما سمعت قوله الشاعر: حَفَدَ الوَلائِدُ حَوْلَهُنَّ وأُسْلِمَتْ ... بأكُفِّهِنَّ أزِمَّةُ الأجْمال [[استشهد بالبيت أبو عبيدة في مجاز القرآن: (١: ٣٦٤) ونسبه لجميل بن عبد الله بن معمر العذري. قال عند قوله تعالى: (بنين وحفدة) : أعواناً وخداما، قال جميل: "حفد الولائد ... الخ" واحدهم حافد مخرج كامل. والجميع: كملة وقال في (اللسان: حفد) يحفد بالكسر حفدا، وحفدانا. واحتفد: خف في العمل وأسرع. وحفد يحفد حفدا: خدم. الأزهري: الحفد في الخدمة والعمل: الخفة، وأنشد (حفد الولائد ... ) البيت.]] ⁕ حدثنا هناد، قال: ثنا أبو الأحوص، عن سماك، عن عكرمة، في قوله ﴿بَنِينَ وَحَفَدَةً﴾ قال: الحفدة: الخُدّام. ⁕ حدثني محمد بن خالد بن خداش، قال: ثني سَلْم بن قتيبة، عن حازم بن إبراهيم البَجَلي، عن سماك، عن عكرمة، قال: قال: الحَفَدَة: الخُدّام. ⁕ حدثنا ابن وكيع، قال: ثنا عمران بن عيينة، عن حصين، عن عكرمة، قال: هم الذين يعينون الرجل من ولده وخدمه. ⁕ حدثنا ابن عبد الأعلى، قال: ثنا محمد بن ثور، عن معمر، عن الحكم بن أبان، عن عكرمة ﴿وَحَفَدَةً﴾ قال: الحَفَدَة: من خدمك مِنْ ولدك. ⁕ حدثنا ابن وكيع، قال: ثنا يحيى بن آدم، عن سلام بن سليم، وقيس عن سِماك، عن عكرمة، قال: هم الخدم. ⁕ حدثنا أحمد، قال: ثنا أبو أحمد، قال: ثنا سلام أبو الأحوص، عن سِماك، عن عكرمة، مثله. ⁕ حدثني محمد بن خالد، قال: ثني سلمة، عن أبي هلال، عن الحسن، في قوله ﴿بَنِينَ وَحَفَدَةً﴾ قال: البنين وبني البنين، مَنْ أعانك من أهل وخادم فقد حفدك. ⁕ حدثني المثنى، قال: ثنا عمرو بن عون، قال: أخبرنا هشيم، عن منصور، عن الحسن، قال: هم الخَدَم. ⁕ حدثني محمد بن خالد وابن وكيع، ويعقوب بن إبراهيم، قالوا: ثنا إسماعيل بن علية، عن ابن أبي نجيح، عن مجاهد، قال: الحَفَدة: الخَدَم. ⁕ حدثنا أحمد بن إسحاق، قال: ثنا أبو أحمد وحدثنا ابن وكيع، قال: ثنا أبي وحدثنا ابن بشار، قال: ثنا عبد الرحمن، جميعا عن سفيان، عن ابن أبي نجيح، عن مجاهد ﴿بَنِينَ وَحَفَدَةً﴾ قال: ابنه وخادمه. ⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء وحدثني المثنى، قال: ثنا أبو حُذيفة، قال: ثنا شبل جميعا، عن ابن أبي نجيح، عن مجاهد، في قول الله تعالى ﴿بَنِينَ وَحَفَدَةً﴾ قال: أنصارًا وأعوانًا وخدامًا. ⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا زمعة، عن ابن طاوس، عن أبيه، قال: الحفدة: الخدم. ⁕ حدثنا ابن بشار مرّة أخرى، قال: ابنه وخادمه. ⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة قال ﴿وَجَعَلَ لَكُمْ مِنْ أَزْوَاجِكُمْ بَنِينَ وَحَفَدَةً﴾ مهنة يمهنونك ويخدمونك من ولدك، كرامة أكرمكم الله بها. ⁕ حدثنا ابن وكيع، قال: ثنا عبد الله، عن إسرائيل، عن السُّديّ، عن أبي مالك: الحَفَدَة، قال: الأعوان. ⁕ حدثنا ابن وكيع، قال: ثنا أبي، عن سفيان، عن حصين، عن عكرمة، قال: الذين يعينونه. ⁕ حدثنا الحسن بن يحيى، قال: أخبرنا عبد الرزاق، قال: أخبرنا مَعْمر، عن الحكَم بن أبان، عن عكرمة، في قوله ﴿بَنِينَ وَحَفَدَةً﴾ قال: الحفدة: من خدمك من ولدك وولد ولدك. ⁕ حدثنا الحسن، قال: أخبرنا عبد الرزاق، قال: أخبرنا ابن التيميّ، عن أبيه، عن الحسن، قال: الحَفَدَة: الخَدَم. ⁕ حدثني المثنى، قال: ثنا أبو نعيم، قال: ثنا سفيان، عن حصين، عن عكرمة ﴿بَنِينَ وَحَفَدَةً﴾ قال: ولده الذين يعينونه. وقال آخرون: هم ولد الرجل وولد ولده. ذكر من قال ذلك: ⁕ حدثنا محمد بن المثنى، قال: ثنا عبد الصمد، قال: ثنا شعبة، عن أبي بشر، عن سعيد بن جبير، عن ابن عباس ﴿وَحَفَدَةً﴾ قال: هم الولد وولد الولد. ⁕ حدثنا ابن بشار، قال: ثنا محمد بن جعفر، قال: ثنا شعبة، عن أبي بشر، عن مجاهد وسعيد بن جبير، عن ابن عباس في هذه الآية ﴿بَنِينَ وَحَفَدَةً﴾ قال: الحَفَدَة: البنون. ⁕ حدثنا ابن وكيع، قال: ثنا غُنْدَر، عن شعبة، عن أبي بشر، عن مجاهد، عن ابن عباس، مثله. ⁕ حدثنا القاسم، قال: ثنا الحسين، قال: ثني حجاج، عن أبي بكر، عن عكرمة، عن ابن عباس، قال: بنوك حين يحفدونك ويرفدونك ويعينونك ويخدمونك، قال حميد: حَفَدَ الوَلائِدُ حَوْلَهُنَّ وأُسْلِمَتْ ... بأكُفِّهِنَّ أزِمَّةُ الأجْمال [[سبق الاستشهاد بالبيت قريبا في فراجعه ثمة.]] ⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله ﴿وَجَعَلَ لَكُمْ مِنْ أَزْوَاجِكُمْ بَنِينَ وَحَفَدَةً﴾ قال: الحَفَدَة: الخدم من ولد الرجل هم ولده، وهم يخدمونه؛ قال: وليس تكون العبيد من الأزواج، كيف يكون من زوجي عبد، إنما الحَفَدَة: ولد الرجل وخدمه. ⁕ حُدثت عن الحسين بن الفَرَج، قال: سمعت أبا معاذ يقول: ثنا عبيد بن سليمان، قال: سمعت الضحاك يقول، في قوله ﴿بَنِينَ وَحَفَدَةً﴾ يعني: ولد الرجل يحفِدونه ويخدُمونه، وكانت العرب إنما تخدمهم أوّلادهم الذكور. وقال آخرون: هم بنو امرأة الرجل من غيره. ذكر من قال ذلك: ⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، قوله ﴿وَجَعَلَ لَكُمْ مِنْ أَزْوَاجِكُمْ بَنِينَ وَحَفَدَةً﴾ يقول: بنو امرأة الرجل ليسوا منه، ويقال: الحَفَدَة: الرجل يعمل بين يدي الرجل، يقول: فلان يحفد لنا، ويزعم رجال أن الحَفَدَة أخْتان [[الأختان: جمع ختن، بسكون التاء، وهو زوج بنت الرجل.]] الرجل. والصواب من القول في ذلك عندي أن يقال: إن الله تعالى أخبر عباده معرفهم نعمه عليهم، فيما جعل لهم من الأزواج والبنين، فقال تعالى ﴿وَاللَّهُ جَعَلَ لَكُمْ مِنْ أَنْفُسِكُمْ أَزْوَاجًا وَجَعَلَ لَكُمْ مِنْ أَزْوَاجِكُمْ بَنِينَ وَحَفَدَةً﴾ فأعلمهم أنه جعل لهم من أزواجهم بنين وحفَدة، والحفَدة في كلام العرب: جمع حافد، كما الكذبة: جمع كاذب، والفسَقة: جمع فاسق. والحافد في كلامهم؛ هو المتخفِّف في الخدمة والعمل. والحَفْد: خفة العمل يقال: مرّ البعير يَحفِد حفَدَانا: إذا مرّ يُسرع في سيره. ومنه قولهم: "إليك نسعى ونحفِد": أي نسرع إلى العمل بطاعتك. يقال منه: حَفد له يحفد حفدا وحفودا وحفدانا ومنه قول الراعي: كَلَّفْتُ مَجْهُولَهَا نُوقا يَمَانيَّةً ... إذا الحُدَاةُ على أكْسائها حَفَدُوا [[الأكساء: واحدها كسى، بوزن قفل، وهو مؤخر العجز، أو مؤخر كل شيء، والجمع أكساء (اللسان: كسا) . وقال في (كسأ) : كسء كل شيء وكسوءه: مؤخره. وكسء الشهر وكسوءه: آخره، قدر عشر بقين منه ... وأنشد أبو عبيدة: كلفت مجهولها................ ... إذا الحداد.......... حفدوا ولعل الحداد في رواية الأزهري محرفة عن الحداة.]] وإذ كان معنى الحفدة ما ذكرنا من أنهم المسرعون في خدمة الرجل، المتخففون فيها، وكان الله تعالى ذكره أخبرنا أن مما أنعم به علينا أن جعل لنا حفدة تحفد لنا، وكان أولادنا وأزواجنا الذين يصلحون للخدمة منا ومن غيرنا وأختاننا الذين هم أزواج بناتنا من أزواجنا وخدمنا من مماليكنا إذا كانوا يحفدوننا، فيستحقون اسم حفدة، ولم يكن الله تعالى دلّ بظاهر تنزيله، ولا على لسان رسوله ﷺ؛ ولا بحجة عقل، على أنه عنى بذلك نوعا من الحفدة، دون نوع منهم، وكان قد أنعم بكلّ ذلك علينا، لم يكن لنا أن نوجه ذلك إلى خاص من الحفدة دون عام، إلا ما اجتمعت الأمة عليه أنه غير داخل فيهم. وإذا كان ذلك كذلك فلكلّ الأقوال التي ذكرنا عمن ذكرنا وجه في الصحة، ومَخْرج في التأويل. وإن كان أولى بالصواب من القول ما اخترنا، لما بيَّنا من الدليل. * * وقوله ﴿وَرَزَقَكُمْ مِنَ الطَّيِّبَاتِ﴾ يقول: ورزقكم من حلال المعاش والأرزاق والأقوات، ﴿أَفَبِالْبَاطِلِ يُؤْمِنُونَ﴾ يقول تعالى ذكره: يحرّم عليهم أولياء الشيطان من البحائر والسوائب والوصائل، فيصدّق هؤلاء المشركون بالله ﴿وَبِنِعْمَةِ اللَّهِ هُمْ يَكْفُرُونَ﴾ يقول: وبما أحلّ الله لهم من ذلك، وأنعم عليهم بإحلاله، يكفرون، يقول: ينكرون تحليله، ويجحدون أن يكون الله أحله.',     source_page = '144',     updated_at  = datetime('now') WHERE id = 'QR:TE:a1ca171d956ca9dad672fba5';
UPDATE qr_tafsir_entries SET content_ar = 'القول في تأويل قوله جل ثناؤه وتقدست أسماؤه: ﴿طسم (١) تِلْكَ آيَاتُ الْكِتَابِ الْمُبِينِ (٢) نَتْلُوا عَلَيْكَ مِنْ نَبَإِ مُوسَى وَفِرْعَوْنَ بِالْحَقِّ لِقَوْمٍ يُؤْمِنُونَ (٣) ﴾ قال أبو جعفر: وقد بيَّنا قبل فيما مضى تأويل قول الله عزَّ وجلَّ: ﴿طسم﴾ ، وذكرنا اختلاف أهل التأويل في تأويله. وأما قوله: ﴿تِلْكَ آيَاتُ الْكِتَابِ الْمُبِينِ﴾ فإنه يعني: هذه آيات الكتاب الذي أنزلته إليك يا محمد، المبين أنه من عند الله، وأنك لم تتقوله: ولم تتخرّصه.. وكان قَتادة فيما ذكر عنه يقول في ذلك ما:- ⁕ حدثني بشر بن معاذ، قال: ثنا يزيد، قال: ثنا سعيد، عن قَتادة، قوله: ﴿طسم تِلْكَ آيَاتُ الْكِتَابِ الْمُبِينِ﴾ يعني مبين والله بركته ورشده وهداه. * * وقوله: ﴿نَتْلُوا عَلَيْك﴾ يقول: نقرأ عليك، ونقصّ في هذا القرآن من خبر ﴿مُوسَى وَفِرْعَوْنَ بِالْحَقِّ﴾ . كما:- ⁕ حدثنا بشر، قال: حدثنا يزيد، قال: ثنا سعيد، عن قَتادة قوله: ﴿نَتْلُوا عَلَيْكَ مِنْ نَبَإِ مُوسَى وفرعون بالحق لقوم يؤمنون﴾ يقول: في هذا القرآن نبؤهم. * * وقوله: ﴿لِقَوْمٍ يُؤْمِنُونَ﴾ يقول: لقوم يصدّقون بهذا الكتاب، ليعلموا أن ما نتلو عليك من نبئهم فيه نبؤهم، وتطمئنّ نفوسهم، بأن سنتنا فيمن خالفك وعاداك من المشركين سنتنا فيمن عادى موسى، ومن آمن به من بني إسرائيل من فرعون وقومه، أن نهلكهم كما أهلكناهم، وننجيهم منهم كما أنجيناهم. * * القول في تأويل قوله تعالى: ﴿إِنَّ فِرْعَوْنَ عَلا فِي الأرْضِ وَجَعَلَ أَهْلَهَا شِيَعًا يَسْتَضْعِفُ طَائِفَةً مِنْهُمْ يُذَبِّحُ أَبْنَاءَهُمْ وَيَسْتَحْيِي نِسَاءَهُمْ إِنَّهُ كَانَ مِنَ الْمُفْسِدِينَ (٤) ﴾ يقول تعالى ذكره: إن فرعون تجبر في أرض مصر وتكبر، وعلا أهلها وقهرهم، حتى أقرّوا له بالعُبُودَةِ. كما:- ⁕ حدثنا محمد بن هارون، قال: ثنا عمرو بن حماد، قال: ثنا أسباط، عن السدي ﴿إنَّ فِرْعَوْنَ عَلا فِي الأرْضِ﴾ يقول: تجبر في الأرض. ⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قَتادة ﴿إنَّ فِرْعَوْنَ عَلا فِي الأرْضِ﴾ أي: بغى في الأرض. * * وقوله: ﴿وَجَعَلَ أَهْلَهَا شِيَعًا﴾ يعني بالشيع: الفِرَق، يقول: وجعل أهلَها فرقًا متفرّقين. كماحدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قَتادة ﴿وَجَعَل أَهْلَهَا شِيَعًا﴾ : أي فرقًا يذبح طائفة منهم، ويستحيي طائفة، ويعذب طائفة، ويستعبد طائفة، قال الله عز وجل: ﴿يُذَبِّحُ أَبْنَاءَهُمْ وَيَسْتَحْيِي نِسَاءَهُمْ إِنَّهُ كَانَ مِنَ الْمُفْسِدِينَ﴾ . ⁕ حدثني موسى بن هارون، قال: ثنا عمرو، قال: ثنا أسباط، عن السدي، قال: كان من شأن فرعون أنه رأى رؤيا في منامه، أن نارا أقبلت من بيت المقدس حتى اشتملت على بيوت مصر، فأحرقت القبط، وتركت بني إسرائيل، وأحرقت بيوت مصر، فدعا السحرة والكهنة والقافة والحازة [[لعله: الحزاة، بضم الحاء، جمع الحازي، وهو المتكهن. قال في (اللسان: حزا) التحزي: التكهن، حزى حزيًا، وتحزى: تكهن. ولم نجده في مادة (حوز) معنى التكهن. فلعل ما في الأصل خطأ الناسخ. ويؤيد ما قلناه أنه سيجيء في سطر ٢٣ صحيحًا كما قلناه.]] فسألهم عن رؤياه، فقالوا له: يخرج من هذا البلد الذي جاء بنو إسرائيل منه، يعنون بيت المقدس، رجل يكون على وجهه هلاك مصر، فأمر ببني إسرائيل أن لا يولد لهم غلام إلا ذبحوه، ولا تولد لهم جارية إلا تركت، وقال للقبط: انظروا مملوكيكم الذين يعملون خارجا، فأدخلوهم، واجعلوا بني إسرائيل يلون تلك الأعمال القذرة، فجعل بني إسرائيل في أعمال غلمانهم، وأدخلوا غلمانهم، فذلك حين يقول: ﴿إِنَّ فِرْعَوْنَ عَلا فِي الأرْضِ وَجَعَلَ أَهْلَهَا شِيَعًا﴾ يعني بني إسرائيل، حين جعلهم في الأعمال القذرة. ⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء جميعا، عن ابن أبي نجيح، عن مجاهد ﴿وَجَعَلَ أَهْلَهَا شِيَعًا﴾ قال: فرّق بينهم. ⁕ حدثنا القاسم، قال: ثنا الحسين، قال: ثني حجاج، عن ابن جُرَيج، عن مجاهد: ﴿وَجَعَلَ أَهْلَهَا شِيَعًا﴾ قال: فِرَقا. ⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿وَجَعَلَ أَهْلَهَا شِيَعًا﴾ قال: الشيع: الفِرَق. * * وقوله: ﴿يَسْتَضْعِفُ طَائِفَةً مِنْهُمْ﴾ ذكر أن استضعافه إياها كان استعباده. ذكر من قال ذلك: ⁕ حدثنا القاسم، قال: ثنا الحسين، قال: ثني أبو سفيان، عن معمر، عن قَتادة: يستعبد طائفة منهم، ويذبح طائفة، ويقتل طائفة، ويستحي طائفة. * * وقوله: ﴿إِنَّهُ كَانَ مِنَ الْمُفْسِدِينَ﴾ يقول: إنه كان ممن يفسد في الأرض بقتله من لا يستحقّ منه القتل، واستعباده من ليس له استعباده، وتجبره في الأرض على أهلها، وتكبره على عبادة ربه.',     source_page = '8',     updated_at  = datetime('now') WHERE id = 'QR:TE:36a931eb90d0105cb49b564a';
UPDATE qr_tafsir_entries SET content_ar = 'القول في تأويل قوله تعالى: ﴿إِنَّ قَارُونَ كَانَ مِنْ قَوْمِ مُوسَى فَبَغَى عَلَيْهِمْ وَآتَيْنَاهُ مِنَ الْكُنُوزِ مَا إِنَّ مَفَاتِحَهُ لَتَنُوءُ بِالْعُصْبَةِ أُولِي الْقُوَّةِ إِذْ قَالَ لَهُ قَوْمُهُ لا تَفْرَحْ إِنَّ اللَّهَ لا يُحِبُّ الْفَرِحِينَ (٧٦) ﴾ يقول تعالى ذكره: ﴿إِنَّ قَارُونَ﴾ وهو قارون بن يصهر بن قاهث بن لاوى بن يعقوب ﴿كَانَ مِنْ قَوْمِ مُوسَى﴾ يقول: كان من عشيرة موسى بن عمران النبيّ ﷺ، وهو ابن عمه لأبيه وأمه، وذلك أن قارون هو قارون بن يصهر بن قاهث، وموسى: هو موسى بن عمران بن قاهث، كذا نسبه ابن جُرَيج. ⁕ حدثنا القاسم، قال: ثنا الحسين، قال: ثني حجاج، عن ابن جُرَيج، قوله: ﴿إِنَّ قَارُونَ كَانَ مِنْ قَوْمِ مُوسَى﴾ قال: ابن عمه ابن أخي أبيه، فإن قارون بن يصفر، هكذا قال القاسم، وإنما هو يصهر بن قاهث، وموسى بن عومر بن قاهث، وعومر بالعربية: عمران. وأما ابن إسحاق فإن ابن حميد حدثنا قال: ثنا سلمة عنه، أن يصهر بن قاهث تزوّج سميت [[في كتاب العرائس (قصص الأنبياء للثعلبي المفسر) سميت بنت يتادم بن بركيا بن يشعان بن إبراهيم. وفي طبعة الحلبي: عن ابن إسحاق: تزوج يصهر بن قاهث "سمين بنت ماريب بن بركيا ابن يقشان بن إبراهيم" وفي أسماء العبرانيين اختلاف كثير بين العلماء.]] بنت بتاويت بن بركنا بن بقشان بن إبراهيم، فولدت له عمران بن يصهر، وقارون بن يصهر، فنكح عمران بخنت بنت شمويل بن بركنا بن بقشان بن بركنا، فولدت له هارون بن عمران، وموسى بن عمران صفي الله ونبيه؛ فموسى على ما ذكر ابن إسحاق ابن أخي قارون، وقارون هو عمه أخو أبيه لأبيه ولأمه. وأكثر أهل العلم في ذلك على ما قاله ابن جُرَيج. ذكر من قال ذلك: ⁕ حدثنا أبو كُرَيب، قال: ثنا جابر بن نوح، قال: أخبرنا إسماعيل بن أبي خالد، عن إبراهيم، في قوله: ﴿إِنَّ قَارُونَ كَانَ مِنْ قَوْمِ مُوسَى﴾ قال: كان ابن عمّ موسى. ⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا سفيان، عن سماك بن حرب، قال: ثنا سعيد عن قَتادة ﴿إِنَّ قَارُونَ كَانَ مِنْ قَوْمِ مُوسَى﴾ : كنا نحدّث أنه كان ابن عمه أخي أبيه، وكان يسمى المنوّر من حُسن صوته بالتوراة، ولكن عدوّ الله نافق، كما نافق السامري، فأهلكه البغي. ⁕ حدثنا ابن وكيع، قال: ثنا أبي، عن سفيان، عن سماك، عن إبراهيم ﴿إِنَّ قَارُونَ كَانَ مِنْ قَوْمِ مُوسَى﴾ قال: كان ابن عمه فبغى عليه. ⁕ قال: ثنا يحيى القطان، عن سفيان، عن سماك، عن إبراهيم، قال: كان قارون ابن عمّ موسى. ⁕ قال: ثنا أبو معاوية، عن ابن أبي خالد، عن إبراهيم ﴿إِنَّ قَارُونَ كَانَ مِنْ قَوْمِ مُوسَى﴾ قال: كان ابن عمه. ⁕ حدثني بشر بن هلال الصواف، قال: ثنا جعفر بن سليمان الضُّبَعِيُّ، عن مالك بن دينار، قال: بلغني أن موسى بن عمران كان ابن عمّ قارون. * * وقوله: ﴿فَبَغَى عَلَيْهِمْ﴾ يقول: فتجاوز حده في الكبر والتجبر عليهم. وكان بعضهم يقول: كان بغيه عليهم زيادة شبر أخذها في طول ثيابه. ذكر من قال ذلك: ⁕ حدثني علي بن سعيد الكندي وأبو السائب وابن وكيع قالوا: ثنا حفص بن غياث، عن ليث، عن شَهر بن حَوْشب: ﴿إِنَّ قَارُونَ كَانَ مِنْ قَوْمِ مُوسَى فَبَغَى عَلَيْهِمْ﴾ قال: زاد عليهم في الثياب شبرا. وقال آخرون: كان بغيه عليهم بكثرة ماله. ذكر من قال ذلك: ⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قَتادة، قال: إنما بغى عليهم بكثرة ماله. * * وقوله: ﴿وَآتَيْنَاهُ مِنَ الْكُنُوزِ مَا إِنَّ مَفَاتِحَهُ لَتَنُوءُ بِالْعُصْبَةِ أُولِي الْقُوَّةِ﴾ يقول تعالى ذكره: وآتينا قارون من كنوز الأموال ما إن مفاتحه، وهي جمع مفتح، وهو الذي يفتح به الأبواب. وقال بعضهم: عنى بالمفاتح في هذا الموضع: الخزائن لِتُثْقِل العصبة. وبنحو الذي قلنا في ذلك قال أهل التأويل. ذكر من قال ما قلنا في معنى مفاتح: ⁕ حدثنا أبو كُرَيب، قال: ثنا جابر بن نوح، قال: أخبرنا الأعمش، عن خيثمة، قال: كانت مفاتح قارون تحمل على ستين بغلا كلّ مفتاح منها باب كنز معلوم مثل الأصبع من جلود. ⁕ حدثنا ابن وكيع، قال: ثنا أبي، عن الأعمش، عن خيثمة، قال: كانت مفاتح كنوز قارون من جلود كل مفتاح مثل الأصبع، كل مفتاح على خزانة على حدة، فإذا ركب حملت المفاتيح على ستين بغلا أغرّ محجَّل. ⁕ حدثنا ابن حميد، قال: ثنا جرير، عن منصور، عن خيثمة، في قوله: ﴿مَا إِنَّ مَفَاتِحَهُ لَتَنُوءُ بِالْعُصْبَةِ أُولِي الْقُوَّةِ﴾ قال: نجد مكتوبا في الإنجيل مفاتح قارون وقر ستين بغلا غرّا محجلة، ما يزيد كل مفتاح منها على أصبع، لكل مفتاح منها كنز. ⁕ حدثنا ابن وكيع، قال: ثنا ابن عيينة، عن حميد، عن مجاهد، قال: كانت المفاتح من جلود الإبل. ⁕ حدثنا القاسم، قال: ثنا الحسين، قال: ثني حجاج، عن ابن جُرَيج، عن مجاهد ﴿وَآتَيْنَاهُ مِنَ الْكُنُوزِ مَا إِنَّ مَفَاتِحَهُ لَتَنُوءُ بِالْعُصْبَةِ﴾ قال: مفاتح من جلود كمفاتح العيدان. وقال قوم: عني المفاتح في هذا الموضع: خزائنه. ذكر من قال ذلك: ⁕ حدثنا أبو كُرَيب، قال: ثنا هشيم، قال: أخبرنا إسماعيل بن سالم، عن أبي صالح، في قوله: ﴿مَا إِنَّ مَفَاتِحَهُ لَتَنُوءُ بِالْعُصْبَةِ﴾ قال: كانت خزائنه تحمل على أربعين بغلا. ⁕ حدثنا ابن وكيع، قال: ثنا أبي، عن أبي حجير، عن الضحاك ﴿مَا إِنَّ مَفَاتِحَهُ﴾ قال: أوعيته. وبنحو الذي قلنا في معنى قوله: ﴿لَتَنُوءُ بِالْعُصْبَةِ﴾ قال أهل التأويل. ذكر من قال ذلك: ⁕ حدثنا أبو كُرَيب، قال: ثنا جابر بن نوح، قال: ثنا أبو روق، عن الضحاك عن ابن عباس، في قوله: ﴿لَتَنُوءُ بِالْعُصْبَةِ﴾ قال: لتثقل بالعصبة. ⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، قوله: ﴿لَتَنُوءُ بِالْعُصْبَةِ﴾ يقول: تثقل. وأما العصبة فإنها الجماعة. واختلف أهل التأويل في مبلغ عددها الذي أريد في هذا الموضع؛ فأما مبلغ عدد العصبة في كلام العرب فقد ذكرناه فيما مضى باختلاف المختلفين فيه، والرواية في ذلك، والشواهد على الصحيح من قولهم في ذلك بما أغنى عن إعادته في هذا الموضع، فقال بعضهم: كانت مفاتحه تنوء بعصبة؛ مبلغ عددها أربعون رجلا. ذكر من قال ذلك: ⁕ حدثنا القاسم، قال: ثنا الحسين، قال: ثنا هشيم، عن إسماعيل بن سالم، عن أبي صالح، قوله: ﴿لَتَنُوءُ بِالْعُصْبَةِ﴾ قال: أربعون رجلا. ⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد عن قَتادة ﴿لَتَنُوءُ بِالْعُصْبَةِ﴾ قال: ذكر لنا أن العصبة ما بين العشرة إلى الأربعين. ⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: أخبرنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿لَتَنُوءُ بِالْعُصْبَةِ أُولِي الْقُوَّةِ﴾ يزعمون أن العصبة أربعون رجلا ينقلون مفاتحه من كثرة عددها. ⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثنى أبي، عن أبيه، عن ابن عباس، قوله: ﴿وَآتَيْنَاهُ مِنَ الْكُنُوزِ مَا إِنَّ مَفَاتِحَهُ لَتَنُوءُ بِالْعُصْبَةِ أُولِي الْقُوَّةِ﴾ قال: أربعون رجلا. وقال آخرون: ستون، وقال: كانت مفاتحه تحمل على ستين بغلا. ⁕ حدثنا كذلك ابن وكيع، قال: ثنا أبي، عن الأعمش، عن خيثمة. وقال آخرون: كات تحمل على ما بين ثلاثة إلى عشرة. ذكر من قال ذلك: ⁕ حدثنا ابن وكيع، قال: ثنا جابر بن نوح، عن أبي روق، عن الضحاك، عن ابن عباس ﴿لَتَنُوءُ بِالْعُصْبَةِ﴾ قال: العصبة: ثلاثة. ⁕ حدثنا أبو كُرَيب، قال: ثنا جابر بن نوح، قال: ثنا أبو روق، عن الضحاك، عن ابن عباس ﴿لَتَنُوءُ بِالْعُصْبَةِ﴾ قال: العصبة: ما بين الثلاثة إلى العشرة. وقال آخرون: كانت تحمل ما بين عشرة إلى خمسة عشر. ذكر من قال ذلك: ⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء جميعا، عن ابن أبي نجيح، عن مجاهد، في قول الله: ﴿مَا إِنَّ مَفَاتِحَهُ لَتَنُوءُ بِالْعُصْبَةِ﴾ قال: العُصْبة: ما بين العشرة إلى الخمسة عشر. ⁕ حدثنا القاسم قال: ثنا الحسين، قال: ثني حجاج، عن ابن جُرَيج، عن مجاهد ﴿لَتَنُوءُ بِالْعُصْبَةِ﴾ قال: العصبة: خمسة عشر رجلا. * * وقوله: ﴿أُولِي الْقُوَّةِ﴾ يعني: أولي الشدة. وقال مجاهد في ذلك ما:- ⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال ثنا عيسى، عن ابن أبي نجيح، عن مجاهد ﴿أُولِي الْقُوَّةِ﴾ قال: خمسَة عَشَر. فإن قال قائل: وكيف قيل: ﴿وَآتَيْنَاهُ مِنَ الْكُنُوزِ مَا إِنَّ مَفَاتِحَهُ لَتَنُوءُ بِالْعُصْبَةِ﴾ وكيف تنوء المفاتح بالعصبة، وإنما العصبة هي التي تنوء بها؟ قيل: اختلف في ذلك أهل العلم بكلام العرب، فقال بعض أهل البصرة: مجاز ذلك: ما إن العصبة ذوي القوّة لتنوء بمفاتح نعمه. قال: ويقال في الكلام: إنها لتنوء بها عجيزتها، وإنما هو: تنوء بعجيزتها كما ينوء البعير بحمله، قال: والعرب قد تفعل مثل هذا، قال الشاعر: فَدَيْتُ بِنَفْسِهِ نَفْسِي وَمالي ... وَما آلُوكَ إلا ما أُطِيقُ [[البيت: من شواهد أبي عبيدة في مجاز القرآن، (الورقة ١٨٢ ب) عن تفسير قوله تعالى: (ما إن مفاتحه لتنوء) قال: أي مفاتح خزائنه. ومجازه: ما إن العصبة ذوي القوة لتنوء بها عجيزتها، وإنما هي تنوء بعجيزتها، كما ينوء البعير بحمله. والعرب قد تفعل مثل هذا قال: "فديت بنفسه نفسي.. " البيت، والمعنى: فديت بنفسي ومال نفسه. وقوله: "وما آلوك ... " إلخ هذا التفات من الغيبة إلى الخطب. ومعناه: ما أستطيع. والعرب تقول: أتاني فلان في حاجة فما استطعت رده. وأتاني في حاجة فألوت فيها: أي اجتهدت. (اللسان: أَلا يألو) . قلت: وجعل المؤلف البيت في القلب نظير الآية (ما إن مفاتحه لتنوء بالعصبة) أي ما إن العصبة أولي القوة تنوء وتعجز عن حمله، كما قال أبو عبيدة.]] والمعنى: فديت بنفسي وبمالي نفسه. وقال آخر: وَتَرْكَبُ خَيْلا لا هَوَادَةَ بَيْنَها ... وَتَشْقَى الرِّمَاحُ بالضَّياطِرَةِ الحُمْرِ [[البيت لخداش بن زهير (اللسان: ضطر) والضياطرة: جمع ضيطر، كالضيطري والجمع: ضياطر وضياطرة. وهم العظماء من الرجال؛ وفي كلام علي عليه السلام: من يعذرني مع هؤلاء الضياطرة، وهم الضخام الذين لا غناء عندهم. قال في اللسان: وقول خداش بن زهير: "ونركب خيلا ... البيت": قال ابن سيده: يجوز أن يكون عنى أن الرماح تشقى بهم، أي لأنهم لا يحسنون حملها، ولا الطعن بها. (قلت: وعلى هذا التوجيه، لا شاهد في البيت) . ويجوز أن يكون على القلب، أي: تشقى الضياطرة الحمر بالرماح، يعني أنهم يقتلون بها. والهوادة: المصالحة والموادعة. قلت: وعلى التوجيه الثاني من كلام ابن سيده، يصح الاستشهاد بالبيت، لما فيه من القلب. قال أبو عبيدة: وإنما يشقى الضياطرة بالرماح. اه. قلت: وهو شاذ كالذي قبله]] وإنما تشقى الضياطرة بالرماح. قال: والخيل ههنا: الرجال. وقال آخر منهم: ﴿مَا إِنَّ مَفَاتِحَهُ﴾ قال: وهذا موضع لا يكاد يبتدأ فيه "إن"، وقد قال: ﴿إِنَّ الْمَوْتَ الَّذِي تَفِرُّونَ مِنْهُ فَإِنَّهُ مُلاقِيكُمْ﴾ وقوله: ﴿لَتَنُوءُ بِالْعُصْبَةِ﴾ إنما العصبة تنوء بها؛ وفي الشعر: تَنُوءُ بِها فَتُثْقِلُها عَجِيزَتُها [[لم أقف على هذا الشعر.]] وليست العجيزة تنوء بها، ولكنها هي تنوء بالعجيزة؛ وقال الأعشى: ما كُنْتَ في الحَرْبِ العَوَانِ مُغَمَّرًا ... إذْ شَبَّ حَرُّ وَقُودِها أجْذَالَها [[البيت لأعشى بني قيس بن ثعلبة (ديوانه طبع القاهرة بشرح الدكتور محمد حسين ص٣١) وهو من قصيدة يمدح بها قيس بن معد يكرب. والحرب العوان: التي قوتل فيها مرة ثانية بعد الأولى، كأنهم جعلوا الأولى بكرًا. والمغمر: الذي لم يجرب الأمور. وشب النار: أوقدها. والأجذال: جمع جذلى (بكسر الجيم وسكون الذال) وهو ما عظم من أصول الشجر المقطع، يجعل حطبًا ووقودًا للنار. والبيت خطاب للممدوح يقول له الشاعر: أقسم بمن جعل الشهور علامة ومواقيت للناس (في البيت الذي قبل البيت) أنك لم تكن في الحرب الشديدة جاهلا بإرادتها على الأعداء حين أوقد حرها الأجذال والحطب. وقد جعل الشاعر الحر هو الذي أوقد الأجذال. وفي هذا قلب للمعنى، والأصل: إذا شبت الأجذال حر الحرب. وعلى هذا القلب استشهد به المؤلف، وهو كالشاهدين قبله.]] وكان بعض أهل العربية من الكوفيين يُنكر هذا الذي قاله هذا القائل، وابتداء إن بعد ما، ويقول: ذلك جائز مع ما ومن، وهو مع ما ومَنْ أجود منه مع الذي، لأن الذي لا يعمل في صلته، ولا تعمل صلته فيه، فلذلك جاز، وصارت الجملة عائد "ما"، إذ كانت لا تعمل في "ما"، ولا تعمل "ما" فيها؛ قال: وحسن مع "ما" و "من"، لأنهما يكونان بتأويل النكرة إن شئت، والمعرفة إن شئت، فتقول: ضربت رجلا ليقومن، وضربت رجلا إنه لمحسن، فتكون "من" و"ما" تأويل هذا، ومع "الذي" أقبح، لأنه لا يكون بتأويل النكرة. وقال آخر منهم في قوله: ﴿لَتَنُوءُ بِالْعُصْبَةِ﴾ : نَوْءُها بالعصبة: أن تُثْقلهم؛ وقال: المعنى: إن مفاتحه لَتُنِيءُ العصبة: تميلهن من ثقلها، فإذا أدخلت الباء قلت: تنوء بهم، كما قال: ﴿آتُونِي أُفْرِغْ عَلَيْهِ قِطْرًا﴾ قال والمعنى: ائتوني بقطر أفرغ عليه؛ فإذا حذفت الباء، زدت على الفعل ألفا في أوله؛ ومثله: ﴿فَأَجَاءَهَا الْمَخَاضُ﴾ معناه: فجاء بها المخاض؛ وقال: قد قال رجل من أهل العربية: ما إن العصبة تنوء بمفاتحه، فحوّل الفعل إلى المفاتح، كما قال الشاعر: إنَّ سِرَاجًا لَكَرِيمٌ مَفْخَرُه ... تَحْلَى بهِ العَيْنُ إذَا مَا تَجْهَرُهْ [[البيت من شواهد الفراء في معاني القرآن (مصورة الجامعة الورقة ٢٤٢) وقد تقدم الاستشهاد به في (٣: ٣١٢) من هذا التفسير، على مثل ما استشهد به هنا، مع أبيات أخر. وقلنا في تفسيره هناك: جهرت فلانًا العين تجهره: نظرت إليه فرأته عظيمًا، فحلى هو فيها. هذا هو أصل المعنى، ولكن الشاعر قلب المعنى. فجعل العين تحلى بالمرئي إذا رأته، فهو كالشاهدين اللذين قبله. وقال الفراء في معاني القرآن (مصورة الجامعة ٢٤٠٥٩) في التعليق على قول الله تعالى: (ما إن مفاتحه لتنوء بالعصبة أولي القوة) : ونوءها بالعصبة أن تثقلهم. والعصبة هاهنا: أربعون رجلا. ومفاتحه: خزائنه. والمعنى: ما إن مفاتحه لتنيء العصبة أي تميلهم من ثقلها؛ فإذا دخلت الباء قلت: تنوء بهم كما قال: (آتوني أفرغ عليه قطرًا) والمعنى: ائتوني بقطر أفرغ عليه. فإذا حذفت الباء رددت في الفعل ألفًا في أوله. ومثله: (فأجاءها المخاض) . معناه: فجاء بها المخاض. وقد قال رجل من أهل العربية: إن المعنى: ما إن العصبة لتنوء بمفاتحه فحول الفعل إلى المفاتح، كما قال الشاعر: "إن سراجًا ... " البيت، وهو الذي يحلى بالعين. فإذا كان سمع بهذا أثرًا، فهو وجه، وإلا فإن الرجل جهل المعنى. اه.]] وهو الذي يحلى بالعين، قال: فإن كان سمع أثرًا بهذا، فهو وجه، وإلا فإن الرجل جهل المعنى، قال: وأنشدني بعض العرب: حتى إذَا ما الْتَأَمَتْ مَوَاصِلُهْ ... ونَاءَ في شقّ الشَّمالِ كَاهِلُهْ [[البيتان مما أنشده بعض العرب، الفراء (انظر معاني القرآن له ص ٢٤٢، واللسان: ناء) قال الفراء بعد الذي نقلناه من قوله في الشاهد السابق: ولقد أنشدني بعض العرب: حتى إذا ما التأمت مواصله ... وناء في شق الشمال كاهله يعني: الرامي لما أخذ القوس ونزع، مال على شقه، فذلك نوءه عليها. ونرى أن قول العرب: "ما ساءك وناءك" من ذلك، ومعناه: ساءك وأناءك، إلا أنه ألقى الألف، لأنه متبع لساءك، كما قالت العرب: أكلت طعامًا، فهنأني ومرأني. ومعناه إذا أفردت: وأمرأني فحذفت منه الألف، لما أن أتبع ما لا ألف فيه.]] يعني: الرامي لما أخذ القوس، ونزع مال عليها. قال: ونرى أن قول العرب: ما ساءك، وناءك من ذلك، ومعناه: ما ساءك وأناءك من ذلك، إلا أنه ألقى الألف لأنه متبع لساءك، كما قالت العرب: أكلت طعاما فهنأني ومرأني، ومعناه: إذا أفردت وأمرأني؛ فحذفت منه الألف لما أتبع ما ليس فيه ألف. وهذا القول الآخر في تأويل قوله: ﴿لَتَنُوءُ بِالْعُصْبَةِ﴾ أولى بالصواب من الأقوال الأخر، لمعنيين: أحدهما: أنه تأويل موافق لظاهر التنزيل. والثاني: أن الآثار التي ذكرنا عن أهل التأويل بنحو هذا المعنى جاءت، وإن قول من قال: معنى ذلك: ما إن العصبة لتنوء بمفاتحه، إنما هو توجيه منهم إلى أن معناه: ما إن العصبة لتنهض بمفاتحه؛ وإذا وجه إلى ذلك لم يكن فيه من الدلالة على أنه أريد به الخبر عن كثرة كنوزه، على نحو ما فيه، إذا وجه إلى أن معناه: إن مفاتحه تثقل العصبة وتميلها، لأنه قد تنهض العصبة بالقليل من المفاتح وبالكثير. وإنما قصد جلّ ثناؤه الخبر عن كثرة ذلك، وإذا أريد به الخبر عن كثرته، كان لا شكّ أن الذي قاله مَن ذكرنا قوله، من أن معناه: لتنوء العصبة بمفاتحه، قول لا معنى له، هذا مع خلافه تأويل السلف في ذلك. * * وقوله: ﴿إِذْ قَالَ لَهُ قَوْمُهُ لا تَفْرَحْ إِنَّ اللَّهَ لا يُحِبُّ الْفَرِحِينَ﴾ يقول: إذ قال قومه: لا تبغ ولا تَبْطَر فرحا، إن الله لا يحبّ من خلقه الأشِرِين البَطِرين. وبنحو الذي قلنا في ذلك قال أهل التأويل. ذكر من قال ذلك: ⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، قوله: ﴿إِنَّ اللَّهَ لا يُحِبُّ الْفَرِحِينَ﴾ يقول: المرحين. ⁕ حدثنا ابن حميد، قال: ثنا حكام، عن عنبسة، عن محمد بن عبد الرحمن، عن القاسم بن أبي بزة، عن مجاهد، في قوله: ﴿لا تَفْرَحْ إِنَّ اللَّهَ لا يُحِبُّ الْفَرِحِينَ﴾ قال: المُتبذِّخين الأشِرين البَطِرين، الذين لا يشكرون الله على ما أعطاهم. ⁕ حدثنا محمد بن بشار، قال: ثنا محمد بن جعفر، قال: ثنا شعبة، عن جابر، قال: سمعت مجاهدا يقول في هذه الآية ﴿إِنَّ اللَّهَ لا يُحِبُّ الْفَرِحِينَ﴾ قال: الأشِرين البَطِرين البَذِخين. ⁕ حدثني يعقوب، قال: ثنا هشيم، قال: أخبرنا العوام، عن مجاهد، في قوله: ﴿لا تَفْرَحْ إِنَّ اللَّهَ لا يُحِبُّ الْفَرِحِينَ﴾ قال: يعني به البغي. ⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، عن ابن أبي نجيح، عن مجاهد، في قول الله: ﴿لا تَفْرَحْ إِنَّ اللَّهَ لا يُحِبُّ الْفَرِحِينَ﴾ قال: المتبذخين الأشرين، الذين لا يشكرون الله فيما أعطاهم. ⁕ حدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، عن ابن أبي نجيح، عن مجاهد، مثله؛ إلا أنه قال: المتبذخين. ⁕ حدثنا محمد بن عبد الله المخرمي، قال: ثني شبابة، قال ثني ورقاء، عن ابن أبي نجيح، عن مجاهد ﴿لا تَفْرَحْ إِنَّ اللَّهَ لا يُحِبُّ الْفَرِحِينَ﴾ قال: الأشرين البطرين. ⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتاده، إذ قال له قومه ﴿لا تَفْرَحْ﴾ : أي لا تمرح ﴿إِنَّ اللَّهَ لا يُحِبُّ الْفَرِحِينَ﴾ : أي إن الله لا يحب المرحين. ⁕ حدثنا القاسم، قال: ثنا الحسين، قال: ثني حجاج، عن ابن جريح، عن مجاهد ﴿لا تَفْرَحْ إِنَّ اللَّهَ لا يُحِبُّ الْفَرِحِينَ﴾ قال: الأشرين البطرين، الذين لا يشكرون الله فيما أعطاهم. ⁕ حدثنا القاسم، قال: ثنا الحسين، قال: ثنا هشيم، قال: أخبرنا العوام، عن مجاهد، في قوله: ﴿إِذْ قَالَ لَهُ قَوْمُهُ لا تَفْرَحْ إِنَّ اللَّهَ لا يُحِبُّ الْفَرِحِينَ﴾ قال: هو فرح البَغْي.',     source_page = '213',     updated_at  = datetime('now') WHERE id = 'QR:TE:76539b25e25181ad6054078b';
UPDATE qr_tafsir_entries SET content_ar = 'القول في تأويل قوله: ﴿وَقَالَ لَهُمْ نَبِيُّهُمْ إِنَّ آيَةَ مُلْكِهِ أَنْ يَأْتِيَكُمُ التَّابُوتُ﴾ قال أبو جعفر: وهذا الخبر من الله تعالى ذكره عن نبيه الذي أخبر عنه به، دليل على أن الملأ من بني إسرائيل الذين قيل لهم هذا القول، لم يقروا ببعثة الله طالوت عليهم ملكا إذ أخبرهم نبيهم بذلك، وعرفهم فضيلته التي فضله الله بها، ولكنهم سألوه الدلالة على صدق ما قال لهم من ذلك وأخبرهم به. فتأويل الكلام، إذ كان الأمر على ما وصفنا:"والله يؤتي ملكه من يشاء والله واسع عليم"، فقالوا له: ما آية ذلكإن كنت من الصادقين؟ [[في المطبوعة: "فقالوا له: ائت بآية على ذلك ... "، وفي المخطوطة: " مما أتى به ذلك" وقد ضرب على الباء من"أتى". واستظهرت قراءتها كما أثبتها، لقوله تعالى بعد: " إن آية ملكه".]] ="قال لهم نبيهم إن آية ملكه أن يأتيكم التابوت". وهذه القصة = [[في المطبوعة: " هذه القصة" بإسقاط الواو، وإسقاطها مخل بالكلام.]] وإن كانت خبرا من الله تعالى ذكره عن الملإ من بني إسرائيل ونبيهم، وما كان من ابتدائهم نبيهم بما ابتدءوا به من مسألته أن يسأل الله لهم أن يبعث لهم ملكا يقاتلون معه في سبيله، ونبأً عما كان منهم من تكذيبهم نبيهم بعد علمهم بنبوته، [[في المطبوعة: " بناء عما كان منهم من تكذيبهم"، وهو غث من الكلام. وفي المخطوطة: "بنا عما كان. . . " غير منقوطة، والصواب ما أثبت مع زيادة"الواو" عطفا على قوله: "وإن كانت خبرا. . . ".]] ثم إخلافهم الموعد الذي وعدوا الله ووعدوا رسوله، من الجهاد في سبيل الله، بالتخلف عنه حين استنهضوا لحرب من استنهضوا لحربه، وفتح الله على القليل من الفئة، مع تخذيل الكثير منهم عن ملكهم وقعودهم عن الجهاد معه= [[سياق الجملة: وهذه القصة، وإن كانت خبرا من الله٠٠ ٠ ونبأ عما كان منهم ... فإنه تأديب ... ".]] فإنه تأديب لمن كان بين ظهراني مهاجر رسول الله ﷺ من ذراريهم وأبنائهم يهود قريظة والنضير، وأنهم لن يعدوا في تكذيبهم محمدا ﷺ فيما أمرهم به ونهاهم عنه= مع علمهم بصدقه، ومعرفتهم بحقيقة نبوته، بعد ما كانوا يستنصرون الله به على أعدائهم قبل رسالته، وقبل بعثة الله إياه إليهم وإلى غيرهم = [[سياق هذه الجملة: "وأنهم لن يعدوا في تكذيبهم محمدا ... أن يكونوا كأسلافهم ... ".]] أن يكونوا كأسلافهم وأوائلهم الذين كذبوا نبيهم شمويل بن بالي، مع علمهم بصدقه، ومعرفتهم بحقية نبوته، وامتناعهم من الجهاد مع طالوت لما ابتعثه الله ملكا عليهم، بعد مسألتهم نبيهم ابتعاث ملك يقاتلون معه عدوهم ويجاهدون معه في سبيل ربهم، ابتداء منهم بذلك نبيهم، وبعد مراجعة نبيهم شمويل إياهم في ذلك= [[قوله: "وحض ... " معطوف على قوله آنفًا: "فإنه تأديب ... ".]] وحض لأهل الإيمان بالله وبرسوله من أصحاب محمد ﷺ على الجهاد في سبيله، وتحذير منه لهم أن يكونوا في التخلف عن نبيهم محمد ﷺ عند لقائه العدو، ومناهضته أهل الكفر بالله وبه، على مثل الذي كان عليه الملأ من بني إسرائيل في تخلفهم عن ملكهم طالوت إذ زحف لحرب عدو الله جالوت، وإيثارهم الدعة والخفض على مباشرة حر الجهاد والقتال في سبيل الله= [[قوله: "وشخذ ... " معطوف ثان على قوله آنفًا: " فإنه تأديب ... ".]] وشحذ منه لهم على الإقدام على مناجزة أهل الكفر به الحرب، وترك تهيب قتالهم أن قل عددهم وكثر عدد أعدائهم واشتدت شوكتهم بقوله: ﴿قَالَ الَّذِينَ يَظُنُّونَ أَنَّهُمْ مُلاقُو اللَّهِ كَمْ مِنْ فِئَةٍ قَلِيلَةٍ غَلَبَتْ فِئَةً كَثِيرَةً بِإِذْنِ اللَّهِ وَاللَّهُ مَعَ الصَّابِرِينَ﴾ [سورة البقرة: ٢٤٩] ،= [[قوله: " وإعلام ... " معطوف ثالث على قوله: "فإنه تأديب ... ".]] وإعلام منه تعالى ذكره عباده المؤمنين به أن بيده النصر والظفر والخير والشر. * * وأما تأويل قوله:"قال لهم نبيهم"، فإنه يعني: للملأ من بني إسرائيل الذين قالوا لنبيهم:"ابعث لنا ملكا نقاتل في سبيل الله". * * وقوله:"إن آية ملكه"،: إن علامة ملك طالوت= [[انظر تفسير"آية" فيما سلف ١: ١٠٦ / ٢: ٣٩٧، ٣٩٨، ٥٥٣ / ٣: ١٨٤ / ٤: ٢٧١.]] التي سألتمونيها دلالة على صدقي في قولي: إن الله بعثه عليكم ملكا، وإن كان من غير سبط المملكة="أن يأتيكم التابوت فيه سكينة من ربكم"، وهو التابوت الذي كانت بنو إسرائيل إذا لقوا عدوا لهم قدموه أمامهم، وزحفوا معه، فلا يقوم لهم معه عدو، ولا يظهر عليهم أحد ناوأهم، حتى ضيعوا أمر الله، [[في المطبوعة والمخطوطة: "حتى منعوا أمر الله". وهو تصحيف لا معنى له، والصواب ما أثبت.]] وكثر اختلافهم على أنبيائهم، فسلبهم الله إياه مرة بعد مرة، يرده إليهم في كل ذلك، حتى سلبهم آخرها مرة فلم يرده عليهم، [[في المطبوعة: "حتى سلبهم آخر مرة"، والذي في المخطوطة هو الصواب الجيد، وإن كانت الأخرى قريبة من الصواب على ضعف.]] ولن يرد إليهم آخر الأبد. [[في المخطوطة: "ولم يرده إليهم آخر الأبد"، وهو خطأ بين.]] * * ثم اختلف أهل التأويل في سبب مجيء التابوت الذي جعل الله مجيئه إلى بني إسرائيل آية لصدق نبيهم شمويل على قوله:"إن الله قد بعث لكم طالوت ملكا"، وهل كانت بنو إسرائيل سلبوه قبل ذلك فرده الله عليهم حين جعل مجيئه آية لملك طالوت، أو لم يكونوا سلبوه قبل ذلك، ولكن الله ابتدأهم به ابتداء؟ فقال بعضهم: بل كان ذلك عندهم من عهد موسى وهارون يتوارثونه، [[في المطبوعة: " كان ذلك عندهم"، بحذف"بل".]] حتى سلبهم إياه ملوك من أهل الكفر به، ثم رده الله عليهم آية لملك طالوت. وقال في سبب رده عليهم ما أنا ذاكره وهو ما: - ٥٦٥٨- حدثني به المثنى قال، حدثنا إسحاق قال، حدثنا إسماعيل بن عبد الكريم قال، حدثني عبد الصمد بن معقل: أنه سمع وهب بن منبه قال: كان لعيلي الذي ربى شمويل، ابنان شابان أحدثا في القربان شيئا لم يكن فيه. كان مسوط القربان الذي كانوا يسوطونه به كلابين [[في المطبوعة والمخطوطة: " كان مشرط القربان الذي يشرطونه به"، وهو خطأ لا معنى له، والصواب من تاريخ الطبري ١: ٢٤٣. والمسوط (بكسر الميم) : المسواط خشبة أو ما يشبهها، يحرك بها ما في القدر ليختلط. ساط الشيء في القدر يسوطه سوطا: إذا حركة وخاصه، ليختلط ويمتزج. وقربان اليهود هذا هو"التقدمة"، كانت من دقيق مع زيت ولبان، يؤخذ قليل من الدقيق المقدم والزيت وكل اللبان، ويوقد على المذبح، أو يعمل منه قطائف علي صاج، وأما البقية فكانت للكمهنة (قاموس الكتاب المقدس ٢: ٢٠٨) . والكلاب (يضم الكاف وتشديد اللام) : سفود من حديد أو خشب، في رأسه عقافة معطوفة كالخطاف، وجمعه: "كلاليب".]] فما أخرجا كان للكاهن الذي يسوطه، [[في المطبوعة والمخطوطة: "للكاهن الذي يستوطنه"، وهو خطأ، صوابه من التاريخ.]] فجعله ابناه كلاليب. [[في المطبوعة والمخطوطة: "فجعل ابناه ... "، والصواب من التاريخ.]] وكانا إذا جاء النساء يصلين في القدس يتشبثان بهن. فبينا شمويل نائم قبل البيت الذي كان ينام فيه عيلي، إذ سمع صوتا يقول: أشمويل!! [[في المخطوطة والتاريخ في هذا الموضع وما بعده: "أشمويل"، والذي قبله: "شمويل"، وأثبت ما فيهما، كما سلف قريبا ص: ٣٠٨، تعليق: ٥.]] فوثب إلى عيلي فقال: لبيك! ما لك! دعوتني؟ فقال: لا! ارجع فنم! فرجع فنام، ثم سمع صوتا آخر يقول: أشمويل!! فوثب إلى عيلي أيضا، فقال: لبيك! ما لك! دعوتني؟ فقال: لم أفعل، ارجع فنم، فإن سمعت شيئا فقل:"لبيك" مكانك،"مرني فأفعل"! فرجع فنام، فسمع صوتا أيضا يقول: أشمويل!! فقال: لبيك أنا هذا! مرني أفعل! قال: انطلق إلى عيلي فقل له:"منعه حب الولد أن يزجر ابنيه أن يحدثا في قدسي وقرباني، وأن يعصياني، فلأنزعن منه الكهانة ومن ولده، ولأهلكنه وإياهما"! فلما أصبح سأله عيلي فأخبره، ففزع لذلك فزعا شديدا. فسار إليهم عدو ممن حولهم، فأمر ابنيه أن يخرجا بالناس فيقاتلا ذلك العدو. فخرجا وأخرجا معهما التابوت الذي كان فيه اللوحان وعصا موسى لينصروا به. [[في التاريخ: "لينتصروا به"، أي ليجلبوا النصر لأنفسهم به.]] فلما تهيئوا للقتال هم وعدوهم، جعل عيلي يتوقع الخبر: ماذا صنعوا؟ فجاءه رجل يخبره وهو قاعد على كرسيه: إن ابنيك قد قتلا وإن الناس قد انهزموا! قال: فما فعل التابوت؟ قال: ذهب به العدو! قال: فشهق ووقع على قفاه من كرسيه فمات. وذهب الذين سبوا التابوت حتى وضعوه في بيت آلهتهم، ولهم صنم يعبدونه، فوضعوه تحت الصنم، والصنم من فوقه، فأصبح من الغد والصنم تحته وهو فوق الصنم. ثم أخذوه فوضعوه فوقه وسمروا قدميه في التابوت، فأصبح من الغد قد تقطعت يدا الصنم ورجلاه، وأصبح ملقى تحت التابوت. فقال بعضهم لبعض: قد علمتم أن إله بني إسرائيل لا يقوم له شيء، فأخرجوه من بيت آلهتكم! فأخرجوا التابوت فوضعوه في ناحية من قريتهم، فأخذ أهل تلك الناحية التي وضعوا فيها التابوت وجع في أعناقهم، فقالوا: ما هذا؟! فقالت لهم جارية كانت عندهم من سبي بني إسرائيل: لا تزالون ترون ما تكرهون ما كان هذا التابوت فيكم! فأخرجوه من قريتكم! قالوا: كذبت! قالت: إن آية ذلك أن تأتوا ببقرتين لهما أولاد لم يوضع عليهما نير قط، ثم تضعوا وراءهم العجل، [[في المطبوعة: "وراءهم" والصواب من التاريخ والمخطوطة. والنير: الخشبة التي تكون على عنق الثور بأداتها.]] ثم تضعوا التابوت على العجل وتسيروهما وتحبسوا أولادهما، فإنهما تنطلقان به مذعنتين، [[في المطبوعة: " ينطلقان مذعنين"، والصواب من المخطوطة والتاريخ.]] حتى إذا خرجتا من أرضكم ووقعتا في أرض بني إسرائيل كسرتا نيرهما، وأقبلتا إلى أولادهما. ففعلوا ذلك، فلما خرجتا من أرضهم ووقعتا في أدنى أرض بني إسرائيل كسرتا نيرهما، وأقبلتا إلى أولادهما. ووضعتاه في خربة فيها حصاد من بني إسرائيل، [[في المطبوعة: "حضار"، وفي المخطوطة: "حصار"، غير منقوطة، والصواب ما في التاريخ.]] ففزع إليه بنو إسرائيل وأقبلوا إليه، فجعل لا يدنو منه أحد إلا مات. فقال لهم نبيهم شمويل: اعترضوا، [[في التاريخ: "اعرضوا"، وهما سواء.]] فمن آنس من نفسه قوة فليدن منه. فعرضوا عليه الناس، فلم يقدر أحد يدنو منه إلا رجلان من بني إسرائيل، [[في التاريخ: "فلم يقدر أحد على أن يدنو منه"، والذي في المخطوطة والمطبوعة حسن.]] أذن لهما بأن يحملاه إلى بيت أمهما، وهي أرملة. فكان في بيت أمهما حتى ملك طالوت، فصلح أمر بني إسرائيل مع أشمويل. [[الأثر: ٥٦٥٨- في التاريخ ١: ٢٤٣- ٢٤٤، وهو صدر الأثر السالف رقم: ٥٦٣٧، وساقهما الطبري في التاريخ سياقا واحدا.]] ٥٦٥٩- حدثنا ابن حميد قال، حدثنا سلمة، عن ابن إسحاق قال، حدثني بعض أهل العلم، عن وهب بن منبه قال: قال شمويل لبني إسرائيل لما قالوا له: أنى يكون له الملك علينا ونحن أحق بالملك منه ولم يؤت سعة من المال؟ قال إن الله اصطفاه عليكم وزاده بسطة في العلم والجسم، وإن آية ملكه= وإن تمليكه من قبل الله= أن يأتيكم التابوت، فيرد عليكم الذي فيه من السكينة وبقية مما ترك آل موسى وآل هارون، وهو الذي كنتم تهزمون به من لقيكم من العدو، وتظهرون به عليه. قالوا: فإن جاءنا التابوت فقد رضينا وسلمنا! وكان العدو الذين أصابوا التابوت أسفل من الجبل جبل إيليا فيما بينهم وبين مصر، وكانوا أصحاب أوثان، وكان فيهم جالوت. وكان جالوت رجلا قد أعطي بسطة في الجسم، وقوة في البطش، وشدة في الحرب، مذكورا بذلك في الناس. وكان التابوت حين استبي قد جعل في قرية من قرى فلسطين يقال لها:"أزدود"، [[في المطبوعة: "يقال لها: أردن"، وهو خطأ لا شك فيه، وأما ما في المخطوطة فهو، "أردود" بالراء، وأنا أظنه بالزاي وأثبته كذلك. فإنه الذي في كتاب القوم في"كتاب صموئيل الأول" الإصحاح الخامس: "أشدود"، وقال صاحب قاموسهم: "أشدود" (حصن، معقل) ، إحدى مدن فلسطين الخمس المحالفة ... وموقعها على ثلاثة أميال من البحر المتوسط بين غزة ويافا. قال: وهي الآن قرية حقيرة تسمى: أسدود، وفي جوارها خرائب كثيرة". والذي يرجع ما ظننته أنها بالزاي أن ابن كثير قال في تفسيره ١: ٦٠٢ أنه يقال لها: " أزدوه"، وقال مصحح التفسير بهامشه أنها في نسخة الأزهر: "أزدرد". وفي البغوي بهامش ابن كثير ١: ٦٠١"أزدود" كما أثبتها.]] فكانوا قد جعلوا التابوت في كنيسة فيها أصنامهم. فلما كان من أمر النبي ﷺ ما كان: من وعد بني إسرائيل أن التابوت سيأتيهم- جعلت أصنامهم تصبح في الكنيسة منكسة على رؤوسها، وبعث الله على أهل تلك القرية فأرا، تبيت الفأرة الرجل فيصبح ميتا، [[في المطبوعة: "تثبت الفأرة"، وليست صوابا، والذي في المخطوطة" تبيت" غير منقوطة وصواب قراءتها ما أثبت. بيت القوم العدو: أتوهم في جوف الليل فأوقعوا بهم وهم في غفلة عنه. والاسم: "البيات"، وفي البغوي ١: ٦٠١ (بهامش ابن كثير) : "فكانت الفأرة تبيت مع الرجل".]] قد أكلت ما في جوفه من دبره. قالوا: تعلمون والله، لقد أصابكم بلاء ما أصاب أمة من الأمم مثله، [[في المطبوعة: "أمة من الأمم قبلكم"، وفي المخطوطة: "أمة من الأمم قبله"، والذي أثبت أقرب إلى رسم المخطوطة، مع التصحيف فيها.]] وما نعلمه أصابنا إلا مذ كان هذا التابوت بين أظهرنا!! مع أنكم قد رأيتم أصنامكم تصبح كل غداة منكسة، شيء لم يكن يصنع بها حتى كان هذا التابوت معها! فأخرجوه من بين أظهركم. فدعوا بعجلة فحملوا عليها التابوت، ثم علقوها بثورين، ثم ضربوا على جنوبهما، وخرجت الملائكة بالثورين تسوقهما، فلم يمر التابوت بشيء من الأرض إلا كان قدسا. فلم يرعهم إلا التابوت على عجلة يجرها الثوران، حتى وقف على بني إسرائيل، فكبروا وحمدوا الله، وجدوا في حربهم، واستوسقوا على طالوت. [[في المطبوعة: "واستوثقوا". وهو خطأ والصواب ما في المخطوطة. ومعناه: اجتمعوا على طاعته. وأصله من"الوسق"وهو ضم الشيء إلى الشيء، وفي حديث أحد: "استوسقوا كما يستوسق جرب الغم. أي: استجمعوا وانضموا. وفي حديث النجاشي: "واستوسق عليه أمر الحبشة"، أي اجتمعوا على طاعته. وهو المراد هنا. وانظر ما سيأتي في الأثر: ٥٧٠٧.]] ٥٦٦٠- حدثنا القاسم قال، حدثنا الحسين قال، حدثني حجاج، عن ابن جريج قال: قال ابن عباس: لما قال لهم نبيهم: إن الله اصطفى طالوت عليكم وزاده بسطة في العلم والجسم- أبوا أن يسلموا له الرياسة، حتى قال لهم:"إن آية ملكه أن يأتيكم التابوت فيه سكينة من ربكم". فقال لهم: أرأيتم إن جاءكم التابوت فيه سكينة من ربكم وبقية مما ترك آل موسى وآل هارون تحمله للملائكة!! = وكان موسى حين ألقى الألواح تكسرت ورفع منها. فنزل فجمع ما بقي فجعله في ذلك التابوت= قال ابن جريج، أخبرني يعلى بن مسلم، عن سعيد بن جبير، عن ابن عباس: أنه لم يبق من الألواح إلا سدسها. قال: وكانت العمالقة قد سبت ذلك التابوت- والعمالقة فرقة من عاد كانوا بأريحا- فجاءت الملائكة بالتابوت تحمله بين السماء والأرض وهم ينظرون إلى التابوت، حتى وضعته عند طالوت. فلما رأوا ذلك قالوا: نعم! فسلموا له وملكوه. قال: وكان الأنبياء إذا حضروا قتالا قدموا التابوت بين يديهم. ويقولون: إن آدم نزل بذلك التابوت وبالركن. وبلغني أن التابوت وعصا موسى في بحيرة طبرية، وأنهما يخرجان قبل يوم القيامة. ٥٦٦١- حدثنا الحسن بن يحيى قال، أخبرنا عبد الرزاق قال، أخبرنا عبد الصمد بن معقل: أنه سمع وهب بن منبه يقول: إن أرميا لما خرب بيت المقدس وحرقت الكتب، وقف في ناحية الجبل فقال:"أنى يحيى هذه الله بعد موتها، فأماته الله مئة عام". ثم رد الله من رد من بني إسرائيل على رأس سبعين سنة من حين أماته، يعمرونها ثلاثين سنة تمام المئة. فلما ذهبت المئة، رد الله إليه روحه، وقد عمرت، فهي على حالتها الأولى. [[الأثر: ٥٦٦١- سيأتي هذا الأثر نفسه برقم: ٥٩١٢ وهو أثر"مبتور" بلا شك ولم أستطع أن أتمه، وانظر التعليق على الأثر التالي المذكور آنفًا.]] [[أما موضع النقط هذا، فإنه سقط بلا شك فيه، فإن خبر أرميا السالف، لا يمكن أن يكون هذا الكلام من صلته، فإن فيه ذكر رد التابوت في عهد طالوت وداود، وهما قبل أرميا بدهر طويل. وأخشى أن يكون الناسخ قد قدم ورقة على ورقة في النسخة العتيقة، أو تخطى وجها من الكتاب الذي نسخ منه. وليس من الممكن إتمام هذا النقص، فلذلك فصلت بين الكلامين بهذه النقط، حتى يتيح الله نسخة أقدم من النسخ التي بين أيدينا تسد هذا الخرم أو تصحح مكان الكلام. وهذا الذي بعد النقط، خبر عن القرية التي وضع فيها التابوت حين سبي، كما ذكر في الأثر رقم: ٥٦٥٨، وهو أثر ضاع صدره عن وهب بن منبه، كما هو واضح في السياق الآتي. ولم أجد صدره في شيء من الكتب التي بين يدي. هذا ونسختنا في الموضع كثيرة الخطأ السهو، كما يتبين ذلك من خط كاتبها، ومن الأخطاء السالفة التي ذكرتها في التعليقات.]] ................................................................................ ................................................................................ ................................................................................ فلما أراد أن يرد عليهم التابوت، أوحى الله إلى نبي من أنبيائهم: إما دانيال وإما غيره: إن كنتم تريدون أن يرفع عنكم المرض، فأخرجوا عنكم هذا التابوت! قالوا: بآية ماذا؟ قال: بآية أنكم تأتون ببقرتين صعبتين لم تعملا عملا قط، فإذا نطرتا إليه وضعتا أعناقهم للنير حتى يشد عليهما، [[في المخطوطة: "فإذا نظرتا إليها"، والصواب ما في المطبوعة.]] ثم يشد التابوت على عجل، ثم يعلق على البقرتين، ثم يخليان فيسيران حيث يريد الله أن يبلغهما. ففعلوا ذلك، ووكل الله بهما أربعة من الملائكة يسوقونهما، فسارت البقرتان سيرا سريعا، حتى إذا بلغتا طرف القدس كسرتا نيرهما، وقطعتا حبالهما، وذهبتا. فنزل إليهما داود ومن معه، فلما رأى داود التابوت حجل إليه فرحا به = فقلنا لوهب: ما حجل إليه، قال: شبيه بالرقص= فقالت له امرأته: لقد خففت حتى كاد الناس يمقتونك لما صنعت! قال: أتبطئيني عن طاعة ربي!! لا تكونين لي زوجة بعد هذا. ففارقها. * * وقال آخرون: بل التابوت= الذي جعله الله آية لملك طالوت= كان في البرية، وكان موسى ﷺ خلفه عند فتاه يوشع، فحملته الملائكة حتى وضعته في دار طالوت. [[عند هذا الموضع انتهى جزء من التقسيم القديم الذي نقلت عنه نسختنا، وفيها هنا ما نصه: "يتلوه إن شاء الله تعالى: ذكر من قال ذلك: وصلى الله على محمد النبي وعلى آله وسلم كثيرا. على الأصل. بلغت بالقراءة من أوله والسماع على القاضي أبي الحسن الخصيب، عن عبد الله، عن أبي محمد الفرغاني، عن أبي جعفر الطبري، والقاضي ينظر في كتابه. وسمع معي أخي على حرسه الله، وأبو الفتح أحمد بن عمر الجهاري (؟ ؟) ونصر بن الحسين الطبري، ومحمد بن علي ... وعبد الرحيم بن أحمد البخاري. وكتب محمد بن أحمد بن عيسى السعدي، في شعبان سنة ثمان وأربعمئة بمصر" "ثم يتلو في أول الجزء التالي: "بسم الله الرحمن الرحيم رب يسر".]] ذكر من قال ذلك: ٥٦٦٢- حدثنا بشر قال، حدثنا يزيد، قال، حدثنا سعيد، عن قتادة في قوله:"إن آية ملكه أن يأتيكم التابوت فيه سكينة من ربكم"، الآية: كان موسى تركه عند فتاه يوشع بن نون وهو بالبرية، وأقبلت به الملائكة تحمله حتى وضعته في دار طالوت فأصبح في داره. ٥٦٦٣- حدثني المثنى قال، حدثنا إسحاق قال، حدثنا ابن أبي جعفر، عن أبيه، عن الربيع في قوله:"إن آية ملكه أن يأتيكم التابوت" الآية، قال: كان موسى - فيما ذكر لنا - ترك التابوت عند فتاه يوشع بن نون وهو في البرية. فذكر لنا أن الملائكة حملته من البرية حتى وضعته في دار طالوت، فأصبح التابوت في داره. * * قال أبو جعفر: وأولى القولين في ذلك بالصواب ما قاله ابن عباس ووهب بن منبه: من أن التابوت كان عند عدو لبني إسرائيل كان سلبهموه. وذلك أن الله تعالى ذكره قال مخبرا عن نبيه في ذلك الزمان قوله لقومه من بني إسرائيل:"إن آية ملكه أن يأتيكم التابوت"، و"الألف واللام" لا تدخلان في مثل هذا من الأسماء إلا في معروف عند المتخاطبين به. وقد عرفه المخبر والمخبر. فقد علم بذلك أن معنى الكلام: إن آية ملكه أن يأتيكم التابوت الذي قد عرفتموه، الذي كنتم تستنصرون به، فيه سكينة من ربكم. ولو كان ذلك تابوتا من التوابيت غير معلوم عندهم قدره ومبلغ نفعه قبل ذلك، لقيل: إن آية ملكه أن يأتيكم تابوت فيه سكينة من ربكم. * * فإن ظن ذو غفلة أنهم كانوا قد عرفوا ذلك التابوت وقدر نفعه وما فيه وهو عند موسى ويوشع، فإن ذلك ما لا يخفى خطؤه. وذلك أنه لم يبلغنا أن موسى لاقى عدوا قط بالتابوت ولا فتاه يوشع، بل الذي يعرف من أمر موسى وأمر فرعون ما قص الله من شأنهما، وكذلك أمره وأمر الجبارين. وأما فتاه يوشع، فإن الذين قالوا هذه المقالة، زعموا أن يوشع خلفه في التيه حتى رد عليهم حين ملك طالوت. فإن كان الأمر على ما وصفوه، فأي الأحوال للتابوت الحال التي عرفوه فيها، فجاز أن يقال: إن آية ملكه أن يأتيكم التابوت الذي قد عرفتموه وعرفتم أمره؟ وفي فساد هذا القول بالذي ذكرنا، [[في المطبوعة: "ففساد هذا القول"، "والصواب ما في المخطوطة.]] أبين الدلالة على صحة القول الآخر، إذ لا قول في ذلك لأهل التأويل غيرهما. * * وكانت صفة التابوت فيما بلغنا، كما: - ٥٦٦٤- حدثنا محمد بن عسكر والحسن بن يحيى قالا أخبرنا عبد الرزاق قال، أخبرنا بكار بن عبد الله قال: سألنا وهب بن منبه عن تابوت موسى: ما كان؟ قال: كان نحوا من ثلاثة أذرع في ذراعين. [[الأثر: ٥٦٦٤-"محمد بن عسكر"، هو محمد بن سهل بن عسكر، سلف في رقم: ٥٥٩٨. بكار بن عبد الله اليماني، روي عن وهب منبه. روى عنه بن ابن المبارك، وهشام بن يوسف وعبد الرزاق. قال أحمد: ثقة. مترجم في الكبير ١/٢/١٢٠، وابن أبي حاتم ١/١ /٤٠٨.]] * * القول في تأويل قوله: ﴿فِيهِ سَكِينَةٌ مِنْ رَبِّكُمْ﴾ قال أبو جعفر: يعني تعالى ذكره بقوله:"فيه"، في التابوت="سكينة من ربكم". * * واختلف أهل التأويل في معنى"السكينة". فقال بعضهم: هي ريح هفافة لها وجه كوجه الإنسان. ذكر من قال ذلك: ٥٦٦٥- حدثنا عمران بن موسى قال، حدثنا عبد الوارث بن سعيد قال، حدثنا محمد بن جحادة، عن سلمة بن كهيل، عن أبي وائل، عن علي بن أبي طالب قال: السكينة، ريح هفافة لها وجه كوجه الإنسان. ٥٦٦٦- حدثنا محمد بن بشار قال، حدثنا عبد الرحمن بن مهدي قال، حدثنا سفيان= وحدثنا الحسن بن يحيى قال، أخبرنا عبد الرزاق قال، أخبرنا سفيان= عن سلمة بن كهيل، عن أبي الأحوص، عن علي قال: السكينة لها وجه كوجه الإنسان، ثم هي ريح هفافة. ٥٦٦٧- حدثني يعقوب بن إبراهيم قال، حدثنا هشيم، عن العوام بن حوشب، عن سلمة بن كهيل، عن علي بن أبي طالب في قوله:"فيه سكينة من ربكم"، قال: ريح هفافة لها صورة= وقال يعقوب في حديثه: لها وجه= [[في المخطوطة: "كما وجه"، وما بينهما بياض، ولعل أقرب ذلك ما في المطبوعة.]] وقال ابن المثنى: كوجه الإنسان. ٥٦٦٨- حدثنا ابن حميد قال، حدثنا جرير، عن منصور، عن سلمة بن كهيل قال، قال علي: السكينة لها وجه كوجه الإنسان، وهي ريح هفافة. [[في المخطوطة: "هى ريح" بإسقاط الواو.]] ٥٦٦٩- حدثنا هناد بن السري قال، حدثنا أبو الأحوص، عن سماك بن حرب، عن خالد بن عرعرة قال، قال علي: السكينة ريح خجوج، ولها رأسان. [[الأثر: ٥٦٦٩- هو بعض الأثر السالف رقم: ٢٠٥٨ في ذكر بناء الكعبة.]] ٥٦٧٠- حدثنا محمد بن المثنى قال، حدثنا محمد بن جعفر قال، حدثنا شعبة، عن سماك قال: سمعت خالد بن عرعرة، يحدث عن علي، نحوه. ٥٦٧١- حدثنا ابن المثنى قال، حدثنا أبو داود قال، حدثنا شعبة، وحماد بن سلمة، وأبو الأحوص، كلهم عن سماك، عن خالد بن عرعرة، عن علي، نحوه. [[الأثران: ٥٦٧٠، ٥٦٧١- انظر الأثران السالفان: ٢٠٥٩، ٢٠٦٠.]] * * وقال آخرون: لها رأس كرأس الهرة وجناحان. ذكر من قال ذلك: ٥٦٧٢- حدثني محمد بن عمرو قال، حدثنا أبو عاصم قال، حدثنا عيسى، عن ابن أبي نجيح، عن مجاهد في قول الله تعالى:" فيه سكينة من ربكم"، قال: أقبلت السكينة [والصرد] وجبريل مع إبراهيم من الشأم= [[ما بين القوسين، زيادة من الأثار التي رويت عن مجاهد في ذلك، في تاريخ مكة للأزرقي ١: ٢٢-٢٨، ونصه في لسان العرب (صرد) . والصرد (بضم الصاد وفتح الراء: طائر أبقع ضخم يكون في الشجر وشعب الجبال لا يقدر عليه أحد، وهو من سباع الطير.]] قال ابن أبي نجيح، سمعت مجاهدا يقول: السكينة لها رأس كرأس الهرة وجناحان. ٥٦٧٣- حدثني المثنى قال، حدثنا أبو حذيفة قال، حدثنا شبل، عن ابن أبي نجيح، عن مجاهد نحوه. ٥٦٧٤- حدثنا ابن وكيع قال، حدثنا أبي قال، حدثنا سفيان، عن ليث، عن مجاهد قال: السكينة لها جناحان وذنب. ٥٦٧٥-حدثنا الحسن بن يحيى قال، أخبرنا عبد الرزاق قال، أخبرنا الثوري، عن ابن أبي نجيح، عن مجاهد قال: لها جناحان وَذَنَب مثل ذنب الهرة. * * وقال آخرون: بل هي رأس هرة ميتة. * * ذكر من قال ذلك: ٥٦٧٧- حدثنا ابن حميد قال، حدثنا سلمة، عن ابن إسحاق، عن وهب بن منبه، عن بعض أهل العلم من بني إسرائيل قال: السكينة رأس هرة ميتة، كانت إذا صرخت في التابوت بصراخ هر، أيقنوا بالنصر وجاءهم الفتح. * * وقال آخرون: إنما هي طست من ذهب من الجنة، كان يغسل فيه قلوب الأنبياء. ذكر من قال ذلك: ٥٦٧٨- حدثنا أبو كريب قال، حدثنا عثمان بن سعيد قال، حدثنا الحكم بن ظهير، عن السدي، عن أبي مالك، عن ابن عباس:"فيه سكينة من ربكم"، قال: طست من ذهب من الجنة، كان يغسل فيه قلوب الأنبياء. ٥٦٧٩- حدثني موسى بن هارون قال، حدثنا عمرو قال، حدثنا أسباط، عن السدي:"فيه سكينة من ربكم"، السكينة: طست من ذهب يغسل فيها قلوب الأنبياء، أعطاها الله موسى، وفيها وضع الألواح. وكانت الألواح، فيما بلغنا، من در وياقوت وزبرجد. * * وقال آخرون:"السكينة"، روح من الله تتكلم. ذكر من قال ذلك: ٥٦٨٠- حدثنا الحسن بن يحيى قال، أخبرنا عبد الرزاق قال، أخبرنا بكار بن عبد الله، قال، سألنا وهب بن منبه فقلنا له: السكينة؟ قال: روح من الله يتكلم، إذا اختلفوا في شيء تكلم فأخبرهم ببيان ما يريدون. ٥٦٨١- حدثنا محمد بن عسكر قال، حدثنا عبد الرزاق قال، حدثنا بكار بن عبد الله: أنه سمع وهب بن منبه، فذكر نحوه. [[الأثران: ٥٦٨٠، ٥٦٨١-"محمد بن عسكر"، و"بكار بن عبد الله". انظر التعليق على الأثر رقم: ٥٦٦٤.]] وقال آخرون:"السكينة"، ما يعرفون من الآيات فيسكنون إليه. ذكر من قال ذلك: ٥٦٨٢- حدثنا القاسم قال، حدثنا الحسين قال، حدثني حجاج، عن ابن جريج قال: سألت عطاء بن أبي رباح عن قوله:"فيه سكينة من ربكم"، الآية، قال: أما السكينة فما يعرفون من الآيات، يسكنون إليها. * * وقال آخرون:"السكينة"، الرحمة. ذكر من قال ذلك: ٥٦٨٣- حدثت عن عمار بن الحسن قال، حدثنا ابن أبي جعفر، عن أبيه، عن الربيع:"فيه سكينة من ربكم"، أي رحمة من ربكم. * * وقال آخرون:"السكينة"، هي الوقار. ذكر من قال ذلك: ٥٦٨٤- حدثنا الحسن بن يحيى قال، أخبرنا عبد الرزاق قال، أخبرنا معمر، عن قتادة في قوله:"فيه سكينة من ربكم"، أي وقار. * * قال أبو جعفر: وأولى هذه الأقوال بالحق في معنى"السكينة"، ما قاله عطاء بن أبي رباح: من الشيء تسكن إليه النفوس من الآيات التي تعرفونها. وذلك أن "السكينة" في كلام العرب"الفعيلة"، من قول القائل:"سكن فلان إلى كذا وكذا"= إذا اطمأن إليه وهدأت عنده نفسه="فهو يسكن سكونا وسكينة"، مثل قولك:"عزم فلان هذا الأمر عزما وعزيمة"، و"قضى الحاكم بين القوم قضاء وقضية"، ومنه قول الشاعر: [[أنشده ابن بري لأبي عريف الكليبي. وأنا في شك من صحة اسمه.]] لله قبر غالها! ماذا يجن؟ ... لقد أجن سكينة ووقارا * * وإذا كان معنى"السكينة" ما وصفت، فجائز أن يكون ذلك على ما قاله علي بن أبي طالب على ما روينا عنه، وجائز أن يكون ذلك على ما قاله مجاهد على ما حكينا عنه، وجائز أن يكون ما قاله وهب بن منبه وما قاله السدي، لأن كل ذلك آيات كافيات تسكن إليهن النفوس، وتثلج بهن الصدور. وإذا كان معنى"السكينة" ما وصفنا، فقد اتضح أن الآية التي كانت في التابوت، التي كانت النفوس تسكن إليها لمعرفتها بصحة أمرها، إنما هي مسماة بالفعل وهي غيره، [[يعني بقوله: " الفعل" مصدر الفعل"سكن"، وهو"السكينة"، كما يقال: "رجل عدل"، فلو سميت الرجل"عدلا"، كان مسمى بالفعل، وهو غيره.]] لدلالة الكلام عليه. * * القول في تأويل قوله: ﴿وَبَقِيَّةٌ مِمَّا تَرَكَ آلُ مُوسَى وَآلُ هَارُونَ﴾ قال أبو جعفر: يعني تعالى ذكره بقوله:"وبقية"، الشيء الباقي، من قول القائل:"قد بقي من هذا الأمر بقية"، وهي"فعلية" منه، نظير"السكينة" من"سكن". * * وقوله:"مما ترك آل موسى وآل هارون"، يعني به: من تركة آل موسى، وآل هارون. * * واختلف أهل التأويل في"البقية" التي كانت بقيت من تركتهم. فقال بعضهم: كانت تلك"البقية" عصا موسى ورضاض الألواح. [[انظر ، تعليق: ١.]] ذكر من قال ذلك: ٥٦٨٥- حدثنا حميد بن مسعدة قال، حدثنا بشر بن المفضل قال، حدثنا داود، عن عكرمة قال: أحسبه عن ابن عباس أنه قال في هذه الآية:"وبقية مما ترك آل موسى وآل هارون"، قال: رضاض الألواح. ٥٦٨٦- حدثنا محمد بن عبد الله بن بزيع قال، حدثنا بشر قال، حدثنا داود، عن عكرمة= قال داود: وأحسبه عن ابن عباس= مثله. ٥٦٨٧- حدثنا ابن المثنى قال، حدثنا أبو الوليد قال، حدثنا حماد، عن داود بن أبي هند، عن عكرمة، عن ابن عباس في هذه الآية:"وبقية مما ترك آل موسى وآل هارون"، قال: عصا موسى ورضاض الألواح. ٥٦٨٨- حدثنا بشر قال، حدثنا يزيد قال، حدثنا سعيد، عن قتادة:"وبقية مما ترك آل موسى وآل هارون"، قال: فكان في التابوت عصا موسى ورضاض الألواح، فيما ذكر لنا. ٥٦٨٩- حدثنا الحسن بن يحيى قال، أخبرنا عبد الرزاق قال، أخبرنا معمر، عن قتادة في قوله:"وبقية مما ترك آل موسى وآل هارون"، قال: البقية عصا موسى ورضاض الألواح. ٥٦٩٠- حدثني موسى قال، حدثنا عمرو قال، حدثنا أسباط، عن السدي:"وبقية مما ترك آل موسى وآل هارون"، أما البقية، فإنها عصا موسى ورضاضة الألواح. [[رضاض الشيء (بضم الراء) : كساره (بضم الكاف) ، وهو ما تكسر منه، وقطعه. ورض الشيء رضا: كسره فصار قطعا. و"رضاضة" بالتاء في آخر رقم: ٥٦٩٠، وهي عربية صحيحة، وإن لم تذكر في المعاجم. ومثلها في مطول هذا الأثر في التاريخ ١: ٢٤٣.]] ٥٦٩١- حدثني المثنى قال، حدثنا إسحاق قال، حدثنا ابن أبي جعفر، عن أبيه، عن الربيع:"وبقية مما ترك آل موسى وآل هارون"، عصا موسى وأثور من التوراة. [[في المطبوعة: "وأمور من التوراة". وفي المخطوطة: "وأسور من التوارة". ورجحت قراءتها"وأثور" جمع أثر: وهو بقية الشيء، وما بقى من رسم الشيء، وجمعه آثار وأثور. وهي هنا بمعنى الرضاض.]] ٥٦٩٢- حدثني المثنى قال، حدثنا إسحاق قال، حدثنا عبد الوهاب الثقفي، عن خالد الحذاء، عن عكرمة في هذه الآية:"وبقية مما ترك آل موسى وآل هارون"، قال: التوراة ورضاض الألواح والعصا= قال إسحاق، قال وكيع: ورضاضه كسره. ٥٦٩٣- حدثني يعقوب قال، حدثنا ابن علية، عن خالد، عن عكرمة في قوله:"وبقية مما ترك آل موسى وآل هارون"، قال: رضاض الألواح. * * وقال آخرون: بل تلك"البقية" عصا موسى وعصا هارون، وشيء من الألواح. [[في المخطوطة: "بل ذلك البقية ... "، والذي في المطبوعة أجود الصواب.]] ذكر من قال ذلك: ٥٦٩٤- حدثنا أبو كريب قال، حدثنا جابر بن نوح، عن إسماعيل، عن ابن أبي خالد، عن أبي صالح:"أن يأتيكم التابوت فيه سكينة من ربكم وبقية مما ترك آل موسى وآل هارون"، قال: كان فيه عصا موسى وعصا هارون، ولوحان من التوراة، والمن. [[الأثر: ٥٦٩٤- في الدر المنثور ١: ٣١٧ مطولا. وفي المخطوطة والمطبوعة: "عن إسماعيل عن ابن أبي خالد"، والصواب ما أثبت، وهو الذي يروي عنه جابر بن نوح، مترجم التهذيب.]] ٥٦٩٥- حدثنا أبو كريب قال، حدثنا ابن إدريس قال، سمعت أبي، عن عطية بن سعد في قوله:"وبقية مما ترك آل موسى وآل هارون"، قال: عصا موسى، وعصا هارون، وثياب موسى، وثياب هارون، ورضاض الألواح. * * وقال آخرون: بل هي العصا والنعلان. ذكر من قال ذلك: ٥٦٩٦- حدثنا الحسن بن يحيى قال، أخبرنا عبد الرزاق قال، سألت الثوري عن قوله:"وبقية مما ترك آل موسى وآل هارون"، قال: منهم من يقول: البقية قفيز من من ورضاض الألواح- ومنهم من يقول: العصا والنعلان. [[القفيز: مكيال من المكاييل، كان عند أهل العراق ثمانية مكاكيك.]] * * وقال آخرون: بل كان ذلك العصا وحدها. ذكر من قال ذلك: ٥٦٩٧- حدثنا الحسن بن يحيى قال، أخبرنا عبد الرزاق قال، أخبرنا بكار بن عبد الله قال، قلنا لوهب بن منبه: ما كان فيه؟ = يعني في التابوت= قال: كان فيه عصا موسى والسكينة. [[الأثر ٥٦٩٧- بكار بن عبد الله اليماني، مضى في الآثار: ٥٦٦٤، ٥٦٨٠، ٥٦٨١، وكان في المطبوعة والمحفوظة"بكار عن عبد الله"، وهو خطأ محض.]] * * وقال آخرون: بل كان ذلك، رضاض الألواح وما تكسر منها. ذكر من قال ذلك: ٥٦٩٨- حدثنا القاسم قال، حدثني حجاج قال، قال ابن جريج، قال ابن عباس في قوله:" وبقية مما ترك آل موسى وآل هارون"، قال: كان موسى حين ألقى الألواح تكسرت ورفع منها، فجعل الباقي في ذلك التابوت. ٥٦٩٩- حدثنا القاسم قال، حدثنا الحسين قال، حدثني حجاج، عن ابن جريج قال، سألت عطاء بن أبي رباح عن قوله:"وبقية مما ترك آل موسى وآل هارون"، [قال] العلم والتوراة. [[زدت ما بين القوسين: لظني أنها سقطت من الناسخ لعجلته، كما يتبين من خطه في هذا الموضع.]] * * وقال آخرون: بل ذلك الجهاد في سبيل الله. ذكر من قال ذلك: ٥٧٠٠- حدثت عن الحسين بن الفرج قال، سمعت أبا معاذ قال، أخبرنا عبيد الله بن سليمان قال، سمعت الضحاك يقول في قوله:"وبقية مما ترك آل موسى وآل هارون"، يعني ب"البقية"، القتال في سبيل الله، وبذلك قاتلوا مع طالوت، وبذلك أمروا. قال أبو جعفر: وأولى الأقوال في ذلك بالصواب أن يقال: إن الله تعالى ذكره أخبر عن التابوت الذي جعله آية لصدق قول نبيه صلى الله عليه = الذي قال لأمته: [[في المطبوعة: "لصدق قول نبيه ﷺ لأمته"، زاد: "وسلم"، وأسقط"الذي قال"، والصواب من المخطوطة.]] "إن الله قد بعث لكم طالوت ملكا" = أن فيه سكينة منه، وبقية مما تركه آل موسى وآل هارون. [[في المطبوعة: "مما تركه آل موسى"، وأثبت ما في المخطوطة.]] وجائز أن يكون تلك البقية: العصا، وكسر الألواح، والتوراة، أو بعضها، والنعلين، والثياب، والجهاد في سبيل الله = وجائز أن يكون بعض ذلك، وذلك أمر لا يدرك علمه من جهة الاستخراج ولا اللغة، ولا يدرك علم ذلك إلا بخبر يوجب عنه العلم. ولا خبر عند أهل الإسلام في ذلك للصفة التي وصفنا. وإذ كان كذلك، فغير جائز فيه تصويب قول وتضعيف آخر غيره، إذ كان جائزا فيه ما قلنا من القول. * * القول في تأويل قوله: ﴿تَحْمِلُهُ الْمَلائِكَةُ﴾ قال أبو جعفر: اختلف أهل التأويل في صفة حمل الملائكة ذلك التابوت. فقال بعضهم: معنى ذلك: تحمله بين السماء والأرض، حتى تضعه بين أظهرهم. ذكر من قال ذلك: ٥٧٠١- حدثنا القاسم قال، حدثنا الحسين قال، حدثني حجاج، عن ابن جريج قال، قال ابن عباس: جاءت الملائكة بالتابوت تحمله بين السماء والأرض وهم ينظرون إليه، حتى وضعته عند طالوت. ٥٧٠٢- حدثني يونس قال، أخبرنا ابن وهب قال، قال ابن زيد: لما قال لهم= يعني النبي، لبني إسرائيل: ="والله يؤتي ملكه من يشاء". قالوا: فمن لنا بأن الله هو آتاه هذا! ما هو إلا لهواك فيه! قال: إن كنتم قد كذبتموني واتهمتمون، فإن آية ملكه:"أن يأتيكم التابوت فيه سكينة من ربكم"، الآية. قال: فنزلت الملائكة بالتابوت نهارا ينظرون إليه عيانا، حتى وضعوه بين أظهرهم، فأقروا غير راضين، وخرجوا ساخطين، وقرأ حتى بلغ:"والله مع الصابرين". ٥٧٠٣- حدثني موسى قال، حدثنا عمرو قال، حدثنا أسباط، عن السدي قال: لما قال لهم نبيهم:"إن الله اصطفاه عليكم وزاده بسطة في العلم والجسم"، قالوا: فإن كنت صادقا فأتنا بآية أن هذا ملك! قال:"إن آية ملكه أن يأتيكم التابوت فيه سكينة من ربكم وبقية مما ترك آل موسى وآل هارون تحمله الملائكة". وأصبح التابوت وما فيه في دار طالوت، فآمنوا بنبوة شمعون، وسلموا ملك طالوت. ٥٧٠٤- حدثنا الحسن بن يحيى قال، أخبرنا عبد الرزاق قال، أخبرنا معمر، عن قتادة في قوله:"تحمله الملائكة"، قال: تحمله حتى تضعه في بيت طالوت. * * وقال آخرون: معنى ذلك: تسوق الملائكة الدواب التي تحمله. ذكر من قال ذلك: ٥٧٠٥- حدثنا الحسن بن يحيى قال، أخبرنا عبد الرزاق قال، أخبرنا الثوري، عن بعض أشياخه قال: تحمله الملائكة على عجلة على بقرة. ٥٧٠٦- حدثنا الحسن قال، أخبرنا عبد الرزاق قال، أخبرنا عبد الصمد بن معقل: أنه سمع وهب بن منبه يقول: وكل بالبقرتين اللتين سارتا بالتابوت أربعة من الملائكة يسوقونهما، فسارت البقرتان بهما سيرا سريعا، حتى إذا بلغتا طرف القدس ذهبتا. * * قال أبو جعفر: وأولى القولين في ذلك بالصواب قول من قال:"حملت التابوت الملائكة حتى وضعته لها في دار طالوت قائما بين أظهر بني إسرائيل". [[في المطبوعة: "حتى وضعته في دار طالوت" بإسقاط"لها"، أي لبني إسرائيل. وفي المطبوعة: "في دار طالوت بين أظهر بني إسرائيل" بإسقاط"قائما"، وكانت هذه اللفظة في المخطوطة: "ما بين أظهر لبني إسرائيل"، وقرأتها: "قائما".]] وذلك أن الله تعالى ذكره قال:"تحمله الملائكة"، ولم يقل: تأتي به…',     source_page = '332',     updated_at  = datetime('now') WHERE id = 'QR:TE:731cefd6182c388d9fbb4efc';
UPDATE qr_tafsir_entries SET content_ar = 'القول في تأويل قوله تعالى: ﴿فَاطِرُ السَّمَاوَاتِ وَالأرْضِ جَعَلَ لَكُمْ مِنْ أَنْفُسِكُمْ أَزْوَاجًا وَمِنَ الأنْعَامِ أَزْوَاجًا يَذْرَؤُكُمْ فِيهِ لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ الْبَصِيرُ (١١) ﴾ يقول تعالى ذكره: ﴿فَاطِرُ السَّمَاوَاتِ وَالأرْضِ﴾ ، خالق السموات السبع والأرض. كما: ⁕ حدثنا محمد، قال: ثنا أحمد، قال: ثنا أسباط، عن السديّ، قوله: ﴿فَاطِرُ السَّمَاوَاتِ وَالأرْضِ﴾ قال: خالق. * * وقوله: ﴿جَعَلَ لَكُمْ مِنْ أَنْفُسِكُمْ أَزْوَاجًا﴾ يقول تعالى ذكره: زوّجكم ربكم من أنفسكم أزواجا. وإنما قال جلّ ثناؤه: ﴿مِنْ أَنْفُسِكُمْ﴾ لأنه خلق حوّاء من ضلع آدم، فهو من الرجال. ﴿وَمِنَ الأنْعَامِ أَزْوَاجًا﴾ يقول جلّ ثناؤه: وجعل لكم من الأنعام أزواجا من الضأن اثنين، ومن المعز اثنين، ومن الإبل اثنين، ومن البقر اثنين، ذكورا وإناثا، ومن كل جنس من ذلك. ﴿يَذْرَؤُكُمْ فِيهِ﴾ يقول: يخلقكم فيما جعل لكم من أزواجكم، ويعيشكم فيما جعل لكم من الأنعام. وقد اختلف أهل التأويل في معنى قوله: ﴿يَذْرَؤُكُمْ فِيهِ﴾ في هذا الموضع، فقال بعضهم: معنى ذلك: يخلقكم فيه. ذكر من قال ذلك: ⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء جميعا، عن ابن أبي نجيع، عن مجاهد، في قوله: ﴿يَذْرَؤُكُمْ فِيهِ﴾ قال: نسل بعد نسل من الناس والأنعام. ⁕ حدثنا محمد بن المثنى، قال: ثنا أحمد، قال: ثنا أسباط، عن السديّ، قوله: ﴿يَذْرَؤُكُمْ﴾ قال: يخلقكم. ⁕ حدثنا ابن حميد، قال: ثنا حكام، عن عنبسة، عن محمد بن عبد الرحمن، عن القاسم بن أبي بزّة، عن مجاهد، في قوله: ﴿يَذْرَؤُكُمْ فِيهِ﴾ قال: نسلا بعد نسل من الناس والأنعام. ⁕ حدثنا محمد بن المثنى، قال: ثنا محمد بن جعفر، قال ثنا شعبة، عن منصور، أنه قال في هذه الآية: ﴿يَذْرَؤُكُمْ فِيهِ﴾ قال يخلقكم. وقال آخرون: بل معناه: يعيشكم فيه. ذكر من قال ذلك: ⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، قوله: ﴿جَعَلَ لَكُمْ مِنْ أَنْفُسِكُمْ أَزْوَاجًا وَمِنَ الأنْعَامِ أَزْوَاجًا يَذْرَؤُكُمْ فِيهِ﴾ يقول: يجعل لكم فيه معيشة تعيشون بها. ⁕ حدثنا محمد بن عبد الأعلى، قال: ثنا محمد بن ثور، عن معمر، عن قتادة ﴿يَذْرَؤُكُمْ فِيهِ﴾ قال: يعيشكم فيه. ⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿يَذْرَؤُكُمْ فِيهِ﴾ قال: عيش من الله يعيشكم فيه. وهذان القولان وإن اختلفا في اللفظ من قائليهما فقد يحتمل توجيههما إلى معنى واحد، وهو أن يكون القائل في معناه يعيشكم فيه، أراد بقوله ذلك: يحييكم بعيشكم به كما يحيي من لم يخلق بتكوينه إياه، ونفخه الروح فيه حتى يعيش حيا. وقد بينت معنى ذرء الله الخلق فيما مضى بشواهده المغنية عن إعادته. * * وقوله: ﴿لَيْسَ كَمِثْلِهِ شَيْءٌ﴾ فيه وجهان: أحدهما أن يكون معناه: ليس هو كشيء، وأدخل المثل في الكلام توكيدًا للكلام إذا اختلف اللفظ به وبالكاف، وهما بمعنى واحد، كما قيل: ما إن نديت بشيء أنت تكرهه [[هذا مصراع أول من بيت للنابغة الذبياني. وعجزه: * إذن فلا رفعت سوطي إلى يدي * (انظر مختار الشعر الجاهلي بشرح مصطفى السقا طبعة الحلبي) ورواية الشطر الأول فيه: * ما قلت من سييء مما أتيت به * قال شارحه: يقول: إذا كنت قلت هذا الذي بلغك، فشلت يدي حتى لا أطيق رفع السوط على خفته. وروى في اللسان والتاج كرواية المؤلف، قال الزبيدي: يقال: ما نديني من فلان شيء أكرهه، أي ما بلني ولا أصابني. وما نديت له كفى بشر وما نديت بشيء. ومحل الشاهد في البيت عند المؤلف قوله" ما إن" حيث أدخل حرف النفي" ما" على حرف النفي" إن" لاختلاف لفظهما، توكيدا للكلام. وهو نظير إدخال كاف التشبيه، على كلمة" مثل" التي تفيد التشبيه، في قوله تعالى (ليس كمثله شيء) ، لتوكيد الكلام؛ لاختلاف اللفظين.]] فأدخل على"ما" وهي حرف جحد"إن" وهي أيضًا حرف جحد، لاختلاف اللفظ بهما، وإن اتفق معناهما توكيدا للكلام، وكما قال أوس بن حجر: وَقَتْلَى كمِثْلِ جذُوعِ النَّخيلْ ... تَغَشَّاهُمُ مُسْبِلٌ مُنْهَمِرْ [[وهذا الشاهد من كلام أوس بن حجر التميمي، وهو شاعر جاهلي مشهور، شاهد كالشاهد السابق، أدل فيه أداة التشبيه" الكاف" على أختها في المعنى" مثل" لاختلاف لفظهما، توكيدا للكلام، وهو نظير" ما" في قوله تعالى: (ليس كمثله شيء) .]] ومعنى ذلك: كجذوع النخيل، وكما قال الآخر: سَعْدُ بْنُ زيد إذَا أبْصَرْتَ فَضْلَهُمُ ... ما إن كمِثْلِهِمِ فِي النَّاسِ مِنْ أحَدٍ [[لم أقف على قائل هذا البيت. وقد استشهد به المؤلف على إدخال أداتي التشبيه (الكاف، ومثل) معا على شيء واحد، فهو في معنى الشاهدين قبله.]] والآخر: أن يكون معناه: ليس مثل شيء، وتكون الكاف هي المدخلة في الكلام، كقول الراجز: وَصَالِياتٍ كَكَما يُؤْثَفَيْنِ [[هذا بيت من عدة أبيات من مشطور الرجز، ينسبان على خطام المجاشعي، ونسبهما الجوهري في الصحاح، والصقلي في شرحه لأبيات الإيضاح للفارسي، إلى هميان بن قحافة. وبيت الشاهد آخرها بيتا. (انظر الأبيات في هامش من الجزء الأول من سر صناعة الإعراب لابن جنى طبعة شركة مصطفى البابي الحبي وأولاده) وفيه: الصاليات: الأثافي التي توضع عليها القدور وقد صليت النار حتى اسودت. ويؤثفين: يجعلن أثافي للقدر، وهي جمع أثفية، يقال أثفى القدر يثفيها: جعل لها أثافي. ومحل الشاهد قوله" كما" فإن الكاف الأولى حرف، والثانية اسم بمعنى مثل. والمعنى: لم يبق إلا حجارة منصوبة كمثل الأثافي. واستشهد به المؤلف على دخول الكاف على الكاف لتوكيد الكلام.]] فأدخل على الكاف كافا توكيدا للتشبيه، وكما قال الآخر: تَنْفِي الغَيادِيقُ عَلى الطَّرِيقِ ... قَلَّصَ عَنْ كَبَيْضَةٍ فِي نِيقِ [[لم أقف على قائل البيت. ولم يتضح لي معناه تماما، ولعل فيه تحريفا من الناسخ. وموضع الشاهد فيه واضح، وهو دخول" عن" على الكاف في قوله"كبيضة" فإما أن تكون الكاف زائدة، أي عن بيضة، وإما أن تكون الكاف اسما بمعنى مثل في محل جر.]] فأدخل الكاف مع"عن"، وقد بيَّنا هذا في موضع غير هذا المكان بشرح هو أبلغ من هذا الشرح، فلذلك تجوّزنا في البيان عنه في هذا الموضع. * * وقوله: ﴿وَهُوَ السَّمِيعُ الْبَصِيرُ﴾ يقول جلّ ثناؤه واصفا نفسه بما هو به، وهو يعني نفسه: السميع لما تنطق به خلقه من قول، البصير لأعمالهم، لا يخفى عليه من ذلك شيء، ولا يعزب عنه علم شيء منه، وهو محيط بجميعه، محصٍ صغيره وكبيره ﴿لِتُجْزَى كُلُّ نَفْسٍ بِمَا كَسَبَتْ﴾ من خير أو شرّ.',     source_page = '282',     updated_at  = datetime('now') WHERE id = 'QR:TE:5c8b8e8e993d293d6069e244';
UPDATE qr_tafsir_entries SET content_ar = 'القول في تأويل قوله تعالى: ﴿وَالأرْضَ وَضَعَهَا لِلأنَامِ (١٠) فِيهَا فَاكِهَةٌ وَالنَّخْلُ ذَاتُ الأكْمَامِ (١١) وَالْحَبُّ ذُو الْعَصْفِ وَالرَّيْحَانُ (١٢) ﴾ يقول تعالى ذكره ﴿وَالأرْضَ وَضَعَهَا لِلأنَامِ﴾ والأرض وطأها للخلق، وهم الأنام. وبنحو الذي قلنا في ذلك قال أهل التأويل. ذكر من قال ذلك: ⁕ حدثنا عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، قوله: ﴿لِلأنَامِ﴾ يقول: للخلق. ⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثنى أبي، عن أبيه، عن ابن عباس، قوله: ﴿وَالأرْضَ وَضَعَهَا لِلأنَامِ﴾ قال: كلّ شيء فيه الروح. ⁕ حدثني يعقوب، قال: ثنا ابن عُلَية، قال: أخبرنا أبو رجاء، عن الحسن، في قوله: ﴿وَالأرْضَ وَضَعَهَا لِلأنَامِ﴾ قال: للخلق الجنّ والإنس. ⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء جميعا، عن ابن أبي نجيح، عن مجاهد، في قوله: ﴿لِلأنَامِ﴾ قال: للخلائق. ⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿لِلأنَامِ﴾ قال: للخلق. ⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿وَضَعَهَا لِلأنَامِ﴾ قال: الأنام: الخلق. ⁕ حدثنا ابن بشار، قال: ثنا محمد بن مروان، قال: ثنا أبو العوّام، عن قتادة ﴿وَالأرْضَ وَضَعَهَا لِلأنَامِ﴾ قال: للخلق. ⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، مثله. وقوله: (فِيهَا فَاكِهَةٌ وَالنَّخْلُ ذَاتُ الأكْمَامِ) يقول تعالى ذكره: في الأرض فاكهة، والهاء والألف فيها من ذكر الأرض. ﴿وَالنَّخْلُ ذَاتُ الأكْمَامِ﴾ : والأكمام: جمع كِمّ، وهو ما تكممت فيه. واختلف أهل التأويل في معنى ذلك، فقال: بعضهم: عنى بذلك تكمم النخل في الليف. ذكر من قال ذلك: ⁕ حدثني يعقوب، قال: ثنا ابن علية، عن أبي رجاء، قال: سألت الحسن، عن قوله: ﴿وَالنَّخْلُ ذَاتُ الأكْمَامِ﴾ ، فقال: سَعَفة من ليف عُصبَتْ بها. ⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة والحسن ﴿ذَاتُ الأكْمَامِ﴾ : أكمامها: ليفها. ⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَالنَّخْلُ ذَاتُ الأكْمَامِ﴾ : الليف الذي يكون عليها. وقال آخرون: يعني بالأكمام: الرُّفات. ذكر من قال ذلك: ⁕ حدثنا ابن بشار، قال: ثنا محمد بن مروان، قال: ثنا أبو العوّام، عن قتادة ﴿وَالنَّخْلُ ذَاتُ الأكْمَامِ﴾ ، قال: أكمامها رُفاتها. وقال آخرون: بل معنى الكلام: والنخل ذات الطلع المتكمم في كمامه. ذكر من قال ذلك: ⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال، قال ابن زيد في قوله: ﴿وَالنَّخْلُ ذَاتُ الأكْمَامِ﴾ ، وقيل له: هو الطلع، قال: نعم، وهو في كم منه حتى ينفتق عنه، قال: والحبّ أيضا في أكمام. وقرأ: ﴿وَمَا تَخْرُجُ مِنْ ثَمَرَاتٍ مِنْ أَكْمَامِهَا﴾ . وأولى الأقوال في ذلك بالصواب أن يقال: إن الله وصف النخل بأنها ذات أكمام، وهي متكممة في ليفها، وطلعها متكمم في جُفِّهِ، ولم يخصص الله الخبر عنها بتكممها في ليفها ولا تكمم طلعها في جفه، بل عمّ الخبر عنها بأنها ذات أكمام. والصواب أن يقال: عني بذلك ذات ليف، وهي به مُتَكَممة وذات طَلعْ هو في جُفِّه متكمِّمٌ فيُعَمَّم، كما عَمَّ جلّ ثناؤه. * * وقوله: ﴿وَالْحَبُّ ذُو الْعَصْفِ وَالرَّيْحَانُ﴾ يقول تعالى ذكره: وفيها الحبّ، وهو حبّ البُرّ والشعير ذو الورق، والتبن: هو العَصْف، وإياه عنى علقمة بن عَبَدَة: تَسقِى مَذَانِبَ قَدْ مالَتْ عَصِيفَتُها ... حَدُورَها مِنْ أتِيّ المَاء مَطْمومُ [[هذا الشاهد من شواهد أبي عبيدة في مجاز القرآن (الورقة ١٧٢ من مصورة جامعة القاهرة رقم ٢٦٣٩٠ عن نسخة "مراد متلا ". وهذا بعد ان انتهت مراجعنا على الصورة الأولى رقم ٢٦٠٥٩ لانتهاء أورقها عند سورة القمر) أنشده أبو عبيدة عند قوله تعالى: (والحب ذو العصف والريحان) قال: تخرج له عصيفة، وهي أذنته أعلاه، وهو الهبود، وأذنه إنما هي زيادته وكثرته وورقه الذي يتعصف.وهو كما قال علقمة بن عبدة " تسقى مذانب ... البيت ". طمها: ملأها لم يبق فيها شيء، وطم إناءه ملأه. وقال شارح مختار الشعر الجاهلي ٤٢٦: المذانب جمع مذنب، وهو مسيل الماء إلى الأرض، والجدول يسيل عن الروضة بمائها إلى ويرها: وعصيفتها: هي الورق الذي يجز فيؤكل، ثم يسقى أصله، ليعود ورقه. وجذورها: الذي انحدر من هذه المذانب واطمأن. الأتي: الجدول. وأراد به هنا: ما يسيل من الماء في الجدول. والمطموم: المملوء بالماء.]] وبنحو الذي قلنا في ذلك قال أهل التأويل. ذكر من قال ذلك: ⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، قوله: ﴿وَالْحَبُّ ذُو الْعَصْفِ وَالرَّيْحَانُ﴾ يقول: التبن. ⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، قوله: ﴿وَالْحَبُّ ذُو الْعَصْفِ وَالرَّيْحَانُ﴾ قال: العصف: ورق الزرع الأخضر الذي قطع رءوسه، فهو يسمى العصف إذا يبس. ⁕ حدثنا ابن حُمَيد، قال: ثنا يعقوب، عن جعفر، عن سعيد ﴿وَالْحَبُّ ذُو الْعَصْفِ﴾ : البقل من الزرع. ⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿وَالْحَبُّ ذُو الْعَصْفِ﴾ ، وعصفه تبنه. ⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، قال: العصف: التبن. ⁕ حدثنا ابن حُميد، قال: ثنا مهران، عن سفيان، عن الضحاك ﴿وَالْحَبُّ ذُو الْعَصْفِ﴾ ، قال: الحبّ: البّر والشعير، والعصف: التِّبن. ⁕ حدثنا سعيد بن يحيى، قال: ثنا عبد الله بن المبارك الخراسانيّ، عن إسماعيل بن أبي خالد، عن أبي مالك قوله: ﴿وَالْحَبُّ ذُو الْعَصْفِ وَالرَّيْحَانُ﴾ قال: الحب أول ما ينبت. ⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء جميعا، عن ابن أبي نجيح، عن مجاهد في قوله: ﴿وَالْحَبُّ ذُو الْعَصْفِ وَالرَّيْحَانُ﴾ قال: العصف: الورق من كل شيء. قال: يقال للزرع إذا قُطع: عصافة، وكلّ ورق فهو عصافة. ⁕ حدثنا الحسن بن عرفة، قال: ثني يونس بن محمد، قال: ثنا عبد الواحد، قال: ثنا أبو روق عطية بن الحارث، قال: سمعت الضحاك يقول في قوله: ﴿وَالْحَبُّ ذُو الْعَصْفِ﴾ قال: العصف: التبن. ⁕ حدثنا سليمان بن عبد الجبار، قال: ثنا محمد بن الصلت، قال: ثنا أبو كُدَينة، عن عطاء، عن سعيد، عن ابن عباس ﴿ذُو الْعَصْفِ﴾ قال: العصف: الزرع. وقال بعضهم: العصف: هو الحب من البرّ والشعير بعينه. ذكر من قال ذلك: ⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: أخبرنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿وَالْحَبُّ ذُو الْعَصْفِ وَالرَّيْحَانُ﴾ ، أما العصف: فهو البرّ والشعير. وأما قوله: ﴿وَالرَّيْحَانُ﴾ فإن أهل التأويل اختلفوا في تأويله فقال بعضهم: هو الرزق. ذكر من قال ذلك: ⁕ حدثني زيد بن أخزم الطائي، قال: ثنا عامر بن مدرك، قال: ثنا عتبة بن يقظان، عن عكرِمة، عن ابن عباس، قال: كلّ ريحان في القرآن فهو رزق. ⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء جميعا، عن ابن أبي نجيح، عن مجاهد ﴿وَالرَّيْحَانُ﴾ قال: الرزق. ⁕ حدثنا ابن حُميد، قال: ثنا مهران، عن سفيان، عن الضحاك ﴿وَالرَّيْحَانُ﴾ : الرزق، ومنهم من يقول: ريحاننا. ⁕ حدثني سليمان بن عبد الجبار، قال: ثنا محمد بن الصلت، قال: ثنا أبو كدينة، عن عطاء، عن سعيد بن جُبير، عن ابن عباس ﴿وَالرَّيْحَانُ﴾ قال: الريح. ⁕ حدثنا الحسن بن عرفة، قال: ثني يونس بن محمد، قال: ثنا عبد الواحد، قال: ثنا أبو روق عطية بن الحارث، قال: سمعت الضحاك يقول في قوله: ﴿وَالرَّيْحَانُ﴾ قال: الرزق والطعام. وقال آخرون: هو الريحان الذي يشمّ. ذكر من قال ذلك: ⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، قال: ﴿الريحان﴾ ما تنبت الأرض من الريحان. ⁕ حدثت عن الحسين، قال: سمعت أبا معاذ يقول: أخبرنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿وَالرَّيْحَانُ﴾ : أما الريحان فما أنبتت الأرض من ريحان. ⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، عن الحسن ﴿وَالرَّيْحَانُ﴾ قال: ريحانكم هذا، حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد في قوله: ﴿وَالرَّيْحَانُ﴾ : الرياحين التي توجد ريحها. وقال آخرون: هو خُضرة الزرع. ⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية عن عليّ، عن ابن عباس، قوله: ﴿وَالرَّيْحَانُ﴾ يقول: خُضرة الزرع. وقال آخرون: هو ما قام على ساق. ذكر من قال ذلك: ⁕ حدثنا ابن حُميد، قال: ثنا يعقوب، عن جعفر، عن سعيد، قال: ﴿الريحان﴾ ما قام على ساق. وأولى الأقوال في ذلك بالصواب قول من قال: عُنِي به الرزق، وهو الحبّ الذي يؤكل منه. وإنما قلنا ذلك أولى الأقوال في ذلك بالصواب؛ لأن الله جلّ ثناؤه أخبر عن الحبّ أنه ذو العصف، وذلك ما وصفنا من الورق الحادث منه، والتبن إذا يبس، فالذي هو أولى بالريحان، أن يكون حبه الحادث منه، إذ كان من جنس الشيء الذي منه العصف، ومسموع من العرب تقول: خرجنا نطلب رَيْحان الله ورزقه، ويقال: سبحانَك وريحانَك: أي ورزقك، ومنه قول النمر بن تَوْلب: سَلامُ الإله وَرَيْحانُهُ ... وجَنَّتُهُ وسَماءٌ درَرْ [[البيت للنمر بن تولب العكلي (اللسان: روح) وبعده: غَمامٌ يُنَزِّل رِزْقَ العِباد ... فأحْيا البِلادَ وطَابَ الشَّجَرْ وهو من شواهد أبي عبيدة في مجاز القرآن (الورقة ١٧٢ من المصورة ٢٦٣٩٠ بجامعة القاهرة) قال: والريحان والحب منه الذي يؤكل، يقال: سبحانك وريحانك: أي رزقك؛ قال النمر بن تولب " سلام الإله ... البيت " اهـ. وفي (اللسان: درر) : والدرة في الأمطار أن يتبع بعضها بعضا، وجمعها: درر، وللسحاب درر: أي صب، الجمع: درر؛ قال النمر بن تولب: ... البيتين. سماء درر أي: ذات درر. اهـ.]] وذُكر عن بعضهم أنه كان يقول: العصف: المأكول من الحبّ والريحان: الصحيح الذي لم يؤكل. واختلفت القراء في قراءة قوله: ﴿وَالرَّيْحَانُ﴾ ، فقرأ ذلك عامة قرّاء المدينة والبصرة وبعض المكيين، وبعض الكوفيين بالرفع عطفا به على الحبّ، بمعنى: وفيها الحبّ ذو العصف، وفيها الريحان أيضا. وقرأ ذلك عامة قرّاء الكوفيين. ﴿وَالرَّيْحَانُ﴾ بالخفض عطفا به على العصف، بمعنى والحبّ ذو العصف وذو الريحان. [[هذا من كلام الفراء في معاني القرآن من المخطوطة.]] وأولى القراءتين في ذلك بالصواب: قراءة من قرأه بالخفض للعلة التي بينت في تأويله، وأنه بمعنى الرزق. وأما الذين قرءوه رفعا، فإنهم وجَّهوا تأويله فيما أرى إلى أنه الريحان الذي يشمّ، فلذلك اختاروا الرفع فيه وكونه خفضا بمعنى: وفيها الحبّ ذو الورق والتبن، وذو الرزق المطعوم أولى وأحسن لما قد بيَّناه قبل.',     source_page = '320',     updated_at  = datetime('now') WHERE id = 'QR:TE:d6bbade90052cd747cccce18';
UPDATE qr_tafsir_entries SET content_ar = 'القول في تأويل قوله تعالى: ﴿هَذِهِ جَهَنَّمُ الَّتِي يُكَذِّبُ بِهَا الْمُجْرِمُونَ (٤٣) يَطُوفُونَ بَيْنَهَا وَبَيْنَ حَمِيمٍ آنٍ (٤٤) فَبِأَيِّ آلاءِ رَبِّكُمَا تُكَذِّبَانِ (٤٥) ﴾ يقول تعالى ذكره: يقال لهؤلاء المجرمين الذين أخبر جلّ ثناؤه أنهم يعرفون يوم القيامة بسيماهم حين يؤخذ بالنواصي والأقدام: هذه جهنم التي يكذّب بها المجرمون، فترك ذكر "يقال" اكتفاء بدلالة الكلام عليه منه، وذُكر أن ذلك في قراءة عبد الله ﴿وهذه جهنم التي كنتما بها تكذّبان تصليانها، لا تموتان فيها ولا تحييان﴾ . [[ذكر الفراء في معاني القرآن (مصورة الجامعة ٢٤٠٥٩ ) قراءة عبد الله، وزاد فيها بعد قوله: (تحييان) : تطوفان. اهـ. و " تطوفان ": هي بدء الآية التي بعدها: (يطوفون بينها.... إلخ) .]] * * وقوله: ﴿يَطُوفُونَ بَيْنَهَا وَبَيْنَ حَمِيمٍ آنٍ﴾ يقول تعالى ذكره: يطوف هؤلاء المجرمون الذين وصف صفتهم في جهنم بين أطباقها ﴿وَبَيْنَ حَمِيمٍ آنٍ﴾ يقول: وبين ماء قد أسخن وأغلي حتى انتهى حرّه وأنى طبخه، وكل شيء قد أدرك وبلغ فقد أنى، ومنه قوله: ﴿غَيْرَ نَاظِرِينَ إِنَاهُ﴾ يعني: إدراكه وبلوغه، كما قال: نابغة بني ذُبيان: ويُخْضَب لِحْيَةٌ غدَرَتْ وخانَتْ بأحمَرَ مِنْ نَجيع الجَوْفِ آني [[البيت لنابغة بني ذبيان (مختار الشعر الجاهلي بشرح مصطفى السقا، طبعة الحلبي ١٩٤) من قصيدة يهجو بها يزيد بن عمرو بن الصعق الكلابي في قصة ذكرها شارحه في ١٩٣ عند بدء القصيدة، (وانظر شرح الأعلم، والوزير أبي بكر البطليوسي على الأشعار الستة، والجزء الأول من خزانة الأدب الكبرى، لعبد القادر البغدادي ٢٠٤ - ٢٠٥) وقال شارح البيت: نجيع الجوف: الدم الخالص. والآنى: الشديد الحرارة، وهو الذي بلغ أناه. اهـ. وقال أبو عبيدة في مجاز القرآن (الورقة ١٧٣ - ب) : عند قوله تعالى: (وبين حميم آن: بلغ أناه في شدة الحر. اهـ.]] يعني: مدرك. وبنحو الذي قلنا في ذلك قال أهل التأويل. ذكر من قال ذلك: ⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس قوله: ﴿وَبَيْنَ حَمِيمٍ آنٍ﴾ يقول: انتهى حرُّه. ⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، قوله: ﴿وَبَيْنَ حَمِيمٍ آنٍ﴾ يقول: غلى حتى انتهى غليه. ⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن قال: ثنا ورقاء جميعا، عن ابن أبي نجيح، عن مجاهد، في قوله: ﴿وَبَيْنَ حَمِيمٍ آنٍ﴾ قال: قد بلغ إناه. ⁕ حدثنا ابن حميد، قال: ثنا يعقوب، عن جعفر، عن سعيد، قال: الآني الذي قد انتهى حرّه. ⁕ حدثنا ابن بشار، قال: ثنا أبو عاصم، قال: ثنا شبيب، عن بشر، عن عكرِمة، عن ابن عباس ﴿يَطُوفُونَ بَيْنَهَا وَبَيْنَ حَمِيمٍ آنٍ﴾ قال: الآني: ما اشتدّ غليانه ونضجه. ⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: أخبرنا عبيد قال: سمعت الضحاك يقول في قوله: ﴿حَمِيمٍ آنٍ﴾ : هو الذي قد انتهى غَلْيه. ⁕ حدثنا ابن بشار، قال: ثنا محمد بن مروان، قال: ثنا أبو العوّام، عن قتادة ﴿وَبَيْنَ حَمِيمٍ آنٍ﴾ قال: أنى طبخها منذ يوم خلق الله السموات والأرض. ⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿يَطُوفُونَ بَيْنَهَا وَبَيْنَ حَمِيمٍ آنٍ﴾ يقول: حميم قد أنى طبخه منذ خلق الله السموات والأرض. ⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن الحسن ﴿حَمِيمٍ آنٍ﴾ يقول: حميم قد آن منتهى حره. ⁕ حدثنا ابن حُميد، قال: ثنا مهران، عن سفيان ﴿حَمِيمٍ آنٍ﴾ قال: قد انتهى حرّه. وقال بعضهم: عنى بالآني: الحاضر. ذكر من قال ذلك: ⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال، قال ابن زيد، في قوله: ﴿يَطُوفُونَ بَيْنَهَا وَبَيْنَ حَمِيمٍ آنٍ﴾ قال: يطوفون بينها وبين حميم حاضر، الآني:الحاضر. * * وقوله: ﴿فَبِأَيِّ آلاءِ رَبِّكُمَا تُكَذِّبَانِ﴾ يقول: فبأيّ نعم ربكما معشر الجنّ والإنس التي أنعمها عليكم -بعقوبته أهل الكفر به، وتكريمه أهل الإيمان به - تكذّبان.',     source_page = '321',     updated_at  = datetime('now') WHERE id = 'QR:TE:549e1d9fc8b329d393d32240';
UPDATE qr_tafsir_entries SET content_ar = 'مكية، وآياتها 4 «نزلت بعد التين» بِسْمِ اللَّهِ الرَّحْمنِ الرَّحِيمِ لِإِيلافِ قُرَيْشٍ متعلق بقوله لْيَعْبُدُوا أمرهم أن يعبدوه لأجل إيلافهم الرحلتين فإن قلت: فلم دخلت الفاء؟ قلت: لما في الكلام من معنى الشرط لأن المعنى: إما لا فليعبدوه لإيلافهم، على معنى: أنّ نعم الله عليهم لا تحصى، فإن لم يعبدوه لسائر نعمه، فليعبدوه لهذه الواحدة التي هي نعمة ظاهرة. وقيل المعنى: عجبوا لإيلاف قريش. وقيل: هو متعلق بما قبله، أى: فجعلهم كعصف مأكول لإيلاف قريش، وهذا بمنزلة التضمين في الشعر: وهو أن يتعلق معنى البيت بالذي قبله تعلقا لا يصح إلا به، وهما في مصحف أبىّ سورة واحدة بلا فصل. وعن عمر: أنه قراهما في الثانية من صلاة المغرب، وقرأ في الأولى: والتين [[هكذا وقع في الثعلبي. وقال عمرو بن ميمون: صليت خلف عمر المغرب. فذكر الحديث. وكذا وصله عبد الرزاق وابن أبى شيبة من رواية أبى إسحاق عن عمرو بن ميمون قال «صلى بنا عمر المغرب. فقرأ في الأولى بالتين. وفي الثانية ألم تر ولإيلاف قريش» .]] . والمعنى أنه أهلك الحبشة الذين قصدوهم ليتسامع الناس بذلك، فيتهيبوهم زيادة تهيب، ويحترموهم فضل احترام، حتى ينتظم لهم الأمن في رحلتيهم، فلا يجترئ أحد عليهم. وكانت لقريش رحلتان: يرحلون في الشتاء إلى اليمن، وفي الصيف إلى الشام، فيمتارون ويتجرون، وكانوا في رحلتيهم آمنين لأنهم أهل حرم الله وولاة بيته، فلا يتعرّض لهم، والناس غيرهم يتخطفون ويغار عليهم. والإيلاف من قولك: آلفت المكان أولفه إيلافا: إذا ألفته، فأنا مؤلف. قال: من المؤلفات الرّهو غير الأوارك [[شددت إليك الرحل فوق شملة ... من المؤلفات الرهو غير الأوارك الشملة بالتشديد. والشملال والشميل: الخفيفة السريعة السير، أى: شددت الرحل فوق نافة سريعة السير ذاهبا إليك، وتلك الناقة من النوق المؤلفات المعتادات الرهو، أى: السير السهل المستقيم. ويروى: الزهو، بالزاي وهو سيرها بعد ورودها الماء. والأوارك: جمع آركة: المقيمات موضع الأراك، ترعاه. أو ترعى نبتا يقال له الحمض، أى: ليست كذلك يلي معلوفة ومكرمة السفر.]] وقرئ: لئلاف قريش، أى: لمؤالفة قريش. وقيل: يقال ألفته إلفا وإلافا. وقرأ أبو جعفر: لإلف قريش، وقد جمعهما من قال: زعمتم أنّ إخوتكم قريش ... لهم إلف وليس لكم إلاف [[زعمتم أن إخوتكم قريش ... لهم إلف وليس لكم إلاف أولئك أومنوا جوعا وخوفا ... وقد جاعت بنو أسد وخافوا لمساور بن هند بن قيس يخاطب بنى أسد. وقريش خبر. وقولهم «لهم إلف» استئناف لبيان كذبهم. والالف والالاف: مصدر ألفه، إذا أحبه واعتاده ولم ينفر منه. وآلف إيلافا بينهما: جعل بينهما إلفا. وقد جمعت قريش بين رحلة الشتاء والصيف، فتارة فرحل هذه وتارة هذه بلا خوف ولا فزع «أولئك» إشارة لقريش «أومنوا» مبنى للمجهول، أى آمنهم ربهم عن الجوع والخوف، وقد جاعت وخافت بنو أسد: التفت إلى الغيبة دلالة على الاعراض عنهم، وتعجيب غيرهم من شأنهم.]] وقرأ عكرمة: ليألف قريش إلفهم رحلة الشتاء والصيف. وقريش: ولد النضر بن كنانة سموا بتصغير القرش: وهو دابة عظيمة في البحر تعبث بالسفن، ولا تطاق إلا بالنار. وعن معاوية أنه سأل ابن عباس رضى الله عنهما: بم سميت قريش؟ قال: بدابة في البحر تأكل ولا تؤكل، وتعلو ولا تعلى. وأنشد: وقريش هي الّتي تسكن البحر ... بها سمّيت قريش قريشا [[وقريش هي التي تسكن البحر ... بها سميت قريش قريشا تأكل الغث والسمين ولا تترك ... يوما لذي جناحين ريشا هكذا في الكتاب نالت قريش ... يأكلون البلاد أكلا كشيشا ولهم آخر الزمان نبى ... يكثر القتل فيهم والخموشا يملأ الأرض خيلة ورجالا ... يحشرون المطر حشرا كميشا لتبع. وقريش: تصغير قرش. قال ابن عباس: اسم دابة في البحر تأكل ولا تؤكل اه فصغر وسمي به النضر بن كنانة، ثم سمى به أولاده. والمحدثون على أنه اسم لفهر بن مالك بن النضر، وقال الروافض: هو اسم لقصي بن كلاب، وتوصلوا بذلك إلى نفى إمامة أبى بكر وعمر لكونهما ليسا قرشيين، لأنهما يجتمعان معه ﷺ بعد قصي، والامامة من قريش، وقريش مبتدأ، والجملة بعدها مستأنفة مبينة لها، وبها سميت خبر، أى: بسببها، سميت هذه القبيلة قريشا تأكل، أى قريش البحرية. ويؤيده ما روى قبل هذا البيت وهو: سلطت بالعلو في لجة البحر ... على سائر البحور جيوشا ... تأكل ويحتمل أنها الضبيلة. والغث الخبيث. والسمين، الطيب وصاحب الجناحين، كناية عن الطير. أو استعارة الغنى، وبالغ في أنها لا تبقى ولا تذر شيئا مما تظفر به بقوله: إنها لا تترك ريش ذى الجناحين. ويروى «فيه» بدل يوما وهو يعنى قريش البحرية. وهكذا: إشارة لحال دابة البحر، أو لما قاله هو. والكتاب: التوراة أو الإنجيل. أو كتب التاريخ. وقريش هنا: القبيلة، ويروى: هكذا في البلاد حى قريش ... يأكلون البلاد...... أى: يأخذون أموالها. والكشيش في الأصل: الصوت الخفي، أى: أكلا بسهولة، بلا إرهاب ولا إنعاب، فهو مجاز، والنبي محمد ﷺ. وخمشه خمشا: خدشه. والخموش: الخدوش. والخيلة: الشبح البعيد. والخيل: الخيالة. والرجال: المشاة على أرجلهم. ويحشرون: صفة لرجال، ويبعد رجوعه لقريش، والكميش: السريع. والمنضم: القاطع، أى: يجمعونها بسرعة، لكن المراد بالخموش هنا: الجروح.]] والتصغير للتعظيم. وقيل: من القرش وهو الكسب: لأنهم كانوا كسابين بتجاراتهم وضربهم في البلاد. أطلق الإيلاف ثم أبدل عنه المقيد بالرحلتين، تفخيما لأمر الإيلاف، وتذكيرا بعظيم النعمة فيه، ونصب الرحلة بإيلافهم مفعولا به، كما نصب يَتِيماً بإطعام، وأراد رحلتي الشتاء والصيف، فأفرد لأمن الإلباس، كقوله. كلوا في بعض بطنكم.... [[قوله «كلوا في بعض بطنكم» بقيته: «تعفوا» وقد تقدم شرح هذا الشاهد بالجزء الأول فراجعه إن شئت اه مصححه. (ع)]] .. وقرئ: رحلة، بالضم: وهي الجهة التي يرحل إليها: والتنكير في جُوعٍ وخَوْفٍ لشدتهما، يعنى: أطعمهم بالرحلتين من جوع شديد كانوا فيه قبلهما، وآمنهم من خوف عظيم وهو خوف أصحاب الفيل، أو خوف التخطف في بلدهم ومسايرهم. وقيل: كانوا قد أصابتهم شدة حتى أكلوا الجيف والعظام المحرقة، وآمنهم من خوف الجذام فلا يصيبهم ببلدهم. وقيل ذلك كله بدعاء إبراهيم صلوات الله عليه. ومن بدع التفاسير: وآمنهم من خوف، من أن تكون الخلافة في غيرهم. وقرئ: من خوف، بإخفاء النون. عن رسول الله ﷺ: «من قرأ سورة لإيلاف قريش أعطاه الله عشر حسنات بعدد من طاف بالكعبة واعتكف بها» [[أخرجه الثعلبي والواحدي وابن مردويه بالسند إلى أبى بن كعب.]] .',     source_page = '479',     updated_at  = datetime('now') WHERE id = 'QR:TE:21156c48d2a7c81b78a75b3c';
UPDATE qr_tafsir_entries SET content_ar = 'مكية، وقيل مدنية، وآياتها 4 «نزلت بعد الناس» بِسْمِ اللَّهِ الرَّحْمنِ الرَّحِيمِ هُوَ ضمير الشأن، واللَّهُ أَحَدٌ هو الشأن، كقولك: هو زيد منطلق، كأنه قيل: الشأن هذا، وهو أنّ الله واحد لا ثانى له. فإن قلت: ما محل هو؟ قلت: الرفع على الابتداء والخبر الجملة. فإن قلت: فالجملة الواقعة خبرا لا بد فيها من راجع إلى المبتدإ، فأين الراجع؟ قلت: حكم هذه الجملة حكم المفرد في قولك «زيد غلامك» في أنه هو المبتدأ في المعنى، وذلك أن قوله اللَّهُ أَحَدٌ هو الشأن الذي هو عبارة عنه، وليس كذلك «زيد أبوه منطلق» فإنّ زيدا والجملة يدلان على معنيين مختلفين، فلا بد مما يصل بينهما. وعن ابن عباس: قالت قريش: يا محمد، صف لنا ربك الذي تدعونا إليه، فنزلت: يعنى: الذي سألتمونى وصفه هو الله، وأحد: بدل من قوله، الله. أو على: هو أحد، وهو بمعنى واحد، وأصله وحد. وقرأ عبد الله وأبىّ: هو الله أحد، بغير قُلْ وفي قراءة النبي ﷺ: الله أحد، بغير قُلْ هُوَ وقال من قرأ: الله أحد، كان بعدل القرآن. وقرأ الأعمش: قل هو الله الواحد. وقرئ: أحد الله، بغير تنوين: أسقط لملاقاته لام التعريف. ونحوه ولا ذاكر الله إلّا قليلا [[تقدم شرح هذا الشاهد بالجزء الأول فراجعه إن شئت اه مصححه.]] والجيد هو التنوين، وكسره لالتقاء الساكنين. والصَّمَدُ فعل بمعنى مفعول، من صمد إليه إذا قصده، وهو السيد المصمود إليه في الحوائج. والمعنى: هو الله الذي تعرفونه وتقرّون بأنه خالق السماوات والأرض وخالقكم، وهو واحد متوحد بالإلهية لا يشارك فيها، وهو الذي يصمد إليه كل مخلوق لا يستغنون عنه، وهو الغنى عنهم لَمْ يَلِدْ لأنه لا يجانس، حتى تكون له من جنسه صاحبة فيتوالدا. وقد دل على هذا المعنى بقوله أَنَّى يَكُونُ لَهُ وَلَدٌ وَلَمْ تَكُنْ لَهُ صاحِبَةٌ. وَلَمْ يُولَدْ لأنّ كل مولود محدث وجسم، وهو قديم لا أوّل لوجوده وليس يجسم ولم يكافئه أحد، أى: لم يماثله ولم يشاكله. ويجوز أن يكون من الكفاءة في النكاح، نفيا للصاحبة: سألوه أن يصفه لهم، فأوحى إليه ما يحتوى على صفاته، فقوله هُوَ اللَّهُ إشارة لهم إلى من هو خالق الأشياء وفاطرها، وفي طىّ ذلك وصفه بأنه قادر عالم، لأن الخلق يستدعى القدرة والعلم، لكونه واقعا على غاية إحكام واتساق وانتظام. وفي ذلك وصفه بأنه حى سميع بصير. وقوله أَحَدٌ وصف بالوحدانية ونفى الشركاء. وقوله الصَّمَدُ وصف بأنه ليس إلا محتاجا إليه، وإذا لم يكن إلا محتاجا إليه: فهو غنى. وفي كونه غنيا مع كونه عالما: أنه عدل غير فاعل للقبائح [[قوله «إنه عدل غير فاعل للقبائح» هذا مذهب المعتزلة، وذهب أهل السنة إلى أنه تعالى هو الخالق لجميع الأشياء خيرها وشرها قبيحها وحسنها. قال تعالى: اللَّهُ خالِقُ كُلِّ شَيْءٍ وعلمه بقبح القبيح لا يمنعه من خلقه، لأنه لحكمة وإن لم يعلمها غيره. (ع)]] ، لعلمه بقبح القبيح وعلمه بغناه عنه. وقوله لَمْ يُولَدْ وصف بالقدم والأوّلية. وقوله لَمْ يَلِدْ نفى للشبه والمجانسة. وقوله وَلَمْ يَكُنْ لَهُ كُفُواً أَحَدٌ تقرير لذلك وبت للحكم به: فإن قلت: الكلام العربي الفصيح أن يؤخر الظرف الذي هو لغو غير مستقر ولا يقدم، وقد نص سيبويه على ذلك في كتابه [[قال محمود: «إن قلت الكلام العربي الفصيح أن يؤخر الظرف وقد نص سيبويه على ذلك» قال أحمد: نقل سيبويه أنه سمع بعض الجفاة من العرب يقرأ: ولم يكن أحدا كفوا له، وجرى هذا الجلف على عادته فجفا طبعه عن لطف المعنى الذي لأجله اقتضى تقديم الظرف مع الخبر على الاسم، وذلك أن الغرض الذي سيقت له الآية نفى المكافأة والمساواة عن ذات الله تعالى، فكان تقديم المكافأة المقصود بأن يسلب عنه أولى، ثم لما قدمت لتسلب ذكر معها الظرف ليبين الذات المقدسة بسلب المكافأة، والله أعلم.]] ، فما باله مقدّما في أفصح كلام وأعربه؟ قلت هذا الكلام إنما سيق لنفى المكافأة عن ذات الباري سبحانه، وهذا المعنى مصبه ومركزه هو هذا الظرف، فكان لذلك أهم شيء وأعناه، وأحقه بالتقدم وأحراه. وقرئ: كفؤا، بضم الكاف والفاء. وبضم الكاف وكسرها مع سكون الفاء: فإن قلت. لم كانت هذه السورة عدل القرآن كله على قصر متنها وتقارب طرفيها؟ قلت: لأمر ما يسود من يسود، وما ذاك إلا لاحتوائها على صفات الله تعالى وعدله وتوحيده، وكفى دليلا من اعترف بفضلها وصدق بقول رسول الله ﷺ فيها: إنّ علم التوحيد من الله تعالى بمكان، وكيف لا يكون كذلك والعلم تابع للمعلوم: يشرف بشرفه، ويتضع بضعه، ومعلوم هذا العلم هو الله تعالى وصفاته، وما يجوز عليه وما لا يجوز، فما ظنك بشرف منزلته وجلالة محله، وإنافته على كل علم، واستيلائه على قصب السبق دونه، ومن ازدراه فلضعف علمه بمعلومه، وقلة تعظيمه له، وخلوه من خشيته، وبعده من النظر لعاقبته. اللهم احشرنا في زمرة العالمين بك العاملين لك، القائلين بعدلك وتوحيدك، الخائفين من وعيدك. وتسمى سورة الأساس لاشتمالها على أصول الدين. وروى أبىّ وأنس عن النبي ﷺ: «أسست السماوات السبع والأرضون السبع على قل هو الله أحد» [[لم أجده مرفوعا «وأخرجه ابن أبى شيبة في فضائل القرآن من رواية عبد الله بن غيلان الثقفي عن العب الأحبار موقوفا.]] يعنى ما خلقت إلا لتكون دلائل على توحيد الله ومعرفة صفاته التي نطقت بها هذه السورة. عن رسول الله ﷺ أنه سمع رجلا يقرأ قل هو الله أحد فقال: «وجبت» . قيل: يا رسول الله وما وجبت؟ قال: «وجبت له الجنة» [[أخرجه الترمذي والنسائي والحاكم من حديث عبيد بن حنين عن أبى هريرة. وله شاهد في الطبراني الكبير من حديث أبى أمامة.]]',     source_page = '448',     updated_at  = datetime('now') WHERE id = 'QR:TE:8c8e454efe0c50aae13798a8';
UPDATE qr_tafsir_entries SET content_ar = 'ذلِكَ إشارة إلى ما قص الله من قصص الأمم الهالكة بذنوبهم لَآيَةً لِمَنْ خافَ لعبرة له، لأنه ينظر إلى ما أحل الله بالمجرمين في الدنيا، وما هو إلا أنموذج مما أعدّ لهم في الآخرة، فإذا رأى عظمه وشدّته اعتبر به عظم العذاب الموعود، فيكون له عبرة وعظة ولطفاً في زيادة التقوى والخشية من الله تعالى. ونحوه إِنَّ فِي ذلِكَ لَعِبْرَةً لِمَنْ يَخْشى. ذلِكَ إشارة إلى يوم القيامة، لأنّ عذاب الآخرة دلّ عليه. والنَّاسُ رفع باسم المفعول [[قال محمود: «إن قلت لم عدل عن الفعل إلى اسم المفعول ... الخ» قال أحمد: ولهذا السر ورد قوله تعالى إِنَّا سَخَّرْنَا الْجِبالَ مَعَهُ يُسَبِّحْنَ بِالْعَشِيِّ وَالْإِشْراقِ، وَالطَّيْرَ مَحْشُورَةً فاستعمل الفعل حيث يليق به، واسم المفعول حيث يحسن استعماله أيضا ... الخ.]] الذي هو مجموع كما يرفع بفعله إذا قلت يجمع له الناس. فإن قلت: لأى فائدة أوثر اسم المفعول على فعله؟ [[قوله «من دلالة» عبارة النسفي: دلالته. (ع)]] قلت: لما في اسم المفعول من دلالة على ثبات معنى الجمع لليوم وأنه يوم لا بدّ من أن يكون ميعاداً مضروباً لجمع الناس له، وأنه الموصوف بذلك صفة لازمة، وهو أثبت أيضاً لإسناد الجمع إلى الناس، وأنهم لا ينفكون منه، ونظيره قول المتهدد: إنك لمنهوب مالك محروب قومك، فيه من تمكن الوصف وثباته ما ليس في الفعل، وإن شئت فوازن بينه وبين قوله يَوْمَ يَجْمَعُكُمْ لِيَوْمِ الْجَمْعِ تعثر على صحة ما قلت لك. ومعنى يجمعون له: يجمعون لما فيه من الحساب والثواب والعقاب يَوْمٌ مَشْهُودٌ مشهود فيه، فاتسع في الظرف [[قال محمود: «المراد مشهود فيه فاتسع في الظرف ... الخ» قال أحمد: يكون المشهود الذي هو المفعول به مسكونا عنه مبهما، ومن الإبهام ما يكون تفخيما، وهذا مكانه.]] بإجرائه مجرى المفعول به، كقوله: وَيَوْمٍ شَهِدْنَاهُ سُلَيْما وَعَامِراً [[تقدم شرح هذا الشاهد بهذا الجزء فراجعه إن شئت اه مصححه.]] أى يشهد فيه الخلائق الموقف لا يغيب عنه أحد. والمراد بالمشهود: الذي كثر شاهدوه. ومنه قولهم: لفلان مجلس مشهود، وطعام محضور. قال: فِى مَحْفِلٍ مِنْ نَوَاصِى النَّاسِ مَشْهُودِ [[من الخصوم إذا حد الضجاج بهم ... بعد ابن سعد ومن الضمر القود ومشهد قد كفيت الغائبين به ... في محفل من نواصي القوم مشهود فرجته بلسان غير ملتبس ... عند الحفاظ وقلب غير مزؤد لأم قيس الضبية. وضج ضجيجاً وضجاجا: صاح. وضج البعير من الحمل: تعب من ثقله، والضمر بالتشديد: جمع ضامر. وفرس أقود: طويل العنق. ورجل أقود: يقبل بوجهه ولا ينثني. والقرد: جمعه. ومشهد: عطف على الخصوم. ويجوز جره برب، أى مجلس كفيت فيه الغائبين عنه بالتكلم عنهم بين محفل من رؤساء الناس وأشرافهم، فالنواصى: استعارة لهم. وفرجته، فككت كربته، وكشفت غمته بكلام واضح الدلالة صادر عن قلب مطمئن غير خائف عند الحفاظ، أى غيرة الخصوم ومحافظة كل منهم على رأيه أو المغاضبة. ويقال: أحفظه إحفاظاً إذا أغضبه.]] فإن قلت: فما منعك أن تجعل اليوم مشهوداً في نفسه دون أن تجعله مشهوداً فيه، كما قال الله تعالى فَمَنْ شَهِدَ مِنْكُمُ الشَّهْرَ فَلْيَصُمْهُ؟ قلت: الغرض وصف ذلك اليوم بالهول والعظم وتميزه من بين الأيام، فإن جعلته مشهوداً في نفسه فسائر الأيام كذلك مشهودات كلها، ولكن يجعل مشهوداً فيه حتى يحصل التميز كما تميز يوم الجمعة عن أيام الأسبوع بكونه مشهوداً فيه دونها، ولم يجز أن يكون مشهوداً في نفسه، لأنّ سائر أيام الأسبوع مثله يشهدها كل من يشهده، وكذلك قوله: فَمَنْ شَهِدَ مِنْكُمُ الشَّهْرَ فَلْيَصُمْهُ الشهر منتصب ظرفاً لا مفعولا به، وكذلك الضمير في فَلْيَصُمْهُ والمعنى: فمن شهد منكم في الشهر فليصم فيه، يعنى: فمن كان منكم مقيما حاضراً لوطنه في شهر رمضان فليصم فيه، ولو نصبته مفعولا فالمسافر والمقيم كلاهما يشهدان الشهر، لا يشهده المقيم، ويغيب عنه المسافر:',     source_page = '408',     updated_at  = datetime('now') WHERE id = 'QR:TE:3ccb91ac43686883c9180cce';
UPDATE qr_tafsir_entries SET content_ar = 'نُوَفِّ إِلَيْهِمْ نوصل إليهم أجور أعمالهم وافية كاملة من غير بخس في الدنيا، وهو ما يرزقون فيها من الصحة والرزق. وقيل: هم أهل الرياء. يقال للقراء منهم: أردت أن يقال: فلان قارئ، فقد قيل ذلك. ولمن وصل الرحمن وتصدّق: فعلت حتى يقال، فقيل. ولمن قاتل فقتل: قاتلت حتى يقال فلان جريء، فقد قيل: وعن أنس بن مالك: هم اليهود والنصارى، إن أعطوا سائلا أو وصلوا رحماً، عجل لهم جزاء ذلك بتوسعة في الرزق وصحة في البدن. وقيل: هم الذين جاهدوا من المنافقين مع رسول الله ﷺ فأسهم لهم في الغنائم. وقرئ: يوفّ، بالياء على أن الفعل لله عزّ وجلّ. وتوفَّ إليهم أعمالهم بالتاء، على البناء للمفعول. وفي قراءة الحسن: نوفى، بالتخفيف وإثبات الياء، لأنّ الشرط وقع ماضياً، كقوله: يَقُولُ لَا غائِبٌ مَالِى وَلَا حَرِمُ [[مر شرح هذا الشاهد بالجزء الأول فراجعه إن شئت. اه مصححه.]] وَحَبِطَ ما صَنَعُوا فِيها وحبط في الآخرة ما صنعوه، أو صنيعهم، يعنى: لم يكن له ثواب لأنهم لم يريدوا به الآخرة، إنما أرادوا به الدنيا، وقد وفي إليهم ما أرادوا وَباطِلٌ ما كانُوا يَعْمَلُونَ أى كان عملهم في نفسه باطلا، لأنه لم يعمل لوجه صحيح، والعمل الباطل لا ثواب له. وقرئ: وبطل على الفعل. وعن عاصم: وباطلا بالنصب، وفيه وجهان: أن تكون ما إبهامية وينتصب بيعملون، ومعناه: وباطلا، أىّ باطل كانوا يعملون. وأن تكون بمعنى المصدر على: وبطل بطلاناً ما كانوا يعملون.',     source_page = '537',     updated_at  = datetime('now') WHERE id = 'QR:TE:bcf9970180795cc94535adc1';
UPDATE qr_tafsir_entries SET content_ar = 'نداؤه ربه: دعاؤه له، وهو قوله رَبِّ مع ما بعده من اقتضاء وعده في تنجية أهله. فإن قلت: فإذا كان النداء هو قوله رَبِّ فكيف عطف فَقالَ رَبِّ على نادى بالفاء؟ قلت: أريد بالنداء إرادة النداء، ولو أريد النداء نفسه لجاء، كما جاء قوله إِذْ نادى رَبَّهُ نِداءً خَفِيًّا قالَ رَبِّ بغير فاء إِنَّ ابْنِي مِنْ أَهْلِي أى بعض أهلى، لأنه كان ابنه من صلبه، أو كان ربيبا له فهو بعض أهله وَإِنَّ وَعْدَكَ الْحَقُّ وأن كل وعد تعده فهو الحق الثابت الذي لا شك في إنجازه والوفاء به، وقد وعدتني أن تنجي أهلى، فما بال ولدى؟ وَأَنْتَ أَحْكَمُ الْحاكِمِينَ أى أعلم الحكام وأعدلهم [[قال محمود: «قال أى أعلم الحكام وأعدلهم، لأنه لا فضل لحاكم على غيره إلا بالعلم ... الخ» قال أحمد: ثم حدث بعد الزمخشري ترفع عن أقضى القضاة إلى قاضى القضاة، والذي تلاحظوا به في ارتفاع هذه الثانية على الأولى: أن الأولى تقتضي مشاركة القضاة لأقضاهم في الوصف، وأن يزاد عليهم، فترفعوا أن يشركهم أحد في وصفهم ممن دونهم في المنصب، فعدلوا عما يشاركه فيه إلى ما ليس كذلك، فأفردوا رئيسهم بتلقيبه بقاضى القضاة: أى هو الذي يقضى بين القضاة ولا يشاركهم منهم أحد في وصفه، وجعلوا الذي يليه في الرتبة أقضى القضاة إلا أنهم إنما يعنون قاضى قضاة زمانه أو إقليمه. وإذا جاز أن يطلق على أمير المؤمنين على بن أبى طالب كرم الله وجهه أقضى قضاة الصحابة في زمانه كما أطلقه عليه النبي عليه الصلاة والسلام حيث قال «أقضاكم على» فدخل في المخاطبين القضاة وغيرهم، فلا حرج إن شاء الله أن يطلق على أعدل قضاة الزمان أو الإقليم وأعلمهم: قاضى القضاة، وأقضى القضاة، أى قضاة زمانه وبلده، وكل قرن ناجم في زمن فهو شبيه زمن فيه بدا هذا اللقب.]] ، لأنه لا فضل لحاكم على غيره إلا بالعلم والعدل. ورب غريق في الجهل والجور من متقلدي الحكومة في زمانك قد لقب أقضى القضاة، ومعناه أحكم الحاكمين فاعتبر واستعبر. ويجوز أن يكون من الحكمة، على أن يبنى من الحكمة حاكم بمعنى النسبة كما قيل دارع من الدرع، وحائض وطالق على مذهب الخليل إِنَّهُ عَمَلٌ غَيْرُ صالِحٍ تعليل لانتفاء كونه من أهله. وفيه إيذان بأن قرابة الدين غامرة لقرابة النسب، وأنّ نسيبك في دينك ومعتقدك من الأباعد في المنصب [[قوله «من الأباعد في المنصب» لعله تحريف، وأصله في النسب. (ع)]] وإن كان حبشياً وكنت قرشياً لصيقك وخصيصك. ومن لم يكن على دينك- وإن كان أمس أقاربك رحماً- فهو أبعد بعيد منك، وجعلت ذاته عملا غير صالح، مبالغة في ذمّه، كقولها: فَإنَّمَا هِىَ إقْبَالٌ وَإدْبَارُ [[مر شرح هذا الشاهد بالجزء الأول فراجعه إن شئت اه مصححه.]] وقيل: الضمير لنداء نوح، أى: إنّ نداءك هذا عمل غير صالح وليس بذاك- فإن قلت: فهلا قيل: إنه عمل فاسد [[قال محمود: «فهلا قيل: إنه عمل فاسد قلت لما نفاه عن أهله نفى عنه ... الخ» قال أحمد. ولهذا المعنى والله أعلم قيل له عليه الصلاة والسلام وَأَنْذِرْ عَشِيرَتَكَ الْأَقْرَبِينَ وإن كان مأموراً بالإنذار على العموم، ولكن لما كانت أهلية النبي عليه الصلاة والسلام مظنة الاتكال والفتور عن العمل، خص أهله بالإنذار إيذانا بذلك، والله أعلم. ولهذا لما نزلت أنذرهم النبي ﷺ وقال: إنى لا أملك لكم من الله شيئاً، أو قال ذلك ولكل واحد منهم بخصوصه.]] ؟ قلت: لما نفاه عن أهله، نفى عنه صفتهم بكلمة النفي التي يستبقى معها لفظ المنفي، وآذن بذلك أنه إنما أنجى من أنجى من أهله لصلاحهم، لا لأنهم أهلك وأقاربك. وإنّ هذا لما انتفى عنه الصلاح لم تنفعه أبوّتك، كقوله كانَتا تَحْتَ عَبْدَيْنِ مِنْ عِبادِنا صالِحَيْنِ فَخانَتاهُما فَلَمْ يُغْنِيا عَنْهُما مِنَ اللَّهِ شَيْئاً وقرئ: عمل غير صالح أى عمل عملا غير صالح. وقرئ: فلا تسئلنّ، بكسر النون بغير ياء الإضافة وبالنون الثقيلة بياء وبغير ياء، يعنى فلا تلتمس منى ملتمساً أو التماساً لا تعلم أصواب هو أم غير صواب، حتى تقف على كنهه. وذكر المسألة دليل على أنّ النداء كان قبل أن يغرق حين خاف عليه. فإن قلت: لم سمى نداؤه سؤالا ولا سؤال فيه؟ قلت: قد تضمن دعاؤه معنى السؤال وإن لم يصرح به، لأنه إذا ذكر الموعد بنجاة أهله في وقت مشارفة ولده الغرق فقد استنجز. وجعل سؤال ما لا يعرف كنهه جهلا وغباوة، ووعظه أن لا يعود إليه وإلى أمثاله من أفعال الجاهلين. فإن قلت: قد وعده أن ينجى أهله، وما كان عنده [[قال محمود: «فان قلت قد وعده الله أن ينجي أهله وما كان عنده ... الخ» قال أحمد: وفي كلام الزمخشري ما يدل على أنه يعتقد أن نوحا عليه السلام صدر منه ما أوجب نسبة الجهل إليه ومعاتبته على ذلك، وليس الأمر كما تخيله الزمخشري، ونحن نوضح الحق في الآية منزلا على نصها مع تنزيه نوح عليه السلام مما توهم الزمخشري نسبته إليه فنقول: لما وعد نوح أولا تنجية أهله إلا من سبق عليه القول منهم ولم يكن كاشفا لحال ابنه المذكور ولا مطلعاً على باطن أمره بل معتقداً بظاهر الحال أنه مؤمن، بقي على التمسك بصيغة العموم للأهلية الثابتة ولم يعارضها يقين في كفر ابنه حتى يخرج من الأهل ويدخل في المستثنين، فسأل الله فيه بناء على ذلك، فتبين له أنه في علمه من المستثنين، وأنه هو لا علم له بذلك، فلذلك سأل فيه، وهذا بأن يكون إبانة عذر أولى منه أن يكون عتباً، فان نوحا عليه السلام لا يكلفه الله علما استأثر به غيبا. وأما قوله إِنِّي أَعِظُكَ أَنْ تَكُونَ مِنَ الْجاهِلِينَ فالمراد منه النهى عن وقوع السؤال في المستقبل بعد أن أعلمه الله باطن أمره، وأنه إن وقع في المستقبل في السؤال كان من الجاهلين. والغرض من ذلك تقديم ما يبقيه عليه السلام على سمة العصمة، والموعظة لا تستدعي وقوع ذنب، بل المقصد منها أن لا يقع الذنب في الاستقبال، ولذلك مثل عليه الصلاة والسلام ذلك، واستعاذ بالله أن يقع منه ما نهى عنه والله أعلم.]] أن ابنه ليس منهم ديناً، فلما أشفى على الغرق تشابه عليه الأمر، لأن العدة قد سبقت له وقد عرف الله حكيما لا يجوز عليه فعل القبيح وخلف الميعاد، فطلب إماطة الشبهة وطلبُ إماطة الشبهة واجب، فلم زجر وسمى سؤاله جهلا؟ قلت: إن الله عز وعلا قدّم له الوعد بإنجاء أهله مع استثناء من سبق عليه القول منهم، فكان عليه أن يعتقد أن في جملة أهله من هو مستوجب للعذاب لكونه غير صالح، وأن كلهم ليسوا بناجين، وأن لا تخالجه شبهة حين شارف ولده الغرق في أنه من المستثنين لا من المستثنى منهم، فعوتب على أن اشتبه عليه ما يجب أن لا يشتبه.',     source_page = '218',     updated_at  = datetime('now') WHERE id = 'QR:TE:1c5a9698fb60aff25f104f2f';
UPDATE qr_tafsir_entries SET content_ar = 'رُسُلُنا يريد الملائكة. عن ابن عباس: جاءه جبريل عليه السلام وملكان معه. وقيل: جبريل وميكائيل وإسرافيل. وقيل: كانوا تسعة. وعن السدى: أحد عشر بِالْبُشْرى هي البشارة بالولد. وقيل: بهلاك قوم لوط، والظاهر الولد سَلاماً سلمنا عليك سلاما سَلامٌ أمركم سلام. وقرئ: فقالوا سلما قال سلم، بمعنى السلام. وقيل: سلم وسلام، كحرم وحرام، وأنشد: مَرَرْنَا فَقُلْنَا إيِه سِلْمٌ فَسَلَّمَتْ ... كَمَا اكْتَلَّ بِالبَرْقِ الْغَمَامُ اللَّوَائِحُ [[لذي الرمة غيلان بن عقبة، يقول: مررنا بديار المحبوبة مىّ، فقلنا إيه، أى حدثى واستأنسى، فأسرنا سلم، أى سلامة وأنس، فسلمت علينا ولمعت ثناياها وغابت بسرعة، كما لمع الغمام بلمعان البرق. وغاب البرق بسرعة. واكتل اكتلالا: لمع لمعانا واللوائح الظواهر: صفة الغمام، لتعدده معنى.]] فَما لَبِثَ أَنْ جاءَ فما لبث في المجيء به، بل عجل فيه. أو فما لبث مجيئه. والعجل: ولد البقرة، ويسعى الحسيل والخبش بلغة أهل السراة، وكان مال إبراهيم عليه الصلاة والسلام البقر حَنِيذٍ مشوىّ بالرضف [[قوله «مشوى بالرضف» أى الحجارة المحماة، كما في الصحاح. (ع)]] في أخدود. وقيل حَنِيذٍ يقطر دسمه، من حنذت الفرس إذا ألقيت عليها الجل حتى تقطر عرقا، ويدل عليه بِعِجْلٍ سَمِينٍ. يقال: نكره وأنكره واستنكره، ومنكور قليل في كلامهم، وكذلك: أنا أنكرك، ولكن منكر ومستنكر، وأنكرك. قال الأعشى: وَأَنْكَرَتْنِى وَمَا كَانَ الَّذِى نَكِرَتْ ... مِنَ الْحَوَادِثِ إلّا الشَّيْبَ وَالصَّلَعَا [[للأعشى. ويقال: أنكره ونكره: جهله ونفر منه: أى جهلتنى المحبوبة، وما كان الذي أنكرته من الحوادث إلا الشيب والصلع وهو انحسار شعر الرأس. وقيل: إن أبا عبيدة سمع بشارا ينكر نسبة هذا البيت للأعشى ويقول: إنه مصنوع عليه لا يشبه كلامه، فتعجب أبو عبيدة من فطنته، كأنه صح عنده إنكاره.]] قيل: كان ينزل في طرف من الأرض فخاف أن يريدوا به مكروها [[قال محمود: «قيل إنه كان ينزل في طرف من الأرض فخاف أن يريدوا به مكروها ... الخ» قال أحمد: وقد وردت قصة إبراهيم هذه في ثلاثة مواضع: هذا أحدها، وهو دال على أنه إنما أوجس منهم خيفة لعلمه أنهم ملائكة وعدم علمه فيم جاءوا. الثاني: في الحجر قوله وَنَبِّئْهُمْ عَنْ ضَيْفِ إِبْراهِيمَ إلى قوله لا تَوْجَلْ إِنَّا نُبَشِّرُكَ فلم يطمئنوا بإعلامه أنهم ملائكة، ولكن بأنهم يبشرون له، فدل على استشعارهم أنه علم كونهم ملائكة ووجل مما جاءوا فيه. الثالث: في الذاريات فَأَوْجَسَ مِنْهُمْ خِيفَةً قالُوا لا تَخَفْ وَبَشَّرُوهُ فهو أيضا كذلك. وأما لوط فلم يشعر أنهم ملائكة حتى أعلموه بذلك. ألا ترى إلى قوله تعالى قالُوا يا لُوطُ إِنَّا رُسُلُ رَبِّكَ لَنْ يَصِلُوا إِلَيْكَ فأول ما أعلموا به أنهم رسل، فالفرق بين هذه الآية وبين آي إبراهيم، مصداق لأن إبراهيم علم كونهم ملائكة ولوطا لم يعلم ذلك، ولا يبعد من فضل إبراهيم على لوط أن يبعد على فراسته أن يعلم أنهم ملائكة دون لوط عليهما السلام.]] . وقيل: كانت عادتهم أنه إذا مسّ من يطرقهم طعامهم أمنوه وإلا خافوه، والظاهر أنه أحسّ بأنهم ملائكة، ونكرهم لأنه تخوّف أن يكون نزولهم لأمر أنكره الله عليه أو لتعذيب قومه، ألا ترى إلى قولهم لا تَخَفْ إِنَّا أُرْسِلْنا إِلى قَوْمِ لُوطٍ وإنما يقال هذا لمن عرفهم ولم يعرف فيهم أرسلوا وَأَوْجَسَ فأضمر [[عاد كلامه. قال: «ومعنى أوجس أضمر وإنما قالوا لا تخف لأنهم رأوا أثر الخوف ... الخ» قال أحمد: وهذا التأويل وهم فيه الزمخشري والله أعلم، لأنهم إنما علموا خوفه ووجله باخباره إياهم بذلك، ويدل عليه قوله تعالى في آية أخرى قالَ إِنَّا مِنْكُمْ وَجِلُونَ قالُوا لا تَوْجَلْ والقصة واحدة، والله الموفق للصواب.]] . وإنما قالوا لا تَخَفْ لأنهم رأوا أثر الخوف والتغير في وجهه. أو عرفوه بتعريف الله. أو علموا أن علمه بأنهم ملائكة موجب للخوف، لأنهم كانوا لا ينزلون إلا بعذاب وَامْرَأَتُهُ قائِمَةٌ قيل: كانت قائمة وراء الستر تسمع تحاورهم. وقيل: كانت قائمة على رؤسهم تخدمهم. وفي مصحف عبد الله: وامرأته قائمة وهو قاعد فَضَحِكَتْ سروراً بزوال الخيفة [[عاد كلامه. قال: «وضحك زوجته لأنها سرت بذهاب الخيفة ... الخ» قال أحمد: ويبعد هذا التأويل أنها قالت بعد يا وَيْلَتى أَأَلِدُ وَأَنَا عَجُوزٌ وَهذا بَعْلِي شَيْخاً إِنَّ هذا لَشَيْءٌ عَجِيبٌ فلو كان حيضها قبل بشارتها لما تعجبت، إذ لا عجب في حمل من تحيض، والحيض في العادة مهماز على إمكان الحمل، والله الموفق.]] أو بهلاك أهل الخبائث. أو كان ضحكها ضحك إنكار لغفلتهم وقد أظلهم العذاب. وقيل: كانت تقول لإبراهيم: اضمم لوطاً ابن أخيك إليك فإنى أعلم أنه ينزل بهؤلاء القوم عذاب، فضحكت سروراً لما أتى الأمر على ما توهمت. وقيل ضحكت فحاضت. وقرأ محمد بن زياد الأعرابى فَضَحِكَتْ بفتح الحاء يَعْقُوبَ رفع بالابتداء، كأنه قيل: ومن وراء إسحاق يعقوب مولود أو موجود، أى من بعده. وقيل الوراء: ولد الولد، وعن الشعبي أنه قيل له: أهذا ابنك؟ فقال نعم، من الوراء، وكان ولد ولده. وقرئ يَعْقُوبَ بالنصب، كأنه قيل. ووهبنا لها إسحاق، ومن وراء إسحاق يعقوب، على طريقة قوله: ... لَيْسُوا مُصْلِحِينَ عَشِيرَةً ... وَلَا نَاعِبٍ [[تقدم شرح هذا الشاهد بالجزء الأول فراجعه إن شئت اه مصححه.]] ... الألف في يا وَيْلَتى مبدلة من ياء الإضافة، وكذلك في «يا لهفاً» و «يا عجباً» وقرأ الحسن: يا ويلتى، بالياء على الأصل. وشَيْخاً نصب بما دلّ عليه اسم الإشارة. وقرئ شيخ، على أنه خبر مبتدأ محذوف، أى: هذا بعلى هو شيخ. أو بعلى: بدل من المبتدأ، وشيخ: خبر، أو يكونان معاً خبرين. قيل: بشرت ولها ثمان وتسعون سنة، ولإبراهيم مائة وعشرون سنة إِنَّ هذا لَشَيْءٌ عَجِيبٌ أن يولد ولد من هرمين، وهو استبعاد من حيث العادة التي أجراها الله. وإنما أنكرت عليها الملائكة تعجبها ف قالُوا أَتَعْجَبِينَ مِنْ أَمْرِ اللَّهِ لأنها كانت في بيت الآيات ومهبط المعجزات والأمور الخارقة للعادات، فكان عليها أن تتوقر، ولا يزدهيها [[قوله «ولا يزدهيها» في الصحاح: زهاه وازدهاه: استخفه وتهاون به. (ع)]] ما يزدهى سائر النساء الناشئات في غير بيوت النبوة، وأن تسبح الله وتمجده مكان التعجب، وإلى ذلك أشارت الملائكة صلوات الله عليهم في قولهم رَحْمَتُ اللَّهِ وَبَرَكاتُهُ عَلَيْكُمْ أَهْلَ الْبَيْتِ أرادوا أن هذه وأمثالها مما يكرمكم به رب العزة ويخصكم بالإنعام به يا أهل بيت النبوّة، فليست بمكان عجب. وأمر الله: قدرته وحكمته: وقوله رَحْمَتُ اللَّهِ وَبَرَكاتُهُ عَلَيْكُمْ كلام مستأنف علل به إنكار التعجب، كأنه قيل: إياك والتعجب، فإنّ أمثال هذه الرحمة والبركة متكاثرة من الله عليكم. وقيل: الرحمة النبوة، والبركات الأسباط من بنى إسرائيل، لأنّ الأنبياء منهم، وكلهم من ولد إبراهيم حَمِيدٌ فاعل ما يستوجب به الحمد من عباده مَجِيدٌ كريم كثير الإحسان إليهم. وأهل البيت: نصب على النداء أو على الاختصاص، لأن أَهْلَ الْبَيْتِ مدح لهم: إذ المراد: أهل بيت خليل الرحمن.',     source_page = '381',     updated_at  = datetime('now') WHERE id = 'QR:TE:1ba6148f04c76f0ddb8530a9';
UPDATE qr_tafsir_entries SET content_ar = 'قائِلٌ مِنْهُمْ هو يهوذا، وكان أحسنهم فيه رأيا. وهو الذي قال، فلن أبرح الأرض. قال لهم: القتل عظيم أَلْقُوهُ فِي غَيابَتِ الْجُبِّ وهي غوره وما غاب منه عن عين الناظر وأظلم من أسفله. قال المنخل: وَإنْ أنَا يَوْماً غَيَّبَتْنِى غَيَابَتِى ... فَسِيرُوا بِسَيْرِى فِى الْعَشِيرَةِ وَالأَهْلِ [[للمنخل. والغيابة: ما غاب عن الناظر من أسفل البئر ونحوه. يقول: وإن غيبتني مقبرتى، كناية عن موته، فسيروا بسيرى، أى فانعونى وسيروا بذكر خصالى، على عادة العرب إذا مات منها رئيس. ويحتمل أنه يوصى أقاربه بالخير، وأنهم يسيرون بمثل سيره، ويفعلون كفعله في جيرانه وقرابته.]] أراد غيابة حفرته التي يدفن فيها. وقرئ غيابات، على الجمع. وغيابات، بالتشديد. وقرأ الجحدري: غيبة. والجب: البئر لم تطو، لأن الأرض تجبّ جباً لا غير يَلْتَقِطْهُ يأخذه بعض السيارة بعض الأقوام الذين يسيرون في الطريق. وقرئ: تلتقطه. بالتاء على المعنى، لأنّ بعض السيارة سيارة، كقوله: كَمَا شَرِقَتْ صَدْرُ الْقَنَاةِ مِنَ الدَّمِ [[تقدم شرح هذا الشاهد بالجزء الأول فراجعه إن شئت اه مصححه.]] ومنه: ذهبت بعض أصابعه إِنْ كُنْتُمْ فاعِلِينَ إن كنتم على أن تفعلوا ما يحصل به غرضكم، فهذا هو الرأى.',     source_page = '395',     updated_at  = datetime('now') WHERE id = 'QR:TE:6483d7ce4334150af86615e8';
UPDATE qr_tafsir_entries SET content_ar = 'وَقالَ نِسْوَةٌ وقال جماعة من النساء وكنّ خمسا: امرأة الساقي، وامرأَة الخباز، وامرأَة صاحب الدواب، وامرأة صاحب السجن، وامرأة الحاجب. والنسوة: اسم مفرد لجمع المرأة وتأنيثه غير حقيقى كتأنيث اللمة، ولذلك لم تلحق فعله تاء التأنيث. وفيه لغتان: كسر النون وضمها فِي الْمَدِينَةِ في مصر امْرَأَتُ الْعَزِيزِ يردن قطفير، والعزيز: الملك بلسان العرب فَتاها غلامها. يقال: فتاي وفتأتي، أى غلامى وجاريتي شَغَفَها خرق حبه شغاف قلبها حتى وصل إلى الفؤاد، والشغاف حجاب القلب، وقيل جلدة رقيقة يقال لها لسان القلب. قال النابغة: وَقَدْ حَالَ هَمٌّ دُونَ ذَلِكَ وَالِجٌ ... مَكَانَ الشِّغَافِ تَبْتَغِيِه الأَصَابِعُ [[وقد حال هم دون ذلك والج ... مكان الشغاف تبتغيه الأصابع وعيد أبى قابوس في غير كنهه ... أتانى ودوني راكش فالضواجع النابغة، يعتذر إلى النعمان ملك العرب عما قذفه به الواشون، أى وقد حال هم دون التغزل في المحبوبة وغيره من اللذات «والج» داخل مكان الشغاف. ويروى «ولوج الشغاف» أى كولوجه، والشغاف: داء في القلب جهة اليمين تخرجه الأطباء بأصابعهم، فتبتغيه الأصابع: من صفته على أنه حال منه. وقيل: حجاب القلب، أو جلدة رقيقة يقال لها لسان القلب، فتبتغيه: صفة للهم، وشبه الأصابع بمن يصح منه الطلب على طريق المكنية والابتغاء تخييل، ثم إنه شبه الهم المعقول بمحسوس وبالغ في ذلك حتى ادعى أن الأصابع تفتش عليه فلا تجده لشدة ولوجه وكمونه في القلب، أو تلمسه وتريد إخراجه. وبين الهم بقوله: وعيد النعمان أبى قابوس وتهديده حال كونه في غير كنه وحقيقته، أى: لم يبلغني بكماله. أو لأنه بلا سبب حصل منى، بل افترى الوشاة على كذباً جاءني. ودوني: ؟؟؟ أمامى هذين الموضعين وهما مسافة بعيدة، ومع ذلك أدركنى الخوف أو بعد المسافة، دلالة على غضب الملك عليه غضباً شديداً.]] وقرئ: شعفها، بالعين، من شعف البعير إذا هنأه [[قوله «إذا هنأه» في الصحاح «هنأت البعير» إذا طليته بالهناء. وهو القطران. (ع)]] فأحرقه بالقطران، قال: كَمَا شَعَفَ المَهْنُوءَةَ الرَّجُلُ الطّالِى [[أتقتلني وقد شعفت فؤادها ... كما شعف المهنوءة الرجل الطالى لامرئ القيس، والاستفهام للإنكار والاستبعاد، أو للتعجب. وشعف الجمل: إذا أحرقه بالقطران المغلي على النار، وهنأه: دهنه بذلك القطران، فأطلق الشعف وأريد منه مطلق الإحراق، ثم أريد منه الإحراق بالعشق مجازاً مرسلا ليصح التشبيه في قوله: كما أحرق الإبل المدهونة الداهن لها. وإن كان شغفت بالغين المعجمة فالمعنى: أصبت شغاف قلبها بالحب، وهو حجاب القلب أو لسانه أو حبة سوداء في وسطه، كما شغف: أى أخاف الإبل المدهونة وراع قلبها الرجل الداهن لها. لأنها تخافه في الأول. وقيل: شبه حبها باستلذاذ الإبل لذلك الطلى بعد دهنها به.]] وحُبًّا نصب على التمييز فِي ضَلالٍ مُبِينٍ في خطإ وبُعدٍ عن طريق الصواب بِمَكْرِهِنَّ باغتيابهنّ وسوء قالتهنّ، وقولهنّ: امرأة العزيز عشقت عبدها الكنعانى ومقتها، وسمى الاغتياب مكراً لأنه في خفية وحالى غيبة، كما يخفى الماكر مكره. وقيل: كانت استكتمتهنّ سرّها فأفشينه عليها أَرْسَلَتْ إِلَيْهِنَّ دعتهنّ. قيل: دعت أربعين امرأة منهنّ الخمس المذكورات وَأَعْتَدَتْ لَهُنَّ مُتَّكَأً ما يتكئن عليه من نمارق، قصدت بتلك الهيئة وهي فعودهنّ متكئات والسكاكين في أيديهنّ: أن يدهشن [[قوله «يدهشن» أى يتحيرن. أفاده الصحاح. (ع)]] ويبهتن عند رؤيته، ويشغلن عن نفوسهنّ فتقع أيديهنّ على أيديهنّ فيقطعنها، لأن المتكئ إذا بهت لشيء وقعت يده على يده، ولا يبعد أن تقصد الجمع بين المكر به وبهنّ، فتضع الخناجر في أيديهنّ ليقطعن أيديهنّ، فتبكتهنّ بالحجة، ولنهول يوسف من مكرها إذا خرج على أربعين نسوة مجتمعات في أيديهنّ الخناجر، وتوهمه أنهنّ يثبن عليه. وقيل: متكأ: مجلس طعام لأنهم كانوا يتكؤن للطعام والشراب والحديث كعادة المترفين، ولذلك «نهى أن يأكل الرجل متكئا» [[من رواية عبد الملك بن أبى سليمان عن ابن الزبير عن جابر قال «نهى رسول الله ﷺ أن يأكل أحدنا بشماله وبأن يأكل متكئاً» وفي الطبري من حديث ابن مسعود «نهى رسول الله ﷺ عن صومين وصلاتين ولباسين ومطعمين وبيعتين» ومنكحين- إلى أن قال: وأما المطعمان فأن يأكل الرجل بشماله ويمينه صحيح. وأن يأكل متكئا، إسناده جيد. وله في الأوسط وفي مسند الشاميين من حديث أبى الدرداء رضى الله عنه قال قال رسول الله ﷺ «لا تأكل متكئاً. ولا تتخط رقاب الناس يوم الجمعة» وأعله ابن حبان في الضعفاء بزريق بن عبد الله رواية عن عمرو بن الأسود عن أبى الدرداء. وفي الباب عن ابن أبى إهاب. أخرجه البزار بلفظ «نهى أن نأكل متكئين» .]] وآتتهنّ السكاكين ليعالجن بها ما يأكلن. وقيل مُتَّكَأً طعاما، من قولك اتكأنا عند فلان: طعمنا [[قوله «طعمنا» لعله «أى طعمناه» . (ع)]] ، على سبيل الكناية، لأن من دعوته ليطعم عندك اتخذت له تكأة يتكئ عليها. قال جميل: فَظَلَلْنَا بِنِعْمَةٍ وَاتَّكَأْنَا ... وَشَرِبْنَا الْحَلَالَ مِنْ قُلَلِهْ [[لحميد بن ثور. وقيل لجميل بن معمر. وظل يظل من باب علم. يقول: فظللنا في نعمة أو ملتبسين بنعمة. واتكأنا: أصله اوتكأنا فتاؤه الأولى واو: أى اتخذنا متكأ اضطجعنا عليه، وشربنا الشراب الحلال يمنى النبيذ، من قلله: جمع قلة، وهي الجرة العظيمة. ففي ذكر القلل دلالة على التوسع في الشرب وعدم التحجر فيه.]] وعن مجاهد مُتَّكَأً طعاما يحزّ حزّا، كأن المعنى يعتمد بالسكين، لأنّ القاطع يتكئ على المقطوع بالسكين. وقرئ متكا بغير همز. وعن الحسن: متكاء بالمدّ، كأنه مفتعال، وذلك لإشباع فتحة الكاف، كقوله «بُمْنتَزاحِ» [[قوله «بمنتزاح» هو من قول الشاعر: وأنت من الغوائل حين ترمى ... وعن ذم الرجال بمنتزاح والبيت لابن هرمة يرثى ابنه. والغوائل: الحوادث التي تغتال النفوس وتهلكها. ونزح: إذا بعد، والمنتزح: اسم لمكان البعد، وأشبعت فتحته فتولدت منها الألف كقولهم: ينباع في ينبع، وعقراب في عقرب.]] بمعنى بمنتزح. ونحوه «يَنْبَاعُ» [[قوله «ينباع» هو من قول الشاعر: ينباع من ذفرى أسيل حرة ... زيافة مثل الفنيق المكدم وقد مر شرح هذا البيت في سورة الأعراف بهذا الجزء فراجعه إن شئت اه مصححه.]] بمعنى ينبع. وقرئ: متكا وهو الأترج، وأنشد: فَأَهْدَتْ مَتْكَةً لِبَنِى أبِيهَا ... تَخُبُّ بِهَا العثَمْثَمَةُ الْوِقَاحُ [[المتكة: الأترجة، وكأنه التي ذكر أبو داود في سننه أنها شقت نصفين وحملت على ناقة. والخبب: نوع من السير. والعثمثمة: الصلبة: والوقاح- بالفتح-: شديدة وقع الخف على الأرض.]] وكانت أهدت أترجة على ناقة، وكأنها الأترجة التي ذكرها أبو داود في سننه أنها شقت بنصفين، وحملا كالعدلين على جمل. وقيل: الزماورد [[قوله «الزماورد» هو الرقاق المحشو باللحم. (ع)]] وعن وهب: أترجا وموزاً وبطيخا. وقيل: أعتدت لهنَّ ما يقطع، من متك الشيء بمعنى بتكه إذا قطعه. وقرأ الأعرج: مُتَّكَأً مفعلا، من تكئ يتكأ، إذا اتكأ أَكْبَرْنَهُ أعظمنه وهبن ذلك الحسن الرائع والجمال الفائق. قيل: كان فضل يوسف على الناس في الحسن كفضل القمر ليلة البدر على نجوم السماء. وعن النبي ﷺ: «مررت بيوسف الليلة التي عرج بى إلى السماء، فقلت لجبريل: من هذا؟ فقال يوسف» فقيل: يا رسول الله، كيف رأيته؟ قال «كالقمر ليلة البدر [[أخرجه الثعلبي من رواية أبى هارون العبدى عن أبى سعيد. وأخرجه الحاكم والبيهقي في الدلائل وابن مردويه من هذا الوجه مطولا.]] » وقيل كان يوسف إذا سار في أزقة مصر يرى تلألؤ وجهه على الجدران، كما يرى نور الشمس من الماء عليها. وقيل: ما كان أحد يستطيع وصف يوسف. وقيل: كان يشبه آدم يوم خلقه ربه. وقيل: ورث الجمال من جدّته سارة. وقيل: أكبرن بمعنى حضن، والهاء للسكت. يقال: أكبرت المرأة إذا حاضت، وحقيقته: دخلت في الكبر لأنها بالحيض تخرج من حدّ الصغر إلى حدّ الكبر، وكأن أبا الطيب أخذ من هذا التفسير قوله: خَفِ اللَّهَ وَاسْتُرْ ذَا الْجَمَالَ بِبُرْقُعٍ ... فَإنْ لُحْتَ حَاضَتْ فِى الْخُدُورِ الْعَوَاتِقُ [[لأبى الطيب، يقول: اتق الله واستر هذا الجمال الذي في وجهك ببرقع، لأنك إن ظهرت حاضت العواتق، أى خيار النساء وهن في خدورهن، لما ينظرن من جمالك. ولاح يلوح: ظهر يظهر.]] قَطَّعْنَ أَيْدِيَهُنَّ جرحنها، كما تقول: كنت أقطع اللحم فقطعت يدي، تريد: جرحتها حاشَ كلمة تفيد معنى التنزيه في باب الاستثناء. تقول: أساء القوم حاشا زيد. قال: حَاشَا أَبِى ثَوْبَانَ إنَّ بِهِ ... ضَنَّا عَنِ المَلْحَاةِ وَالشَّتْمِ [[حاشا أبى ثوبان إن أبا ... ثوبان ليس ببكمة فدم عمرو بن عبد الله إن به ... ضنا عن الملحاة والشتم للمنقذ بن الطماح وهو الجميح الأسدى. وحاشا: كلمة تبرئة وتنزيه واقعة موقع المصدر مضافة لما بعدها، كسبحان الله. ويجوز أنها حاشا الاستثنائية، وهي حرف جر عند الأكثر. ورواه الضبي: حاشا أبا ثوبان بالنصب، فهو فعل، واحتمال لغة القصر ضعيف لشهرة لغة الاعراب بالحروف. وعلى الأول فبناؤها لمشابهتها للحرفية لفظا ومعنى. وبكم الرجل- كتعب-: إذا عجز عن الكلام. وقدم كسهل وظرف، إذا عجز عن الحجة كأن فمه مسدود. والضن- بالكسر-: البخل. والملحاة: مفعلة، من لحاه إذا لامه. واللحاء- كالرداء- مفاعلة من اللحن والعذل، من لحوت العود إذا قشرته. وتكرير أبى ثوبان لتعظيمه والتنويه باسمه، ليس ببكمة بالضم، أى ذى بكمة، أى: ليس بأبكم، ولا قدم: أى عاجز عن الكلام. وعمرو: قيل إنه بدل من أبى ثوبان، فقوله: إن أبا ثوبان الخ: جملة اعتراضية مبينة لوجه التنزيه. وفي قوله: إن به ضنا، بيان لوجه سكوته عن مؤاخذة اللئام. والمعنى: إن به امتناعا وتنزها عن اللؤم والشتم.]] وهي حرف من حروف الجر، فوضعت موضع التنزيه والبراءة، فمعنى «حاشا الله» براءة الله وتنزيه الله، وهي قراءة ابن مسعود، على إضافة حاشا إلى الله إضافة البراءة. ومن قرأ: حاشا لله، فنحو قولك: سقيا لك، كأنه قال: براءة، ثم قال: لله، لبيان من يبرأ وينزه. والدليل على تنزيل «حاشا» منزلة المصدر: قراءة أبى السمال: حاشَ لِلَّهِ، بالتنوين. وقراءة أبى عمرو حاشَ لِلَّهِ بحذف الألف الآخرة. وقراءة الأعمش حاشَ لِلَّهِ بحذف الألف الأولى. وقرئ حاشَ لِلَّهِ بسكون الشين، على أن الفتحة تبعت الألف في الإسقاط، وهي ضعيفة لما فيها من التقاء الساكنين على غير حدّه. وقرئ: حاشا الإله. فإن قلت: فلم جاز في حاشا لله أن لا ينوّن بعد إجرائه مجرى: براءة لله؟ قلت: مراعاة لأصله الذي هو الحرفية. ألا ترى إلى قولهم: جلست من عن يمينه، كيف تركوا «عن» غير معرب على أصله؟ وعلى [[قوله «على أصله وعلى في قوله» عطفه يحتاج إلى تكلف، أى: وإلى قوله غدت من عليه بعد مأتم ظمؤها كيف ترك على في قوله. ويمكن أن التقدير: ألا ترى إلى قولهم الخ وعلى في قوله أى: وألا ترى على ... الخ. (ع)]] في قوله «غدت من عليه» منقلب الألف إلى الياء مع الضمير؟ والمعنى: تنزيه الله تعالى من صفات العجز، والتعجب من قدرته على خلق جميل مثله. وأما قوله حاشَ لِلَّهِ ما عَلِمْنا عَلَيْهِ مِنْ سُوءٍ فالتعجب من قدرته على خلق عفيف مثله ما هذا بَشَراً نفين عنه البشرية لغرابة جماله ومباعدة حسنه [[قال محمود: «نفين عنه البشرية لغرابة جماله ومباعدة حسنه ... الخ» قال أحمد: تقدم القول في مسألة التفضيل شافياً، والزمخشري لا يدعه التعصب للمعتقد الفاسد أن يحمله على مثل هذه المشافهات، يرمى بها أهل الحق فينسب إليهم الإجبار والخسار والمكابرة في الضروريات وجحد الحقائق تعكيساً، وهذا كله هم برآء منه، وحسبه من المقابلة بذلك خطؤه في اعتقاد أن تفضيل الملك عند قائله ليس ضروريا ولا عقلياً نظريا، ولكن سمعياً، وقد قنع في الاستدلال على هذه العقيدة بالضرورة التي ادعى أنها مركوزة في الطباع، ثم حكم بأن كل مركوز في الطباع حق، وخصوصاً والكلام في طباع النساء القائلات: ما هذا بشرا. وإذا كان كل مركوز في الطباع حقاً، فما ركز فيها حب الشهوات وإيثار العاجلة وجميع أمهات. الذنوب مركوز في الطباع، أفيكون ذلك حقاً إلا عند ناظر بعين الهوى، أعشى في سبيل الهدى، والله ولى التوفيق.]] ، لما عليه محاسن الصور، وأثبتن له الملكية وبتتن بها الحكم، وذلك لأن الله عز وجل ركز في الطباع أن لا أحسن من الملك، كما ركز فيها أن لا أقبح من الشيطان، ولذلك يشبه كل متناه في الحسن والقبح بهما، وما ركز ذلك فيها إلا لأنّ الحقيقة كذلك، كما ركز في الطباع أن لا أدخل في الشر من الشياطين، ولا أجمع للخير من الملائكة، إلا ما عليه الفئة الخاسئة [[قوله «إلا ما عليه الفئة الخاسئة» يريد أهل السنة، وقد أساء في تعصبه للمعتزلة فعفا الله عنه. (ع)]] المجبرة من تفضيل الإنسان على الملك، وما هو إلا من تعكيسهم للحقائق، وجحودهم للعلوم الضرورية، ومكابرتهم في كل باب، وإعمال «ما» عمل «ليس» هي اللغة القدمى الحجازية [[قوله «ليس هي اللغة القدمى الحجازية» بمعنى القديمة، لكن لم يذكرها في الصحاح. (ع)]] وبها ورد القرآن. ومنها قوله تعالى ما هُنَّ أُمَّهاتِهِمْ ومن قرأ على سليقته من بنى تميم، قرأ «بشر» بالرفع. وهي في قراءة ابن مسعود. وقرئ: ما هذا بشرى، أى ما هو بعبد مملوك لئيم إِنْ هذا إِلَّا مَلَكٌ كَرِيمٌ تقول هذا بشرى، أى حاصل بشرى، بمعنى: هذا مشرى. وتقول: هذا لك بشرى أم بكرى؟ والقراءة هي الأولى، لموافقتها المصحف، ومطابقة بشر لملك قالَتْ فَذلِكُنَّ ولم تقل فهذا وهو حاضر [[قال محمود: «لم لم تقل فهذا وهو حاضر ... الخ» قال أحمد: وبهذا أجبت عما أورده من السؤال في قوله تعالى أول البقرة الم ذلِكَ الْكِتابُ لما جعل الاشارة إلى الحروف المذكورة فقال: إن قلت كيف أشار إليها وهي قريبة كما يشار إلى البعيد، وأجاب هو بأن كل متقض بعيد، وأجبت أنا بأن الاشارة بذلك إلى بعيد منزلة هذا الكتاب بالنسبة إلى كتب الله تعالى.]] ، رفعاً لمنزلته في الحسن، واستحقاق أن يحب ويفتتن به، وربئاً بحاله واستبعاداً لمحله. ويجوز أن يكون إشارة إلى المعنىّ بقولهنّ: عشقت عبدها الكنعانى. تقول: هو ذلك العبد الكنعانى الذي صوّرتن في أنفسكنّ، ثم لمتنني فيه. تعنى: أنكن لم تصوّرنه بحق صورته، ولو صوّرتنه بما عاينتن لعذرتننى في الافتنان به. الاستعصام: بناء مبالغة يدل على الامتناع البليغ والتحفظ الشديد، كأنه في عصمة وهو يجتهد في الاستزادة منها. ونحوه استمسك واستوسع الفتق واستجمع الرأى واستفحل الخطب. وهذا بيان لما كان من يوسف عليه السلام لا مزيد عليه، وبرهان لا شيء أنور منه، على أنه بريء مما أضاف إليه أهل الحشو مما فسروا به الهمّ والبرهان. فإن قلت: الضمير في آمُرُهُ راجع إلى الموصول، أم إلى يوسف؟ قلت: بل إلى الموصول. والمعنى: ما آمر به، فحذف الجار كما في قولك: أمرتك الخير، ويجوز أن تجعل «ما» مصدرية، فيرجع إلى يوسف. ومعناه: ولئن لم يفعل أمرى إياه، أى موجب أمرى ومقتضاه. قرئ وَلَيَكُوناً بالتشديد والتخفيف. والتخفيف أولى، لأنّ النون كتبت في المصحف ألفاً على حكم الوقف، وذلك لا يكون إلا في الخفيفة.',     source_page = '122',     updated_at  = datetime('now') WHERE id = 'QR:TE:069867d4a7cd3c98427a76e8';
UPDATE qr_tafsir_entries SET content_ar = 'فَلَمَّا دَخَلُوا عَلى يُوسُفَ قيل وجه يوسف إلى أبيه جهازاً ومائتي راحلة ليتجهز إليه بمن معه. وخرج يوسف والملك في أربعة آلاف من الجند والعظماء وأهل مصر بأجمعهم، فتلقوا يعقوب وهو يمشى يتوكأ على يهوذا، فنظر إلى الخيل والناس فقال: يا يهوذا، أهذا فرعون مصر؟ قال لا، هذا ولدك، فلما لقيه قال يعقوب عليه السلام: السلام عليك يا مذهب الأحزان. وقيل إن يوسف قال له لما التقيا: يا أبت، بكيت علىّ حتى ذهب بصرك، ألم تعلم أن القيامة تجمعنا؟ فقال: بلى، ولكن خشيت أن تسلب دينك فيحال بيني وبينك، وقيل: إنّ يعقوب وولده دخلوا مصر وهم اثنان وسبعون، ما بين رجل وامرأة، وخرجوا منها مع موسى ومقاتلتهم ستمائة ألف وخمسمائة وبضعة وسبعون رجلا سوى الذرية والهرمى، وكانت الذرّية ألف ألف ومائتي ألف آوى إِلَيْهِ أَبَوَيْهِ ضمهما إليه واعتنقهما. قال ابن أبى إسحاق: كانت أمّه تحيى، وقيل: هما أبوه وخالته. ماتت أمّه فتزوّجها وجعلها أحد الأبوين، لأنّ الرابة تدعى أمّاً، لقيامها مقام الأمّ، أو لأنّ الخالة أمّ كما أنّ العم أب. ومنه قوله وَإِلهَ آبائِكَ إِبْراهِيمَ وَإِسْماعِيلَ وَإِسْحاقَ فإن قلت: ما معنى دخولهم عليه قبل دخولهم مصر؟ قلت: كأنه حين استقبلهم نزل لهم في مضرب [[قوله «في مضرب» عبارة النسفي: مضرب خيمة. (ع)]] أو بيت ثم، فدخلوا عليه وضمّ إليه أبويه، ثم قال لهم ادْخُلُوا مِصْرَ إِنْ شاءَ اللَّهُ آمِنِينَ ولما دخل مصر وجلس في مجلسه مستويا على سريره واجتمعوا إليه، أكرم أبويه فرفعهما على السرير وَخَرُّوا لَهُ يعنى الإخوة الأحد عشر والأبوين سُجَّداً ويجوز أن يكون قد خرج في قبة من قباب الملوك التي تحمل على البغال، فأمر أن يرفع إليه أبواه، فدخلا عليه القبة. فآواهما إليه بالضم والاعتناق وقرّبهما منه، وقال بعد ذلك: ادخلوا مصر. فإن قلت: بم تعلقت المشيئة؟ قلت: بالدخول مكيفاً بالأمن، لأن القصد إلى اتصافهم بالأمن في دخولهم، فكأنه قيل لهم: اسلموا وأمنوا في دخولكم إن شاء الله. ونظيره قولك للغازى: ارجع سالما غانما إن شاء الله. فلا تعلق المشيئة بالرجوع مطلقا، ولكن مقيداً بالسلامة والغنيمة، مكيفا بهما. والتقدير: ادخلوا مصر آمنين إن شاء الله دخلتم آمنين، ثم حذف الجزاء لدلالة الكلام عليه، ثم اعترض بالجملة الجزائية بين الحال وذى الحال. ومن بدع التفاسير أن قوله إِنْ شاءَ اللَّهُ من باب التقديم والتأخير، وأن موضعها ما بعد قوله سَوْفَ أَسْتَغْفِرُ لَكُمْ رَبِّي في كلام يعقوب، وما أدرى ما أقول فيه وفي نظائره. فإن قلت: كيف جاز لهم أن يسجدوا لغير الله؟ قلت: كانت السجدة عندهم جارية مجرى التحية والتكرمة، كالقيام، والمصافحة وتقبيل اليد. ونحوها مما جرت عليه عادة الناس، من أفعال شهرت في التعظيم والتوقير. وقيل: ما كانت إلا انحناء دون تعفير الجباه، وخرورهم سجداً يأباه. وقيل: معناه وخرّوا لأجل يوسف سجداً لله شكراً. وهذا أيضا فيه نبوة. يقال: أحسن إليه وبه، وكذلك أساء إليه وبه. قال: أَسِيئِى بِنَا أَوْ أَحْسِنِى لَا مَلُومَةً [[مر شرح هذا الشاهد من هذا الجزء فراجعه إن شئت اه مصححه.]] مِنَ الْبَدْوِ من البادية، لأنهم كانوا أهل عمد وأصحاب مواش ينتقلون في المياه والمناجع نَزَغَ أفسد بيننا وأغرى، وأصله من نخس الرائض الدابة وحمله على الجري. يقال، نزغه ونسغه، إذا نخسه لَطِيفٌ لِما يَشاءُ لطيف التدبير لأجله، رفيق حتى يجيء على وجه الحكمة والصواب. وروى أن يوسف أخذ بيد يعقوب فطاف به في خزائنه، فأدخله خزائن الورق والذهب، وخزائن الحلىّ، وخزائن الثياب، وخزائن السلاح وغير ذلك، فلما أدخله خزانة القراطيس قال: يا بنىّ، ما أعقك: عندك هذه القراطيس وما كتبت إلىّ على ثمان مراحل؟ قال: أمرنى جبريل. قال أو ما تسأله؟ قال: أنت أبسط إليه منى فسله. قال جبريل عليه السلام: الله تعالى أمرنى بذلك لقولك وَأَخافُ أَنْ يَأْكُلَهُ الذِّئْبُ قال: فهلا خفتنى؟ وروى أن يعقوب أقام معه أربعا وعشرين سنة ثم مات. وأوصى أن يدفنه بالشام إلى جنب أبيه إسحاق. فمضى بنفسه ودفنه ثمة، ثم عاد إلى مصر، وعاش بعد أبيه ثلاثا وعشرين سنة، فلما تم أمره وعلم أنه لا يدوم له، طلبت نفسه الملك الدائم الخالد، فتاقت نفسه إليه فتمنى الموت. وقيل: ما تمناه نبىّ قبله ولا بعده، فتوفاه الله طيبا طاهراً، فتخاصم أهل مصر وتشاحوا في دفنه: كل يحب أن يدفن في محلتهم حتى هموا بالقتال، فرأوا من الرأى أن عملوا له صندوقا من مر مر وجعلوه فيه، ودفنوه في النيل بمكان يمرّ عليه الماء ثم يصل إلى مصر ليكونوا كلهم فيه شرعا واحداً [[قوله «ليكونوا كلهم فيه شرعا واحداً» في الصحاح: الناس في هذا الأمر شرع، أى سواء، يحرك ويسكن. (ع)]] ، وولد له: إفراثيم وميشا، وولد لإفراثيم نون، ولنون يوشع فتى موسى، ولقد توارثت الفراعنة من العماليق بعده مصر، ولم يزل بنو إسرائيل تحت أيديهم على بقايا دين يوسف وآبائه. إلى أن بعث الله موسى ﷺ.',     source_page = '279',     updated_at  = datetime('now') WHERE id = 'QR:TE:b42dbcdae5e931482baf9a3b';
UPDATE qr_tafsir_entries SET content_ar = 'وَلَوْ أَنَّ قُرْآناً جوابه محذوف، كما تقول لغلامك: لو أنى قمت إليك، وتترك الجواب والمعنى: ولو أن قرآنا سُيِّرَتْ بِهِ الْجِبالُ عن مقارّها، وزعزعت عن مضاجعها أَوْ قُطِّعَتْ بِهِ الْأَرْضُ حتى تتصدع وتتزايل قطعاً أَوْ كُلِّمَ بِهِ الْمَوْتى فتسمع وتجيب، لكان هذا القرآن لكونه غاية في التذكير ونهاية في الإنذار والتخويف، كما قال لَوْ أَنْزَلْنا هذَا الْقُرْآنَ عَلى جَبَلٍ لَرَأَيْتَهُ خاشِعاً مُتَصَدِّعاً مِنْ خَشْيَةِ اللَّهِ هذا يعضد ما فسرت به قوله لِتَتْلُوَا عَلَيْهِمُ الَّذِي أَوْحَيْنا إِلَيْكَ من إرادة تعظيم ما أوحى إلى رسول الله ﷺ من القرآن. وقيل: معناه ولو أن قرآنا وقع به تسيير الجبال وتقطيع الأرض وتكليم الموتى وتنبيههم، لما آمنوا به ولما تنبهوا عليه كقوله وَلَوْ أَنَّنا نَزَّلْنا إِلَيْهِمُ الْمَلائِكَةَ الآية. وقيل: إن أبا جهل بن هشام قال لرسول الله ﷺ: سير بقرآنك الجبال عن مكة حتى تتسع لنا فنتخذ فيها البساتين والقطائع، كما سخرت لداود عليه السلام إن كنت نبياً كما تزعم، فلست بأهون على الله من داود. وسخر لنا به الريح لنركبها ونتجر إلى الشام ثم نرجع في يومنا، فقد شق علينا قطع المسافة البعيدة كما سخرت لسليمان عليه السلام. أو ابعث لنا به رجلين أو ثلاثة ممن مات من آبائنا: منهم قصى بن كلاب [[لم أجده بهذا السياق، وقد روى ابن ربيعة عن أبى أسامة عن مجالد عن الشعبي قال قالت قريش النبي ﷺ «إن كنت نبياً كما تزعم فباعد بين جبلي مكة- أحسبها هذين مسيرة أربعة أيام أو خمسة حتى تزرع فيها ونرعى، وابعث لنا آباءنا من الموتى حتى يكلمونا ويخبرون أنك نبى، أو احملنا إلى الشام، أو إلى اليمن، أو إلى الحيرة، حتى نذهب ونجيء في ليلة كما زعمت أنك فعلت. فأنزل الله تعالى وَلَوْ أَنَّ قُرْآناً- الآية وروى ابن أبى حاتم وابن مردويه من طريق عطية بن أبى سعيد قال قالوا لمحمد ﷺ: «لو سيرت لنا جبال مكة حتى تتسع فنحرث فيها، أو قطعت لنا الأرض كما كان سليمان يقطع لقومه الريح» وروى أبو يعلى من حديث الزبير بن العوام يقول «لما نزلت: وأنذر عشيرتك الأقربين صاح رسول الله ﷺ: يا آل قريش، فجاءته قريش. فحذرهم وأنذرهم فقالوا: تزعم أنك نبى وأن سليمان سخر له الريح والجبال، وأن موسى سخر له البحر، وأن عيسى كان يحيى الموتى. فادع الله أن يسير عنا هذه الجبال وتنفجر لنا الأرض أنهارا فنتخذها محارث فنزرع ونأكل أو ادع الله أن يحيى لنا موتانا فنكلمهم ويكلمونا أو ادع الله أن يصبر هذه الصخرة التي بجنبك ذهبا فننحت منها ويغنينا قال: فبينما نحن حوله إذ نزل عليه الوحى. فلما سرى عنه قال: والذي نفسي بيده، لقد أعطانى ما سألتم ولو شئت كان ولكن أخبرنى أنه إن أعطاكم ذلك ثم كفرتم يعذبكم. فنزلت» .]] فنزلت. ومعنى تقطيع الأرض على هذا: قطعها بالسير ومجاوزتها. وعن الفراء: هو متعلق بما قبله. والمعنى: وهم يكافرون بالرحمن وَلَوْ أَنَّ قُرْآناً سُيِّرَتْ بِهِ الْجِبالُ وما بينهما اعتراض، وليس ببعيد من السداد. وقيل قُطِّعَتْ بِهِ الْأَرْضُ شققت فجعلت أنهارا وعيونا بَلْ لِلَّهِ الْأَمْرُ جَمِيعاً على معنيين، أحدهما: بل لله القدرة على كل شيء، وهو قادر على الآيات التي اقترحوها، إلا أنّ علمه بأنّ إظهارها مفسدة يصرفه. والثاني: بل لله أن يلجئهم إلى الإيمان، وهو قادر على الإلجاء لولا أنه بنى أمر التكليف على الاختيار. ويعضده قوله أَفَلَمْ يَيْأَسِ الَّذِينَ آمَنُوا أَنْ لَوْ يَشاءُ اللَّهُ يعنى مشيئة الإلجاء والقسر [[قوله «أن لو يشاء الله يعنى مشيئة الإلجاء» هذا عند المعتزلة دون أهل السنة. (ع)]] لَهَدَى النَّاسَ جَمِيعاً ومعنى أَفَلَمْ يَيْأَسِ أفلم يعلم. قيل: هي لغة قوم من النخع. وقيل: إنما استعمل اليأس بمعنى العلم لتضمنه معناه، لأنّ اليائس عن الشيء عالم بأنه لا يكون، كما استعمل الرجاء في معنى الخوف، والنسيان في معنى الترك لتضمن ذلك. قال سحيم بن وثيل الرياحي: أَقُولُ لَهُمْ بِالشِّعْبِ إذْ يَيْسِرُونَنِى ... أَلَمْ تَيْأَسُوا أنِّى ابْنُ فَارِسِ زَهْدَمِ [[مر شرح هذا الشاهد بالجزء الأول فراجعه إن شئت اه مصححه.]] ويدل عليه أن علياً وابن عباس وجماعة من الصحابة والتابعين قرءوا: أفلم يتبين، وهو تفسير أَفَلَمْ يَيْأَسِ وقيل: إنما كتبه الكاتب وهو ناعس مستوى السينات، وهذا ونحوه مما لا يصدق في كتاب الله الذي لا يأتيه الباطل من بين يديه ولا من خلفه، وكيف يخفى مثل هذا حتى يبقى ثابتا بين دفتي الإمام. وكان متقلبا في أيدى أولئك الأعلام المحتاطين في دين الله المهيمنين عليه لا يغفلون عن جلائله ودقائقه، خصوصا عن القانون الذي إليه المرجع، والقاعدة التي عليها البناء، وهذه والله فرية ما فيها مرية. ويجوز أن يتعلق أَنْ لَوْ يَشاءُ بآمنوا، على: أولم يقنط عن إيمان هؤلاء الكفرة الذين آمنوا بأن لو يشاء الله لهدى الناس جميعا ولهداهم تُصِيبُهُمْ بِما صَنَعُوا من كفرهم وسوء أعمالهم قارِعَةٌ داهية تقرعهم بما يحل الله بهم في كل وقت من صنوف البلايا والمصائب في نفوسهم وأولادهم وأموالهم أَوْ تَحُلُّ القارعة قَرِيباً منهم فيفزعون ويضطربون ويتطاير إليهم شرارها، ويتعدى إليهم شرورها حَتَّى يَأْتِيَ وَعْدُ اللَّهِ وهو موتهم، أو القيامة. وقيل: ولا يزال كفار مكة تصيبهم بما صنعوا برسول الله ﷺ من العداوة والتكذيب قارعة، لأنّ رسول الله ﷺ كان لا يزال يبعث السرايا [[قلت: هو موجود في المغازي لابن اسحق. والواقدي، وطبقات ابن سعد في عدة سرايا منها سرية زيد ابن حارثة ليلقى عير قريش، وسرية على الحر بن سعد بن بكر وغيرهما.]] فتغير حول مكة وتختطف منهم، وتصيب من مواشيهم. أو تحل أنت يا محمد قريبا من دارهم بجيشك، كما حل بالحديبية، حتى يأتى وعد الله وهو فتح مكة، وكان الله قد وعده ذلك',     source_page = '261',     updated_at  = datetime('now') WHERE id = 'QR:TE:76a9504b8c7f5d4a3754c8d0';
UPDATE qr_tafsir_entries SET content_ar = 'إِذْ أَنْجاكُمْ ظرف للنعمة بمعنى الإنعام، أى إنعامه عليكم ذلك الوقت. فإن قلت: هل يجوز أن ينتصب بعليكم؟ قلت: لا يخلو من أن يكون صلة للنعمة بمعنى الإنعام، أو غير صلة إذا أردت بالنعمة العطية، فإذا كان صلة لم يعمل فيه، وإذا كان غير صلة بمعنى اذكروا نعمة الله مستقرّة عليكم عمل فيه، ويتبين [[قوله «ويتبين» لعله: وتبيين. (ع)]] الفرق بين الوجهين أنك إذا قلت: نعمة الله عليكم، فإن جعلته صلة لم يكن كلاماً حتى تقول فائضة أو نحوها، وإلا كان كلاما. ويجوز أن يكون «إذ» بدلا من نعمة الله، أى: اذكروا وقت إنجائكم، وهو من بدل الاشتمال. فإن قلت: في سورة البقرة يُذَبِّحُونَ وفي الأعراف يُقَتِّلُونَ وهاهنا وَيُذَبِّحُونَ مع الواو، فما الفرق؟ قلت: الفرق أنّ التذبيح حيث طرح الواو جعل تفسيراً للعذاب وبياناً له، وحيث أثبت جعل التذبيح لأنه أو في على جنس العذاب، وزاد عليه زيادة ظاهرة كأنه جنس آخر. فإن قلت: كيف كان فعل آل فرعون بلاء من ربهم؟ قلت: تمكينهم وإمهالهم، حتى فعلوا ما فعلوا ابتلاء من الله. ووجه آخر وهو أن ذلك إشارة إلى الإنجاء وهو بلاء عظيم، والبلاء يكون ابتلاء بالنعمة والمحنة جميعا، قال تعالى وَنَبْلُوكُمْ بِالشَّرِّ وَالْخَيْرِ فِتْنَةً وقال زهير: فَأَبْلَاهُمَا خَيرَ البَلَاءِ الذِى يَبْلُوا [[تقدم شرح هذا الشاهد بهذا الجزء فراجعه إن شئت اه مصححه.]]',     source_page = '208',     updated_at  = datetime('now') WHERE id = 'QR:TE:7e8628a7391c8550dbe2cf2a';
UPDATE qr_tafsir_entries SET content_ar = 'كانَ مِنَ الْجِنِّ كلام مستأنف [[قال محمود: «قوله تعالى كان من الجن مستأنف تعليل لفسوقه ... الخ» قال أحمد: والحق معه في هذا الفعل غير أن قوله «تعمده الله تعالى» لفظة لا تروق ولا تليق، فان التعمد إنما يوصف به عرفا من يفعل في بعض الأحيان خطأ وفي بعضها تعمدا، فاجتنابها في حق الله تعالى واجب، والله الموفق.]] جار مجرى التقليل بعد استثناء إبليس من الساجدين، كأن قائلا قال: ما له لم يسجد؟ فقيل: كان من الجن فَفَسَقَ عَنْ أَمْرِ رَبِّهِ والفاء للتسبيب أيضا، جعل كونه من الجن سببا في فسقه، لأنه لو كان ملكا كسائر من سجد لآدم لم يفسق عن أمر الله، لأنّ الملائكة معصومون البتة لا يجوز عليهم ما يجوز على الجن والإنس، كما قال لا يَسْبِقُونَهُ بِالْقَوْلِ وَهُمْ بِأَمْرِهِ يَعْمَلُونَ وهذا الكلام المعترض تعمد من الله تعالى لصيانة الملائكة عن وقوع شبهة في عصمتهم. فما أبعد البون بين ما تعمده الله، وبين قول من ضادّه وزعم أنه كان ملكا ورئيسا على الملائكة، فعصى، فلعن ومسخ شيطانا، ثم ورّكه [[قوله «ثم ورّكه» أى اتهمه به. (ع)]] على ابن عباس. ومعنى فَفَسَقَ عَنْ أَمْرِ رَبِّهِ خرج عما أمره به ربه من السجود. قال: فواسقا عن قصدها جوائرا [[مر شرح هذا الشاهد بالجزء الأول فراجعه إن شئت اه مصححه.]] أو صار فاسقا كافرا بسبب أمر ربه الذي هو قوله اسْجُدُوا لِآدَمَ. أَفَتَتَّخِذُونَهُ الهمزة للإنكار والتعجيب، كأنه قيل: أعقيب ما وجد منه تتخذونه وَذُرِّيَّتَهُ أَوْلِياءَ مِنْ دُونِي وتستبدلونهم بى، بئس البدل من الله إبليس لمن استبدله، فأطاعه بدل طاعته ما أَشْهَدْتُهُمْ وقرئ: ما أشهدناهم، يعنى: أنكم اتخذتموهم شركاء لي في العبادة، وإنما كانوا يكونون شركاء فيها لو كانوا شركاء في الإلهية، فنفى مشاركتهم في الإلهية بقوله ما أَشْهَدْتُهُمْ خَلْقَ السَّماواتِ وَالْأَرْضِ لأعتضد بهم في خلقها [[قوله «لأعتضد بهم في خلقها» أى لأستعين بهم. (ع)]] وَلا خَلْقَ أَنْفُسِهِمْ أى ولا أشهدت بعضهم خلق بعض كقوله وَلا تَقْتُلُوا أَنْفُسَكُمْ. وَما كُنْتُ مُتَّخِذَ الْمُضِلِّينَ بمعنى وما كنت متخذهم عَضُداً أى أعوانا، فوضع المضلين موضع الضمير ذمّا لهم بالإضلال، فإذا لم يكونوا عضدا لي في الخلق، فما لكم تتخذونهم شركاء لي في العبادة؟ وقرئ: وما كنت، بالفتح: الخطاب لرسول الله ﷺ، والمعنى: وما صح لك الاعتضاد بهم، وما ينبغي لك أن تعتز بهم. وقرأ على رضى الله عنه: وما كنت متخذا المضلين، بالتنوين على الأصل. وقرأ الحسن: عضدا، بسكون الضاد، ونقل ضمتها إلى العين. وقرئ: عضدا، بالفتح وسكون الضاد. وعضدا، بضمتين وعضدا بفتحتين: جمع عاضد، كخادم وخدم، وراصد ورصد، من عضده: إذا قواه وأعانه،',     source_page = '119',     updated_at  = datetime('now') WHERE id = 'QR:TE:19553dd04d0c41782e797eda';
UPDATE qr_tafsir_entries SET content_ar = 'أَهْلَ قَرْيَةٍ هي أنطاكية. وقيل: الأبلة، وهي أبعد أرض الله من السماء أَنْ يُضَيِّفُوهُما وقرئ: يضيفوهما. يقال: ضافه إذا كان له ضيفا. وحقيقته: مال إليه، من ضاف السهم عن الغرض، ونظيره: زاره، من الازورار. وأضافه وضيفه: أنزله وجعله ضيفه. وعن النبي ﷺ: كانوا أهل قرية لئاما [[أخرجه النسائي من رواية إسرائيل عن ابن إسحاق عن سعيد بن جبير عن ابن عباس عن أبى عن النبي ﷺ، في قوله فَأَبَوْا أَنْ يُضَيِّفُوهُما. قال «كانوا أهل قرية لئاما» وهو في مسلم بلفظ فَانْطَلَقا حَتَّى إِذا أَتَيا أَهْلَ قَرْيَةٍ لئاما.]] . وقيل شر القرى التي لا يضاف الضيف فيها ولا يعرف لابن السبيل حقه يُرِيدُ أَنْ يَنْقَضَّ استعيرت الإرادة للمداناة والمشارفة، كما استعير الهمّ والعزم لذلك. قال الراعي: في مهمه قلقت به هاماتها ... قلق الفئوس إذا أردن نصولا [[للراعي يصف الإبل بأنها في مهمه: أى مفازة، قلقت: أى تحركت فيه هاماتها: أى رءوسها. قلق الفئوس: أى كتحرك الفئوس جمع فأس وهي آلة الحفر، إذا أردن: أى الفئوس، نصولا: أى قربن منه، فالارل مجاز مرسل، ونصولها: خروج الحديدة من المقبض. والنصول في كل شيء: الخروج، والانصال: الإخراج، ولقد شبه رءوس الإبل مع أعناقها بالفئوس.]] وقال: يريد الرّمح صدر أبى براء ... ويعدل عن دماء بنى عقيل [[الارادة هنا مجاز عن التوجه. ويجوز أن الاسناد مجاز، لأن المريد صاحب الرمح. والأوجه أنه شبه الرمح بإنسان على طريق المكنية، وإسناد الارادة والعدول إليه تخييل، أى: يريد أن يشرب من صدر أبى براء، لا من دماء هؤلاء.]] وقال حسان: إنّ دهرا يلفّ شملى بجمل ... لزمان يهمّ بالإحسان [[لحسان بن ثابت، ولففت الشيء: طويته وأدرجته، من باب رد. والشمل. المتفرق، ويطلق على المجتمع من الأمور. وجمل: اسم محبوبته. ويروى: بسعدى. يقول: إن الدهر الذي يجمع شملى بمحبوبتى لدهريهم بالإحسان ويريده، وهم من باب رد أيضا، أى: دهر يريد الإحسان لا الاساءة كعادة الدهر، فشبه الزمان بإنسان يصح منه إرادة الإحسان على طريق المكنية، والهم تخييل. ويحتمل أن إسناد الهم له مجاز عقلى كاسناد اللف، وهما في الحقيقة لله.]] وسمعت من يقول: عزم السراج أن يطفأ، وطلب أن يطفأ. وإذا كان القول والنطق والشكاية والصدق والكذب والسكوت والتمرد والإباء والعزة والطواعية وغير ذلك مستعارة للجماد ولما لا يعقل، فما بال الإرادة؟ قال: إذا قالت الأنساع للبطن الحق [[تقدم شرح هذا الشاهد ب من الجزء الأول فراجعه إن شئت اه مصححه.]] تقول سنّى للنّواة طنّى لا ينطق الّلهو حتّي ينطق العود [[فاستنطق العود قد طال السكوت به ... لا ينطق اللهو حتى ينطق العود لأبى نواس، شبه صوت العود على وجه الاستقامة والحسن بالنطق بالغناء على طريق التصريحية. أو شبه العود بإنسان على طريق المكنية والنطق تخييل، والسين والتاء للطلب، والسكوت ترشيح لذلك، لأنه ضد التكلف. والمراد بنطق اللهو زيادته وحسنه، فهو من باب المشاكلة، وهل هي حقيقة أو مجاز أو كناية أو قسم رابع؟ خلاف بين القوم بين في البيان.]] وشكا إلىّ بعبرة وتحمحم [[فازور من وقع القنا بلبانه ... وشكا إلى بعبرة وتحمحم لو كان يدرى ما المحاورة اشتكى ... ولكان لو علم الكلام مكلمي لعنترة بن شداد من معلقته، يصف فرسه بأنه ازور أى مال من وقوع الرماح بلبانه، وهو موضع اللبب من صدره، وشبهه بالعاقل على طريق المكنية والشكاية تخييل، والعبرة: البكاء. والحمحمة: صوت الصهيل يشبه الحنين، لو كان يعلم ما هي المحاورة والمخاطبة لاشتكى إلىّ وخاطبني حقيقة، وإنما يشكو إلى بالعبرة والتحمحم فقط. وفسره بقوله: ولكان مكلما لي لو علم الكلام، وذلك مبالغة في شدة الحرب.]] فإن يك ظنّى صادقا وهو صادقي [[لهفي على القوم الذين تجمعوا ... بذي السيد لم يلقوا عليا ولا عمرا فان يك ظنى صادقا وهو صادقي ... بشملة يحبسهم بها محبسا وعرا لكنز أم شملة بن برد المنقري، وذو السيد- بالكسر-: موضع المعركة، والسيد: الذئب. وقولها «وهو صادقي» اعتراض. وبشملة: متعلق بظنى. تقول: يا تلهفى على القوم الذين اجتمعوا في ذلك الموضع ولم يلاقهم أحد هذين الفارسين، فقتلوا بردا أبا شملة. فان يك ظنى به صادقا مع أن عادته يصدقني، يحبسهم شملة في تلك المعركة حبسا صعبا فيأخذ ثأر أبيه. ويجوز أن محبسا ظرف يدل من بها. وشبهت الظن بمن يصح منه الصدق في الخبر على طريق الكناية، والصدق تخييل لذلك. أو المعنى: فان يك ظنى مطابقا للواقع.]] وَلَمَّا سَكَتَ عَنْ مُوسَى الْغَضَبُ تمرّد مارد وعزّ الأبلق [[وقد قالت الزبا لحصن سموأل ... تمرد مارد وعز الأبلق مارد: هو حصن دومة الجندل. والأبلق: حصن سموأل، قصدتهما الزبا ملكة الجزيرة فاستصعبا عليها، فقالت ذلك، وصار يضرب مثلا. وقوله: لحصن سموأل، أى: ولحصن دومة الجندل. تمرد: صار أملس ناعما، ومرد مردا ومرودة، إذا كان أملس لا شعر فيه والمكان لا نبات فيه، أو تمرد بمعنى تشيطن، وفعل أهله فعل المردة من الجن، فهو لا يستطيع أحد طلوعه. وعز إن كان مضارعه بضم العين كان متعديا بمعنى غالب، وإن كان بكسرها كان لازما بمعنى امتنع. والمعنى: أنها لم تقدر على بلوغ مرادها منهما لشجاعة أهلهما.]] ولبعضهم: يأبى على أجفانه إغفاءه ... همّ إذا انقاد الهموم تمرّدا» أبت الرّوادف والثّدىّ لقمصها ... مسّ البطون وأن تمسّ ظهورا [[أبت الروادف والثدي لقمصها ... مس البطون وأن تمس ظهورا وإذا الرياح مع العشى تناوحت ... نيهن حاسدة وهجن غيورا الاباء: المنع الاختياري فشبه الروادف والثدي لكبرها بمن يصح منه ذلك على طريق المكنية والاباء تخييل. والأقرب أنه مجاز مرسل، والمراد به مطلق المنع، والكلام بعد ذلك كناية عن نهود ثدييها وكبر رد فيها وضمور خصريها. وفيه لف ونشر غير مرتب، لأن مس البطون يرجع للثدي، ومس الظهور يرجع للروادف. وعبر بالجمع عن غيره مجازا. أو اعتبر الأجزاء، فالتجوز في مفرد الجمع. والثدي بالتشديد: جمع ثدي بالتخفيف. والقمص: جمع قميص. وتناوح الجبلان. تقابلا، فالمراد بالتناوح: التقابل، بحيث يجيء بعض الرياح من أمامها وبعضها من خلفها، فتظهر روادفها ونهودها وتلتصق الثياب بخصرها فيظهر ضموره، فتنبه الحاسدة لها، ويهيج الغيور لكراهة ذلك من الرياح. وهاج الشيء: هام، وهاجه: هيمه، وهيجه: هيمه. وما هنا من الوسط. ويجوز أنه شبه على طريق المكنية. أو شبه أصواتها اللينة بالتناوح على طريق التصريحية، ثم جعل ذلك كناية عن تقابلها لأنها إنما يكون لها أصوات إذا تقابلت فاضطربت، ومع: بمعنى في.]] قالَتا أَتَيْنا طائِعِينَ ولقد بلغني أن بعض المحرفين لكلام الله تعالى ممن لا يعلم، كان يجعل الضمير للخضر، لأنّ ما كان فيه من آفة الجهل وسقم الفهم، أراه أعلى الكلام طبقة أدناه منزلة، فتحمل ليردّه إلى ما هو عنده أصح وأفصح، وعنده أن ما كان أبعد من المجاز كان أدخل في الإعجاز. وانقض: إذا أسرع سقوطه، من انقضاض الطائر وهو يفعلّ، مطاوع قضضته. وقيل: افعلّ من النقض، كاحمرّ من الحمرة. وقرئ: أن ينقض من النقض، وأن ينقاص، من انقاصت السن إذا انشقت طولا. قال ذو الرمة: ......... منقاص ومنكثب [[يغشى الكناس بروقيه ويهدمه ... من هائل الرمل منقاص ومنكثب لذي الرمة يصف ثورا وحشيا. والكناس: بيت الوحش. وروقاه: قرناه. والمنقاص- كالمختار-: المتساقط من جانب طول الكناس. والمنكثب- بالمثلاثة-: المجتمع. وروى: منقاض، بالمعجمة. والمعنى واحد، أى: يحفر الكناس بقرينه، ليستتر من المطر، ويهدمه المتساقط المجتمع من الرمل الرخو الهايل.]] بالصاد غير معجمة فَأَقامَهُ قيل: أقامه بيده. وقيل: مسحه بيده فقام واستوى. وقيل: أقامه بعمود عمده به. وقيل: نقضه وبناه. وقيل كان طول الجدار في السماء مائة ذراع، كانت الحال حال اضطرار وافتقار إلى المطعم، وقد لزتهما الحاجة إلى آخر كسب المرء وهو المسألة، فلم يجدا مواسيا، فلما أقام الجدار لم يتمالك موسى لما رأى من الحرمان ومساس الحاجة أن قالَ لَوْ شِئْتَ لَاتَّخَذْتَ عَلَيْهِ أَجْراً وطلبت على عملك جعلا حتى ننتعش ونستدفع به الضرورة وقرئ: لتخذت، والتاء في تخذ، أصل كما في تبع، واتخذ افتعل منه، كاتبع من تبع، وليس من الأخذ في شيء.',     source_page = '181',     updated_at  = datetime('now') WHERE id = 'QR:TE:4ec731e30ba406f260ca6799';
UPDATE qr_tafsir_entries SET content_ar = 'عن ابن عباس: فاطمأنت إلى قوله فدنا منها فنفخ في جيب درعها، فوصلت النفخة إلى بطنها فحملت. وقيل: كانت مدّة الحمل ستة أشهر. وعن عطاء وأبى العالية والضحاك: سبعة أشهر. وقيل: ثمانية، ولم يعش مولود وضع لثمانية إلا عيسى. وقيل: ثلاث ساعات. وقيل: حملته في ساعة، وصوّر في ساعة، ووضعته في ساعة، حين زالت الشمس من يومها. وعن ابن عباس: كانت مدة الحمل ساعة واحدة، كما حملته نبذته. وقيل: حملته وهي بنت ثلاث عشرة سنة. وقيل: بنت عشر، وقد كانت حاضت حيضتين قبل أن تحمل. وقالوا: ما من مولود إلا يستهلّ غيره [[قوله «ما من مولود إلا يستهل غيره» في الصحاح «استهل الصبى» أى صاح عند الولادة. (ع)]] فَانْتَبَذَتْ بِهِ أى اعتزلت وهو في بطنها، كقوله: تدوس بنا الجماحم والتّريبا [[تقدم شرح هذا الشاهد ب من الجزء الأول فراجعه إن شئت اه مصححه.]] أى تدوس الجماجم ونحن على ظهورها، ونحوه قوله تعالى تَنْبُتُ بِالدُّهْنِ أى تنبت ودهنها فيها: الجار والمجرور في موضع الحال قَصِيًّا بعيدا من أهلها وراء الجبل. وقيل: أقصى الدار. وقيل: كانت سميت لابن عم لها اسمه يوسف، فلما قيل: حملت من الزنا، خاف عليها قتل الملك، فهرب بها فلما كان ببعض الطريق حدّثته نفسه بأن يقتلها، فأتاه جبريل فقال: إنه من روح القدس فلا تقتلها، فتركها.',     source_page = '138',     updated_at  = datetime('now') WHERE id = 'QR:TE:8456eeb900f4c1296d2f9cfe';
UPDATE qr_tafsir_entries SET content_ar = 'تُساقِطْ فيه تسع قراآت: تساقط، بإدغام التاء. وتتساقط، بإظهار التاءين. وتساقط، بطرح الثانية. ويساقط، بالياء وإدغام التاء. وتساقط، وتسقط، ويسقط، وتسقط، ويسقط: التاء للنخلة، والياء للجذع. ورطبا تمييز أو مفعول على حسب القراءة. وعن المبرد: جواز انتصابه بهزّى وليس بذاك. والباء في بِجِذْعِ النَّخْلَةِ صلة للتأكيد، كقوله تعالى وَلا تُلْقُوا بِأَيْدِيكُمْ إِلَى التَّهْلُكَةِ أو على معنى: افعلي الهزّ به، كقوله: يجرح في عراقيبها نصلى [[تقدم شرح هذا الشاهد بالجزء الثاني فراجعه إن شئت اه مصححه.]] قالوا: التمر للنفساء عادة من ذلك الوقت، وكذلك التحنيك، وقالوا: كان من العجوة. وقيل: ما للنفساء خير من الرطب، ولا للمريض خير من العسل، وقيل: إذا عسر ولادها لم يكن لها خير من الرطب. عن طلحة بن سليمان جَنِيًّا بكسر الجيم للإتباع، أى جمعنا لك في السرىّ والرطب فائدتين، إحداهما: الأكل والشرب، والثانية سلوة الصدر، لكونهما معجزتين، وهو معنى قوله فَكُلِي وَاشْرَبِي وَقَرِّي عَيْناً أى وطيبي نفسا ولا تغتمي وارفضى عنك ما أحزنك وأهمك. وقرئ: وَقَرِّي بالكسر لغة نجد فَإِمَّا تَرَيِنَّ بالهمز: ابن الرومي. عن أبى عمرو: وهذا من لغة من يقول: لبأت بالحج، وحلأت السويق [[قوله «يقول لبأت بالحج وحلأت السويق» والكثير: لبيت بالحج، وحليت السويق، أى: جعلته حلوا. (ع)]] ، وذلك لتآخ بين الهمز وحرف اللين في الإبدال صَوْماً صمتا. وفي مصحف عبد الله: صمتا. وعن أنس بن مالك مثله. وقيل: صياما، إلا أنهم كانوا لا يتكلمون في صيامهم، وقد نهى رسول الله ﷺ عن صوم الصمت [[لم أره هكذا وأخرج عبد الرزاق من حديث جابر بلفظ «لا صمت يوم إلى الليل» وفيه حزام بن عثمان وهو ضعيف ولأبى داود من حديث على مثله. وقد تقدم في تفسير النساء.]] ، لأنه نسخ في أمته، أمرها الله بأن تنذر الصوم لئلا تشرع مع البشر المنهمين لها في الكلام لمعنيين، أحدهما: أن عيسى صلوات الله عليه يكفيها الكلام بما يبرئ به ساحتها. والثاني: كراهة مجادلة السفهاء ومناقلتهم. وفيه أن السكوت عن السفيه واجب. ومن أذل الناس: سفيه لم يجد مسافها. قيل: أخبرتهم بأنها نذرت الصوم بالإشارة. وقيل: سوغ لها ذلك بالنطق إِنْسِيًّا أى أكلم الملائكة دون الإنس',     source_page = '578',     updated_at  = datetime('now') WHERE id = 'QR:TE:a3cb5828de206ee256b6e6cd';
UPDATE qr_tafsir_entries SET content_ar = 'اللغو: فضول الكلام وما لا طائل تحته. وفيه تنبيه ظاهر على وجوب تجنب اللغو واتقائه، حيث نزه الله عنه الدار التي لا تكليف فيها. وما أحسن قوله سبحانه وَإِذا مَرُّوا بِاللَّغْوِ مَرُّوا كِراماً وَإِذا سَمِعُوا اللَّغْوَ أَعْرَضُوا عَنْهُ وَقالُوا لَنا أَعْمالُنا وَلَكُمْ أَعْمالُكُمْ سَلامٌ عَلَيْكُمْ لا نَبْتَغِي الْجاهِلِينَ نعوذ بالله من اللغو والجهل والخوض فيما لا يعنينا. أى: إن كان تسليم بعضهم على بعض أو تسليم الملائكة عليهم لغوا، فلا يسمعون لغوا إلا ذلك، فهو من وادى قوله: ولا عيب فيهم غير أنّ سيوفهم ... بهنّ فلول من قراع الكتائب [[تقدم شرح هذا الشاهد ب من الجزء الثاني فراجعه إن شئت اه مصححه.]] أو لا يسمعون فيها إلا قولا يسلمون فيه من العيب والنقيصة، على الاستثناء المنقطع [[قال محمود: «يجوز أن يكون من قوله: ولا عيب فيهم غير أن سيوفهم ... بهن فلول من قراع الكتائب وأن يكون استثناء منقطعا» قال أحمد: والفرق بين الوجهين أنه جعل الفلول عيبا على سبيل التجوز، بتا لنفى العيب بالكلية، كأنه يقول: إن كان فلول السيوف من القراع عيبا فإنهم ذوو عيب، معناه: وإن لم يكن عيبا فليس فيهم عيب البتة، لأنه لا شيء سوى هذا، فهو بعد هذا التجوز والفرض استثناء متصل.]] . أو لأن معنى السلام هو الدعاء بالسلامة [[عاد كلامه. قال: «ويجوز أن يكون متصلا على أن يكون السلام هو الدعاء بالسلامة ... الخ» قال أحمد: وهذا يجعله من المتصل على أصل الحقيقة. لا كالأول الناشئ عن المجاز. وفي هذا الباب بعد، لأنه يقتضى البت بأن الجنة يسمع فيها لغو وفضول، وحاش لله، فلا غول فيها ولا لغو.]] . ودار السلام: هي دار السلامة، وأهلها عن الدعاء بالسلامة أغنياء، فكان ظاهره من باب اللغو وفضول الحديث، لولا ما فيه من فائدة الإكرام. من الناس من يأكل الوجبة [[قوله «من الناس من يأكل الوجبة» أى يأكل كل يوم وليلة مرة، وقد وجب نفسه توجيبا إذا عودها ذلك، كذا في الصحاح. (ع)]] . ومنهم من يأكل متى وجد- وهي عادة المنهومين. ومنهم من يتغدى ويتعشى- وهي العادة الوسطى المحمودة، ولا يكون ثم ليل ولا نهار، ولكن على التقدير، ولأن المتنعم عند العرب من وجد غداء وعشاء. وقيل: أراد دوام الرزق ودروره، كما تقول: أنا عند فلان صباحا ومساء وبكرة وعشيا، يريد: الديمومة، ولا تقصد الوقتين المعلومين.',     source_page = '142',     updated_at  = datetime('now') WHERE id = 'QR:TE:d169678d616d5c371cb8556f';
UPDATE qr_tafsir_entries SET content_ar = 'وَيَزِيدُ معطوف على موضع فليمدد، لأنه واقع موقع الخبر، تقديره: من كان في الضلالة مدّ أو يمدّ له الرحمن. ويزيد: أى يزيد في ضلال الضال بخذلانه، ويزيد المهتدين هداية بتوفيقه وَالْباقِياتُ الصَّالِحاتُ أعمال الآخرة كلها. وقيل: الصلوات. وقيل: سبحان الله والحمد لله ولا إله إلا الله والله أكبر، أى هي خَيْرٌ ثَواباً من مفاخرات الكفار وَخَيْرٌ مَرَدًّا أى مرجعا وعاقبة، أو منفعة، من قولهم: ليس لهذا الأمر مردّ: وهل يرد بكاى زندا [[تقدم شرح هذا الشاهد بالجزء الثاني فراجعه إن شئت اه مصححه]] فإن قلت: كيف قيل خير ثوابا كأنّ لمفاخراتهم ثوابا، حتى يجعل ثواب الصالحات خيرا منه؟ قلت: كأنه قيل: ثوابهم النار. على طريقة قوله: ... فأعتبوا بالصّيلم [[تقدم شرح هذا الشاهد بالجزء الأول فراجعه إن شئت اه مصححه]] وقوله: شجعاء جرّتها الذّميل تلوكه ... أصلا إذا راح المطي غراثا [[الشجع: سرعة نقل القوائم. والشجعاء: السريعة السير. والجرة- بالكسر-، ما يجتره البعير من كرشه يمضغه. والذميل: نوع من السير. واللوك: المضغ. والأصل: جمع أصيل، وهو من العصر للغروب. والرواح: من الظهر إليه. والغراث: الجياع. يصف ناقته بسرعة السير، وشبه السير عندها بجرتها، يجامع سرعة الحركة وانطباع الناقة واستلذاذها لكل. وجعلها تبرزه شيئا فشيئا كالجرة للمبالغة. وفيه دلالة على خلو بطنها من العلف إذا راح، أى: إذا كان غيرها لا يجد قوة على السير، فالغرث: استعارة. ويجوز أن المعنى أنها سريعة في السير ولو كانت جائعة كغيرها من المطايا، فالغرث حقيقته.]] وقوله: تحيّة بينهم ضرب وجيع [[تقدم شرح هذا الشاهد بالجزء الأول فراجعه إن شئت اه مصححه]] ثم بنى عليه خير ثوابا. وفيه ضرب من التهكم الذي هو أغيظ للمتهدد من أن يقال له: عقابك النار. فإن قلت: فما وجه التفضيل في الخير كأن لمفاخرهم شركا فيه؟ قلت: هذا من وجيز كلامهم، يقولون: الصيف أحرّ من الشتاء، أى: أبلغ من الشتاء في برده.',     source_page = '525',     updated_at  = datetime('now') WHERE id = 'QR:TE:0a69161a11a0a170ac06c003';
UPDATE qr_tafsir_entries SET content_ar = 'قرئ إِدًّا بالكسر والفتح. قال ابن خالويه: الإدّ والأدّ: العجب. وقيل: العظيم المنكر. والإدّة: الشدّة. وأدنى الأمر وآدنى: أثقلنى وعظم علىّ إدّا تَكادُ قراءة الكسائي ونافع بالياء. وقرئ «ينفطرن» [[قوله «وقرئ ينفطرن» يفيد أن القراءة المشهورة «يتفطرن» بالتاء. (ع)]] الانفطار من فطره إذا شقه. والتفطر، من فطره إذا شققه وكرر الفعل فيه. وقرأ ابن مسعود: ينصدعن، أى تهد هدّا، أو مهدودة، أو مفعول له، أى: لأنها تهدّ. فإن قلت: ما معنى انفطار السموات وانشقاق الأرض وخرور الجبال؟ ومن أين تؤثر هذه الكلمة في الجمادات؟ قلت: فيه وجهان، أحدهما: أن الله سبحانه يقول: كدت أفعل هذا بالسماوات والأرض [[قال محمود: «معناه: كدت أهدّ السموات وأفطر الأرض ... الخ» قال أحمد: ويظهر لي وراءها معنى آخر والله أعلم، وذلك أن الله تعالى قد استعار لدلالتها على وجوده عز وجل موصوفا بصفات الكمال الواجبة له، أن جعلها تسبح بحمده. قال تعالى تُسَبِّحُ لَهُ السَّماواتُ السَّبْعُ وَالْأَرْضُ وَمَنْ فِيهِنَّ وَإِنْ مِنْ شَيْءٍ إِلَّا يُسَبِّحُ بِحَمْدِهِ ومما دلت عليه السموات والأرض والجبال بل وكل ذرة من ذراتها: أن الله تعالى مقدس عن نسبة الولد إليه: وفي كل شيء له آية ... تدل على أنه واحد فالمعتقد نسبة الولد إلى الله تعالى قد عطل دلالة هذه الموجودات على تنزيه الله وتقديسه، فاستعير لابطال ما فيها من روح الدلالة التي خلقت لأجلها، إبطال صورها بالهد والانفطار والانشقاق «فسبحان من قسم عباده، فجعل العباد، تستلذ فتسبح بتسبيح داود، يكاد ينهد لمقاله من هو عن باب التوفيق مطرود مردود.]] والجبال عند وجود هذه الكلمة غضبا منى على من تفوّه بها، لولا حلى ووقارى، وأنى لا أعجل بالعقوبة كما قال إِنَّ اللَّهَ يُمْسِكُ السَّماواتِ وَالْأَرْضَ أَنْ تَزُولا وَلَئِنْ زالَتا إِنْ أَمْسَكَهُما مِنْ أَحَدٍ مِنْ بَعْدِهِ إِنَّهُ كانَ حَلِيماً غَفُوراً. والثاني: أن يكون استعظاما للكلمة، وتهويلا من فظاعتها، وتصويرا لأثرها في الدين وهدمها لأركانه وقواعده، وأن مثال ذلك الأثر في المحسوسات: أن يصيب هذه الأجرام العظيمة التي هي قوام العالم ما تنفطر منه وتنشق وتخرّ. وفي قوله لَقَدْ جِئْتُمْ وما فيه من المخاطبة بعد الغيبة، وهو الذي يسمى الالتفات في علم البلاغة زيادة تسجيل عليهم بالجرأة على الله، والتعرّض لسخطه، وتنبيه على عظم ما قالوا. في أَنْ دَعَوْا ثلاثة أوجه: أن يكون مجرورا بدلا من الهاء في منه، كقوله: على حالة لو أنّ في القوم حاتما ... على جوده لضنّ بالماء حاتم [[تقدم شرح هذا الشاهد بالجزء الأول فراجعه إن شئت اه مصححه.]] ومنصوبا بتقدير سقوط اللام وإفضاء الفعل، أى: هذا لأن دعوا، علل الخرور بالهدّ، والهدّ بدعاء الولد للرحمن. ومرفوعا بأنه فاعل هذا، أى هدها دعاء الولد للرحمن. وفي اختصاص الرحمن وتكريره مرات من الفائدة أنه هو الرحمن وحده، لا يستحق هذا الاسم غيره، من قبل أنّ أصول النعم وفروعها منه: خلق العالمين، وخلق لهم جميع ما معهم، كما قال بعضهم: فلينكشف عن بصرك غطاؤه، فأنت وجميع ما عندك عطاؤه. فمن أضاف إليه ولدا فقد جعله كبعض خلقه وأخرجه بذلك عن استحقاق اسم الرحمن. هو من دعا بمعنى سمى المتعدي إلى مفعولين، فاقتصر على أحدهما الذي هو الثاني، طلبا للعموم والإحاطة بكل ما دعى له ولدا. أو من دعا بمعنى نسب، الذي مطاوعه ما في قوله عليه السلام «من ادعى إلى غير مواليه [[لم أره بلفظ «من ادعي» وإنما هو عند مسلم بلفظ «انتمى» أخرجه من حديث على بن أبى طالب رفعه «من ادعى إلى غير أبيه أو انتمى إلى غير مواليه- الحديث»]] » وقول الشاعر: إنّا بنى نهشل لا ندّعى لأب [[إنا بنى نهشل لا ندعى لأب ... عنه ولا هو بالأبناء يشرينا يكفيه إن نحن متنا أن يسر بنا ... وهو إذا ذكر الآباء يكفينا لبشامة بن حزن النهشلي، ويقال: ادعى فلان في بنى هاشم ولهم وإليهم، أى: انتسب إليهم وادعى عنهم إذا انتسب لغيرهم. وعدل عنهم يقول: إنا لا ننتسب لأب غير نهشل، وبنى نهشل: نصب على الاختصاص يفيد المدح ولا هو يشرينا، أى يبيعنا ويستبدلنا بأبناء غيرنا، ثم قال: يكفيه منا سروره بنا إن متنا ولحقناه، حيث أوجبنا له ولنا الثناء الجميل من شجاعتنا وحسن خصالنا. و «إن» بمعنى «إذا» لأن الموت لا شك فيه. ويروى «أن يسب» بباء، ولعل معناه: لا مسبة له غير موتنا في القتال، يعنى: إن كان ذلك مسبة وليس كذلك، ويمكن أن تعبيره بالكفاية ليفيد أنه مستغن عن المدح من جهة أبنائه عند التفاخر. وعند عد مآثر الآباء لا نحتاج لغيره، فننتسب له لنشرف بشرفه.]] أى لا ننتسب إليه.',     source_page = '438',     updated_at  = datetime('now') WHERE id = 'QR:TE:4f5d432b2f475343d5a41806';
UPDATE qr_tafsir_entries SET content_ar = 'بَلْ إضراب عن اتخاذ اللهو واللعب، وتنزيه منه لذاته، كأنه قال: سبحاننا أن نتخذ اللهو واللعب [[قال محمود: «معناه سبحاننا أن نتخذ لهوا ولعبا ... الخ» قال أحمد: وله تحت قوله واستغنائنا عن القبيح دفين من البدعة والضلالة، ولكنه من الكنوز التي يحمى عليها في نار جهنم، وذلك أن القدرية يوجبون على الله تعالى رعاية المصالح وفعل ما يتوهمونه حسنا بعقولهم، ويظنون أن الحكمة تقتضي ذلك، فلا يستغنى الحكيم على زعمهم عن خلق الحسن على وفق الحكمة بخلاف القبيح، فان الحكمة تقتضي الاستغناء عنه، فالى ذلك يلوح الزمخشري وما هي إلا نزعة سبق إليها ضلال الفلاسفة. ومن ثم يقولون: ليس في الإمكان أكمل من هذا العالم، لأنه لو كان في القدرة أكمل منه وأحسن، ثم لم يخلقه الله تعالى: لكان بخلا ينافي الجود، أو عجزا ينافي القدرة، حتى انبعهم في ذلك من لا نسميه من أهل الملة- عفا الله عنه- إن كان هذا مما يدخل تحت ذيل العفو. فالحق أن الله تعالى مستغن عن جميع الأفعال حسنة كانت أو غيرها، مصلحة كانت أو مفسدة. وأن له أن لا يخلق ما يتوهمه القدرية حسنا، وله أن يفعل ما يتوهمونه في الشاهد قبيحا، وأن كل موجود من فاعل وفعل على الإطلاق فبقدرته وجد، فليس في الوجود إلا الله وصفاته وأفعاله، وهو مستغن عن العالم بأسره، وحسنه وقبحه، فلو أن أولكم وآخركم وإنسكم وجنكم على أتقى قلب رجل منكم لم يزد ذلك في ملكه شيئا، ولو أن أولكم وآخركم وإنسكم وجنكم على أفجر قلب رجل منكم لم ينقص ذلك من ملكه شيئا. اللهم ألهمنا الحق واستعملنا به.]] ، بل من عادتنا وموجب حكمتنا واستغنائنا عن القبيح أن نغلب اللعب بالجد، وندحض الباطل بالحق. واستعار لذلك القذف [[عاد كلامه. قال: «وفي قوله تعالى بل نقذف بالحق على الباطل استعارة حسنة: استعار القذف ... الخ» قال أحمد: ومثل هذا التنبيه من حسناته، ولولا أن السيئة التي قبلها تتعلق بالعقيدة لتلوت: إن الحسنات يذهبن السيئات، والله أعلم.]] والدمغ، تصويرا لإبطاله وإهداره ومحقه فجعله كأنه جرم صلب كالصخرة مثلا، قذف به على جرم رخو أجوف فدمغه [[قوله «فدمغه» في الصحاح: أى شجه حتى بلغت الشجة الدماغ. (ع)]] ، ثم قال وَلَكُمُ الْوَيْلُ مِمَّا تَصِفُونَ به مما لا يجوز عليه وعلى حكمته. وقرئ: فيدمغه بالنصب، وهو في ضعف قوله: سأترك منزلي لبنى تميم ... وألحق بالحجاز فاستريحا [[تقدم شرح هذا الشاهد بالجزء الأول فراجعه إن شئت اه مصححه.]] وقرئ فيدمغه.',     source_page = '557',     updated_at  = datetime('now') WHERE id = 'QR:TE:2bb80726ee03a6c768b292c6';
UPDATE qr_tafsir_entries SET content_ar = 'مِنْ رَسُولٍ وَلا نَبِيٍّ دليل بين على تغاير الرسول والنبي. وعن النبي ﷺ أنه سئل عن الأنبياء فقال «مائة ألف وأربعة وعشرون ألفا» قيل فكم الرسول منهم؟ قال: «ثلاثمائة وثلاثة عشر جما غفيرا» [[أخرجه أحمد وإسحاق من رواية معاذ بن رفاعة عن على بن زيد عن القاسم عن أبى أمامة «أن أبا ذر سأل رسول الله ﷺ: كم الأنبياء؟ فقال: مثله. وعلى ضعيف. ورواه ابن حبان من طريق إبراهيم بن هشام الغساني حدثنا أبى عن حذيفة. يعنى يحيى الغساني عن أبى إدريس الخولاني عن أبى ذر- فذكره في حديث طويل جدا. وأفرط ابن الجوزي فذكره في الموضوعات واتهم به إبراهيم بن هشام المذكور. ولم يصب في ذلك: فإنها طريقا أخرجها الحاكم وغيره من رواية يحيى بن سعيد السعيدي عن ابن جريج عن عطاء عن عبيد بن عمير عن أبى ذر بطوله. ويحيى السعيدي ضعيف. ولكن لا يأتى الحكم بالوضع مع هذه المتابعة.]] . والفرق بينهما أن الرسول من الأنبياء: من جمع إلى المعجزة الكتاب المنزل عليه. والنبىّ غير الرسول: من لم ينزل عليه كتاب وإنما أمر أن يدعو الناس إلى شريعة من قبله. والسبب في نزول هذه الآية أنّ رسول الله ﷺ لما أعرض عنه قومه وشاقوه وخالفه عشيرته ولم يشايعوه على ما جاء به: تمنى لفرط ضجره من إعراضهم ولحرصه وتهالكه على إسلامهم أن لا ينزل عليه ما ينفرهم، لعله يتخذ ذلك طريقا إلى استمالتهم واستنزالهم عن غيهم وعنادهم، فاستمرّ به ما تمناه حتى نزلت عليه سورة «والنجم» وهو في نادى قومه، وذلك التمني في نفسه، فأخذ يقرؤها فلما بلغ قوله وَمَناةَ الثَّالِثَةَ الْأُخْرى : أَلْقَى الشَّيْطانُ فِي أُمْنِيَّتِهِ التي تمناها، أى: وسوس إليه بما شيعها به، فسبق لسانه على سبيل السهو والغلط إلى أن قال: تلك الغرانيق [[أخرجه البزار والطبري والطبراني وابن مردويه من طريق أمية بن خالد عن شعبة عن أبى بشر عن سعيد ابن جبير قال: لا أعلمه إلا عن ابن عباس «أن النبي ﷺ كان بمكة فقرأ سورة النجم، حتى انتهى إلى قوله تعالى أَفَرَأَيْتُمُ اللَّاتَ وَالْعُزَّى وَمَناةَ الثَّالِثَةَ الْأُخْرى فجرى على لسانه: تلك الغرانيق العلا، الشفاعة منها ترتجى، قال: فسمع بذلك مشركو مكة، فسروا بذلك. فاشتبه على رسول الله ﷺ فأنزل الله تعالى وَما أَرْسَلْنا مِنْ قَبْلِكَ مِنْ رَسُولٍ وَلا نَبِيٍّ إِلَّا إِذا تَمَنَّى- الآية» زاد في رواية ابن مردويه: فلما بلغ آخرها سجد وسجد معه المسلمون والمشركون» ورواه الطبري من طريق سعيد بن جبير مرسلا. وأخرجه ابن مردويه من طريق أبى عاصم النبيل عن عثمان بن الأسود عن سعيد بن جبير عن ابن عباس نحوه. ولم يشك في وصله، وهذا أصح طرف هذا الحديث. قال البزار: تفرد بوصله أمية بن خالد عن شعبة، وغيره يرويه عنه مرسلا. وأخرجه الطبري وابن مردويه من وجه آخر عن ابن عباس. وهو من طريق العوفى عن جده عطية عنه، وأخرجه الطبري من طريق محمد بن كعب القرظي، ومن طريق قتادة، ومن طريق أبى العالية. فهذه مراسيل يقوى بعضها بعضا. وأصل القصة في الصحيح بلفظ «أن النبي ﷺ وهو بمكة- فسجد وسجد معه المسلمون والمشركون والجن والانس» قال البزار: المعروف في هذا رواية الكلبي عن أبى صالح عن ابن عباس. وأخرجها ابن مردويه من طريقه. وأخرجه الواقدي من طريق أخرى. قلت: وفي مجموع ذلك رد على عياض حيث قال: إن من ذكر من المفسرين وغيرهم لم يسندها أحد منهم، ولا رفعها إلى صاحب إلا رواية البزار. وقد بين البزار أنه لا يعرف من طريق يجوز ذكره سوى ما ذكره وفيه ما فيه مع وقوع الشك. قلت: أما ضعفه فلا ضعف فيه أصلا. فان الجميع ثقات وأما الشك فيه فقد يجيء تأثيره ولو فردا غريبا لكن غايته أنه يصير مرسلا، إنما هو حجة عند عياض وغيره ممن يقبل مرسل الثقة، أما هو حجة إذا اعتضد عند من يرد المرسل إنما يعتضد بكثرة المتابعات. تبع ثقة رجالها. وأما طعنه فيه باختلاف الألفاظ فلا تأثير للروايات الضعيفة الواهية في الرواية القوية. فيعتمد من القصة على الرواية الصحيحة أى يعتمد على الرواية المتابعة وليس فيها ولا فيما تابعها اضطراب والاضطراب في غيرها. فيكفى لأنه ضعيف برواية الكلبي، ويكفى ما عداها، وأما طعنه فيه من جهة المعنى فله أسوة كثيرة من الأحاديث الصحاح التي لا يؤخذ بظاهرها، بل يرد بالتأويل المعتمد إلى ما يليق بقواعد الدين.]] العلى، وإن شفاعتهنّ لترتجى. وروى: الغرانقة، ولم يفطن له حتى أدركته العصمة فتنبه عليه. وقيل: نبهه جبريل عليه السلام. أو تكلم الشيطان بذلك فأسمعه الناس، فلما سجد في آخرها سجد معه جميع من في النادي وطابت نفوسهم، وكان تمكين الشيطان من ذلك محنة من الله وابتلاء، زاد المنافقون به شكا وظلمة، والمؤمنون نورا وإيقانا. والمعنى: أن الرسل والأنبياء من قبلك كانت هجيراهم كذلك إذا تمنوا مثل ما تمنيت، مكن الله الشيطان ليلقى في أمانيهم مثل ما ألقى في أمنيتك، إرادة امتحان من حولهم، والله سبحانه له أن يمتحن عباده بما شاء من صنوف المحن وأنواع الفتن، ليضاعف ثواب الثابتين ويزيد في عقاب المذبذبين. وقيل تَمَنَّى: قرأ. وأنشد: تمنّى كتاب الله أوّل ليلة ... تمنّى داود الزّبور على رسل [[تقدم شرح هذا الشاهد بالجزء الأول فراجعه إن شئت اه مصححه،]] وأمنيته: قراءته. وقيل: تلك الغرانيق: إشارة إلى الملائكة، أى: هم الشفعاء لا الأصنام فَيَنْسَخُ اللَّهُ ما يُلْقِي الشَّيْطانُ أى يذهب به ويبطله ثُمَّ يُحْكِمُ اللَّهُ آياتِهِ أى يثبتها.',     source_page = '157',     updated_at  = datetime('now') WHERE id = 'QR:TE:c325663800ad076ab001eaea';
UPDATE qr_tafsir_entries SET content_ar = 'وَجاهِدُوا أمر بالغزو وبمجاهدة النفس والهوى وهو الجهاد الأكبر. عن النبي ﷺ أنه رجع من بعض غزواته فقال «رجعنا من الجهاد الأصغر إلى الجهاد الأكبر [[هكذا ذكره الثعلبي بغير سند، وأخرجه البيهقي في الزهد من حديث جابر، قال «قدم على رسول الله ﷺ قوم غزاة. فقال: قدمتم بخير مقدم من الجهاد الأصغر إلى الجهاد الأكبر. قيل: وما الجهاد الأكبر؟ قال: مجاهدة العبد هواه» قال: فيه ضعف، قلت: هو من رواية عيسى بن إبراهيم عن يحيى بن يعلى عن ليث ابن أبى سليم، والثلاثة ضعفاء، وأورده النسائي في الكنى من قول إبراهيم بن أبى عبلة، أحد التابعين من أهل الشام.]] » فِي اللَّهِ أى في ذات الله ومن أجله. يقال: هو حق عالم، وجدّ عالم، أى: عالم حقا وجدا. ومنه حَقَّ جِهادِهِ. فإن قلت: ما وجه هذه الإضافة، وكان القياس: حق الجهاد فيه. أو حق جهادكم فيه، كما قال وَجاهِدُوا فِي اللَّهِ؟ قلت: الإضافة تكون بأدنى ملابسة واختصاص، فلما كان الجهاد مختصا بالله من حيث أنه مفعول لوجهه ومن أجله، صحت إضافته إليه. ويجوز أن يتسع في الظرف كقوله: ويوما شهدناه سليما وعامرا [[تقدم شرح هذا الشاهد بالجزء الثاني فراجعه إن شئت اه مصححه.]] اجْتَباكُمْ اختاركم لدينه ولنصرته وَما جَعَلَ عَلَيْكُمْ فِي الدِّينِ مِنْ حَرَجٍ فتح باب التوبة للمجرمين، وفسح بأنواع الرخص والكفارات والديات والأروش. ونحوه قوله تعالى يُرِيدُ اللَّهُ بِكُمُ الْيُسْرَ وَلا يُرِيدُ بِكُمُ الْعُسْرَ وأمّة محمد ﷺ هي الأمة المرحومة الموسومة بذلك في الكتب المتقدمة. نصب الملة بمضمون ما تقدّمها. كأنه قيل: وسع دينكم توسعة ملة أبيكم، ثم حذف المضاف وأقام المضاف إليه مقامه. أو على الاختصاص، أى: أعنى بالدين ملة أبيكم كقولك: الحمد لله الحميد. فإن قلت: لم يكن إِبْراهِيمَ أبا للأمّة كلها. قلت: هو أبو رسول الله ﷺ، فكان أبا لأمته، لأنّ أمة الرسول في حكم أولاده هُوَ يرجع إلى الله تعالى: وقيل: إلى إبراهيم. ويشهد للقول الأوّل قراءة أبىّ بن كعب: الله سماكم مِنْ قَبْلُ وَفِي هذا أى من قبل القرآن في سائر الكتب وفي القرآن، أى: فضلكم على الأمم وسماكم بهذا الاسم الأكرم لِيَكُونَ الرَّسُولُ شَهِيداً عَلَيْكُمْ أنه قد بلغكم وَتَكُونُوا شُهَداءَ عَلَى النَّاسِ بأنّ الرسل قد بلغتهم. وإذ خصكم بهذه الكرامة والأثرة، فاعبدوه وثقوا به ولا تطلبوا النصرة والولاية إلا منه، فهو خير مولى وناصر. عن رسول الله ﷺ: «من قرأ سورة الحج أعطى من الأجر كحجة حجها وعمرة اعتمرها بعدد من حج واعتمر فيما مضى وفيما بقي [[أخرجه الثعلبي وابن مردويه من حديث أبى بن كعب بالإسناد المذكور في سورة آل عمران.]] » .',     source_page = '408',     updated_at  = datetime('now') WHERE id = 'QR:TE:7f8083fce04bd13464af4c7b';
UPDATE qr_tafsir_entries SET content_ar = 'والمعنى: لو كشف الله عنهم هذا الضرّ وهو الهزال والقحط الذي أصابهم برحمته عليهم ووجدوا الخصب، لارتدوا إلى ما كانوا عليه من الاستكبار وعداوة رسول الله ﷺ والمؤمنين وإفراطهم فيها، ولذهب عنهم هذا الإبلاس وهذا التملق بين يديه ويسترحمونه، واستشهد على ذلك بأنا أخذناهم أوّلا بالسيوف وبما جرى عليهم يوم بدر من قتل صناديدهم وأسرهم، فما وجدت منهم بعد ذلك استكانة ولا تضرع، حتى فتحنا عليهم باب الجوع الذي هو أشدّ من الأسر والقتل وهو أطم العذاب، فأبلسوا الساعة وخضعت رقابهم، وجاء أعتاهم وأشدّهم شكيمة في العناد يستعطفك. أو محناهم بكل محنة من القتل والجوع فما رئي فيهم لين مقادة وهم كذلك، حتى إذا عذبوا بنار جهنم فحينئذ يبلسون، كقوله وَيَوْمَ تَقُومُ السَّاعَةُ يُبْلِسُ الْمُجْرِمُونَ، لا يُفَتَّرُ عَنْهُمْ وَهُمْ فِيهِ مُبْلِسُونَ. والإبلاس: اليأس من كل خير. وقيل: السكوت مع التحير. فإن قلت: ما وزن استكان؟ قلت: استفعل من الكون [[قال محمود: «استكان استفعل من الكون، أى: انتقل من كون إلى كون، كما يقال: استحال، إذا انتقل من حال إلى حال» قال أحمد: هذا التأويل أسلم وأحق من تأويل من اشتقه من السكون وجعله افتعل، ثم أشبعت الفتحة فتولدت الألف كتولدها في قوله ينباع من ذفرى غضوب جسرة فان هذا الاشباع ليس بفصيح، وهو من ضرورات الشعر، فينبغي أن ترفع منزلة القرآن عن ورود مثله فيه، لكن تنظير الزمخشري له باستحال: وهم، فان استكان على تأويله أحد أقسام استفعل، الذي معناه التحول، كقولهم: استحجر الطين، واستنوق الجمل. وأما استحال فثلاثيه حال يحول، إذا انتقل من حال إلى حال، وإذا كان الثلاثي يفيد معنى التحول لم يبق لصيغة استفعل فيها أثر، فليس استحال من استفعل للتحول. ولكنه من استفعل بمعنى فعل، وهو أحد أقسامه، إذ لم يزد السداسى فيه على الثلاثي معنى، والله أعلم. ثم نعود إلى تأويله فنقول: المعنى عليه: فما انتقلوا من كون التكبر والتجبر والاعتياص إلى كون الخضوع والضراعة إلى الله تعالى. ولقائل أن يقول: استكان يفيد على التأويل المذكور الانتقال من كون إلى كون، فليس حمله على أنه انتقال عن التكبر إلى الخضوع بأولى من العكس. وترى هذه الصيغة لا تفهم إلا أحد الانتقالين، فلو كانت مشتقة من مطلق الكون لكانت مجملة محتملة للانتقالين جميعا. والجواب أن أصلها كذلك على الإطلاق، ولكن غلب العرف على استعمالها في الانتقال الخاص كما غلب في غيرها، والله أعلم. وكان جدي أبو العباس أحمد بن فارس الفقيه الوزير رحمه الله يذكر لي أنه لما دخل بغداد زمن الامام الناصر رضى الله عنه، أظهر من جملة كراماته له: أن جمع له الوزير جميع علماء بغداد وعقد بهم محفلا للمناظرة، وكان يذكر لي أن مما انجر الكلام إليه حينئذ هذه الآية، وأن أحدهم وكان يعرف بالأجل اللغوي خصه الوزير بالسؤال عنها فقال: وهو مشتق من قول العرب: كنت لك إذا خضعت، وهي لغة هذلية فاستحسن منه ذلك. قال أحمد: وقد وقفت عليها بعد ذلك في غريب أبى عبيد المروي وهو أحسن محامل الآية وأسلمها، والله أعلم. وعلى هذا يكون من استفعل بمعنى فعل، كقولهم: استقر واستعلى، وحال واستحال على ما مر. وقد قال لي بعضهم يوما: لم لا تجعله على هذا التأويل من استفعل المبنى للمبالغة. مثل استحسر واستعصم من حسر وعصم، فقلت: لا يسعني ذلك: لأن المعنى يأباه، وذلك أنها جاءت في النفي والمقصود منها ذم هؤلاء بالجفوة والقسوة وعدم الخضوع، مع ما يوجب نهاية الضراعة من أخذهم بالعذاب، فلو ذهبت إلى جعلها للمبالغة أفادت نقص المبالغة، لأن نفى الأبلغ أدنى من نفى الأدنى. وكأنهم على ذلك ذموا بنفي الخضوع الكثير، وأنهم ما بلغوا في الضراعة نهايتها، وليس الواقع، فإنهم ما اتسموا بالضراعة ولا بلظة منها، فكيف تنفى عنهم النهاية الموهمة لحصول البداية، والله أعلم.]] ، أى: انتقل من كون إلى كون، كما قيل: استحال، إذا انتقل من حال إلى حال. ويجوز أن يكون افتعل من السكون أشبعت فتحة عينه، كما جاء: بمنتزاح [[قوله «كما جاء بمنتزاح» أى في قوله: وأنت من الغوائل حين ترمى ... وعن ذم الرجال بمنتزاح اه عليان قلت: وقد تقدم شرح هذا الشاهد بالجزء الثاني فراجعه إن شئت اه مصححه.]] . فإن قلت: هلا قيل: وما تضرعوا. أو: فما يستكينون؟ قلت: لأنّ المعنى: محناهم فما وجدت منهم عقيب المحنة استكانة. وما من عادة هؤلاء أن يستكينوا ويتضرعوا حتى يفتح عليهم باب العذاب الشديد. وقرئ: فتحنا.',     source_page = '464',     updated_at  = datetime('now') WHERE id = 'QR:TE:2831db1b3bc466a8be8c35f5';
UPDATE qr_tafsir_entries SET content_ar = 'حَتَّى يتعلق بيصفون، أى: لا يزالون على سوء الذكر إلى هذا الوقف. والآية فاصلة بينهما على وجه الاعتراض والتأكيد للإغضاء عنهم، مستعينا بالله على الشيطان أن يستزله عن الحلم ويغريه على الانتصار منهم. أو على قوله: وإنهم لكاذبون [[قوله «أو على قوله: وإنهم لكاذبون» لعله عطف على المعنى، فكأنه قال فيما مر: حتى رد على قوله يَصِفُونَ. فقال هنا: أو على قوله وَإِنَّهُمْ لَكاذِبُونَ. (ع)]] . خطاب الله بلفظ الجمع للتعظيم، كقوله: فإن شئت حرّمت النّساء سواكم [[تقدم شرح هذا الشاهد بالجزء الثاني فراجعه إن شئت اه مصححه.]] وقوله: ألا فارحمونى يا إله محمّد [[ألا فارحمونى يا إله محمد ... فان لم أكن أهلا فأنت له أهل «ألا» استفتاحية دالة على الاهتمام بما يعقبها من الكلام، وخاطب الاله الواحد الأحد بخطاب الجمع جريا على عادة العرب من خطاب السادة والملوك بذلك تعظما. وقيل: هو إشارة إلى تكرار الفعل للتوكيد، كأنه قيل: ارحمني ارحمني ارحمني، وإضافته إلى محمد ﷺ للتوسل به إلى الله عز وجل، فان لم أكن أهلا لهذا الطلب أو المطلوب من الرحمة والرفق» فأنت يا الله أهل له.]] إذا أيقن بالموت واطلع على حقيقة الأمر، أدركته الحسرة على ما فرّط فيه من الإيمان والعمل الصالح فيه، فسأل ربه الرجعة وقال لَعَلِّي أَعْمَلُ صالِحاً في الإيمان الذي تركته، والمعنى: لعلى آتى بما تركته من الإيمان، وأعمل فيه صالحا، كما تقول: لعلى أبنى على أس، تريد: أسس أسا وأبنى عليه. وقيل: فيما تركت من المال. وعن النبي ﷺ: «إذا عاين المؤمن الملائكة قالوا نرجعك إلى الدنيا، فيقول: إلى دار الهموم والأحزان! بل قدوما إلى الله. وأمّا الكافر فيقول: رب ارجعون» كَلَّا ردع عن طلب الرجعة، وإنكار واستبعاد. والمراد بالكلمة: الطائفة من الكلام المنتظم بعضها مع بعض، وهي قوله: لَعَلِّي أَعْمَلُ صالِحاً فِيما تَرَكْتُ. هُوَ قائِلُها لا محالة، لا يخليها ولا يسكت عنها لاستيلاء الحسرة عليه وتسلط الندم. أو هو قائلها وحده لا يجاب إليها ولا تسمع منه وَمِنْ وَرائِهِمْ بَرْزَخٌ والضمير للجماعة، أى: أمامهم حائل بينهم وبين الرجعة إلى يوم البعث، وليس المعنى: أنهم يرجعون يوم البعث، وإنما هو إقناط كلى لما علم أنه لا رجعة يوم البعث إلا إلى الآخرة.',     source_page = '383',     updated_at  = datetime('now') WHERE id = 'QR:TE:6357aac4ec97b526bde1586e';
UPDATE qr_tafsir_entries SET content_ar = 'فِي بُيُوتٍ يتعلق بما قبله، أى، كمشكاة في بعض بيوت الله وهي المساجد، كأنه قيل: مثل نوره كما يرى في المسجد نور المشكاة التي من صفتها كيت وكيت. أو بما بعده، وهو يسبح، أى: يسبح له رجال في بيوت. وفيها تكرير، كقولك: زيد في الدار جالس فيها. أو بمحذوف، كقوله فِي تِسْعِ آياتٍ أى سبحوا في بيوت. والمراد بالإذن: الأمر. ورفعها: بناؤها، كقوله بَناها. رَفَعَ سَمْكَها فَسَوَّاها، وَإِذْ يَرْفَعُ إِبْراهِيمُ الْقَواعِدَ وعن ابن عباس رضى الله عنهما: هي المساجد، أمر الله أن تبنى. أو تعظيمها والرفع من قدرها. وعن الحسن رضى الله عنه: ما أمر الله أن ترفع بالبناء، ولكن بالتعظيم وَيُذْكَرَ فِيهَا اسْمُهُ أوفق له، وهو عام في كل ذكر. وعن ابن عباس رضى الله عنهما: وأن يتلى فيها كتابه. وقرئ: يسبح، على البناء للمفعول، ويسند إلى أحد الظروف الثلاثة، أعنى: لَهُ فِيها بِالْغُدُوِّ، ورِجالٌ مرفوع بما دلّ عليه يُسَبِّحُ وهو يسبح له. وتسبح، بالتاء وكسر الباء. وعن أبى جعفر رضى الله عنه بالتاء وفتح الباء. ووجهها أن يسند إلى أوقات الغدوّ والآصال على زيادة الباء، وتجعل الأوقات مسبحة. والمراد ربها، كصيد عليه يومان. والمراد وحشهما. والآصال: جمع أصل وهو العشى. والمعنى: بأوقات الغدوّ، أى: بالغدوات. وقرئ: والإيصال، وهو الدخول في الأصيل. يقال: آصل، كأظهر وأعتم. التجارة: صناعة التاجر، وهو الذي يبيع ويشترى للربح، فإما أن يريد: لا يشغلهم نوع من هذه الصناعة، ثم خص البيع لأنه في الإلهاء أدخل، من قبل أن التاجر إذا اتجهت له بيعة رابحة وهي طلبته الكلية من صناعته: ألهته ما لا يلهيه شراء شيء يتوقع فيه الريح في الوقت الثاني، لأن هذا يقين وذاك مظنون. وإمّا أن يسمى الشراء تجارة، إطلاقا لاسم الجنس على النوع، كما تقول: رزق فلان تجارة رابحة إذا اتجه له بيع صالح أو شراء. وقيل: التجارة لأهل الجلب، اتجر فلان في كذا: إذا جلبه. التاء في إقامة، عوض من العين الساقطة للإعلال. والأصل: إقوام» فلما أضيفت أقيمت الإضافة مقام حرف التعويض، فأسقطت. ونحوه: وأخلفوك عد الأمر الّذى وعدوا [[تقدم شرح هذا الشاهد بالجزء الأول فراجعه إن شئت اه مصححه]] وتقلب القلوب والأبصار: إما أن تتقلب وتتغير في أنفسها: وهو أن تضطرب من الهول والفزع وتشخص، كقوله وَإِذْ زاغَتِ الْأَبْصارُ وَبَلَغَتِ الْقُلُوبُ الْحَناجِرَ. وإما أن تتقلب أحوالها وتتغير فتفقه القلوب بعد أن كانت مطبوعا عليها لا تفقه، وتبصر الأبصار بعد أن كانت عميا لا تبصر أَحْسَنَ ما عَمِلُوا أى أحسن جزاء أعمالهم، كقوله لِلَّذِينَ أَحْسَنُوا الْحُسْنى والمعنى يسبحون ويخافون، ليجزيهم ثوابهم مضاعفا ويزيدهم على الثواب تفضلا. وكذلك معنى قوله الْحُسْنى وَزِيادَةٌ المثوبة الحسنى وزيادة عليها من التفضل. وعطاء الله تعالى: إما تفضل، وإما ثواب، وإما عوض وَاللَّهُ يَرْزُقُ ما يتفضل به بِغَيْرِ حِسابٍ فأما الثواب فله حساب لكونه على حسب الاستحقاق.',     source_page = '323',     updated_at  = datetime('now') WHERE id = 'QR:TE:0a55ce4ff8016ba4ae899976';
UPDATE qr_tafsir_entries SET content_ar = 'أدخل (قد) ليؤكد علمه بما هم عليه من المخالفة عن الدين والنفاق ومرجع توكيد العلم إلى توكيد الوعيد، وذلك أن (قد) إذا دخلت على المضارع كانت بمعنى «ربما» فوافقت «ربما» في خروجها إلى معنى التكثير في نحو قوله: فان تمس مهجور الفناء فربّما ... أقام به بعد الوفود وفود [[ألا إن عينا لم تجد يوم واسط ... عليك يجارى دمعها لجمود عشية قام النائحات وشققت ... جيوب بأيدى مأتم وخدود فان تمس مهجور الفناء فربما ... أقام به بعد الوفود وفود لابن عطاء السندي: يرث ى ابن هبيرة لما قتله المنصور. وواسط: موضع الواقعة. وأتم بالمكان: أقام به. والمأتم: مكان الاقامة: استعمل في جماعة النساء الحزينات مجازا مشهورا، وجمعه: مآتم بمد الهمزة. يقول: إن كل عين لم تبك عليك ذلك اليوم لشديدة الجمود. وعشية: بدل من يوم. وجيب القميص. مخرج الرأس منه، أى: مزقت الجيوب والخدود بأيدى النساء، ثم التفت إلى الخطاب، وصبر وتصبر بقوله: فان تمس مهجور الفناء، كناية عن الموت، فربما: أى كثيرا أقام بفناء بيتك جموع من الناس بعد جموع، يستمنحونك، أى: فان يهجر فناؤك الآن فلا حزن، لأنه كثيرا ما اجتمع فيه الناس ومنحوا خيرا.]] ونحوه قول زهير: أخى ثقة لا تهلك الخمر ماله ... ولكنّه قد يهلك المال نائله [[تقدم شرح هذا الشاهد بالجزء الثاني فراجعه إن شئت اه مصححه.]] والمعنى. أنّ جميع ما في السموات والأرض مختصة به خلقا وملكا وعلما، فكيف يخفى عليه أحوال المنافقين وإن كانوا يجتهدون في سترها عن العيون وإخفائها. وسينبئهم يوم القيامة بما أبطنوا من سوء أعمالهم وسيجازيهم حق جزائهم. والخطاب والغيبة في قوله قَدْ يَعْلَمُ ما أَنْتُمْ عَلَيْهِ وَيَوْمَ يُرْجَعُونَ إِلَيْهِ يجوز أن يكونا جميعا المنافقين على طريق الالتفات. ويجوز أن يكون (ما أنتم عليه) عاما، و (يرجعون) للمنافقين، والله أعلم. عن رسول الله ﷺ: «من قرأ سورة النور أعطى من الأجر عشر حسنات بعدد كل مؤمن ومؤمنة فيما مضى وفيما بقي [[أخرجه الثعلبي وابن مردويه باسناديهما إلى أبى بن كعب رضى الله عنه.]] » .',     source_page = '17',     updated_at  = datetime('now') WHERE id = 'QR:TE:8bb81bc2318e2c3c04921d21';
UPDATE qr_tafsir_entries SET content_ar = 'تكاثر خير الَّذِي إِنْ شاءَ وهب لك في الدنيا خَيْراً مما قالوا، وهو أن يعجل لك مثل ما وعدك في الآخرة من الجنات والقصور. وقرئ: ويجعل، بالرفع عطفا على جعل: لأن الشرط إذا وقع ماضيا، جاز في جزائه الجزم والرفع، كقوله: وإن أتاه خليل يوم مسألة ... يقول لا غائب مالى ولا حرم [[تقدم شرح هذا الشاهد بالجزء الأول فراجعه إن شئت اه مصححه.]] ويجوز في (ويجعل لك) إذا أدغمت: أن تكون اللام في تقدير الجزم والرفع جميعا. وقرئ بالنصب، على أنه جواب الشرط بالواو.',     source_page = '537',     updated_at  = datetime('now') WHERE id = 'QR:TE:174a5184a1ab24ac4d6fde20';
UPDATE qr_tafsir_entries SET content_ar = 'البروج: منازل الكواكب السبعة السيارة: الحمل، والثور، والجوزاء، والسرطان، والأسد، والسنبلة، والميزان، والعقرب، والقوس، والجدى، والدلو، والحوت: سميت بالبروج التي هي القصور العالية، لأنها لهذه الكواكب كالمنازل لسكانها. واشتقاق البرج من التبرج، لظهوره. والسراج: الشمس كقوله تعالى وَجَعَلَ الشَّمْسَ سِراجاً وقرئ. سرجا، وهي الشمس والكواكب الكبار معها. وقرأ الحسن والأعمش: وقمرا منيرا، وهي جمع ليلة قمراء، كأنه قال: وذا قمر منيرا لأنّ الليالي تكون قمرا بالقمر، فأضافه إليها. ونظيره- في بقاء حكم المضاف بعد سقوطه وقيام المضاف إليه مقامه- قول حسان: بردي يصفّق بالرّحيق السّلسل [[تقدم شرح هذا الشاهد بالجزء الأول فراجعه إن شئت اه مصححه]] يريد: ماء بردي، ولا يبعد أن يكون القمر بمعنى القمر، كالرشد والرشد، والعرب والعرب.',     source_page = '84',     updated_at  = datetime('now') WHERE id = 'QR:TE:91e4a11039c5da5d2e603b57';
UPDATE qr_tafsir_entries SET content_ar = 'وَعِبادُ الرَّحْمنِ مبتدأ خبره في آخر السورة، كأنه قيل: وعباد الرحمن الذين هذه صفاتهم أولئك يجزون الغرفة. ويجوز أن يكون خبره الَّذِينَ يَمْشُونَ وأضافهم إلى الرحمن تخصيصا وتفضيلا. وقرئ: وعباد الرحمن. وقرئ: يمشون هَوْناً حال، أو صفة للمشي، بمعنى: هينين. أو: مشيا هينا، إلا أنّ في وضع المصدر موضع الصفة مبالغة. والهون: الرفق واللين. ومنه الحديث «أحبب حبيبك هونا [[أخرجه الترمذي من رواية أيوب عن ابن سيرين عن أبى هريرة تفرد به سويد بن عمرو عن حماد بن سلمة عن أيوب قال الترمذي. غريب. وقال ابن حبان، في الضعفاء: سويد بن عمرو يضع المتون الواهية على الأسانيد الصحيحة. وليس هذا من حديث أبى هريرة. وإنما هو من قول على رضى الله عنه. وقد رفعه الحسن بن أبى جعفر عن أيوب عن حميد بن عبد الرحمن عن على. وهو خطأ فاحش. ورواية الحسن بن أبى جعفر في فوائد تمام وأخرجه ابن عدى من طريق الحسن بن دنيا- عن ابن سيرين عن أبى هريرة. قال: الحسن بن دنيا- أجمعوا على ضعفه ورواه الطبراني في الأوسط. من رواية أبى الزناد عن الأعرج. عن أبى هريرة لكن الراوي له عن أبى الزناد متروك. وهو عباد بن كثير. وفي الباب عن ابن عمر أخرجه الطبراني وفيه أبو السلط الهروي. وهو متروك وعن ابن عمرو بن العاص أخرجه أيضا من طريق محمد بن كثير الضمري. عن ابن لهيعة، عن أبى نهشل عنه وهذا إسناد واه جدا. والموقوف عن على. أخرجه البيهقي في الشعب في الحادي والأربعين من رواية أبى إسحاق عن صبرة بن يزيد ثم عن على. وقال الدارقطني. الصحيح على على موقوف]] مّا» وقوله «المؤمنون هينون لينون [[أخرجه ابن المبارك في الزهد قال أخبرنا سعيد بن عبد العزيز عن مكحول بهذا مرسلا «وزاد كالجمل الأنف الذي إن قيد انقاد. وإن ينخ على صخرة أناخ» وأخرجه البيهقي في الشعب في السادس والخمسين من هذا الوجه قال هذا مرسل ثم أخرجه من طريق العقيلي في منكرات عبد الله بن عبد العزيز. وفي الباب عن ابن أنس مرفوعا ذكره ابن طاهر في الكلام على أحاديث الشهاب. وفيه زكريا بن يحيى الوقاد وهو واهى الحديث.]] » والمثل: إذا عزّ أخوك فهن. ومعناه: إذا عاسر فياسر. والمعنى: أنهم يمشون بسكينة ووقار وتواضع، لا يضربون بأقدامهم ولا يخفقون بنعالهم أشرا وبطرا، ولذلك كره بعض العلماء الركوب في الأسواق، ولقوله وَيَمْشُونَ فِي الْأَسْواقِ. سَلاماً تسلما منكم لا نجاهلكم، ومتاركة لا خير بيننا ولا شر، أى: نتسلم منكم تسلما، فأقيم السلام مقام التسلم. وقيل: قالوا سدادا من القول يسلمون فيه من الإيذاء والإثم. والمراد بالجهل: السفه وقلة الأدب وسوء الرعة، [[قوله «وسوء الرعة» في الصحاح: يقال: فلان سيئ الرعة، أى: قليل الورع. وفيه: قيل ذلك الورع- بكسر الراء-: الرجل التقى. وقد ورع يرع- بالكسر فيهما- ورعا ورعة. (ع)]] من قوله: ألا لا يجهلن أحد علينا ... فنجهل فوق جهل الجاهلينا [[تقدم شرح هذا الشاهد بالجزء الثاني فراجعه إن شئت اه مصححه.]] وعن أبى العالية: نسختها آية القتال، ولا حاجة إلى ذلك لأنّ الإغضاء عن السفهاء وترك المقابلة مستحسن في الأدب والمروءة والشريعة، وأسلم للعرض والورع.',     source_page = '390',     updated_at  = datetime('now') WHERE id = 'QR:TE:72d8c2931edf767fcef7e431';
UPDATE qr_tafsir_entries SET content_ar = 'قرئ يَقْتُرُوا بكسر التاء وضمها. ويقتروا، بتخفيف التاء وتشديدها. والقتر والإقتار والتقتير: التضييق الذي هو نقيض الإسراف. والإسراف: مجاوزة الحدّ في النفقة. ووصفهم بالقصد الذي هو بين الغلو والتقصير. وبمثله أمر رسول الله ﷺ وَلا تَجْعَلْ يَدَكَ مَغْلُولَةً إِلى عُنُقِكَ وَلا تَبْسُطْها كُلَّ الْبَسْطِ وقيل: الإسراف إنما هو الإنفاق في المعاصي، فأما في القرب فلا إسراف. وسمع رجل رجلا يقول: لا خير في الإسراف. فقال: لا إسراف في الخير. وعن عمر بن عبد العزيز رضى الله عنه أنه شكر عبد الملك بن مروان حين زوّجه ابنته وأحسن إليه، فقال: وصلت الرحم وفعلت وصنعت، وجاء بكلام حسن، فقال ابن لعبد الملك: إنما هو كلام أعدّه لهذا المقام، فلما كان بعد أيام دخل عليه والابن حاضر، فسأله عن نفقته وأحواله فقال: الحسنة بين السيئتين، فعرف عبد الملك أنه أراد ما في هذه الآية فقال لابنه: يا بنىّ، أهذا أيضا مما أعدّه؟ وقيل: أولئك أصحاب محمد ﷺ، كانوا لا يأكلون طعاما للتنعم واللذة، ولا يلبسون ثوبا للجمال والزينة، ولكن كانوا يأكلون ما يسدّ جوعتهم ويعينهم على عبادة ربهم، ويلبسون ما يستر عوراتهم ويكنهم من الحرّ والقرّ [[قوله «والقر» أى البرد. (ع)]] . وقال عمر رضى الله عنه: كفى سرفا أن لا يشتهى رجل شيئا إلا اشتراه فأكله [[أخرجه عبد الرزاق في التفسير عن ابن عيينة عن رجل عن الحسن عن عمر بن الخطاب وهذا منقطع من طريقه. رواه الثعلبي. ورواه أحمد في الزهد عن إسماعيل عن يونس عن الحسن كذلك ورواه ابن ماجة وأبو يعلى والبيهقي في الشعب من طريق نوح بن ذكوان عن الحسن عن أنس رضى الله عنه مرفوعا والأول أصح]] . والقوام: العدل بين الشيئين لاستقامة الطرفين واعتدالهما. ونظير القوام من الاستقامة: السواء من الاستواء. وقرئ: قواما، بالكسر، وهو ما يقام به الشيء. يقال: أنت قوامنا، بمعنى ما تقام به الحاجة لا يفضل عنها ولا ينقص، والمنصوبان أعنى بَيْنَ ذلِكَ قَواماً: جائز أن يكونا خبرين معا، وأن يجعل بين ذلك لغوا، وقواما مستقرا. وأن يكون الظرف خبرا، وقواما حالا مؤكدة. وأجاز الفراء أن يكون بَيْنَ ذلِكَ اسم كان، على أنه مبنى لإضافته إلى غير متمكن، كقوله: لم يمنع الشّرب منها غير أن نطقت [[تقدم شرح هذا الشاهد بالجزء الثاني فراجعه إن شئت اه مصححه.]] وهو من جهة الإعراب لا بأس به، ولكن المعنى ليس بقوى لأنّ ما بين الإسراف والتقتير قوام لا محالة، فليس في الخبر الذي هو معتمد الفائدة فائدة.',     source_page = '422',     updated_at  = datetime('now') WHERE id = 'QR:TE:bf8028fff966c4fb6e1698c3';
UPDATE qr_tafsir_entries SET content_ar = 'حَرَّمَ اللَّهُ أى حرّمها. والمعنى: حرّم قتلها. وإِلَّا بِالْحَقِّ متعلق بهذا القتل المحذوف. أو بلا يقتلون، ونفى هذه المقبحات العظام على الموصوفين بتلك الخلال العظيمة في الدين، للتعريض بما كان عليه أعداء المؤمنين من قريش وغيرهم، كأنه قيل: والذين برأهم الله وطهرهم مما أنتم عليه. والقتل بغير الحق: يدخل فيه الوأد وغيره. وعن ابن مسعود رضى الله عنه قلت: يا رسول الله، أىّ الذنب أعظم؟ قال: «أن تجعل لله ندّا وهو خلقك» قلت: ثم أىّ؟ قال «أن تقتل ولدك خشية أن يأكل معك» قلت: ثم أى؟ قال «أن تزانى حليلة جارك» [[متفق عليه من رواية أبى وائل عن عمرو بن شرحبيل عنه.]] فأنزل الله تصديقه. وقرئ: يلق فيه أثاما. وقرئ: يلقى، بإثبات الألف، وقد مر مثله. والآثام: جزاء الإثم، بوزن الوبال والنكال ومعناهما. قال: جزي الله ابن عروة حيث أمسى ... عقوقا والعقوق له أثام [[العقوق- بالفتح-: كثير العقوق بالضم، وهو منع بر الوالدين وقطع صلتهما، والأثام- كالوبال-: جزاء الإثم. وقيل: هو الإثم، فسمي به مسببه وهو الجزاء، ومفعول جزى الثاني محذوف. وعقوقا خبر أمسى. والعقوق: مبتدأ، أى: لا بد العقوق من جزاء سيء عظيم.]] وقيل هو الإثم. ومعناه: يلق جزاء أثام. وقرأ ابن مسعود رضى الله عنه: أياما [[قوله «أياما» وفي الصحاح «الأيام» الدخان. (ع)]] ، أى شدائد. يقال: يوم ذو أيام: لليوم العصيب. يُضاعَفْ بدل من يلق، لأنهما في معنى واحد، كقوله: متى تأتنا تلمم بنا في ديارنا ... تجد حطبا جزلا ونارا تأجّجا [[تقدم شرح هذا الشاهد بالجزء الأول فراجعه إن شئت اه مصححه.]] وقرئ: يضعف، ونضعف له العذاب، بالنون ونصب العذاب. وقرئ بالرفع على الاستئناف أو على الحال، وكذلك يَخْلُدْ وقرئ: ويخلد، على البناء للمفعول مخففا ومثقلا، من الإخلاد والتخليد. وقرئ: وتخلد، بالتاء على الالتفات يُبَدِّلُ مخفف ومثقل، وكذلك سيئاتهم. فإن قلت: ما معنى مضاعفة العذاب وإبدال السيئات حسنات؟ قلت: إذا ارتكب المشرك معاصى مع الشرك عذب على الشرك وعلى المعاصي جميعا، فتضاعف العقوبة لمضاعفة المعاقب عليه. وإبدال السيئات حسنات: أنه يمحوها بالتوبة، ويثبت مكانها الحسنات: الإيمان، والطاعة، والتقوى. وقيل: يبدّلهم بالشرك إيمانا، وبقتل المسلمين: قتل المشركين، وبالزنا: عفة وإحصانا.',     source_page = '331',     updated_at  = datetime('now') WHERE id = 'QR:TE:e0b0d4a85bcae83406f2b9d1';
UPDATE qr_tafsir_entries SET content_ar = 'أَتُتْرَكُونَ يجوز أن يكون إنكارا لأن يتركوا مخلدين في نعيمهم لا يزالون عنه، وأن يكون تذكيرا بالنعمة في تخلية الله إياهم وما يتنعمون فيه من الجنات وغير ذلك، مع الأمن والدّعة فِي ما هاهُنا في الذي استقر في هذا المكان من النعيم، ثم فسره بقوله فِي جَنَّاتٍ وَعُيُونٍ وهذا أيضا إجمال ثم تفصيل. فإن قلت: لم قال وَنَخْلٍ بعد قوله: في جنات، والجنة تتناول النخل أوّل شيء كما يتناول النعم الإبل كذلك من بين الأزواج، حتى أنهم ليذكرون الجنة ولا يقصدون إلا النخيل، كما يذكرون النعم ولا يريدون إلا الإبل. قال زهير: .... تسقى جنّة سحقا [[تقدم شرح هذا الشاهد بالجزء الأول فراجعه إن شئت اه مصححه.]] قلت: فيه وجهان: أن يخص النخل بإفراده بعد دخوله في جملة سائر الشجر، تنبيها على انفراده عنها بفضله عليها، وأن يريد بالجنات: غيرها من الشجر، لأنّ اللفظ يصلح لذلك، ثم يعطف عليها النخل. الطلعة: هي التي تطلع من النخلة، كنصل السيف في جوفه شماريخ القنو. والقنو: اسم للخارج من الجذع كما هو بعرجونه وشماريخه. والهضيم: اللطيف الضامر، من قولهم: كشح هضيم، وطلع إناث النخل فيه لطف، وفي طلع الفحاحيل جفاء، وكذلك طلع البرني ألطف من طلع اللون [[قوله «وكذلك طلع البرني ألطف من طلع اللون» البرني: ضرب من التمر. واللون: الدقل، والدقل: أردا التمر، كذا في الصحاح. (ع)]] ، فذكرهم نعمة الله في أن وهب لهم أجود النخل وأنفعه: لأنّ الإناث ولادة التمر، والبرني: أجود التمر وأطيبه ويجوز أن يريد أن نخيلهم أصابت جودة المنابت وسعة الماء، وسلمت من العاهات، فحملت الحمل الكثير، وإذا كثر الحمل هضم، وإذا قل جاء فاخرا. وقيل: الهضيم: اللين النضيج، كأنه قال: ونخل قد أرطب ثمره. قرأ الحسن: وتنحتون، بفتح الحاء. وقرئ: فرهين، وفارهين. والفراهة: الكيس والنشاط. ومنه: خيل فرهة، استعير لامتثال الأمر، وارتسامه طاعة الآمر المطاع. أو جعل الأمر مطاعا على المجاز الحكمي، والمراد الآمر. ومنه قولهم: لك علىّ إمرة مطاعة. وقوله تعالى وَأَطِيعُوا أَمْرِي. فإن قلت: ما فائدة قوله وَلا يُصْلِحُونَ؟ قلت: فائدته أنّ فسادهم فساد مصمت ليس معه شيء من الصلاح، كما تكون حال بعض المفسدين مخلوطة ببعض الصلاح.',     source_page = '105',     updated_at  = datetime('now') WHERE id = 'QR:TE:86afe0869ca189cc63602024';
UPDATE qr_tafsir_entries SET content_ar = 'وقرئ: يكن، بالتذكير. وآية، بالنصب على أنها خبره، وأَنْ يَعْلَمَهُ هو الاسم. وقرئ. تكن، بالتأنيث، وجعلت آيَةً اسماء، وأَنْ يَعْلَمَهُ خبرا، وليست كالأولى لوقوع النكرة اسما والمعرفة خبرا، وقد خرّج لها وجه آخر ليتخلص من ذلك، فقيل: في يَكُنْ ضمير القصة، وآيَةً أَنْ يَعْلَمَهُ جملة واقعة موقع الخبر. ويجوز على هذا أن يكون لَهُمْ آيَةً هي جملة الشأن، أَنْ يَعْلَمَهُ بدلا عن آية. ويجوز مع نصب الآية تأنيث يَكُنْ كقوله تعالى ثُمَّ لَمْ تَكُنْ فِتْنَتُهُمْ إِلَّا أَنْ قالُوا ومنه بيت لبيد: فمضى وقدّمها وكانت عادة ... منه إذا هي عرّدت أقدامها [[تقدم شرح هذا الشاهد بهذا الجزء فراجعه إن شئت اه مصححه.]] وقرئ: تعلمه، بالتاء. عُلَماءُ بَنِي إِسْرائِيلَ: عبد الله بن سلام وغيره. قال الله تعالى وَإِذا يُتْلى عَلَيْهِمْ قالُوا آمَنَّا بِهِ إِنَّهُ الْحَقُّ مِنْ رَبِّنا إِنَّا كُنَّا مِنْ قَبْلِهِ مُسْلِمِينَ. فإن قلت: كيف خط في المصحف «علمؤا» بواو قبل الألف؟ قلت: خط على لغة من يميل الألف إلى الواو وعلى هذه اللغة كتبت الصلوة والزكاة والربوا.',     source_page = '13',     updated_at  = datetime('now') WHERE id = 'QR:TE:33be600c80603f4548af7c17';
UPDATE qr_tafsir_entries SET content_ar = 'أراد: آية ملجئة إلى الإيمان قاصرة عليه. فَظَلَّتْ معطوف على الجزاء الذي هو ننزل، لأنه لو قيل: أنزلنا، لكان صحيحا. ونظيره: فأصدّق وأكن، كأنه قيل: أصدق. وقد قرئ: لو شئنا لأنزلنا. وقرئ: فتظل أعناقهم. فإن قلت: كيف صح مجيء خاضعين خبرا عن الأعناق قلت: أصل الكلام: فظلوا لها خاضعين، فأقحمت الأعناق لبيان موضع الخضوع، وترك الكلام على أصله، كقوله: ذهبت أهل اليمامة، كأنّ الأهل غير مذكور. أو لما وصفت بالخضوع الذي هو للعقلاء قيل: خاضعين، كقوله تعالى لِي ساجِدِينَ وقيل أعناق الناس: رؤساؤهم ومقدّموهم، شبهوا بالأعناق كما قيل لهم هم الرءوس والنواصي والصدور. قال: في محفل من نواصي النّاس مشهود [[تقدم شرح هذا الشاهد بالجزء الثاني فراجعه إن شئت اه مصححه.]] وقيل: جماعات الناس. يقال: جاءنا عنق من الناس لفوج منهم. وقرئ: فظلت أعناقهم لها خاضعة. وعن ابن عباس رضى الله عنهما: نزلت هذه الآية فينا وفي بنى أمية. قال: ستكون لنا عليهم الدولة، فتذل لنا أعناقهم بعد صعوبة، ويلحقهم هوان بعد عزة.',     source_page = '428',     updated_at  = datetime('now') WHERE id = 'QR:TE:a49b0cf998b03d17cc5c8d18';
UPDATE qr_tafsir_entries SET content_ar = 'الحكم: الحكمة، أو الحكم بين الناس بالحق. وقيل: النبوّة، لأنّ النبي ذو حكمة وذو حكم بين عباد الله. والإلحاق بالصالحين: أن يوفقه لعمل ينتظم به في جملتهم، أو يجمع بينه وبينهم في الجنة. ولقد أجابه حيث قال وَإِنَّهُ فِي الْآخِرَةِ لَمِنَ الصَّالِحِينَ. والإخزاء: من الخزي وهو الهوان. ومن الخزاية [[قوله «ومن الخزاية» لعله: أو من. (ع)]] وهي الحياء. وهذا أيضا من نحو استغفارهم مما علموا أنه مغفور وفي يُبْعَثُونَ ضمير العباد، لأنه معلوم. أو ضمير الضالين. وأن يجعل من جملة الاستغفار لأبيه [[قوله «أو ضمير الضالين، وأن يجعل من جملة الاستغفار لأبيه» لعله عطف على المعنى، كأنه قال: ويحتمل أنه ضمير الضالين ... الخ. (ع)]] ، يعنى: ولا تخزني يوم يبعث الضالون وأبى فيهم إِلَّا مَنْ أَتَى اللَّهَ إلا حال من أتى الله بِقَلْبٍ سَلِيمٍ وهو من قولهم: تحيّة بينهم ضرب وجيع [[تقدم شرح هذا الشاهد بالجزء الأول فراجعه إن شئت اه مصححه.]] وما ثوابه إلا السيف. وبيانه أن يقال لك: هل لزيد مال وبنون؟ فتقول: ماله وبنوه: سلامة قلبه، تريد نفى المال والبنين عنه، وإثبات سلامة القلب له بدلا عن ذلك. وإن شئت حملت الكلام على المعنى وجعلت المال والبنين في معنى الغنى، كأنه قيل: يوم لا ينفع غنى إلا غنى من أتى الله بقلب سليم، لأن غنى الرجل في دينه بسلامة قلبه، كما أن غناه في دنياه بماله وبنيه. ولك أن تجعل الاستثناء منقطعا، ولا بدّ لك مع ذلك من تقدير المضاف وهو الحال، والمراد بها سلامة القلب، وليست هي من جنس المال والبنين، حتى يؤوّل المعنى إلى أن المال والبنين لا ينفعان، وإنما ينفع سلامة القلب. ولو لم يقدر المضاف، لم يتحصل للاستثناء معنى. وقد جعل مَنْ مفعولا لينفع، أى: لا ينفع مال ولا بنون، إلا رجلا سلم قلبه مع ماله حيث أنفقه في طاعة الله، ومع بنيه حيث أرشدهم إلى الدين وعلمهم الشرائع. ويجوز على هذا إِلَّا مَنْ أَتَى اللَّهَ بِقَلْبٍ سَلِيمٍ من فتنة المال والبنين. ومعنى سلامة القلب: سلامته من آفات الكفر والمعاصي، ومما أكرم الله تعالى به خليله ونبه على جلالة محله في الإخلاص: أن حكى استثناءه هذا حكاية راض بإصابته فيه، ثم جعله صفة له في قوله وَإِنَّ مِنْ شِيعَتِهِ لَإِبْراهِيمَ، إِذْ جاءَ رَبَّهُ بِقَلْبٍ سَلِيمٍ ومن بدع التفاسير: تفسير بعضهم السليم باللديغ من خشية الله. وقول آخر: هو الذي سلم وسلم وأسلم وسالم واستسلم. وما أحسن ما رتب إبراهيم عليه السلام كلامه مع المشركين، حين سألهم أوّلا عما يعبدون سؤال مقرّر لا مستفهم، ثم أنحى على آلهتهم فأبطل أمرها بأنها لا تضر ولا تنفع ولا تبصر ولا تسمع على تقليدهم آباءهم الأقدمين، فكسره وأخرجه من أن يكون شبهة فضلا أن يكون حجة، ثم صوّر المسألة في نفسه دونهم حتى تخلص منها إلى ذكر الله عز وعلا، فعظم شأنه وعدّد نعمته، من لدن خلقه وإنشائه إلى حين وفاته، مع ما يرجى في الآخرة من رحمته، ثم أتبع ذلك أن دعاه بدعوات المخلصين، وابتهل اليه ابتهال الأوّابين، ثم وصله بذكر يوم القيامة وثواب الله وعقابه وما يدفع إليه المشركون يومئذ من الندم والحسرة على ما كانوا فيه من الضلال وتمنى الكرة إلى الدنيا ليؤمنوا ويطيعوا.',     source_page = '60',     updated_at  = datetime('now') WHERE id = 'QR:TE:f05aeb47d2944dfe4bce8e4d';
UPDATE qr_tafsir_entries SET content_ar = 'وفِي تِسْعِ آياتٍ كلام مستأنف، وحرف الجرّ فيه يتعلق بمحذوف. والمعنى: اذهب في تسع آيات إِلى فِرْعَوْنَ ونحوه: فقلت إلى الطّعام فقال منهم ... فريق نحسد الإنس الطّعاما [[تقدم شرح هذا الشاهد بالجزء الأول فراجعه إن شئت اه مصححه.]] ويجوز أن يكون المعنى: وألق عصاك، وأدخل يدك: في تسع آيات، أى: في جملة تسع آيات وعدادهنّ. ولقائل أن يقول: كانت الآيات إحدى عشرة: ثنتان منها اليد والعصا، والتسع: الفلق، والطوفان، والجراد، والقمل، والضفادع، والدم، والطمسة، والجدب في بواديهم، والنقصان في مزارعهم.',     source_page = '2',     updated_at  = datetime('now') WHERE id = 'QR:TE:8b69783e0030255dd7fd295e';
UPDATE qr_tafsir_entries SET content_ar = 'فارِغاً صفرا من العقل. والمعنى: أنها حين سمعت بوقوعه في يد فرعون طار عقلها لما دهمها من فرط الجزع والدهش. ونحوه قوله تعالى وَأَفْئِدَتُهُمْ هَواءٌ أى جوّف لا عقول فيها ومنه بيت حسان: ألا أبلغ أبا سفيان عنّى ... فأنت مجوّف نخب هواء [[تقدم شرح هذا الشاهد ضمن أبيات في الجزء الثاني فراجعه إن شئت اه مصححه.]] وذلك أنّ القلوب مراكز العقول. ألا ترى إلى قوله فَتَكُونَ لَهُمْ قُلُوبٌ يَعْقِلُونَ بِها ويدل عليه قراءة من قرأ: فرغا. وقرئ: قرعا، أى خاليا من قولهم: أعوذ بالله من صفر الإناء وقرع الفناء [[قوله «من صفر الإناء وقرع الفناء» صفر الإناء: خلوه، مصدر: صفر الشيء بالكسر، أى: خلا. وقرع الفناء: خلوه من الغاشية، مصدر قرع بالكسر، أى: خلا. (ع)]] . وفرغا، من قولهم: دماؤهم بينهم فرغ، أى هدر، يعنى: بطل قلبها وذهب، وبقيت لا قلب لها من شدّة ما ورد عليها لَتُبْدِي بِهِ لتصحر [[قوله «لتصحر به» في الصحاح: أصحر الرجل، أى: خرج إلى الصحراء والمراد هنا تجهر به ولا تكتم أمره (ع)]] به. والضمير لموسى والمراد بأمره وقصته، وأنه ولدها لَوْلا أَنْ رَبَطْنا عَلى قَلْبِها بإلهام الصبر، كما يربط على الشيء المنفلت ليقرّ ويطمئن لِتَكُونَ مِنَ الْمُؤْمِنِينَ من المصدقين بوعد الله، وهو قوله إِنَّا رَادُّوهُ إِلَيْكِ ويجوز: وأصبح فؤادها فارغا من الهم، حين سمعت أن فرعون عطف عليه وتبناه إن كادت لتبدي بأنه ولدها، لأنها لم تملك نفسها فرحا وسرورا بما سمعت، لولا أنا طامنا قلبها وسكنّا قلقه الذي حدث به من شدّة الفرح والابتهاج، لتكون من المؤمنين الواثقين بوعد الله لا بتبني فرعون وتعطفه. وقرئ: مؤسى، بالهمزة: جعلت الضمة في جارة الواو- وهي الميم- كأنها فيها، فهمزت كما تهمز واو وجوه قُصِّيهِ اتبعى أثره وتتبعى خبره. وقرئ فبصرت بالكسر- يقال بصرت به عن جنب وعن جنابة، بمعنى: عن بعد. وقرئ: عن جانب، وعن جنب. والجنب: الجانب. يقال: قعد إلى جنبه وإلى جانبه، أى: نظرت إليه مزورة متجانفة مخاتلة [[قوله «متجانفة مخاتلة» متجانفة: أى مائلة. ومخاتلة: أى مخادعة. أفاده الصحاح. (ع)]] . وهم لا يحسون بأنها أخته، وكان اسمها مريم.',     source_page = '563',     updated_at  = datetime('now') WHERE id = 'QR:TE:be400e6019a6dad2d941d300';
UPDATE qr_tafsir_entries SET content_ar = 'فإن قلت: ما الفرق بين فعل الاستجابة في الآية، وبينه في قوله: فلم يستجبه عند ذاك مجيب [[قوله «فلم يستجبه عند ذاك مجيب» صدره: وداع دعا يا من يجيب إلى الندى اه عليان. قلت: وقد تقدم شرح هذا الشاهد بالجزء الأول فراجعه إن شئت اه مصححه.]] حيث عدّى بغير اللام؟ قلت: هذا الفعل يتعدّى إلى الدعاء بنفسه وإلى الداعي باللام، ويحذف الدعاء إذا عدّى إلى الداعي في الغالب، فيقال، استجاب الله دعاءه أو استجابة له، ولا يكاد يقال: استجاب له دعاءه. وأما البيت فمعناه: فلم يستجب دعاءه، على حذف المضاف. فإن قلت: فالاستجابة تقتضي دعاء ولا دعاء هاهنا. قلت: قوله فأتوا بكتاب أمر بالإتيان والأمر بعث على الفعل ودعاء إليه، فكأنه قال: فإن لم يستجيبوا دعاءك إلى الإتيان بالكتاب الأهدى، فاعلم أنهم قد ألزموا ولم تبق لهم حجة إلا اتباع الهوى، ثم قال وَمَنْ أَضَلُّ مِمَّنِ لا يتبع في دينه إلا هَواهُ بِغَيْرِ هُدىً مِنَ اللَّهِ أى مطبوعا على قلبه ممنوع الألطاف إِنَّ اللَّهَ لا يَهْدِي أى لا يلطف بالقوم الثابتين على الظلم الذين اللاطف بهم عابث. وقوله بغير هدى في موضع الحال، يعنى: مخذولا مخلى بينه وبين هواه.',     source_page = '456',     updated_at  = datetime('now') WHERE id = 'QR:TE:23d240a558d2dea2a89b882b';
UPDATE qr_tafsir_entries SET content_ar = 'وقرئ: يصدنك، من أصدّه بمعنى صدّه، وهي في لغة كلب. وقال: أناس أصدوا النّاس بالسّيف عنهمو ... صدود السّواقى عن أنوف الحوائم [[تقدم شرح هذا الشاهد بالجزء الثاني فراجعه إن شئت اه مصححه.]] بَعْدَ إِذْ أُنْزِلَتْ إِلَيْكَ بعد وقت إنزاله [[قوله «بعد وقت إنزاله» لعله: إنزالها. (ع)]] وإذ تضاف إليه أسماء الزمان، كقولك: حينئذ وليلتئذ ويومئذ وما أشبه ذلك. والنهى عن مظاهرة الكافرين ونحو ذلك من باب التهييج الذي سيق ذكره.',     source_page = '538',     updated_at  = datetime('now') WHERE id = 'QR:TE:e2c60db4e6b1691f9223c1ef';
UPDATE qr_tafsir_entries SET content_ar = 'مكية [إلا من آية 1 إلى غاية آية 11 فمدنية] وآياتها 69 [نزلت بعد الروم] بِسْمِ اللَّهِ الرَّحْمنِ الرَّحِيمِ الحسبان لا يصح تعليقه بمعاني المفردات، ولكن بمضامين الجمل. ألا ترى أنك لو قلت: حسبت زيدا وظننت الفرس: لم يكن شيئا حتى تقول: حسبت زيدا عالما وظننت الفرس جوادا، لأنّ قولك: زيد عالم، أو الفرس جواد كلام دال على مضمون، فأردت الإخبار عن ذلك المضمون ثابتا عندك على وجه الظن لا اليقين، فلم تجد بدّا في العبارة عن ثباته عندك على ذلك الوجه، من ذكر شطرى الجملة مدخلا عليهما فعل الحسبان، حتى يتم لك غرضك. فإن قلت: فأين الكلام الدال على المضمون الذي يقتضيه الحسبان في الآية؟ قلت: هو في قوله أَنْ يُتْرَكُوا أَنْ يَقُولُوا آمَنَّا وَهُمْ لا يُفْتَنُونَ وذلك أن تقديره: أحسبوا تركهم غير مفتونين، لقولهم: آمنا، فالترك أول مفعولي حسب، ولقولهم: آمنا، هو الخبر. وأما «غير مفتونين» فتتمة الترك، لأنه من الترك الذي هو بمعنى التصيير، كقوله: فتركته جزر السّباع ينشنه [[تقدم شرح هذا الشاهد بالجزء الأول فراجعه إن شئت اه مصححه.]] ألا ترى أنك قبل المجيء بالحسبان، تقدر أن تقول: تركهم غير مفتونين، لقولهم: آمنا، على تقدير: حاصل ومستقر، قبل اللام. فإن قلت: أَنْ يَقُولُوا هو علة تركهم غير مفتونين، فكيف يصح أن يقع خبر مبتدأ؟ قلت: كما تقول خروجه لمخافة الشر، وضربه للتأديب، وقد كان التأديب والمخافة في قولك: خرجت مخافة الشر، وضربته تأديبا: تعليلين. وتقول أيضا: حسبت خروجه لمخافة الشر، وظننت ضربه للتأديب، فتجعلهما مفعولين كما جعلتهما مبتدأ وخبرا. والفتنة: الامتحان بشدائد التكليف: من مفارقة الأوطان، ومجاهدة الأعداء، وسائر الطاعات الشاقة، وهجر الشهوات والملاذ، وبالفقر والقحط، وأنواع المصائب في الأنفس والأموال. وبمصابرة الكفار على أذاهم وكيدهم وضرارهم. والمعنى: أحسب الذين أجروا كلمة الشهادة على ألسنتهم وأظهروا القول بالإيمان: أنهم يتركون بذلك غير ممتحنين، بل يمحنهم الله بضروب المحن، حتى يبلو صبرهم، وثبات أقدامهم، وصحة عقائدهم، ونصوع نياتهم، ليتميز المخلص من غير المخلص، والراسخ في الدين من المضطرب، والمتمكن من العابد على حرف، كما قال لَتُبْلَوُنَّ فِي أَمْوالِكُمْ وَأَنْفُسِكُمْ وَلَتَسْمَعُنَّ مِنَ الَّذِينَ أُوتُوا الْكِتابَ مِنْ قَبْلِكُمْ وَمِنَ الَّذِينَ أَشْرَكُوا أَذىً كَثِيراً وَإِنْ تَصْبِرُوا وَتَتَّقُوا فَإِنَّ ذلِكَ مِنْ عَزْمِ الْأُمُورِ وروى أنها نزلت في ناس من أصحاب رسول الله ﷺ قد جزعوا من أذى المشركين. وقيل في عمار بن ياسر: وكان يعذب في الله. وقيل: في ناس أسلموا بمكة، فكتب إليهم المهاجرون: لا يقبل منكم إسلامكم حتى تهاجروا، فخرجوا فتبعهم المشركون فردّوهم، فلما نزلت كتبوا بها إليهم، فخرجوا فاتبعهم المشركون فقاتلوهم، فمنهم من قتل ومنهم من نجا. وقيل: في مهجع بن عبد الله مولى عمر بن الخطاب رضى الله عنه، وهو أوّل قتيل من المسلمين يوم بدر، رماه عامر بن الحضرمي فقال رسول الله ﷺ: سيد الشهداء مهجع، وهو أول من يدعى إلى باب الجنة من هذه الأمة [[ذكره الثعلبي عن مقاتل قال «نزلت هاتان الآيتان في مهجع بن عبد الله مولى عمر، كان أول من قتل من المسلمين يوم بدر، رماه عامر بن الحضرمي بسهم فقتله. فقال النبي ﷺ: سيد الشهداء مهجع وهو أول من يدعى إلى باب الجنة من هذه الأمة» وسنده إلى مقاتل في أول كتابه، وفي الدلائل لابن أبى شيبة من طريق القاسم بن عبد الرحمن بن عبد الله بن مسعود قال «أول من استشهد يوم بدر مهجع مولى عمر» .]] ، فجزع عليه أبواه وامرأته وَلَقَدْ فَتَنَّا موصول بأحسب أو بلا يفتنون، كقولك: ألا يمتحن فلان وقد امتحن من هو خير منه، يعنى: أن أتباع الأنبياء عليهم السلام قبلهم، قد أصابهم من الفتن والمحن نحو ما أصابهم. أو ما هو أشدّ منه فصبروا، كما قال: وَكَأَيِّنْ مِنْ نَبِيٍّ قاتَلَ مَعَهُ رِبِّيُّونَ كَثِيرٌ فَما وَهَنُوا ... الآية وعن النبي ﷺ: «قد كان من قبلكم يؤخذ فيوضع المنشار على رأسه فيفرق فرقتين، ما يصرفه ذلك عن دينه، ويمشط بأمشاط الحديد ما دون عظمه من لحم وعصب، ما يصرفه ذلك عن دينه» [[أخرجه البخاري من حديث خباب بن الأرت به، وأتم منه.]] فَلَيَعْلَمَنَّ اللَّهُ بالامتحان الَّذِينَ صَدَقُوا في الإيمان وَلَيَعْلَمَنَّ الْكاذِبِينَ فيه. فإن قلت: كيف وهو عالم بذلك فيما لم يزل؟ قلت: لم يزل يعلمه معدوما، ولا يعلمه موجودا إلا إذا وجد [[قال محمود: «إن قلت هو لم يزل يعلم الصادقين والكاذبين قبل الامتحان، فما وجه هذا الكلام؟ قلت: لم يزل يعلمه معدوما ولا يعلمه موجودا إلا إذا وجد» قال أحمد: فيما ذكر إيهام بمذهب فاسد، وهو اعتقاد أن العلم بالكائن غير العلم بأن سيكون، والحق أن علم الله تعالى واحد يتعلق بالموجود زمان وجوده وقبله وبعده على ما هو عليه، وفائدة ذكر العلم هاهنا وإن كان سابقا على وجود المعلوم: التنبيه بالسبب على المسبب وهو الجزاء، كأنه قال تعالى: لنعلمنهم فلنجازينهم بحسب علمه فيهم، والله أعلم.]] ، والمعنى: وليتميزن الصادق منهم من الكاذب. ويجوز أن يكون وعدا ووعيدا، كأنه قال: وليثيبن الذين صدقوا وليعاقبنّ الكاذبين. وقرأ على رضى الله عنه والزهري: وليعلمنّ، من الإعلام، أى: وليعرفنهم الله الناس من هم. أو ليسمنهم بعلامة يعرفون بها من بياض الوجوه وسوادها، وكحل العيون وزرقتها.',     source_page = '75',     updated_at  = datetime('now') WHERE id = 'QR:TE:2f6201e694f2f44ed6e9a9a9';
UPDATE qr_tafsir_entries SET content_ar = 'فإن قلت: فما تصنع بقوله قُلْ سِيرُوا فِي الْأَرْضِ؟ قلت: هي حكاية كلام حكاه إبراهيم عليه السلام لقومه، كما يحكى رسولنا ﷺ كلام الله على هذا المنهاج في أكثر القرآن فإن قلت: فإذا كانت خطابا لقريش فما وجه توسطهما بين طرفى قصة إبراهيم والجملة؟ أو الجمل الاعتراضية لا بد لها من اتصال بما وقعت معترضة فيه؟ ألا تراك لا تقول: مكة- وزيد أبوه قائم- خير بلاد الله؟ قلت: إيراد قصة إبراهيم ليس إلا إرادة للتنفيس عن رسول الله ﷺ، وأن تكون مسلاة له ومتفرجا بأنّ أباه إبراهيم خليل الله كان ممنوّا بنحو ما مني [[قوله «كان ممنوا بنحو ماضى؟؟؟ به» أى: مبتلى. في الصحاح: منوته ومنيته، إذا ابتليته. (ع)]] به من شرك قومه وعبادتهم الأوثان، فاعترض بقوله: وإن تكذبوا، على معنى إنكم يا معشر قريش إن تكذبوا محمدا فقد كذب إبراهيم قومه وكل أمة نبيها، لأن قوله فَقَدْ كَذَّبَ أُمَمٌ مِنْ قَبْلِكُمْ لا بد من تناوله لأمّة إبراهيم، وهو كما ترى اعتراض واقع [[قوله «وهو كما ترى اعتراض واقع» لعله: واقع موقعه. (ع)]] متصل، ثم سائر الآيات الواطئة عقبها من أذيالها وتوابعها، لكونها ناطقة بالتوحيد ودلائله، وهدم الشرك وتوهين قواعده، وصفة قدرة الله وسلطانه، ووضوح حجته وبرهانه. قرئ يَرَوْا بالياء والتاء. ويبدئ ويبدأ. وقوله ثُمَّ يُعِيدُهُ ليس بمعطوف على يبدئ، وليست الرؤية واقعة عليه، وإنما هو إخبار على حياله بالإعادة بعد الموت، كما وقع النظر في قوله تعالى: فَانْظُرُوا كَيْفَ بَدَأَ الْخَلْقَ ثُمَّ اللَّهُ يُنْشِئُ النَّشْأَةَ الْآخِرَةَ على البدء دون الإنشاء، ونحوه قولك: ما زلت أوثر فلانا وأستخلفه على من أخلفه [[قال محمود: «يعيده ليس معطوفا على يبدئ، وإنما هو إخبار على حياله، كما وقع كَيْفَ بَدَأَ الْخَلْقَ ثُمَّ اللَّهُ يُنْشِئُ النَّشْأَةَ الْآخِرَةَ كقولك ما زلت أوثر فلانا وأستخلفه بعدي» قال أحمد، وقد تقدم له عند قوله تعالى أَمَّنْ يَبْدَؤُا الْخَلْقَ ثُمَّ يُعِيدُهُ أنه معطوف، وصحح العطف- وإن كانوا ينكرون الاعادة- لأن الاعتراف بها لازم لهم، وقد أبى هاهنا جعله معطوفا، فالفرق والله أعلم أنه هاهنا لو عطف الاعادة على البداءة لدخلت في الرؤية الماضية، وهي لم تقع بعد، ولا كذلك في آية النمل، ولقائل أن يقول: هي وإن لم تقع، إلا أنها باخبار الله تعالى بوقوعها كالواقعة المرئية، فعوملت معاملة ما رئي وشوهد إلا أن جعله خبرا ثانيا أوضح، والله أعلم.]] . فإن قلت: هو معطوف بحرف العطف، فلا بد له من معطوف عليه، فما هو؟ قلت: هو جملة قوله أَوَلَمْ يَرَوْا كَيْفَ يُبْدِئُ اللَّهُ الْخَلْقَ وكذلك: وأستخلفه، معطوف على جملة قوله: ما زلت أوثر فلانا ذلِكَ يرجع إلى ما يرجع إليه هو في قوله وَهُوَ أَهْوَنُ عَلَيْهِ من معنى يعيد. دل بقوله النَّشْأَةَ الْآخِرَةَ على أنهما نشأتان، وأن كل واحدة منهما إنشاء، أى: ابتداء واختراع، وإخراج من العدم إلى الوجود، لا تفاوت بينهما إلا أن الآخرة إنشاء بعد إنشاء مثله، والأولى ليست كذلك. وقرئ: النشأة والنشاءة، كالرأفة والرآفة. فإن قلت: ما معنى الإفصاح باسمه مع إيقاعه مبتدأ في قوله ثُمَّ اللَّهُ يُنْشِئُ النَّشْأَةَ الْآخِرَةَ بعد إضماره في قوله: كيف بدأ الخلق؟ وكان القياس أن يقال: كيف بدأ الله الخلق ثم ينشئ النشأة الآخرة؟ قلت: الكلام معهم كان واقعا في الإعادة، وفيها كانت تصطك الركب، فلما قرّرهم في الإبداء بأنه من الله، احتج عليهم بأن الإعادة إنشاء مثل الإبداء، فإذا كان الله الذي لا يعجزه شيء هو الذي لم يعجزه الإبداء، فهو الذي وجب أن لا تعجزه الإعادة [[قال محمود: «إن قلت ما وجه الإفصاح باسمه تعالى مع النشأة الآخرة، بعد إضماره في البداءة أو لا؟ قلت: لأن النشأة الآخرة هي المقصودة وفيها كانت تصطك الركب، فكانت خليقة بإبراز اسمه تعالى تحقيقا لنسبة الاعادة إلى من نسبت إليه الأولى» قال أحمد: والأصل الاظهار ثم الإضمار، ويليه لقصد التفخيم: الاظهار بعد الاظهار، ويليه وهو أفخم الثلاثة: الاظهار بعد الإضمار كما في الآية، والله أعلم.]] ، فكأنه قال: ثم ذاك الذي أنشأ النشأة الأولى هو الذي ينشئ النشأة الآخرة، فللدلالة والتنبيه على هذا المعنى أبرز اسمه وأوقعه مبتدأ يُعَذِّبُ مَنْ يَشاءُ تعذيبه وَيَرْحَمُ مَنْ يَشاءُ رحمته، ومتعلق المشيئتين مفسر مبين في مواضع من القرآن [[قوله «ومتعلق المشيئتين مفسر مبين في مواضع من القرآن» تفسيره بما يأتى مبنى على أنه تعالى يجب عليه تعذيب الكافر والفاسق إذا لم يتوبا وإثابة المعصوم والتائب، وهو مذهب المعتزلة. ولا يجب عليه تعالى شيء عند أهل السنة، فالمشيئة في الآية على إطلاقها. (ع)]] وهو من يستوجبهما من الكافر والفاسق إذا لم يتوبا، ومن المعصوم والتائب تُقْلَبُونَ تردون وترجعون وَما أَنْتُمْ بِمُعْجِزِينَ ربكم أى لا تفوتونه إن هربتم من حكمه وقضائه فِي الْأَرْضِ الفسيحة وَلا فِي السَّماءِ التي هي أفسح منها وأبسط لو كنتم فيها، كقوله تعالى: إِنِ اسْتَطَعْتُمْ أَنْ تَنْفُذُوا مِنْ أَقْطارِ السَّماواتِ وَالْأَرْضِ فَانْفُذُوا، وقيل: ولا من في السماء [[قوله «وقيل ولا من في السماء» عبارة الخازن: ولا من في السماء بمعجز. (ع)]] كما قال حسان رضى الله عنه: أمن يهجو رسول الله منكم ... ويمدحه وينصره سواء [[تقدم شرح هذا الشاهد ضمن أبيات بالجزء الثاني فراجعه إن شئت اه مصححه.]] ويحتمل أن يراد: لا تعجزونه كيفما هبطتم في مهاوي الأرض وأعماقها، أو علوتم في البروج والقلاع الذاهبة في السماء، كقوله تعالى وَلَوْ كُنْتُمْ فِي بُرُوجٍ مُشَيَّدَةٍ أو لا تعجزون أمره الجاري في السماء والأرض أن يجرى عليكم، فيصيبكم ببلاء يظهر من الأرض أو ينزل من السماء.',     source_page = '563',     updated_at  = datetime('now') WHERE id = 'QR:TE:eaa737c0cd4ba65a8f3f04df';
UPDATE qr_tafsir_entries SET content_ar = 'قرئ: آية، وآيات. أرادوا: هلا أنزل عليه آية مثل ناقة صالح ومائدة عيسى عليهما السلام ونحو ذلك إِنَّمَا الْآياتُ عِنْدَ اللَّهِ ينزل أيتها شاء، ولو شاء أن ينزل ما تقترحونه لفعل وَإِنَّما أَنَا نَذِيرٌ كلفت الإنذار وإبانته بما أعطيت من الآيات، وليس لي أن أتخير على الله آياته فأقول، أنزل علىّ آية كذا دون آية كذا، مع علمى أنّ الغرض من الآية ثبوت الدلالة، والآيات كلها في حكم آية واحدة في ذلك، ثم قال أَوَلَمْ يَكْفِهِمْ آية مغنية عن سائر الآيات- إن كانوا طالبين للحق غير متعنتين- هذا القرآن الذي تدوم تلاوته عليهم في كل مكان وزمان فلا يزال معهم آية ثابتة لا تزول ولا تضمحلّ، كما تزول كل آية بعد كونها، وتكون في مكان دون مكان. إنّ في مثل هذه الآية الموجودة في كل مكان وزمان إلى آخر الدهر لَرَحْمَةً لنعمة عظيمة لا تشكر. وتذكرة لِقَوْمٍ يُؤْمِنُونَ وقيل: أو لم يكفهم، يعنى اليهود: أنا أنزلنا عليك الكتاب يتلى عليهم بتحقيق ما في أيديهم من نعتك ونعت دينك. وقيل: إنّ ناسا من المسلمين أتوا رسول الله ﷺ بكتف قد كتبوا فيها بعض ما يقول اليهود، فلما أن نظر إليها ألقاها وقال: كفى بها حماقة قوم أو ضلالة قوم أن يرغبوا عما جاءهم به نبيهم إلى ما جاء به غير نبيهم، فنزلت [[أخرجه الطبري وأبو داود في المراسيل من طريق يحيى بن جعدة «أن النبي ﷺ أتاه قوم من المسلمين بكتاب في كتف» فذكر نحوه ولفظ الطبري كالأصل.]] . والوجه ما ذكرناه كَفى بِاللَّهِ بَيْنِي وَبَيْنَكُمْ شَهِيداً أنى قد بلغتكم ما أرسلت به إليكم وأنذرتكم، وأنكم قابلتمونى بالجحد والتكذيب يَعْلَمُ ما فِي السَّماواتِ وَالْأَرْضِ فهو مطلع على أمرى وأمركم، وعالم بحقي وباطلكم وَالَّذِينَ آمَنُوا بِالْباطِلِ منكم وهو ما تعبدون من دون الله وَكَفَرُوا بِاللَّهِ وآياته أُولئِكَ هُمُ الْخاسِرُونَ المغبونون في صفقتهم حيث اشتروا الكفر بالإيمان، إلا أن الكلام ورد مورد الإنصاف، كقوله وَإِنَّا أَوْ إِيَّاكُمْ لَعَلى هُدىً أَوْ فِي ضَلالٍ مُبِينٍ وكقول حسان: فشر كما لخير كما الفداء [[تقدم شرح هذا الشاهد ضمن أبيات بالجزء الثاني فراجعه إن شئت اه مصححه.]] وروى أنّ كعب بن الأشرف وأصحابه قالوا: يا محمد، من يشهد لك بأنك رسول الله، فنزلت.',     source_page = '563',     updated_at  = datetime('now') WHERE id = 'QR:TE:7d3b566417763f70ae733cf6';
UPDATE qr_tafsir_entries SET content_ar = 'يقال بدع الشيء فهو بديع، كقولك: بزع الرجل [[قوله «بزع الرجل» بزع بالزاي كظرف وزنا ومعنى. أفاده الصحاح وصرح كقولك بأنه لا يوصف به الأحداث. (ع)]] فهو بزيع. وبَدِيعُ السَّماواتِ من إضافة الصفة المشبهة إلى فاعلها أى بديع سماواته وأرضه. وقيل البديع بمعنى المبدع، كما أنّ السميع في قول عمرو: أمِنْ رَيْحَانَةَ الدَّاعِى السَّمِيعُ [[مر شرح هذا الشاهد من هذا الجزء فراجعه إن شئت اه مصححه.]] بمعنى المسمع وفيه نظر كُنْ فَيَكُونُ من كان التامّة، أى أحدث فيحدث. وهذا مجاز من الكلام وتمثيل ولا قول ثم، كما لا قول في قوله: إذْ قَالَتِ الْأَنْسَاعُ لِلْبَطْنِ الْحَقِ [[إذا قالت الأنساع للبطن الحق ... قدوما فآضت كالفنيق المحنق لأبى النجم العجلى. والنسع- بالكسر-: حزام عريض يشد به وسط الدابة وستر الهودج. والحق: فعل أمر، أى التصق يا بطن بالظهر وانضمر. وقدوما: نصب على المصدر بمحذوف أو بما قبله على أنه مفعول له. وآض يئيض أيضا: إذا صار يصير، أو رجع يرجع، أى صارت الناقة كالفنيق. ويروى: فأحنت، أى حقدت واغتاظت الناقة، وأصله بكسر الحاء فسكن تخفيفاً كما تقدم في ضجر ودبر. والفنيق: الفحل المنعم المكرم. يقال: أفنقه، إذا نعمه. وجارية فنقة: ناعمة. والمحنق: المغيظ، من الحنق وهو الحقد والغيظ. ويروى «إذ قالت» بدل «إذا قالت» . والحق: بوصل الهمزة وقطعها. والمحنق بسكون الحاء، فيكون من الرجز، لا من الطويل. وقدم قدما، كنصر نصراً، إذا تقدم. والظاهر أن هذه الرواية هي الصواب لكثرة رجز أبى النجم. وإثبات القول للأنساع ومخاطبتها البطن من باب التمثيل. والمعنى أنه شد عليها أدوات السفر فاغتاظت غيظاً شديداً، كالفحل المكرم الذي غاظه غيره.]] وإنما المعنى أنّ ما قضاه من الأمور وأراد كونه، فإنما يتكوّن ويدخل تحت الوجود من غير امتناع ولا توقف، كما أنّ المأمور المطيع الذي يؤمر فيمتثل لا يتوقف ولا يمتنع ولا يكون منه الإباء. أكد بهذا استبعاد الولادة لأنّ من كان بهذه الصفة من القدرة كانت حاله مباينة لأحوال الأجسام في توالدها. وقرئ (بديع السماوات) مجروراً على أنه بدل من الضمير في له. وقرأ المنصور بالنصب على المدح.',     source_page = '60',     updated_at  = datetime('now') WHERE id = 'QR:TE:72ac5b4a0149b79c4b823a94';
UPDATE qr_tafsir_entries SET content_ar = 'وَهُوَ كُرْهٌ لَكُمْ من الكراهة بدليل قوله وَعَسى أَنْ تَكْرَهُوا شَيْئاً ثم إما أن يكون بمعنى الكراهة على وضع المصدر موضع الوصف مبالغة، كقولها: فَإنَّمَا هِىَ إقْبَالٌ وَإدْبَارُ [[مر شرح هذا الشاهد بهذا الجزء فراجعه إن شئت اه مصححه]] كأنه في نفسه لفرط كراهتهم له. وإما أن يكون فعلا بمعنى مفعول كالخبز بمعنى المخبوز، أى وهو مكروه لكم. وقرأ السلمى- بالفتح- على أن يكون بمعنى المضموم، كالضعف والضعف، ويجوز أن يكون بمعنى الإكراه على طريق المجاز، كأنهم أكرهوا عليه لشدة كراهتهم له ومشقته عليهم. ومنه قوله تعالى: (حَمَلَتْهُ أُمُّهُ كُرْهاً وَوَضَعَتْهُ كُرْهاً) [[قوله «ووضعته كرها وعلى قوله تعالى» أى جميع ما كلفوه جار على قوله تعالى: (وَعَسى أَنْ تَكْرَهُوا ... ) الخ فان النفوس تكرهه وهو خير لهم، وتحب خلافه وهو شر لهم. (ع)]] ، وعلى قوله تعالى: (وَعَسى أَنْ تَكْرَهُوا شَيْئاً) جميع ما كلفوه، فإن النفوس تكرهه وتنفر عنه وتحب خلافه وَاللَّهُ يَعْلَمُ ما يصلحكم وما هو خير لكم وَأَنْتُمْ لا تَعْلَمُونَ ذلك.',     source_page = '218',     updated_at  = datetime('now') WHERE id = 'QR:TE:93740035e4bc3f0a175ff8b5';
UPDATE qr_tafsir_entries SET content_ar = 'لا جُناحَ عَلَيْكُمْ لا تبعة عليكم من إيجاب مهر إِنْ طَلَّقْتُمُ النِّساءَ ما لَمْ تَمَسُّوهُنَّ ما لم تجامعوهنّ أَوْ تَفْرِضُوا لَهُنَّ فَرِيضَةً إلا أن تفرضوا لهن فريضة، أو حتى تفرضوا، وفرض الفريضة: تسمية المهر. وذلك أن المطلقة غير المدخول بها إن سمى لها مهر فلها نصف المسمى، وإن لم يسم لها فليس لها نصف مهر المثل ولكن المتعة. والدليل على أن الجناح تبعة المهر قوله: (وإن طلقتموهن) إلى قوله: (فَنِصْفُ ما فَرَضْتُمْ) فقوله: فنصف ما فرضتم: إثبات للجناح المنفي ثمة، والمتعة درع وملحفة وخمار على حسب الحال عند أبى حنيفة، إلا أن يكون مهر مثلها أقل من ذلك. فلها الأقل من نصف مهر المثل ومن المتعة، ولا ينقص من خمسة دراهم لأن أقل المهر عشرة دراهم فلا ينقص من نصفها. والْمُوسِعِ الذي له سعة. والْمُقْتِرِ الضيق الحال. وَقَدَّرَهُ مقداره الذي يطيقه، لأنّ ما يطيقه هو الذي يختص به. وقرئ بفتح الدال. والقدْر والقدَر لغتان. وعن النبي صلى اللَّه عليه وسلم أنه قال لرجل من الأنصار تزوج امرأة ولم يسم لها مهراً، ثم طلقها قبل أنّ يمسها: «أمتعتها» ؟ قال: لم يكن عندي شيء. قال: «متعها بقلنسوتك [[لم أجده.]] » . وعند أصحابنا لا تجب المتعة إلا لهذه وحدها، وتستحب لسائر المطلقات ولا تجب. مَتاعاً تأكيد لمتعوهن، بمعنى تمتيعاً بِالْمَعْرُوفِ بالوجه الذي يحسن في الشرع والمروءة حَقًّا صفة لمتاعا، أى متاعا واجبا عليهم. أو حق ذلك حقاً عَلَى الْمُحْسِنِينَ على الذين يحسنون إلى المطلقات بالتمتيع، وسماهم قبل الفعل محسنين كما قال صلى اللَّه عليه وسلم «من قتل قتيلا فله سلبه [[تقدم في من هذا الجزء.]] » إِلَّا أَنْ يَعْفُونَ يريد المطلقات. فإن قلت: أى فرق بين قولك: الرجال يعفون. والنساء يعفون؟ قلت: الواو في الأوّل ضميرهم، والنون علم الرفع. والواو في الثاني لام الفعل والنون ضميرهنّ، والفعل مبنى لا أثر في لفظه للعامل وهو في محل النصب «ويعفو: عطف على محله. والَّذِي بِيَدِهِ عُقْدَةُ النِّكاحِ الولىّ [[قال محمود رحمه اللَّه: «والذي بيده عقدة النكاح الولي ... الخ» قال أحمد رحمه اللَّه: هذا النقل وهم فيه الزمخشري عن الشافعي رضى اللَّه عنه، فان مذهبه موافق لمذهب أبى حنيفة رضى اللَّه عنه في أن المراد به الزوج. وإنما ذهب إلى أن المراد الولي الامام مالك رضى اللَّه عنه، وصدق الزمخشري أنه قول ظاهر الصحة، عليه رونق الحق وطلاوة الصواب لوجوه: الأول: أن الذي بيده عقدة النكاح ثابتة مستقرة هو الولي. وأما الزوج فله ذلك حالة العقد المتقدم خاصة، ثم هو بعد الطلاق، والكلام حينئذ ليس من عقدة النكاح في شيء البتة، فان قيل: أطلق عليه ذلك بعد الطلاق بتأويل «كان» مقدرة، فلا يخفى على المنصف ما في ذلك من البعد والخروج من حد إطلاق الكلام وأصله. الثاني: أن الخطاب الأول للزوجات اتفاقا بقوله: (إِلَّا أَنْ يَعْفُونَ) وفيهن من لا عفو لها البتة كالأمة والبكر، فلولا استتمام التقسيم بصرف الثاني إلى الولي على ابنته البكر أو أمته، وإلا لزم الخروج عن ظاهر عموم الأول، وحيث حمل الكلام على الولي صار الكلام بمعنى: إلا أن يعفون كن أهلا للعفو، أو يعفو لهن إن لم يكن أهلا، ولهذا كان الولي الذي يعفو ويعتبر عفوه عند مالك: هو الأب في ابنته البكر. والسيد في أمته خاصة. الثالث: أن الكتاب العزيز جدير بتناسب الأقسام وانتظام أطراف الكلام، والأمر فيه على هذا المحمل بهذه المثابة، فان الآية حينئذ مشتملة على خطاب الزوجات ثم الأولياء ثم الأزواج بقوله: (وَلا تَنْسَوُا الْفَضْلَ بَيْنَكُمْ) فتكون على هذا الوجه ملية بالفوائد جامعة للمقاصد. الرابع: أن المضاف إلى صاحب عقدة النكاح العفو كما هو مضاف إلى الزوجات، والعفو: الاسقاط لغة وهو المراد في الأول اتفاقا، إذ المضاف إلى الزوجات هو الاسقاط بلا ريب، ولو كان المراد بصاحب العقدة الزوج لتعين حمل العفو على تكميل المهر وإعطائه ما لا يستحق عليه، وهذا إنما يطابقه من الأسماء التفضل. ومن ثم قال في خطاب الأزواج (وَلا تَنْسَوُا الْفَضْلَ بَيْنَكُمْ) لأن المبذول من جهته غير مستحق عليه فهو فضل لا عفو. ولا يقال: لعل الزوج تعجل المهر كاملا قبل الطلاق وطلق فيجب استرجاع النصف فيسقطه ويعفو عنه وحينئذ يبقى العفو من جانب الزوج على ظاهره وحقيقته، لأنا نقول: حسبنا في رد هذا الوجه ما فيه من الكلفة وتقدير ما الأصل خلافه. الخامس: أن صدر الآية خطاب للأزواج في قوله: (وَإِنْ طَلَّقْتُمُوهُنَّ) إلى قوله: (فَرَضْتُمْ) فلو جاء قوله (أَوْ يَعْفُوَا الَّذِي بِيَدِهِ عُقْدَةُ النِّكاحِ) مراداً به الزوج لكان عدولا والتفاتا من الخطاب إلى الغيبة، وليس هذا من مواضعه، ولأجل هذا جاء قوله: (وَلا تَنْسَوُا الْفَضْلَ بَيْنَكُمْ) على صيغة الخطاب، لأن المراد به الأزواج لخطابهم أولا السادس: أن قوله: (إِلَّا أَنْ يَعْفُونَ) وما عطف عليه استثناء من قوله: (فَنِصْفُ ما فَرَضْتُمْ) وأصل الكلام: فنصف ما فرضتم واجب عليكم إلا أن يعفو عنه الزوجات فليس بواجب عليكم إذاً، فإذا حمل الكلام على الولي استقام، إذ هم لو كملوا المهر لهن فالنصف واجب عليهم ولا يتغير ولا يخالف الحالة المستثناة مما وقع منه الاستثناء، فلا يجرى الاستثناء على حقيقته في المخالفة بين الأول والثاني، إلا أن يقال: مقتضى قوله: (فَنِصْفُ ما فَرَضْتُمْ) واجب عليكم: أن النصف الآخر غير مؤدى إليهن لأنه ساقط عن الزوج، فإذا عفا بمعنى كمل المهر فقد صار النصف الآخر مؤدى إليهن، ففي هذا التأويل من الكلفة ما يسقط مؤنة رده.]] يعنى إلا أن تعفو المطلقات عن أزواجهن فلا يطالبنهم بنصف المهر، وتقول المرأة: ما رآني ولا خدمته ولا استمتع بى فكيف آخذ منه شيئا، أو يعفو الولىّ الذي يلي عقد نكاحهن، وهو مذهب الشافعي. وقيل هو الزوج، وعفوه أن يسوق إليها المهر كاملا، وهو مذهب أبى حنيفة والأوّل ظاهر الصحة. وتسمية الزيادة على الحق عفواً فيها نظر، إلا أن يقال كان الغالب عندهم أن يسوق إليها المهر عند التزوّج، فإذا طلقها استحقّ أن يطالبها بنصف ما ساق إليها، فإذا ترك المطالبة فقد عفا عنها. أو سماه عفواً على طريق المشاكلة. وعن جبير بن مطعم أنه تزوج امرأة وطلقها قبل أن يدخل بها فأكمل لها الصداق وقال: أنا أحق بالعفو. وعنه أنه دخل على سعد بن أبى وقاص فعرض عليه بنتاً له فتزوّجها، فلما خرج طلقها وبعث إليها بالصداق كاملا، فقيل له: لم تزوّجتها؟ فقال: عرضها علىّ فكرهت ردّه، قيل: فلم بعثت بالصداق؟ قال: فأين الفضل؟ [[أخرجه الطبري من طريق ابن أبى ذئب عن سعيد بن محمد بن جبير عن جده جبير بن مطعم به سواء.]] والْفَضْلَ التفضل. أى ولا تنسوا أن يتفضل بعضكم على بعض وتتمرؤا ولا تستقصوا: وقرأ الحسن: أن يعفو الذي، بسكون الواو. وإسكان الواو والياء في موضع النصب تشبيه لهما بالألف لأنهما أختاها. وقرأ أبو نهيك: وأن يعفو، بالياء. وقرئ: ولا تنسو الفضل، بكسر الواو.',     source_page = '35',     updated_at  = datetime('now') WHERE id = 'QR:TE:3058e9a727c094f618270ad8';
UPDATE qr_tafsir_entries SET content_ar = 'إِسْرائِيلَ هو يعقوب عليه السلام لقب له، ومعناه في لسانهم: صفوة اللَّه، وقيل عبد اللَّه. وهو بزنة إبراهيم وإسماعيل غير منصرف مثلهما لوجود العلمية والعجمة. وقرئ إسرائل، وإسرائلّ. وذِكرهم النعمة: أن لا يخلوا بشكرها، ويعتدّوا بها، ويستعظموها، ويطيعوا ماتحها. وأراد بها ما أنعم به على آبائهم مما عدّد عليهم: من الإنجاء من فرعون وعذابه ومن الغرق. ومن العفو عن اتخاذ العجل، والتوبة عليهم، وغير ذلك، وما أنعم به عليهم من إدراك زمن محمد صلى اللَّه عليه وآله وسلم المبشر به في التوراة والإنجيل. والعهد يضاف إلى المعاهِد والمعاهَد جميعا. يقال أوفيت بعهدي، أى بما عاهدت عليه كقوله: (وَمَنْ أَوْفى بِعَهْدِهِ مِنَ اللَّهِ) وأوفيت بعهدك: أى بما عاهدتك عليه. ومعنى وَأَوْفُوا بِعَهْدِي وأوفوا بما عاهدتموني عليه من الإيمان بى والطاعة لي، كقوله: (وَمَنْ أَوْفى بِما عاهَدَ عَلَيْهُ اللَّهَ) ، (وَمِنْهُمْ مَنْ عاهَدَ اللَّهَ) ، (رِجالٌ صَدَقُوا ما عاهَدُوا اللَّهَ عَلَيْهِ) ، أُوفِ بِعَهْدِكُمْ بما عاهدتكم عليه من حسن الثواب على حسناتكم وَإِيَّايَ فَارْهَبُونِ فلا تنقضوا عهدى. وهو من قولك: زيدا رهبته. وهو أوكد في إفادة الاختصاص من (إِيَّاكَ نَعْبُدُ) . وقرئ (أوفّ) بالتشديد: أى أبالغ في الوفاء بعهدكم، كقوله: (مَنْ جاءَ بِالْحَسَنَةِ فَلَهُ خَيْرٌ مِنْها) . ويجوز أن يريد بقوله: (وَأَوْفُوا بِعَهْدِي) ما عاهدوا عليه ووعدوه من الإيمان بنبىّ الرحمة والكتاب المعجز. ويدل عليه قوله: وَآمِنُوا بِما أَنْزَلْتُ مُصَدِّقاً لِما مَعَكُمْ وَلا تَكُونُوا أَوَّلَ كافِرٍ بِهِ أوّل من كفر به، أو أول فريق أو فوج كافر به، أو: ولا يكن كل واحد منكم أوّل كافر به، كقولك: كسانا حلة، أى كل واحد منا. وهذا تعريض بأنه كان يجب أن يكونوا أوّل من يؤمن به لمعرفتهم به وبصفته. ولأنهم كانوا المبشرين بزمان من أوحى إليه والمستفتحين على الذين كفروا به، وكانوا يعدون اتباعه أول الناس كلهم، فلما بعث كان أمرهم على العكس كقوله: (لَمْ يَكُنِ الَّذِينَ كَفَرُوا مِنْ أَهْلِ الْكِتابِ وَالْمُشْرِكِينَ مُنْفَكِّينَ حَتَّى تَأْتِيَهُمُ الْبَيِّنَةُ) إلى قوله: (وَما تَفَرَّقَ الَّذِينَ أُوتُوا الْكِتابَ إِلَّا مِنْ بَعْدِ ما جاءَتْهُمُ الْبَيِّنَةُ) ، (فَلَمَّا جاءَهُمْ ما عَرَفُوا كَفَرُوا بِهِ) . ويجوز أن يراد: ولا تكونوا مثل أول كافر به، يعنى من أشرك به من أهل مكة. أى: ولا تكونوا وأنتم تعرفونه مذكورا في التوراة موصوفا، مثل من لم يعرفه وهو مشرك لا كتاب له. وقيل: الضمير في «به» لما معكم، لأنهم إذا كفروا بما يصدّقه فقد كفروا به. والاشتراء استعارة للاستبدال كقوله تعالى: (اشْتَرَوُا الضَّلالَةَ بِالْهُدى) وقوله: كَمَا اشْتَرَى المُسْلِمُ إذْ تَنَصَّرَا [[مر شرح هذا الشاهد من هذا الجزء فراجعه إن شئت. اه مصححه]] وقوله: فإنِّى شَرَيْتُ الحِلْمَ بَعْدَك بالجَهْلِ [[ألا زعمت أسماء أن لا أحبها ... فقلت بلى لولا ينازعني شغلي جزيتك ضعف الود لولا اشتكيته ... وما إن جزاك الضعف من أحد قبلي فان تزعمينى كنت أجهل فيكم ... فانى شريت الحلم بعدك بالجهل لأبى ذؤيب الهذلي. وزعمت: أى ظنت أنه الحال والشأن لا أحبها، فقلت لها: بلى أحبك لولا ينازعني: أى لولا أن ينازعني شغلي ويصرفني عن مودتك، أو لو لم ينازعني شغلي لوددتك: جزيتك ضعف الود: أى وددتك قدر المعتاد مرتين، أو قدر ودك مرتين، لولا اشتكيته: أى لولا أن مللته وسئمته، أو لو لم تشتكيه لضاعفته وأكثرته، فلولا هنا يحتمل أنها كلمة واحدة فيقدر بعدها «أن» المصدرية، ويحتمل أنها كلمتان بمعنى لو لم، لكنه استعمال نادر. ويجوز في «لولا» الثانية أنها حرف تحضيض وتوبيخ كهلا، يعنى كان الأحق بالشكوى كثرة المودة الموجبة للتهمة، لا كثرة الهجر. و «ما» نافية، و «إن» و «من» زائدتان. وأجهل: فعل مضارع مرفوع. وقيل: أفعل تفضيل منصوب. فيكم: أى بسببكم، أو فيما بين قبيلتكم. وعبر بضمير جمع المذكر للتعظيم. فانى شريت: جواب الشرط، واشترى الشيء: أخذه بالثمن، وشراه: باعه به، فالمراد هنا: استبدلت العقل بعد فراقك بالجهل، فهو مجاز مرسل علاقته الإطلاق. والمعنى: أنه اعتذر عن عدم ودها بشغله وشكواها وعقله.]] يعنى ولا تستبدلوا بآياتى ثمنا وإلا فالثمن هو المشترى به. والثمن القليل الرياسة التي كانت لهم في قومهم، خافوا عليها الفوات لو أصبحوا أتباعا لرسول اللَّه صلى اللَّه عليه وسلم فاستبدلوها- وهي بدل قليل ومتاع يسير- بآيات اللَّه وبالحق الذي كل كثير إليه قليل، وكل كبير إليه حقير، فما بال القليل الحقير. وقيل كانت عامّتهم يعطون أحبارهم من زروعهم وثمارهم، ويهدون إليهم الهدايا، ويرشونهم الرشا على تحريفهم الكلم، وتسهيلهم لهم ما صعب عليهم من الشرائع. وكان ملوكهم يدرّون عليهم الأموال ليكتموا أو يحرّفوا.',     source_page = '69',     updated_at  = datetime('now') WHERE id = 'QR:TE:bb50bac333cd0498d720101c';
UPDATE qr_tafsir_entries SET content_ar = 'القائلون: هم الملائكة، والأنبياء، والمؤمنون فِي كِتابِ اللَّهِ في اللوح. أو في علم الله وقضائه. أو فيما كتبه، أى: أوجبه بحكمته. ردّوا ما قالوه وحلفوا عليه، وأطلعوهم على الحقيقة تم وصلوا ذلك بتقريعهم على إنكار البعث بقولهم فَهذا يَوْمُ الْبَعْثِ وَلكِنَّكُمْ كُنْتُمْ لا تَعْلَمُونَ أنه حق لتفريطكم في طلب الحق واتباعه. فإن قلت: ما هذه الفاء؟ وما حقيقتها؟ قلت: هي التي في قوله: فقد جئنا خراسانا [[تقدم شرح هذا الشاهد بهذا الجزء فراجعه إن شئت اه مصححه.]] وحقيقتها: أنها جواب شرط يدل عليه الكلام، كأنه قال: إن صح ما قلتم من أن خراسان أقصى ما يراد بنا فقد جئنا خراسان، وآن لنا أن نخلص، وكذلك إن كنتم منكرين البعث فهذا يوم البعث، أى فقد تبين بطلان قولكم. وقرأ الحسن يوم البعث، بالتحريك لا يَنْفَعُ قرئ بالياء والتاء يُسْتَعْتَبُونَ من قولك: استعتبني فلان فأعتبته. أى: استرضانى فأرضيته، وذلك إذا كنت جانيا عليه. وحقيقة أعتبته: أزلت عتبه. ألا ترى إلى قوله: غضبت تميم أن تقتّل عامر ... يوم النّسار فأعتبوا بالصّيلم [[تقدم شرح هذا الشاهد بالجزء الأول فراجعه إن شئت اه مصححه.]] كيف جعلهم غضابا، ثم قال: فأعتبوا، أى: أزيل غضبهم. والغضب في معنى العتب. والمعنى: لا يقال لهم أرضوا ربكم بتوبة وطاعة، ومثله قوله تعالى لا يُخْرَجُونَ مِنْها، وَلا هُمْ يُسْتَعْتَبُونَ. فإن قلت: كيف جعلوا غير مستعتبين في بعض الآيات، وغير معتبين في بعضها، وهو قوله وَإِنْ يَسْتَعْتِبُوا فَما هُمْ مِنَ الْمُعْتَبِينَ؟ قلت: أما كونهم غير مستعتبين: فهذا معناه. وأما كونهم غير معتبين، فمعناه: أنهم غير راضين بما هم فيه، فشبهت حالهم بحال قوم جنى عليهم، فهم عاتبون على الجاني غير راضين عنه، فإن يستعتبوا الله: أى يسألوه إزالة ما هم فيه، فما هم من المجابين إلى إزالته.',     source_page = '271',     updated_at  = datetime('now') WHERE id = 'QR:TE:0b734d3e7bd325e1f94c2e4f';
UPDATE qr_tafsir_entries SET content_ar = 'قرئ مِثْقالَ حَبَّةٍ بالنصب والرفع، فمن نصب كان الضمير للهنة [[قوله «للهنة من الاساءة» في الصحاح «هن» : على وزن أخ: كلمة كناية. ومعناه: شيء، ومؤنثه: هنة. والقماءة: الصغر والحقارة. كذا في الصحاح (ع)]] من الإساءة أو الإحسان، أى: إن كانت مثلا في الصغر والقماءة كحبة الخردل، فكانت مع صغرها في أخفى موضع وأحرزه كجوف الصخرة [[قال محمود: «هذا من البديع الذي يسمى التتميم» قال أحمد: يعنى أنه تمم خلفاءها في نفسها بخفاء مكانها من الصخرة، وهو من وادى قولها كأنه علم في رأسه نار.]] أو حيث كانت في العالم العلوي أو السفلى يَأْتِ بِهَا اللَّهُ يوم القيامة فيحاسب بها عاملها إِنَّ اللَّهَ لَطِيفٌ يتوصل علمه إلى كل خفى خَبِيرٌ عالم بكنهه. وعن قتادة: لطيف باستخراجها، خبير بمستقرّها. ومن قرأ بالرفع: كان ضمير القصة، وإنما أنث المثقال لإضافته إلى الحبة، كما قال: كما شرقت صدر القناة من الدّم [[تقدم شرح هذا الشاهد بالجزء الأول فراجعه إن شئت اه مصححه.]] وروى أنّ ابن لقمان قال له: أرأيت الحبة تكون في مقل البحر- أى: في مغاصه- يعلمها الله؟ فقال: إنّ الله يعلم أصغر الأشياء في أخفى الأمكنة، لأنّ الحبة في الصخرة أخفى منها في الماء. وقيل: الصخرة هي التي تحت الأرض، وهي السجين يكتب فيها أعمال الكفار. وقرئ: فتكن، بكسر الكاف. من وكن الطائر يكن: إذا استقر في وكنته، وهي مقره ليلا.',     source_page = '395',     updated_at  = datetime('now') WHERE id = 'QR:TE:17f076003d4b1390744581dc';
UPDATE qr_tafsir_entries SET content_ar = 'النكاح: الوطء، وتسمية العقد نكاحا لملابسته له، من حيث أنه طريق إليه. ونظيره تسميتهم الخمر إثما، لأنها سبب في اقتراف الإثم، ونحوه في علم البيان قول الراجز: أسنمة الآبال في سحابه [[أقبل كالمستن من ربابه ... كأنما الوابل في مصابه أسنمة الآبال في سحابه يصف مطرا بالكثرة والثروة. ويقال: استن الفرس، إذا قمص ولعب، وهو أن يرفع يديه ويطرحهما تارة ورجليه أخرى على التعاقب. وقمص البحر بالسفينة: إذا حركها، فرفع مقدمها تارة ومؤخرها أخرى، فالمستن: اسم فاعل منه، واستعير للسحاب: إذ أقبل يتحرك وفيه المطر. والرباب: السحاب الأبيض المتلاصق. وضمير «أقبل» و «ربابه» للمطر. والوابل: إظهار في مقام الإضمار، للدلالة على الكثرة. وفي مصابه: حال له. وأسنمة الآبال: مبتدأ. وفي سحابه: خبر، والجملة خبر الوائل، وأطلق الأسنمة على الماء لأنه سبب سمنها، والمصاب: مصدر على زنة المفعول. الوابل: المطر الشديد الوقع. والأسنمة: جمع سنام. والآبال- بمد الهمزة-: جمع الإبل]] سمى الماء بأسنمة الآبال، لأنه سبب سمن المال وارتفاع أسنمته، ولم يرد لفظ النكاح في كتاب الله إلا في معنى العقد، لأنه في معنى الوطء من باب التصريح به. ومن آداب القرآن: الكناية عنه بلفظ الملامسة والمماسة والقربان والتغشى والإتيان. فإن قلت: لم خصّ المؤمنات والحكم الذي نطقت به الآية تستوي فيه المؤمنات والكتابيات؟ قلت: في اختصاصهنّ تنبيه على أن أصل أمر المؤمن والأولى به: أن يتخير لنطفته، وأن لا ينكح إلا مؤمنة عفيفة، ويتنزه عن مزاوجة الفواسق فما بال الكوافر، ويستنكف أن يدخل تحت لحاف واحد عدوة الله ووليه، فالتي في سورة المائدة: تعليم ما هو جائز غير محرّم، من نكاح المحصنات من الذين أوتوا الكتاب. وهذه فيها تعليم ما هو الأولى بالمؤمنين من نكاح المؤمنات. فإن قلت: ما فائدة ثم في قوله ثُمَّ طَلَّقْتُمُوهُنَّ؟ قلت: فائدته نفى التوهم عمن عسى يتوهم تفاوت الحكم: بين أن يطلقها وهي قريبة العهد من النكاح، وبين أن يبعد عهدها بالنكاح ويتراخى بها المدة في حبالة الزواج ثم يطلقها: فإن قلت: إذا خلا بها خلوة يمكنه معها المساس، هل يقوم ذلك مقام المساس؟ قلت، نعم عند أبى حنيفة وأصحابه حكم الخلوة الصحيحة حكم المساس، وقوله فَما لَكُمْ عَلَيْهِنَّ مِنْ عِدَّةٍ دليل على أن العدة حق واجب على النساء للرجال تَعْتَدُّونَها تستوفون عددها، من قولك: عددت الدراهم فاعتدها، كقولك. كلته فأكتاله، ووزنته فاتزنه. وقرئ: تعتدونها، مخففا، أى: تعتدون فيها «كقوله: ويوم شهدناه [[تقدم شرح هذا الشاهد بالجزء الثاني فراجعه إن شئت اه مصححه.]] والمراد بالاعتداد ما في قوله تعالى وَلا تُمْسِكُوهُنَّ ضِراراً لِتَعْتَدُوا. فإن قلت: ما هذا التمتيع أواجب أم مندوب إليه؟ قلت إن كانت غير مفروض لها كانت المتعة واجبة، ولا تجب المتعة عند أبى حنيفة إلا لها وحدها دون سائر المطلقات، وإن كانت مفروضا لها، فالمتعة مختلف فيها: فبعض على الندب والاستحباب، ومنهم أبو حنيفة. وبعض على الوجوب سَراحاً جَمِيلًا من غير ضرار ولا منع واجب.',     source_page = '408',     updated_at  = datetime('now') WHERE id = 'QR:TE:5026cbd80c8780a33f3960b6';
UPDATE qr_tafsir_entries SET content_ar = 'أمره بأن يقررهم بقوله مَنْ يَرْزُقُكُمْ ثم أمره بأن يتولى الإجابة والإقرار عنهم بقوله: يرزقكم الله. وذلك للإشعار بأنهم مقرّون به بقلوبهم، إلا أنهم ربما أبوا أن يتكلموا به، لأن الذي تمكن في صدورهم من العناد وحب الشرك قد ألجم أفواههم عن النطق بالحق مع علمهم بصحته، ولأنهم إن تفوهوا بأن الله رازقهم: لزمهم أن يقال لهم: فما لكم لا تعبدون من يرزقكم وتؤثرن عليه من لا يقدر على الرزق، ألا ترى إلى قوله قُلْ مَنْ يَرْزُقُكُمْ مِنَ السَّماءِ وَالْأَرْضِ أَمَّنْ يَمْلِكُ السَّمْعَ وَالْأَبْصارَ حتى قال: فَسَيَقُولُونَ اللَّهُ ثم قال فَماذا بَعْدَ الْحَقِّ إِلَّا الضَّلالُ فكأنهم كانوا يقرّون بألسنتهم مرّة، ومرّة كانوا يتلعثمون عنادا وضرارا وحذارا من إلزام الحجة، ونحوه قوله عزّ وجلّ قُلْ مَنْ رَبُّ السَّماواتِ وَالْأَرْضِ قُلِ اللَّهُ قُلْ أَفَاتَّخَذْتُمْ مِنْ دُونِهِ أَوْلِياءَ لا يَمْلِكُونَ لِأَنْفُسِهِمْ نَفْعاً وَلا ضَرًّا وأمره أن يقول لهم بعد الإلزام والإلجام الذي إن لم يزد على إقرارهم بألسنتهم لم يتقاصر عنه وَإِنَّا أَوْ إِيَّاكُمْ لَعَلى هُدىً أَوْ فِي ضَلالٍ مُبِينٍ ومعناه: وإنّ أحد الفريقين من الذين يتوحدون الرازق من السماوات والأرض بالعبادة ومن الذين يشركون به الجماد الذي لا يوصف بالقدرة، لعلى أحد الأمرين من الهدى والضلال، وهذا من الكلام المنصف الذي كل من سمعه من موال أو مناف قال لمن خوطب به: قد أنصفك صاحبك، وفي درجه بعد تقدمة ما قدم من التقرير البليغ: دلالة غير خفية على من هو من الفريقين على الهدى ومن هو في الضلال المبين، ولكن التعريض والتورية أنضل [[قوله «ولكن التعريض والتورية أفضل» في الصحاح «ناضله» : راماه، يقال: ناضلت فلانا فنضلته إذا غلبته اه، فالأنضل الأشد رميا، فلذا عدى بالي. (ع)]] بالمجادل إلى الغرض، وأهجم به على الغلبة، مع قلة شغب الخصم وفلّ شوكته [[قوله «وفل شوكته» أى كسرها. (ع)]] بالهوينا ونحوه قول الرجل لصاحبه: علم الله الصادق منى ومنك، وإن أحدنا لكاذب [[قال محمود: «لما ألزمهم الحجة في قوله قُلِ ادْعُوا الَّذِينَ زَعَمْتُمْ مِنْ دُونِ اللَّهِ لا يَمْلِكُونَ مِثْقالَ ذَرَّةٍ فِي السَّماواتِ وَلا فِي الْأَرْضِ وَما لَهُمْ فِيهِما مِنْ شِرْكٍ وَما لَهُ مِنْهُمْ مِنْ ظَهِيرٍ وهلم جرا إلى الآية المذكورة- وهذا الإلزام إن لم يزد على إقرارهم بألسنتهم لم يتقاصر عنه- أمره أن يقول وَإِنَّا أَوْ إِيَّاكُمْ لَعَلى هُدىً أَوْ فِي ضَلالٍ مُبِينٍ ومعناه: أن أحد الفريقين من الموحدين الرازق من السماوات والأرض بالعبادة، ومن الذين يشركون به الجماد الذي لا يوصف بالقدرة على ذرة: لعلى أحد الأمرين من الهدى أو الضلال، وهذا من الكلام المنصف الذي كل من سمعه من موافق أو مخالف قال للمخاطب به: قد أنصفك صاحبك، والتعريض أنضل بالمجادل إلى الغرض، وأهجم به على الغلبة، مع قلة شغب الخصم وفل شوكته بالهوينا. ونحوه قول الرجل لصاحبه: الله يعلم الصادق منى ومنك، وإن أحدنا لكاذب ومنه قول حسان: أتهجوه ولست له بكفء ... فشركما لخيركما الفداء قال أحمد: وهذا تفسير مهذب وافتنان مستعذب، رددته على سمعي فزاد رونقا بالترديد، واستعاذه الخاطر كأنى بطيء الفهم حين يفيد، ولا ينبغي أن ينكر بعد ذلك على الطريقة التي أكثر تعاطيها متأخر والفقهاء في مجادلاتهم ومحاوراتهم، وذلك قولهم: أحد الأمرين لازم على الإبهام، فهذا المسلك من هذا الوادي غير بعيد، فتأمله والله الموفق.]] . ومنه بيت حسان: أتهجوه ولست له بكفء ... فشر كما لخير كما الفداء [[تقدم شرح هذا الشاهد ضمن أبيات بالجزء الثاني فراجعه إن شئت اه مصححه.]] فإن قلت: كيف خولف بين حرفى الجرّ الداخلين على الحق والضلال؟ قلت: لأن صاحب الحق كأنه مستعل على فرس جواد يركضه حيث شاء، والضال كأنه منغمس في ظلام مرتبك فيه لا يدرى أين يتوجه. وفي قراءة أبىّ: وإنا أو إياكم إما على هدى أو في ضلال مبين.',     source_page = '563',     updated_at  = datetime('now') WHERE id = 'QR:TE:c58df6138b711cd8d783fd85';
UPDATE qr_tafsir_entries SET content_ar = 'القراءة بالميتة على الخفة أشيع، لسلسها على اللسان. وأَحْيَيْناها استئناف بيان لكون الأرض الميتة آية، وكذلك نسلخ: ويجوز أن توصف الأرض والليل بالفعل، لأنه أريد بهما الجنسان مطلقين لا أرض [[قال محمود: «يجوز أن يكون أحييناها صفة للأرض وصح ذلك لأن المراد بالأرض الجنس ولم يقصد بها أرض معينة وأن يكون بيانا لوجه الآية فيها» قال أحمد: وغيره من النحاة يمنع وقوع الجملة صفة للمعرف وإن كان جنسيا وليس الغرض منه معينا ويراعي هذا المانع المطابقة اللفظية في الوصفية ومنه ولقد أمر على اللئيم يسبني.]] وليل بأعيانهما، فعوملا معاملة النكرات في وصفهما بالأفعال، ونحوه: ولقد امر على اللّئيم يسبني [[تقدم شرح هذا الشاهد بالجزء الأول فراجعه إن شئت اه مصححه.]] وقوله فَمِنْهُ يَأْكُلُونَ بتقديم الظرف للدلالة على أن الحب هو الشيء الذي يتعلق به معظم العيش ويقوم بالارتزاق منه صلاح الإنس، وإذا قل جاء القحط ووقع الضرّ، وإذا فقد جاء الهلاك ونزل البلاء. قرئ وَفَجَّرْنا بالتخفيف والتثقيل، والفجر والتفجير، كالفتح والتفتيح لفظا ومعنى. وقرئ ثَمَرِهِ بفتحتين وضمتين وضمة وسكون، والضمير لله تعالى: والمعنى: ليأكلوا مما خلقه الله من الثمر وَمن ما عَمِلَتْهُ أَيْدِيهِمْ من الغرس والسقي والآبار، وغير ذلك من الأعمال إلى أن بلغ الثمر منتهاه وإبان أكله، يعنى أنّ الثمر في نفسه فعل الله وخلقه، وفيه آثار من كد بنى آدم، وأصله من ثمرنا كما قال: وجعلنا، وفجرنا، فنقل الكلام من التكلم إلى الغيبة على طريقة الالتفات. ويجوز أن يرجع إلى النخيل، وتترك الأعناب غير مرجوع إليها، لأنه علم أنها في حكم النخيل فيما علق به من أكل ثمره. ويجوز أن يراد من ثمر المذكور وهو الجنات، كما قال رؤبة: فيها خطوط من بياض وبلق ... كأنّه في الجلد توليع البهق [[تقدم شرح هذا الشاهد بالجزء الأول فراجعه إن شئت اه مصححه.]] فقيل له، فقال: أردت كأن ذاك: ولك أن تجعل «ما» نافية على أنّ الثمر خلق الله ولم تعمله أيدى الناس ولا يقدرون عليه. وقرئ على الوجه الأوّل، وما عملت من غير راجع، وهي في مصاحف أهل الكوفة كذلك، وفي مصاحف أهل الحرمين والبصرة والشام مع الضمير الْأَزْواجَ الأجناس والأصناف وَمِمَّا لا يَعْلَمُونَ ومن أزواج لم يطلعهم الله عليها ولا توصلوا إلى معرفتها بطريق من طرق العلم، ولا يبعد أن يخلق الله تعالى من الخلائق الحيوان والجماد ما لم يجعل للبشر طريقا إلى العلم به، لأنه لا حاجة بهم في دينهم ودنياهم إلى ذلك العلم، ولو كانت بهم اليه حاجة لأعلمهم بما لا يعلمون، كما أعلمهم بوجود ما لا يعلمون. وعن ابن عباس رضى الله عنهما: لم يسمهم. وفي الحديث «ما لا عين رأت [[قوله «في الحديث ما لا عين رأت» أوله: «أعددت لعبادي الصالحين» كما مر في تفسير السجدة. (ع)]] ولا أذن سمعت ولا خطر على قلب بشر، بله ما أطلعتهم عليه» فأعلمنا بوجوده وإعداده ولم يعلمنا به ما هو، ونحوه فَلا تَعْلَمُ نَفْسٌ ما أُخْفِيَ لَهُمْ مِنْ قُرَّةِ أَعْيُنٍ وفي الإعلام بكثرة ما خلق مما علموه ومما جهلوه ما دلّ على عظم قدرته واتساع ملكه.',     source_page = '16',     updated_at  = datetime('now') WHERE id = 'QR:TE:df337053404a72e20be599ab';
UPDATE qr_tafsir_entries SET content_ar = 'مكية، وهي مائة وإحدى وثمانون آية، وقيل: واثنتان وثمانون [نزلت بعد الأنعام] بِسْمِ اللَّهِ الرَّحْمنِ الرَّحِيمِ أقسم الله سبحانه بطوائف الملائكة أو بنفوسهم الصافات أقدامها في الصلاة، من قوله تعالى وَإِنَّا لَنَحْنُ الصَّافُّونَ أو أجنحتها في الهواء واقفة منتظرة لأمر الله فَالزَّاجِراتِ السحاب سوقا فَالتَّالِياتِ لكلام الله من الكتب المنزلة وغيرها. وقيل الصَّافَّاتِ: الطير، من قوله تعالى وَالطَّيْرُ صَافَّاتٍ والزاجرات: كل ما زجر عن معاصى الله. والتاليات: كل من تلا كتاب الله. ويجوز أن يقسم بنفوس العلماء العمال الصافات أقدامها في التهجد وسائر الصلوات وصفوف الجماعات، فالزاجرات بالمواعظ والنصائح، فالتاليات آيات الله والدارسات شرائعه. أو بنفوس قواد الغزاة في سبيل الله التي تصف الصفوف وتزجر الخيل للجهاد، وتتلو الذكر [[قال محمود: «المقسم به طوائف الملائكة أو نفوسهم، والمراد صفهم في الصلاة وزجرهم السحاب أى سوقهم وتلاوتهم ذكر الله أو العلماء والمراد تصافف أقدامهم في الصلاة وزجرهم بالمواعظ عن المعاصي وتلاوتهم الذكر...... إلى أن قال: ... «ويكون التفاصل بين الطوائف إما على أن الأول هو الأفضل أو على العكس» قال أحمد: قد جوز أن يكون ترتيبها في التفاضل على أن الأول وهو الأفضل وعلى العكس، ولم يبين وجه كل واحد منهما من حيث صنعة البديع، ونحن نبينه فنقول: وجه البداءة بالأفضل الاعتناء بالأهم. فقدم، ووجه عكس هذا الترقي من الأدنى إلى الأعلى، ومنه قوله: بها ليل منهم جعفر وابن أمه ... على ومنهم أحمد المنخير ولا يقال: إن هذا إنما ساغ لأن الواو لا تقتضي رتبة، فان هذا غايته أنه عذر، وما ذكرناه بيان لما فيه من مقتضى البديع والبلاغة، وفي هذه الآية دلالة على مذهب سيبويه والخليل في مثل وَاللَّيْلِ إِذا يَغْشى وَالنَّهارِ إِذا تَجَلَّى فإنهما يقولان: الواو الثانية وما بعدها عواطف، وغيرهما يذهب إلى أنها حروف قسم، فوقوع الفاء في هذه الآية موقع الواو والمعنى واحد، إلا أن ما تزيده الفاء من ترتيبها دليل واضح على أن الواو الواقعة في مثل هذا السياق للعطف لا للقسم.]] مع ذلك لا تشغلها عنه تلك الشواغل، كما يحكى عن علىّ بن أبى طالب رضى الله عنه. فإن قلت: ما حكم الفاء إذا جاءت عاطفة في الصفات؟ قلت: إما أن تدل على ترتب معانيها في الوجود، كقوله: يا لهف زيّابة للحرث الصّابح ... فالغانم فالآيب [[تقدم شرح هذا الشاهد بالجزء الأول فراجعه إن شئت اه مصححه.]] كأنه قيل: الذي صبح فغنم فآب. وإما على ترتبها في التفاوت من بعض الوجوه، كقولك: خذ الأفضل فالأكمل، واعمل الأحسن فالأجمل. وإما على ترتب موصوفاتها في ذلك، كقوله: رحم الله المحلقين فالمقصرين، فعلى هذه القوانين الثلاثة ينساق أمر الفاء العاطفة في الصفات. فإن قلت: فعلى أى هذه القوانين هي فيما أنت بصدده؟ قلت: إن وحدت الموصوف كانت للدلالة على ترتب الصفات في التفاضل، وإن ثلثته، فهي للدلالة على ترتب الموصوفات فيه، بيان ذلك: أنك إذا أجريت هذه الأوصاف على الملائكة وجعلتهم جامعين لها، فعطفها بالفاء يفيد ترتبا لها في الفضل: إما إن يكون الفضل للصف ثم للزجر ثم للتلاوة، وإما على العكس، وكذلك إن أردت العلماء وقواد الغزاة. وإن أجريت الصفة الأولى على طوائف والثانية والثالثة على أخر، فقد أفادت ترتب الموصوفات في الفضل، أعنى أن الطوائف الصافات ذوات فضل والزاجرات أفضل، والتاليات أبهر فضلا، أو على العكس، وكذلك إذا أردت بالصافات: الطير، وبالزاجرات: كل ما يزجر عن معصية. وبالتاليات: كل نفس تتلو الذكر، فإن الموصوفات مختلفة. وقرئ بإدغام التاء في الصاد والزاى والذال رَبُّ السَّماواتِ خبر بعد خبر. أو خبر مبتدإ محذوف. والْمَشارِقِ ثلاثمائة وستون مشرقا، وكذلك المغارب: تشرق الشمس كل يوم في مشرق منها وتغرب في مغرب، ولا تطلع ولا تغرب في واحد يومين. فإن قلت: فماذا أراد بقوله رَبُّ الْمَشْرِقَيْنِ وَرَبُّ الْمَغْرِبَيْنِ؟ قلت: أراد مشرقى الصيف والشتاء ومغربيهما.',     source_page = '41',     updated_at  = datetime('now') WHERE id = 'QR:TE:6957a9ce7832fbebd62afe44';
UPDATE qr_tafsir_entries SET content_ar = 'فلما بلغ أن يسعى مع أبيه في أشغاله وحوائجه. فإن قلت: مَعَهُ بم يتعلق؟ قلت: لا يخلو إما أن يتعلق ببلغ، أو بالسعي، أو بمحذوف، فلا يصح تعلفه ببلغ لاقتضائه بلوغهما معا حدّ السعى، ولا بالسعي لأنّ صلة المصدر لا تتقدم عليه، فبقى أن يكون بيانا، كأنه لما قال: فلما بلغ السعى أى الحدّ الذي يقدر فيه على السعى قيل: مع من؟ فقال مع أبيه. والمعنى في اختصاص الأب أنه أرفق الناس به، وأعطفهم عليه، وغيره ربما عنف به في الاستسعاء فلا يحتمله، لأنه لم تستحكم قوته ولم يصلب عوده، وكان إذ ذاك ابن ثلاث عشرة سنة. والمراد: أنه على غضاضة سنه وتقلبه في حد الطفولة، كان فيه من رصانة الحلم وفسحة الصدر ما جسره على احتمال تلك البلية العظيمة والإجابة بذلك الجواب الحكيم: أتى في المنام فقيل له: اذبح ابنك، ورؤيا الأنبياء وحى كالوحى في اليقظة، فلهذا قال إِنِّي أَرى فِي الْمَنامِ أَنِّي أَذْبَحُكَ فذكر تأويل الرؤيا، كما يقول الممتحن وقد رأى أنه راكب في سفينة: رأيت في المنام أنى ناج من هذه المحنة، وقيل: رأى ليلة التروية كأن قائلا يقول له: إنّ الله يأمرك بذبح ابنك هذا، فلما أصبح روّى في ذلك من الصباح إلى الرواح، أمن الله هذا الحلم أو من الشيطان؟ فمن ثم سمى يوم التروية، فلما أمسى رأى مثل ذلك، فعرف أنه من الله، فمن ثم سمى يوم عرفة، ثم رأى مثله في الليلة الثالثة، فهم بنحره فسمى اليوم يوم النحر. وقيل: إنّ الملائكة حين بشرته بغلام حليم قال: هو إذن ذبيح الله. فلما ولد وبلغ حد السعى معه قيل له: أوف بنذرك فَانْظُرْ ماذا تَرى من الرأى على وجه المشاورة. وقرئ: ماذا ترى [[قوله «وقرئ ماذا ترى» لعله بضم التاء وكسر الراء، من أراه يريه، فليحرر. (ع)]] ، أى: ماذا تبصر من رأيك وتبديه. وماذا ترى، على البناء للمفعول، أى: ماذا تريك نفسك من الرأى افْعَلْ ما تُؤْمَرُ أى ما تؤمر به، فحذف الجار كما حذف من قوله: أمرتك الخير فافعل ما أمرت به [[تقدم شرح هذا الشاهد بالجزء الثاني فراجعه إن شئت اه مصححه.]] أو أمرك على إضافة المصدر إلى المفعول، وتسمية المأمور به أمرا. وقرئ: ما تؤمر به. فإن قلت: لم شاوره في أمر هو حتم من الله؟ قلت: لم يشاوره ليرجع إلى رأيه ومشورته، ولكن ليعلم ما عنده فيما نزل به من بلاء الله، فيثبت قدمه ويصبره إن جزع، ويأمن عليه الزلل إن صبر وسلم، وليعلمه حتى يراجع نفسه فيوطنها ويهون عليها، ويلقى البلاء وهو كالمستأنس به، ويكتسب المثوبة بالانقياد لأمر الله قبل نزوله: ولأنّ المغافصة [[قوله «المغافصة» في الصحاح: غافصت الرجل، أى: أخذته على غرة. (ع)]] بالذبح مما يستسمج، وليكون سنة في المشاورة، فقد قيل: لو شاور آدم الملائكة في أكله من الشجرة لما فرط منه ذلك. فإن قلت: لم كان ذلك بالمنام دون اليقظة؟ قلت: كما أرى يوسف عليه السلام سجود أبويه وإخوته له في المنام من غير وحى إلى أبيه، وكما وعد رسول الله ﷺ دخول المسجد الحرام في المنام، وما سوى ذلك من منامات الأنبياء، وذلك لتقوية الدلالة على كونهم صادقين مصدوقين، لأنّ الحال إما حال يقظة أو حال منام، فإذا تظاهرت الحالتان على الصدق كان ذلك أقوى للدلالة من انفراد أحدهما.',     source_page = '590',     updated_at  = datetime('now') WHERE id = 'QR:TE:ebae07a81eaae4db7d3efc3d';
UPDATE qr_tafsir_entries SET content_ar = 'وَما مِنَّا أحد إِلَّا لَهُ مَقامٌ مَعْلُومٌ فحذف الموصوف وأقيمت الصفة مقامه، كقوله: أنا ابن جلا وطلّاع الثّنايا [[تقدم شرح هذا الشاهد بالجزء الثاني فراجعه إن شئت اه مصححه.]] بكفّى كان من أرمى البشر [[تقدم شرح هذا الشاهد بالجزء الثاني فراجعه إن شئت اه مصححه.]] مقام معلوم في العبادة، والانتهاء إلى أمر الله مقصور عليه لا يتجاوزه، كما روى: فمنهم راكع لا يقيم صلبه، وساجد لا يرفع رأسه لَنَحْنُ الصَّافُّونَ نصف أقدامنا في الصلاة، أو أجنحتنا في الهواء. منتظرين ما نؤمر. وقيل: نصف أجنحتنا حول العرش داعين للمؤمنين. وقيل: إنّ المسلمين إنما اصطفوا في الصلاة منذ نزلت هذه الآية. وليس يصطف أحد من أهل الملل في صلاتهم غير المسلمين الْمُسَبِّحُونَ المنزهون أو المصلون. والوجه أن يكون هذا وما قبله من قوله سُبْحانَ اللَّهِ عَمَّا يَصِفُونَ من كلام الملائكة حتى يتصل بذكرهم في قوله وَلَقَدْ عَلِمَتِ الْجِنَّةُ كأنه قيل: ولقد علم الملائكة وشهدوا أن المشركين مفترون عليهم في مناسبة رب العزة وقالوا: سبحان الله، فنزهوه عن ذلك، واستثنوا عباد الله المخلصين وبرؤهم منه، وقالوا للكفرة فإذا صحّ ذلك فإنكم وآلهتكم لا تقدرون أن تفتنوا على الله أحدا من خلقه وتضلوه، إلا من كان مثلكم ممن علم الله- لكفرهم، لا لتقديره وإرادته [[قوله «لا لتقديره وإرادته تعالى» مبنى على مذهب المعتزلة أن الله لا يقدر الشر ولا يريده. وقال أهل السنة: إن كل كائن فهو بقضاء الله وقدره كما بين في علم التوحيد. (ع)]] ، تعالى الله عما يقول الظالمون علوا كبيرا- أنهم من أهل النار، وكيف نكون مناسبين لرب العزة ويجمعنا وإياه جنسية واحدة؟ وما نحن إلا عبيد أذلاء بين يديه، لكل منا مقام من الطاعة لا يستطيع أن يزل عنه ظفرا، خشوعا لعظمته وتواضعا لجلاله، ونحن الصافون أقدامنا لعبادته وأجنحتنا، مذعنين خاضعين مسبحين ممجدين، وكما يجب على العباد [[قوله «وكما يجب على العباد لربهم» لعله كما يجب. كعبارة النسفي. (ع)]] لربهم. وقيل: هو من قول رسول الله ﷺ، يعنى: وما من المسلمين أحد إلا له مقام معلوم يوم القيامة على قدر عمله، من قوله تعالى عَسى أَنْ يَبْعَثَكَ رَبُّكَ مَقاماً مَحْمُوداً ثم ذكر أعمالهم وأنهم هم الذين يصطفون في الصلاة يسبحون الله وينزهونه مما يضيف إليه من لا يعرفه مما لا يجوز عليه.',     source_page = '305',     updated_at  = datetime('now') WHERE id = 'QR:TE:423cb804083cf3c069f93863';
UPDATE qr_tafsir_entries SET content_ar = 'لِشاعِرٍ مَجْنُونٍ يعنون محمدا ﷺ بَلْ جاءَ بِالْحَقِّ رد على المشركين وَصَدَّقَ الْمُرْسَلِينَ كقوله مُصَدِّقاً لِما بَيْنَ يَدَيْهِ وقرئ: لذائقو العذاب، بالنصب على تقدير النون، كقوله: ولا ذاكر الله إلّا قليلا [[تقدم شرح هذا الشاهد بالجزء الأول فراجعه إن شئت اه مصححه.]] بتقدير التنوين. وقرئ على الأصل: لذائقون العذاب إِلَّا ما كُنْتُمْ تَعْمَلُونَ إلا مثل ما عملتم جزاء سيئا بعمل سيئ.',     source_page = '448',     updated_at  = datetime('now') WHERE id = 'QR:TE:7e30c74dfa592f661229633d';
UPDATE qr_tafsir_entries SET content_ar = 'الضمير في لا يَسَّمَّعُونَ لكل شيطان، لأنه في معنى الشياطين. وقرئ بالتخفيف والتشديد، وأصله: يتسمعون. والتسمع: تطلب السماع. يقال: تسمع فسمع، أو فلم يسمع. وعن ابن عباس رضى الله عنهما: هم يتسمعون ولا يسمعون، وبهذا ينصر التخفيف على التشديد، فإن قلت: لا يسمعون كيف اتصل بما قبله؟ قلت: لا يخلو من أن يتصل بما قبله على أن يكون صفة لكل شيطان، أو استئنافا فلا تصحّ الصفة لأنّ الحفظ من شياطين لا يسمعون ولا يستمعون لا معنى له، وكذلك الاستئناف لأنّ سائلا لو سأل: لم تحفظ من الشياطين؟ فأجيب بأنهم لا يسمعون: لم يستقم، فبقى أن يكون كلاما منقطعا مبتدأ اقتصاصا، لما عليه حال المسترقة للسمع [[أبطل الزمخشري أن يكون لا يَسَّمَّعُونَ صفة لأن الحفظ من شيطان لا يسمع لا معنى له وأبطل أن يكون أصله لئلا يسمعوا، فحذف اللام وحذفها كثير، ثم حذف أن وأهدر عملها مثل: ألا أيها ذا الزاجري أحضر الوغي ... وأن أشهد اللذات هل أنت مخلدى واستبعد اجتماع هذين الحذفين، وإن كان كل واحد منهما بانفراده سائغا، ولما أبطل هذين الوجهين تعين عنده أن يكون ابتداء كلام اقتصاصا لما عليه أحوال المسترقة للسمع» قال أحمد: كلا الوجهين مستقيم، والجواب عن إشكاله الوارد على الوجه الأول: أن عدم سماع الشيطان سببه الحفظ منه، فحال الشيطان حال كونه محفوظا منه هي حاله حال كونه لا يسمع، وإحدى الحالين لازمة للأخرى، فلا مانع أن يجتمع الحفظ منه، وكونه موصوفا بعدم السماع في حالة واحدة لا على أن عدم السماع ثابت قبل الحفظ بل معه وقسيمه، ونظير هذه الآية على هذا التقدير قوله تعالى وَسَخَّرَ لَكُمُ اللَّيْلَ وَالنَّهارَ وَالشَّمْسَ وَالْقَمَرَ وَالنُّجُومُ مُسَخَّراتٌ بِأَمْرِهِ فقوله تعالى مُسَخَّراتٌ حال مما تقدمه العامل فيه الفعل الذي هو سخر. ومعناه مستقيم، لأن تسخيرها يستلزم كونها مسخرة، فالحال التي سخرت فيها هي الحال التي كانت فيها مسخرة، لا على معنى تسخيرها مع كونها مسخرة قبل ذلك، وما أشار له الزمخشري في هذه الآية قريب من هذا التفسير، إلا أنه ذكر معه تأويلا آخر كالمستشكل لهذا الوجه، فجعل مسخرات جمع مسخر مصدر كممزق، وجعل المعنى: وسخر لكم الليل والنهار والشمس والقمر أنواعا من التسخير، وفيما ذكرناه كفاية، ومن هذا النمط ثُمَّ أَرْسَلْنا رُسُلَنا وهم ما كانوا رسلا إلا بالإرسال، وهؤلاء ما كانوا لا يسمعون إلا بالحفظ. وأما الجواب عن إشكاله الثاني فورود حذفين في مثل قوله تعالى يُبَيِّنُ اللَّهُ لَكُمْ أَنْ تَضِلُّوا وأصله لئلا تضلوا، فحذف اللام و «لا» جميعا من محليهما.]] ، وأنهم لا يقدرون أن يسمعوا إلى كلام الملائكة. أو يتسمعوا وهم مقذوفون بالشهب مدحورون عن ذلك، إلا من أمهل حتى خطف خطفة واسترق استراقة، فعندها تعاجله الهلكة بإتباع الشهاب الثاقب. فإن قلت: هل يصح قول من زعم أن أصله: لئلا يسمعوا فحذفت اللام كما حذفت في قولك: جئتك أن تكرمني، فبقى أن لا يسمعوا فحذفت أن وأهدر عملها، كما في قول القائل: ألا أيها ذا الزّاجرى أحضر الوغى [[تقدم شرح هذا الشاهد بالجزء الأول فراجعه إن شئت اه مصححه.]] قلت: كل واحد من هذين الحذفين غير مردود على انفراده، فأما اجتماعهما فمنكر من المنكرات، على أن صون القرآن عن مثل هذا التعسف واجب. فإن قلت: أى فرق بين سمعت فلانا يتحدّث، وسمعت إليه يتحدّث، وسمعت حديثه، وإلى حديثه؟ قلت: المعدّى بنفسه يفيد الإدراك، والمعدى بإلى يفيد الإصغاء مع الإدراك، والملأ الأعلى: الملائكة، لأنهم يسكنون السماوات. والإنس والجن: هم الملأ الأسفل، لأنهم سكان الأرض. وعن ابن عباس رضى الله عنهما: هم الكتبة من الملائكة. وعنه: أشراف الملائكة مِنْ كُلِّ جانِبٍ من جميع جوانب السماء من أى جهة صعدوا للاستراق دُحُوراً مفعول له، أى: ويقذفون للدحور وهو الطرد، أو مدحورين على الحال. أو لأنّ القذف والطرد متقاربان في المعنى، فكأنه قيل: يدحرون أو قذفا. وقرأ أبو عبد الرحمن السلمى بفتح الدال على: قذفا دحورا طرودا. أو على أنه قد جاء مجيء القبول والولوع. والواصب: الدائم، وصب الأمر وصوبا، يعنى أنهم في الدنيا مرجومون بالشهب، وقد أعدّ لهم في الآخرة نوع من العذاب دائم غير منقطع مَنْ في محل الرفع بدل من الواو في لا يسمعون، أى: لا يسمع الشياطين إلا الشيطان الذي خَطِفَ الْخَطْفَةَ وقرئ: خطف بكسر الخاء والطاء وتشديدها، وخطف بفتح الخاء وكسر الطاء وتشديدها، وأصلهما: اختطف. وقرئ: فأتبعه، وفاتبعه.',     source_page = '159',     updated_at  = datetime('now') WHERE id = 'QR:TE:867c384c3b03fde79143cd2d';
UPDATE qr_tafsir_entries SET content_ar = 'فإن قلت: كيف تطابق قوله اصْبِرْ عَلى ما يَقُولُونَ وقوله وَاذْكُرْ عَبْدَنا داوُدَ حتى عطف أحدهما على صاحبه؟ قلت: كأنه قال لنبيه عليه الصلاة والسلام: اصبر على ما يقولون، وعظم أمر معصية الله في أعينهم بذكر قصة داود، وهو أنه نبىّ من أنبياء الله تعالى قد أولاه ما أولاه من النبوّة والملك، لكرامته عليه وزلفته لديه، ثم زل زلة فبعث إليه الملائكة ووبخه عليها. على طريق التمثيل والتعريض، حتى فطن لما وقع فيه فاستغفر وأناب، ووجد منه ما يحكى من بكائه الدائم وغمه الواصب [[قوله «وغمه الواصب» أى: الدائم. (ع)]] ، ونقش جنايته في بطن كفه حتى لا يزال يجدد النظر إليها والندم عليها فما الظنّ بكم مع كفركم ومعاصيكم؟ أو قال له ﷺ: اصبر على ما يقولون وصن نفسك وحافظ عليها أن تزل فيما كلفت من مصابرتهم وتحمل أذاهم، واذكر أخاك داود وكرامته على الله كيف زلّ تلك الزلة اليسيرة فلقى من توبيخ الله وتظليمه ونسبته إلى البغي ما لقى ذَا الْأَيْدِ ذا القوّة في الدين المضطلع بمشاقه وتكاليفه، كان على نهوضه بأعباء النبوّة والملك يصوم يوما ويفطر يوما وهو أشدّ الصوم، ويقوم نصف الليل. يقال: فلان أيد، وذو أيد، وذو آد. وأياد كل شيء: ما يتقوّى به أَوَّابٌ توّاب رجاع إلى مرضاة الله فإن قلت: ما ذلك على أنّ الأيد القوّة في الدين؟ قلت: قوله تعالى إِنَّهُ أَوَّابٌ لأنه تعليل لذي الأيد وَالْإِشْراقِ وقت الإشراق، وهو حين تشرق الشمس، أى: تضيء ويصفو شعاعها وهو وقت الضحى. وأما شروقها فطلوعها، يقال: شرقت الشمس، ولما تشرق [[قال محمود: «الاشراق حين تشرق الشمس، أى يصفو نورها وهو وقت الضحى. وأما شروقها فطلوعها. يقال: شرقت الشمس ولما تشرق. ومنه أخذ ابن عباس صلاة الضحى. قال: ويحتمل أن يكون من أشرق القوم إذا دخلوا في وقت الشروق، ويكون المراد وقت صلاة الفجر لانتهائه بشروق الشمس» قال أحمد: الوجه الثاني يفرق بين العشى والاشراق، فان العشى ظرف بلا إشكال، فلو حمل الاشراق على الدخول في وقت الشروق لكان مصدرا، مع أن المراد به الظرف، لأنه فعل الشمس وصفتها التي تستعمل ظرفا كالطلوع والغروب وشبههما.]] . وعن أمّ هانئ: دخل علينا رسول الله ﷺ فدعا بوضوء فتوضأ ثم صلى صلاة الضحى وقال: يا أمّ هانئ هذه صلاة الإشراق [[أخرجه ابن مردويه والثعلبي والواحدي والبغوي والطبراني كلهم من رواية أبى بكر الهذلي عن عطاء عن ابن عباس: حدثتني أم هانئ. ورواه الحاكم من وجه آخر عن عبد الله بن الحرث عن ابن عباس «كان لا يصلى الضحى حتى أدخلناه على أم هانئ فقلت لها: أخبرى ابن عباس قالت: دخل رسول الله ﷺ في بيتي فصلى صلاة الضحى ثمان ركعات. قال: فخرج ابن عباس وهو يقول: هذه صلاة الاشراق» هذا موقوف وهو أصح.]] . وعن طاوس عن ابن عباس قال: هل تجدون ذكر صلاة الضحى في القرآن؟ قالوا لا، فقرأ: إنا سخرنا الجبال معه يسبحن بالعشي والإشراق وقال: كانت صلاة يصليها داود عليه السلام. وعنه: ما عرفت صلاة الضحى إلا بهذه الآية. وعنه: لم يزل في نفسي من صلاة الضحى شيء حتى طلبتها فوجدتها بهذه الآية يُسَبِّحْنَ بِالْعَشِيِّ وَالْإِشْراقِ وكان لا يصلى صلاة الضحى، ثم صلاها بعد. وعن كعب أنه قال لابن عباس: إنى لا أجد في كتب الله صلاة بعد طلوع الشمس، فقال: أنا أوجدك ذلك في كتاب الله تعالى، يعنى هذه الآية. ويحتمل أن يكون من أشرق القوم إذا دخلوا في الشروق، ومنه قوله تعالى فَأَخَذَتْهُمُ الصَّيْحَةُ مُشْرِقِينَ وقول أهل الجاهلية: أشرق [[قوله «أشرق ثبير» كانوا يقولون: أشرق ثبير كيما نغير، كما في الصحاح. (ع)]] ثبير، ويراد وقت صلاة الفجر لانتهائه بالشروق. ويسبحن: في معنى ومسبحات على الحال. فإن قلت: هل من فرق بين يسبحن ومسبحات [[قال محمود: «إن قلت لم اختار يسبحن على مسبحات وأيهما وقع كان حالا، وأجاب بأن اختيارهما لمعنى وهو الدلالة على حدوث التسبيح شيئا بعد شيء كأن السامع محاضر لها فيسمعها تسبح. ومنه قول الأعشى: إلى ضوء نار في يفاع تحرق ولو قال: محرقة لم يكن شيئا. قال أحمد: ولهذه النكتة فرق سحنون من أصحابنا بين: أنا محرم يوم أفعل كذا «بصيغة اسم الفاعل. وبين أحرم بصيغة المضارع. فرأى أن المعلق بصيغة اسم الفاعل يكون محرما بوجود صيغة التعليق، ولا كذلك المعلق بصيغة الفعل المضارع، فانه لا يكون محرما حتى يحرم ويقال له أحرم، فكأنه رأى أن صيغة الفعل خصوصية في الدلالة على حدوثه، ولا كذلك اسم الفاعل وإن كان متأخرا. وأصحابنا اختلفوا في معنى قول سحنون في اسم الفاعل يكون محرما يوم يفعل، فمنهم من قال: أراد الفور فينشئ إحراما، ومنهم من قال: يكون محرما في الحال بالتعليق الأول ولا يجدد شيئا. ومذهب مالك: التسوية بين صيغتي اسم الفاعل والفعل في هذا المقام والله أعلم. وحقق الزمخشري هذا الفرق بين اسم الفاعل والفعل في قوله وَالطَّيْرَ مَحْشُورَةً كُلٌّ لَهُ أَوَّابٌ فقال: لما كان الواقع حشر الطير دفعة واحدة، وكان ذلك أدل على القدرة، لم يكن لاستعمال الفعل الدال على الحدوث شيئا فشيئا معنى، فاستعمل فيه اسم المفعول على خلاف استعمال الفعل في الأول.]] ؟ قلت: نعم، وما اختير يسبحن على مسبحات إلا لذلك، وهو الدلالة على حدوث التسبيح من الجبال شيئا بعد شيء وحالا بعد حال، وكأن السامع محاضر تلك الحال يسمعها تسبح. ومثله قول الأعشى: إلى ضوء نار في يفاع تحرق [[تقدم شرح هذا الشاهد ضمن أبيات بالجزء الثالث فراجعه إن شئت اه مصححه.]] ولو قال: محرقة، لم يكن شيئا. وقوله مَحْشُورَةً في مقابلة: يسبحن: إلا أنه لما لم يكن في الحشر ما كان في التسبيح من إرادة الدلالة على الحدوث شيئا بعد شيء، جيء به اسما لا فعلا. وذلك أنه لو قيل: وسخرنا الطير يحشرن- على أنّ الحشر يوجد من حاشرها شيئا بعد شيء. والحاشر هو الله عز وجل- لكان خلفا، لأنّ حشرها جملة واحدة أدلّ على القدرة. وعن ابن عباس رضى الله عنهما كان إذا سبح جاوبته الجبال بالتسبيح، واجتمعت إليه الطير فسبحت، فذلك حشرها. وقرئ: والطير محشورة. بالرفع كُلٌّ لَهُ أَوَّابٌ كل واحد من الجبال والطير لأجل داود، أى: لأجل تسبيحه مسبح، لأنها كانت تسبح بتسبيحه. ووضع الأوّاب موضع المسبح: إمّا لأنها كانت ترجع التسبيح، والمرجع رجاع، لأنه يرجع إلى فعله رجوعا بعد رجوع وإمّا لأن الأواب- وهو التوّاب الكثير الرجوع إلى الله وطلب مرضاته- من عادته أن يكثر ذكر الله ويديم تسبيحه وتقديسه. وقيل: الضمير لله، أى: كل من داود والجبال والطير لله أؤاب، أى مسبح مرجع للتسبيح وَشَدَدْنا مُلْكَهُ قوّيناه، قال تعالى سَنَشُدُّ عَضُدَكَ وقرئ شددنا على المبالغة. قيل: كان يبيت حول محرابه أربعون ألف مستلئم [[قوله «مستلئم» أى: لا بس اللأمة، وهي الدرع. أفاده الصحاح. (ع)]] يحرسونه وقيل: الذي شدّ الله به ملكه وقذف في قلوب قومه الهيبة: أنّ رجلا ادّعى عنده على آخر بقرة، وعجز عن إقامة البينة، فأوحى الله تعالى إليه في المنام: أن اقتل المدّعى عليه، فقال: هذا منام، فأعيد الوحى في اليقظة، فأعلم الرجل فقال: إنّ الله عزّ وجلّ لم يأخذنى بهذا الذنب، ولكن بأنى قتلت أبا هذا غيلة، فقتله، فقال الناس: إن أذنب أحد ذنبا أظهره الله عليه، فقتله، فهابوه الْحِكْمَةَ الزبور وعلم الشرائع. وقيل: كل كلام وافق الحق فهو حكمة. الفصل: التمييز بين الشيئين. وقيل للكلام البين: فصل، بمعنى المفصول كضرب الأمير، لأنهم قالوا: كلام ملتبس، وفي كلامه لبس. والملتبس: المختلط، فقيل في نقيضه: فصل، أى مفصول بعضه من بعض، فمعنى فصل الخطاب: البين من الكلام الملخص الذي يتبينه من يخاطب به لا يلتبس عليه، ومن فصل الخطاب وملخصه: أن لا يخطئ صاحبه مظانّ الفصل والوصل، فلا يقف في كلمة الشهادة على المستثنى منه، ولا يتلو قوله فَوَيْلٌ لِلْمُصَلِّينَ إلا موصولا بما بعده، ولا وَاللَّهُ يَعْلَمُ وَأَنْتُمْ حتى يصله بقوله لا تَعْلَمُونَ ونحو ذلك، وكذلك مظانّ العطف وتركه، والإضمار والإظهار والحذف والتكرار، وإن شئت كان الفصل بمعنى الفاصل، كالصوم والزور، وأردت بفصل الخطاب: الفاصل من الخطاب الذي يفصل بين الصحيح والفاسد، والحق والباطل، والصواب والخطأ، وهو كلامه في القضايا والحكومات وتدابير الملك والمشورات. وعن علىّ بن أبى طالب رضى الله عنه. هو قوله: البينة على المدّعى واليمين على المدّعى عليه، وهو من الفصل بين الحق والباطل، ويدخل فيه قول بعضهم: هو قوله «أمّا بعد» لأنه يفتتح إذا تكلم في الأمر الذي له شأن بذكر الله وتحميده، فإذا أراد أن يخرج إلى الغرض المسوق إليه: فصل بينه وبين ذكر الله بقوله: أمّا بعد. ويجوز أن يراد الخطاب القصد الذي ليس فيه اختصار مخلّ ولا إشباع مملّ. ومنه ما جاء في صفة كلام رسول الله ﷺ: فصل لا نذر ولا هذر [[هو حديث أم معيد. وقد تقدم في سورة الأعراف، وفي الأدب لأبى داود من حديث عائشة «كان كلام رسول الله ﷺ فصلا يفهمه من سمعه» .]] .',     source_page = '63',     updated_at  = datetime('now') WHERE id = 'QR:TE:4641c745507f2834840c3cb2';
UPDATE qr_tafsir_entries SET content_ar = 'لَقَدْ ظَلَمَكَ جواب قسم محذوف. وفي ذلك استنكار لفعل خليطه وتهجين لطمعه. والسؤال: مصدر مضاف إلى المفعول، كقوله تعالى مِنْ دُعاءِ الْخَيْرِ وقد ضمن معنى الإضافة فعدّى تعديتها، كأنه قيل بإضافة نَعْجَتِكَ إِلى نِعاجِهِ على وجه السؤال والطلب. فإن قلت: كيف سارع إلى تصديق أحد الخصمين حتى ظلم الآخر قبل استماع كلامه [[قال محمود: «فان قلت كيف سارع بتصديق أحد الخصمين قبل سماع كلام الآخر، وأجاب بأن ذلك كان بعد اعتراف خصمه ولكنه لم يحك في القرآن لأنه معلوم» قال أحمد: ويحتمل أن يكون ذلك من داود على سبيل الفرض والتقدير، أى: إن صح ذلك فقد ظلمك.]] ؟ قلت: ما قال ذلك إلا بعد اعتراف صاحبه، ولكنه لم يحك في القرآن لأنه معلوم. ويروى أنه قال: أنا أريد أن آخذها منه وأكمل نعاجى مائة، فقال داود: إن رمت ذلك ضربنا منك هذا وهذا، وأشار إلى طرف الأنف والجبهة، فقال: يا داود أنت أحق أن يضرب منك هذا وهذا، وأنت فعلت كيت وكيت، ثم نظر داود فلم ير أحدا، فعرف ما وقع فيه والْخُلَطاءِ الشركاء الذين خلطوا أموالهم، الواحد: خليط، وهي الخلطة، وقد غلبت في الماشية، والشافعي رحمه الله يعتبرها، فإذا كان الرجلان خليطين في ماشية بينهما غير مقسومة، أو لكل واحد منهما ماشية على حدة إلا أنّ مراحهما ومساقهما وموضع حلبهما والراعي والكلب واحد والفحولة مختلطة: فهما يزكيان زكاة الواحد فإن كان لهما أربعون شاة فعليهما شاة. وإن كانوا ثلاثة ولهم مائة وعشرون لكل واحد وأربعون، فعليهم واحدة كما لو كانت لواحد. وعند أبى حنيفة: لا تعتبر الخلطة، والخليط والمنفرد عنده واحد، ففي أربعين بين خليطين: لا شيء عنده، وفي مائة وعشرين بين ثلاثة: ثلاث شياه. فإن قلت: فهذه الخلطة ما تقول فيها؟ قلت: عليهما شاة واحدة، فيجب على ذى النعجة أداء جزء من مائة جزء من الشاة عند الشافعي رحمه الله، وعند أبى حنيفة لا شيء عليه، فإن قلت: ماذا أراد بذكر حال الخلطاء في ذلك المقام؟ قلت: قصد به الموعظة الحسنة والترغيب في إيثار عادة الخلطاء الصلحاء الذين حكم لهم بالقلة، وأن يكرّه إليهم الظلم والاعتداء الذي عليه أكثرهم، مع التأسف على حالهم، وأن يسلى المظلوم عما جرى عليه من خليطه، وأنّ له في أكثر الخلطاء أسوة. وقرئ: ليبغى بفتح الياء على تقدير النون الخفيفة، وحذفها كقوله: اضرب عنك الهموم طارقها [[اضرب عنك الهموم طارقها ... ضربك بالسوط قونس الفرس لطرفة بن العبد، وقال أبو حاتم وابن برى: هو مصنوع عليه. واضرب فعل أمر بنى على الفتح لاتصاله بنون التوكيد الخفيفة تقديرا، وحذفها لغير وقف ولالتقاء الساكنين قليل. وقيل ضرورة كما هنا. والمعنى: ادفع عنك الهموم، فهو استعارة مضرحة. وضربك بالسوط، أى: كضربك به ترشيح، وطارقها: بدل من الهموم، أى الفاشي لك منها، والسوط: معمول من جلد تساق به الفرس. ويروى: بالسيف، لكنه غير ملائم للفرس، بل للفارس. وقونسها: أعلى رأسها. وقيل: شعر عنقها. ويجوز تشبيه الهموم بحيوان يصح ضربه على طريق المكنية، والضرب تخييل، والطروق ترشيح.]] وهو جواب قسم محذوف. وليبغ: بحذف الياء، اكتفاء منها بالكسرة، وما في وَقَلِيلٌ ما هُمْ للإبهام. وفيه تعجب من قلتهم. وإن أردت أن تتحقق فائدتها وموقعها فاطرحها، من قول امرئ القيس: وحديث ما على قصره [[تقدم شرح هذا الشاهد بهذا الجزء فراجعه إن شئت اه مصححه.]] وانظر هل بقي له معنى قط. لما كان الظنّ الغالب يدانى العلم، استعير له. ومعناه: وعلم داود وأيقن أَنَّما فَتَنَّاهُ أنا ابتليناه لا محالة بامرأة أوريا، هل يثبت أو يزل؟ وقرئ: فتناه، بالتشديد للمبالغة. وأفتناه، من قوله: لئن فتنتني لهى بالأمس أفتنت [[لئن فتنتني لهى بالأمس أفتنت ... سعيدا فأمسى قد قلى كل مسلم وألقى مصابيح القراءة واشترى ... وصال الغواني بالكتاب المنمنم للأعشى الهمداني. وفتنته المرأة- بالتخفيف والتشديد- وأفتنته: دلهته وحيرته. و «لهى بالأمس أفتنت» جواب القسم المدلول عليه باللام في قوله: لئن فتنتني. وجواب الشرط محذوف دل عليه جواب القسم. والمعنى: إن فتنتني فلا أحزن ولا أتعجب، فان تلك عادتها من قبل، فالمراد بالأمس: الزمن الماضي. وسعيد: هو ابن جبير، كان عالما تقيا. وقلى كل مسلم، أى: بغض كل مسلم سواها. وعبر بالمسلم، لأنه يبعد بغضه. والمصابيح: يجوز أنها حقيقة، وأنها مجاز عن الكتب. والغواني: الجميلات. والمنمنم: المحسن بنقوش الكتابة.]] وفتناه وفتناه، على أن الألف ضمير الملكين. وعبر بالراكع عن الساجد، لأنه ينحنى ويخضع كالساجد. وبه استشهد أبو حنيفة وأصحابه في سجدة التلاوة، على أنّ الركوع يقوم مقام السجود. وعن الحسن: لأنه لا يكون ساجدا حتى يركع، ويجوز أن يكون قد استغفر الله لذنبه وأحرم بركعتي الاستغفار والإنابة، فيكون المعنى: وخرّ للسجود راكعا أى مصليا، لأنّ الركوع يجعل عبارة عن الصلاة وَأَنابَ ورجع إلى الله تعالى بالتوبة والتنصل. وروى أنه بقي ساجدا أربعين يوما وليلة لا يرفع رأسه إلا لصلاة مكتوبة أو ما لا بدّ منه ولا يرقأ دمعه حتى نبت العشب من دمعه إلى رأسه، ولم يشرب ماء إلا وثلثاه دمع، وجهد نفسه راغبا إلى الله تعالى في العفو عنه حتى كاد يهلك، واشتغل بذلك عن الملك حتى وثب ابن له يقال له إيشا على ملكه ودعا إلى نفسه، واجتمع إليه أهل الزيغ من بنى إسرائيل، فلما غفر له حاربه فهزمه. وروى أنه نقش خطيئته في كفه حتى لا ينساها. وقيل: إنّ الخصمين كانا من الإنس، وكانت الخصومة على الحقيقة بينهما: إما كانا خليطين في الغنم، وإما كان أحدهما موسرا وله نسوان كثيرة من المهائر والسراري، والثاني معسرا ماله إلا امرأة واحدة، فاستنزله عنها وإنما فزع لدخولهما عليه في غير وقت الحكومة أن يكونا مغتالين، وما كان ذنب داود إلا أنه صدّق أحدهما على الآخر وظلمه قبل مسألته [[قال محمود: «ونقل بعضهم أن هذه القصة لم تكن من الملائكة وليست تمثيلا وإنما كانت من البشر إما خليطين في الغنم حقيقة، وإما كان أحدهما موسرا وله نسوان كثيرة من المهاتر والسراري والثاني معسرا وماله إلا امرأة واحدة، فاستنزله عنها، وفزع داود، وخوفه أن يكونا مغتالين لأنهما دخلا عليه في غير وقت القضاء، وما كان ذنب داود إلا أنه صدق أحدهما على الآخر ونسبه إلى الظلم قبل مسألته» قال أحمد: مقصود هذا القائل تنزيه داود عن ذنب يبعثه عليه شهوة النساء، فأخذ الآية على ظاهرها وصرف الذنب إلى العجلة في نسبة الظلم إلى المدعى عليه، لأن الباعث على ذلك في الغالب إنما هو التهاب الغضب وكراهيته أخف مما يكون الباعث عليه الشهوة والهوى، ولعل هذا القائل يؤكد رأيه في الآية بقوله تعالى عقبها وصية لداود عليه السلام: يا داوُدُ إِنَّا جَعَلْناكَ خَلِيفَةً فِي الْأَرْضِ فَاحْكُمْ بَيْنَ النَّاسِ بِالْحَقِّ وَلا تَتَّبِعِ الْهَوى فما جرت العناية بتوصيته فيما يتعلق بالأحكام إلا والذي صدر منه أولا وبان منه من قبيل ما وقع له في الحكم بين الناس، وقد التزم المحققون من أئمتنا أن الأنبياء عليهم الصلاة والسلام: داود وغيره- منزهون من الوقوع في صغائر الذنوب مبرؤن من ذلك، والتمسوا المحامل الصحيحة لأمثال هذه القصة، وهذا هو الحق الأبلج، والسبيل الأبهج، إن شاء الله تعالى.]]',     source_page = '75',     updated_at  = datetime('now') WHERE id = 'QR:TE:98a375c019bfa31e7fd57ea2';
UPDATE qr_tafsir_entries SET content_ar = 'أَفَغَيْرَ اللَّهِ منصوب بأعبد. وتَأْمُرُونِّي اعتراض. ومعناه، أفغير الله أعبد بأمركم، وذلك حين قال له المشركون: استلم بعض آلهتنا ونؤمن بإلهك. أو ينصب بما يدل عليه جملة قوله تَأْمُرُونِّي أَعْبُدُ لأنه في معنى تعبدوننى وتقولون لي: اعبد، والأصل: تأمروننى أن أعبد، فحذف «أن» ورفع الفعل، كما في قوله: ألا أيهذا الزّاجرى أحضر الوغى [[تقدم شرح هذا الشاهد بالجزء الأول فراجعه إن شئت اه مصححه.]] ألا تراك تقول: أفغير الله تقولون لي اعبده، وأ فغير الله تقولون لي أعبد، فكذلك أفغير الله تأمروننى أن أعبده. وأ فغير الله تأمروننى أن أعبد، والدليل على صحة هذا الوجه: قراءة من قرأ أَعْبُدُ بالنصب. وقرئ: تأمروننى، على الأصل. وتأمرونى، على إدغام النون أو حذفها.',     source_page = '159',     updated_at  = datetime('now') WHERE id = 'QR:TE:97956e2eb5c0f8750a0c9b5d';
UPDATE qr_tafsir_entries SET content_ar = 'الآزفة: القيامة، سميت بذلك لأزوفها، أى: لقربها. ويجوز أن يريد بيوم الآزفة: وقت الخطة الآزفة، وهي مشارفتهم دخول النار، فعند ذلك ترتفع قلوبهم عن مقارّها فتلصق بحناجرهم، فلا هي تخرج فيموتوا، ولا ترجع إلى مواضعها فيتنفسوا ويتروّحوا، ولكنها معترضة كالشجا، كما قال تعالى فَلَمَّا رَأَوْهُ زُلْفَةً سِيئَتْ وُجُوهُ الَّذِينَ كَفَرُوا. فإن قلت: كاظِمِينَ بم انتصب؟ قلت: هو حال عن أصحاب القلوب على المعنى، لأن المعنى: إذ قلوبهم لدى حناجرهم كاظمين عليها. ويجوز أن يكون حالا عن القلوب، وأن القلوب كاظمة على غم وكرب فيها مع بلوغها الحناجر، وإنما جمع الكاظم جمع السلامة، لأنه وصفها بالكظم الذي هو من أفعال العقلاء، كما قال تعالى رَأَيْتُهُمْ لِي ساجِدِينَ وقال فَظَلَّتْ أَعْناقُهُمْ لَها خاضِعِينَ وتعضده قراءة من قرأ: كاظمون. ويجوز أن يكون حالا عن قوله: وأنذرهم، أى: وأنذرهم مقدّرين أو مشارفين الكظم، كقوله تعالى فَادْخُلُوها خالِدِينَ الحميم: المحب المشفق. والمطاع: مجاز في المشفع، لأن حقيقة الطاعة نحو حقيقة الأمر في أنها لا تكون إلا لمن فوقك. فإن قلت: ما معنى قوله تعالى: وَلا شَفِيعٍ يُطاعُ؟ قلت: يحتمل أن يتناول النفي الشفاعة والطاعة معا، وأن يتناول الطاعة دون الشفاعة، [[قال محمود: «يحتمل أن يكون المنفي الشفيع الذي هو الموصوف وصفته وهي الطاعة، ويحتمل أن يكون المنفي الصفة وهي الطاعة والشفيع ثابت» قال أحمد: إنما جاء الاحتمال من حيث دخول النفي على مجموع الموصوف والصفة. ونفى المجموع، كما يكون بنفي كل واحد من جزئيه، وكذلك يكون بنفي أحدهما، على أن المراد هنا- كما قال-: نفى الأمرين جميعا. قال: وفائدة ذكر الموصوف أنه كالدليل على نفى الصفة، لأنه إذا انتفى الموصوف انتفت الصفة قطعا، قلت: فكأنه نفى الصفة مرتين من وجهين مختلفين.]] كما تقول: ما عندي كتاب يباع، فهو محتمل نفى البيع وحده، وأن عندك كتابا إلا أنك لا تبيعه، ونفيهما جميعا، وأن لا كتاب عندك، ولا كونه مبيعا. ونحوه: ولا ترى الضّبّ بها ينجحر [[تقدم شرح هذا الشاهد بالجزء الأول فراجعه إن شئت اه مصححه.]] يريد: نفى الضب وانجحاره. فإن قلت: فعلى أى الاحتمالين يجب حمله؟ قلت: على نفى الأمرين جميعا، من قبل أن الشفعاء هم أولياء الله، وأولياء الله لا يحبون ولا يرضون إلا من أحبه الله ورضيه، وأن الله لا يحب الظالمين، فلا يحبونهم، وإذا لم يحبوهم لم ينصروهم ولم يشفعوا لهم. قال الله تعالى وَما لِلظَّالِمِينَ مِنْ أَنْصارٍ وقال: وَلا يَشْفَعُونَ إِلَّا لِمَنِ ارْتَضى ولأن الشفاعة لا تكون إلا في زيادة التفضل، [[قوله «لا تكون إلا في زيادة التفضل» هذا عند المعتزلة. أما عند أهل السنة فتكون في الخروج من النار أيضا، كما تقرر في التوحيد. وحديث الشفاعة مشهور، نعم الكفار لا خروج لهم من النار. (ع)]] وأهل التفضل وزيادته إنما هم أهل الثواب، بدليل قوله تعالى وَيَزِيدُهُمْ مِنْ فَضْلِهِ وعن الحسن رضى الله عنه: والله ما يكون لهم شفيع البتة، فإن قلت: الغرض حاصل بذكر الشفيع ونفيه، فما الفائدة في ذكر هذه الصفة ونفيها؟ قلت: في ذكرها فائدة جليلة، وهي أنها ضمت إليه، ليقام انتفاء الموصوف مقام الشاهد على انتفاء الصفة، لأن الصفة لا تتأتى بدون موصوفها، فيكون ذلك إزالة لتوهم وجود الموصوف، بيانه: أنك إذا عوتبت على القعود عن الغزو فقلت: ما لي فرس أركبه، ولا معى سلاح أحارب به، فقد جعلت عدم الفرس وفقد السلاح علة مانعة من الركوب والمحاربة، كأنك تقول: كيف يتأتى منى الركوب والمحاربة ولا فرس لي ولا سلاح معى، فكذلك قوله وَلا شَفِيعٍ يُطاعُ معناه: كيف يتأتى التشفيع ولا شفيع، فكان ذكر التشفيع والاستشهاد على عدم تأتيه بعدم الشفيع: وضعا لانتفاء الشفيع موضع الأمر المعروف [[قوله «موضع الأمر المعروف» أى الذي يعرفه السامع ويسلمه، كما هو شأن الشاهد على الدعوى، وإذا كان انتفاء الشفيع معروفا فلا ينتفي أن يتوهم وجوده، وبهذا يتبين قوله فيما سبق، فيكون ذلك إزالة لتوهم وجود الموصوف. (ع)]] غير المنكر الذي لا ينبغي أن يتوهم خلافه.',     source_page = '426',     updated_at  = datetime('now') WHERE id = 'QR:TE:61a82ffb85e185f66a589be6';
UPDATE qr_tafsir_entries SET content_ar = 'رَجُلٌ مُؤْمِنٌ وقرئ: رجل، بسكون الجيم كما يقال: عضد، في عضد وكان قبطيا ابن عم لفرعون: آمن بموسى سرا وقيل كان إسرائيليا ومِنْ آلِ فِرْعَوْنَ صفة لرجل. أو صلة ليكتم، أى: يكتم إيمانه من آل فرعون، واسمه: سمعان أو حبيب. وقيل: خربيل، أو حزبيل. والظاهر: أنه كان من آل فرعون، فإنّ المؤمنين من بنى إسرائيل لم يقلوا ولم يعزوا. والدليل عليه قول فرعون: أَبْناءَ الَّذِينَ آمَنُوا مَعَهُ. وقول المؤمن فَمَنْ يَنْصُرُنا مِنْ بَأْسِ اللَّهِ إِنْ جاءَنا دليل ظاهر على أنه ينتصح لقومه أَنْ يَقُولَ لأن يقول. وهذا إنكار منه عظيم وتبكيت شديد، كأنه قال: أترتكبون الفعلة الشنعاء التي هي قتل نفس محرمة، وما لكم علة قط في ارتكابها إلا كلمة الحق التي نطق بها وهي قوله رَبِّيَ اللَّهُ مع أنه لم يحضر لتصحيح قوله بينة واحدة، ولكن بينات عدّة من عند من نسب إليه الربوبية، وهو ربكم لا ربه وحده، وهو استدراج لهم إلى الاعتراف به، وليلين بذلك جماحهم ويكسر من سورتهم [[قال محمود: «الظاهر أن الرجل من آل فرعون، وقيل: إنه من بنى إسرائيل. ومن آل فرعون: متعلق بيكتم، تقديره: يكتم إيمانه من آل فرعون، وهو بعيد، لأن بنى إسرائيل كان إيمانهم ظاهرا فاشيا، ولقد استدرجهم هذا المؤمن في الايمان باستشهاده على صدق موسى بإحضاره عليه السلام من عند من تنسب إليه الربوبية ببينات عدة لا بينة واحدة، وأتى بها معرفة، معناه: البينات العظيمة التي شهدتموها وعرفتموها على ذلك، ليلين بذلك جماحهم ويكسر من سورتهم ... الخ» قال أحمد: لقد أحسن الفهم والتفطن لأسرار هذا القول، ويناسب تقديم الكاذب على الصادق هنا قوله تعالى وَشَهِدَ شاهِدٌ مِنْ أَهْلِها إِنْ كانَ قَمِيصُهُ قُدَّ مِنْ قُبُلٍ فَصَدَقَتْ وَهُوَ مِنَ الْكاذِبِينَ وَإِنْ كانَ قَمِيصُهُ قُدَّ مِنْ دُبُرٍ فَكَذَبَتْ وَهُوَ مِنَ الصَّادِقِينَ فقدم الشاهد أمارة صدقها على أمارة صدق يوسف، وإن كان الصادق هو يوسف دونها، لرفع التهمة وإبعاد الظن، وإدلالا بأن الحق معه، ولا يضره التأخير لهذه الفائدة. وقريب من هذا التصرف لابعاد التهمة ما في قصة يوسف مع أخيه، إذ بدأ بأوعيتهم قبل وعاء أخيه، حتى قيل: إنه لما انتهى إليه قال: اللهم ما سرق هذا ولا هو بوجه سارق، فاطمأنت أنفسهم وانزاحت التهمة عن يوسف أن يكون قصد ذلك، فقالوا: والله لنفتشنه، فاستخرجها من وعائه.]] ، ولك أن تقدر مضافا محذوفا، أى: وقت أن تقول. والمعنى. أتقتلونه ساعة سمعتم منه هذا القول من غير روية ولا فكر في أمره. وقوله بِالْبَيِّناتِ يريد بالبينات العظيمة التي عهدتموها وشهدتموها، ثم أخذهم بالاحتجاج على طريقة التقسيم فقال: لا يخلو من أن يكون كاذبا أو صادقا، وَإِنْ يَكُ كاذِباً فَعَلَيْهِ كَذِبُهُ أى يعود عليه كذبه ولا يتخطاه ضرره، وَإِنْ يَكُ صادِقاً يُصِبْكُمْ بَعْضُ ما يعدكم إن تعرّضتم له. فإن قلت: لم قال: بعض الَّذِي يَعِدُكُمْ وهو نبىّ صادق، لا بد لما يعدهم أن يصيبهم كله لا بعضه؟ قلت: لأنه احتاج في مقاولة خصوم موسى ومنا كريه إلى أن يلاوصهم [[قوله «إلى أن يلاوصهم ويداريهم» في الصحاح: فلان يلاوص الشجر، أى: ينظر كيف يأتيها لقلعها. (ع)]] ويداريهم، ويسلك معهم طريق الإنصاف في القول، ويأتيهم من وجهة المناصحة، فجاء بما علم أنه أقرب إلى تسليمهم لقوله، وأدخل في تصديقهم له وقبولهم منه، فقال وَإِنْ يَكُ صادِقاً يُصِبْكُمْ بَعْضُ الَّذِي يَعِدُكُمْ وهو كلام المنصف في مقاله غير المشتط فيه، ليسمعوا منه ولا يردّوا عليه، وذلك أنه حين فرضه صادقا فقد أثبت أنه صادق في جميع ما يعد، ولكنه أردفه يُصِبْكُمْ بَعْضُ الَّذِي يَعِدُكُمْ ليهضمه بعض حقه في ظاهر الكلام، فيريهم أنه ليس بكلام من أعطاه حقه وافيا، فضلا أن يتعصب له، أو يرمى بالحصا من ورائه، وتقديم الكاذب على الصادق أيضا من هذا القبيل، وكذلك قوله إِنَّ اللَّهَ لا يَهْدِي مَنْ هُوَ مُسْرِفٌ كَذَّابٌ. فإن قلت: فعن أبى عبيدة أنه فسر البعض بالكل، وأنشد بيت لبيد: ترّاك امكنة إذا لم أرضها ... أو يرتبط بعض النفوس حمامها [[تقدم شرح هذا الشاهد بالجزء الأول فراجعه إن شئت اه مصححه.]] قلت: إن صحت الرواية عنه. فقد حق فيه قول المازني في مسألة العلقى: كان أجفى من أن يفقه ما أقول له إِنَّ اللَّهَ لا يَهْدِي مَنْ هُوَ مُسْرِفٌ يحتمل أنه كان مسرفا كذابا خذله الله وأهلكه ولم يستقم له أمر، فيتخلصون منه. وأنه لو كان مسرفا كذابا لما هداه الله للنبوّة، ولما عضده بالبينات. وقيل: ما تولى أبو بكر من رسول الله ﷺ كان أشدّ من ذلك طاف ﷺ بالبيت، فلقوه حين فرغ، فأخذوا بمجامع ردائه فقالوا له: أنت الذي تنهانا عما كان يعبد آباؤنا، فقال: أنا ذاك، فقام أبو بكر الصدّيق رضى الله عنه فالتزمه من ورائه وقال: أتقتلون رجلا أن يقول ربى الله، وقد جاءكم بالبينات من ربكم، رافعا صوته بذلك، وعيناه تسفحان، حتى أرسلوه [[أخرجه النسائي من طريق هشام عن عروة عن أبيه عن عمرو بن العاص. وابن حبان من طريق يحيى ابن عروة عن عروة عن عبد الله بن عمرو بن العاص أتم منه. قلت: علقه البخاري نحوهما.]] . وعن جعفر الصادق: أنّ مؤمن آل فرعون قال ذلك سرا، وأبو بكر قاله ظاهرا.',     source_page = '641',     updated_at  = datetime('now') WHERE id = 'QR:TE:57483ba793dfc737653b9abc';
UPDATE qr_tafsir_entries SET content_ar = 'بِالْكِتابِ بالقرآن وَبِما أَرْسَلْنا بِهِ رُسُلَنا من الكتب. فإن قلت: وهل قوله فَسَوْفَ يَعْلَمُونَ إِذِ الْأَغْلالُ فِي أَعْناقِهِمْ إلى مثل قولك: سوف أصوم أمس؟ قلت: المعنى على إذا: إلا أن الأمور المستقبلة لما كانت في أخبار الله تعالى متيقنة مقطوعا بها: عبر عنها بلفظ ما كان ووجد، والمعنى على الاستقبال. وعن ابن عباس: والسلاسل يسحبون بالنصب وفتح الياء، على عطف الجملة الفعلية على الاسمية. وعنه: والسلاسل يسحبون بحر السلاسل. ووجهه أنه لو قيل: إذ أعناقهم في الأغلال مكان قوله إِذِ الْأَغْلالُ فِي أَعْناقِهِمْ لكان صحيحا مستقيما، فلما كانتا عبارتين معتقبتين: حمل قوله وَالسَّلاسِلُ على العبارة الأخرى. ونظيره: مشائيم ليسوا مصلحين عشيرة ... ولا ناعب إلّا ببين غرابها [[مر شرح هذا الشاهد بالجزء الأول فراجعه إن شئت اه مصححه.]] كأنه قيل: بمصلحين. وقرئ: وبالسلاسل يسحبون فِي النَّارِ يُسْجَرُونَ من سجر التنور إذا ملأه بالوقود. ومنه: السجير [[قوله «ومنه السجير» في الصحاح: «سجير الرجل» : صفيه وخليله، والجمع السجراء. (ع)]] ، كأنه سجر بالحب، أى: مليء. ومعناه: أنهم في النار فهي محيطة بهم، وهم مسجورون بالنار مملوءة بها أجوافهم. ومنه قوله تعالى نارُ اللَّهِ الْمُوقَدَةُ الَّتِي تَطَّلِعُ عَلَى الْأَفْئِدَةِ اللهم أجرنا من نارك فإنا عائذون بجوارك ضَلُّوا عَنَّا غابوا عن عيوننا، فلا نراهم ولا ننتفع بهم. فإن قلت: أما ذكرت في تفسير قوله تعالى إِنَّكُمْ وَما تَعْبُدُونَ مِنْ دُونِ اللَّهِ حَصَبُ جَهَنَّمَ: أنهم مقرونون بآلهتهم، فكيف يكونون معهم وقد ضلوا عنهم؟ قلت: يجوز أن يضلوا عنهم إذا وبخوا وقيل لهم: أينما كنتم تشركون من دون الله فيغيثوكم ويشفعوا لكم، وأن يكونوا معهم في سائر الأوقات [[قوله «في سائر الأوقات» أى باقى الأوقات بعد وقت التوبيخ. (ع)]] ، وأن يكونوا معهم في جميع أوقاتهم، إلا أنهم لما لم ينفعوهم فكأنهم ضالون عنهم بَلْ لَمْ نَكُنْ نَدْعُوا مِنْ قَبْلُ شَيْئاً أى تبين لنا أنهم لم يكونوا شيئا، وما كنا نعبد بعبادتهم شيئا كما تقول: حسبت أنّ فلانا شيء فإذا هو ليس بشيء إذا خبرته فلم تر عنده خيرا كَذلِكَ يُضِلُّ اللَّهُ الْكافِرِينَ مثل ضلال آلهتهم عنهم يضلهم عن آلهتهم، حتى لو طلبوا الآلهة أو طلبتهم الآلهة لم يتصادفوا ذلِكُمْ الإضلال بسبب ما كان لكم من الفرح والمرح بِغَيْرِ الْحَقِّ وهو الشرك وعبادة الأوثان ادْخُلُوا أَبْوابَ جَهَنَّمَ السبعة المقسومة لكم. قال الله تعالى لَها سَبْعَةُ أَبْوابٍ لِكُلِّ بابٍ مِنْهُمْ جُزْءٌ مَقْسُومٌ. خالِدِينَ مقدّرين الخلود فَبِئْسَ مَثْوَى الْمُتَكَبِّرِينَ عن الحق المستخفين به مثواكم أو جهنم. فإن قلت: أليس قياس النظم أن يقال: فبئس مدخل المتكبرين، كما تقول: زر بيت الله فنعم المزار، وصل في المسجد الحرام فنعم المصلى؟ قلت: الدخول المؤقت بالخلود في معنى الثواء.',     source_page = '381',     updated_at  = datetime('now') WHERE id = 'QR:TE:46acda1df0f23ee6f0c2f097';
UPDATE qr_tafsir_entries SET content_ar = 'فإن قلت: فما وجوه القراءات الثلاث في وَيَعْلَمَ؟ قلت: أما الجزم فعلى ظاهر العطف وأما الرفع فعلى الاستئناف. وأما النصب فللعطف على تعليل محذوف تقديره: لينتقم منهم ويعلم الذين يجادلون ونحوه في العطف على التعليل المحذوف غير عزيز في القرآن، منه قوله تعالى وَلِنَجْعَلَهُ آيَةً لِلنَّاسِ وقوله تعالى وَخَلَقَ اللَّهُ السَّماواتِ وَالْأَرْضَ بِالْحَقِّ وَلِتُجْزى كُلُّ نَفْسٍ بِما كَسَبَتْ وأما قول الزجاج: النصب على إضمار أن، لأنّ قبلها جزاء، تقول: ما تصنع أصنع مثله وأكرمك. وإن شئت وأكرمك، على: وأنا أكرمك. وإن شئت وأكرمك جزما، ففيه نظر لما أورده سيبويه في كتابه. قال: واعلم أنّ النصب بالفاء والواو في قوله: إن تأتنى آتك وأعطيك: ضعيف، وهو نحو من قوله: وألحق بالحجاز فاستريحا [[تقدم شرح هذا الشاهد بالجزء الأول فراجعه إن شئت اه مصححه.]] فهذا يجوز، وليس بحدّ الكلام ولا وجهه، إلا أنه في الجزاء صار أقوى قليلا، لأنه ليس بواجب أنه يفعل. إلا أن يكون من الأوّل فعل، فلما ضارع الذي لا يوجبه كالاستفهام ونحوه: أجازوا فيه هذا على ضعفه اه. ولا يجوز أن تحمل القراءة المستفيضة على وجه ضعيف ليس بحدّ الكلام ولا وجهه، ولو كانت من هذا الباب لما أخلى سيبويه منها كتابه، وقد ذكر نظائرها من الآيات المشكلة. فإن قلت: فكيف يصح المعنى على جزم وَيَعْلَمَ؟ قلت: كأنه قال: أو إن يشأ يجمع بين ثلاثة أمور: هلاك قوم ونجاة قوم وتحذير آخرين مِنْ مَحِيصٍ من محيد عن عقابه.',     source_page = '557',     updated_at  = datetime('now') WHERE id = 'QR:TE:c6f4c0ed10d186a9841f1d0f';
UPDATE qr_tafsir_entries SET content_ar = 'قرئ: ومن يعش، بضم الشين وفتحها. والفرق بينهما أنه إذا حصلت الآفة في بصره قيل: عشى. وإذا نظر نظر العشى ولا آفة به قيل عشا. ونظيره: عرج، لمن به الآفة [[قال محمود: «يقال عشى بصره بكسر الشين إذا أصابته الآفة ... » قال أحمد: في هذه الآية نكتتان بديعتان، إحداهما: الدلالة على أن النكرة الواقعة في سياق الشرط تفيد العموم، وهي مسألة اضطرب فيها الأصوليون وإمام الحرمين من القائلين بافادتها العموم، حتى استدرك على الأئمة إطلاقهم القول بأن النكرة في سياق الإثبات تخص، وقال: إن الشرط يعم، والنكرة في سياقه تعم. وقد رد عليه الفقيه أبو الحسن على الأنبارى شارح كتابه ردا عنيفا. وفي هذه الآية للإمام ومن قال بقوله كفاية، وذلك أن الشيطان ذكر فيها منكرا في سياق شرط، ونحن نعلم أنه إنما أراد عموم الشياطين لا واحدا لوجهين، أحدهما: أنه قد ثبت أن لكل أحد شيطانا، فكيف بالعاشى عن ذكر الله، والآخر: يؤخذ من الآية: وهو أنه أعاد عليه الضمير مجموعا في قوله وَإِنَّهُمْ فانه عائد إلى الشيطان قولا واحدا «ولولا إفادته عموم الشمول لما جاز عود ضمير الجمع عليه بلا إشكال، فهذه نكتة تجد عند إسماعها لمخالفي هذا الرأى سكتة. والنكتة الثانية: أن في هذه الآية ردا على من زعم أن العود على معنى من يمنع من العود على لفظها بعد ذلك. واحتج المانع لذلك بأنه إجمال بعد تفسير، وهو خلاف المعهود من الفصاحة. وقد نقض الكندي هذا بقوله تعالى وَمَنْ يُؤْمِنْ بِاللَّهِ وَيَعْمَلْ صالِحاً يُدْخِلْهُ جَنَّاتٍ تَجْرِي مِنْ تَحْتِهَا الْأَنْهارُ خالِدِينَ فِيها أَبَداً قَدْ أَحْسَنَ اللَّهُ لَهُ رِزْقاً ونقض غيره بقوله وَمِنَ النَّاسِ مَنْ يَشْتَرِي لَهْوَ الْحَدِيثِ لِيُضِلَّ عَنْ سَبِيلِ اللَّهِ بِغَيْرِ عِلْمٍ وَيَتَّخِذَها هُزُواً أُولئِكَ لَهُمْ عَذابٌ مُهِينٌ وَإِذا تُتْلى عَلَيْهِ ... الآية وكان جدي رحمه الله قد استخرج من هذه الآية بعض ذلك، لأنه أعاد على اللفظ في قوله: يَعْشُ ولَهُ مرتين، ثم على المعنى في قوله لَيَصُدُّونَهُمْ ثم على اللفظ بقوله حَتَّى إِذا جاءَنا وقد قدمت أن الذي منع ذلك قد يكون اقتصر بمنعه على مجيء ذلك في جملة واحدة وأما إذا تعددت الجمل واستفلت كل بنفسها فقد لا يمنع ذلك حتى رددت على الزمخشري في قوله تعالى لا يَمْلِكُونَ الشَّفاعَةَ إِلَّا مَنِ اتَّخَذَ عِنْدَ الرَّحْمنِ عَهْداً فان الجملة واحدة، فانظره في موضعه.]] . وعرج، لمن مشى مشية العرجان من غير عرج. قال الحطيئة: متى تأته تعشو إلى ضوء ناره [[كسوب ومتلاف إذا ما سألته ... تهلل واهتز اهتزاز المهند وذاك امرؤ إن يعطك اليوم نائلا ... بكفيه لم يمنعك من نائل الغد متى تأته تعشو إلى ضوء ناره ... تجد خير نار عندها خير موقد للحطيئة، يقول: هو كثير الكسب وكثير الإتلاف، وبينهما طباق التضاد: إذا سألته أجابك بسرعة وطلاقة وجه وهو المراد بقوله: تهلل واهتز كاهتزاز السيف المطلق من حديد الهند، إذا أعطاك اليوم عطاء بكفيه معا كناية عن كثرة العطاء، وسألته في غد أعطاك أيضا. وعشى يعشى كرضى يرضى: إذا كان ببصره آفة. وعشى يعشو: إذا تعاشى بغير آفة. والمعنى: منى تأته على هيئة الأعشى- مجاز عن إظهار الفاقة- تجده أكرم الناس، عبر عنه بذلك على طريق الكناية.]] أى: تنظر إليها نظر العشىّ لما يضعف بصرك من عظم الوقود واتساع الضوء. وهو بين في قوله حاتم: أعشو إذا ما جارتى برزت ... حتّى يوارى جارتى الخدر [[ناري ونار الجار واحدة ... وإليه قبلي تنزل القدر ما ضرني جار أجاوره ... ألا يكون لبابه ستر أعشو إذا ما جارتى برزت ... حتى يوارى جارتى الخدر لحاتم الطائي: وعشى يعشى كرضى يرضى: صار لا يبصر ليلا، وعشا يعشو كدعا يدعو: إذا نظر كنظر الأعشى. يقول: إن ناري هي نار جارى، وتنزل قدرى إليه ليأكل منها قبلي أو ناري ونار جارى واحدة في الزمن والقوة ومع ذلك تنزل قدره إليه قبلي ليأكلها سريعا خوف اطلاع أحد عليه. لكن يبعد هذا أن المقام ليس لذم الجار بل للمدح. ثم هذا كناية عن شدة كرمه على غيره، ثم وصف نفسه بالعفة بقوله: ما ضرني جار من جيراني بمسبة ولا غيرها من أن لا يكون لبابه حجاب يستر أهله، فانى أتغافل وأغض بصرى إذا خرجت جارتى، حتى يسترها بينها. وأتى بالظاهر موضع المضمر ليفيد أنه ينبغي مراعاة حق الجوار. والاحتمال الأول أقعد، لأن معناه أنه يبره ويعف عن محارمه. وأما الثاني ففيه ذم جاره، وهو لا يلائم بعده.]] وقرئ: يعشو، على أنّ من موصولة غير مضمنة معنى الشرط. وحق هذا القارئ أن يرفع نقيض. ومعنى القراءة بالفتح: ومن يعم عَنْ ذِكْرِ الرَّحْمنِ وهو القرآن، كقوله تعالى صُمٌّ بُكْمٌ عُمْيٌ وأما القراءة بالضم فمعناها: ومن يتعام عن ذكره، أى: يعرف أنه الحق وهو يتجاهل ويتغابى، كقوله تعالى وَجَحَدُوا بِها وَاسْتَيْقَنَتْها أَنْفُسُهُمْ. نُقَيِّضْ لَهُ شَيْطاناً نخذله [[قوله «نقيض له شيطانا: نخذله» تأويله بذلك مبنى على أنه تعالى لا يفعل القبيح، وهو مذهب المعتزلة. وعند أهل السنة أنه فاعل الكائنات كلها، فالآيات على ظاهرها (ع)]] ونخل بينه وبين الشياطين، كقوله تعالى وَقَيَّضْنا لَهُمْ قُرَناءَ، أَلَمْ تَرَ أَنَّا أَرْسَلْنَا الشَّياطِينَ عَلَى الْكافِرِينَ وقرئ: يقيض، أى: يقيض له الرحمن ويقيض له الشيطان. فإن قلت: لم جمع ضمير من وضمير الشيطان في قوله وَإِنَّهُمْ لَيَصُدُّونَهُمْ؟ قلت: لأنّ مَنْ مبهم في جنس العاشى، وقد قيض له شيطان مبهم في جنسه، فلما جاز أن يتناولا لإبهامهما غير واحدين: جاز أن يرجع الضمير إليهما مجموعا حَتَّى إِذا جاءَنا العاشى. وقرئ: جاءانا، على أنّ الفعل له ولشيطانه. قالَ لشيطانه يا لَيْتَ بَيْنِي وَبَيْنَكَ بُعْدَ الْمَشْرِقَيْنِ يريد المشرق والمغرب، فغلب. كما قيل: العمران والقمران. فإن قلت: فما بعد المشرقين؟ قلت: تباعدهما، والأصل: بعد المشرق من المغرب، والمغرب من المشرق. فلما غلب وجمع المفترقين بالتثنية: أضاف البعد إليهما أَنَّكُمْ في محل الرفع على الفاعلية، يعنى: ولن ينفعكم كونكم مشتركين في العذاب كما ينفع الواقعين في الأمر الصعب اشتراكهم فيه، لتعاونهم في تحمل أعبائه وتقسمهم لشدّته وعنائه، وذلك أنّ كل واحد منكم به من العذاب ما لا تبلغه طاقته، ولك أن تجعل الفعل للتمني في قوله يا لَيْتَ بَيْنِي وَبَيْنَكَ على معنى: ولن ينفعكم اليوم ما أنتم فيه من تمنى مباعدة القرين. وقوله أَنَّكُمْ فِي الْعَذابِ مُشْتَرِكُونَ تعليل، أى: لن ينفعكم تمنيكم، لأنّ حقكم أن تشتركوا أنتم وقرناؤكم في العذاب كما كنتم مشتركين في سببه وهو الكفر. وتقوّيه قراءة من قرأ: إنكم بالكسر. وقيل: إذا رأى الممنوّ بشدّة [[قوله «إذا رأى الممنو بشدة» أى المبتلى. ومنى: أى ابتلى. أفاده الصحاح (ع)]] من منى بمثلها: روّحه ذلك ونفس بعض كربه، وهو التأسى الذي ذكرته الخنساء: أعزى النّفس عنه بالتّأسى [[يذكرني طلوع الشمس صخرا ... وأذكره بكل غروب شمس ولولا كثرة الباكين حولي ... على إخوانهم لقتلت نفسي وما يبكون مثل أخى ولكن ... أعزى النفس عنه بالتأسى للخنساء ترثى أخاها. وإسناد التذكير الطلوع: مجاز عقلى، لأنه سبب في تذكيرها إياه، وكذلك الغروب حيث كان ذهابه عند الأول وإيابه عند الثاني عادة. أو لأنه يذهب في الأول للغارات، ويجلس في الثاني مع الضيفان. أو لأن طلوعها يشبه طلعته، وغروبها: يشبه موته. وفيه نوع من البديع يسمى التنكيت: وهو الإتيان بلفظ يسد غيره مسده، لولا نكتة فيه ترجح اختصاصه بالذكر: لكان اختصاصه خطأ، كما في اختصاص الوقتين هنا. أفاده السيوطي في شرح عقود الجمان. وفيه أيضا نوع آخر يسمى الادماج: وهو أن يضمن كلام سيق لمعنى معنى آخر، كما ضمن الكلام المسوق هنا لمعنى الرثاء معنى المدح بالشجاعة والكرم. أو بحسن الطلعة. والباء في «بكل» سببيه. ويحتمل أن الاسناد للأول من باب الاسناد للزمان، فتكون الباء في الثاني بمعنى «في» أو «مع» وذكر الشمس ثانيا في آخر المصراع الثاني من باب رد العجز على الصدر. وأعزى النفس: أسليها وأصبرها عنه بالتأسى، أى: الاقتداء بغيري من أهل المصائب وفي اقتدائها بالباكين من الرجال: إشعار بتجلدها وعظم شأنها مثلهم. وروى «على أمواتهم» بدل: «على إخوانهم» ، و «أسلى» بدل «أعزى» .]] فهؤلاء لا يؤسيهم اشتراكهم ولا يروّحهم، لعظم ما هم فيه. فإن قلت: ما معنى قوله تعالى إِذْ ظَلَمْتُمْ؟ قلت: معناه: إذ صح ظلمكم وتبين ولم يبق لكم ولا لأحد شبهة في أنكم كنتم ظالمين، وذلك يوم القيامة. وإذ: بدل من اليوم. ونظيره: إذا ما انتسبنا لم تلدني لئيمة [[مر شرح هذا الشاهد بالجزء الثالث فراجعه إن شئت اه مصححه.]] أى: تبين أنى ولد كريمة.',     source_page = '40',     updated_at  = datetime('now') WHERE id = 'QR:TE:f53afc7e0b6d09d3d73f2e87';
UPDATE qr_tafsir_entries SET content_ar = 'أَفَنَضْرِبُ عَنْكُمُ الذِّكْرَ صَفْحاً بمعنى: أفننحى عنكم الذكر ونذوده عنكم على سبيل المجاز، من قولهم: ضرب الغرائب عن الحوض. ومنه قول الحجاج: ولأضربنكم ضرب غرائب الإبل. وقال طرفة: أضرب عنك الهموم طارقها ... ضربك بالسّيف قونس الفرس [[تقدم شرح هذا الشاهد بهذا الجزء فراجعه إن شئت اه مصححه.]] والفاء للعطف على محذوف، تقديره: أنهملكم فنضرب عنكم الذكر، إنكارا لأن يكون الأمر على خلاف ما قدّم من إنزاله الكتاب. وخلقه قرآنا عربيا، ليعقلوه ويعملوا بمواجبه. وصفحا على وجهين. إما مصدر من صفح عنه: إذا أعرض، منتصب على أنه مفعول له، على معنى: أفنعزل عنكم إنزال القرآن وإلزام الحجة به إعراضا عنكم. وإمّا بمعنى الجانب من قولهم: نظر إليه بصفح وجهه وصفح وجهه، على معنى: أفننحيه عنكم جانبا، فينتصب على الظرف كما تقول: ضعه جانبا، وامش جانبا. وتعضده قراءة من قرأ: صفحا بالضم. وفي هذه القراءة وجه آخر: وهو أن يكون تخفيف صفح جمع صفوح، وينتصب على الحال، أى: صافحين معرضين أَنْ كُنْتُمْ أى: لأن كنتم. وقرئ: إن كنتم، وإذ كنتم. فإن قلت: كيف استقام معنى إن الشرطية، وقد كانوا مسرفين على البتّ؟ قلت: هو من الشرط الذي ذكرت أنه يصدر عن المدل [[قوله «عن المدل» أى: المواثق. أفاده الصحاح. (ع) .]] بصحة الأمر، المتحقق لثبوته، كما يقول الأجير: إن كنت عملت لك فوفني حقي، وهو عالم بذلك، ولكنه يخيل في كلامه أن تفريطك في الخروج عن الحق: فعل من له شك في الاستحقاق، مع وضوحه استجهالا له.',     source_page = '87',     updated_at  = datetime('now') WHERE id = 'QR:TE:c4aa66a68d6a21c36cd1a9cd';
UPDATE qr_tafsir_entries SET content_ar = 'وقرئ: حجتهم بالنصب والرفع، على تقديم خبر كان وتأخيره. فإن قلت: لم سمى قولهم حجة وليس بحجة؟ قلت: لأنهم أدلوا به كما يدلى المحتج بحجته وساقوه مساقها، فسميت حجة على سبيل التهكم. أو لأنه في حسبانهم وتقديرهم حجة. أو لأنه في أسلوب قوله: تحيّة بينهم ضرب وجيع [[تقدم شرح هذا الشاهد بالجزء الأول فراجعه إن شئت اه مصححه.]] كأنه قيل: ما كان حجتهم إلا ما ليس بحجة. والمراد: نفى أن تكون لهم حجة البتة. فإن قلت: كيف وقع قوله قُلِ اللَّهُ يُحْيِيكُمْ جوابا لقولهم ائْتُوا بِآبائِنا إِنْ كُنْتُمْ صادِقِينَ؟ قلت: لما أنكروا البعث وكذبوا الرسل، وحسبوا أنّ ما قالوه قول مبكت. ألزموا ما هو مقرّون به: من أنّ الله عز وجل هو الذي يحييهم ثم يميتهم، وضم إلى إلزام ذلك إلزام ما هو واجب الإقرار به إن أنصفوا وأصغوا إلى داعى الحق، وهو جمعهم إلى يوم القيامة، ومن كان قادرا على ذلك كان قادرا على الإتيان بآبائهم، وكان أهون شيء عليه.',     source_page = '60',     updated_at  = datetime('now') WHERE id = 'QR:TE:cf472be691845b06f06b5756';
UPDATE qr_tafsir_entries SET content_ar = 'الأفاك: الكذاب، والأثيم: المتبالغ في اقتراف الآثام يُصِرُّ يقبل على كفره ويقيم عليه. وأصله من إصرار الحمار على العانة [[قوله «من إصرار الحمار على العانة» جماعة حمر الوحش كما في الصحاح. وفيه أيضا: ضر الفرس أذنيه: ضمها إلى رأسه، فإذا لم يوقعوا قالوا: أصر الفرس، بالألف. (ع)]] وهو أن ينحى عليها صارّا أذنيه مُسْتَكْبِراً عن الإيمان بالآيات والإذعان لما ينطق به من الحق، مزدريا لها معجبا بما عنده. قيل: نزلت في النضر بن الحرث وما كان يشترى من أحاديث الأعاجم، ويشغل الناس بها عن استماع القرآن. والآية عامّة في كل ما كان مضارّا لدين الله. فإن قلت: ما معنى ثم في قوله ثُمَّ يُصِرُّ مُسْتَكْبِراً؟ قلت: كمعناه في قول القائل: يرى غمرات الموت ثمّ يزورها [[تقدم شرح هذا الشاهد بالجزء الثالث فراجعه إن شئت اه مصححه.]] وذلك أنّ غمرات الموت حقيقة، بأن ينجو رائيها بنفسه ويطلب الفرار عنها. وأمّا زيارتها والإقدام على مزاولتها. فأمر مستبعد، فمعنى ثم: الإيذان بأن فعل المقدّم عليها بعد ما رآها وعاينها، شيء يستبعد في العادات والطباع، وكذلك آيات الله الواضحة الناطقة بالحق، من تليت عليه وسمعها: كان مستبعدا في العقول إصراره على الضلالة عندها واستكباره عن الإيمان بها كَأَنْ مخففة، والأصل كأنه لم يسمعها: والضمير ضمير الشأن، كما في قوله: كأن ظبية تعطو إلى ناضر السّلم [[فيوما توافينا بوجه مقسم ... كأن ظبية تعطو إلى وارق السلم ويوما تريد مالنا مع مالها ... فان لم ننلها لم تنمنا ولم تتم الباعث بن صريم اليشكري يذكر حال امرأته. ويوما: ظرف مقدم. ويروى: ويوم، أى: ورب يوم تقابلنا فيه ولا حاجة لتقدير الرابط على نصب اليوم. وقسم قساما وقسامة، كجمل جمالا. وظرف ظرافة. والمقسم: المحسن. وكأن: مخففة من الثقيلة، واسمها ضمير المرأة، أو ضمير الشأن. وظبية: بالرفع على الأول خبر. وعلى الثاني: مبتدأ، وهو مع خبره خبر كان. وتعطو: صفة على الأول، وهو الخبر على الثاني. ويروى: ظبية، بالنصب، فهو الاسم وإن كان عملها مخففة قليلا. ويروى: مجرورا بالكاف، وإن: زائدة بين الجار والمجرور: وتعطو: تأخذ وتتناول، ماثلة إلى وارق السلم. ومن النوادر: أورق فهو وارق. وأينع فهو يانع. والقياس: مورق، أى: كثير الورق. ويروى: ناضر، بدل: وارق. والسلم: شجر العضاء، هذا شأنها في يوم. وفي يوم آخر تؤذينا فتريد مالنا منضما إلى مالها، فان نعطها لم تتركنا ننام من كثرة كلامها وإيذائها، ولم تنم هي أيضا. واليوم هنا: مطلق الزمن.]] ومحل الجملة النصب على الحال. أى: يصير مثل غير السامع وَإِذا بلغه شيء من آياتنا وعلم أنه منها اتَّخَذَها أى اتخذ الآيات هُزُواً ولم يقل: اتخذه، للإشعار بأنه إذا أحس بشيء من الكلام أنه من جملة الآيات التي أنزلها الله تعالى على محمد ﷺ: خاض في الاستهزاء بجميع الآيات. ولم يقتصر على الاستهزاء بما بلغه، ويحتمل: وإذا علم من آياتنا شيئا يمكن أن يتشبث به المعاند ويجد له محملا يتسلق به على الطعن والغميزة: افترصه واتخذ آيات الله هزوا، وذلك نحو افتراص ابن الزبعرى قوله عز وجل إِنَّكُمْ وَما تَعْبُدُونَ مِنْ دُونِ اللَّهِ حَصَبُ جَهَنَّمَ ومغالطته رسول الله ﷺ، وقوله: خصمتك. ويجوز أن يرجع الضمير إلى شيء، لأنه في معنى الآية كقول أبى العتاهية: نفسي بشيء من الدنيا معلّقة ... الله والقائم المهدي يكفيها [[نفسي بشيء من الدنيا معلقة ... الله والقائم المهدى يكفيها إنى لأيأس منها ثم يطمعنى ... فيها احتقارك للدنيا وما فيها لأبى العتاهية. وكنى بالشيء عن جارية من حظايا المهدى اسمها عتبة، ولذلك أعاد عليه الضمير مؤنثا. وقوله «من الدنيا» معناه: أنه لا يريد من الدنيا غيره. والقائم: أى بأمر الشرع. ويكفيها، أى: يكفيني تلك الحاجة. أو يكفى نفسي ما تريد، والله: بقطع الهمزة، لأن أول المصراع محل ابتداء في الجملة، إنى لأيأس أى أقطع طمعي منها، ثم أطمع فيها ثانيا بسبب احتقارك للدنيا وما فيها. وهو مدح بنهاية الكرم. وروى أنه كتب ذلك في ثوب، وأدرجه في برنية وأهداها المهدى، فهم بدفعها إليه فقالت: أتدفعني إلى رجل متكسب بالتعشق، فأمر بملء البرنية مالا ودفعها إليه، فقال للخزان: إنما أمر لي بدنانير، فقال له: نعطيك دراهم ونراجعه. واختلفوا في ذلك سنة، فقالت: لو كان عاشقا لما فرق بينهما.]] حيث أراد عتبة. وقرئ: علم أُولئِكَ إشارة إلى كل أفاك أثيم، لشموله الأفاكين. والوراء اسم للجهة التي يواريها الشخص من خلف أو قدام. قال: أليس ورائي أن تراخت منيّتى ... أدب مع الولدان أزحف كالنّسر [[لعبيد، والهمزة للتقرير. وورائي هنا بمعنى: أمامى، وهو في الأصل: الجهة التي يواريها الشخص، لكن يكثر في الجهة التي خلفه، وتوسع فيه حتى استعمل في كل غيب. ومنه: المستقبل. وتراخت: تباعدت وتأخرت. وأدب: أمشى بهينة وتؤدة. وأن المصدرية مقدرة قبله، لأنه اسم ليس، وإن كان لفظه مرفوعا. وأزحف: يحتمل أنه بدل، وأنه حال. وكالنسر: حال. أو معناه: كزحف النسر في الأرض، مع كونه أبيض وفيه نوع احتراس، لأنه يتوهم من قوله «مع الولدان» نقص عقله، فدل على أن المراد الضعف كالولدان. والشيب كالنسر، لأنه أبيض، مع كونه رئيس الطيور وكلها تخشاه.]] ومنه قوله عز وجل مِنْ وَرائِهِمْ أى من قدّامهم ما كَسَبُوا من الأموال في رحلهم ومتاجرهم وَلا مَا اتَّخَذُوا مِنْ دُونِ اللَّهِ من الأوثان.',     source_page = '515',     updated_at  = datetime('now') WHERE id = 'QR:TE:af0db08024b3dbe519cd3e88';
UPDATE qr_tafsir_entries SET content_ar = 'قرئ: حسنا، بضم الحاء وسكون السين. وبضمهما. وبفتحهما. وإحسانا. وكرها، بالفتح والضم، وهما لغتان في معنى المشقة، كالفقر والفقر. وانتصابه على الحال: أى: ذات كره. أو على أنه صفة للمصدر، أى: حملا ذا كره وَحَمْلُهُ وَفِصالُهُ ومدّة حمله وفصاله ثَلاثُونَ شَهْراً وهذا دليل على أن أقل الحمل ستة أشهر، لأن مدّة الرضاع إذا كانت حولين لقوله عز وجل حَوْلَيْنِ كامِلَيْنِ لِمَنْ أَرادَ أَنْ يُتِمَّ الرَّضاعَةَ بقيت للحمل ستة أشهر. وقرئ: وفصله. والفصل والفصال: كالفطم والفطام، بناء ومعنى. فإن قلت: المراد بيان مدّة الرضاع لا الفطام، فكيف عبر عنه بالفصال؟ قلت: لما كان الرضاع يليه الفصال ويلابسه لأنه ينتهى به ويتم: سمى فصالا، كما سمى المدّة بالأمد من قال: كل حى مستكمل مدّة العمر ... ومود إذا انتهى أمده [[تقدم شرح هذا الشاهد بالجزء الأول فراجعه إن شئت اه مصححه.]] وفيه فائدة وهي الدلالة على الرضاع التام المنتهى بالفصال ووقته. وقرئ: حتى إذا استوى وبلغ أشدّه. وبلوغ الأشد: أن يكتهل ويستوفى السنّ التي تستحكم فيها قوّته وعقله وتمييزه، وذلك إذا أناف على الثلاثين وناطح الأربعين. وعن قتادة: ثلاث وثلاثون سنة، ووجهه أن يكون ذلك أوّل الأشد، وغايته الأربعين. وقيل: لم يبعث نبىّ قط إلا بعد أربعين سنة. والمراد بالنعمة التي استوزع الشكر عليها: نعمة التوحيد والإسلام، وجمع بين شكرى النعمة عليه وعلى والديه، لأن النعمة عليهما نعمة عليه. وقيل في العمل المرضى: هو الصلوات الخمس. فإن قلت: ما معنى فِي في قوله وَأَصْلِحْ لِي فِي ذُرِّيَّتِي؟ قلت: معناه: أن يجعل ذرّيته موقعا للصلاح [[قال محمود: «فان قلت: ما معنى في هاهنا، وأجاب بأن المراد جعل ذريته ... الخ» قال أحمد: ومثله قوله تعالى إِلَّا الْمَوَدَّةَ فِي الْقُرْبى عدولا عن قوله: إلا مودة القربى. أو المودة للقربى، والله أعلم.]] ومظنة له كأنه قال: هب لي الصلاح في ذرّيتى وأوقعه فيهم ونحوه: يجرح في عراقيبها نصلى [[تقدم شرح هذا الشاهد بالجزء الثاني فراجعه إن شئت اه مصححه.]] مِنَ الْمُسْلِمِينَ من المخلصين. وقرئ: يتقبل، ويتجاوز، بفتح الياء، والضمير فيهما لله عز وجل. وقرئا بالنون. فإن قلت: ما معنى قوله فِي أَصْحابِ الْجَنَّةِ؟ قلت: هو نحو قولك: أكرمنى الأمير في ناس من أصحابه، تريد: أكرمنى في جملة من أكرم منهم، ونظمنى في عدادهم، ومحله النصب على الحال، على معنى: كائنين في أصحاب الجنة ومعدودين فيهم وَعْدَ الصِّدْقِ مصدر مؤكد، لأن قوله: يتقبل، ويتجاوز: وعد من الله لهم بالتقبل والتجاوز. وقيل: نزلت في أبى بكر رضى الله عنه وفي أبيه أبى قحافة وأمّه أم الخير وفي أولاده، واستجابة دعائه فيهم. وقيل: لم يكن أحد من الصحابة من المهاجرين منهم والأنصار أسلم هو ووالداه وبنوه وبناته غير أبى بكر.',     source_page = '277',     updated_at  = datetime('now') WHERE id = 'QR:TE:f06b8603b8131415d4fbb1b1';
UPDATE qr_tafsir_entries SET content_ar = 'فإن قلت: ما معنى قوله تعالى مَثَلُ الْجَنَّةِ الَّتِي وُعِدَ الْمُتَّقُونَ فِيها أَنْهارٌ كمن هو خالد في النار؟ قلت: هو كلام في صورة الإثبات ومعنى النفي والإنكار [[قال محمود: «هو كلام في صورة الإثبات ومعناه النفي ... الخ» قال أحمد: كم ذكر الناس في تأويل هذه الآية، فلم أر أطلى ولا أحلى من هذه النكت التي ذكرها، لا يعوزها إلا للتنبيه على أن في الكلام محذوفا لا بد من تقديره لأنه لا معادلة بين الجنة وبين الخالدين في النار إلا على تقدير مثل ساكن فيه يقوم وزن الكلام ويتعادل كفتاه. ومن هذا النمط قوله تعالى أَجَعَلْتُمْ سِقايَةَ الْحاجِّ وَعِمارَةَ الْمَسْجِدِ الْحَرامِ كَمَنْ آمَنَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ وَجاهَدَ فِي سَبِيلِ اللَّهِ فانه لا بد من تقدير محذوف مع الأول أو الثاني، ليتعادل القسمان، وبهذا الذي قدرته في الآية ينطبق آخر الكلام على أوله، فيكون المقصود تنظير بعد التسوية بين المتمسك بالسيئة والراكب للهوى ببعد التسوية بين المنعم في الجنة والمعذب في النار على الصفات المتقابلة المذكورة في الجهتين. وهو من وادى تنظير الشيء بنفسه، باعتبار حالتين إحداهما أوضح في البيان من الأخرى، فان المتمسك بالسنة هو المنعم في الجنة الموصوفة. والمتبع للهوى: هو المعذب في النار المنعوتة، ولكن أنكر التسوية بينهما باعتبار الأعمال أولا، وأوضح ذلك بإنكار التسوية بينهما باعتبار الأعمال أولا، وأوضح ذلك بإنكار التسوية بينهما باعتبار الجزاء ثانيا.]] ، لانطوائه تحت حكم كلام مصدّر بحرف الإنكار، ودخوله في حيزه، وانخراطه في سلكه، وهو قوله تعالى أَفَمَنْ كانَ عَلى بَيِّنَةٍ مِنْ رَبِّهِ كَمَنْ زُيِّنَ لَهُ سُوءُ عَمَلِهِ فكأنه قيل: أمثل الجنة كمن هو خالد في النار، أى كمثل جزاء من هو خالد في النار. فإن قلت: فلم عرّى في حرف الإنكار؟ وما فائدة التعرية؟ قلت: تعريته من حرف الإنكار فيها زيادة تصوير لمكابرة من يسوّى بين المتمسك بالبينة والتابع لهواه، وأنه بمنزلة من يثبت التسوية بين الجنة التي تجرى فيها تلك الأنهار، وبين النار التي يسقى أهلها الحميم. ونظيره قول القائل: أفرح أن أرزأ الكرام وأن ... أورث ذودا شصائصا نبلا [[تقدم شرح هذا الشاهد بالجزء الثالث فراجعه إن شئت اه مصححه.]] هو كلام منكر للفرح برزية الكرام ووراثة الذود، مع تعريه عن حرف الإنكار لانطوائه تحت حكم قول من قال: أتفرح بموت أخيك وبوراثة إبله، والذي طرح لأجله حرف الإنكار إرادة أن يصوّر قبح ما أزن به [[قوله «ما أزن» أى اتهم. أفاده الصحاح. (ع)]] فكأنه قال له: نعم مثلي يفرح بمرزاة الكرام وبأن يستبدل منهم ذودا يقل طائله [[قوله «يقل طائله» لأن الشصائص قليلات اللبن. والنبل: الكبار من الإبل، والصغار منها أيضا، فهو من الأضداد. أفاده الصحاح. (ع)]] ، وهو من التسليم الذي تحته كل إنكار، ومثل الجنة: صفة الجنة العجيبة الشأن، وهو مبتدأ، وخبره: كمن هو خالد. وقوله: فيها أنهار، داخل في حكم الصلة كالتكرير لها. ألا ترى إلى صحة قولك: التي فيها أنهار. ويجوز أن يكون خبر مبتدأ محذوف هي فيها [[قوله «هي فيها» لعله: أى هي فيها. (ع)]] أنهار، وكأن قائلا قال: وما مثلها؟ فقيل: فيها أنهار، وأن يكون في موضع الحال، أى: مستقرّة فيها أنهار، وفي قراءة على رضى الله عنه: أمثال الجنة، أى: ما صفاتها كصفات النار. وقرئ: أسن. يقال: أسن الماء وأجن: إذا تغير طعمه وريحه. وأنشد ليزيد بن معاوية: لقد سقتني رضابا غير ذى أسن ... كالمسك فتّ على ماء العناقيد [[ليزيد بن معاوية. وترضب الرجل ريق المرأة: إذا ترشفه. وأسن أسنا كتعب تعبا: تغير طعمه أو ريحه أو لونه. لطول مدته. يقول: سقتني ريقها الذي لم يتغير. وماء العناقيد: كناية عن الخمر، واستعاره لريقها على التصريحية، وناولتني المسك حال كونه تفتت على ريقها الشبيه بالخمر، أى: كأنه كذلك لطيبه. ويروى: كالمسك وهي الظاهرة، والتشبيه من قبيل تشبيه المفرد بالمركب، لأنه لا يريد تشبيه الرضاب بالمسك فقط.]] مِنْ لَبَنٍ لَمْ يَتَغَيَّرْ طَعْمُهُ كما تتغير ألبان الدنيا، فلا يعود قارصا ولا حاذرا [[قوله «ولا حاذرا ولا ما يكره» لعله محذوف، وأصله: حازر بالزاي، وفي الصحاح: الحاذر: اللبن الحامض]] ، ولا ما يكره من الطعوم لَذَّةٍ تأنيث لذّ، وهو اللذيذ، أو وصف بمصدر. وقرئ بالحركات الثلاث، فالجر على صفه الخمر، والرفع على صفة الأنهار، والنصب على العلة، أى: لأجل لذة الشاربين. والمعنى: ما هو إلا التلذذ الخالص، ليس معه ذهاب عقل ولا خمار ولا صداع، ولا آفة من آفات الخمر مُصَفًّى لم يخرج من بطون النحل فيخالطه الشمع وغيره ماءً حَمِيماً قيل إذا دنا منهم شوى وجوههم، وانمازت فروة رءوسهم، فإذا شربوه قطع أمعاءهم.',     source_page = '264',     updated_at  = datetime('now') WHERE id = 'QR:TE:964de9e351a11f6dd95af713';
UPDATE qr_tafsir_entries SET content_ar = 'إعادة النداء عليهم: استدعاء منهم لتجديد الاستبصار عند كل خطاب وارد، وتطرية الإنصات لكل حكم نازل، وتحريك منهم لئلا يفتروا ويغفلوا عن تأملهم وما أخذوا به عند حضور مجلس رسول الله ﷺ من الأدب الذي المحافظة عليه تعود عليهم بعظيم الجدوى في دينهم، وذلك لأنّ في إعظام صاحب الشرع إعظام ما ورد به، ومستعظم الحق لا يدعه استعظامه أن يألو عملا بما يحدوه [[قوله «بما يحدوه عليه» أى: يحضه. (ع)]] عليه، وارتداعا عما يصده عنه، وانتهاء إلى كل خير، والمراد بقوله لا تَرْفَعُوا أَصْواتَكُمْ فَوْقَ صَوْتِ النَّبِيِّ أنه إذا نطق ونطقتم فعليكم أن لا تبلغوا بأصواتكم وراء الحدّ الذي يبلغه بصوته، وأن تغضوا منها بحيث يكون كلامه عاليا لكلامكم، وجهره باهرا لجهركم، حتى تكون مزيته عليكم لائحة، وسابقته واضحة، وامتيازه عن جمهوركم كشية الأبلق [[قوله «كشية الأبلق» في الصحاح «الشية» : لون يخالف معظم لون الفرس وغيره. وفيه أيضا: اللغط الصوت والجلبة. وفيه الصخب: الصياح والجلبة. (ع)]] غير خاف، لا أن تغمروا صوته بلغطكم وتبهروا منطقه بصخبكم. وبقوله: ولا تجهروا له بالقول: إنكم إذا كلمتموه وهو صامت فإياكم والعدول عما نهيتم عنه من رفع الصوت، بل عليكم أن لا تبلغوا به الجهر الدائر بينكم، وأن تتعمدوا في مخاطبته القول اللين المقرّب من الهمس الذي يضادّ الجهر، كما تكون مخاطبة المهيب المعظم، عاملين بقوله عز اسمه وَتُعَزِّرُوهُ وَتُوَقِّرُوهُ وقيل معنى وَلا تَجْهَرُوا لَهُ بِالْقَوْلِ كَجَهْرِ بَعْضِكُمْ لِبَعْضٍ لا تقولوا له: يا محمد، يا أحمد، وخاطبوه بالنبوّة. قال ابن عباس: لما نزلت هذه الآية قال أبو بكر رضى الله عنه: يا رسول الله، والله لا أكلمك إلا السرار أو أخا السرار حتى ألقى الله، [[ذكره الواحدي عن عطاء عن ابن عباس. ولم يسق سنده إليه. وأخرجه البزار وابن مردويه من طريق طارق بن شهاب عن أبى بكر. قال لما نزل يا أَيُّهَا الَّذِينَ آمَنُوا لا تَرْفَعُوا أَصْواتَكُمْ فَوْقَ صَوْتِ النَّبِيِّ قلت: يا رسول الله آليت ألا أكلمك إلا كأخى السرار حتى ألقى الله» وأخرجه الحاكم والبيهقي في المدخل من حديث أبى هريرة. قال «لما نزلت إِنَّ الَّذِينَ يَغُضُّونَ- الآية قال أبو بكر. والذي أنزل عليك الكتاب يا رسول الله لا أكلمك إلا كأخى السرار حتى ألقى الله عز وجل «وقال صحيح على شرط مسلم]] وعن عمر رضى الله عنه: انه كان يكلم النبي ﷺ كأخى السرار لا يسمعه حتى يستفهمه [[أخرجه البخاري من حديث أبى الزبير. قال «لما نزلت يا أَيُّهَا الَّذِينَ آمَنُوا لا تَرْفَعُوا أَصْواتَكُمْ فَوْقَ صَوْتِ النَّبِيِّ- الآية كان عمر بعد ذلك إذا حدث النبي ﷺ حدثه كأخى السرار. لم يسمعه حتى يستفهمه.]] ، وكان أبو بكر إذا قدم على رسول الله ﷺ وفد: أرسل إليهم من يعلمهم كيف يسلمون ويأمرهم بالسكينة والوقار عند رسول الله ﷺ، [[لم أجده]] وليس الغرض برفع الصوت ولا الجهر: ما يقصد به الاستخفاف والاستهانة، لأنّ ذلك كفر، والمخاطبون مؤمنون، وإنما الغرض صوت هو في نفسه والمسموع من جرسه غير مناسب لما يهاب به العظماء ويوقر الكبراء، فيتكلف الغض منه، وردّه إلى حدّ يميل به إلى ما يستبين فيه المأمور به من التعزير والتوقير، ولم يتناول النهى أيضا رفع الصوت الذي لا يتأذى به رسول الله ﷺ، وهو ما كان منهم في حرب أو مجادلة معاند أو إرهاب عدوّ أو ما أشبه ذلك، ففي الحديث: أنه قال عليه الصلاة والسلام للعباس بن عبد المطلب لما انهزم الناس يوم حنين: «اصرخ بالناس [[لم أجده، وقد تقدم أن ذلك كان يوم حنين، والعباس لم يشهد أحدا.]] » وكان العباس أجهر الناس صوتا [[لم أجده]] . يروى: أنّ غارة أتتهم يوما فصاح العباس يا صباحاه، فأسقطت الحوامل لشدّة صوته [[لم أجده]] . وفيه يقول نابغة بنى جعدة: زجر أبى عروة السّباع إذا ... أشفق أن يختلطن بالغنم [[تقدم شرح هذا الشاهد بهذا الجزء فراجعه إن شئت اه مصححه.]] زعمت الرواة أنه كان يزجر السباع عن الغنم فيفتق مرارة السبع في جوفه [[لم أجده]] . وفي قراءة ابن مسعود: لا ترفعوا بأصواتكم والباء مزيدة محذوّ بها حذو التشديد في قول الأعلم الهذلي: رفعت عينى بالحجا ... ز إلى أناس بالمناقب [[للأعلم الهذلي، يقول: نظرت وأنا في الحجاز إلى من في المناقب. وهذان الموضعان بينهما مسافة بعيدة، وهذا من شدة الشوق إلى من في المناقب.]] وليس المعنى في هذه القراءة أنهم نهوا عن الرفع الشديد، تخيلا أن يكون ما دون الشديد مسوغا لهم، ولكن المعنى نهيهم عما كانوا عليه من الجلبة، واستجفاؤهم فيما كانوا يفعلون. وعن ابن عباس: نزلت في ثابت بن قيس بن شماس، وكان في أذنه وقر، وكان جهوري الصوت، فكان إذا تكلم رفع صوته، وربما كان يكلم رسول الله ﷺ فيتأذى بصوته [[لم أجده]] . وعن أنس أن هذه الآية لما نزلت: فقد ثابت، فتفقده رسول الله ﷺ فأخبر بشأنه، فدعاه، فسأله فقال: يا رسول الله، لقد أنزلت إليك هذه الآية، وإنى رجل جهير الصوت. فأخاف أن يكون عملى قد حبط، فقال له رسول الله ﷺ: لست هناك، إنك تعيش بخير وتموت بخير، وإنك من أهل الجنة [[متفق عليه من حديث أنس دون قوله «لست هناك، وزاد أحمد والطبراني فيه: فقال أنس: فكنا نراه يمشى بين أظهرنا ونحن نعلم أنه من أهل الجنة» .]] .. وأمّا ما يروى عن الحسن: أنها نزلت فيمن كان يرفع صوته من المنافقين فوق صوت رسول الله ﷺ، فمحمله والخطاب للمؤمنين: على أن ينهى المؤمنون ليندرج المنافقون تحت النهى، ليكون الأمر أغلظ عليهم وأشق. وقيل: كان المنافقون يرفعون أصواتهم ليظهروا قلة مبالاتهم، فيقتدى بهم ضعفة المسلمين. وكاف التشبيه في محل النصب، أى: لا تجهروا له جهرا مثل جهر بعضكم لبعض. وفي هذا: أنهم لم ينهوا عن الجهر مطلقا، حتى لا يسوغ لهم أن يكلموه إلا بالهمس والمخافتة، وإنما نهوا عن جهر مخصوص مقيد بصفة، أعنى: الجهر المنعوت بمماثلة ما قد اعتادوه منهم فيما بينهم، وهو الخلو من مراعاة أبهة النبوّة وجلالة مقدارها، وانحطاط سائر الرتب وإن جلت عن رتبتها أَنْ تَحْبَطَ أَعْمالُكُمْ منصوب الموضع، على أنه مفعول له، وفي متعلقه وجهان، أحدهما: أن يتعلق بمعنى النهى، فيكون المعنى: انتهوا عما نهيتم عنه لحبوط أعمالكم، أى: لخشية حبوطها على تقدير حذف المضاف، كقوله تعالى يُبَيِّنُ اللَّهُ لَكُمْ أَنْ تَضِلُّوا والثاني: أن يتعلق بنفس الفعل، ويكون المعنى: أنهم نهوا عن الفعل الذي فعلوه لأجل الحبوط، لأنه لما كان بصدد الأداء إلى الحبوط: جعل كأنه فعل لأجله، وكأنه العلة والسبب في إيجاده على سبيل التمثيل، كقوله تعالى لِيَكُونَ لَهُمْ عَدُوًّا. فإن قلت: لخص الفرق بين الوجهين. قلت: تلخيصه أن يقدر الفعل في الثاني مضموما إليه المفعول له، كأنهما شيء واحد [[قال محمود: «إنه مفعول له ومتعلقه إما معنى النهى، كأنه قال: انتهوا كراهية حبوط أعمالكم على حذف مضاف، كقوله يُبَيِّنُ اللَّهُ لَكُمْ أَنْ تَضِلُّوا وأما نفس الفعل فهو المنهي عنه، على معنى تنزيل صيرورة الجهر المنهي عنه إلى الحبوط. منزلة جعل الحبوط علة في الجهر على التمثيل، من وادى لِيَكُونَ لَهُمْ عَدُوًّا وَحَزَناً قال: وتلخيص الفرق بينهما أنه على الثاني يقدر انضمام المفعول من أجله إلى الفعل الأول ... الخ» قال أحمد: هو يحوم على شرعة وبيئة إياك. ورودها: وذلك أنه يعتقد أن ما دون الكفر ولو كبيرة واحدة تحبط العمل وتوجب الخلود في العذاب المقيم، وتخرج المؤمن من اسم الايمان ورسمه، ومعاذ الله من هذا المعتقد، فعليك بعقيدة أهل السنة الممهدة في مواضع من هذا المجموع، فجدد العهد بها: وهي اعتقاد أن المؤمن لا يخلد في النار، وأن الجنة له بوعد الله حتم ولو كانت خطاياه ما دون الشرك أو ما يؤدى إليه كزبد البحر، وأنه لا تحبط حسنة سيئة طارئة كائنة ما كانت سوى الشرك. والزمخشري اغتنم الفرصة في ظاهر هذه الآية فنزلها على معتقده ووجه ظهورها فيما يدعيه: أن رفع الصوت بين يدي رسول الله ﷺ معصية لا تبلغ الشرك، وقد أخاف الله عباده من إحباطه الأعمال بها، ولو كان الإحباط مقطوعا بنفيه: لم تستقم الاخافة به، وأنى له أن يبلغ من ذلك آماله، ونظم الكلام يأباه عنده البصر بمعناه، فنقول: المراد في الآية النهى عن رفع الصوت على الإطلاق، ومعلوم أن حكم النهي: الحذر مما يتوقع في ذلك من إيذاء النبي عليه السلام، والقاعدة المختارة أن إيذاءه عليه الصلاة والسلام يبلغ مبلغ الكفر المحبط للعمل باتفاق، فورد النهى عما هو مظنة لأذى النبي عليه الصلاة والسلام سواء وجد هذا المعنى أولا، حماية للذريعة وحسما للمادة، ثم لما كان هذا المنهي عنه وهو رفع الصوت منقسما إلى ما يبلغ ذلك المبلغ أولا، ولا دليل يميز أحد القسمين عن الآخر: لزم المكلف أن يكف عن ذلك مطلقا، وخوف أن يقع فيهما هو محبط للعمل، وهو البالغ حد الإيذاء، إذ لا دليل ظاهر يميزه، وإن كان فلا يتفق تمييزه في كثير من الأحيان، وإلى التباس أحد القسمين بالآخر وقعت الاشارة بقوله أَنْ تَحْبَطَ أَعْمالُكُمْ وَأَنْتُمْ لا تَشْعُرُونَ وإلا فلو كان الأمر على ما يعتقده الزمخشري: لم يكن لقوله وَأَنْتُمْ لا تَشْعُرُونَ موقع، إذ الأمر بين أن يكون رفع الصوت مؤذيا فيكون كفرا محبطا قطعا، وبين أن يكون غير مؤذ فيكون كبيرة محبطة، على رأيه قطعا، فعلى كلا حاليه الإحباط به محقق، إذا فلا موقع لادعام الكلام بعدم الشعور، مع أن الإحباط ثابت مطلقا، والله أعلم وهذا التقرير الذي ذكرته يدور على مقدمتين كلتا هما صحيحة إحداهما: أن رفع الصوت من جنس ما يحصل به الإيذاء، وهذا أمر يشهد به النقل والمشاهدة الآن، حتى إن الشيخ ليتأذى برفع التلميذ صوته بين يديه، فكيف برتبة النبوة وما يستحقه من الإجلال والإعظام. المقدمة الأخرى: أن إيذاء النبي ﷺ كفر، وهذا أمر ثابت قد نص عليه أئمتنا وأفتوا بقتل من تعرض لذلك كفرا، ولا تقبل توبته، فما أتاه أعظم عند الله وأكبر، والله الموفق.]] ، ثم يصب النهى عليهما جميعا صبا. وفي الأوّل يقدر النهى موجها على الفعل على حياله، ثم يعلل له منهيا عنه. فإن قلت: بأى النهيين تعلق المفعول له؟ قلت: بالثاني عند البصريين، مقدرا إضماره عند الأوّل، كقوله تعالى آتُونِي أُفْرِغْ عَلَيْهِ قِطْراً وبالعكس عند الكوفيين، وأيهما كان فمرجع المعنى إلى أنّ الرفع والجهر كلاهما منصوص أداؤه إلى حبوط العمل: وقراءة ابن مسعود: فتحبط أعمالكم، أظهر نصا بذلك، لأنّ ما بعد الفاء لا يكون إلا مسببا عما قبله، فيتنزل الحبوط من الجهر منزلة الحلول من الطغيان في قوله تعالى فَيَحِلَّ عَلَيْكُمْ غَضَبِي والحبوط من حبطت الإبل: إذا أكلت الخضر فنفخ بطونها، وربما هلكت. ومنه قوله عليه الصلاة والسلام «وإن مما ينبت الربيع لما يقتل حبطا أو يلم» [[أخرجه مسلم وغيره.]] ومن أخواته: حبجت الإبل، إذا أكلت العرفج [[قوله «إذا أكلت العرفج» في الصحاح: شجر ينبت في السهل، الواحدة: عرفجة. (ع)]] فأصابها ذلك. وأحبض عمله: مثل أحبطه. وحبط الجرح وحبر: إذا غفر، وهو نكسه وتراميه إلى الفساد: جعل العمل السيئ في إضراره بالعمل الصالح كالداء والحرض [[قوله «كالداء والحرض» أى الفساد. أفاده الصحاح.]] لمن يصاب به، أعاذنا الله من حبط الأعمال وخيبة الآمال. وقد دلت الآية على أمرين هائلين، أحدهما: أن فيما يرتكب من يؤمن من الآثام ما يحبط عمله. والثاني: أن في آثامه ما لا يدرى أنه محبط، ولعله عند الله كذلك، فعلى المؤمن أن يكون في تقواه كالماشى في طريق شائك لا يزال يحترز ويتوقى ويتحفظ.',     source_page = '38',     updated_at  = datetime('now') WHERE id = 'QR:TE:9575c8ef83cdcd9a7032574b';
UPDATE qr_tafsir_entries SET content_ar = 'بعث رسول الله ﷺ الوليد بن عقبة أخا عثمان لأمّه- وهو الذي ولاه عثمان الكوفة بعد سعد بن أبى وقاص، فصلى بالناس وهو سكران صلاة الفجر أربعا، ثم قال: هل أزيدكم، فعزله عثمان [[أخرجه مسلم من طريق أبى ساسان حصين بن منذر قال شهدت عثمان أخى الوليد بن عقبة وقد صلى الغداة بالكوفة أربعا- الحديث بطوله» وأخرجه ابن إسحاق والنسائي من هذا الوجه وقالوا فيه «وقد صلى للغداة أربعا»]] عنهم- مصدّقا إلى بنى المصطلق، وكانت بينه وبينهم إحقة، فلما شارف ديارهم ركبوا مستقبلين له، فحسبهم مقاتليه، فرجع وقال لرسول الله ﷺ: قد ارتدوا ومنعوا الزكاة [[أخرجه إسحاق والطبراني من حديث أم سلمة. دون قوله «فاتهمهم فقال لتنتهن أو لأبعثن إليكم رجلا هو عندي كنفسي يقاتل مقاتلتكم الخ» وعندهما بدل ذلك «فما زالوا يعتذرون إليه حتى نزلت فيهم الآية» وفيه موسى بن عبيدة، وهو ضعيف ونحوه رواه أحمد والطبراني أيضا من حديث الحارث بن دثار الخزاعي أخرجه ابن مردويه من طريق عبد الله بن عبد القدوس عن الأعمش عن موسى بن المسيب عن سالم بن أبى الجعد. عن جابر قال: بعث رسول الله ﷺ الوليد بن عقبة- فذكر الحديث بنحوه وزاد فقال عليه الصلاة والسلام: لتنتهن أو لأبعثن إليكم رجلا- فذكره.]] ، فغضب رسول الله ﷺ وهمّ أن يغزوهم، فبلغ القوم فوردوا وقالوا: نعوذ بالله من غضبه وغضب رسوله، فاتهمهم فقال: «لتنتهنّ أو لأبعثنّ إليكم رجلا هو عندي كنفسي يقاتل مقاتلتكم ويسبى ذراريكم» ثم ضرب بيده على كتف على رضى الله عنه. وقيل: بعث إليهم خالد بن الوليد فوجدهم منادين بالصلوات متهجدين، فسلموا إليه الصدقات [[لم أره.]] ، فرجع. وفي تنكير الفاسق والنبأ: شياع في الفساق والأنباء، كأنه قال: أىّ فاسق جاءكم بأىّ نبإ [[قال محمود: «نكر فاسقا ونبأ لقصد الشياع، فكأنه قيل أىّ فاسق جاء بأى نبأ» قال أحمد: تسامح بلفظ الشياع والمراد الشمول، لأن النكرة إذا وقعت في سياق الشرط تعم، كما إذا وقعت في سياق النفي، والله أعلم.]] . فتوقفوا فيه وتطلبوا بيان الأمر وانكشاف الحقيقة، ولا تعتمدوا قول الفاسق «لأنّ من لا يتحامى جنس الفسوق لا يتحامى الكذب الذي هو نوع منه. والفسوق: الخروج من الشيء والانسلاخ منه. يقال: فسقت الرطبة عن قشرها. ومن مقلوبه: قفست البيضة، إذا كسرتها وأخرجت ما فيها. ومن مقلوبه أيضا: قفست الشيء إذا أخرجته عن يد مالكه مغتصبا له عليه، ثم استعمل في الخروج عن القصد والانسلاخ من الحق. قال رؤبة: فواسقا عن قصدها جوائرا [[تقدم شرح هذا الشاهد بالجزء الأول فراجعه إن شئت اه مصححه.]] وقرأ ابن مسعود: فتثبتوا. والتثبت والتبين: متقاربان، وهما طلب الثبات والبيان والتعرّف، ولما كان رسول الله صلى الله تعالى عليه وآله وسلم والذين معه بالمنزلة التي لا يجسر أحد أن يخبرهم بكذب، وما كان يقع مثل ما فرط من الوليد إلا في الندرة. قيل: إن جاءكم بحرف الشك وفيه أنّ على المؤمنين أن يكونوا على هذه الصفة، لئلا يطمع فاسق في مخاطبتهم بكلمة زور أَنْ تُصِيبُوا مفعول له، أى: كراهة إصابتكم قَوْماً بِجَهالَةٍ حال، كقوله تعالى وَرَدَّ اللَّهُ الَّذِينَ كَفَرُوا بِغَيْظِهِمْ يعنى جاهلين بحقيقة الأمر وكنه القصة. والإصباح: بمعنى الصيرورة. والندم: ضرب من الغم، وهو: أن تغتمّ على ما وقع منك تتمنى أنه لم يقع، وهو غم يصحب الإنسان صحبة لها دوام ولزام، لأنه كلما تذكر المتندّم عليه راجعه من الندام: وهو لزام الشريب ودوام صحبته. ومن مقلوباته: أدمن الأمر أدامه. ومدن بالمكان: أقام به. ومنه: المدينة وقد تراهم يجعلون الهم صاحبا ونجيا وسميرا وضجيعا، وموصوفا بأنه لا يفارق صاحبه. الجملة المصدّرة بلو لا تكون كلاما مستأنفا، لأدائه إلى تنافر النظم [[قال محمود: «الجملة المصدرة بلو لا تكون مستأنفة، لأدائه إلى تنافر النظم ... الخ» قال أحمد: من جملة هنات المعتزلة: ثلبهم على عثمان رضى الله عنه ووقوفهم عن الحكم بتعنيف قتلته، فضم إلى هذا المعتقد غير معرج عليه: ما أورده الزمخشري في هذا الموضع من حكايات تولية عثمان لأخيه الوليد الفاعل تلك الفعلة الشنعاء عوضا عن سعد بن أبى وقاص أحد الصحابة، وما عرض به من أن بعض الصحابة كان يصدر منهم هنات، فمنها مطالبتهم النبي ﷺ باتباع آرائهم التي من جملتها تصديق الوليد في الإيقاع ببني المصطلق، فإذا ضممت هذه النبذة التي ذكرها إرسالا إلى ما علمت من معتقده: تبين لك من حال- أعنى الزمخشري- ما لا أطيق التصريح به، لأنه لم يصرح وإنما سلكنا معه سبيل الانصاف ومحجة الانتصاف: نص بنص، وتلويح بتلويح، فنسأل الله العظيم- بعد الصلاة على نبيه محمد خاتم النبيين- أن يرضى عن أصحابه أجمعين، وعنا بهم آمين.]] ، ولكن متصلا بما قبله حالا من أحد الضميرين في فيكم المستتر المرفوع، أو البارز المجرور. وكلاهما مذهب سديد. والمعنى: أن فيكم رسول الله على حالة يجب عليكم تغييرها. أو أنتم على حالة يجب عليكم تغييرها: وهي أنكم تحاولون منه أن يعمل في الحوادث على مقتضى ما يعنّ لكم من رأى، واستصواب فعل المطواع لغيره التابع له فيما يرتئيه، المحتذى على أمثلته، ولو فعل ذلك لَعَنِتُّمْ أى لوقعتم في العنت والهلاك. يقال: فلان يتعنت فلانا، أى: يطلب ما يؤدّيه إلى الهلاك. وقد أعنت العظم: إذا هيض [[قوله «إذا هيض بعد الجبر» في الصحاح: هاض العظم يهيضه هيضا: كسره بعد الجبر. وفيه أيضا: جبرت العظم جبرا، وجبر العظم بنفسه جبورا، أى: انجبر. (ع)]] بعد الجبر. وهذا يدل على أن بعض المؤمنين زينوا لرسول الله ﷺ الإيقاع ببني المصطلق وتصديق قول الوليد. وأن نظائر ذلك من الهنات كانت تفرط منهم، وأن بعضهم كانوا يتصوّنون ويزعهم جدّهم في التقوى عن الجسارة على ذلك، وهم الذين استثناهم بقوله تعالى وَلكِنَّ اللَّهَ حَبَّبَ إِلَيْكُمُ الْإِيمانَ أى إلى بعضكم، ولكنه أغنت عن ذكر البعض: صفتهم المفارقة لصفة غيرهم، وهذا من إيجازات القرآن ولمحاته اللطيفة، التي لا يفطن لها إلا الخواص. وعن بعض المفسرين: هم الذين امتحن الله قلوبهم للتقوى. وقوله أُولئِكَ هُمُ الرَّاشِدُونَ والخطاب لرسول الله ﷺ، أى: أولئك المستثنون هم الراشدون يصدق ما قلته. فإن قلت: ما فائدة تقديم خبر إن على اسمها؟ قلت: القصد إلى توبيخ بعض المؤمنين على ما استهجن الله منهم من استتباع رأى رسول الله ﷺ لآرائهم، فوجب تقديمه لانصباب الغرض إليه. فإن قلت: فلم قيل يُطِيعُكُمْ دون: أطاعكم؟ قلت: للدلالة على أنه كان في إرادتهم استمرار عمله على ما يستصوبونه. وأنه كلما عنّ لهم رأى في أمر كان معمولا عليه، بدليل قوله فِي كَثِيرٍ مِنَ الْأَمْرِ كقولك: فلان يقرى الضيف ويحمى الحريم، تريد: أنه مما اعتاده ووجد منه مستمرّا. فإن قلت: كيف موقع لكِنْ وشريطتها مفقودة: من مخالفة ما بعدها لما قبلها نفيا وإثباتا؟ قلت: هي مفقودة من حيث اللفظ، حاصلة من حيث المعنى لأن الذين حبب إليهم الإيمان قد غايرت صفتهم صفة المتقدّم ذكرهم، فوقعت، لكنّ في حاق موقعها من الاستدراك. ومعنى تحبيب الله وتكريهه اللطف والإمداد بالتوفاق [[عاد كلامه. قال: «ومعنى تحبيب الله وتكريهه اللطف والامداد بالتوفيق ... الخ» قال أحمد: تلجلج والحق أبلج، وزاغ والسبيل منهج، وقاس الخلق بالواحد الحق، وجعل أفعالهم لهم من إيمان وكفر وخير وشر، اغترارا بحال اعتقد اطراده في الشاهد، وهو أن الإنسان لا يمدح بفعل غيره، وقاس الغائب على الشاهد تحكما، وتغلغل باتباع هوى معجما، فجره ذلك بل جرأه على تأويل الآية وإبطال ما ذكرته من نسبة تحبيب الايمان إلى الله تعالى على حقيقته، وجعله مجازا لأنه يعتقد أنها لو بقيت على ظاهرها لكان خلق الايمان مضافا إلى الله تعالى، والعبد إذا ممدوح بما ليس من فعله. وهذا عنده محال، فأتبع الآية رأيه الفاسد، فإذا عرضت عليه الأدلة العقلية على الوحدانية، والنقلية على أنه لا خالق إلا الله خالق كل شيء، وطولب بابقاء الآية على ظاهرها المؤيد بالعقل والنقل، فانه يتمسك في تأويلها بالحبال المذكورة في التحكم بقياس الغائب على الشاهد، مما له إدلاء إلى تعويج كتاب الله الذي لا يأتيه الباطل من بين يديه ولا من خلفه، فالذي نعتقده- ثبتنا الله على الحق- أن الله تعالى منح ومدح وأعطى وامتن، فلا موجود إلا الله وصفاته وأفعاله، غير أنه تعالى جعل أفعاله بعضها محلا لبعض، فسمى المحل فاعلا والحال فعلا، فهذا هو التوحيد الذي لا محيص عنه للمؤمن ولا محيد، ولا بد أن أطارحه القول فأقول: أخبرنى عن ثناء الله على أنبيائه ورسله بما حاصله اصطفاؤه لهم لاختياره إياهم: هل بمكتسب أم بغير مكتسب، فلا يسعه أن يقول إلا أنه أثنى عليهم بما لم يكتسبوه، بل بما وهبه إياهم فاتهبوه. وإن عرج على القسم الآخر وهو دعوى أنهم أثنى عليهم بمكتسب لهم من رسالة أو نبوة، فقد خرج عن أهل الملة، وانحرف عن أهل القبلة، وهذه البذة كفاية إن شاء الله تعالى.]] ، وسبيله الكناية كما سبق، وكل ذى لب وراجع إلى بصيرة وذهن لا يغبى عليه أن الرجل لا يمدح بغير فعله، وحمل الآية على ظاهرها يؤدّى إلى أن يثنى عليهم بفعل الله، وقد نفى الله هذا عن الذين أنزل فيهم وَيُحِبُّونَ أَنْ يُحْمَدُوا بِما لَمْ يَفْعَلُوا فإن قلت: فإنّ العرب تمدح بالجمال وحسن الوجوه، وذلك فعل الله، وهو مدح مقبول عند الناس غير مردود. قلت: الذي سوّغ ذلك لهم أنهم رأوا حسن الرواء [[قوله «حسن الرواء» في الصحاح: الرواء- بالضم-: المنظر. (ع)]] وو سامة المنظر في الغالب، يسفر عن مخبر مرضى وأخلاق محمودة ومن ثم قالوا: أحسن ما في الدميم وجهه [[قوله «ما في الدميم وجهه» في الصحاح «الدميم» : القبيح. (ع)]] ، فلم يجعلوه من صفات المدح لذاته، ولكن لدلالته على غيره. على أن من محققة الثقات وعلماء المعاني من دفع صحة ذلك وخطأ المادح به، وقصر المدح على النعت بأمّهات الخير: وهي الفصاحة والشجاعة والعدل والعفة، وما يتشعب منها ويرجع إليها، وجعل الوصف بالجمال والثروة وكثرة الحفدة والأعضاد وغير ذلك مما ليس للإنسان فيه عمل غلطا ومخالفة عن المعقول والْكُفْرَ تغطية نعم الله تعالى وغمطها بالجحود. والْفُسُوقَ الخروج عن قصد الإيمان ومحجته بركوب الكبائر وَالْعِصْيانَ ترك الانقياد والمضي لما أمر به الشارع. والعرق العاصي: العانذ [[قوله «والعرق العاصي: العانذ» في الصحاح: عنذ العرق: سال ولم يرقأ، فهو عرق عانذ. (ع)]] . واعتصت النواة: اشتدّت. والرشد: الاستقامة على طريق الحق مع تصلب فيه من الرشادة وهي الصخرة: قال أبو الوازع: كل صخرة رشادة. وأنشد: وغير مقلّد وموشّمات ... صلين الضّوء من صمّ الرّشاد [[الظاهر أن الشاعر يصف الديار بأنها لم يبق فيها غير وتد الخباء المقلد بالحبل، وغير الأثافى المغير لونها بالنار. والوشم والتوشيم: تغيير اللون، أى: التي احترقت بضوءها أى حرها. ومن صم الرشاد: بيان لها. والصم: جمع صماء، أى: صلبة. والرشاد الصخر. واحدة رشادة. وقيل: يصف مطايا بأنها مطبوعة على العمل غير محتاجة الزمام، وأنها غيرها أثر السير قوية، بحيث يظهر الشرر من شدة وقع خفافها على الصخر الصلب.]] وفَضْلًا مفعول له، أو مصدر من غير فعله [[أعرب الزمخشري فضلا في الآية مفعولا لأجله، منصبا عن قوله: الراشدون ... الخ. قال أحمد: أورد الاشكال بعد تقرير أن الرشد ليس من فعل الله تعالى، وإنما هو فعلهم حقيقة على ما هو معتقده، ونحن بنينا على ما بينا: أن الرشد من أفعال الله ومخلوقاته، فقد وجد شرط انتصاب المفعول له، وهو اتحاد فاعل الفعلين، على أن الاشكال وارد نصا على تقريرنا على غير الحد الذي أورده عليه الزمخشري، بل من جهة أن الله تعالى خاطب خلقه بلغتهم المعهودة عندهم. ومما يعهدونه أن الفاعل من نسب إليه الفعل، وسواء كان ذلك حقيقة أو مجازا حتى يكون زبد فاعلا وانقض الحائط وأشباهه كذلك. وقد نسب الرشد إليهم على طريقة أنهم الفاعلون وإن كانت النسبة مجازية باعتبار المعتقد، وإذا تقرر وروده على هذا الوجه فلك في الجواب عنه طريقان: إما جواب الزمخشري، وإما أمكن منه وأبين: وهو أن الرشد هنا يستلزم كونه راشدا، إذ هو مطاوعه، لأن الله تعالى أرشدهم فرشدوا. وحينئذ يتحد الفاعل على طريقة الصناعة المطابقة للحقيقة وهو عكس قوله يُرِيكُمُ الْبَرْقَ خَوْفاً وَطَمَعاً فان الاشكال بعينه وارد فيها، إذ الخوف والطمع فعلهم، أى: منسوب إليهم على طريقة أنهم الخانفون الطامعون، والفعل الأول لله تعالى، لأنه مريهم ذلك، والجواب عنه: أنهم مفعولون في معنى الفاعلين، بواسطة استلزام المطاوعة، لأنه إذا أراهم فقد رأوا. وقد سلف هذا الجواب مكانه، فصححت الكلام هاهنا بتقدير المفعول فاعلا وعكسه آية الحجرات، إذ تصحيح الكلام فيها بتقدير الفاعل مفعولا، وهذا من دقائق العربية فتأمله، والله الموفق.]] . فإن قلت: من أين جاز وقوعه مفعولا له، والرشد فعل القوم، والفضل فعل الله تعالى، والشرط أن يتحد الفاعل. قلت: لما وقع الرشد عبارة عن التحبيب والتزيين والتكريه، مسندة إلى اسمه تقدست أسماؤه: صار الرشد كأنه فعله، فجاز أن ينتصب عنه أو لا ينتصب عن الراشدون، ولكن عن الفعل المسند إلى اسم الله تعالى، والجملة التي هي أُولئِكَ هُمُ الرَّاشِدُونَ اعتراض. أو عن فعل مقدر، كأنه قيل: جرى ذلك، أو كان ذلك فضلا من الله. وأما كونه مصدرا من غير فعله، فأن يوضع موضع رشدا، لأنّ رشدهم فضل من الله لكونهم موفقين فيه، والفضل والنعمة بمعنى الإفضال والإنعام وَاللَّهُ عَلِيمٌ بأحوال المؤمنين وما بينهم من التمايز والتفاضل حَكِيمٌ حين يفضل وينعم بالتوفيق على أفاضلهم.',     source_page = '119',     updated_at  = datetime('now') WHERE id = 'QR:TE:552d17ef74a8fbc0f3dc3240';
UPDATE qr_tafsir_entries SET content_ar = 'صَدُقاتِهِنَّ مهورهن، وفي حديث شريح: قضى ابن عباس لها بالصدقة. وقرئ: (صَدُقاتِهِنَّ) بفتح الصاد وسكون الدال على تخفيف صدقاتهن. وصدقاتهن بضم الصاد وسكون الدال جمع صدقة بوزن غرفة. وقرئ: صدقتهن، بضم الصاد والدال على التوحيد، وهو تثقيل صدقة، كقولك في ظلمة ظلمة نِحْلَةً من نحله كذا إذا أعطاه إياه ووهبه له عن طيبة من نفسه نحلة ونحلا. ومنه حديث أبى بكر رضى اللَّه عنه: إنى كنت نحلتك جداد عشرين وسقا بالعالية [[أخرجه مالك بإسناد صحيح أتم منه.]] . وانتصابها على المصدر [[قال محمود: «نحلة منصوب على المصدر لأنها في معنى الإيتاء ... الخ» قال أحمد: هذا الفصل بجملته حسن جداً، غير أن في جملة تذكير الضمير في منه على الصداق، ثم تنظيره ذلك بقوله «فأصدق نظراً» وذلك أن المراعى ثم الأصل، وهو عدم دخول الفاء والجزم وتقدير ما هو الأصل، وإعطاؤه حكم الموجود ليس ببدع، ولا كذلك إفراد الصداق المقدر، فانه ليس بأصل الكلام، بل الأصل الجمع: وأما الافراد فقد يأتى في مثله على سبيل الاختصار استغناء عن الجمع بالاضافة، ولا يرد أنهم قد راعوا ما ليس بأصل في قوله: بدا لي أنى لست مدرك ما مضى ... ولا سابق شيئا إذا كان جائيا لأن دخول الباء وإن لم يكن أصلا، إلا أنها قد توطنت بهذا الموضوع وكثر حلولها فيه، فصارت كأن الأصل دخولها في الخبر، واللَّه أعلم. والأمر في ذلك قريب]] لأن النحلة والإيتاء بمعنى الإعطاء فكأنه قيل: وانحلوا النساء صدقاتهن نحلة، أى أعطوهنّ مهورهنّ عن طيبة أنفسكم، أو على الحال من المخاطبين، أى آتوهنّ صدقاتهن ناحلين طيبي النفوس بالإعطاء، أو من الصدقات، أى منحولة معطاة عن طيبة الأنفس. وقيل: نحلة من اللَّه عطية من عنده وتفضلا منه عليهن، وقيل: النحلة الملة، ونحلة الإسلام خير النحل. وفلان ينتحل كذا: أى يدين به. والمعنى: آتوهن مهورهن ديانة، على أنها مفعول لها. ويجوز أن يكون حالا من الصدقات، أى دينا من اللَّه شرعه وفرضه. والخطاب للأزواج. وقيل: للأولياء، لأنهم كانوا يأخذون مهور بناتهم، وكانوا يقولون: هنيئا لك النافجة، لمن تولد له بنت، يعنون: تأخذ مهرها فتنفج به مالك أى تعظمه. الضمير في: (مِنْهُ) جار مجرى اسم الإشارة كأنه قيل عن شيء من ذلك، كما قال اللَّه تعالى: (قُلْ أَأُنَبِّئُكُمْ بِخَيْرٍ مِنْ ذلِكُمْ) بعد ذكر الشهوات، ومن الحجج المسموعة من أفواه العرب ما روى عن رؤبة أنه قيل له في قوله: كَأنَّهُ فِى الْجِلدِ تَوْلِيعُ الْبَهَقْ [[مر شرح هذا الشاهد ب من هذا الجزء فراجعه إن شئت اه مصححه]] فقال: أردت كأن ذاك. أو يرجع إلى ما هو في معنى الصدقات وهو الصداق، لأنك لو قلت: وآتوا النساء صداقهن، لم تخل بالمعنى، فهو نحو قوله: (فَأَصَّدَّقَ وَأَكُنْ مِنَ الصَّالِحِينَ) كأنه قيل: أصدّق. ونَفْساً تمييز، وتوحيدها لأنّ الغرض بيان الجنس والواحد يدل عليه. والمعنى: فإن وهبن لكم شيئا من الصداق وتجافت عنه نفوسهن طيبات غير مخبثات بما يضطرهن إلى الهبة من شكاسة أخلاقكم وسوء معاشرتكم فَكُلُوهُ فأنفقوه. قالوا: فإن وهبت له ثم طلبت منه بعد الهبة، علم أنها لم تطب منه نفسا، وعن الشعبي: أن رجلا أتى مع امرأته شريحا في عطية أعطتها إياه وهي تطلب أن ترجع، فقال شريح: ردّ عليها. فقال الرجل: أليس قد قال اللَّه تعالى: (فَإِنْ طِبْنَ لَكُمْ) قال لو طابت نفسها عنه لما رجعت فيه. وعنه: أقيلها فيما وهبت ولا أقيلة، لأنهنّ يخدعن. وحكى أن رجلا من آل معيط أعطته امرأته ألف دينار صداقا كان لها عليه، فلبث شهرا ثم طلقها، فخاصمته إلى عبد الملك بن مروان، فقال الرجل: أعطتنى طيبة بها نفسها، فقال عبد الملك: فأين الآية التي بعدها فلا تأخذوا منه شيئا؟ اردد عليها. وعن عمر رضى اللَّه عنه أنه كتب إلى قضاته: إن النساء يعطين رغبة ورهبة. فأيما امرأة أعطت ثم أرادت أن ترجع فذلك لها» [[أخرجه ابن أبى شيبة وعبد الرزاق من طريق محمد بن عبيد اللَّه الثقفي قال كتب عمر نحوه.]] وعن ابن عباس أنّ رسول اللَّه صلى اللَّه عليه وسلم سئل عن هذه الآية فقال «إذا جادت لزوجها بالعطية طائعة غير مكرهة لا يقضى به عليكم سلطان ولا يؤاخذكم اللَّه به في الآخرة» [[أخرجه الثعلبي والواحدي في الأوسط من رواية جويبر عن الضحاك عن ابن عباس.]] وروى أن أناسا كانوا يتأثمون أن يرجع أحد منهم في شيء مما ساق إلى امرأته، فقال اللَّه تعالى إن طابت نفس واحدة من غير إكراه ولا خديعة فكلوه سائغا هنيئا. وفي الآية دليل على ضيق المسلك في ذلك ووجوب الاحتياط، حيث بنى الشرط على طيب النفس فقيل: فإن طبن، ولم يقل: فإن وهبن أو سمحن، إعلاما بأنّ المراعى هو تجافى نفسها عن الموهوب طيبة. وقيل: إن طبن لكم عن شيء منه، ولم يقل: فإن طبن لكم عنها، بعثا لهن على تقليل الموهوب. وعن الليث بن سعد: لا يجوز تبرعها إلا باليسير. وعن الأوزاعى: لا يجوز تبرعها ما لم تلد أو تقم في بيت زوجها سنة. ويجوز أن يكون تذكير الضمير لينصرف إلى الصداق الواحد، فيكون متناولا بعضه، ولو أنث لتناول ظاهره هبة الصداق كله، لأنّ بعض الصدقات واحدة منها فصاعدا. الهنيء، والمريء: صفتان من هنؤ الطعام ومرؤ، إذا كان سائغاً لا تنغيص فيه. وقيل: الهنيء: ما يلذه الآكل. والمريء ما يحمد عاقبته. وقيل هو ما ينساغ في مجراه. وقيل لمدخل الطعام من الحلقوم إلى فم المعدة «المريء» لمروء الطعام فيه وهو انسياغه، وهما وصف للمصدر، أى أكلا هنيئا مريئا، أو حال من الضمير، أى كلوه وهو هنيء مريء، وقد يوقف على فكلوه ويبتدأ مريئا على الدعاء، وعلى أنهما صفتان أقيمتا مقام المصدرين، كأنه قيل: هنأ مرأ. وهذه عبارة عن التحليل والمبالغة في الإباحة وإزالة التبعة.',     source_page = '149',     updated_at  = datetime('now') WHERE id = 'QR:TE:6d5c9274280f34698b4c6651';
UPDATE qr_tafsir_entries SET content_ar = '«لو» مع ما في حيزه صلة للذين. والمراد بهم: الأوصياء، أمروا بأن يخشوا اللَّه [[قال محمود: «المراد الأوصياء أمروا بأن يخشوا اللَّه ... الخ» قال أحمد: وإنما ألجأه إلى تقدير (تَرَكُوا) بقوله: شارفوا أن يتركوا لأن جوابه قوله: (خافُوا عَلَيْهِمْ) والخوف عليهم إنما يكون قبل تركهم إياهم وذلك في دار الدنيا، فقد دل على أن المراد بالترك الاشراف عليه ضرورة، وإلا لزم وقوع الجواب قبل الشرط وهو باطل، ونظيره (فَبَلَغْنَ أَجَلَهُنَّ فَأَمْسِكُوهُنَّ بِمَعْرُوفٍ أَوْ سَرِّحُوهُنَّ بِمَعْرُوفٍ) أى شارفن بلوغ الأجل، ولهذا المجاز في التعبير عن المشارفة على الترك بالترك سر بديع، وهو التخويف بالحالة التي لا يبقى معها مطمع في الحياة ولا في الذب عن الذرية الضعاف، وهي الحالة التي وإن كانت من الدنيا إلا أنها لقربها من الآخرة ولصوقها بالمفارقة صارت من حيزها ومعبراً عنها بما يعبر به عن الحالة الكائنة بعد المفارقة من الترك، واللَّه أعلم.]] فيخافوا على من في حجورهم من اليتامى ويشفقوا عليهم، خوفهم على ذريتهم لو تركوهم ضعافا وشفقتهم عليهم وأن يقدّروا ذلك في أنفسهم ويصوّروه حتى لا يجسروا على خلاف الشفقة والرحمة. ويجوز أن يكون المعنى: وليخشوا على اليتامى من الضياع. وقيل: هم الذين يجلسون إلى المريض فيقولون: إن ذريتك لا يغنون عنك من اللَّه شيئا، فقدم مالك، فيستغرقه بالوصايا، فأمروا بأن يخشوا ربهم، أو يخشوا على أولاد المريض ويشفقوا عليهم شفقتهم على أولاد أنفسهم لو كانوا. ويجوز أن يتصل بما قبله وأن يكون أمراً بالشفقة للورثة على الذين يحضرون القسمة من ضعفاء أقاربهم واليتامى والمساكين وأن يتصوّروا أنهم لو كانوا أولادهم بقوا خلفهم ضائعين محتاجين، هل كانوا يخافون عليهم الحرمان والخيبة؟ فإن قلت: ما معنى وقوع لَوْ تَرَكُوا وجوابه صلة للذين؟ قلت: معناه: وليخش الذين صفتهم وحالهم أنهم لو شارفوا أن يتركوا خلفهم ذرية ضعافا، وذلك عند احتضارهم خافوا عليهم الضياع بعدهم لذهاب كافلهم وكاسبهم، كما قال القائل: لَقَدْ زَادَ الْحَيَاةَ إلَىَّ حُبًّا ... بَنَاتِى إنَّهُنَّ مِنَ الضِّعَافِ أُحَاذِرُ أَن يَرَيْنَ الْبُؤْسَ بَعْدِى ... وَأَنْ يَشْرَبْنَ رَنْقاً بَعْدَ صَافِى [[تقدم شرح هذه الشواهد ب من هذا الجزء فراجعه إن شئت اه مصححه.]] وقرئ: ضعفاء. وضعافى، وضعافى. نحو: سكارى، وسكارى. والقول السديد من الأوصياء: أن لا يؤذوا اليتامى ويكلموهم كما يكلمون أولادهم بالأدب الحسن والترحيب، ويدعوهم بيا بنىّ ويا ولدى، ومن الجالسين إلى المريض أن يقولوا له إذا أراد الوصية: لا تسرف في وصيتك فتجحف بأولادك، مثل قول رسول اللَّه صلى اللَّه عليه وسلم لسعد: «إنك إن تترك ولدك أغنياء خير من أن تدعهم عالة يتكففون الناس [[متفق عليه من حديث سعد بن أبى وقاص في قصة.]] » وكان الصحابة رضى اللَّه عنهم يستحبون أن لا تبلغ الوصية الثلث وأن الخمس أفضل من الربع والربع أفضل من الثلث. ومن المتقاسمين ميراثهم أن يلطفوا القول ويجملوه للحاضرين.',     source_page = '404',     updated_at  = datetime('now') WHERE id = 'QR:TE:67ff51d6d8a51ff10760759e';
UPDATE qr_tafsir_entries SET content_ar = 'إِذْ منصوب بأقرب، وساغ ذلك لأنّ المعاني تعمل في الظرف متقدّمة ومتأخرة: والمعنى: أنه لطيف يتوصل علمه إلى خطرات النفس وما لا شيء أخفى منه، وهو أقرب من الإنسان [[قوله «وهو أقرب من الإنسان» يقال: قرب من الشيء كما يقال: قرب إليه. (ع)]] من كل قريب حين يتلقى الحفيظان ما يتلفظ به، إيذانا بأن استحفاظ الملكين أمر هو غنى عنه، وكيف لا يستغنى عنه وهو مطلع على أخفى الخفيات؟ وإنما ذلك لحكمة اقتضت ذلك: وهي ما في كتبة الملكين وحفظهما، وعرض صحائف العمل يوم يقوم الأشهاد. وعلم العبد بذلك مع علمه بإحاطة الله بعمله: من زيادة لطف له في الانتهاء عن السيئات والرغبة في الحسنات. وعن النبي ﷺ «إنّ مقعد ملكيك على ثنيتيك، ولسانك قلمهما، وريقك مدادهما، وأنت تجرى فيما لا يعنيك لا تستحي من الله تعالى ولا منهما» [[أخرجه الثعلبي من رواية جميل بن الحسن عن أرطاه بن الأشعث العدوى عن جعفر بن محمد عن أبيه عن على رضى الله عنه عن النبي ﷺ قال «مقعد ملكيك» فذكره.]] ويجوز أن يكون تلقى الملكين بيانا للقرب، يعنى: ونحن قريبون منه مطلعون على أحواله مهيمنون عليه، إذ حفظتنا وكتبتنا موكلون به، والتلقي: التلقن بالحفظ والكتبة. والقعيد: القاعد، كالجليس بمعنى الجالس، وتقديره: عن اليمين قعيد وعن الشمال قعيد من المتلقيين، فترك أحدهما لدلالة الثاني عليه، كقوله: ... كنت منه ووالدي ... بريّا....... [[تقدم شرح هذا الشاهد بالجزء الثاني فراجعه إن شئت اه مصححه.]] .. رَقِيبٌ ملك يرقب عمله عَتِيدٌ حاضر، واختلف فيما يكتب الملكان، فقيل: يكتبان كل شيء حتى أنينه في مرضه. وقيل: لا يكتبان إلا ما يؤجر عليه أو يؤزر به. ويدل عليه قوله عليه السلام «كاتب الحسنات على يمين الرجل وكاتب السيئات على يسار الرجل، وكاتب الحسنات أمين على كاتب السيئات، فإذا عمل حسنة كتبها ملك اليمين عشرا، وإذا عمل سيئة قال صاحب اليمين لصاحب الشمال: دعه سبع ساعات لعله يسبح أو يستغفر» [[أخرجه الثعلبي والبغوي من طريق جعفر عن القاسم عن أبى أمامة. ومن هذا الوجه أخرجه الطبراني. وأخرجه البيهقي من هذا الوجه. ومن رواية بشر بن نمير عن القاسم نحوه. وأخرجه الطبراني من رواية ثور بن يزيد عن القاسم نحوه. وروى أبو نعيم في الحلية وابن مردويه من طريق إسماعيل بن عياش عن عاصم بن رجاء عن عروة بن رديم، عن القاسم عن أبى أمامة وعند الطبري من طريق على بن جرير عن حماد بن سلمة عن عبد الحميد بن جعفر عن كنانة، قال «دخل عثمان بن عفان على رسول الله ﷺ. فقال: يا رسول الله، كم مع العبد ملك؟ - الحديث»]] وقيل: إنّ الملائكة يجتنبون الإنسان عند غائطه وعند جماعه. وقرئ: ما يلفظ، على البناء للمفعول.',     source_page = '52',     updated_at  = datetime('now') WHERE id = 'QR:TE:7cfbe0704643d25695b5bd63';
UPDATE qr_tafsir_entries SET content_ar = 'أَكُفَّارُكُمْ يا أهل مكة خَيْرٌ مِنْ أُولئِكُمْ الكفار المعدودين: قوم نوح وهود وصالح ولوط وآل فرعون، أى أهم خير قوّة وآلة ومكانة في الدنيا، أو أقل كفرا وعنادا يعنى: أنّ كفاركم مثل أولئك بل شر منهم أَمْ أنزلت عليكم يا أهل مكة بَراءَةٌ في الكتب المتقدّمة. أنّ من كفر منكم وكذب الرسل كان آمنا من عذاب الله، فأمنتم بتلك البراءة نَحْنُ جَمِيعٌ جماعة أمرنا مجتمع مُنْتَصِرٌ ممتنع لا نرام ولا نضام. وعن أبى جهل أنه ضرب فرسه يوم بدر، فتقدّم في الصف وقال: نحن ننتصر اليوم من محمد وأصحابه، فنزلت سَيُهْزَمُ الْجَمْعُ عن عكرمة: لما نزلت هذه الآية قال عمر: أى جمع يهزم، فلما رأى رسول الله ﷺ يثب في الدرع ويقول: «سيهزم الجمع» عرف تأويلها [[أخرجه عبد الرزاق عن معمر عن قتادة، وعن أيوب عن عكرمة «أن عمر- فذكره» وأتم منه، ورواه من هذا الوجه إسحاق والطبري وابن أبى حاتم، ورواه الطبري في الأوسط من رواية عبد المجيد بن أبى رواد عن معمر عن قتادة عن أنس عن عمر موصولا.]] وَيُوَلُّونَ الدُّبُرَ أى الأدبار كما قال: كلوا في بعض بطنكم تعفوا [[تقدم شرح هذا الشاهد بالجزء الأول فراجعه إن شئت اه مصححه.]] وقرئ: الأدبار أَدْهى أشدّ وأفظع. والداهية: الأمر المنكر لذي لا يهتدى لدوائه وَأَمَرُّ من الهزيمة والقتل والأسر. وقرئ: سنهزم الجمع.',     source_page = '479',     updated_at  = datetime('now') WHERE id = 'QR:TE:973d6289a9a7ab2506aefaae';
UPDATE qr_tafsir_entries SET content_ar = 'مَقامَ رَبِّهِ موقفه الذي يقف فيه العباد للحساب يوم القيامة يَوْمَ يَقُومُ النَّاسُ لِرَبِّ الْعالَمِينَ ونحوه لِمَنْ خافَ مَقامِي ويجوز أن يراد بمقام ربه: أن الله قائم عليه، أى حافظ مهيمن من قوله تعالى أَفَمَنْ هُوَ قائِمٌ عَلى كُلِّ نَفْسٍ بِما كَسَبَتْ فهو يراقب ذلك فلا يجسر على معصيته. وقيل: هو مقحم كما تقول: أخاف جانب فلان، وفعلت هذا لمكانك. وأنشد: ذعرت به القطا ونفيت عنه ... مقام الذئب كالرّجل اللّعين [[قوله «كالرجل اللعين» : هو شيء ينصب وسط الزرع لطرد الوحوش، كذا في الصحاح. اه عليان. قلت: وتقدم شرح هذا الشاهد بهذا الجزء فراجعه إن شئت اه مصححه.]] يريد: ونفيت عنه الذئب. فإن قلت: لم قال جَنَّتانِ؟ قلت: الخطاب للثقلين، فكأنه قيل: لكل خائفين منكما جنتان: جنة للخائف الإنسى، وجنة للخائف الجنى. ويجوز أن يقال: جنة لفعل الطاعات، وجنة لترك المعاصي، لأنّ التكليف دائر عليهما وأن يقال: جنة يثاب بها، وأخرى تضم إليها على وجه التفضل، كقوله تعالى لِلَّذِينَ أَحْسَنُوا الْحُسْنى وَزِيادَةٌ خص الأفنان بالذكر: وهي الغصنة [[قوله «وهي الغصنة» جمع غصن، كقرطة جمع قرط. أفاده الصحاح. (ع)]] التي تتشعب من فروع الشجرة، لأنها هي التي تورق وتثمر، فمنها تمتد الظلال، ومنها تجتنى الثمار. وقيل: الأفنان ألوان النعم ما تشتهي الأنفس وتلذ الأعين. قال: ومن كل أفنان اللّذاذة والصّبا ... لهوت به والعيش أخضر ناضر [[الأفنان: جمع فنن، وهو الغصن كثير الورق، فيكون شبه اللذات والصبا: بروضة أو شجرة ذات أفنان على طريق المكنية. وإثبات الأفنان: تخييل. ويجوز أنه جمع فن، أى: نوع وصف على غير قياس، كصحب وأصحاب. واللذاذات: جمع لذاذة، وهي اللذة. ويروى: اللذاذة بالافراد. والصبا: الشباب أو هوى النفس. ومن بمعنى بعض على طريقة الزمخشري، أى: وبعض الأفنان لهوت، أى: تمتعت به. والجمهور يجعلون نحو هذا مما حذف فيه الموصوف، كقولهم: منا ظعن ومنا أقام، لتقدم مجرور يدل عليه، فمن كل: خبر مقدم، ولهوت: صفة لمحذوف مبتدأ مؤخر، أى: صنف لهوت به، لكن المعنى على الاخبار باللهو، فلا بد من المصير إلى رأى الزمخشري. أو جعل الجار والمجرور صفة للمبتدإ، ولهوت خبرا وإن لم يتقدم المجرور على الصفة. ويجوز أن «من كل» معمول لمحذوف يفسره المذكور، أى: تمنعت من كل الأفنان لهوت به، والواو للحال، أى: والحال أن العيش أخضر، أى رطب لين ناضر حسن، نشبه العش بروض يافع. والخضرة تخييل.]] عَيْنانِ تَجْرِيانِ حيث شاءوا في الأعالى والأسافل. وقيل: تجريان من جبل من مسك. وعن الحسن: تجريان بالماء الزلال: إحداهما التسنيم، والأخرى: السلسبيل زَوْجانِ صنفان: قيل: صنف معروف وصنف غريب مُتَّكِئِينَ نصب على المدح الخائفين. أو حال منهم، لأنّ من خاف في معنى الجمع بَطائِنُها مِنْ إِسْتَبْرَقٍ من ديباج ثخين، وإذا كانت البطائن من الإستبرق، فما ظنك بالظهائر؟ وقيل: ظهائرها من سندس. وقيل: من نور دانٍ قريب يناله القائم والقاعد والنائم. وقرئ: وجنى، بكسر الجيم.',     source_page = '205',     updated_at  = datetime('now') WHERE id = 'QR:TE:1128c0e43cfbd921abfd2add';
UPDATE qr_tafsir_entries SET content_ar = 'فِي سَمُومٍ في حر نار ينفذ في المسام وَحَمِيمٍ وماء حار متناه في الحرارة وَظِلٍّ مِنْ يَحْمُومٍ من دخان أسود بهيم لا بارِدٍ وَلا كَرِيمٍ نفى لصفتى الظل عنه، يريد: أنه ظل، ولكن لا كسائر الظلال: سماه ظلا، ثم نفى عنه برد الظل وروحه ونفعه لمن يأوى إليه من أذى الحر وذلك كرمه ليمحق ما في مدلول الظل من الاسترواح إليه. والمعنى أنه ظل حارّ ضارّ إلا أنّ للنفي في نحو هذا شأنا ليس للإثبات. وفيه تهكم بأصحاب الشأمة، وأنهم لا يستأهلون الظل البارد الكريم الذي هو لأضدادهم في الجنة. وقرئ: لا بارد ولا كريم بالرفع، أى: لا هو كذلك والْحِنْثِ الذنب العظيم. ومنه قولهم: بلغ الغلام الحنث، أى: الحلم ووقت المؤاخذة بالمآثم. ومنه: حنث في يمينه، خلاف: برّ فيها. ويقال: تحنث إذا تأثم وتحرج أَوَآباؤُنَا دخلت همزة الاستفهام على حرف العطف. فإن قلت: كيف حسن العطف على المضمر في لَمَبْعُوثُونَ من غير تأكيد بنحن؟ قلت: حسن للفاصل الذي هو الهمزة، كما حسن في قوله تعالى ما أَشْرَكْنا وَلا آباؤُنا لفصل لا المؤكدة النفي. وقرئ: أو آباؤنا. وقرئ: لمجمعون [[قوله «وقرئ: لمجمعون إلى ميقات» في الصحاح: أجمعت الشيء: جعلته جميعا. (ع)]] إِلى مِيقاتِ يَوْمٍ مَعْلُومٍ إلى ما وقتت به الدنيا من يوم معلوم، والإضافة بمعنى من، كخاتم فضة. والميقات: ما وقت به الشيء، أى: حدّ. ومنه مواقيت الإحرام: وهي الحدود التي لا يتجاوزها من يريد دخول مكة إلا محرما أَيُّهَا الضَّالُّونَ عن الهدى الْمُكَذِّبُونَ بالبعث، وهم أهل مكة ومن في مثل حالهم مِنْ شَجَرٍ مِنْ زَقُّومٍ من الأولى لابتداء الغاية، والثانية لبيان الشجر وتفسيره. وأنث ضمير الشجر على المعنى، وذكره على اللفظ في قوله مِنْهَا وعَلَيْهِ ومن قرأ مِنْ شَجَرٍ مِنْ زَقُّومٍ فقد جعل الضميرين للشجرة، وإنما ذكر الثاني على تأويل الزقوم، لأنه تفسيرها وهي في معناه شُرْبَ الْهِيمِ قرئ بالحركات الثلاث، فالفتح والضم: مصدران. وعن جعفر الصادق رضى الله عنه، أيام أكل وشرب، بفتح الشين. وأما المكسور فبمعنى المشروب، أى: ما يشربه الهيم وهي الإبل التي بها الهيام، وهو داء تشرب منه فلا تروى: جمع أهيم وهيماء. قال ذو الرمّة: فأصبحت كالهيماء لا الماء مبرد ... صداها ولا يقضى عليها هيامها [[وقد زودت مى على النأى قبلة ... علاقات حاجات طويل سقامها فأصبحت كالهيماء لا الماء مبرد ... صداها ولا يقضى عليها هيامها لذي الرمة، يقول: وقد زودتنا، أى جعلت زادنا مى عند الرحيل قبلة، فكانت القبلة علاقات الحاجات وأسباب التطلع إلى الوصال، فعلاقات: خبر مرفوع، أو بدل منصوب. والسقام ككلام، وسقم كتعب، وسقم كبخل: مصدر سقم كتعب تعبا، أى: عناؤها طويل المدة لا يبرأ. ويقال للجمل: أهيم. وللناقة هيماء، إذا أصابهما الهيام بالضم: وهو داء تغلى منه قلوب الإبل كالعطش الشديد، أى: فأصبحت كالناقة الهيماء. وقوله «لا الماء مبرد» استئناف مبين لوجه الشبه فيها. أو حال منها، أى: لا يبرد الماء ظمأها ولا يقضى عليها، أى: لا يمينها هيامها، فأنا كذلك لا وصال فيشفينى، ولا التلهف يميتني. ويروى: ولا يقضى على هيامها، ولعل معناه: لا الماء يبرد الحرقة التي حصلت لي منها، ولا يميتني الهيام الذي حصل لي منها، ولكن الأولى أقعد وأجود معنى.]] وقيل الهيم: الرمال. ووجهه أن يكون جمع الهيام بفتح الهاء وهو الرمل الذي لا يتماسك، جمع على فعل كسحاب وسحب، ثم خفف وفعل به ما فعل بجمع أبيض. والمعنى: أنه يسلط عليهم من الجوع ما يضطرّهم إلى أكل الزقوم الذي هو كالمهل، فإذا ملؤوا منه البطون يسلط عليهم من العطش ما يضطرّهم إلى شرب الحميم الذي يقطع أمعاءهم، فيشربونه شرب الهيم. فإن قلت: كيف صحّ عطف الشاربين على الشاربين، وهما لذوات متفقة، وصفتان متفقتان، فكان عطفا للشيء على نفسه؟ قلت: ليسنا بمتفقتين، من حيث إنّ كونهم شاربين للحميم على ما هو عليه: من تناهى الحرارة وقطع الأمعاء: أمر عجيب، وشربهم له على ذلك كما تشرب الهيم الماء: أمر عجيب أيضا، فكانتا صفتين مختلفتين. النزل: الرزق الذي يعدّ للنازل تكرما له. وفيه تهكم، كما في قوله تعالى فَبَشِّرْهُمْ بِعَذابٍ أَلِيمٍ وكقول أبى الشعر الضبي. وكنّا إذا الجبّار بالجيش ضافنا ... جعلنا القنا والموهفات له نزلا [[تقدم شرح هذا الشاهد بالجزء الأول فراجعه إن شئت اه مصححه.]] وقرئ: نزلهم بالتخفيف.',     source_page = '458',     updated_at  = datetime('now') WHERE id = 'QR:TE:bd71227e7d51c58cf263bf67';
UPDATE qr_tafsir_entries SET content_ar = 'الْماءَ الَّذِي تَشْرَبُونَ يريد: الماء العذب الصالح للشرب. والْمُزْنِ السحاب: الواحدة مزنة. وقيل: هو السحاب الأبيض خاصة، وهو أعذب ماء أُجاجاً ملحا زعاقا [[قوله «ملحا زعاقا» في الصحاح «الماء الزعاق» : الملح. وطعام مزعوق: إذا كثر ملحه. (ع)]] لا يقدر على شربه. فإن قلت: لم أدخلت اللام على جواب لَوْ في قوله لَجَعَلْناهُ حُطاماً ونزعت منه هاهنا؟ قلت: إنّ «لو» لما كانت داخلة على جملتين معلقة ثانيتهما بالأولى تعلق الجزاء بالشرط، ولم تكن مخلصة للشرط كإن ولا عاملة مثلها، وإنما سرى فيها معنى الشرط اتفاقا من حيث إفادتها في مضمونى جملتيها أنّ الثاني امتنع لامتناع الأوّل: افتقرت في جوابها إلى ما ينصب علما على هذا التعلق، فزيدت هذه اللام لتكون علما على ذلك، فإذا حذفت بعد ما صارت علما مشهورا مكانه، فلأن الشيء إذا علم وشهر موقعه وصار مألوفا ومأنوسا به: لم يبال بإسقاطه عن اللفظ، استغناء بمعرفة السامع. ألا ترى إلى ما يحكى عن رؤبة أنه كان يقول: خير، لمن قال له: كيف أصبحت؟ فحذف الجار لعلم كل أحد بمكانه. وتساوى حالى حذفه وإثباته لشهرة أمره. وناهيك بقول أوس: حتى إذا الكلّاب قال لها ... كاليوم مطلوبا ولا طلبا [[تقدم شرح هذا الشاهد بالجزء الثاني فراجعه إن شئت اه مصححه.]] وحذفه «لم أر» فإذن حذفها اختصار لفظي وهي ثابتة في المعنى، فاستوى الموضعان بلا فرق بينهما، على أن تقدّم ذكرها والمسافة قصيرة مغن عن ذكرها ثانية ونائب عنه. ويجوز أن يقال: إنّ هذه اللام مفيدة معنى التوكيد لا محالة، فأدخلت في آية المطعوم دون آية المشروب، للدلالة على أن أمر المطعوم مقدّم على أمر المشروب، وأن الوعيد بفقده أشد وأصعب، من قبل أن المشروب إنما يحتاج إليه تبعا للمطعوم. ألا ترى أنك إنما تسقى ضيفك بعد أن تطعمه، ولو عكست قعدت تحت قول أبى العلاء: إذا سقيت ضيوف النّاس محضا ... سقوا أضيافهم شبما زلالا [[لأبى العلاء يمدح سعد الدولة أبا الفضائل، وعيب عليه حيث مدح بسقى الضيوف الماء قبل ذكر الطعام. والمخض- بمعجمتين-: اللبن المنزوع زبده، فهو بمعنى الممخوض. ويروى: محضا، بالحاء المهملة، أى: خالصا حلوا أو حامضا. والشبم- كحذر-: البارد. والزلال: العقب. هذا وحيث جعل علماء البلاغة للمقام مدخلا في الدلالة على المراد فنقول: إن معنى البيت: إذا عجلت الناس اللبن لأضيافهم واكتفوا به عن الاسراع بالطعام: عجلوا هم بالطعام لضيوفهم لاستعدادهم للضيفان، فيحتاجون لشرب الماء، فيسقونهم ماء قبل إطعام غيرهم الضيفان، فسقيهم الماء يفيد تعجيل الطعام قبله بمعونة المقام، لأنه يلزمه عادة فلا عيب فيه.]] وسقى بعض العرب فقال: أنا لا أشرب إلا على ثميلة، ولهذا قدّمت آية المطعوم على آية المشروب.',     source_page = '288',     updated_at  = datetime('now') WHERE id = 'QR:TE:714959c48c16c257da646884';
UPDATE qr_tafsir_entries SET content_ar = 'أَلَمْ يَأْنِ من أنى الأمر يأنى، إذا جاء إناه، أى. وقته. وقرئ: ألم يئن، من آن يئين بمعنى: أنى يأنى، وألما يأن، قيل: كانوا مجدبين بمكة، فلما هاجروا أصابوا الرزق والنعمة ففتروا عما كانوا عليه، فنزلت. وعن ابن مسعود: ما كان بين إسلامنا وبين أن عوتبنا بهذه الآية إلا أربع سنين [[أخرجه مسلم بلفظ «وبين أن عاتبنا الله» ووهم الحاكم فاستدركه.]] . وعن ابن عباس رضى الله عنهما: أنّ الله استبطأ قلوب المؤمنين فعاتبهم على رأس ثلاث عشرة من نزول القرآن. وعن الحسن رضى الله عنه: أما والله لقد استبطأهم وهم يقرؤن من القرآن أقل مما تقرءون. فانظروا في طول ما قرأتم منه وما ظهر فيكم من الفسق. وعن أبى بكر رضى الله عنه أنّ هذه الآية قرئت بين يديه وعنده قوم من أهل اليمامة، فبكوا بكاء شديدا، فنظر إليهم فقال: هكذا كنا حتى قست القلوب. وقرئ: نزّل ونزل. وأنزل وَلا يَكُونُوا عطف على تخشع، وقرئ بالتاء على الالتفات. ويجوز أن يكون نهيا لهم عن مماثلة أهل الكتاب في قسوة القلوب بعد أن وبخوا، وذلك أنّ بنى إسرائيل كان الحق يحول بينهم وبين شهواتهم، وإذا سمعوا التوراة والإنجيل خشعوا لله ورقت قلوبهم، فلما طال عليهم الزمان غلبهم الجفاء والقسوة واختلفوا وأحدثوا ما أحدثوا من التحريف وغيره. فإن قلت: ما معنى لِذِكْرِ اللَّهِ وَما نَزَلَ مِنَ الْحَقِّ؟ قلت: يجوز أن يراد بالذكر وبما نزل من الحق: القرآن، لأنه جامع للأمرين: للذكر والموعظة، وأنه حق نازل من السماء، وأن يراد خشوعها إذا ذكر الله وإذا تلى القرآن كقوله تعالى إِذا ذُكِرَ اللَّهُ وَجِلَتْ قُلُوبُهُمْ وَإِذا تُلِيَتْ عَلَيْهِمْ آياتُهُ زادَتْهُمْ إِيماناً أراد بالأمد: الأجل، كقوله: ...... إذا انتهى أمده [[قوله «كقوله إذا انتهي أمده» البيت من أوله: كل حى مستكمل مدة العمر ... ومود إذا انتهى أمده.... اه عليان قلت: قد تقدم شرح هذا الشاهد بالجزء الأول فراجعه إن شئت. اه مصححه.]] وقرئ: الأمدّ، أى: الوقت الأطول وَكَثِيرٌ مِنْهُمْ فاسِقُونَ خارجون عن دينهم رافضون لما في الكتابين.',     source_page = '277',     updated_at  = datetime('now') WHERE id = 'QR:TE:52ec87a07922ab9222c47247';
UPDATE qr_tafsir_entries SET content_ar = 'مدنية، وآياتها 14 [نزلت بعد التغابن] بِسْمِ اللَّهِ الرَّحْمنِ الرَّحِيمِ لِمَ هي لام الإضافة داخلة على ما الاستفهامية كما دخل عليها غيرها من حروف الجر في قولك: بم، وفيم، ومم، وعم، وإلام، وعلام. وإنما حذفت الألف، لأنّ ما والحرف كشيء واحد، ووقع استعمالهما كثيرا في كلام المستفهم، وقد جاء استعمال الأصل قليلا والوقف على زيادة هاء السكت أو الإسكان، ومن أسكن في الوصل فلإجرائه مجرى الوقف، كما سمع: ثلاثة، أربعة: بالهاء وإلقاء حركة الهمزة عليها محذوفة، وهذا الكلام يتناول الكذب وإخلاف الموعد. وروى أنّ المؤمنين قالوا قبل أن يؤمروا بالقتال: لو نعلم أحب الأعمال إلى الله تعالى لعملناه ولبذلنا فيه أموالنا وأنفسنا، فدلهم الله تعالى على الجهاد في سبيله، فولوا يوم أحد فعيرهم. وقيل: لما أخبر الله بثواب شهداء بدر قالوا: لئن لقينا قتالا لنفرغن فيه وسعنا، ففروا يوم أحد ولم يفوا. وقيل: كان الرجل يقول: قتلت ولم يقتل، وطعنت ولم يطعن، وضربت ولم يضرب، وصبرت ولم يصبر. وقيل: كان قد أذى المسلمين رجل ونكى فيهم، فقتله صهيب وانتحل قتله آخر، فقال عمر لصهيب: أخبر النبي عليه السلام أنك قتلته، فقال: إنما قتله لله ولرسوله، فقال عمر: يا رسول الله قتله صهيب، قال: كذلك يا أبا يحيى؟ قال: نعم، فنزلت [[أخرجه الثعلبي من حديث صهيب قال «كان رجل يوم بدر قد آذى المسلمين ونكأ فيهم فقتله صهيب. فقال رجل: يا رسول الله قتلت فلانا. ففرح بذلك رسول الله ﷺ. فقال عمرو بن عبد الرحمن لصهيب أخبر النبي ﷺ بذلك- الحديث»]] في المنتحل. وعن الحسن: نزلت في المنافقين. ونداؤهم بالإيمان: تهكم بهم وبإيمانهم، هذا من أفصح كلام وأبلغه [[قال محمود: «هذا من أفصح الكلام وأبلغه، في معناه قصد إلى التعجب بغير صيغة التعجب لتعظيم الأمر ... الخ» قال أحمد: وزائد على هذه الوجوه الأربعة وجه خامس: وهو تكراره لقوله ما لا تَفْعَلُونَ وهو لفظ واحد في كلام واحد ومن فوائد التكرار: التهويل والإعظام، وإلا فقد كان الكلام مستقلا لو قيل: كبر مقتا عند الله ذلك، فما إعادته إلا لمكان هذه الفائدة الثانية، والله أعلم.]] في معناه قصد في كَبُرَ التعجب من غير لفظه كقوله: غلت ناب كليب بواؤها [[تقدم شرح هذا الشاهد بالجزء الثالث فراجعه إن شئت اه مصححة.]] ومعنى التعجب: تعظيم الأمر في قلوب السامعين، لأن التعجب لا يكون إلا من شيء خارج عن نظائره وأشكاله، وأسند إلى أن تقولوا. ونصب مَقْتاً على تفسيره، دلالة على أنّ قولهم ما لا يفعلون مقت خالص لا شوب فيه، لفرط تمكن المقت منه، واختير لفظ المقت لأنه أشد البغض وأبلغه. ومنه قيل: نكاح المقت، للعقد على الرابة [[قوله «على الرابة» هي بتشديد الباء كالدابة. وفي الصحاح: نكاح المقت كان في الجاهلية: أن يتزوج الرجل امرأة أبيه اه. (ع)]] ، ولم يقتصر على أن جعل البغض كبيرا، حتى جعل أشده وأفحشه. وعِنْدَ اللَّهِ أبلغ من ذلك، لأنه إذا ثبت كبر مقته عند الله فقد تم كبره وشدته وانزاحت عنه الشكوك. وعن بعض السلف أنه قيل له: حدّثنا، فسكت ثم قيل له حدثنا، فقال: تأمروننى أن أقول ما لا أفعل فاستعجل مقت الله. في قوله إِنَّ اللَّهَ يُحِبُّ الَّذِينَ يُقاتِلُونَ فِي سَبِيلِهِ عقيب ذكر مقت المخلف: دليل [[قال محمود: «ذكره لهذا عقيب ذكر مقت المخلف دليل ... الخ» قال أحمد: صدق، والأول كالبسطة العامة لهذه القصة الخاصة، كقوله تعالى يا أَيُّهَا الَّذِينَ آمَنُوا لا تُقَدِّمُوا بَيْنَ يَدَيِ اللَّهِ وَرَسُولِهِ وَاتَّقُوا اللَّهَ إِنَّ اللَّهَ سَمِيعٌ عَلِيمٌ، يا أَيُّهَا الَّذِينَ آمَنُوا لا تَرْفَعُوا أَصْواتَكُمْ فَوْقَ صَوْتِ النَّبِيِّ فالنهي العام ورد أولا، والمقصود اندراج هذا الخاص فيه كما تقول للمقترف جرما معينا: لا تفعل ما يلصق العار بك ولا تشاتم زيدا، وفائدة مثل هذا النظم: النهي عن الشيء الواحد مرتين مندرجا في العموم ومفردا بالخصوص، وهو أولى من النهى عنه على الخصوص مرتين فان ذلك معدود في حين التكرار، وهذا يتكرر مع ما في التعميم من التعظيم والتهويل، والله أعلم.]] على أن المقت قد تعلق بقول الذين وعدوا الثبات في قتال الكفار فلم يفوا. وقرأ زيد بن على: يقاتلون بفتح التاء. وقرئ: يقتلون صَفًّا صافين أنفسهم أو مصفوفين كَأَنَّهُمْ في تراصهم من غير فرجة ولا خلل بُنْيانٌ رص بعضه إلى بعض ورصف. وقيل: يجوز أن يريد استواء نياتهم في الثبات حتى يكونوا في اجتماع الكلمة كالبنيان المرصوص. وعن بعضهم: فيه دليل على فضل القتال راجلا، لأن الفرسان لا يصطفون على هذه الصفة. وقوله صَفًّا كَأَنَّهُمْ بُنْيانٌ حالان متداخلتان [[قال محمود: «قوله صَفًّا كَأَنَّهُمْ بُنْيانٌ مَرْصُوصٌ: حالان متداخلتان» قال أحمد: يريد أن معنى الأولى مشتمل على معنى الثانية، لأن التراص هيئة للاصطفاف، والله أعلم.]] .',     source_page = '273',     updated_at  = datetime('now') WHERE id = 'QR:TE:dc0ca37e95b91da68a9228da';
UPDATE qr_tafsir_entries SET content_ar = 'شبه اليهود- في أنهم حملة التوراة وقرّاؤها وحفاظ ما فيها، ثم إنهم غير عاملين بها ولا منتفعين بآياتها، وذلك أنّ فيها نعت رسول الله ﷺ والبشارة به ولم يؤمنوا به- بالحمار حمل أسفارا، أى كتبا كبارا من كتب العلم، فهو يمشى بها ولا يدرى منها إلا ما يمر بجنبيه وظهره من الكد والتعب. وكل من علم ولم يعمل بعلمه فهذا مثله، وبئس المثل بِئْسَ مثلا مَثَلُ الْقَوْمِ الَّذِينَ كَذَّبُوا بِآياتِ اللَّهِ وهم اليهود الذين كذبوا بآيات الله الدالة على صحة نبوّة محمد ﷺ. ومعنى حُمِّلُوا التَّوْراةَ: كلفوا علمها والعمل بها، ثُمَّ لَمْ يَحْمِلُوها ثم لم يعملوا بها، فكأنهم لم يحملوها. وقرئ: حملوا التوراة، أى حملوها ثم لم يحملوها في الحقيقة لفقد العمل. وقرئ: يحمل الأسفار. فإن قلت: يَحْمِلُ ما محله؟ قلت: النصب على الحال [[قال محمود: «إما أن يكون قوله يَحْمِلُ حالا، كقوله: ولقد أمر على اللئيم يسبني قال أحمد: يريد أن المراد فيها الجنس، فتعريفه وتنكيره سواء.]] ، أو الجر على الوصف، لأنّ الحمار كاللئيم في قوله: ولقد أمرّ على اللّئيم يسبّنى [[تقدم شرح هذا الشاهد بالجزء الأول فراجعه إن شئت اه مصححه.]]',     source_page = '16',     updated_at  = datetime('now') WHERE id = 'QR:TE:3e83d09c399fed70be344d2b';
UPDATE qr_tafsir_entries SET content_ar = 'مكية، وآياتها 44 [نزلت بعد الحاقة] بِسْمِ اللَّهِ الرَّحْمنِ الرَّحِيمِ ضمن سَأَلَ معنى دعا، فعدّى تعديته، كأنه قيل: دعا داع بِعَذابٍ واقِعٍ من قولك: دعا بكذا. إذا استدعى وطلبه. ومنه قوله تعالى يَدْعُونَ فِيها بِكُلِّ فاكِهَةٍ وعن ابن عباس رضى الله عنهما: هو النضر بن الحرث: قال إن كان هذا هو الحق من عندك فأمطر علينا حجارة من السماء أو ائتنا بعذاب أليم. وقيل: هو رسول الله ﷺ، استعجل بعذاب للكافرين. وقرئ. سال سائل، وهو على وجهين: إما أن يكون من السؤال وهي لغة قريش، يقولون: سلت تسأل، وهما يتسايلان، وأن يكون من السيلان. ويؤيده قراءة ابن عباس: سال سيل، والسيل: مصدر في معنى السائل، كالغور بمعنى الغائر. والمعنى: اندفع عليهم وادى عذاب فذهب بهم وأهلكهم. وعن قتادة: سأل سائل عن عذاب الله على من ينزل وبمن يقع؟ فنزلت، وسأل على هذا الوجه مضمن معنى: عنى واهتم. فإن قلت: بم يتصل قوله لِلْكافِرينَ؟ قلت: هو على القول الأوّل متصل بعذاب صفة له، أى: بعذاب واقع كائن للكافرين، أو بالفعل، أى: دعا للكافرين بعذاب واقع. أو بواقع، أى: بعذاب نازل لأجلهم، وعلى الثاني: هو كلام مبتدأ جواب للسائل، أى: هو للكافرين. فإن قلت: فقوله مِنَ اللَّهِ بم يتصل؟ قلت: يتصل بواقع، أى واقع من عنده، أو بدافع، بمعنى: ليس له دافع من جهته إذا جاء وقته وأوجبت الحكمة وقوعه ذِي الْمَعارِجِ ذى المصاعد جمع معرج، ثم وصف المصاعد وبعد مداها في العلو والارتفاع فقال: تَعْرُجُ الْمَلائِكَةُ وَالرُّوحُ إِلَيْهِ إلى عرشه وحيث تهبط منه أوامره فِي يَوْمٍ كانَ مِقْدارُهُ كمقدار مدة خَمْسِينَ أَلْفَ سَنَةٍ مما يعد الناس. والروح. جبريل عليه السلام، أفرده لتميزه بفضله. وقيل: الروح خلق هم حفظة على الملائكة، كما أنّ الملائكة حفظة على الناس. فإن قلت. بم يتعلق قوله فَاصْبِرْ؟ قلت: بسأل سائل، لأنّ استعجال النصر بالعذاب إنما كان على وجه الاستهزاء برسول الله ﷺ والتكذيب بالوحي، وكان ذلك مما يضجر رسول الله ﷺ، فأمر بالصبر عليه، وكذلك من سأل عن العذاب لمن هو، فإنما سأل على طريق التعنت، وكان من كفار مكة. ومن قرأ: سال سائل، أو سيل، فمعناه: جاء العذاب لقرب وقوعه، فاصبر فقد شارفت الانتقام، وقد جعل فِي يَوْمٍ من صلة واقِعٍ أى: يقع في يوم طويل مقداره خمسون ألف سنة من سنيكم، وهو يوم القيامة: إما أن يكون استطالة له لشدّته على الكفار، وإما لأنه على الحقيقة كذلك. قيل: فيه خمسون موطنا كل موطن ألف سنة، وما قدر ذلك على المؤمن إلا كما بين الظهر والعصر. الضمير في يَرَوْنَهُ للعذاب الواقع، أو ليوم القيامة فيمن علق فِي يَوْمٍ بواقع، أى: يستبعدونه على جهة الإحالة وَنحن نَراهُ قَرِيباً هينا في قدرتنا غير بعيد علينا ولا متعذر، فالمراد بالبعيد: البعيد من الإمكان، وبالقريب: القريب منه. نصب يَوْمَ تَكُونُ بقريبا، أى: يمكن ولا يتعذر في ذلك اليوم. أو بإضمار يقع، لدلالة واقِعٍ عليه. أو يوم تكون السماء كالمهل. كان كيت وكيت. أو هو بدل عن فِي يَوْمٍ فيمن علقه بواقع كَالْمُهْلِ كدردىّ الزيت. وعن ابن مسعود: كالفضة المذابة في تلوّنها كَالْعِهْنِ كالصوف المصبوغ ألوانا، لأنّ الجبال جدد بيض وحمر مختلف ألوانها وغرابيب سود، فإذا بست وطيرت في الجو: أشبهت العهن المنفوش إذا طيرته الريح وَلا يَسْئَلُ حَمِيمٌ حَمِيماً أى لا يسأله بكيف حالك ولا يكلمه، لأن بكل أحد ما يشغله عن المساءلة يُبَصَّرُونَهُمْ أى يبصر الأحماء الأحماء، فلا يخفون عليهم، [[قال محمود: «معناه يبصر الأصدقاء أصدقاءهم فيعرفونهم ... الخ» قال أحمد: وفيه دليل على أن الفاعل والمفعول الواقعين في سياق النفي يعم، كما التزم في: والله لا أشرب ماء من إداوة: أنه عام في المياه والأدوات، خلافا لبعضهم في الأدوات.]] فما يمنعهم من المساءلة أنّ بعضهم لا يبصر بعضا، وإنما يمنعهم التشاغل: وقرئ: يبصرونهم. وقرئ: ولا يسئل، على البناء للمفعول، أى: لا يقال الحميم أين حميمك ولا يطلب منه، لأنهم يبصرونهم فلا يحتاجون إلى السؤال والطلب. فإن قلت: ما موقع يبصرونهم؟ قلت: هو كلام مستأنف، كأنه لما قال وَلا يَسْئَلُ حَمِيمٌ حَمِيماً قيل: لعله لا يبصره، فقيل: يبصرونهم، ولكنهم لتشاغلهم لم يتمكنوا من تساؤلهم. فإن قلت: لم جمع الضميران في يُبَصَّرُونَهُمْ وهما للحميمين؟ قلت: المعنى على العموم لكل حميمين لا لحميمين اثنين. ويجوز أن يكون يُبَصَّرُونَهُمْ صفة، أى: حميما مبصرين معرّفين إياهم. قرئ: يومئذ، بالجرّ والفتح على البناء للإضافة إلى غير متمكن، ومن عذاب يومئذ، بتنوين عَذابِ ونصب يَوْمِئِذٍ وانتصابه بعذاب، لأنه في معنى تعذيب وَفَصِيلَتِهِ عشيرته الأدنون الذين فصل عنهم تُؤْوِيهِ تضمه انتماء إليها، أو لياذا بها في النوائب يُنْجِيهِ عطف على يفتدى، أى: يودّ لو يفتدى، ثم لو ينجيه الافتداء. أو من في الأرض. وثم: لاستبعاد الإنجاء، يعنى: تمنى لو كان هؤلاء جميعا تحت يده وبذلهم في فداء نفسه، ثم ينجيه ذلك وهيهات أن ينجيه كَلَّا ردّ للمجرم عن الودادة، وتنبيه على أنه لا ينفعه الافتداء ولا ينجيه من العذاب، ثم قال إِنَّها والضمير للنار، ولم يجر لها ذكر، لأنّ ذكر العذاب دل عليها. ويجوز أن يكون ضميرا مبهما ترجم عنه الخبر، أو ضمير القصة. ولَظى علم للنار، منقول من اللظى: بمعنى اللهب. ويجوز أن يراد اللهب. ونَزَّاعَةً خبر بعد خبر لأنّ، أو خبر للظى إن كانت الهاء ضمير القصة، أو صفة له إن أردت اللهب، والتأنيث لأنه في معنى النار. أو رفع على التهويل، أى: هي نزاعة. وقرئ نزاعة، بالنصب على الحال المؤكدة، أو على أنها متلظية نزاعة، أو على الاختصاص للتهويل. والشوى: الأطراف. أو جمع شواة: وهي جلدة الرأس تنزعها نزعا فتبتكها [[قوله «فتبتكها» أى: تقطعها. (ع)]] ثم تعاد تَدْعُوا مجاز عن إحضارهم، كأنها تدعوهم فتحضرهم. ونحوه قول ذى الرمّة: ...... تدعو أنفه الرّبب [[أمسى بوهبين مجتازا لمرتعه ... من ذى الفوارس تدعو أنفه الربب لدى الرمة يصف ثورا وحشيا. ووهبين: اسم موضع، وكذلك ذو الفوارس. والربب- بموحدتين-: جمع ربة وهي أول ما ينبت من الكلا. والدعاء: الطلب، وهو هنا مجاز عن التسبب في الأمر، لأن النبات الصغير سبب في وصول أنفه للأرض، ليرعاه. ويجوز تشبيه الربب بالداعي، والدعاء تخييل، ثم يحتمل أن مرتعه من ذى الفوارس ويحتمل أنه سار من ذى الفوارس إلى وهبين. ويروى: مختارا، أى: متخيرا ومتطلبا خير المراتع.]] وقوله: ليالي اللهو يطبينى فأتبعه [[تقدم شرح هذا الشاهد بالجزء الثالث فراجعه إن شئت اه مصححه.]] وقول أبى النجم: تقول للرّائد أعشبت أنزل [[تقدم شرح هذا الشاهد بالجزء الثاني فراجعه إن شئت اه مصححه.]] وقيل: تقول لهم: إلىّ إلىّ يا كافر يا منافق. وقيل: تدعو المنافقين والكافرين بلسان فصيح. ثم تلتقطهم التقاط الحب، فيجوز أن يخلق الله فيها كلاما كما يخلقه في جلودهم وأيديهم وأرجلهم، وكما خلقه في الشجرة [[قوله «وكما خلقه في الشجرة» على زعم المعتزلة أنه تكليم الله موسى، كأنه كذلك. وعند أهل السنة أنه أطلعه على كلامه القديم القائم بذاته تعالى. (ع)]] ويجوز أن يكون دعاء الزبانية. وقيل: تدعو تهلك، من قول العرب: دعاك الله، أى: أهلكك. قال دعاك الله من رجل بأفعى [[دعاك الله من رجل بأفعي ... ضئيل تنفث السم الذعافا دعاك، أى: أهلك الله بأفعى يقال: دعاه الله بالمكروه: أنزله به، ومن رجل: بيان واقع موقع الحال، أو تمييز مقترن بمن. لأن ما قبله فيه معنى التعجب، فيحتاج لتمييز جهة التعجب. وقال بعض النحاة: قد يجيء التمييز لمجرد التوكيد، فيكون هذا منه، بأفعى بالتنوين: اسم للحية. وقيل ممنوع من الصرف، لأنه صفة للحية الشديدة السم، والذعاف: أى الشديد القاتل، ضئيل: ضعيفة مهزولة. والنفث: إخراج النفس مع بلل، وهو هنا إخراج السم الذعاف كغراب: المسرع القتل. ويحتمل أن «دعاك الله» من باب المجاز، كأن الله دعاه؟؟؟ لقتله بالأفعى. أو طلبه بأفعى أرسلها إليه لتحضره بإهلاكه. وخص المهزولة لأنها أشد إيذاء من غيرها، وقال ضئيل، مع أن موصوفه مؤنث على حد: إن رحمة الله قريب، والمذكر: أفعوان. ويروى «ينفث» على أن الأفعى واحد من الجنس فهو مذكر.]] مَنْ أَدْبَرَ عن الحق وَتَوَلَّى عنه وَجَمَعَ المال فجعله في وعاء وكنزه ولم يؤدّ الزكاة والحقوق الواجبة فيه، وتشاغل به عن الدين، وزهى باقتنائه وتكبر.',     source_page = '191',     updated_at  = datetime('now') WHERE id = 'QR:TE:2d72cddcd91ffeb50a2936d5';
UPDATE qr_tafsir_entries SET content_ar = 'مِنَّا الصَّالِحُونَ منا الأبرار المتقون وَمِنَّا دُونَ ذلِكَ ومنا قوم دون ذلك، فحذف الموصوف، كقوله وَما مِنَّا إِلَّا لَهُ مَقامٌ مَعْلُومٌ وهم المقتصدون في الصلاح غير الكاملين فيه. أو أرادوا الطالحين كُنَّا طَرائِقَ قِدَداً بيان للقسمة المذكورة، أى: كنا ذوى مذاهب مفترقة مختلفة. أو كنا في اختلاف أحوالنا مثل الطرائق المختلفة. أو كنا في طرائق مختلفة، كقوله: كما عسل الطّريق الثّعلب [[تقدم شرح هذا الشاهد بالجزء الثاني فراجعه إن شئت اه مصححه.]] أو كانت طرائقنا طرائق قددا على حذف المضاف الذي هو الطرائق وإقامة الضمير المضاف إليه مقامه والقدّة من قدّ، كالقطعة من قطع، ووصفت الطرائق بالقدد، لدلالتها على معنى التقطع والتفرّق.',     source_page = '92',     updated_at  = datetime('now') WHERE id = 'QR:TE:62bcda763e40fef598fa2c29';
UPDATE qr_tafsir_entries SET content_ar = 'قرأ الحسن: ولا تمنّ. وتستكثر، مرفوع منصوب المحل على الحال، أى: ولا تعط مستكثرا رائيا لما تعطيه كثيرا، أو طالبا للكثير: نهى عن الاستغزار: وهو أن يهب شيئا وهو يطمع أن يتعوّض من الموهوب له أكثر من الموهوب، وهذا جائز. ومنه الحديث «المستغزر يثاب من هبته» [[تقدم في الروم من قول شريح.]] وفيه وجهان، أحدهما: أن يكون نهيا خاصا برسول الله ﷺ: لأنّ الله تعالى اختار له أشرف الآداب وأحسن الأخلاق. والثاني: أن يكون نهى تنزيه لا تحريم له ولأمّته. وقرأ الحسن: تستكثر، بالسكون. وفيه ثلاثة أوجه، الإبدال من تمنن. كأنه قيل: ولا تمنن لا تستكثر، على أنه من المنّ في قوله عز وجل ثُمَّ لا يُتْبِعُونَ ما أَنْفَقُوا مَنًّا وَلا أَذىً لأنّ من شأن المنان بما يعطى أن يستكثره، أى: يراه كثيرا ويعتدّ به، وأن يشبه ثرو بعضد، فيسكن تخفيفا، وأن يعتبر حال الوقف. وقرأ الأعمش بالنصب بإضمار «أن» كقوله: ألا أيّهذا الزّاجرى أحضر الوغى [[تقدم شرح هذا الشاهد بالجزء الأول فراجعه إن شئت اه مصححه.]] وتؤيده قراءة ابن مسعود: ولا تمنن أن تستكثر. ويجوز في الرفع أن تحذف «أن» ويبطل عملها، كما روى: أحضر الوغى بالرفع، وَلِرَبِّكَ فَاصْبِرْ ولوجه الله، فاستعمل الصبر. وقيل: على أذى المشركين. وقيل: على أداء الفرائض. وعن النخعي: على عطيتك، كأنه وصله بما قبله، وجعله صبرا على العطاء من غير استكثار. والوجه أن يكون أمرا بنفس الفعل، وأن يتناول على العموم كل مصبور عليه ومصبور عنه، ويراد الصبر على أذى الكفار، لأنه أحد ما يتناوله العام.',     source_page = '159',     updated_at  = datetime('now') WHERE id = 'QR:TE:49dceec06ab498ab7e3aab31';
UPDATE qr_tafsir_entries SET content_ar = 'مكية، وآياتها 40 [نزلت بعد القارعة] بِسْمِ اللَّهِ الرَّحْمنِ الرَّحِيمِ إدخال «لا» النافية على فعل القسم مستفيض في كلامهم وأشعارهم. قال امرؤ القيس: لا وأبيك أبنة العامرىّ ... لا يدّعى القوم أنّى أفرّ [[تقدم شرح هذا الشاهد بالجزء الأول فراجعه إن شئت اه مصححه.]] وقال غوثة بن سلمى: ألا نادت أمامة باحتمال ... لتحزننى فلا بك ما أبالى [[إذا نادت أمامة باحتمال ... لتحزننى فلا بك ما أبالى فسيرى ما بدا لك أو أقيمي ... فأيا ما أتيت ففي نقالى لغوثة بن سلمى بن ربيعة، يقول: إذا أظهرت أمامة محبوبتى أمارات الارتحال عنى لتحزننى، فأطلق النداء على ذلك مجازا. ويروى «ألا» بدل «إذا» ولا زائدة قبل القسم، لأن المعنى فبحقك وحياتك ما أبالى ولا أحزن، وحسن زيادتها: أنها في الغالب مسلطة على دعوى الخصم نافية لها، وفي القسم بمحبوبته على عدم المبالاة ببعدها عنه نوع تهكم بها. وقيل: المعنى فلا يقع ما أبالى على الدعاء، وهذا إنما يظهر على رواية: فلا بك ما أبالى، وأصله يكن، أى: يحصل، فحذفت النون عند الجزم تخفيفا. وما موصولة. ويروى: فآبك، أى: أبعدك الله: دعاء أيضا. والتقالى: التباغض، أى: فسيرى ما دام يظهر لك المسير، أو أقيمى، فهما منك سواء، وأى شيء تفعلينه فهو ناشئ عن تباغض بيني وبينك، ومع ذلك لا أعتنى بشأنك لأنى مشغول بأهم منك: وهو موت أقاربه، والتفت إليها بالخطاب ليصدعها بالجواب.]] وفائدتها توكيد القسم، وقالوا إنها صلة مثلها في لِئَلَّا يَعْلَمَ أَهْلُ الْكِتابِ وفي قوله: في بئر لا حور سرى وما شعر [[في بئر لا حور سرى وما شعر ... بافكه حتى إذا الصبح حشر «لا» زائدة بين المضاف والمضاف إليه شذوذا. والحور- بالضم-: الهلكة جمع حائر أى هالك، كبزل وبازل، ونزل ونازل. وقيل: الحور بمعنى الهلاك، وجمعه: أحور، أى: سرى في بئر هلاك وما درى بذلك. وقوله «بافكه» يجوز تعلقه بشعر، ويجوز تعلقه بسرى، وشبه سبب الهلاك بالبئر على طريق التصريح التحير والضرر بالوقوع في كل، ولذلك قال: سرى، وهو يناسب الظلمة والحيرة، لأنه بمعنى سار ليلا. والافك: الباطل، واستعار الصبح الحق على طريق التصريحية، وحشر: أضاء واتضح، فحينئذ تبين كذبه، أى: دام على كذبه حتى ظهر الحق]] واعترضوا عليه بأنها إنما تزاد في وسط الكلام لا في أوّله، وأجابوا بأنّ القرآن في حكم سورة واحدة متصل بعضه ببعض، والاعتراض صحيح، لأنها لم تقع مزيدة إلا في وسط الكلام، ولكن الجواب غير سديد. ألا ترى إلى امرئ القيس كيف زادها في مستهل قصيدته. والوجه أن يقال: هي للنفي. والمعنى في ذلك أنه لا يقسم بالشيء إلا إعظاما له يدلك عليه قوله تعالى فَلا أُقْسِمُ بِمَواقِعِ النُّجُومِ وَإِنَّهُ لَقَسَمٌ لَوْ تَعْلَمُونَ عَظِيمٌ فكأنه بإدخال حرف النفي يقول: إنّ إعظامى له بإقسامى به كلا إعظام، يعنى أنه يستأهل فوق ذلك. وقيل إن «لا» نفى لكلام وردّ له قبل القسم، كأنهم أنكروا البعث فقيل: لا، أى ليس الأمر على ما ذكرتم، ثم قيل: أقسم بيوم القيامة. فإن قلت: قوله تعالى فَلا وَرَبِّكَ لا يُؤْمِنُونَ والأبيات التي أنشدتها: المقسم عليه فيها منفي، فهلا زعمت أنّ «لا» التي قبل القسم زيدت موطئة النفي بعده ومؤكدة له، وقدرت المقسم عليه المحذوف هاهنا منفيا، كقولك لا أُقْسِمُ بِيَوْمِ الْقِيامَةِ، لا تتركون سدى؟ قلت: لو قصر الأمر على النفي دون الإثبات لكان لهذا القول ماغ، ولكنه لم يقصر. ألا ترى كيف لقى لا أُقْسِمُ بِهذَا الْبَلَدِ بقوله لَقَدْ خَلَقْنَا الْإِنْسانَ وكذلك فَلا أُقْسِمُ بِمَواقِعِ النُّجُومِ بقوله إِنَّهُ لَقُرْآنٌ كَرِيمٌ وقرئ: لأقسم، على أنّ اللام للابتداء. وأقسم خبر مبتدإ محذوف، معناه: لأنا أقسم. قالوا: ويعضده أنه في الإمام بغير ألف بِالنَّفْسِ اللَّوَّامَةِ بالنفس المتقية التي تلوم النفوس فيه أى في يوم القيامة على تقصيرهن في التقوى أو بالتي لا تزال تلوم نفسها وإن اجتهدت في الإحسان. وعن الحسن: إن المؤمن لا تراه إلا لائما نفسه، وإنّ الكافر يمضى قدما لا يعاتب نفسه [[قوله: «وأن الكافر يمضى قدما لا يعاتب» في الصحاح مضى قدما- بضم الدال-: لم يعرج ولم ينثن اه. (ع)]] . وقيل: هي التي تتلوّم يومئذ على ترك الازدياد إن كانت محسنة. وعلى التفريط إن كانت مسيئة. وقيل: هي نفس آدم، لم تزل تتلوم على فعلها الذي خرجت به من الجنة. وجواب القسم ما دل عليه قوله أَيَحْسَبُ الْإِنْسانُ أَلَّنْ نَجْمَعَ عِظامَهُ وهو لتبعثن. وقرأ قتادة: أن لن نجمع عظامه، على البناء للمفعول. والمعنى: نجمعها بعد تفرقها ورجوعها رميما ورفاتا مختلطا بالتراب، وبعد ما سفتها الرياح وطيرتها في أباعد الأرض. وقيل إن عدى ابن أبى ربيعة ختن الأخنس بن شريق [[قوله «ختن الأخنس بن شريق» في الصحاح «الختن» بالتحريك: كل من كان من قبل المرأة مثل الأب والأخ، وعند العامة: ختن الرجل زوج ابنته. (ع)]] وهما اللذان كان رسول الله ﷺ يقول فيهما: «اللهم اكفني جارى السوء» [[ذكره الثعلبي والبغوي، والواحدي بغير إسناد.]] قال لرسول الله ﷺ: يا محمد حدثني عن يوم القيامة متى يكون وكيف أمره؟ فأخبره رسول الله ﷺ، فقال: لو عاينت ذلك اليوم لم أصدقك يا محمد ولم أو من به أو يجمع الله العظام، فنزلت بَلى أوجبت ما بعد النفي وهو الجمع، فكأنه قيل بَلى نجمعها. وقادِرِينَ حال من الضمير في نجمع، أى: نجمع العظام قادرين على تأليف جميعها وإعادتها إلى التركيب الأول، إلى أن نسوى بنانه أى: أصابعه التي هي أطرافه، وآخر ما يتم به خلقه. أو على أن نسوى بنانه ونضم سلامياته على صغرها ولطافتها بعضها إلى بعض كما كانت أولا من غير نقصان ولا تفاوت، فكيف بكبار العظام. وقيل: معناه بلى نجمعها ونحن قادرون على أن نسوى أصابع يديه ورجليه، أى نجعلها مستوية شيئا واحدا كخف البعير وحافر الحمار لا تفرق بينها، فلا يمكنه أن يعمل بها شيئا مما يعمل بأصابعه المفرقة ذات المفاصل والأنامل من فنون الأعمال، والبسط والقبض، والتأتى لما يريد من الحوائج. وقرئ قادرون، أى: نحن قادرون، بَلْ يُرِيدُ عطف على أَيَحْسَبُ فيجوز أن يكون مثله استفهاما، وأن يكون إيجابا على أن يضرب عن مستفهم عنه إلى آخر. أو يضرب عن مستفهم عنه إلى موجب لِيَفْجُرَ أَمامَهُ ليدوم على فجوره فيما بين يديه من الأوقات وفيما يستقبله من الزمان لا ينزع عنه. وعن سعيد بن جبير رضى الله عنه: يقدم الذنب ويؤخر التوبة. يقول: سوف أتوب، سوف أتوب: حتى يأتيه الموت على شرّ أحواله وأسوإ أعماله يَسْئَلُ سؤال متعنت مستبعد لقيام الساعة في قوله أَيَّانَ يَوْمُ الْقِيامَةِ ونحوه: ويقولون متى هذا الوعد.',     source_page = '692',     updated_at  = datetime('now') WHERE id = 'QR:TE:4b6aad8b47e23d220a9e2a7d';
UPDATE qr_tafsir_entries SET content_ar = 'مدنية، وآياتها 31 [نزلت بعد الرحمن] بِسْمِ اللَّهِ الرَّحْمنِ الرَّحِيمِ هل بمعنى «قد» في الاستفهام خاصة، والأصل: أهل، بدليل قوله: أهل رأونا بسفع القاع ذى الأكم [[تقدم شرح هذا الشاهد بالجزء الثالث فراجعه إن شئت اه مصححه.]] فالمعنى: أقد أتى؟ على التقرير والتقريب جميعا، أى: أتى على الإنسان قبل زمان قريب حِينٌ مِنَ الدَّهْرِ لَمْ يَكُنْ فيه شَيْئاً مَذْكُوراً أى كان شيئا منسيا غير مذكور نطفة في الأصلاب والمراد بالإنسان: جنس بنى آدم، بدليل قوله إِنَّا خَلَقْنَا الْإِنْسانَ مِنْ نُطْفَةٍ. حِينٌ مِنَ الدَّهْرِ طائفة من الزمن الطويل الممتد. فإن قلت: ما محل لَمْ يَكُنْ شَيْئاً مَذْكُوراً؟ قلت: محله النصب على الحال من الإنسان، كأنه قيل: هل أتى عليه حين من الدهر غير مذكور. أو الرفع على الوصف لحين، كقوله يَوْماً لا يَجْزِي والِدٌ عَنْ وَلَدِهِ وعن بعضهم: أنها تليت عنده فقال: ليتها تمت، أراد: ليت تلك الحالة تمت، وهي كونه شيئا غير مذكور ولم يخلق ولم يكلف.',     source_page = '342',     updated_at  = datetime('now') WHERE id = 'QR:TE:077778d3d88e87f9cb68c2dc';
UPDATE qr_tafsir_entries SET content_ar = 'وكُلُوا وَتَمَتَّعُوا حال من المكذبين، أى الويل ثابت لهم في حال ما يقال لهم كلوا وتمتعوا فإن قلت: كيف يصح أن يقال لهم ذلك في الآخرة؟ قلت: يقال لهم ذلك في الآخرة إيذانا بأنهم كانوا في الدنيا أحقاء بأن يقال لهم، وكانوا من أهله تذكيرا بحالهم السمجة وبما جنوا على أنفسهم من إيثار المتاع القليل على النعيم والملك الخالد. وفي طريقته قوله: إخوتى لا تبعدوا أبدا ... وبلى والله قد بعدوا [[تقدم شرح هذا الشاهد بالجزء الثاني فراجعه إن شئت اه مصححه.]] يريد: كنتم أحقاء في حياتكم بأن يدعى لكم بذلك، وعلل ذلك بكونهم مجرمين دلالة على أن كل مجرم ماله إلا الأكل والتمتع أياما قلائل، ثم البقاء في الهلاك أبدا. ويجوز أن يكون كُلُوا وَتَمَتَّعُوا كلاما مستأنفا خطابا للمكذبين في الدنيا ارْكَعُوا اخشعوا لله وتواضعوا له بقبول وحيه واتباع دينه. واطرحوا هذا الاستكبار والنخوة، لا يخشعون ولا يقبلون ذلك، ويصرون على استكبارهم. وقيل: ما كان على العرب أشدّ من الركوع والسجود: وقيل: نزلت في ثقيف حين أمرهم رسول الله ﷺ بالصلاة، فقالوا: لا نجي [[قوله «فقالوا لا نجى» نجبى من التجبية: وهي الانحناء اه. (ع)]] فإنها مسبة [[هكذا ذكره الثعلبي. وأخرجه أبو داود وأحمد وابن أبى شيبة والطبراني من رواية الحسن عن عثمان بن أبى العاص به وأتم منه.]] علينا. فقال رسول الله ﷺ: لا خير في دين ليس فيه ركوع ولا سجود بَعْدَهُ بعد القرآن، يعنى أنّ القرآن من بين الكتب المنزلة آية مبصرة ومعجزة باهرة، فحين لم يؤمنوا به فبأى كتاب بعده يُؤْمِنُونَ وقرئ: تؤمنون، بالتاء. عن رسول الله ﷺ «من قرأ سورة والمرسلات كتب له أنه ليس من المشركين» [[أخرجه الثعلبي والواحدي وابن مردويه عن أبى بن كعب.]]',     source_page = '405',     updated_at  = datetime('now') WHERE id = 'QR:TE:7ee9739e1c7c296e5bf238b8';
UPDATE qr_tafsir_entries SET content_ar = 'المرصاد: الحدّ الذي يكون فيه الرصد. والمعنى: أن جهنم هي حدّ الطاغين الذي يرصدون فيه للعذاب وهي مآبهم. أو هي مرصاد لأهل الجنة ترصدهم الملائكة الذين يستقبلونهم عندها، لأن مجازهم عليها، وهي مآب للطاغين. وعن الحسن وقتادة نحوه، قالا: طريقا وممرّا لأهل الجنة. وقرأ ابن يعمر: أنّ جهنم، بفتح الهمزة على تعليل قيام الساعة بأنّ جهنم كانت مرصادا للطاغين، كأنه قيل: كان ذلك لإقامة الجزاء. قرئ: لابثين ولبثين، واللبث أقوى، لأنّ اللابث من وجد منه اللبث، ولا يقال «لبث» إلا لمن شأنه اللبث، كالذي يجثم بالمكان لا يكاد ينفك منه أَحْقاباً حقبا [[قوله «أحقابا» في الصحاح «الحقب» بالضم: ثمانون سنة. والحقبة- بالكسر-: واحدة الحقب، وهي السنون. والحقب: الدهر، والأحقاب: الدهور. (ع)]] بعد حقب، كلما مضى حقب تبعه آخر إلى غير نهاية، ولا يكاد يستعمل الحقب والحقبة إلا حيث يراد تتابع الأزمنة وتواليها، والاشتقاق يشهد لذلك. ألا ترى إلى حقيبة الراكب، والحقب الذي وراء التصدير [[قوله «والحقب الذي وراء التصدير» في الصحاح «التصدير» : الحزام، وهو في صدر البعير، والحقب عند الثيل. وفيه «الثيل» : وعاء قضيب البعير. (ع)]] وقيل: الحقب ثمانون سنة، ويجوز أن يراد: لابثين فيها أحقابا غير ذائقين فيها بردا ولا شرابا إلا حميما وغساقا، ثم يبدلون بعد الأحقاب غير الحميم والغساق من جنس آخر من العذاب. وفيه وجه آخر: وهو أن يكون من «حقب عامنا» إذا قل مطره وخيره، وحقب فلان: إذا أخطأه الرزق، فهو حقب، وجمعه أحقاب، فينتصب حالا عنهم، يعنى لابثين فيها حقيبين [[قوله «لابثين فيها حقيبين» لعله حقبين من حقب بالكسر كجحدين من جحد: إذا كان ضيقا قليل الخير فيهما، أفاده الصحاح. (ع)]] جحدين. وقوله لا يَذُوقُونَ فِيها بَرْداً وَلا شَراباً تفسير له والاستثناء منقطع، يعنى: لا يذوقون فيها بردا وروحا ينفس عنهم حرّ النار، ولا شرابا يسكن من عطشهم، ولكن يذوقون فيها حميما وغساقا وقيل «البرد» النوم، وأنشد: فلو شئت حرّمت النّساء سواكم ... وإن شئت لم أطعم نقاخا ولا بردا [[تقدم شرح هذا الشاهد بالجزء الأول فراجعه إن شئت اه مصححه.]] وعن بعض للعرب: منع البرد البرد [[قوله «منع البرد البرد» أى: منع البرد النوم. (ع)]] . وقرئ: غساقا، بالتخفيف والتشديد: وهو ما يغسق، أى: يسيل من صديدهم وِفاقاً وصف بالمصدر. أو ذا وفاق. وقرأ أبو حيوة: وفاقا، فعال من وفقه كذا كِذَّاباً تكذيبا، وفعال في باب فعل كله فاش في كلام فصحاء من العرب لا يقولون غيره، وسمعنى بعضهم أفسر آية فقال لقد فسرتها فسارا ما سمع بمثله. وقرئ بالتخفيف، وهو مصدر كذب، بدليل قوله: فصدقتها وكذبتها ... والمرء ينفعه كذابه [[الكذاب- ككتاب-: مصدر مضاف لفاعله. وصدقتها وكذبتها- بتخفيفها- بمعنى: قلت لها قولا صادقا تارة، وقولا كاذبا تارة أخرى. أو قلت لها: أنت صادقة تارة، وأنت كاذبة تارة. والضمير لنفسه أو صاحبته مثلا. وعلل ذلك بأن الكذب قد ينفع.]] وهو مثل قوله أَنْبَتَكُمْ مِنَ الْأَرْضِ نَباتاً يعنى: وكذبوا بآياتنا فكذبوا كذابا. أو تنصبه بكذبوا، لأنه يتضمن معنى كذبوا، لأنّ كل مكذب بالحق كاذب، وإن جعلته بمعنى المكاذبة فمعناه: وكذبوا بآياتنا، فكاذبوا مكاذبة. أو كذبوا بها مكاذبين، لأنهم إذا كانوا عند المسلمين كاذبين وكان المسلمون عندهم كاذبين فبينهم مكاذبة. أو لأنهم يتكلمون بما هو إفراط في الكذب فعل من يغالب في أمر، فيبلغ فيه أقصى جهده. وقرئ: كذابا، وهو جمع كاذب، أى: كذبوا بآياتنا كاذبين، وقد يكون الكذاب بمعنى الواحد البليغ في الكذب، يقال: رجل كذاب، كقولك: حسان، وبخال، فيجعل صفة لمصدر كذبوا، أى: تكذيبا كذابا مفرطا كذبه، وقرأ أبو السمال: وكل شيء أحصيناه، بالرفع على الابتداء كِتاباً مصدر في موضع إحصاء وأحصينا في معنى كتبنا، لالتقاء الإحصاء، والكتبة في معنى الضبط والتحصيل. أو يكون حالا في معنى: مكتوبا في اللوح وفي صحف الحفظة. والمعنى: إحصاء معاصيهم، كقوله: أَحْصاهُ اللَّهُ وَنَسُوهُ وهو اعتراض. وقوله فَذُوقُوا مسبب عن كفرهم بالحساب وتكذيبهم بالآيات، وهي آية في غاية الشدّة، وناهيك بلن نزيدكم، وبدلالته على أن ترك الزيادة كالمحال الذي لا يدخل تحت الصحة. وبمجيئها على طريقة الالتفات شاهدا على أنّ الغضب قد تبالغ، وعن النبي ﷺ: «هذه الآية أشدّ ما في القرآن على أهل النار» [[أخرجه ابن أبى حاتم والثعلبي من رواية جسر بن فرقد السبخى عن الحسن سألت أبا برزة الأسلمي فذكره وجسر ضعيف. ورواه الطبراني والبيهقي في الشعب موقوفا.]] .',     source_page = '294',     updated_at  = datetime('now') WHERE id = 'QR:TE:87ffa68c793f8a29584cd87e';
UPDATE qr_tafsir_entries SET content_ar = 'وَيَذَرَكَ عطف على لِيُفْسِدُوا لأنه إذا تركهم ولم يمنعهم، وكان ذلك مؤدّيا إلى ما دعوه فساداً وإلى تركه وترك آلهته، فكأنه تركهم لذلك. أو هو جواب للاستفهام بالواو كما يجاب بالفاء، نحو قول الحطيئة: ألم أك جاركم ويكون بيني ... وبينكم المودّة والإخاء [[تقدم شرح هذا الشاهد بالجزء الأول فراجعه إن شئت اهـ مصححه]] والنصب بإضمار «أن» تقديره: أيكون منك ترك موسى، ويكون تركه إياك وآلهتك. وقرئ: ويذرك وآلهتك بالرفع عطفا على أتذر موسى، بمعنى: أتذره وأ يذرك، يعنى: تطلق له ذلك. أو يكون مستأنفا أو حالا على معنى: أتذره وهو يذرك وآلهتك. وقرأ الحسن: ويذرك بالجزم، كأنه قيل: يفسدوا، كما قرئ وَأَكُنْ مِنَ الصَّالِحِينَ كأنه قيل: أصدّق. وقرأ أنس رضى الله عنه: ونذرك، بالنون والنصب، أى يصرفنا عن عبادتك فنذرها. وقرئ: ويذرك وإلاهتك، أى عبادتك. وروى أنهم قالوا له ذلك، لأنه وافق السحرة على الإيمان ستمائة ألف نفس، فأرادوا بالفساد في الأرض ذلك وخافوا أن يغلبوا على الملك، وقيل: صنع فرعون لقومه أصناما وأمرهم أن يعبدوها تقربا إليه كما يعبد عبدة الأصنام الأصنام، ويقولون: ليقربونا إلى الله زلفى، ولذلك قال: أنا ربكم الأعلى سَنُقَتِّلُ أَبْناءَهُمْ يعنى سنعيد عليهم ما كنا محناهم به من قتل الأبناء، ليعلموا أنا على ما كنا عليه من الغلبة والقهر، وأنهم مقهورون تحت أيدينا كما كانوا، وأن غلبة موسى لا أثر لها في ملكنا واستيلائنا، ولئلا يتوهم العامة أنه هو المولود الذي أخبر المنجمون والكهنة بذهاب ملكنا على يده، فيثبطهم ذلك عن طاعتنا ويدعوهم إلى اتباعه، وأنه منتظر بعد.',     source_page = '578',     updated_at  = datetime('now') WHERE id = 'QR:TE:bff6bbc4ba6b1216a1fcdd4a';
UPDATE qr_tafsir_entries SET content_ar = 'الاستدراج: استفعال من الدرجة بمعنى الاستصعاد، أو الاستنزال درجة بعد درجة. قال الأعشى: فلو كنت في جبّ ثمانين قامة ... ورقيت أسباب السّماء بسلّم ليستدر جنك القول حتّى تهرّه ... وتعلم أنّى عنكم غير مفحم [[مر شرح هذا الشاهد بالجزء الأول فراجعه إن شئت اه مصححه.]] ومنه: درج الصبى إذا قارب بين خطاه. وأدرج الكتاب: طواه شيئاً بعد شيء. ودرج القوم: مات بعضهم في أثر بعض. ومعنى سَنَسْتَدْرِجُهُمْ سنستدنيهم قليلا قليلا إلى ما يهلكهم ويضاعف عقابهم مِنْ حَيْثُ لا يَعْلَمُونَ ما يراد بهم. وذلك أن يواتر الله نعمه عليهم مع انهماكهم في الغىّ، فكلما جدّد عليهم نعمة ازدادوا بطراً وجدّدوا معصية، فيتدرّجون في المعاصي بسبب ترادف النعم، ظانين أنّ مواترة النعم أثرة من الله وتقريب، وإنما هي خذلان منه وتبعيد، فهو استدراج الله تعالى، نعوذ بالله منه وَأُمْلِي لَهُمْ عطف على سَنَسْتَدْرِجُهُمْ وهو داخل في حكم السين إِنَّ كَيْدِي مَتِينٌ سماه كيداً لأنه شبيه بالكيد، من حيث أنه في الظاهر إحسان وفي الحقيقة خذلان ما بِصاحِبِهِمْ بمحمد ﷺ مِنْ جِنَّةٍ من جنون، وكانوا يقولون شاعر مجنون. وعن قتادة أنّ النبي ﷺ علا الصفا فدعاهم فخذاً فخذاً يحذرهم بأس الله، فقال قائلهم: إن صاحبكم هذا لمجنون، بات يهوّت [[قوله «بات يهوت» أى يضيح. (ع)]] إلى الصباح [[أخرجه الطبري بإسناد صحيح إلى قتادة قال «ذكر لنا- فذكره. فأنزل الله أَوَلَمْ يَتَفَكَّرُوا ما بِصاحِبِهِمْ مِنْ جِنَّةٍ الآية]] أَوَلَمْ يَنْظُرُوا نظر استدلال فِي مَلَكُوتِ السَّماواتِ وَالْأَرْضِ فيما تدلان عليه من عظم الملك. والملكوت: الملك العظيم وَما خَلَقَ اللَّهُ مِنْ شَيْءٍ وفيما خلق الله مما يقع عليه اسم الشيء، من أجناس لا يحصرها العدد ولا يحيط بها الوصف وَأَنْ عَسى أن مخففة من الثقيلة، والأصل: وأنه عسى، على أن الضمير ضمير الشأن. والمعنى: أو لم ينظروا في أن الشأن والحديث عسى أَنْ يَكُونَ قَدِ اقْتَرَبَ أَجَلُهُمْ ولعلهم يموتون عما قريب، فيسارعوا إلى النظر وطلب الحق وما ينجيهم. قبل مغافصة الأجل [[قوله «قبل مغافصة الأجل» أى أخذه إياهم على حين غفلة. اه من الصحاح. (ع)]] وحلول العقاب. ويجوز أن يراد باقتراب الأجل: اقتراب الساعة، ويكون من «كان» التي فيها ضمير الشأن. فإن قلت: بم يتعلق قوله فَبِأَيِّ حَدِيثٍ بَعْدَهُ يُؤْمِنُونَ؟ قلت: بقوله عَسى أَنْ يَكُونَ قَدِ اقْتَرَبَ أَجَلُهُمْ كأنه قيل: لعلّ أجلهم قد اقترب، فما لهم لا يبادرون إلى الإيمان بالقرآن قبل الفوت، وماذا ينتظرون بعد وضوح الحقِّ، وبأىّ حديث أحقّ منه يريدون أن يؤمنوا.',     source_page = '395',     updated_at  = datetime('now') WHERE id = 'QR:TE:8948f8c6fb4e35a8ed65e7bb';
UPDATE qr_tafsir_entries SET content_ar = 'مكية، وآياتها 29 [نزلت بعد المسد] بِسْمِ اللَّهِ الرَّحْمنِ الرَّحِيمِ في التكوير وجهان: أن يكون من كوّرت العمامة إذا لففتها، أى: يلف ضوءها لفا فيذهب انبساطه وانتشاره في الآفاق، وهو عبارة عن إزالتها والذهاب بها، لأنها ما دامت باقية كان ضياؤها منبسطا غير ملفوف. أو يكون لفها عبارة عن رفعها وسترها، لأنّ الثواب إذا أريد رفعه لف وطوى، ونحوه قوله يَوْمَ نَطْوِي السَّماءَ وأن يكون من طعنه فجوّره وكوّره: إذا ألقاه، أى: تلقى وتطرح عن فلكها، كما وصفت النجوم بالانكدار. فإن قلت: ارتفاع الشمس على الابتداء أو الفاعلية؟ قلت: بل على الفاعلية رافعها فعل مضمر يفسره كوّرت، لأنّ «إذا» يطلب الفعل لما فيه من معنى الشرط انْكَدَرَتْ انقضت. قال: أبصر خربان فضاء فانكدر [[إذا الكرام ابتدروا الباع بدر ... تقضى البازي إذا البازي كسر «انى جناحيه من الطود فمر ... أبصر خربان فضاء فانكدر العجاج يمدح عمر بن عبيد الله التميمي. والباع بالمهملة: قدر مد اليدين، والمراد به الكرم مجازا. وبدر: أسرع وغلب الكرام، وتقضى: نصب به، وأصله: تقضض، أبدل الثاني حرف علة وكسر الأول، أى: أمال جناحيه وداناهما من الجبل العظيم، ومر: سار على وجه الجبل. وخربان- جمع خرب-: طائر يقال له الحبارى، وهو مضاف لفضاء، فانكدر: أى انقض وسقط عليها فيأكلها. ويروى صدر هذا الرجز: لقد سما ابن معمر حين اعتمر ... مغزى بعيدا من بعيد وضبر تقضى البازي ... الخ. واعتمر: أى زار. والمغزى: مكان الغزو. وضبره ضبرا: جمعه جمعا. يقول: ارتفع قدره حين غزا موضعا بعيدا من الشام، وجمع لذلك جيشا عظيما، وأسرع كاسراع البازي إلى الحبارى: بالغ في وصف البازي تصويرا لحال المشبه، ومبالغة في مدحه.]] ويروى في الشمس والنجوم: أنها تطرح في جهنم ليراها من عبدها، كما قال إِنَّكُمْ وَما تَعْبُدُونَ مِنْ دُونِ اللَّهِ حَصَبُ جَهَنَّمَ. سُيِّرَتْ أى على وجه الأرض وأبعدت. أو سيرت في الجوّ تسيير السحاب كقوله وَهِيَ تَمُرُّ مَرَّ السَّحابِ. والعشار في جمع عشراء، كالنفاس في جمع نفساء: وهي التي أتى على حملها عشرة أشهر، ثم هو اسمها إلى أن تضع لتمام السنة، وهي أنفس ما تكون عند أهلها وأعزها عليهم عُطِّلَتْ تركت مسيبة مهملة. وقيل: عطلها أهلها عن الحلب والصر، لاشتغالهم بأنفسهم. وقرئ: عطلت، بالتخفيف حُشِرَتْ جمعت من كل ناحية. قال قتادة: يحشر كل شيء حتى الذباب للقصاص. وقيل: إذا قضى بينها ردّت ترابا فلا يبقى منها إلا ما فيه سرور لبنى آدم وإعجاب بصورته، كالطاوس ونحوه. وعن ابن عباس رضى الله عنهما: حشرها موتها. يقال: إذا أجحفت السنة بالناس وأموالهم حشرتهم السنة. وقرئ: حشرت، بالتشديد سُجِّرَتْ قرئ بالتخفيف والتشديد، من سجر التنور: إذا ملأه بالحطب، أى: ملئت وفجر بعضها إلى بعض حتى تعود مجرا واحدا. وقيل: ملئت نيرانا تضطرم لتعذيب أهل النار. وعن الحسن: يذهب ماؤها فلا تبقى فيها قطرة زُوِّجَتْ قرنت كل نفس بشكلها. وقيل: قرنت الأرواح بالأجساد. وقيل بكتبها وأعمالها. وعن الحسن: هو كقوله وَكُنْتُمْ أَزْواجاً ثَلاثَةً وقيل: نفوس المؤمنين بالحور، ونفوس الكافرين بالشياطين. وأد يئد مقلوب من آد يئود: إذا أثقل. قال الله تعالى وَلا يَؤُدُهُ حِفْظُهُما لأنه إثقال بالتراب: كان الرجل إذا ولدت له بنت فأراد أن يستحييها: ألبسها جبة من صوف أو شعر ترعى له الإبل والغنم في البادية، وإن أراد قتلها تركها حتى إذا كانت سداسية فيقول لأمها: طيبيها وزينيها، حتى أذهب بها إلى أحمائها، وقد حفر لها بئرا في الصحراء، فيبلغ بها البئر فيقول لها: انظري فيها، ثم يدفعها من خلفها ويهيل عليها، حتى تستوي البئر بالأرض. وقيل: كانت الحامل إذا أقربت حفرت حفرة فتمخضت على رأس الحفرة، فإذا ولدت بنتا رمت بها في الحفرة، وإن ولدت ابنا حبسته. فإن قلت: ما حملهم على وأد البنات؟ قلت: الخوف من لحوق العار بهم من أجلهنّ. أو الخوف من الإملاق، كما قال الله تعالى وَلا تَقْتُلُوا أَوْلادَكُمْ خَشْيَةَ إِمْلاقٍ وكانوا يقولون: إن الملائكة بنات الله، فألحقوا البنات به، فهو أحق بهنّ. وصعصعة بن ناجية ممن منع الوأد، فبه افتخر الفرزدق في قوله: ومنّا الّذى منع الوائدات ... فأحيا الوئيد فلم توأد [[للفرزدق، يفتخر يجده صعصعة: قدم على رسول الله ﷺ فأسلم وقال: يا رسول الله، عملت أعمالا في الجاهلية فهل لي فيها من أجر؟ فقال: وما عملت؟ قال: قد أحييت ثلاثا وستين من الموؤدة أشترى الواحدة منهن بناقتين عشراويتين وجمل، فقال ﷺ: هذا من باب البر ولك أجره إذ من الله عليك بالإسلام. ويقال: وأد بنته إذا دفنها وهي حية، وكانت كندة تفعل ذلك خوف العار والفقر. ويروى: فأحيا الوئيد وهي أوقع. والوئيد يقال للمفرد والجمع مذكرا أو مؤنثا. ويروى: وجدي، أى: هو الذي منع الجماعات الدافنات بناتهن حيات وفداهن من الموت، فكأنه أحياهن، فأطلق الوئيد على المشرفات على الموت مجازا، والأحياء ترشيح.]] فإن قلت: فما معنى سؤال الموؤدة عن ذنبها الذي قتلت به، وهلا سئل الوائد عن موجب قتله لها؟ قلت: سؤالها وجوابها تبكيت لقاتلها نحو التبكيت في قوله تعالى لعيسى أَأَنْتَ قُلْتَ لِلنَّاسِ ... إلى قوله ... سُبْحانَكَ ما يَكُونُ لِي أَنْ أَقُولَ ما لَيْسَ لِي بِحَقٍّ وقرئ: سألت، أى: خاصمت عن نفسها، وسألت الله أو قاتلها، وإنما قيل قُتِلَتْ بناء على أن الكلام إخبار عنها، ولو حكى ما خوطبت به حين سئلت. فقيل: قتلت. أو كلامها حين سئلت لقيل: قتلت. وقرأ ابن عباس رضى الله عنهما: قتلت، على الحكاية. وقرئ: قتلت، بالتشديد. وفيه دليل بين على أن أطفال المشركين لا يعذبون، وعلى أن التعذيب لا يستحق إلا بالذنب، وإذا بكت الله الكافر ببراءة الموؤدة من الذنب: فما أقبح به، وهو الذي لا يظلم مثقال ذرّة أن يكرّ عليها بعد هذا التبكيت فيفعل بها ما تنسى عنده فعل المبكت من العذاب الشديد السرمد. وعن ابن عباس رضى الله عنهما أنه سئل عن ذلك، فاحتجّ بهذه الآية نُشِرَتْ قرئ بالتخفيف والتشديد، يريد: صحف الأعمال تطوى صحيفة الإنسان عند موته، ثم تنشر إذا حوسب. عن قتادة: صحيفتك يا ابن آدم تطوى على عملك، ثم تنشر يوم القيامة، فلينظر رجل ما يملى في صحيفته. وعن عمر رضى الله عنه أنه كان إذا قرأها قال: إليك يساق الأمر يا ابن آدم. وعن النبي ﷺ أنه قال: «يحشر الناس عراة حفاة» فقالت أمّ سلمة: كيف بالنساء؟ فقال: شغل الناس يا أمّ سلمة» قالت: وما شغلهم؟ قال: نشر الصحف فيها مثاقيل الذرّ ومثاقيل الخردل [[أخرجه الثعلبي من طريق محمد بن أبى موسى عن عطاء بن يسار عن أم سلمة بهذا. وأصله في الصحيحين عن عائشة، وأخرجه الحاكم من حديث سودة.]] ويجوز أن يراد: نشرت بين أصحابها، أى فرقت بينهم. وعن مرثد بن وداعة: إذا كان يوم القيامة تطايرت الصحف من تحت العرش، فتقع صحيفة المؤمن في يده في جنة عالية، وتقع صحيفة الكافر في يده في سموم وحميم أى مكتوب فيها ذلك، وهي صحف غير صحف الأعمال كُشِطَتْ كشفت وأزيلت، كما يكشط الإهاب عن الذبيحة، والغطاء عن الشيء. وقرأ ابن مسعود: قشطت. واعتقاب الكاف والقاف كثير. يقال: لبكت الثريد ولبقته، والكافور والقافور سُعِّرَتْ أو قدت إيقادا شديدا. وقرئ: سعرت بالتشديد للمبالغة. قيل: سعرها عضب الله تعالى وخطايا بنى آدم أُزْلِفَتْ أدنيت من المتقين، كقوله تعالى وَأُزْلِفَتِ الْجَنَّةُ لِلْمُتَّقِينَ غَيْرَ بَعِيدٍ قيل: هذه اثنتا عشرة خصلة. ست منها في الدنيا، وست في الآخرة. وعَلِمَتْ: هو عامل النصب في إِذَا الشَّمْسُ كُوِّرَتْ وفيما عطف عليه. فإن قلت: كل نفس تعلم ما أحضرت، كقوله يَوْمَ تَجِدُ كُلُّ نَفْسٍ ما عَمِلَتْ مِنْ خَيْرٍ مُحْضَراً لا نفس واحدة. فما معنى قوله عَلِمَتْ نَفْسٌ؟ قلت: هو من عكس كلامهم الذي يقصدون به الإفراط فيما بعكس عنه. ومنه قوله عز وجل: رُبَما يَوَدُّ الَّذِينَ كَفَرُوا لَوْ كانُوا مُسْلِمِينَ ومعناه: معنى كم وأبلغ منه. وقول القائل: قد أترك القرن مصفرّا أنامله [[تقدم شرح هذا الشاهد بالجزء الأول فراجعه إن شئت اه مصححه.]] وتقول لبعض قوّاد العساكر: كم عندك من الفرسان؟ فيقول: رب فارس عندي. أولا تعدم عندي فارسا، وعنده المقانب [[قوله «وعنده المقانب في الصحاح «المقنب» : ما بين لثلاثين إلى الأربعين من الخيل. (ع)]] ، وقصده بذلك التمادي في تكثير فرسانه، ولكنه أراد إظهار براءته من التزيد، وأنه ممن يقلل كثير ما عنده، فضلا أن يتزيد، فجاء بلفظ التقليل، ففهم منه معنى الكثرة على الصحة واليقين. وعن ابن مسعود رضى الله عنه أنّ قارئا قرأها عنده، فلما بلغ عَلِمَتْ نَفْسٌ ما أَحْضَرَتْ قال: وانقطاع ظهرياه.',     source_page = '202',     updated_at  = datetime('now') WHERE id = 'QR:TE:0e923aa10792fdc9448b4416';
UPDATE qr_tafsir_entries SET content_ar = 'الكدح: جهد النفس في العمل والكدّ فيه حتى يؤثر فيها، من كدح جلده: إذا خدشه. ومعنى كادِحٌ إِلى رَبِّكَ جاهد إلى لقاء ربك، وهو الموت وما بعده من الحال الممثلة باللقاء فَمُلاقِيهِ فملاق له لا مجالة لا مفرّ لك منه، وقيل: الضمير في ملاقيه للكدح يَسِيراً سهلا هينا لا يناقش فيه ولا يعترض بما يسوءه ويشق عليه، كما يناقش أصحاب الشمال. وعن عائشة رضى الله عنها: هو أن يعرّف ذنوبه، ثم يتجاوز عنه. وعن النبي ﷺ أنه قال: «من يحاسب يعذب» فقيل يا رسول الله: فسوف يحاسب حسابا يسيرا. قال «ذلكم العرض، من نوقش في الحساب عذب» [[متفق عليه من حديث عائشة.]] إِلى أَهْلِهِ إلى عشيرته إن كانوا مؤمنين. أو إلى فريق المؤمنين. أو إلى أهله في الجنة من الحور العين وَراءَ ظَهْرِهِ قيل: تغل يمناه إلى عنقه، وتجعل شماله وراء ظهره، فيؤتى كتابه بشماله من وراء ظهره. وقيل تخلع يده اليسرى من وراء ظهره. يَدْعُوا ثُبُوراً يقول: يا ثبوراه. والثبور: الهلاك. وقرئ: ويصلى سعيرا، كقوله وَتَصْلِيَةُ جَحِيمٍ ويصلى: بضم الياء والتخفيف، كقوله وَنُصْلِهِ جَهَنَّمَ. فِي أَهْلِهِ فيما بين ظهرانيهم: أو معهم، على أنهم كانوا جميعا مسرورين، يعنى أنه كان في الدنيا مترفا بطرا مستبشرا كعادة الفجار الذين لا يهمهم أمر الآخرة ولا يفكرون في العواقب، ولم يكن كئيبا حزينا متفكرا كعادة الصلحاء والمتقين وحكاية الله عنهم إِنَّا كُنَّا قَبْلُ فِي أَهْلِنا مُشْفِقِينَ. ظَنَّ أَنْ لَنْ يَحُورَ لن يرجع إلى الله تعالى تكذيبا بالمعاد. يقال: لا يحور ولا يحول، أى: لا يرجع ولا يتغير. قال لبيد: يحور رمادا بعد إذ هو ساطع [[تقدم شرح هذا الشاهد بالجزء الرابع فراجعه إن شئت اه مصححه.]] وعن ابن عباس: ما كنت أدرى ما معنى يحور حتى سمعت أعرابية تقول لبنية لها: حورى، أى: ارجعي بَلى إيجاب لما بعد النفي في لَنْ يَحُورَ أى: بلى ليحورنّ إِنَّ رَبَّهُ كانَ بِهِ بَصِيراً وبأعماله لا ينساها ولا تخفى عليه، فلا بدّ أن يرجعه ويجازيه عليها. وقيل: نزلت الآيتان في أبى سلمة بن عبد الأشدّ وأخيه الأسود بن عبد الأشد.',     source_page = '13',     updated_at  = datetime('now') WHERE id = 'QR:TE:cf515cf1b3b61bd0fc052932';
UPDATE qr_tafsir_entries SET content_ar = 'فإن قلت: أين جواب القسم؟ قلت: محذوف يدل عليه قوله قُتِلَ أَصْحابُ الْأُخْدُودِ كأنه قيل: أقسم بهذه الأشياء أنهم ملعونون، يعنى كفار قريش كما لعن أصحاب الأخدود، وذلك أن السورة وردت في تثبيت المؤمنين وتصبيرهم على أذى أهل مكة، وتذكيرهم بما جرى على من تقدّمهم: من التعذيب على الإيمان. وإلحاق أنواع الأذى، وصبرهم وثباتهم، حتى يأنسوا بهم ويصبروا على ما كانوا يلقون من قومهم، ويعلموا أن كفارهم عند الله بمنزلة أولئك المعذبين المحرقين بالنار، ملعونون أحقاء بأن يقال فيهم: قتلت قريش، كما قيل: قتل أصحاب الأخدود وقتل: دعاء عليهم، كقوله قُتِلَ الْإِنْسانُ ما أَكْفَرَهُ وقرئ: قتل، بالتشديد. والأخدود: الخدّ في الأرض وهو الشق، ونحوهما بناء ومعنى: الخق والأخقوق. ومنه فساخت قوائمه في أخاقيق جرذان [[قوله «جرذان» في الصحاح «الجرذ» : ضرب من الفأر والجمع: الجرذان. (ع)]] . روى عن النبي ﷺ أنه قال: كان لبعض الملوك ساحر، فلما كبر ضمّ إليه غلاما ليعلمه السحر، وكان في طريق الغلام راهب: فسمع منه، فرأى في طريقه ذات يوم دابة قد حبست الناس. فأخذ حجرا فقال: اللهم إن كان الراهب أحبّ إليك من الساحر فاقتلها، فقتلها، فكان الغلام بعد ذلك يبرئ الأكمه والأبرص، ويشفى من الأدواء، وعمى جليس للملك فأبرأه فأبصره الملك فسأله فقال: من ردّ عليك بصرك؟ فقال: ربى، فغضب فعذبه. فدل على الغلام فعذبه، فدل على الراهب، فلم يرجع الراهب عن دينه، فقدّ بالمنشار وأبى الغلام فذهب به إلى جبل ليطرح من ذروته، فدعا فرجب بالقوم، فطاحوا ونجا، فذهب به إلى قرقور [[قوله «قرقور» في الصحاح «القرقور» : السفينة الطويلة. (ع)]] فلججوا به ليغرقوه، فدعا فانكفأت بهم السفينة، فغرقوا ونجا، فقال للملك: لست بقاتلي حتى تجمع الناس في صعيد وتصلبني على جذع وتأخذ سهما من كنانتي وتقول: بسم الله رب الغلام، ثم ترميني به. فرماه فوقع في صدغه فوضع يده عليه ومات، فقال الناس: آمنا برب الغلام، فقيل للملك. نزل بك ما كنت تحذر، فأمر بأخاديد في أفواه السكك وأو قدت فيها النيران فمن لم يرجع منهم طرحه فيها حتى جاءت امرأة معها صبى فتقاعست [[قوله «فتقاعست» في الصحاح «تقاعس» : إذا تأخر عن الأمر ولم يتقدم. (ع)]] أن تقع فيها، فقال الصبى: يا أماه، اصبري فإنك على الحق، فاقتحمت. وقيل: قال لها قعى ولا تنافقى. وقيل: قال لها ما هي إلا غميضة فصبرت [[أخرجه مسلم. والترمذي والنسائي وابن حبان والطبري والطبراني وأحمد وإسحاق وأبو يعلى والبزار كلهم من رواية ابن أبى ليلى من طرق وأقربها إلى لفظ الكتاب سياق الطبري. تفرد به ثابت البناني عن عبد الرحمن.]] . وعن على رضى الله عنه: أنهم حين اختلفوا في أحكام المجوس قال: هم أهل كتاب وكانوا متمسكين بكتابهم، وكانت الخمر قد أحلت لهم، فتناولها بعض ملوكهم فسكر، فوقع على أخته فلما صحا ندم وطلب المخرج، فقالت له: المخرج أن تخطب الناس فتقول: يا أيها الناس، إنّ الله أحل نكاح الأخوات، ثم تخطبهم بعد ذلك فتقول: إن الله حرّمه، فخطب فلم يقبلوا منه فقالت له: ابسط فيهم السوط، فلم يقبلوا، فقالت له: ابسط فيهم السيف، فلم يقبلوا، فأمرته بالأخاديد وإيقاد النيران وطرح من أبى فيها، فهم الذين أرادهم الله بقوله قُتِلَ أَصْحابُ الْأُخْدُودِ [[أخرجه مسلم والترمذي والنسائي وأبو يعلى. والطبري والطبراني. وأحمد وإسحاق والبزار كلهم من رواية عبد الرحمن بن حميد والطبري من رواية جعفر بن أبى المغيرة عن عبد الرحمن بن أيزى قال «لما هزم المسلمون أهل الاسفيذيان انصرفوا فجاءهم يعنى عمر رضى الله عنه. فاجتمعوا فقالوا. أى شيء يجرى على المجوس من الأحكام؟ نهم ليسوا أهل كتاب. وليسوا من مشركي العرب. فقال: هم أهل الكتاب. فذكره. وسياق الطبري أتم منه]] وقيل: وقع إلى نجران رجل ممن كان على دين عيسى عليه السلام، فدعاهم فأجابوه فسار إليهم ذو نواس اليهودي بجنود من حمير، فخيرهم بين النار واليهودية فأبوا، فأحرق منهم اثنى عشر ألفا في الأخاديد. وقيل: سبعين ألفا [[أخرجه ابن إسحاق في السيرة، حدثني يزيد بن أبى زياد عن محمد بن كعب. فذره مطولا.]] ، وذكر أنّ طول الأخدود: أربعون ذراعا وعرضه اثنا عشر ذراعا [[نقله الثعلبي عن الكلبي.]] . وعن النبي ﷺ أنه كان إذا ذكر أصحاب الأخدود تعوّذ من جهد البلاء [[أخرجه ابن أبى شيبة عن أبى أسامة عن عوف عن الحسن بهذا.]] النَّارِ بدل اشتمال من الأخدود ذاتِ الْوَقُودِ وصف لها بأنها نار عظيمة لها ما يرتفع به لهبها من الحطب الكثير وأبدان الناس، وقرئ: الوقود، بالضم إِذْ ظرف لقتل، أى لعنوا حين أحدقوا بالنار قاعدين حولها. ومعنى عَلَيْها على ما يدنو منها من حافات الأخدود، كقوله: وبات على النّار النّدى والمحلّق [[تقدم شرح هذا الشاهد بالجزء الثالث فراجعه إن شئت اه مصححه.]] وكما تقول: مرت عليه، تريد: مستعليا لمكان يدنو منه، ومعنى شهادتهم على إحراق المؤمنين: أنهم وكلوا بذلك وجعلوا شهودا يشهد بعضهم لبعض عند الملك أنّ أحدا منهم لم يفرط فيما أمر به وفوض إليه من التعذيب. ويجوز أن يراد: أنهم شهود على ما يفعلون بالمؤمنين، يؤدّون شهادتهم يوم القيامة يَوْمَ تَشْهَدُ عَلَيْهِمْ أَلْسِنَتُهُمْ وَأَيْدِيهِمْ وَأَرْجُلُهُمْ بِما كانُوا يَعْمَلُونَ. وَما نَقَمُوا مِنْهُمْ وما عابوا منهم وما أنكروا إلا الإيمان، كقوله: ولا عيب فيهم غير أنّ سيوفهم [[تقدم شرح هذا الشاهد بالجزء الثاني فراجعه إن شئت اه مصححه.]] قال ابن الرقيات: ما نقموا من بنى أميّة إلّا ... أنّهم يحلمون إن غضبوا [[لقيس الرقيات. ونقموا كرهوا: وحلم- كظرف-: صفح. يقول: إنهم جعلوا أحسن الأشياء وهو الحلم عند الغضب قبيحا. ويجوز أن فاعل الفعلين ضمير بنى أمية. ويجوز أن الأول لهم، والثاني: الناقمين. وفيه استتباع المدح بما يشبه الذم للمبالغة في المدح، حيث جعل الحلم عند الغضب ذما، مع أنه غاية في المدح. ويروى ما نقم الناس، وعليها فالصواب إسقاط «بين» لأجل الوزن.]] وقرأ أبو حيوة: نقموا، بالكسر، والفصيح: هو الفتح. وذكر الأوصاف التي يستحق بها أن يؤمن به ويعبد، وهو كونه عزيزا غالبا قادرا يخشى عقابه حميدا منعما. يجب له الحمد على نعمته ويرجى ثوابه لَهُ مُلْكُ السَّماواتِ وَالْأَرْضِ فكل من فيهما تحق عليه عبادته والخشوع له تقديرا، لأن ما نَقَمُوا مِنْهُمْ هو الحق الذي لا ينقمه إلا مبطل منهمك في الغىّ، وإن الناقمين أهل لانتقام الله منهم بعذاب لا يعدله عذاب وَاللَّهُ عَلى كُلِّ شَيْءٍ شَهِيدٌ وعيد لهم، يعنى أنه علم ما فعلوا، وهو مجازيهم عليه.',     source_page = '53',     updated_at  = datetime('now') WHERE id = 'QR:TE:1a765b955b645307ba47e535';
UPDATE qr_tafsir_entries SET content_ar = 'إِنَّهُ الضمير للخالق، لدلالة خلق عليه. ومعناه: إنّ ذلك الذي خلق الإنسان ابتداء من نطفة عَلى رَجْعِهِ على إعادته خصوصا لَقادِرٌ لبين القدرة لا يلتاث [[قوله «لا يلتاث عليه» في الصحاح «التاث في عمله» : أى أبطأ. (ع)]] عليه ولا يعجز عنه. كقوله: إننى لفقير [[قوله «كقوله إننى لفقير» أى الشاعر، حيث قال: لئن كان يهدى برد أنيابها العلى ... لأفقر منى إننى لفقير (ع) وقد تقدم شرح هذا الشاهد بهذا الجزء فراجعه إن شئت اه مصححه.]] يَوْمَ تُبْلَى منصوب برجعه، ومن جعل الضمير في رَجْعِهِ للماء وفسره برجعه إلى مخرجه من الصلب والترائب أو الإحليل. أو إلى الحالة الاولى نصب الظرف بمضمر السَّرائِرُ ما أسرّ في القلوب من العقائد والنيات وغيرها، وما أخفى من الأعمال. وبلاؤها. تعرّفها وتصفحها، والتمييز بين ما طاب منها وما خبث. وعن الحسن أنه سمع رجلا ينشد: سيبقى لها في مضمر القلب والحشا ... سريرة ودّ يوم تبلى السّرائر [[إذا رمت عنها سلوة قال شافع ... من الحب ميعاد السلو المقابر سيقى لها في مضمر القلب والحشا ... سريرة ود يوم تبلى السرائر لمجنون بنى عامر صاحب ليلى العامرية. وسلا عنه سلوة وسلوا: صد عنه وأعرض، وشبه بعث الحب إياه وحمله على دوام المودة بقول القائل على طريق التصريحية، وتسمية الحب شافعا: ترشيح. ومن بيانية. ويحتمل أنها تجريدية دلالة على أن الحب بلغ نهاية اللذة حتى حمل على دوام المودة فانتزع منه غيره وأسند له الفعل. ويجوز أنها تبعيضية دالة على أن بعضه يكفى في الشفاعة. وقوله «المقابر» أى دخولها، كناية عن الموت. والمراد: التأبيد، بدليل ما بعده. ومضمر القلب: المضمر في القلب. أو مضمر هو القلب. وتبلى: مبنى للفاعل، أى: تفنى. ويحتمل بناءه للمفعول، أى: تختبر. والحشا- بالفتح-: عطف على القلب أعم منه، دلالة على أن الحب في غير قلبه أيضا.]] فقال: ما أغفله عما في وَالسَّماءِ وَالطَّارِقِ؟ فَما لَهُ فما للإنسان مِنْ قُوَّةٍ من منعة في نفسه يمتنع بها وَلا ناصِرٍ ولا مانع يمنعه.',     source_page = '23',     updated_at  = datetime('now') WHERE id = 'QR:TE:8d4dc5a660fe79c78492ed30';
UPDATE qr_tafsir_entries SET content_ar = 'جنح له وإليه: إذا مال. والسلم تؤنث تأنيث نقيضها وهي الحرب قال: السِّلْمُ تَأْخُذُ مِنْهَا مَا رَضِيتَ بِهِ ... وَالْحَرْبُ يَكْفِيكَ مِنْ أَنْفَاسِهَا جُرَعُ [[مر شرح هذا الشاهد بالجزء الأول فراجعه إن شئت اه مصححه.]] وقرئ بفتح السين وكسرها. وعن ابن عباس رضى الله عنه أن الآية منسوخة بقوله تعالى قاتِلُوا الَّذِينَ لا يُؤْمِنُونَ بِاللَّهِ وعن مجاهد بقوله فَاقْتُلُوا الْمُشْرِكِينَ حَيْثُ وَجَدْتُمُوهُمْ والصحيح أن الأمر موقوف على ما يرى فيه الامام صلاح الإسلام وأهله من حرب أو سلم، وليس بحتم أن يقاتلوا أبدا، أو يجابوا إلى الهدنة أبداً. وقرأ الأشهب العقيلي. فاجنح بضم النون وَتَوَكَّلْ عَلَى اللَّهِ ولا تخف من إبطانهم المكر في جنوحهم إلى السلم، فإنّ الله كافيك وعاصمك من مكرهم وخديعتهم. قال مجاهد، يريد قريظة.',     source_page = '252',     updated_at  = datetime('now') WHERE id = 'QR:TE:4f77afe2e20985a29ce3a064';
UPDATE qr_tafsir_entries SET content_ar = 'مدنية وقيل مكية، وآياتها 8 [نزلت بعد النساء] بِسْمِ اللَّهِ الرَّحْمنِ الرَّحِيمِ زِلْزالَها قرئ بكسر الزاى وفتحها، فالمكسور مصدر، والمفتوح: اسم، وليس في الأبنية فعلال بالفتح إلا في المضاعف. فإن قلت: ما معنى زلزالها بالإضافة؟ قلت: معناه زلزالها الذي تستوجبه في الحكمة ومشيئة الله، وهو الزلزال الشديد الذي ليس بعده. ونحوه قولك: أكرم التقىّ إكرامه، وأهن الفاسق إهانته، تريد: ما يستوجبانه من الإكرام والإهانة أو زلزالها كله وجميع ما هو ممكن منه. الأثقال: جمع [[قوله «جمع ثقل وهو متاع» في الصحاح «الثقل» : واحد الأثقال، مثل حمل وأحمال. والثقل- بالتحريك متاع المسافر وحشمه. (ع)]] ثقل. وهو متاع البيت، وتحمل أثقالكم جعل ما في جوفها من الدفائن أثقالا لها وَقالَ الْإِنْسانُ ما لَها زلزلت هذه الزلزلة الشديدة ولفظت ما في بطنها، وذلك عند النفخة الثانية حين تزلزل وتلفظ أمواتها أحياء، فيقولون ذلك لما يبهرهم من الأمر الفظيع، كما يقولون: مَنْ بَعَثَنا مِنْ مَرْقَدِنا. وقيل: هذا قول الكافر، لأنه كان لا يؤمن بالبعث، فأما المؤمن فيقول: هذا ما وعد الرحمن وصدق المرسلون. فإن قلت: ما معنى تحديث الأرض والإيحاء لها؟ قلت: هو مجاز عن إحداث الله تعالى فيها من الأحوال ما يقوم مقام التحديث بالنسيان، حتى ينظر من يقول مالها إلى تلك الأحوال، فيعلم لم زلزلت ولم لفظت الأموات؟ وأنّ هذا ما كانت الأنبياء ينذرونه ويحذرون منه. وقيل: ينطقها الله على الحقيقة. وتخبر بما عمل عليها من خير وشر. وروى عن رسول الله ﷺ تشهد على كل أحد بما عمل على ظهرها [[أخرجه الترمذي والنسائي وابن حبان والحاكم من رواية ابن أيوب عن يحيى عن أبى سليمان المنقري عن أبى هريرة. وسعيد ثقة. وخالفه رشدين بن سعد وهو ضعيف فقال: عن يحيى بن أبى سليمان عن أبى حازم بالسندين المذكورين عن أنس بن مالك. وأخرجه ابن مردويه.]] . فإن قلت: إِذا، ويَوْمَئِذٍ: ما ناصبهما؟ قلت: يَوْمَئِذٍ: بدل من إِذا، وناصبهما تُحَدِّثُ. ويجوز أن ينتصب إِذا بمضمر، ويَوْمَئِذٍ بتحدث. فإن قلت: أين مفعولا تُحَدِّثُ؟ قلت: قد حذف أوّلهما، والثاني أخبارها، وأصله تحدث الخلق أخبارها، إلا أن المقصود ذكر تحديثها الأخبار لا ذكر الخلق تعظيما لليوم. فإن قلت: بم تعلقت الباء في قوله بِأَنَّ رَبَّكَ؟ قلت، بتحدّث، معناه: تحدّث أخبارها بسبب إيحاء ربك لها، وأمره إياها بالتحديث. ويجوز أن يكون المعنى: يومئذ تحدث بتحديث أنّ ربك أوحى لها أخبارها، على أن تحديثها بأن ربك أوحى لها: تحديث بأخبارها، كما تقول: نصحتني كل نصيحة، بأن نصحتني في الدين. ويجوز أن يكون بِأَنَّ رَبَّكَ بدلا من أَخْبارَها كأنه قيل: يومئذ تحدث بأخبارها بأن ربك أوحى لها، لأنك تقول: حدثته كذا وحدثته بكذا. وأَوْحى لَها بمعنى أوحى إليها، وهو مجاز كقوله أَنْ نَقُولَ لَهُ كُنْ فَيَكُونُ قال: أوحى لها القرار فاستقرّت [[تقدم شرح هذا الشاهد بالجزء الثالث فراجعه إن شئت اه مصححه.]] وقرأ ابن مسعود: تنبئ أخبارها، وسعيد بن جبير: تنبئ، بالتخفيف. يصدرون عن مخارجهم من القبور إلى الموقف أَشْتاتاً بيض الوجوه آمنين، وسود الوجوه فزعين. أو يصدرون عن الموقف أشتاتا يتفرق بهم طريقا الجنة والنار، ليروا جزاء أعمالهم. وفي قراءة النبي ﷺ: ليروا بالفتح. وقرأ ابن عباس وزيد بن على: يره، بالضم. ويحكى أنّ أعرابيا أخر خَيْراً يَرَهُ فقيل له، قدّمت وأخرت، فقال: خذا بطن هرشى أو قفاها فإنّه ... كلا جانبي هرشى لهنّ طريق [[روى أن أعرابيا أخر قوله تعالى خَيْراً يَرَهُ عما بعده، فقيل: قدمت وأخرت، فضرب ذلك البيت مثلا. وهرشى- كسكرى: ثنية في طريق مكة عند الجحفة، أى: اسلكا أما تلك الثنية أو خلفها، فانه أى: الحال والشأن كل من جانبيها طريق للإبل التي تطلبانها، وتكرير لفظ «هرشى» لتقريرها في ذهن السامع خوف غفلته عنها، والمقام كان مقام هداية، فحسن فيه ذلك.]] والذرّة: النملة الصغيرة، وقيل «الذرّ» ما يرى في شعاع الشمس من الهباء. فإن قلت حسنات الكافر محبطة بالكفر، وسيئات المؤمن معفوّة باجتناب الكبائر، فما معنى الجزاء بمثاقيل الذرّ من الخير والشر [[قال محمود: «إن قلت حسنات الكافر محبطة بالكفر ... الخ» قال أحمد: السؤال مبنى على قاعدتين، إحداهما: أن حسنات الكافر محبطة بالكفر، وهذه فيها نظر، فان حسنات الكافر محبطة، أى: لا يثاب عليها ولا ينعم. وأما تخفيف العذاب بسببها، فغير منكر، فقد وردت به الأحاديث الصحيحة. وقد ورد أن حاتما يخفف الله عنه لكرمه ومعروفه، وورد ذلك في حق غيره كأبى طالب أيضا، فحينئذ لحسنات الكافر أثر ما في تخفيف العذاب، فيمكن أن يكون المرئي هو ذلك الأثر، والله أعلم. وأما القاعدة الثانية: وهي القول بأن اجتناب الكبائر يوجب تمحيص الصغائر ويكفرها عن المؤمن، فمردود عند أهل السنة فان الصغائر عندهم حكمها في التكفير في حكم الكبائر: تكفر بأحد أمرين: إما بالتوبة النصوح المقبولة، وإما بالمشية لا غير ذلك. وأما اجتناب الكبيرة عندهم فلا يوجب التكفير للصغيرة، فالسؤال المذكور إذا ساقط عن أهل السنة، ولكن الزمخشري التزم الجواب عنه الزموه على قاعدته الفاسدة، والله الموفق.]] ؟ قلت: المعنى فمن يعمل مثقال ذرّة خيرا: من فريق السعداء. ومن يعمل مثقال ذرّة شرا: من فريق الأشقياء، لأنه جاء بعد قوله يَصْدُرُ النَّاسُ أَشْتاتاً، عن رسول الله ﷺ. «من قرأ سورة إذا زلزلت أربع مرات كان كمن قرأ القرآن كله» [[أخرجه الثعلبي من حديث على بإسناد أهل البيت، لكنه من رواية أبى القاسم الطائي. وهو ساقط وشاهده عند ابن أبى شيبة والبزار من رواية سلمة بن وردان عن أنس مرفوعا: إذا زلزلت تعدل ربع القرآن» وأخرجه ابن مردويه والواحدي باسناديهما إلى أبى بن كعب بلفظ «من قرأ إذا زلزلت أعطى من الأجر كمن قرأ القرآن.]] .',     source_page = '75',     updated_at  = datetime('now') WHERE id = 'QR:TE:da23fa65e3baf5102239000b';
UPDATE qr_tafsir_entries SET content_ar = 'معنى أكل الأموال على وجهين: إما أن يستعار الأكل للأخذ. ألا ترى إلى قولهم: أخذ الطعام وتناوله. وإمّا على أن الأموال يؤكل بها فهي سبب الأكل. ومنه قوله: إنَّ لَنَا أَحْمِرَةً عِجَافَا ... يَأْكُلْنَ كُلَّ لَيْلَةٍ إكافَا [[مر شرح هذا الشاهد بالجزء الأول فراجعه إن شئت اه مصححه.]] يريد: علفاً يشترى بثمن إكاف. ومعنى أكلهم بالباطل: أنهم كانوا يأخذون الرشا في الأحكام، والتخفيف والمسامحة في الشرائع وَالَّذِينَ يَكْنِزُونَ يجوز أن يكون إشارة إلى الكثير من الأحبار والرهبان، للدلالة على اجتماع خصلتين مذمومتين فيهم: أخذ البراطيل. وكنز الأموال، والضنّ بها عن الإنفاق في سبيل الخير. ويجوز أن يراد المسلمون الكانزون غير المنافقين، ويقرن بينهم وبين المرتشين من اليهود والنصارى، تغليظا ودلالة على أن من يأخذ منهم السحت، ومن لا يعطى منكم طيب ماله: سواء في استحقاق البشارة بالعذاب الأليم. وقيل: نسخت الزكاة آية الكنز. وقيل: هي ثابتة، وإنما عنى بترك الإنفاق في سبيل الله منع الزكاة. وعن النبي ﷺ «ما أدّى زكاته فليس بكنز وإن كان باطناً، وما بلغ أن يزكى فلم يزك فهو كنز وإن كان ظاهراً» [[أخرجه البيهقي من طريق محمد بن جبير عن سفيان عن عبد الله بن دينار عن ابن عمر مرفوعا بلفظ «كل ما أدى زكاته فليس بكنز وإن كان مدفونا، وكل مالا يؤدى زكاته فهو كنز وإن كان ظاهرا» قال البيهقي: ليس هذا بمحفوظ، والمشهور عن سفيان بن عبيد الله عن نافع عن ابن عمر قوله. ورواه الطبراني في الأوسط وابن مردويه وابن عدى من طريق سويد بن عبد العزيز عن عبيد الله بسنده مرفوعا، ولفظه «كل مال وإن كان تحت سبع أرضين يؤدى زكاته فليس بكنز، وكل مال لا يؤدى زكاته وإن كان ظاهرا فهو كنز» قال ابن عدى: وفيه سويد وغيره يرويه موقوفا والموقوف رواه عبد الرزاق عن عبيد الله العمرى موقوفا والشافعي عن ابن عيينة عن ابن عجلان عن نافع نحوه، وفي الباب عن أم سلمة قالت «جئت ألبس أوضاحا من ذهب فقلت يا رسول الله أكنز هو؟ فقال: ما بلغ الذي يؤدى زكاته فليس بكنز» أخرجه أبو داود والحاكم.]] وعن عمر رضى الله عنه أنّ رجلا سأله عن أرض له باعها فقال: أحرز مالك الذي أخذت، احفر له تحت فراش امرأتك. قال: أليس بكنز؟ قال: ما أدّى زكاته فليس بكنز [[أخرجه عبد الرزاق من طريق بشر بن سعيد أن رجلا باع رجلا حائطا أو مالا بمال عظيم فقال له عمر ابن الخطاب رضى الله عنه: أحسن موضع هذا المال- الحديث» ورواه ابن أبى شيبة من طريق أخرى عن سعيد ابن أبى سعيد أن عمر سأل رجلا- فذكره.]] وعن عمر رضى الله عنه: كل ما أدّيت زكاته فليس بكنز وإن كان تحت سبع أرضين، وما لم يؤدّ زكاته فهو الذي ذكر الله تعالى وإن كان على ظهر الأرض [[تقدم الكلام عليه.]] فإن قلت: فما تصنع بما روى سالم بن الجعد رضى الله عنه أنها لما نزلت قال رسول الله ﷺ: «تباً للذهب تبا للفضة» قالها ثلاثاً. فقالوا له: أىّ مال نتخذ؟ قال «لساناً ذاكراً، وقلباً خاشعاً، وزوجة تعين أحدكم على دينه [[كذا ذكره مرسلا، وهو معروف من رواية سالم بن ثوبان أخرجه الطبري والطبراني في الأوسط من طريق موثل بن إسماعيل عن الثوري عن الأعمش ومنصور وعمرو بن مرة عن سالم بن أبى الجعد عن ثوبان بهذا، ورواه الترمذي وأحمد في الزهد من رواية إسرائيل عن منصور ومده به، وليس فيه «تبا الذهب تبا الفضة» بل فيه: فقال بعض أصحابه «لو علمنا أى المال خير فنتخذه» قال البخاري وغيره: سالم لم يسمع من ثوبان، ورواه ابن ماجة وأحمد وأبو نعيم في الحلية من رواية عبد الله بن عمرو بن مرة عن أبيه عن سالم عن ثوبان، ورواه ابن ماجة وأحمد وأبو نعيم في الحلية من رواية عبد الله بن عمرو بن مرة عن أبيه عن سالم عن ثوبان قال «لما نزلت قالوا: فأى المال نتخذ؟ قال عمر: فأنا أعلم لكم ذلك فأوضع على بعيره فأدرك النبي ﷺ وأنا في أثره فقال: يا رسول الله أى المال نتخذ؟ - الحديث» وفي الباب عن على أخرجه عبد الرزاق عن الثوري عن أبى حصين عن أبى الضحى عن جعدة بن سبرة عنه، وعن بريدة أخرجه ابن مردويه من رواية الحكم بن ظهير عن علقمة بن مرثد عن سليمان بن بريدة عن أبيه. وعن بعض الصحابة أخرجه أحمد من رواية سعيد عن سالم بن عطية عن عبد الله بن عطية عن عبد الله بن أبى الهذيل حدثني صاحب لي أن رسول الله ﷺ قال «تبا للذهب تبا للفضة» فحدثني صاحبي أنه انطلق مع عمر، فقال: يا رسول الله. فذكر نحوه.]] وبقوله عليه الصلاة والسلام «من ترك صفراء أو بيضاء كوى بها» [[أخرجه البخاري في التاريخ والطبري وابن مردويه من طريق عبد الله بن عبد الواحد الثقفي عن أبى النجيب الشامي «كان نعل سيف أبى هريرة من فضة، فنهاه عنه أبو ذر وقال: إن رسول الله ﷺ قال: من ترك صفراء أو بيضاء كوى بها» وفي الباب عن أبى أمامة، أخرجه الطبراني بلفظ «ما من عبد يموت فيترك صفراء أو بيضاء إلا كوى بها» وعن ثوبان أخرجه ابن مردويه والطبراني في مسند الشاميين من رواية أرطاة بن المنذر عن ابن عامر عنه، بلفظ «ما من أحد يترك صفراء أو بيضاء من ذهب أو فضة إلا جعل صفائح ثم كوى بها» .]] وتوفى رجل فوجد في مئزره دينار، فقال رسول الله ﷺ «كية» وتوفى آخر فوجد في مئزره ديناران، فقال «كيتان» [[أخرجه أحمد وابن أبى شيبة وأبو يعلى والطبراني والطبري من طريق شهر بن حوشب عن أبى أمامة، بلفظ مروه في الموضعين. ورواه ابن حبان في صحيحه من حديث ابن مسعود بالشطر الثاني.]] قلت: كان هذا قبل أن تفرض الزكاة، فأمّا بعد فرض الزكاة، فالله أعدل وأكرم من أن يجمع عبده مالا من حيث أذن له فيه، ويؤدّى عنه ما أوجب عليه فيه، ثم يعاقبه. ولقد كان كثير من الصحابة كعبد الرحمن بن عوف وطلحة بن عبيد الله وعبيد الله رضى الله عنهم يقتنون الأموال ويتصرفون فيها، وما عابهم أحد ممن أعرض عن القنية، لأنّ الإعراض اختيار للأفضل، وإلا دخل في الورع والزهد في الدنيا، والاقتناء مباح موسع لا يذمّ صاحبه، ولكل شيء حدّ. وما روى عن علىّ رضى الله عنه: أربعة آلاف فما دونها نفقة، فما زاد فهو كنز [[أخرجه عبد الرزاق والطبري بإسناده الماضي عن على رضى الله عنه قبل بحديثين.]] : كلام في الأفضل. فإن قلت: لم قيل: ولا ينفقونها، وقد ذكر شيئان؟ قلت: ذهاباً بالضمير إلى المعنى دون اللفظ: لأن كل واحد منهما جملة وافية وعدة كثيرة ودنانير ودراهم، فهو كقوله وَإِنْ طائِفَتانِ مِنَ الْمُؤْمِنِينَ اقْتَتَلُوا وقيل: ذهب به إلى الكنوز. وقيل: إلى الأموال. وقيل: معناه ولا ينفقونها والذهب، [[قوله «والذهب» لعله و «الذهب كذلك» . (ع)]] كما أن معنى قوله: فَإنِّى وَقَيَّارٌ بِهَا لَغَرِيبُ [[تقدم شرح هذا الشاهد بالجزء الأول فراجعه إن شئت اه مصححه.]] وقيار كذلك. فإن قلت: لم خصا بالذكر من بين سائر الأموال؟ قلت: لأنهما قانون التمول وأثمان الأشياء، ولا يكنزهما إلا من فضلا عن حاجته، ومن كثرا عنده حتى يكنزهما لم يعدم سائر أجناس المال، فكان ذكر كنزهما دليلا على ما سواهما، فإن قلت: ما معنى قوله يُحْمى عَلَيْها؟ وهلا قيل: تحمى، من قولك: حمى الميسم [[قال محمود: «إن قلت: هلا قيل تحمى، كما يقال: حمى الميسم وأحميته ... الخ» قال أحمد: وفي هذا الفصل دقائق إعراب يشوب حسنها إغراب، والله الموفق.]] وأحميته، ولا تقول: أحميت على الحديد؟ قلت: معناه أن النار تحمى عليها، أى توقد ذات حمى وحرّ شديد، من قوله نارٌ حامِيَةٌ ولو قيل: يوم تحمى، لم يعط هذا المعنى. فإن قلت: فإذا كان الإحماء للنار، فلم ذكر الفعل؟ قلت: لأنه مسند إلى الجار والمجرور، أصله: يوم تحمى النار عليها، فلما حذفت النار قيل: يحمى عليها، لانتقال الاسناد عن النار إلى عليها، كما تقول: رفعت القصة إلى الأمير، فإن لم تذكر القصة قلت: رفع إلى الأمير. وعن ابن عامر أنه قرأ: تحمى، بالتاء. وقرأ أبو حيوة: فيكوى بالياء. فإن قلت: لم خصت هذه الأعضاء؟ قلت: لأنهم لم يطلبوا بأموالهم- حيث لم ينفقوها في سبيل الله- إلا الأغراضَ الدنيوية، من وجاهة عند الناس، وتقدّم، وأن يكون ماء وجوههم مصوناً عندهم، يتلقون بالجميل، ويحيون بالإكرام، ويبجلون ويحتشمون، ومن أكل طيبات يتضلعون منها وينفخون جنوبهم، ومن لبس ناعمة من الثياب يطرحونها على ظهورهم، كما ترى أغنياء زمانك هذه أغراضهم وطلباتهم من أموالهم، لا يخطرون ببالهم قول رسول الله ﷺ «ذهب أهل الدثور بالأجور» [[أخرجه مسلم من طريق أبى الأسود عن أبى ذر «أن أناسا من أصحاب النبي ﷺ: قالوا: يا رسول الله ذهب أهل الدثور بالأجور يصلون كما نصلى- الحديث.]] وقيل: لأنهم كانوا إذا أبصروا الفقير عبسوا، وإذا ضمهم وإياه مجلس زوروا عنه وتولوا بأركانهم وولوه ظهورهم. وقيل: معناه يكون على الجهات الأربع مقاديمهم ومآخيرهم وجنوبهم هذا ما كَنَزْتُمْ على إرادة القول. وقوله لِأَنْفُسِكُمْ أى كنزتموه لننتفع به نفوسكم وتلتذ وتحصل لها الأغراض التي حامت حولها وما علمتم أنكم كنزتموه لتستضر به أنفسكم وتتعذب وهو توبيخ لهم فَذُوقُوا ما كُنْتُمْ تَكْنِزُونَ وقرئ: تكنزون، بضم النون، أى وبال المال الذي كنتم تكنزونه أو وبال كونكم كانزين.',     source_page = '216',     updated_at  = datetime('now') WHERE id = 'QR:TE:fad2d1f8b11cf70bd55c4382';
UPDATE qr_tafsir_entries SET content_ar = 'إِنَّما يَسْتَأْذِنُكَ يعنى المنافقين، وكانوا تسعة وثلاثين رجلا يَتَرَدَّدُونَ عبارة عن التحير، لأن التردّد ديدن المتحير، كما أنّ الثبات والاستقرار ديدن المستبصر. قرئ: عدّه، بمعنى عدّته، فعل بالعدّة ما فعل بالعدة من قال: وَأَخْلَفُوكَ عِدَ الأَمْرِ الَّذِى وَعَدُوا [[مر شرح هذا الشاهد بالجزء الأول فراجعه إن شئت اه مصححه]] من حذف تاء التأنيث، وتعويض المضاف إليه منها. وقرئ: عدّة، بكسر العين بغير إضافة، وعدّه بإضافة. فإن قلت: كيف موقع حرف الاستدراك؟ قلت: لما كان قوله وَلَوْ أَرادُوا الْخُرُوجَ معطياً معنى نفى خروجهم واستعدادهم للغزو. قيل وَلكِنْ كَرِهَ اللَّهُ انْبِعاثَهُمْ كأنه قيل: ما خرجوا ولكن تثبطوا عن الخروج لكراهة انبعاثهم، كما تقول: ما أحسن إلىّ زيد، ولكن أساء إلىّ فَثَبَّطَهُمْ فكسلهم وخذلهم وضعف رغبتهم في الانبعاث وَقِيلَ اقْعُدُوا جعل إلقاء الله في قلوبهم كراهة الخروج أمراً بالقعود. وقيل: هو قول الشيطان بالوسوسة. وقيل: هو قولهم لأنفسهم. وقيل: هو إذن رسول الله ﷺ لهم في القعود. فإن قلت: كيف جاز أن يوقع الله تعالى في نفوسهم كراهة الخروج إلى الغزو وهي قبيحة، وتعالى الله عن إلهام القبيح [[قال محمود: «إن قلت كيف جاز أن يوقع الله في نفوسهم كراهة الخروج للغزو ... الخ» قال أحمد: وهذا الفصل من كلامه مبنى على قاعدتين فاسدتين: إيجاب مراعاة المصالح على الله تعالى، والتحسين والتقبيح. وقد تكرر بطلان ذلك فاحذره. واعلم أن معتقد أهل السنة أن الله تعالى ألقى كراهة الخروج في قلوبهم، لأنه أراد شقاوتهم، وانضاف إلى ذلك إرادة راحة المخلصين من مرافقتهم، إذ الأمر ليس شرطا في نفوذ المشيئة، والله الموفق.]] ؟ قلت: خروجهم كان مفسدة، لقوله لَوْ خَرَجُوا فِيكُمْ ما زادُوكُمْ إِلَّا خَبالًا فكان إيقاع كراهة ذلك الخروج في نفوسهم حسناً ومصلحة. فإن قلت: فلم خطأ رسول الله ﷺ في الإذن لهم فيما هو مصلحة؟ قلت: لأنّ إذن رسول الله ﷺ لهم لم يكن للنظر في هذه المصلحة ولا علمها إلا بعد القفول بإعلام الله تعالى، ولكن لأنهم استأذنوه في ذلك واعتذروا إليه، فكان عليه أن يتفحص عن كنه معاذيرهم ولا يتجوّز في قبولها، فمن ثم أتاه العتاب. ويجوز أن يكون في ترك رسول الله ﷺ الإذن لهم مع تثبيط الله إياهم مصلحة أخرى، فبإذنه لهم فقدت تلك المصلحة، وذلك أنهم إذا ثبطهم الله فلم ينبعثوا وكان قعودهم بغير إذن من رسول الله ﷺ قامت عليهم الحجة ولم تبق لهم معذرة. ولقد تدارك الله ذلك حيث هتك أستارهم وكشف أسرارهم وشهد عليهم بالنفاق، وأنهم لا يؤمنون بالله واليوم الآخر. فإن قلت: ما معنى قوله مَعَ الْقاعِدِينَ؟ [[عاد كلامه. قال: «فان قلت فما معنى قوله مع القاعدين ... الخ» قال أحمد: وهذا من تنبيهاته الحسنة، ونزيده بسطاً فنقول: لو قيل اقعدوا مقتصراً عليه، لم يفد سوى أمرهم بالقعود، وكذلك: كونوا مع القاعدين، ولا تحصل هذه الفائدة مع إلحاقهم بهؤلاء الأصناف الموصوفين عند الناس بالتخلف والتقاعد، الموسومين بهذه السمة، إلا من عبارة الآية، ولعن الله فرعون: لقد بالغ في توعد موسى عليه السلام بقوله: لأجعلنك من المسجونين، ولم يقل: لأجعلنك مسجونا، لمثل هذه النكتة من المبالغة]] قلت: هو ذمّ لهم وتعجيز، وإلحاق بالنساء والصبيان والزمنى الذين شأنهم القعود والجثوم في البيوت، وهم القاعدون والخالفون والخوالف، ويبينه قوله تعالى رَضُوا بِأَنْ يَكُونُوا مَعَ الْخَوالِفِ. إِلَّا خَبالًا ليس من الاستثناء المنقطع في شيء كما يقولون لأن الاستثناء المنقطع هو أن يكون المستثنى من غير جنس المستثنى منه، كقولك: ما زادوكم خيراً إلا خبالا، والمستثنى منه في هذا الكلام غير مذكور، وإذا لم يذكر وقع الاستثناء من أعم العام الذي هو الشيء، فكان استثناء متصلا، لأنّ الخبال بعض أعمّ العام، كأنه قيل: ما زادوكم شيئاً إلا خبالا. والخبال، الفساد والشرّ وَلَأَوْضَعُوا خِلالَكُمْ ولسعوا بينكم بالتضريب [[قوله «بالتضريب» أى بالإغراء. (ع)]] والنمائم وإفساد ذات البين. يقال: وضع البعير وضعاً إذا أسرع وأوضعته أنا. والمعنى: ولأوضع ركائبهم بينكم، والمراد الإسراع بالنمائم، لأنّ الراكب أسرع من الماشي. وقرأ ابن الزبير رضى الله عنه: ولأرقصوا، من رقصت الناقة رقصاً إذا أسرعت وأرقصتها. قال: وَالرَّاقِصَات إلَى مِنْى فَالغَبْغَبِ وقرئ: ولأوفضوا. فإن قلت: كيف خطّ في المصحف: ولا أوضعوا، بزيادة ألف؟ قلت: كانت الفتحة تكتب ألفاً قبل الخط العربي، والخط العربي اخترع قريباً من نزول القرآن، وقد بقي من ذلك الألف أثر في الطباع، فكتبوا صورة الهمزة ألفاً، وفتحتها ألفاً أخرى، ونحو: أو لا أذبحنه. يَبْغُونَكُمُ الْفِتْنَةَ يحاولون أن يفتنوكم. بأن يوقعوا الخلاف فيما بينكم ويفسدوا نياتكم في مغزاكم وَفِيكُمْ سَمَّاعُونَ لَهُمْ أى نمامون يسماعون حديثكم فينقلونه إليهم. أو فيكم قوم يسماعون للمنافقين ويطيعونهم لَقَدِ ابْتَغَوُا الْفِتْنَةَ أى العنت ونصب الغوائل والسعى في تشتيت شملك وتفريق أصحابك عنك، كما فعل عبد الله بن أبىّ يوم أحد حين انصرف بمن معه وعن ابن جريج رضى الله عنه: وقفوا لرسول الله ﷺ على الثنية ليلة العقبة وهم اثنا عشر رجلا ليفتكوا به مِنْ قَبْلُ من قبل غزوة تبوك وَقَلَّبُوا لَكَ الْأُمُورَ ودبروا لك الحيل والمكايد، ودوّروا الآراء في إبطال أمرك. وقرئ: وقلبوا بالتخفيف حَتَّى جاءَ الْحَقُّ وهو تأييدك ونصرك وَظَهَرَ أَمْرُ اللَّهِ وغلب دينه وعلا شرعه.',     source_page = '323',     updated_at  = datetime('now') WHERE id = 'QR:TE:e0ebbc11ee219157d79865c3';
UPDATE qr_tafsir_entries SET content_ar = '(سُورَةُ العادِياتِ) إحْدى عَشْرَةَ آيَةً مَكِّيَّةٌ ﷽ ﴿والعادِياتِ ضَبْحًا﴾ قَوْلُهُ تَعالى ﴿والعادِياتِ ضَبْحًا﴾ . اعْلَمْ أنَّ الضَّبْحَ أصْواتُ أنْفاسِ الخَيْلِ إذا عَدَتْ، وهو صَوْتٌ لَيْسَ بِصَهِيلٍ ولا حَمْحَمَةٍ، ولَكِنَّهُ صَوْتُ نَفَسٍ، ثُمَّ اخْتَلَفُوا في المُرادِ بِالعادِياتِ عَلى قَوْلَيْنِ: الأوَّلُ: ما رُوِيَ عَنْ عَلِيٍّ - عَلَيْهِ السَّلامُ - وابْنِ مَسْعُودٍ أنَّها الإبِلُ، وهو قَوْلُ إبْراهِيمَ والقُرَظِيِّ رَوى سَعِيدُ بْنُ جُبَيْرٍ عَنِ ابْنِ عَبّاسٍ قالَ: ”بَيْنا أنا جالِسٌ في الحِجْرِ إذْ أتانِي رَجُلٌ فَسَألَنِي عَنِ العادِياتِ ضَبْحًا، فَفَسَّرْتُها بِالخَيْلِ فَذَهَبَ إلى عَلِيٍّ - عَلَيْهِ السَّلامُ - وهو تَحْتَ سِقايَةِ زَمْزَمَ فَسَألَهُ وذَكَرَ لَهُ ما قُلْتُ، فَقالَ: ادْعُهُ لِي فَلَمّا وقَفْتُ عَلى رَأْسِهِ، قالَ: تُفْتِي النّاسَ بِما لا عِلْمَ لَكَ بِهِ، واللَّهِ إنْ كانَتْ لَأوَّلَ غَزْوَةٍ في الإسْلامِ بَدْرٌ وما كانَ مَعَنا إلّا فَرَسانِ فَرَسٌ لِلزُّبَيْرِ وفَرَسٌ لِلْمِقْدادِ، ﴿والعادِياتِ ضَبْحًا﴾ الإبِلُ مِن عَرَفَةَ إلى مُزْدَلِفَةَ، ومِنَ المُزْدَلِفَةِ إلى مِنًى، يَعْنِي إبِلَ الحاجِّ، قالَ ابْنُ عَبّاسٍ: فَرَجَعْتُ عَنْ قَوْلِي إلى قَوْلِ عَلِيٍّ عَلَيْهِ السَّلامُ“ ويَتَأكَّدُ هَذا القَوْلُ بِما رَوى أُبَيٌّ في فَضْلِ السُّورَةِ مَرْفُوعًا: ”مَن قَرَأها أُعْطِيَ مِنَ الأجْرِ بِعَدَدِ مَن باتَ بِالمُزْدَلِفَةِ وشَهِدَ جَمْعًا“ وعَلى هَذا القَوْلِ: ﴿فالمُورِياتِ قَدْحًا﴾ أنَّ الحَوافِرَ تَرْمِي بِالحَجَرِ مِن شِدَّةِ العَدْوِ فَتَضْرِبُ بِهِ حَجَرًا آخَرَ فَتُورِي النّارَ، أوْ يَكُونُ المَعْنى الَّذِينَ يَرْكَبُونَ الإبِلَ وهُمُ الحَجِيجُ إذا أوْقَدُوا نِيرانَهم بِالمُزْدَلِفَةِ ﴿فالمُغِيراتِ﴾ الإغارَةُ سُرْعَةُ السَّيْرِ وهم يَنْدَفِعُونَ صَبِيحَةَ يَوْمِ النَّحْرِ مُسْرِعِينَ إلى مِنًى ﴿فَأثَرْنَ بِهِ نَقْعًا﴾ يَعْنِي غُبارًا بِالعَدْوِ، وعَنْ مُحَمَّدِ بْنِ كَعْبٍ: النَّقْعُ ما بَيْنَ المُزْدَلِفَةِ إلى مِنًى ﴿فَوَسَطْنَ بِهِ جَمْعًا﴾ يَعْنِي مُزْدَلِفَةَ لِأنَّها تُسَمّى الجَمْعَ لِاجْتِماعِ الحاجِّ بِها، وعَلى هَذا التَّقْدِيرِ، فَوَجْهُ القَسَمِ بِهِ مِن وُجُوهٍ: أحَدُها: ما ذَكَرْنا مِنَ المَنافِعِ الكَثِيرَةِ فِيهِ في قَوْلِهِ: ﴿أفَلا يَنْظُرُونَ إلى الإبِلِ﴾ [الغاشية: ١٧] وثانِيها: كَأنَّهُ تَعْرِيضٌ بِالآدَمِيِّ الكَنُودِ فَكَأنَّهُ تَعالى يَقُولُ: إنِّي سَخَّرْتُ مِثْلَ هَذا لَكَ وأنْتَ مُتَمَرِّدٌ عَنْ طاعَتِي. وثالِثُها: الغَرَضُ بِذِكْرِ إبِلِ الحَجِّ التَّرْغِيبُ في الحَجِّ، كَأنَّهُ تَعالى يَقُولُ: جَعَلْتُ ذَلِكَ الإبِلَ مُقْسَمًا بِهِ، فَكَيْفَ أُضَيِّعُ عَمَلَكَ ! وفِيهِ تَعْرِيضٌ لِمَن يَرْغَبُ في الحَجِّ، فَإنَّ الكَنُودَ هو الكَفُورُ، والَّذِي لَمْ يَحُجَّ بَعْدَ الوُجُوبِ مَوْصُوفٌ بِذَلِكَ، كَما في قَوْلِهِ تَعالى: ﴿ولِلَّهِ عَلى النّاسِ حِجُّ البَيْتِ﴾ إلى قَوْلِهِ: ﴿ومَن كَفَرَ﴾ . [آل عمران: ٩٧] القَوْلُ الثّانِي: قَوْلُ ابْنِ عَبّاسٍ ومُجاهِدٍ وقَتادَةَ والضَّحّاكِ وعَطاءٍ وأكْثَرِ المُحَقِّقِينَ: أنَّهُ الخَيْلُ، ورُوِيَ ذَلِكَ مَرْفُوعًا. قالَ الكَلْبِيُّ: «بَعَثَ رَسُولُ اللَّهِ ﷺ سَرِيَّةً إلى أُناسٍ مِن كِنانَةَ فَمَكَثَ ما شاءَ اللَّهُ أنْ يَمْكُثَ لا يَأْتِيهِ مِنهم خَبَرٌ فَتَخَوَّفَ عَلَيْها. فَنَزَلَ جِبْرِيلُ - عَلَيْهِ السَّلامُ - بِخَبَرِ مَسِيرِها» . فَإنْ جَعَلْنا الألِفَ واللّامَ في: ﴿والعادِياتِ﴾ لِلْمَعْهُودِ السّابِقِ كانَ مَحَلُّ القَسَمِ خَيْلَ تِلْكَ السَّرِيَّةِ، وإنْ جَعَلْناهُما لِلْجِنْسِ كانَ ذَلِكَ قَسَمًا بِكُلِّ خَيْلٍ عَدَتْ في سَبِيلِ اللَّهِ. واعْلَمْ أنَّ ألْفاظَ هَذِهِ الآياتِ تُنادِي أنَّ المُرادَ هو الخَيْلُ، وذَلِكَ لِأنَّ الضَّبْحَ لا يَكُونُ إلّا لِلْفَرَسِ، واسْتِعْمالُ هَذا اللَّفْظِ في الإبِلِ يَكُونُ عَلى سَبِيلِ الِاسْتِعارَةِ، كَما اسْتُعِيرَ المَشافِرُ والحافِرُ لِلْإنْسانِ، والشَّفَتانِ لِلْمُهْرِ، والعُدُولُ مِنَ الحَقِيقَةِ إلى المَجازِ بِغَيْرِ ضَرُورَةٍ لا يَجُوزُ، وأيْضًا فالقَدْحُ يَظْهَرُ بِالحافِرِ ما لا يَظْهَرُ بِخُفِّ الإبِلِ، وكَذا قَوْلُهُ: ﴿فالمُغِيراتِ صُبْحًا﴾ لِأنَّهُ بِالخَيْلِ أسْهَلُ مِنهُ بِغَيْرِهِ، وقَدْ رُوِّينا أنَّهُ ورَدَ في بَعْضِ السَّرايا، وإذا كانَ كَذَلِكَ فالأقْرَبُ أنَّ السُّورَةَ مَدَنِيَّةٌ، لِأنَّ الإذْنَ بِالقِتالِ كانَ بِالمَدِينَةِ، وهو الَّذِي قالَهُ الكَلْبِيُّ: إذا عَرَفْتَ ذَلِكَ فَهَهُنا مَسائِلُ: المَسْألَةُ الأُولى: أنَّهُ تَعالى إنَّما أقْسَمَ بِالخَيْلِ لِأنَّ لَها في العَدْوِ مِنَ الخِصالِ الحَمِيدَةِ ما لَيْسَ لِسائِرِ الدَّوابِّ، فَإنَّها تَصْلُحُ لِلطَّلَبِ والهَرَبِ والكَرِّ والفَرِّ، فَإذا ظَنَنْتَ أنَّ النَّفْعَ في الطَّلَبِ عَدَوْتَ إلى الخَصْمِ لِتَفُوزَ بِالغَنِيمَةِ، وإذا ظَنَنْتَ أنَّ المَصْلَحَةَ في الهَرَبِ قَدَرْتَ عَلى أشَدِّ العَدْوِ، ولا شَكَّ أنَّ السَّلامَةَ إحْدى الغَنِيمَتَيْنِ، فَأقْسَمَ تَعالى بِفَرَسِ الغازِي لِما فِيهِ مِن مَنافِعِ الدُّنْيا والدِّينِ، وفِيهِ تَنْبِيهٌ عَلى أنَّ الإنْسانَ يَجِبُ عَلَيْهِ أنْ يُمْسِكَهُ لا لِلزِّينَةِ والتَّفاخُرِ، بَلْ لِهَذِهِ المَنفَعَةِ، وقَدْ نَبَّهَ تَعالى عَلى هَذا المَعْنى في قَوْلِهِ: ﴿والخَيْلَ والبِغالَ والحَمِيرَ لِتَرْكَبُوها وزِينَةً﴾ [النحل: ٨] فَأدْخَلَ لامَ التَّعْلِيلِ عَلى الرُّكُوبِ وما أدْخَلَهُ عَلى الزِّينَةِ وإنَّما قالَ: ﴿ضَبْحًا﴾ لِأنَّهُ أمارَةٌ يُظْهِرُ بِهِ التَّعَبَ وأنَّهُ يَبْذُلُ كُلَّ الوُسْعِ ولا يَقِفُ عِنْدَ التَّعَبِ، فَكَأنَّهُ تَعالى يَقُولُ: إنَّهُ مَعَ ضَعْفِهِ لا يَتْرُكُ طاعَتَكَ، فَلْيَكُنِ العَبْدُ في طاعَةِ مَوْلاهُ أيْضًا كَذَلِكَ. المَسْألَةُ الثّانِيَةُ: ذَكَرُوا في انْتِصابِ ﴿ضَبْحًا﴾ وُجُوهًا: أحَدُها: قالَ الزَّجّاجُ: والعادِياتِ تَضْبَحُ ضَبْحًا. وثانِيها: أنْ يَكُونَ ﴿والعادِياتِ﴾ في مَعْنى والضّابِحاتِ، لِأنَّ الضَّبْحَ يَكُونُ مَعَ العَدْوِ، وهو قَوْلُ الفَرّاءِ. وثالِثُها: قالَ البَصْرِيُّونَ: التَّقْدِيرُ: والعادِياتِ ضابِحَةً، فَقَوْلُهُ: ﴿ضَبْحًا﴾ نُصِبَ عَلى الحالِ.',     source_page = '60',     updated_at  = datetime('now') WHERE id = 'QR:TE:9d4ca3c160d2ae6ca34f196c';
UPDATE qr_tafsir_entries SET content_ar = 'ثُمَّ قالَ: ﴿إنَّ رَبَّهم بِهِمْ يَوْمَئِذٍ لَخَبِيرٌ﴾ اعْلَمْ أنَّ فِيهِ سُؤالاتٍ: الأوَّلُ: أنَّهُ يُوهِمُ أنَّ عِلْمَهُ بِهِمْ في ذَلِكَ اليَوْمِ إنَّما حَصَلَ بِسَبَبِ الخِبْرَةِ، وذَلِكَ يَقْتَضِي سَبْقَ الجَهْلِ وهو عَلى اللَّهِ تَعالى مُحالٌ: الجَوابُ مِن وجْهَيْنِ: أحَدُهُما: كَأنَّهُ تَعالى يَقُولُ: إنَّ مَن لَمْ يَكُنْ عالِمًا، فَإنَّهُ يَصِيرُ بِسَبَبِ الِاخْتِبارِ عالِمًا، فَمَن كانَ لَمْ يَزَلْ عالِمًا أنْ يَكُونَ خَبِيرًا بِأحْوالِكَ ! وثانِيهِما: أنَّ فائِدَةَ تَخْصِيصِ ذَلِكَ الوَقْتِ في قَوْلِهِ: ﴿يَوْمَئِذٍ﴾ مَعَ كَوْنِهِ عالِمًا لَمْ يَزَلْ أنَّهُ وقْتَ الجَزاءِ، وتَقْرِيرُهُ لِمَنِ المُلْكُ كَأنَّهُ يَقُولُ: لا حاكِمَ يَرُوجُ حُكْمُهُ ولا عالِمَ تَرُوجُ فَتْواهُ يَوْمَئِذٍ إلّا هو، وكَمْ عالِمٍ لا يَعْرِفُ الجَوابَ وقْتَ الواقِعَةِ ثُمَّ يَتَذَكَّرُهُ بَعْدَ ذَلِكَ، فَكَأنَّهُ تَعالى يَقُولُ: لَسْتُ كَذَلِكَ. السُّؤالُ الثّانِي: لِمَ خَصَّ أعْمالَ القُلُوبِ بِالذِّكْرِ في قَوْلِهِ: ﴿وحُصِّلَ ما في الصُّدُورِ﴾ وأهْمَلَ ذِكْرَ أعْمالِ الجَوارِحِ ؟ الجَوابُ: لِأنَّ أعْمالَ الجَوارِحِ تابِعَةٌ لِأعْمالِ القَلْبِ. فَإنَّهُ لَوْلا البَواعِثُ والإراداتُ في القُلُوبِ لَما حَصَلَتْ أفْعالُ الجَوارِحِ، ولِذَلِكَ إنَّهُ تَعالى جَعَلَها الأصْلَ في الذَّمِّ، فَقالَ: ﴿آثِمٌ قَلْبُهُ﴾ [البقرة: ٢٨٣] والأصْلُ في المَدْحِ، فَقالَ: ﴿وجِلَتْ قُلُوبُهُمْ﴾ . [الأنْفالِ: ٢ ] السُّؤالُ الثّالِثُ: لِمَ قالَ: ﴿وحُصِّلَ ما في الصُّدُورِ﴾ ولَمْ يَقُلْ: وحُصِّلَ ما في القُلُوبِ ؟ الجَوابُ: لِأنَّ القَلْبَ مَطِيَّةُ الرُّوحِ وهو بِالطَّبْعِ مُحِبٌّ لِمَعْرِفَةِ اللَّهِ وخِدْمَتِهِ، إنَّما المُنازِعُ في هَذا البابِ هو النَّفْسُ ومَحِلُّها ما يَقْرُبُ مِنَ الصَّدْرِ، ولِذَلِكَ قالَ: ﴿يُوَسْوِسُ في صُدُورِ النّاسِ﴾ [الناس: ٥] وقالَ: ﴿أفَمَن شَرَحَ اللَّهُ صَدْرَهُ لِلْإسْلامِ﴾ [ الزُّمَرِ: ٢٢] فَجَعَلَ الصَّدْرَ مَوْضِعًا لِلْإسْلامِ. السُّؤالُ الرّابِعُ: الضَّمِيرُ في قَوْلِهِ: ﴿إنَّ رَبَّهم بِهِمْ﴾ عائِدٌ إلى الإنْسانِ وهو واحِدٌ. والجَوابُ: الإنْسانُ في مَعْنى الجَمْعِ كَقَوْلِهِ تَعالى: ﴿إنَّ الإنْسانَ لَفي خُسْرٍ﴾ [ العَصْرِ: ٢] ثُمَّ قالَ: ﴿إلّا الَّذِينَ آمَنُوا﴾ [العصر: ٣] ولَوْلا أنَّهُ لِلْجَمْعِ وإلّا لَما صَحَّ ذَلِكَ. واعْلَمْ أنَّهُ بَقِيَ مِن مَباحِثِ هَذِهِ الآيَةِ مَسْألَتانِ: المَسْألَةُ الأُولى: هَذِهِ الآيَةُ تَدُلُّ عَلى كَوْنِهِ تَعالى عالِمًا بِالجُزْئِيّاتِ الزَّمانِيّاتِ، لِأنَّهُ تَعالى نَصَّ عَلى كَوْنِهِ عالِمًا بِكَيْفِيَّةِ أحْوالِهِمْ في ذَلِكَ اليَوْمِ فَيَكُونُ مُنْكِرُهُ كافِرًا. المَسْألَةُ الثّانِيَةُ: نُقِلَ أنَّ الحَجّاجَ سَبَقَ عَلى لِسانِهِ أنَّ بِالنَّصْبِ، فَأسْقَطَ اللّامَ مِن قَوْلِهِ: ﴿لَخَبِيرٌ﴾ حَتّى لا يَكُونَ الكَلامُ لَحْنًا، وهَذا يُذْكَرُ في تَقْرِيرِ فَصاحَتِهِ، فَزَعَمَ بَعْضُ المَشايِخِ أنَّ هَذا كُفْرٌ لِأنَّهُ قَصْدٌ لِتَغْيِيرِ المُنْزَلِ. ونُقِلَ عَنْ أبِي السَّمَوْءَلِ أنَّهُ قَرَأ عَلى هَذا الوَجْهِ، واللَّهُ سُبْحانَهُ وتَعالى أعْلَمُ وصَلّى اللَّهُ عَلى سَيِّدِنا مُحَمَّدٍ وعَلى آلِهِ وصَحْبِهِ وسَلَّمَ.',     source_page = '66',     updated_at  = datetime('now') WHERE id = 'QR:TE:7e07ab52066adf24e53be3b6';
UPDATE qr_tafsir_entries SET content_ar = 'أمّا قَوْلُهُ تَعالى: ﴿فالمُورِياتِ قَدْحًا﴾ . فاعْلَمْ أنَّ الإيراءَ إخْراجُ النّارِ، والقَدْحَ الصَّكُّ تَقُولُ: قَدَحَ فَأوْرى وقَدَّ فَأصْلَدَ، ثُمَّ في تَفْسِيرِ الآيَةِ وُجُوهٌ: أحَدُها: قالَ ابْنُ عَبّاسٍ: يُرِيدُ ضَرْبَ الخَيْلِ بِحَوافِرِها الجَبَلَ فَأوْرَتْ مِنهُ النّارَ مِثْلَ الزَّنْدِ إذا قُدِحَ، وقالَ مُقاتِلٌ: يَعْنِي الخَيْلَ تَقْدَحْنَ بِحَوافِرِهِنَّ في الحِجارَةِ نارًا كَنارِ الحُباحِبِ، والحُباحِبُ اسْمُ رَجُلٍ كانَ بَخِيلًا لا يُوقِدُ النّارَ إلّا إذا نامَ النّاسُ، فَإذا انْتَبَهَ أحَدٌ أطْفَأ نارَهُ لِئَلّا يَنْتَفِعَ بِها أحَدٌ. فَشُبِّهَتْ هَذِهِ النّارُ الَّتِي تَنْقَدِحُ مِن حَوافِرِ الخَيْلِ بِتِلْكَ النّارِ الَّتِي لَمْ يَكُنْ فِيها نَفْعٌ ومِنَ النّاسِ مَن يَقُولُ: إنَّها نَعْلُ الحَدِيدِ يَصُكُّ الحَجَرَ فَتَخْرُجُ النّارُ، والأوَّلُ أبْلَغُ لِأنَّ عَلى ذَلِكَ التَّقْدِيرِ تَكُونُ السَّنابِكُ نَفْسُها كالحَدِيدِ. وثالِثُها: قالَ قَوْمٌ: هَذِهِ الآياتُ في الخَيْلِ، ولَكِنْ إيراؤُها أنْ تُهِيجَ الحَرْبَ بَيْنَ أصْحابِها وبَيْنَ عَدُوِّهِمْ، كَما قالَ تَعالى: ﴿كُلَّما أوْقَدُوا نارًا لِلْحَرْبِ أطْفَأها اللَّهُ﴾ [المائدة: ٦٤] ومِنهُ يُقالُ لِلْحَرْبِ إذا التَحَمَتْ: حَمِيَ الوَطِيسُ. وثالِثُها: هُمُ الَّذِينَ يَغْزُونَ فَيُورُونَ بِاللَّيْلِ نِيرانَهم لِحاجَتِهِمْ وطَعامِهِمْ ﴿فالمُورِياتِ﴾ هُمُ الجَماعَةُ مِنَ الغُزاةِ. ورابِعُها: إنَّها هي الألْسِنَةُ تُورِي نارَ العَداوَةِ لِعِظَمِ ما تَتَكَلَّمُ بِهِ. وخامِسُها: هي أفْكارُ الرِّجالِ تُورِي نارَ المَكْرِ والخَدِيعَةِ، رُوِيَ ذَلِكَ عَنِ ابْنِ عَبّاسٍ، ويُقالُ: لَأقْدَحَنَّ لَكَ ثُمَّ لَأُورِيَنَّ لَكَ، أيْ لَأُهَيِّجَنَّ عَلَيْكَ شَرًّا وحَرْبًا، وقِيلَ: هو المَكْرُ إلّا أنَّهُ مَكْرٌ بِإيقادِ النّارِ لِيَراهُمُ العَدُوُّ كَثِيرًا، ومِن عادَةِ العَرَبِ عِنْدَ الغَزْوِ إذا قَرُبُوا مِنَ العَدُوِّ أنْ يُوقِدُوا نِيرانًا كَثِيرَةً، لِكَيْ إذا نَظَرَ العَدُوُّ إلَيْهِمْ ظَنَّهم كَثِيرًا. وسادِسُها: قالَ عِكْرِمَةُ: المُورِياتِ قَدْحًا: الأسِنَّةُ. وسابِعُها: ﴿فالمُورِياتِ قَدْحًا﴾ أيْ فالمُنْجِحاتِ أمْرًا، يَعْنِي الَّذِينَ وجَدُوا مَقْصُودَهم وفازُوا بِمَطْلُوبِهِمْ مِنَ الغَزْوِ والحَجِّ، ويُقالُ لِلْمُنْجِحِ في حاجَتِهِ: ورى زَنْدَهُ، ثُمَّ يَرْجِعُ هَذا إلى الجَماعَةِ المُنْجِحَةِ، ويَجُوزُ أنْ يَرْجِعَ إلى الخَيْلِ يَنْجَحُ رُكْبانُها قالَ جَرِيرٌ: وجَدْنا الأزْدَ أكْرَمَهم جَوادا وأوْراهم إذا قَدَحُوا زِنادا ويُقالُ: فُلانٌ إذا قَدَحَ أوْرى، وإذا مَنَحَ أرْوى، واعْلَمْ أنَّ الوَجْهَ الأوَّلَ أقْرَبُ لِأنَّ لَفْظَ الإيراءِ حَقِيقَةٌ في إيراءِ النّارِ، وفي غَيْرِهِ مَجازٌ، ولا يَجُوزُ تَرْكُ الحَقِيقَةِ بِغَيْرِ دَلِيلٍ.',     source_page = '62',     updated_at  = datetime('now') WHERE id = 'QR:TE:bdbf5a74e28dae723b59034b';
UPDATE qr_tafsir_entries SET content_ar = 'أمّا قَوْلُهُ تَعالى: ﴿فالمُغِيراتِ صُبْحًا﴾ يَعْنِي الخَيْلَ تُغِيرُ عَلى العَدُوِّ وقْتَ الصُّبْحِ، وكانُوا يُغِيرُونَ صَباحًا لِأنَّهم في اللَّيْلِ يَكُونُونَ في الظُّلْمَةِ فَلا يُبْصِرُونَ شَيْئًا، وأمّا النَّهارُ فالنّاسُ يَكُونُونَ فِيهِ كالمُسْتَعِدِّينَ لِلْمُدافَعَةِ والمُحارَبَةِ، أمّا هَذا الوَقْتُ فالنّاسُ يَكُونُونَ فِيهِ في الغَفْلَةِ وعَدَمِ الِاسْتِعْدادِ. وأمّا الَّذِينَ حَمَلُوا هَذِهِ الآياتِ عَلى الإبِلِ، قالُوا: المُرادُ هو الإبِلُ تَدْفَعُ بِرُكْبانِها يَوْمَ النَّحْرِ مِن جَمْعٍ إلى مِنًى، والسُّنَّةُ أنْ لا تُغِيرَ حَتّى تُصْبِحَ، ومَعْنى الإغارَةِ في اللُّغَةِ الإسْراعُ، يُقالُ: أغارَ إذا أسْرَعَ وكانَتِ العَرَبُ في الجاهِلِيَّةِ تَقُولُ: أشْرِقْ ثَبِيرُ كَيْما نُغِيرُ: أيْ نُسْرِعُ في الإفاضَةِ. أمّا قَوْلُهُ: ﴿فَأثَرْنَ بِهِ نَقْعًا﴾ فَفِيهِ مَسائِلُ: المَسْألَةُ الأُولى: في النَّقْعِ قَوْلانِ: أحَدُهُما: أنَّهُ هو الغُبارُ وقِيلَ: إنَّهُ مَأْخُوذٌ مِن نَقْعِ الصَّوْتِ إذا ارْتَفَعَ، فالغُبارُ يُسَمّى نَقْعًا لِارْتِفاعِهِ، وقِيلَ: هو مِنَ النَّقْعِ في الماءِ، فَكَأنَّ صاحِبَ الغُبارِ غاصَ فِيهِ، كَما يَغُوصُ الرَّجُلُ في الماءِ. والثّانِي: النَّقْعُ الصِّياحُ مِن قَوْلِهِ عَلَيْهِ الصَّلاةُ والسَّلامُ: «ما لَمْ يَكُنْ نَقْعٌ ولا لَقَلَقَةٌ» أيْ فَهَيَّجْنَ في المُغارِ عَلَيْهِمْ صِياحَ النَّوائِحِ، وارْتَفَعَتْ أصْواتُهُنَّ، ويُقالُ: ثارَ الغُبارُ والدُّخانُ، أيِ ارْتَفَعَ وثارَ القَطا عَنْ مِفْحَصِهِ، وأثَرْنَ الغُبارَ أيْ هَيَّجْنَهُ، والمَعْنى أنَّ الخَيْلَ أثَرْنَ الغُبارَ لِشِدَّةِ العَدْوِ في المَوْضِعِ الَّذِي أغَرْنَ فِيهِ. المَسْألَةُ الثّانِيَةُ: الضَّمِيرُ في قَوْلِهِ: ”بِهِ“ إلى ماذا يَعُودُ ؟ فِيهِ وُجُوهٌ: أحَدُها: وهو قَوْلُ الفَرّاءِ أنَّهُ عائِدٌ إلى المَكانِ الَّذِي انْتَهى إلَيْهِ، والمَوْضِعِ الَّذِي تَقَعُ فِيهِ الإغارَةُ، لِأنَّ في قَوْلِهِ: ﴿فالمُغِيراتِ صُبْحًا﴾ دَلِيلًا عَلى أنَّ الإغارَةَ لا بُدَّ لَها مِن وضْعٍ، وإذا عُلِمَ المَعْنى جازَ أنْ يُكَنّى عَمّا لَمْ يَجُزْ ذِكْرُهُ بِالتَّصْرِيحِ كَقَوْلِهِ: ﴿إنّا أنْزَلْناهُ في لَيْلَةِ القَدْرِ﴾ [ القَدْرِ: ١] وثانِيها: إنَّهُ عائِدٌ إلى ذَلِكَ الزَّمانِ الَّذِي وقَعَتْ فِيهِ الإغارَةُ، أيْ فَأثَرْنَ في ذَلِكَ الوَقْتِ نَقْعًا. وثالِثُها: وهو قَوْلُ الكِسائِيِّ أنَّهُ عائِدٌ إلى العَدْوِ، أيْ فَأثَرْنَ بِالعَدْوِ نَقْعًا، وقَدْ تَقَدَّمَ ذِكْرُ العَدْوِ في قَوْلِهِ: ﴿والعادِياتِ﴾ . المَسْألَةُ الثّالِثَةُ: فَإنْ قِيلَ: عَلى أيِّ شَيْءٍ عَطَفَ قَوْلَهُ: ﴿فَأثَرْنَ﴾ قُلْنا: عَلى الفِعْلِ الَّذِي وُضِعَ اسْمُ الفاعِلِ مَوْضِعَهُ، والتَّقْدِيرُ: واللّائِي عَدَوْنَ فَأوْرَيْنَ، وأغَرْنَ فَأثَرْنَ. المَسْألَةُ الرّابِعَةُ: قَرَأ أبُو حَيْوَةَ: ”فَأثَّرْنَ“ بِالتَّشْدِيدِ بِمَعْنى فَأظْهَرْنَ بِهِ غُبارًا، لِأنَّ التَّأْثِيرَ فِيهِ مَعْنى الإظْهارِ، أوْ قَلَبَ ثَوَّرْنَ إلى وثَّرْنَ وقَلَبَ الواوَ هَمْزَةً.',     source_page = '63',     updated_at  = datetime('now') WHERE id = 'QR:TE:4903cb201ad93702e61e1f64';
UPDATE qr_tafsir_entries SET content_ar = 'أحَدُها: قَوْلُهُ: ﴿إنَّ الإنْسانَ لِرَبِّهِ لَكَنُودٌ﴾ قالَ الواحِدِيُّ: أصْلُ الكُنُودِ مَنعُ الحَقِّ والخَيْرِ، والكَنُودُ الَّذِي يَمْنَعُ ما عَلَيْهِ، والأرْضُ الكَنُودُ هي الَّتِي لا تُنْبِتُ شَيْئًا، ثُمَّ لِلْمُفَسِّرِينَ عِباراتٌ، فَقالَ ابْنُ عَبّاسٍ ومُجاهِدٌ وعِكْرِمَةُ والضَّحّاكُ وقَتادَةُ: الكَنُودُ هو الكَفُورُ قالُوا: ومِنهُ سُمِّيَ الرَّجُلُ المَشْهُورُ كِنْدَةَ لِأنَّهُ كَنَدَ أباهُ فَفارَقَهُ، وعَنِ الكَلْبِيِّ الكَنُودُ -بِلِسانِ كِنْدَةَ-: العاصِي، وبِلِسانِ بَنِي مالِكٍ: البَخِيلُ، وبِلِسانِ مُضَرَ ورَبِيعَةَ: الكَفُورُ، ورَوى أبُو أُمامَةَ عَنِ النَّبِيِّ ﷺ أنَّ ” «الكَنُودَ“ هو الكَفُورُ الَّذِي يَمْنَعُ رِفْدَهُ، ويَأْكُلُ وحْدَهُ، ويَضْرِبُ عَبْدَهُ» ، وقالَ الحَسَنُ: ”الكَنُودُ“ اللَّوّامُ لِرَبِّهِ يَعُدُّ المِحَنَ والمَصائِبَ، ويَنْسى النِّعَمَ والرّاحاتِ، وهو كَقَوْلِهِ: ﴿وأمّا إذا ما ابْتَلاهُ فَقَدَرَ عَلَيْهِ رِزْقَهُ فَيَقُولُ رَبِّي أهانَنِ﴾ [الفجر: ١٦] واعْلَمْ أنَّ مَعْنى الكَنُودِ لا يَخْرُجُ عَنْ أنْ يَكُونَ كُفْرًا أوْ فِسْقًا، وكَيْفَما كانَ فَلا يُمْكِنُ حَمْلُهُ عَلى كُلِّ النّاسِ، فَلا بُدَّ مِن صَرْفِهِ إلى كافِرٍ مُعَيَّنٍ، أوْ إنْ حَمَلْناهُ عَلى الكُلِّ كانَ المَعْنى أنَّ طَبْعَ الإنْسانِ يَحْمِلُهُ عَلى ذَلِكَ إلّا إذا عَصَمَهُ اللَّهُ بِلُطْفِهِ وتَوْفِيقِهِ مِن ذَلِكَ، والأوَّلُ قَوْلُ الأكْثَرِينَ قالُوا: لِأنَّ ابْنَ عَبّاسٍ قالَ: إنَّها نَزَلَتْ في قُرْطِ بْنِ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ نَوْفَلٍ القُرَشِيِّ، وأيْضًا فَقَوْلُهُ: ﴿أفَلا يَعْلَمُ إذا بُعْثِرَ ما في القُبُورِ﴾ لا يَلِيقُ إلّا بِالكافِرِ: لِأنَّ ذَلِكَ كالدَّلالَةِ عَلى أنَّهُ مُنْكِرٌ لِذَلِكَ الأمْرِ. الثّانِي: مِنَ الأُمُورِ الَّتِي أقْسَمَ اللَّهُ عَلَيْها قَوْلُهُ: ﴿وإنَّهُ عَلى ذَلِكَ لَشَهِيدٌ﴾ وفِيهِ قَوْلانِ: أحَدُهُما: أنَّ الإنْسانَ عَلى ذَلِكَ أيْ: عَلى كُنُودِهِ لَشَهِيدٌ يَشْهَدُ عَلى نَفْسِهِ بِذَلِكَ، إمّا لِأنَّهُ أمْرٌ ظاهِرٌ لا يُمْكِنُهُ أنْ يَجْحَدَهُ، أوْ لِأنَّهُ يَشْهَدُ عَلى نَفْسِهِ بِذَلِكَ في الآخِرَةِ ويَعْتَرِفُ بِذُنُوبِهِ. القَوْلُ الثّانِي: المُرادُ وإنَّ اللَّهَ عَلى ذَلِكَ لَشَهِيدٌ قالُوا: وهَذا أوْلى لِأنَّ الضَّمِيرَ عائِدٌ إلى أقْرَبِ المَذْكُوراتِ، والأقْرَبُ هَهُنا هو لَفْظُ الرَّبِّ تَعالى ويَكُونُ ذَلِكَ كالوَعِيدِ والزَّجْرِ لَهُ عَنِ المَعاصِي مِن حَيْثُ إنَّهُ يُحْصِي عَلَيْهِ أعْمالَهُ، وأمّا النّاصِرُونَ لِلْقَوْلِ الأوَّلِ فَقالُوا: إنَّ قَوْلَهُ بَعْدَ ذَلِكَ: ﴿وإنَّهُ لِحُبِّ الخَيْرِ لَشَدِيدٌ﴾ الضَّمِيرُ فِيهِ عائِدٌ إلى الإنْسانِ، فَيَجِبُ أنْ يَكُونَ الضَّمِيرُ في الآيَةِ الَّتِي قَبْلَهُ عائِدًا إلى الإنْسانِ لِيَكُونَ النَّظْمُ أحْسَنَ. الأمْرُ الثّالِثُ: مِمّا أقْسَمَ اللَّهُ عَلَيْهِ قَوْلُهُ: ﴿وإنَّهُ لِحُبِّ الخَيْرِ لَشَدِيدٌ﴾ الخَيْرُ المالُ مِن قَوْلِهِ تَعالى: ﴿إنْ تَرَكَ خَيْرًا﴾ [البقرة: ١٨٠] وقَوْلِهِ: ﴿وإذا مَسَّهُ الخَيْرُ مَنُوعًا﴾ [المعارج: ٢١] وهَذا لِأنَّ النّاسَ يَعُدُّونَ المالَ فِيما بَيْنَهم خَيْرًا كَما أنَّهُ تَعالى سَمّى ما يَنالُ المُجاهِدَ مِنَ الجِراحِ وأذى الحَرْبِ سُوءًا في قَوْلِهِ: ﴿لَمْ يَمْسَسْهم سُوءٌ﴾ [آل عمران: ١٧٤] والشَّدِيدُ البَخِيلُ المُمْسِكُ، يُقالُ: فُلانٌ شَدِيدٌ ومُتَشَدِّدٌ، قالَ طَرَفَةُ: أرى المَوْتَ يَعْتامُ الكِرامَ ويَصْطَفِي عَقِيلَةَ مالِ الفاحِشِ المُتَشَدِّدِ ثُمَّ في التَّفْسِيرِ وُجُوهٌ: أحَدُها: أنَّهُ لِأجْلِ حُبِّ المالِ لَبَخِيلٌ مُمْسِكٌ. وثانِيها: أنْ يَكُونَ المُرادُ مِنَ الشَّدِيدِ القَوِيَّ، ويَكُونُ المَعْنى وإنَّهُ لِحُبِّ المالِ وإيثارِ الدُّنْيا وطَلَبِها قَوِيٌّ مُطِيقٌ، وهو لِحُبِّ عِبادَةِ اللَّهِ وشُكْرِ نِعَمِهِ ضَعِيفٌ، تَقُولُ: هو شَدِيدٌ لِهَذا الأمْرِ وقَوِيٌّ لَهُ، إذا كانَ مُطِيقًا لَهُ ضابِطًا. وثالِثُها: أرادَ إنَّهُ لِحُبِّ الخَيْراتِ غَيْرُ هَنِيٍّ مُنْبَسِطٍ ولَكِنَّهُ شَدِيدٌ مُنْقَبِضٌ. ورابِعُها: قالَ الفَرّاءُ: يَجُوزُ أنْ يَكُونَ المَعْنى وإنَّهُ لِحُبِّ الخَيْرِ لَشَدِيدُ الحُبِّ يَعْنِي أنَّهُ يُحِبُّ المالَ، ويُحِبُّ كَوْنَهُ مُحِبًّا لَهُ، إلّا أنَّهُ اكْتَفى بِالحُبِّ الأوَّلِ عَنِ الثّانِي، كَما قالَ: ﴿اشْتَدَّتْ بِهِ الرِّيحُ في يَوْمٍ عاصِفٍ﴾ [إبراهيم: ١٨] أيْ في يَوْمٍ عاصِفِ الرِّيحِ فاكْتَفى بِالأُولى عَنِ الثّانِيَةِ. وخامِسُها: قالَ قُطْرُبٌ: أيْ إنَّهُ شَدِيدُ حُبِّ الخَيْرِ، كَقَوْلِكَ إنَّهُ لِزَيْدٍ ضَرُوبٌ أيْ إنَّهُ ضَرُوبُ زَيْدٍ.',     source_page = '64',     updated_at  = datetime('now') WHERE id = 'QR:TE:e043ec7da1d2f3776d851cc0';
UPDATE qr_tafsir_entries SET content_ar = '(سُورَةُ القارِعَةِ) إحْدى عَشْرَةَ آيَةً مَكِّيَّةٌ ﷽ ﴿القارِعَةُ﴾ ﴿ما القارِعَةُ﴾ ﴿وما أدْراكَ ما القارِعَةُ﴾ اعْلَمْ أنَّهُ سُبْحانَهُ وتَعالى لَمّا خَتَمَ السُّورَةَ المُتَقَدِّمَةَ بِقَوْلِهِ: ﴿إنَّ رَبَّهم بِهِمْ يَوْمَئِذٍ لَخَبِيرٌ﴾ فَكَأنَّهُ قِيلَ: وما ذَلِكَ اليَوْمُ ؟ فَقِيلَ: هي القارِعَةُ. ﷽ ﴿القارِعَةُ﴾ ﴿ما القارِعَةُ﴾ ﴿وما أدْراكَ ما القارِعَةُ﴾ اعْلَمْ أنَّ فِيهِ مَسائِلَ: المَسْألَةُ الأُولى: القَرْعُ الضَّرْبُ بِشِدَّةٍ واعْتِمادٍ، ثُمَّ سُمِّيَتِ الحادِثَةُ العَظِيمَةُ مِن حَوادِثِ الدَّهْرِ قارِعَةً، قالَ اللَّهُ تَعالى: ﴿ولا يَزالُ الَّذِينَ كَفَرُوا تُصِيبُهم بِما صَنَعُوا قارِعَةٌ﴾ [الرعد: ٣١] ومِنهُ قَوْلُهم: العَبْدُ يُقْرَعُ بِالعَصا، ومِنهُ المِقْرَعَةُ وقَوارِعُ القُرْآنِ وقَرَعَ البابَ، وتَقارَعُوا: تَضارَبُوا بِالسُّيُوفِ، واتَّفَقُوا عَلى أنَّ القارِعَةَ اسْمٌ مِن أسْماءِ القِيامَةِ، واخْتَلَفُوا في لِمِّيَّةِ هَذِهِ التَّسْمِيَةِ عَلى وُجُوهٍ: أحَدُها: أنَّ سَبَبَ ذَلِكَ هو الصَّيْحَةُ الَّتِي تَمُوتُ مِنها الخَلائِقُ: لِأنَّ في الصَّيْحَةِ الأُولى تَذْهَبُ العُقُولُ، قالَ تَعالى: ﴿فَصَعِقَ مَن في السَّماواتِ ومَن في الأرْضِ﴾ [الزمر: ٦٨] وفي الثّانِيَةِ تَمُوتُ الخَلائِقُ سِوى إسْرافِيلَ، ثُمَّ يُمِيتُهُ اللَّهُ ثُمَّ يُحْيِيهِ، فَيَنْفُخُ الثّالِثَةَ فَيَقُومُونَ. ورُوِيَ أنَّ الصُّورَ لَهُ ثُقْبٌ عَلى عَدَدِ الأمْواتِ لِكُلِّ واحِدٍ ثُقْبَةٌ مَعْلُومَةٌ، فَيُحْيِي اللَّهُ كُلَّ جَسَدٍ بِتِلْكَ النَّفْخَةِ الواصِلَةِ إلَيْهِ مِن تِلْكَ الثُّقْبَةِ المُعَيَّنَةِ، والَّذِي يُؤَكِّدُ هَذا الوَجْهَ قَوْلُهُ تَعالى: ﴿ما يَنْظُرُونَ إلّا صَيْحَةً واحِدَةً﴾ [يس: ٤٩] ، ﴿فَإنَّما هي زَجْرَةٌ واحِدَةٌ﴾ [النازعات: ١٣] وثانِيها: أنَّ الأجْرامَ العُلْوِيَّةَ والسُّفْلِيَّةَ يَصْطَكّانِ اصْطِكاكًا شَدِيدًا عِنْدَ تَخْرِيبِ العالَمِ، فَبِسَبَبِ تِلْكَ القَرْعَةِ سُمِّيَ يَوْمُ القِيامَةِ بِالقارِعَةِ. وثالِثُها: أنَّ القارِعَةَ هي الَّتِي تَقْرَعُ النّاسَ بِالأهْوالِ والإفْزاعِ، وذَلِكَ في السَّماواتِ بِالِانْشِقاقِ والِانْفِطارِ، وفي الشَّمْسِ والقَمَرِ بِالتَّكَوُّرِ، وفي الكَواكِبِ بِالِانْتِثارِ، وفي الجِبالِ بِالدَّكِّ والنَّسْفِ، وفي الأرْضِ بِالطَّيِّ والتَّبْدِيلِ، وهو قَوْلُ الكَلْبِيِّ. ورابِعُها: أنَّها تَقْرَعُ أعْداءَ اللَّهِ بِالعَذابِ والخِزْيِ والنَّكالِ، وهو قَوْلُ مُقاتِلٍ، قالَ بَعْضُ المُحَقِّقِينَ وهَذا أوْلى مِن قَوْلِ الكَلْبِيِّ لِقَوْلِهِ تَعالى: ﴿وهم مِن فَزَعٍ يَوْمَئِذٍ آمِنُونَ﴾ . [النمل: ٨٩] المَسْألَةُ الثّانِيَةُ: في إعْرابِ قَوْلِهِ: ﴿القارِعَةُ﴾ ﴿ما القارِعَةُ﴾ وُجُوهٌ: أحَدُها: أنَّهُ تَحْذِيرٌ وقَدْ جاءَ التَّحْذِيرُ بِالرَّفْعِ والنَّصْبِ تَقُولُ: الأسَدُ الأسَدُ، فَيَجُوزُ الرَّفْعُ والنَّصْبُ. وثانِيها: فِيهِ إضْمارٌ أيْ سَتَأْتِيكُمُ القارِعَةُ عَلى ما أخْبَرْتُ عَنْهُ في قَوْلِهِ: ﴿إذا بُعْثِرَ ما في القُبُورِ﴾ . [العاديات: ٩] وثالِثُها: رُفِعَ بِالِابْتِداءِ وخَبَرُهُ: ﴿ما القارِعَةُ﴾ وعَلى قَوْلِ قُطْرُبٍ الخَبَرُ: ﴿وما أدْراكَ ما القارِعَةُ﴾ فَإنْ قِيلَ: إذا أخْبَرْتَ عَنْ شَيْءٍ بِشَيْءٍ فَلا بُدَّ وأنْ تَسْتَفِيدَ مِنهُ عِلْمًا زائِدًا، وقَوْلُهُ: ﴿وما أدْراكَ﴾ يُفِيدُ كَوْنَهُ جاهِلًا بِهِ فَكَيْفَ يُعْقَلُ أنْ يَكُونَ هَذا خَبَرًا ؟ قُلْنا: قَدْ حَصَلَ لَنا بِهَذا الخَبَرِ عِلْمٌ زائِدٌ: لِأنّا كُنّا نَظُنُّ أنَّها قارِعَةٌ كَسائِرِ القَوارِعِ، فَبِهَذا التَّجْهِيلِ عَلِمْنا أنَّها قارِعَةٌ فاقَتِ القَوارِعَ في الهَوْلِ والشِّدَّةِ. المَسْألَةُ الثّالِثَةُ: قَوْلُهُ: ﴿وما أدْراكَ ما القارِعَةُ﴾ فِيهِ وُجُوهٌ: أحَدُها: مَعْناهُ لا عِلْمَ لَكَ بِكُنْهِها، لِأنَّها في الشِّدَّةِ بِحَيْثُ لا يَبْلُغُها وهْمُ أحَدٍ ولا فَهْمُهُ، وكَيْفَما قَدَّرْتَهُ فَهو أعْظَمُ مِن تَقْدِيرِكَ كَأنَّهُ تَعالى قالَ: قَوارِعُ الدُّنْيا في جَنْبِ تِلْكَ القارِعَةِ كَأنَّها لَيْسَتْ بِقَوارِعَ، ونارُ الدُّنْيا في جَنْبِ نارِ الآخِرَةِ كَأنَّها لَيْسَتْ بِنارٍ، ولِذَلِكَ قالَ في آخِرِ السُّورَةِ: ﴿نارٌ حامِيَةٌ﴾ تَنْبِيهًا عَلى أنَّ نارَ الدُّنْيا في جَنْبِ تِلْكَ لَيْسَتْ بِحامِيَةٍ، وصارَ آخِرُ السُّورَةِ مُطابِقًا لِأوَّلِها مِن هَذا الوَجْهِ. فَإنْ قِيلَ: هَهُنا قالَ: ﴿وما أدْراكَ ما القارِعَةُ﴾ وقالَ في آخِرِ السُّورَةِ: ﴿فَأُمُّهُ هاوِيَةٌ﴾ ﴿وما أدْراكَ ما هِيَهْ﴾ ولَمْ يَقُلْ: وما أدْراكَ ما هاوِيَةٌ فَما الفَرْقُ ؟ قُلْنا: الفَرْقُ أنَّ كَوْنَها قارِعَةً أمْرٌ مَحْسُوسٌ، أمّا كَوْنُها هاوِيَةً فَلَيْسَ كَذَلِكَ، فَظَهَرَ الفَرْقُ بَيْنَ المَوْضِعَيْنِ. وثانِيها: أنَّ ذَلِكَ التَّفْصِيلَ لا سَبِيلَ لِأحَدٍ إلى العِلْمِ بِهِ إلّا بِإخْبارِ اللَّهِ وبَيانِهِ: لِأنَّهُ بَحْثٌ عَنْ وُقُوعِ الوَقَعاتِ لا عَنْ وُجُوبِ الواجِباتِ، فَلا يَكُونُ إلى مَعْرِفَتِهِ دَلِيلٌ إلّا بِالسَّمْعِ. المَسْألَةُ الرّابِعَةُ: نَظِيرُ هَذِهِ الآيَةِ قَوْلُهُ: ﴿الحاقَّةُ﴾ ﴿ما الحاقَّةُ﴾ ﴿وما أدْراكَ ما الحاقَّةُ﴾ [الحاقة: ١- ٣] ثُمَّ قالَ المُحَقِّقُونَ: قَوْلُهُ: ﴿القارِعَةُ﴾ ﴿ما القارِعَةُ﴾ أشَدُّ مِن قَوْلِهِ: ﴿الحاقَّةُ﴾ ﴿ما الحاقَّةُ﴾ لِأنَّ النّازِلَ آخِرًا لا بُدَّ وأنْ يَكُونَ أبْلَغَ: لِأنَّ المَقْصُودَ مِنهُ زِيادَةُ التَّنْبِيهِ، وهَذِهِ الزِّيادَةُ لا تَحْصُلُ إلّا إذا كانَتْ أقْوى، وأمّا بِالنَّظَرِ إلى المَعْنى، فالحاقَّةُ أشَدُّ لِكَوْنِهِ راجِعًا إلى مَعْنى العَدْلِ، والقارِعَةُ أشَدُّ لِما أنَّها تَهْجُمُ عَلى القُلُوبِ بِالأمْرِ الهائِلِ.',     source_page = '67',     updated_at  = datetime('now') WHERE id = 'QR:TE:0ae8ff22907e5170f76b7043';
UPDATE qr_tafsir_entries SET content_ar = 'ثُمَّ قالَ تَعالى: ﴿يَوْمَ يَكُونُ النّاسُ كالفَراشِ المَبْثُوثِ﴾ ﴿وتَكُونُ الجِبالُ كالعِهْنِ المَنفُوشِ﴾ قالَ صاحِبُ الكَشّافِ: الظَّرْفُ نُصِبَ بِمُضْمَرٍ دَلَّتْ عَلَيْهِ القارِعَةُ، أيْ تَقْرَعُ يَوْمَ يَكُونُ النّاسُ كَذا. واعْلَمْ أنَّهُ تَعالى وصَفَ ذَلِكَ اليَوْمَ بِأمْرَيْنِ: الأوَّلُ: كَوْنُ النّاسِ فِيهِ: ﴿كالفَراشِ المَبْثُوثِ﴾ قالَ الزَّجّاجُ: الفَراشُ هو الحَيَوانُ الَّذِي يَتَهافَتُ في النّارِ، وسُمِّيَ فَراشًا لِتَفَرُّشِهِ وانْتِشارِهِ، ثُمَّ إنَّهُ تَعالى شَبَّهَ الخَلْقَ وقْتَ البَعْثِ هَهُنا بِالفَراشِ المَبْثُوثِ، وفي آيَةٍ أُخْرى بِالجَرادِ المُنْتَشِرِ. أمّا وجْهُ التَّشْبِيهِ بِالفَراشِ، فَلِأنَّ الفَراشَ إذا ثارَ لَمْ يَتَّجِهْ لِجِهَةٍ واحِدَةٍ، بَلْ كُلُّ واحِدَةٍ مِنها تَذْهَبُ إلى غَيْرِ جِهَةِ الأُخْرى، يَدُلُّ هَذا عَلى أنَّهم إذا بُعِثُوا فَزِعُوا، واخْتَلَفُوا في المَقاصِدِ عَلى جِهاتٍ مُخْتَلِفَةٍ غَيْرِ مَعْلُومَةٍ، والمَبْثُوثُ المُفَرَّقُ، يُقالُ: بَثَّهُ إذا فَرَّقَهُ. وأمّا وجْهُ التَّشْبِيهِ بِالجَرادِ فَهو في الكَثْرَةِ. قالَ الفَرّاءُ: كَغَوْغاءِ الجَرادِ يَرْكَبُ بَعْضُهُ بَعْضًا، وبِالجُمْلَةِ فاللَّهُ سُبْحانَهُ وتَعالى شَبَّهَ النّاسَ في وقْتِ البَعْثِ بِالجَرادِ المُنْتَشِرِ، وبِالفَراشِ المَبْثُوثِ، لِأنَّهم لَمّا بُعِثُوا يَمُوجُ بَعْضُهم في بَعْضٍ كالجَرادِ والفَراشِ، ويُؤَكِّدُ ما ذَكَرْنا بِقَوْلِهِ تَعالى: ﴿فَتَأْتُونَ أفْواجًا﴾ [النبأ: ١٨] وقَوْلِهِ: ﴿يَوْمَ يَقُومُ النّاسُ لِرَبِّ العالَمِينَ﴾ [المطففين: ٦] وقَوْلِهِ في قِصَّةِ يَأْجُوجَ ومَأْجُوجَ: ﴿وتَرَكْنا بَعْضَهم يَوْمَئِذٍ يَمُوجُ في بَعْضٍ﴾ [الكهف: ٩٩] فَإنْ قِيلَ: الجَرادُ بِالنِّسْبَةِ إلى الفَراشِ كِبارٌ، فَكَيْفَ شَبَّهَ الشَّيْءَ الواحِدَ بِالصَّغِيرِ والكَبِيرِ مَعًا ؟ قُلْنا: شَبَّهَ الواحِدَ بِالصَّغِيرِ والكَبِيرِ لَكِنْ في وصْفَيْنِ. أمّا التَّشْبِيهُ بِالفَراشِ فَبِذَهابِ كُلِّ واحِدَةٍ إلى غَيْرِ جِهَةِ الأُخْرى. وأمّا بِالجَرادِ فَبِالكَثْرَةِ والتَّتابُعِ، ويُحْتَمَلُ أنْ يُقالَ: إنَّها تَكُونُ كِبارًا أوَّلًا كالجَرادِ، ثُمَّ تَصِيرُ صِغارًا كالفَراشِ بِسَبَبِ احْتِراقِهِمْ بِحَرِّ الشَّمْسِ، وذَكَرُوا في التَّشْبِيهِ بِالفَراشِ وُجُوهًا أُخْرى: أحَدُها: ما رُوِيَ أنَّهُ - عَلَيْهِ السَّلامُ - قالَ: «النّاسُ عالِمٌ ومُتَعَلِّمٌ، وسائِرُ النّاسِ هَمَجٌ رَعاعٌ» فَجَعَلَهُمُ اللَّهُ في الآخِرَةِ كَذَلِكَ: ﴿جَزاءً وِفاقًا﴾ [ النَّبَأِ: ٢٦] وثانِيها: أنَّهُ تَعالى إنَّما أدْخَلَ حَرْفَ التَّشْبِيهِ، فَقالَ: ﴿كالفَراشِ﴾ لِأنَّهم يَكُونُونَ في ذَلِكَ اليَوْمِ أذَلَّ مِنَ الفَراشِ، لِأنَّ الفَراشَ لا يُعَذَّبُ، وهَؤُلاءِ يُعَذَّبُونَ، ونَظِيرُهُ: ﴿كالأنْعامِ بَلْ هم أضَلُّ﴾ . [الأعراف: ١٧٩] الصِّفَةُ الثّانِيَةُ: مِن صِفاتِ ذَلِكَ اليَوْمِ قَوْلُهُ تَعالى: ﴿وتَكُونُ الجِبالُ كالعِهْنِ المَنفُوشِ﴾ العِهْنُ الصُّوفُ ذُو الألْوانِ، وقَدْ مَرَّ تَحْقِيقُهُ عِنْدَ قَوْلِهِ: ﴿وتَكُونُ الجِبالُ كالعِهْنِ﴾ والنَّفْشُ فَكُّ الصُّوفِ حَتّى يَنْتَفِشَ بَعْضُهُ عَنْ بَعْضٍ، وفي قِراءَةِ ابْنِ مَسْعُودٍ: ”كالصُّوفِ المَنفُوشِ“ . واعْلَمْ أنَّ اللَّهَ تَعالى أخْبَرَ أنَّ الجِبالَ مُخْتَلِفَةُ الألْوانِ عَلى ما قالَ: ﴿ومِنَ الجِبالِ جُدَدٌ بِيضٌ وحُمْرٌ مُخْتَلِفٌ ألْوانُها وغَرابِيبُ سُودٌ﴾ [فاطر: ٢٧] ثُمَّ إنَّهُ سُبْحانَهُ يُفَرِّقُ أجْزاءَها ويُزِيلُ التَّأْلِيفَ والتَّرْكِيبَ عَنْها فَيَصِيرُ ذَلِكَ مُشابِهًا لِلصُّوفِ المُلَوَّنِ بِالألْوانِ المُخْتَلِفَةِ إذا جُعِلَ مَنفُوشًا، وهَهُنا مَسائِلُ: المَسْألَةُ الأُولى: إنَّما ضَمَّ بَيْنَ حالِ النّاسِ وبَيْنَ حالِ الجِبالِ، كَأنَّهُ تَعالى نَبَّهَ عَلى أنَّ تَأْثِيرَ تِلْكَ القَرْعَةِ في الجِبالِ هو أنَّها صارَتْ كالعِهْنِ المَنفُوشِ، فَكَيْفَ يَكُونُ حالُ الإنْسانِ عِنْدَ سَماعِها فالوَيْلُ ثُمَّ الوَيْلُ لِابْنِ آدَمَ إنْ لَمْ تَتَدارَكْهُ رَحْمَةُ رَبِّهِ، ويُحْتَمَلُ أنْ يَكُونَ المُرادُ أنَّ جِبالَ النّارِ تَصِيرُ كالعِهْنِ المَنفُوشِ لِشِدَّةِ حُمْرَتِها. المَسْألَةُ الثّانِيَةُ: قَدْ وصَفَ اللَّهُ تَعالى تَغَيُّرَ الأحْوالِ عَلى الجِبالِ مِن وُجُوهٍ: أوَّلُها: أنْ تَصِيرَ قِطَعًا، كَما قالَ: ﴿دُكَّتِ الأرْضُ دَكًّا دَكًّا﴾ [الفجر: ٢١] . وثانِيها: أنْ تَصِيرَ كَثِيبًا مَهِيلًا، كَما قالَ: ﴿وتَرى الجِبالَ تَحْسَبُها جامِدَةً وهي تَمُرُّ مَرَّ السَّحابِ﴾ [النمل: ٨٨] ثُمَّ تَصِيرُ كالعِهْنِ المَنفُوشِ، وهي أجْزاءٌ كالذَّرِّ تَدْخُلُ مِن كُوَّةِ البَيْتِ لا تَمَسُّها الأيْدِي، ثُمَّ قالَ في الرّابِعِ: تَصِيرُ سَرابًا، كَما قالَ: ﴿وسُيِّرَتِ الجِبالُ فَكانَتْ سَرابًا﴾ [ النَّبَأِ: ٢٠] . المَسْألَةُ الثّالِثَةُ: لَمْ يَقُلْ: يَوْمَ يَكُونُ النّاسُ كالفَراشِ المَبْثُوثِ والجِبالُ كالعِهْنِ المَنفُوشِ بَلْ قالَ: ﴿وتَكُونُ الجِبالُ كالعِهْنِ المَنفُوشِ﴾ لِأنَّ التَّكْرِيرَ في مِثْلِ هَذا المَقامِ أبْلَغُ في التَّحْذِيرِ.',     source_page = '69',     updated_at  = datetime('now') WHERE id = 'QR:TE:2d493bf02b5fa523c495944b';
UPDATE qr_tafsir_entries SET content_ar = 'واعْلَمْ أنَّهُ تَعالى لَمّا وصَفَ يَوْمَ القِيامَةِ قَسَّمَ النّاسَ فِيهِ إلى قِسْمَيْنِ فَقالَ: ﴿فَأمّا مَن ثَقُلَتْ مَوازِينُهُ﴾ واعْلَمْ أنَّ في المَوازِينِ قَوْلَيْنِ: أحَدُهُما: أنَّهُ جَمْعُ مَوْزُونٍ وهو العَمَلُ الَّذِي لَهُ وزْنٌ وخَطَرٌ عِنْدَ اللَّهِ، وهَذا قَوْلُ الفَرّاءِ قالَ: ونَظِيرُهُ يُقالُ: عِنْدِي دِرْهَمٌ بِمِيزانِ دِرْهَمِكَ ووَزْنِ دِرْهَمِكَ ودارِي بِمِيزانِ دارِكَ ووَزْنِ دارِكَ أيْ بِحِذائِها. والثّانِي: أنَّهُ جَمْعُ مِيزانٍ، قالَ ابْنُ عَبّاسٍ: المِيزانُ لَهُ لِسانٌ وكِفَّتانِ لا يُوزَنُ فِيهِ إلّا الأعْمالُ فَيُؤْتى بِحَسَناتِ المُطِيعِ في أحْسَنِ صُورَةٍ، فَإذا رَجَحَ فالجَنَّةُ لَهُ، ويُؤْتى بِسَيِّئاتِ الكافِرِ في أقْبَحِ صُورَةٍ فَيَخِفُّ وزْنُهُ فَيَدْخُلُ النّارَ. وقالَ الحَسَنُ في المِيزانِ: لَهُ كِفَّتانِ ولا يُوصَفُ، قالَ المُتَكَلِّمُونَ: إنَّ نَفْسَ الحَسَناتِ والسَّيِّئاتِ لا يَصِحُّ وزْنُهُما، خُصُوصًا وقَدِ انْقَضَيا، بَلِ المُرادُ أنَّ الصُّحُفَ المَكْتُوبَ فِيها الحَسَناتُ والسَّيِّئاتُ تُوزَنُ، أوْ يُجْعَلُ النُّورُ عَلامَةَ الحَسَناتِ والظُّلْمَةُ عَلامَةَ السَّيِّئاتِ، أوْ تُصَوَّرُ صَحِيفَةُ الحَسَناتِ بِالصُّورَةِ الحَسَنَةِ وصَحِيفَةُ السَّيِّئاتِ بِالصُّورَةِ القَبِيحَةِ فَيَظْهَرُ بِذَلِكَ الثِّقَلُ والخِفَّةُ، وتَكُونُ الفائِدَةُ في ذَلِكَ ظُهُورَ حالِ صاحِبِ الحَسَناتِ في الجَمْعِ العَظِيمِ فَيَزْدادُ سُرُورًا، وظُهُورَ حالِ صاحِبِ السَّيِّئاتِ فَيَكُونُ ذَلِكَ كالفَضِيحَةِ لَهُ عِنْدَ الخَلائِقِ. أمّا قَوْلُهُ تَعالى: ﴿فَهُوَ في عِيشَةٍ راضِيَةٍ﴾ فالعِيشَةُ مَصْدَرٌ بِمَعْنى العَيْشِ، كالخِيفَةِ بِمَعْنى الخَوْفِ، وأمّا الرّاضِيَةُ فَقالَ الزَّجّاجُ: مَعْناهُ: أيْ: عِيشَةٍ ذاتِ رِضًا يَرْضاها صاحِبُها وهي كَقَوْلِهِمْ: لابِنٌ، وتامِرٌ بِمَعْنى: ذُو لَبَنٍ وذُو تَمْرٍ، ولِهَذا قالَ المُفَسِّرُونَ: تَفْسِيرُها: مَرْضِيَّةٌ عَلى مَعْنى يَرْضاها صاحِبُها. * * * ثُمَّ قالَ تَعالى: ﴿وأمّا مَن خَفَّتْ مَوازِينُهُ﴾ أيْ قَلَّتْ حَسَناتُهُ فَرَجَحَتِ السَّيِّئاتُ عَلى الحَسَناتِ قالَ أبُو بَكْرٍ رَضِيَ اللَّهُ عَنْهُ: إنَّما ثَقُلَتْ مَوازِينُ مَن ثَقُلَتْ مَوازِينُهُ بِاتِّباعِهِمُ الحَقَّ في الدُّنْيا وثِقَلِهِ عَلَيْهِمْ، وحُقَّ لِمِيزانٍ لا يُوضَعُ فِيهِ إلّا الحَقُّ أنْ يَكُونَ ثَقِيلًا، وإنَّما خَفَّتْ مَوازِينُ مَن خَفَّتْ مَوازِينُهُ بِاتِّباعِهِمُ الباطِلَ في الدُّنْيا وخِفَّتِهِ عَلَيْهِمْ، وحُقَّ لِمِيزانٍ يُوضَعُ فِيهِ الباطِلُ أنْ يَكُونَ خَفِيفًا، وقالَ مُقاتِلٌ: إنَّما كانَ كَذَلِكَ لِأنَّ الحَقَّ ثَقِيلٌ والباطِلَ خَفِيفٌ. ﴿فَأُمُّهُ هاوِيَةٌ﴾ ﴿وما أدْراكَ ما هِيَهْ﴾ ﴿نارٌ حامِيَةٌ﴾ أمّا قَوْلُهُ تَعالى: ﴿فَأُمُّهُ هاوِيَةٌ﴾ فَفِيهِ وُجُوهٌ: أحَدُها: أنَّ الهاوِيَةَ مِن أسْماءِ النّارِ وكَأنَّها النّارُ العَمِيقَةُ يَهْوِي أهْلُ النّارِ فِيها مَهْوًى بَعِيدًا، والمَعْنى فَمَأْواهُ النّارُ، وقِيلَ لِلْمَأْوى ”أُمٌّ“ عَلى سَبِيلِ التَّشْبِيهِ بِالأُمِّ الَّتِي لا يَقَعُ الفَزَعُ مِنَ الوَلَدِ إلّا إلَيْها. وثانِيها: فَأُمُّ رَأْسِهِ هاوِيَةٌ في النّارِ ذَكَرَهُ الأخْفَشُ، والكَلْبِيُّ، وقَتادَةُ قالَ: لِأنَّهم يَهْوُونَ في النّارِ عَلى رُءُوسِهِمْ. وثالِثُها: أنَّهم إذا دَعَوْا عَلى الرَّجُلِ بِالهَلاكِ قالُوا: هَوَتْ أُمُّهُ؛ لِأنَّهُ إذا هَوى أيْ: سَقَطَ وهَلَكَ فَقَدْ هَوَتْ أُمُّهُ حُزْنًا وثُكْلًا، فَكَأنَّهُ قِيلَ: ﴿وأمّا مَن خَفَّتْ مَوازِينُهُ﴾ فَقَدْ هَلَكَ. * * * ثُمَّ قالَ تَعالى: ﴿وما أدْراكَ ما هِيَهْ﴾ قالَ صاحِبُ الكَشّافِ: ”هِيَهْ“ ضَمِيرُ الدّاهِيَةِ الَّتِي دَلَّ عَلَيْها قَوْلُهُ: ﴿فَأُمُّهُ هاوِيَةٌ﴾ في التَّفْسِيرِ الثّالِثِ: أوْ ضَمِيرُ ”هاوِيَةٌ“ والهاءُ لِلسَّكْتِ فَإذا وصَلَ جازَ حَذْفُها، والِاخْتِيارُ الوَقْفُ بِالهاءِ لِاتِّباعِ المُصْحَفِ والهاءُ ثابِتَةٌ فِيهِ، وذَكَرْنا الكَلامَ في هَذِهِ الهاءِ عِنْدَ قَوْلِهِ: ﴿لَمْ يَتَسَنَّهْ﴾ [البقرة: ٢٥٩] ، ﴿فَبِهُداهُمُ اقْتَدِهِ﴾ [ الأنْعامِ: ٩٠] ، ﴿ما أغْنى عَنِّي مالِيَهْ﴾ [الحاقة: ٢٨] . * * * ثُمَّ قالَ تَعالى: ﴿نارٌ حامِيَةٌ﴾ والمَعْنى أنَّ سائِرَ النِّيرانِ بِالنِّسْبَةِ إلَيْها كَأنَّها لَيْسَتْ حامِيَةً، وهَذا القَدْرُ كافٍ في التَّنْبِيهِ عَلى قُوَّةِ سُخُونَتِها، نَعُوذُ بِاللَّهِ مِنها ومِن جَمِيعِ أنْواعِ العَذابِ، ونَسْألُهُ التَّوْفِيقَ وحُسْنَ المَآبِ: ﴿رَبَّنا وآتِنا ما وعَدْتَنا عَلى رُسُلِكَ ولا تُخْزِنا يَوْمَ القِيامَةِ إنَّكَ لا تُخْلِفُ المِيعادَ﴾ [آل عمران: ١٩٤]',     source_page = '71',     updated_at  = datetime('now') WHERE id = 'QR:TE:b85aeb49141a398ee94f163a';
UPDATE qr_tafsir_entries SET content_ar = '(سُورَةُ التَّكاثُرِ) ثَمانِ آياتٍ مَكِّيَّةٌ بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ ﴿ألْهاكُمُ التَّكاثُرُ﴾ ﴿حَتّى زُرْتُمُ المَقابِرَ﴾ ﷽ ﴿ألْهاكُمُ التَّكاثُرُ﴾ ﴿حَتّى زُرْتُمُ المَقابِرَ﴾ فِيهِ مَسائِلُ: المَسْألَةُ الأُولى: الإلْهاءُ الصَّرْفُ إلى اللَّهْوِ. واللَّهْوُ الِانْصِرافُ إلى ما يَدْعُو إلَيْهِ الهَوى، ومَعْلُومٌ أنَّ الِانْصِرافَ إلى الشَّيْءِ يَقْتَضِي الإعْراضَ عَنْ غَيْرِهِ، فَلِهَذا قالَ أهْلُ اللُّغَةِ: ألْهانِي فُلانٌ عَنْ كَذا أيْ أنْسانِي وشَغَلَنِي، ومِنهُ الحَدِيثُ: ”أنَّ الزُّبَيْرَ كانَ إذا سَمِعَ صَوْتَ الرَّعْدِ لَهى عَنْ حَدِيثِهِ“ أيْ تَرَكَهُ وأعْرَضَ عَنْهُ، وكُلُّ شَيْءٍ تَرَكْتَهُ فَقَدْ لَهَيْتَ عَنْهُ، والتَّكاثُرُ التَّباهِي بِكَثْرَةِ المالِ والجاهِ والمَناقِبِ يُقالُ: تَكاثَرَ القَوْمُ تَكاثُرًا إذا تَعادَلُوا ما لَهم مِن كَثْرَةِ المَناقِبِ، وقالَ أبُو مُسْلِمٍ: التَّكاثُرُ تَفاعُلٌ عَنِ الكَثْرَةِ، والتَّفاعُلُ يَقَعُ عَلى أحَدِ وُجُوهٍ ثَلاثَةٍ يَحْتَمِلُ أنْ يَكُونَ بَيْنَ الِاثْنَيْنِ فَيَكُونُ مُفاعَلَةً، ويَحْتَمِلُ تَكَلُّفَ الفِعْلِ تَقُولُ: تَكارَهْتُ عَلى كَذا إذا فَعَلْتَهُ وأنْتَ كارِهٌ، وتَقُولُ: تَباعَدْتُ عَنِ الأمْرِ إذا تَكَلَّفْتَ العَمى عَنْهُ وتَقُولُ: تَغافَلْتُ، ويَحْتَمِلُ أيْضًا الفِعْلَ بِنَفْسِهِ كَما تَقُولُ: تَباعَدْتُ عَنِ الأمْرِ أيْ بَعُدْتُ عَنْهُ، ولَفْظُ التَّكاثُرِ في هَذِهِ الآيَةِ يَحْتَمِلُ الوَجْهَيْنِ الأوَّلِينَ، فَيَحْتَمِلُ التَّكاثُرَ بِمَعْنى المُفاعَلَةِ لِأنَّهُ كَمْ مِنِ اثْنَيْنِ يَقُولُ كُلُّ واحِدٍ مِنهُما لِصاحِبِهِ: ﴿أنا أكْثَرُ مِنكَ مالًا وأعَزُّ نَفَرًا﴾ ويَحْتَمِلُ تَكَلُّفَ الكَثْرَةِ فَإنَّ الحَرِيصَ يَتَكَلَّفُ جَمِيعَ عُمُرِهِ تَكْثِيرَ مالِهِ، واعْلَمْ أنَّ التَّفاخُرَ والتَّكاثُرَ شَيْءٌ واحِدٌ، ونَظِيرُ هَذِهِ الآيَةِ قَوْلُهُ تَعالى: ﴿وتَفاخُرٌ بَيْنَكُمْ﴾ [ الحَدِيدِ: ٢٠] المَسْألَةُ الثّانِيَةُ: اعْلَمْ أنَّ التَّفاخُرَ إنَّما يَكُونُ بِإثْباتِ الإنْسانِ نَوْعًا مِن أنْواعِ السَّعادَةِ لِنَفْسِهِ، وأجْناسُ السَّعادَةِ ثَلاثَةٌ: فَأحَدُها: في النَّفْسِ. والثّانِيَةُ: في البَدَنِ. والثّالِثَةُ: فِيما يُطِيفُ بِالبَدَنِ مِن خارِجٍ، أمّا الَّتِي في النَّفْسِ فَهِيَ العُلُومُ والأخْلاقُ الفاضِلَةُ وهُما المُرادانِ بِقَوْلِهِ حِكايَةً عَنْ إبْراهِيمَ: ﴿رَبِّ هَبْ لِي حُكْمًا وألْحِقْنِي بِالصّالِحِينَ﴾ [الشعراء: ٨٣] وبِهِما يُنالُ البَقاءُ الأبَدِيُّ والسَّعادَةُ السَّرْمَدِيَّةُ. وأمّا الَّتِي في البَدَنِ فَهي الصِّحَّةُ والجَمالُ وهي المَرْتَبَةُ الثّانِيَةُ، وأمّا الَّتِي تُطِيفُ بِالبَدَنِ مِن خارِجٍ فَقِسْمانِ: أحَدُهُما: ضَرُورِيٌّ وهو المالُ والجاهُ والآخَرُ غَيْرُ ضَرُورِيٍّ وهو الأقْرِباءُ والأصْدِقاءُ وهَذا الَّذِي عَدَدْناهُ في المَرْتَبَةِ الثّالِثَةِ إنَّما يُرادُ كُلُّهُ لِلْبَدَنِ بِدَلِيلِ أنَّهُ إذا تَألَّمَ عُضْوٌ مِن أعْضائِهِ فَإنَّهُ يَجْعَلُ المالَ والجاهَ فِداءً لَهُ. وأمّا السَّعادَةُ البَدَنِيَّةُ فالفُضَلاءُ مِنَ النّاسِ إنَّما يُرِيدُونَها لِلسَّعادَةِ النَّفْسانِيَّةِ فَإنَّهُ ما لَمْ يَكُنْ صَحِيحَ البَدَنِ لَمْ يَتَفَرَّغْ لِاكْتِسابِ السَّعاداتِ النَّفْسانِيَّةِ الباقِيَةِ، إذا عَرَفْتَ هَذا فَنَقُولُ: العاقِلُ يَنْبَغِي أنْ يَكُونَ سَعْيُهُ في تَقْدِيمِ الأهَمِّ عَلى المُهِمِّ، فالتَّفاخُرُ بِالمالِ والجاهِ والأعْوانِ والأقْرِباءِ تَفاخُرٌ بِأخَسِّ المَراتِبِ مِن أسْبابِ السَّعاداتِ، والِاشْتِغالُ بِهِ يَمْنَعُ الإنْسانَ مِن تَحْصِيلِ السَّعادَةِ النَّفْسانِيَّةِ بِالعِلْمِ والعَمَلِ، فَيَكُونُ ذَلِكَ تَرْجِيحًا لِأخَسِّ المَراتِبِ في السَّعاداتِ عَلى أشْرَفِ المَراتِبِ فِيها، وذَلِكَ يَكُونُ عَكْسَ الواجِبِ ونَقِيضَ الحَقِّ، فَلِهَذا السَّبَبِ ذَمَّهُمُ اللَّهُ تَعالى فَقالَ: ﴿ألْهاكُمُ التَّكاثُرُ﴾ ويَدْخُلُ فِيهِ التَّكاثُرُ بِالعَدَدِ وبِالمالِ والجاهِ والأقْرِباءِ والأنْصارِ والجَيْشِ، وبِالجُمْلَةِ فَيَدْخُلُ فِيهِ التَّكاثُرُ بِكُلِّ ما يَكُونُ مِنَ الدُّنْيا ولَذّاتِها وشَهَواتِها. المَسْألَةُ الثّالِثَةُ: قَوْلُهُ: ﴿ألْهاكُمُ﴾ يُحْتَمَلُ أنْ يَكُونَ إخْبارًا عَنْهم، ويُحْتَمَلُ أنْ يَكُونَ اسْتِفْهامًا بِمَعْنى التَّوْبِيخِ والتَّقْرِيعِ أيْ ”أألْهاكُمْ“ كَما قُرِئَ ”أنْذَرْتَهم“ و”أأنْذَرْتَهم“ و”إذا كُنّا عِظامًا“ و”أئِذا كُنّا عِظامًا“ . المَسْألَةُ الرّابِعَةُ: الآيَةُ دَلَّتْ عَلى أنَّ التَّكاثُرَ والتَّفاخُرَ مَذْمُومٌ، والعَقْلُ دَلَّ عَلى أنَّ التَّكاثُرَ والتَّفاخُرَ في السَّعاداتِ الحَقِيقِيَّةِ غَيْرُ مَذْمُومٍ، ومِن ذَلِكَ ما رُوِيَ مِن تَفاخُرِ العَبّاسِ بِأنَّ السِّقايَةَ بِيَدِهِ، وتَفاخُرِ شَيْبَةَ بِأنَّ المِفْتاحَ بِيَدِهِ إلى أنْ قالَ عَلِيٌّ عَلَيْهِ السَّلامُ: وأنا قَطَعْتُ خُرْطُومَ الكُفْرِ بِسَيْفِي فَصارَ الكُفْرُ مُثْلَةً فَأسْلَمْتُمْ فَشَقَّ ذَلِكَ عَلَيْهِمْ فَنَزَلَ قَوْلُهُ تَعالى: ﴿أجَعَلْتُمْ سِقايَةَ الحاجِّ﴾ [ التَّوْبَةِ: ١٩] الآيَةَ وذَكَرْنا في تَفْسِيرِ قَوْلِهِ تَعالى: ﴿وأمّا بِنِعْمَةِ رَبِّكَ فَحَدِّثْ﴾ [ الضُّحى: ١١] أنَّهُ يَجُوزُ لِلْإنْسانِ أنْ يَفْتَخِرَ بِطاعاتِهِ ومَحاسِنِ أخْلاقِهِ إذا كانَ يَظُنُّ أنَّ غَيْرَهُ يَقْتَدِي بِهِ، فَثَبَتَ أنَّ مُطْلَقَ التَّكاثُرِ لَيْسَ بِمَذْمُومٍ، بَلِ التَّكاثُرُ في العِلْمِ والطّاعَةِ والأخْلاقِ الحَمِيدَةِ، هو المَحْمُودُ، وهو أصْلُ الخَيْراتِ، فالألِفُ واللّامُ في التَّكاثُرِ لَيْسا لِلِاسْتِغْراقِ، بَلْ لِلْمَعْهُودِ السّابِقِ، وهو التَّكاثُرُ في الدُّنْيا ولَذّاتِها وعَلائِقِها، فَإنَّهُ هو الَّذِي يَمْنَعُ عَنْ طاعَةِ اللَّهِ تَعالى وعُبُودِيَّتِهِ، ولَمّا كانَ ذَلِكَ مُقَرَّرًا في العُقُولِ ومُتَّفَقًا عَلَيْهِ في الأدْيانِ، لا جَرَمَ حَسُنَ إدْخالُ حَرْفِ التَّعْرِيفِ عَلَيْهِ. المَسْألَةُ الخامِسَةُ: في تَفْسِيرِ الآيَةِ وُجُوهٌ: أحَدُها: ﴿ألْهاكُمُ التَّكاثُرُ﴾ بِالعَدَدِ رُوِيَ أنَّها نَزَلَتْ في بَنِي سَهْمٍ وبَنِي عَبْدِ مَنافٍ تَفاخَرُوا أيُّهم أكْثَرُ فَكانَ بَنُو عَبْدِ مَنافٍ أكْثَرَ فَقالَ بَنُو سَهْمٍ: عُدُّوا مَجْمُوعَ أحْيائِنا وأمْواتِنا مَعَ مَجْمُوعِ أحْيائِكم وأمْواتِكم، فَفَعَلُوا فَزادَ بَنُو سَهْمٍ، فَنَزَلَتِ الآيَةُ وهَذِهِ الرِّوايَةُ مُطابِقَةٌ لِظاهِرِ القُرْآنِ، لِأنَّ قَوْلَهُ: ﴿حَتّى زُرْتُمُ المَقابِرَ﴾ يَدُلُّ عَلى أنَّهُ أمْرٌ مَضى. فَكَأنَّهُ تَعالى يُعَجِّبُهم مِن أنْفُسِهِمْ، ويَقُولُ هَبْ أنَّكم أكْثَرُ مِنهم عَدَدًا فَماذا يَنْفَعُ ؟ والزِّيارَةُ إتْيانُ المَوْضِعِ، وذَلِكَ يَكُونُ لِأغْراضٍ كَثِيرَةٍ، وأهَمُّها وأوْلاها بِالرِّعايَةِ تَرْقِيقُ القَلْبِ وإزالَةُ حُبِّ الدُّنْيا، فَإنَّ مُشاهَدَةَ القُبُورِ تُورِثُ ذَلِكَ عَلى ما قالَ عَلَيْهِ السَّلامُ: «كُنْتُ نَهَيْتُكم عَنْ زِيارَةِ القُبُورِ ألا فَزُورُوها فَإنَّ في زِيارَتِها تَذْكِرَةً» ثُمَّ إنَّكم زُرْتُمُ القُبُورَ، بِسَبَبِ قَساوَةِ القَلْبِ والِاسْتِغْراقِ في حُبِّ الدُّنْيا فَلَمّا انْعَكَسَتْ هَذِهِ القَضِيَّةُ، لا جَرَمَ ذَكَرَ اللَّهُ تَعالى ذَلِكَ في مَعْرِضِ التَّعْجِيبِ. والقَوْلُ الثّانِي: أنَّ المُرادَ هو التَّكاثُرُ بِالمالِ واسْتَدَلُّوا عَلَيْهِ بِما رَوى مُطَرِّفُ بْنُ عَبْدِ اللَّهِ بْنِ الشِّخِّيرِ عَنْ أبِيهِ، أنَّهُ - عَلَيْهِ السَّلامُ -كانَ يَقْرَأُ: ﴿ألْهاكُمُ﴾ وقالَ: «ابْنُ آدَمَ يَقُولُ: مالِي مالِي، وهَلْ لَكَ مِن مالِكَ إلّا ما أكَلْتَ فَأفْنَيْتَ، أوْ لَبِسْتَ فَأبْلَيْتَ، أوْ تَصَدَّقْتَ فَأمْضَيْتَ» ، والمُرادُ مِن قَوْلِهِ: ﴿حَتّى زُرْتُمُ المَقابِرَ﴾ أيْ حَتّى مُتُّمْ، وزِيارَةُ القَبْرِ عِبارَةٌ عَنِ المَوْتِ، يُقالُ لِمَن ماتَ: زارَ قَبْرَهُ وزارَ رَمْسَهُ، قالَ جَرِيرٌ لِلْأخْطَلِ: زارَ القُبُورَ أبُو مالِكٍ فَأصْبَحَ ألْأمَ زُوّارِها أيْ ماتَ، فَيَكُونُ مَعْنى الآيَةِ: ألْهاكم حِرْصُكم عَلى تَكْثِيرِ أمْوالِكم عَنْ طاعَةِ رَبِّكم حَتّى أتاكُمُ المَوْتُ، وأنْتُمْ عَلى ذَلِكَ، يُقالُ: حَمْلُهُ عَلى هَذا الوَجْهِ مُشْكِلٌ مِن وجْهَيْنِ: الأوَّلُ: أنَّ الزّائِرَ هو الَّذِي يَزُورُ ساعَةً ثُمَّ يَنْصَرِفُ، والمَيِّتُ يَبْقى في قَبْرِهِ، فَكَيْفَ يُقالُ: إنَّهُ زارَ القَبْرَ ؟ والثّانِي: أنَّ قَوْلَهُ: ﴿حَتّى زُرْتُمُ المَقابِرَ﴾ إخْبارٌ عَنِ الماضِي، فَكَيْفَ يُحْمَلُ عَلى المُسْتَقْبَلِ ؟ والجَوابُ عَنِ السُّؤالِ الأوَّلِ أنَّهُ قَدْ يَمْكُثُ الزّائِرُ، لَكِنْ لا بُدَّ لَهُ مِنَ الرَّحِيلِ، وكَذا أهْلُ القُبُورِ يَرْحَلُونَ عَنْها إلى مَكانِ الحِسابِ. والجَوابُ عَنِ السُّؤالِ الثّانِي مِن وُجُوهٍ: أحَدُها: يُحْتَمَلُ أنْ يَكُونَ المُرادُ مَن كانَ مُشْرِفًا عَلى المَوْتِ بِسَبَبِ الكِبَرِ، ولِذَلِكَ يُقالُ فِيهِ: إنَّهُ عَلى شَفِيرِ القَبْرِ وثانِيها: أنَّ الخَبَرَ عَمَّنْ تَقَدَّمَهم وعْظًا لَهم، فَهو كالخَبَرِ عَنْهم، لِأنَّهم كانُوا عَلى طَرِيقَتِهِمْ، ومِنهُ قَوْلُهُ تَعالى: ﴿ويَقْتُلُونَ النَّبِيِّينَ﴾ [البقرة: ٦١] . وثالِثُها: قالَ أبُو مُسْلِمٍ: إنَّ اللَّهَ تَعالى يَتَكَلَّمُ بِهَذِهِ السُّورَةِ يَوْمَ القِيامَةِ تَعْيِيرًا لِلْكُفّارِ، وهم في ذَلِكَ الوَقْتِ قَدْ تَقَدَّمَتْ مِنهم زِيارَةُ القُبُورِ. القَوْلُ الثّالِثُ: ﴿ألْهاكُمُ﴾ الحِرْصُ عَلى المالِ وطَلَبُ تَكْثِيرِهِ حَتّى مَنَعْتُمُ الحُقُوقَ المالِيَّةَ إلى حِينِ المَوْتِ، ثُمَّ تَقُولُ في تِلْكَ الحالَةِ: أوْصَيْتُ لِأجْلِ الزَّكاةِ بِكَذا، ولِأجْلِ الحَجِّ بِكَذا. القَوْلُ الرّابِعُ: ﴿ألْهاكُمُ التَّكاثُرُ﴾ فَلا تَلْتَفِتُونَ إلى الدِّينِ، بَلْ قُلُوبُكم كَأنَّها أحْجارٌ لا تَنْكَسِرُ البَتَّةَ إلّا إذا زُرْتُمُ المَقابِرَ، هَكَذا يَنْبَغِي أنْ تَكُونَ حالُكم، وهو أنْ يَكُونَ حَظُّكم مِن دِينِكم ذَلِكَ القَدْرَ القَلِيلَ مِنَ الِانْكِسارِ، ونَظِيرُهُ قَوْلُهُ تَعالى: ﴿قَلِيلًا ما تَشْكُرُونَ﴾ [الأعراف: ١٠] أيْ لا أقْنَعُ مِنكم بِهَذا القَدْرِ القَلِيلِ مِنَ الشُّكْرِ. المَسْألَةُ السّادِسَةُ: أنَّهُ تَعالى لَمْ يَقُلْ: ﴿ألْهاكُمُ التَّكاثُرُ﴾ عَنْ كَذا وإنَّما لَمْ يَذْكُرْهُ، لِأنَّ المُطْلَقَ أبْلَغُ في الذَّمِّ لِأنَّهُ يَذْهَبُ الوَهْمُ فِيهِ كُلَّ مَذْهَبٍ، فَيَدْخُلُ فِيهِ جَمِيعُ ما يَحْتَمِلُهُ المَوْضِعُ، أيْ: ألْهاكُمُ التَّكاثُرُ عَنْ ذِكْرِ اللَّهِ وعَنِ الواجِباتِ والمَندُوباتِ في المَعْرِفَةِ والطّاعَةِ والتَّفَكُّرِ والتَّدَبُّرِ، أوْ نَقُولُ: إنْ نَظَرْنا إلى ما قَبْلَ هَذِهِ الآيَةِ فالمَعْنى: ألْهاكُمُ التَّكاثُرُ عَنِ التَّدَبُّرِ في أمْرِ القارِعَةِ والِاسْتِعْدادِ لَها قَبْلَ المَوْتِ، وإنْ نَظَرْنا إلى الأسْفَلِ فالمَعْنى ألْهاكُمُ التَّكاثُرُ، فَنَسِيتُمُ القَبْرَ حَتّى زُرْتُمُوهُ.',     source_page = '72',     updated_at  = datetime('now') WHERE id = 'QR:TE:a595e33b7e7ed8dab1294529';
UPDATE qr_tafsir_entries SET content_ar = 'أمّا قَوْلُهُ تَعالى: ﴿كَلّا سَوْفَ تَعْلَمُونَ﴾ ﴿ثُمَّ كَلّا سَوْفَ تَعْلَمُونَ﴾ فَهو يَتَّصِلُ بِما قَبْلَهُ وبِما بَعْدَهُ، أمّا الأوَّلُ فَعَلى وجْهِ الرَّدِّ والتَّكْذِيبِ أيْ: لَيْسَ الأمْرُ كَما يَتَوَهَّمُهُ هَؤُلاءِ مِن أنَّ السَّعادَةَ الحَقِيقِيَّةَ بِكَثْرَةِ العَدَدِ والأوْلادِ، وأمّا اتِّصالُهُ بِما بَعْدَهُ، فَعَلى مَعْنى القَسَمِ أيْ حَقًّا سَوْفَ تَعْلَمُونَ لَكِنْ حِينَ يَصِيرُ الفاسِقُ تائِبًا، والكافِرُ مُسْلِمًا، والحَرِيصُ زاهِدًا، ومِنهُ قَوْلُ الحَسَنِ: لا يَغُرَّنَّكَ كَثْرَةُ مَن تَرى حَوْلَكَ فَإنَّكَ تَمُوتُ وحْدَكَ، وتُحاسَبُ وحْدَكَ، وتَقْرِيرُهُ: ﴿يَوْمَ يَفِرُّ المَرْءُ﴾ [عبس: ٣٤] ، ﴿ويَأْتِينا فَرْدًا﴾ [مريم: ٨٠] ، ﴿ولَقَدْ جِئْتُمُونا فُرادى﴾ [الأنعام: ٩٤] إلى أنْ قالَ: ﴿وتَرَكْتُمْ ما خَوَّلْناكُمْ﴾ [ الأنْعامِ: ٩٤] وهَذا يَمْنَعُكَ عَنِ التَّكاثُرِ، وذَكَرُوا في التَّكْرِيرِ وُجُوهًا: أحَدُها: أنَّهُ لِلتَّأْكِيدِ، وأنَّهُ وعِيدٌ بَعْدَ وعِيدٍ كَما تَقُولُ لِلْمَنصُوحِ: أقُولُ لَكَ، ثُمَّ أقُولُ لَكَ: لا تَفْعَلْ. وثانِيها: أنَّ الأوَّلَ عِنْدَ المَوْتِ حَيْثُ يُقالُ لَهُ: لا بُشْرى، والثّانِي في سُؤالِ القَبْرِ: مَن رَبُّكَ ؟ والثّالِثُ عِنْدَ النُّشُورِ حِينَ يُنادِي المُنادِي، فُلانٌ شَقِيٌّ شَقاوَةً لا سَعادَةَ بَعْدَها أبَدًا وحِينَ يُقالُ: ﴿وامْتازُوا اليَوْمَ﴾ [يس: ٥٩] وثالِثُها: عَنِ الضَّحّاكِ سَوْفَ تَعْلَمُونَ أيُّها الكُفّارُ: ﴿ثُمَّ كَلّا سَوْفَ تَعْلَمُونَ﴾ أيُّها المُؤْمِنُونَ، وكانَ يَقْرَؤُها كَذَلِكَ، فالأوَّلُ وعِيدٌ والثّانِي وعْدٌ. ورابِعُها: أنَّ كُلَّ أحَدٍ يَعْلَمُ قُبْحَ الظُّلْمِ والكَذِبِ وحُسْنَ العَدْلِ والصِّدْقِ، لَكِنْ لا يَعْرِفُ قَدْرَ آثارِها ونَتائِجِها، ثُمَّ إنَّهُ تَعالى يَقُولُ: سَوْفَ تَعْلَمُ العِلْمَ المُفَصَّلَ لَكِنَّ التَّفْصِيلَ يَحْتَمِلُ الزّائِدَ، فَمَهْما حَصَلَتْ زِيادَةُ لَذَّةٍ، ازْدادَ عِلْمًا، وكَذا في جانِبِ العُقُوبَةِ، فَقَسَّمَ ذَلِكَ عَلى الأحْوالِ، فَعِنْدَ المُعايَنَةِ يَزْدادُ، ثُمَّ عِنْدَ البَعْثِ، ثُمَّ عِنْدَ الحِسابِ، ثُمَّ عِنْدَ دُخُولِ الجَنَّةِ والنّارِ، فَلِذَلِكَ وقَعَ التَّكْرِيرُ. وخامِسُها: أنَّ إحْدى الحالَتَيْنِ عَذابُ القَبْرِ والأُخْرى عَذابُ القِيامَةِ، كَما رُوِيَ عَنْ أبِي ذَرٍّ أنَّهُ قالَ: كُنْتُ أشُكُّ في عَذابِ القَبْرِ، حَتّى سَمِعْتُ عَلِيَّ بْنَ أبِي طالِبٍ - عَلَيْهِ السَّلامُ - يَقُولُ: إنَّ هَذِهِ الآيَةَ تَدُلُّ عَلى عَذابِ القَبْرِ، وإنَّما قالَ: ﴿ثُمَّ﴾ لِأنَّ بَيْنَ العالَمَيْنِ والحَياتَيْنِ مَوْتًا. ﴿كَلّا لَوْ تَعْلَمُونَ عِلْمَ اليَقِينِ﴾ ﴿لَتَرَوُنَّ الجَحِيمَ﴾ ﴿ثُمَّ لَتَرَوُنَّها عَيْنَ اليَقِينِ﴾ وفِيهِ مَسائِلُ: المَسْألَةُ الأُولى: اتَّفَقُوا عَلى أنَّ جَوابَ ”لَوْ“ مَحْذُوفٌ، وأنَّهُ لَيْسَ قَوْلُهُ: ﴿لَتَرَوُنَّ الجَحِيمَ﴾ جَوابَ ”لَوْ“ ويَدُلُّ عَلَيْهِ وجْهانِ: أحَدُهُما: أنَّ ما كانَ جَوابَ ”لَوْ“ فَنَفْيُهُ إثْباتٌ، وإثْباتُهُ نَفْيٌ، فَلَوْ كانَ قَوْلُهُ: ﴿لَتَرَوُنَّ الجَحِيمَ﴾ جَوابًا لِـ ”لَوْ“ لَوَجَبَ أنْ لا تَحْصُلَ هَذِهِ الرُّؤْيَةُ، وذَلِكَ باطِلٌ، فَإنَّ هَذِهِ الرُّؤْيَةَ واقِعَةٌ قَطْعًا، فَإنْ قِيلَ: المُرادُ مِن هَذِهِ الرُّؤْيَةِ رُؤْيَتُها بِالقَلْبِ في الدُّنْيا، ثُمَّ إنَّ هَذِهِ الرُّؤْيَةَ غَيْرُ واقِعَةٍ قُلْنا: تَرْكُ الظّاهِرِ خِلافُ الأصْلِ. والثّانِي: أنَّ قَوْلَهُ: ﴿ثُمَّ لَتُسْألُنَّ يَوْمَئِذٍ عَنِ النَّعِيمِ﴾ إخْبارٌ عَنْ أمْرٍ سَيَقَعُ قَطْعًا، فَعَطْفُهُ عَلى ما لا يُوجَدُ ولا يَقَعُ قَبِيحٌ في النَّظْمِ، واعْلَمْ أنَّ تَرْكَ الجَوابِ في مِثْلِ هَذا المَكانِ أحْسَنُ، يَقُولُ الرَّجُلُ لِلرَّجُلِ: لَوْ فَعَلْتَ هَذا أيْ لَكانَ كَذا، قالَ اللَّهُ تَعالى: ﴿لَوْ يَعْلَمُ الَّذِينَ كَفَرُوا حِينَ لا يَكُفُّونَ عَنْ وُجُوهِهِمُ النّارَ ولا عَنْ ظُهُورِهِمْ﴾ [الأنْبِياءِ: ٣٩ ] ولَمْ يَجِئْ لَهُ جَوابٌ وقالَ: ﴿ولَوْ تَرى إذْ وُقِفُوا عَلى رَبِّهِمْ﴾ [ الأنْعامِ: ٣٠] إذا عَرَفْتَ هَذا فَنَقُولُ: ذَكَرُوا في جَوابِ ”لَوْ“ وُجُوهًا: أحَدُها: قالَ الأخْفَشُ: ”لَوْ تَعْلَمُونَ عِلْمَ اليَقِينِ“ ما ألْهاكُمُ التَّكاثُرُ. وثانِيها: قالَ أبُو مُسْلِمٍ: لَوْ عَلِمْتُمْ ماذا يَجِبُ عَلَيْكم لَتَمَسَّكْتُمْ بِهِ أوْ لَوْ عَلِمْتُمْ لِأيِّ أمْرٍ خُلِقْتُمْ لاشْتَغَلْتُمْ بِهِ. وثالِثُها: أنَّهُ حَذَفَ الجَوابَ لِيَذْهَبَ الوَهْمُ كُلَّ مَذْهَبٍ فَيَكُونُ التَّهْوِيلُ أعْظَمَ، وكَأنَّهُ قالَ: ”لَوْ عَلِمْتُمْ عِلْمَ اليَقِينِ لَفَعَلْتُمْ ما لا يُوصَفُ ولا يُكْتَنَهُ، ولَكِنَّكم ضُلّالٌ وجَهَلَةٌ“، وأمّا قَوْلُهُ: ﴿لَتَرَوُنَّ الجَحِيمَ﴾ فاللّامُ يَدُلُّ عَلى أنَّهُ جَوابُ قَسَمٍ مَحْذُوفٍ، والقَسَمُ لِتَوْكِيدِ الوَعِيدِ، وأنَّ ما أُوعَدا بِهِ مِمّا لا مَدْخَلَ فِيهِ لِلرَّيْبِ وكَرَّرَهُ مَعْطُوفًا بِـ ”ثُمَّ“ تَغْلِيظًا لِلتَّهْدِيدِ وزِيادَةً في التَّهْوِيلِ. المَسْألَةُ الثّانِيَةُ: أنَّهُ تَعالى أعادَ لَفْظَ ”كَلّا“ وهو لِلزَّجْرِ، وإنَّما حَسُنَتِ الإعادَةُ: لِأنَّهُ عَقَّبَهُ في كُلِّ مَوْضِعٍ بِغَيْرِ ما عَقَّبَ بِهِ المَوْضِعَ الآخَرَ، كَأنَّهُ تَعالى قالَ: لا تَفْعَلُوا هَذا فَإنَّكم تَسْتَحِقُّونَ بِهِ مِنَ العَذابِ كَذا لا تَفْعَلُوا هَذا فَإنَّكم تَسْتَوْجِبُونَ بِهِ ضَرَرًا آخَرَ، وهَذا التَّكْرِيرُ لَيْسَ بِالمَكْرُوهِ بَلْ هو مَرْضِيٌّ عِنْدَهم، وكانَ الحَسَنُ رَحِمَهُ اللَّهُ يَجْعَلُ مَعْنى ﴿كَلّا﴾ في هَذا المَوْضِعِ بِمَعْنى ”حَقًّا“ كَأنَّهُ قِيلَ حَقًّا: ﴿لَوْ تَعْلَمُونَ عِلْمَ اليَقِينِ﴾ . المَسْألَةُ الثّالِثَةُ: في قَوْلِهِ: ﴿عِلْمَ اليَقِينِ﴾ وجْهانِ: أحَدُهُما: أنَّ مَعْناهُ عِلْمًا يَقِينًا فَأُضِيفَ المَوْصُوفُ إلى الصِّفَةِ، كَقَوْلِهِ تَعالى: ﴿ولَدارُ الآخِرَةِ﴾ [ يُوسُفَ: ١٠٩] وكَمّا يُقالُ: مَسْجِدُ الجامِعِ وعامُ الأوَّلِ. والثّانِي: أنَّ اليَقِينَ هَهُنا هو المَوْتُ والبَعْثُ والقِيامَةُ، وقَدْ سُمِّيَ المَوْتُ يَقِينًا في قَوْلِهِ: ﴿واعْبُدْ رَبَّكَ حَتّى يَأْتِيَكَ اليَقِينُ﴾ [الحِجْرِ: ٩٩ ] ولِأنَّهُما إذا وقَعا جاءَ اليَقِينُ وزالَ الشَّكُّ، فالمَعْنى لَوْ تَعْلَمُونَ عِلْمَ المَوْتِ وما يَلْقى الإنْسانُ مَعَهُ وبَعْدَهُ في القَبْرِ وفي الآخِرَةِ لَمْ يُلْهِكُمُ التَّكاثُرُ والتَّفاخُرُ عَنْ ذِكْرِ اللَّهِ، وقَدْ يَقُولُ الإنْسانُ: أنا أعْلَمُ عِلْمَ كَذا أيْ: أتَحَقَّقُهُ، وفُلانٌ يَعْلَمُ عِلْمَ الطِّبِّ وعِلْمَ الحِسابِ، لِأنَّ العُلُومَ أنْواعٌ، فَيَصْلُحُ لِذَلِكَ أنْ يُقالَ: عَلِمْتُ عِلْمَ كَذا. * * * المَسْألَةُ الرّابِعَةُ: العِلْمُ مِن أشَدِّ البَواعِثِ عَلى العَمَلِ، فَإذا كانَ وقْتُ العَمَلِ أمامَهُ كانَ وعْدًا وعِظَةً، وإنْ كانَ بَعْدَ وفاةِ وقْتِ العَمَلِ فَحِينَئِذٍ يَكُونُ حَسْرَةً ونَدامَةً، كَما ذُكِرَ أنَّ ذا القَرْنَيْنِ لَمّا دَخَلَ الظُّلُماتِ (وجَدَ خَرَزًا)، فالَّذِينَ كانُوا مَعَهُ أخَذُوا مِن تِلْكَ الخَرَزِ فَلَمّا خَرَجُوا مِنَ الظُّلُماتِ وجَدُوها جَواهِرَ، ثُمَّ الآخِذُونَ كانُوا في الغَمِّ أيْ لَمّا لَمْ يَأْخُذُوا أكْثَرَ مِمّا أخَذُوا، والَّذِينَ لَمْ يَأْخُذُوا كانُوا أيْضًا في الغَمِّ، فَهَكَذا يَكُونُ أحْوالُ أهْلِ القِيامَةِ. المَسْألَةُ الخامِسَةُ: في الآيَةِ تَهْدِيدٌ عَظِيمٌ لِلْعُلَماءِ فَإنَّها دَلَّتْ عَلى أنَّهُ لَوْ حَصَلَ اليَقِينُ بِما في التَّكاثُرِ والتَّفاخُرِ مِنَ الآفَةِ لَتَرَكُوا التَّكاثُرَ والتَّفاخُرَ، وهَذا يَقْتَضِي أنَّ مَن لَمْ يَتْرُكِ التَّكاثُرَ والتَّفاخُرَ لا يَكُونُ اليَقِينُ حاصِلًا لَهُ فالوَيْلُ لِلْعالِمِ الَّذِي لا يَكُونُ عامِلًا ثُمَّ الوَيْلُ لَهُ. المَسْألَةُ السّادِسَةُ: في تَكْرارِ الرُّؤْيَةِ وُجُوهٌ: أحَدُها: أنَّهُ لِتَأْكِيدِ الوَعِيدِ أيْضًا لَعَلَّ القَوْمَ كانُوا يَكْرَهُونَ سَماعَ الوَعِيدِ فَكَرَّرَ لِذَلِكَ، ونُونُ التَّأْكِيدِ تَقْتَضِي كَوْنَ تِلْكَ الرُّؤْيَةِ اضْطِرارِيَّةً، يَعْنِي لَوْ خُلِّيتُمْ ورَأْيَكم ما رَأيْتُمُوها لَكِنَّكم تُحْمَلُونَ عَلى رُؤْيَتِها شِئْتُمْ أمْ أبَيْتُمْ. وثانِيها: أنَّ أوَّلَهُما الرُّؤْيَةُ مِنَ البَعِيدِ: ﴿إذا رَأتْهم مِن مَكانٍ بَعِيدٍ سَمِعُوا لَها تَغَيُّظًا﴾ [الفرقان: ١٢] وقَوْلُهُ: ﴿وبُرِّزَتِ الجَحِيمُ لِمَن يَرى﴾ [النازعات: ٣٦] والرُّؤْيَةُ الثّانِيَةُ إذا صارُوا إلى شَفِيرِ النّارِ. وثالِثُها: أنَّ الرُّؤْيَةَ الأُولى عِنْدَ الوُرُودِ والثّانِيَةَ عِنْدَ الدُّخُولِ فِيها، وقِيلَ: هَذا التَّفْسِيرُ لَيْسَ بِحَسَنٍ لِأنَّهُ قالَ: ﴿ثُمَّ لَتُسْألُنَّ﴾ والسُّؤالُ يَكُونُ قَبْلَ الدُّخُولِ. ورابِعُها: الرُّؤْيَةُ الأُولى الوَعْدُ والثّانِيَةُ المُشاهَدَةُ. وخامِسُها: أنْ يَكُونَ المُرادُ لَتَرَوُنَّ الجَحِيمَ غَيْرَ مَرَّةٍ فَيَكُونُ ذِكْرُ الرُّؤْيَةِ مَرَّتَيْنِ عِبارَةً عَنْ تَتابُعِ الرُّؤْيَةِ واتِّصالِها لِأنَّهم مُخَلَّدُونَ في الجَحِيمِ فَكَأنَّهُ قِيلَ لَهم عَلى جِهَةِ الوَعِيدِ: لَئِنْ كُنْتُمُ اليَوْمَ شاكِّينَ فِيها غَيْرَ مُصَدِّقِينَ بِها فَسَتَرَوْنَها رُؤْيَةً دائِمَةً مُتَّصِلَةً فَتَزُولُ عَنْكُمُ الشُّكُوكُ وهو كَقَوْلِهِ: ﴿ما تَرى في خَلْقِ الرَّحْمَنِ مِن تَفاوُتٍ﴾ - إلى قَوْلِهِ - ﴿ارْجِعِ البَصَرَ كَرَّتَيْنِ﴾ [الملك: ٣، ٤] بِمَعْنى لَوْ أعَدْتَ النَّظَرَ فِيها ما شِئْتَ لَمْ تَجِدْ فُطُورًا ولَمْ يُرِدْ مَرَّتَيْنِ فَقَطْ، فَكَذا هَهُنا، إنْ قِيلَ: ما فائِدَةُ تَخْصِيصِ الرُّؤْيَةِ الثّانِيَةِ بِاليَقِينِ ؟ قُلْنا: لِأنَّهم في المَرَّةِ الأُولى رَأوْا لَهَبًا لا غَيْرُ، وفي المَرَّةِ الثّانِيَةِ رَأوْا نَفْسَ الحُفْرَةِ وكَيْفِيَّةَ السُّقُوطِ فِيها وما فِيها مِنَ الحَيَواناتِ المُؤْذِيَةِ، ولا شَكَّ أنَّ هَذِهِ الرُّؤْيَةَ أجْلى، والحِكْمَةُ في النَّقْلِ مِنَ العِلْمِ الأخْفى إلى الأجْلى التَّفْرِيعُ عَلى تَرْكِ النَّظَرِ لِأنَّهم كانُوا يَقْتَصِرُونَ عَلى الظَّنِّ ولا يَطْلُبُونَ الزِّيادَةَ. المَسْألَةُ السّابِعَةُ: قِراءَةُ العامَّةِ لَتَرَوُنَّ بِفَتْحِ التّاءِ، وقُرِئَ بِضَمِّها مِن رَأيْتُهُ الشَّيْءَ، والمَعْنى أنَّهم يُحْشَرُونَ إلَيْها فَيَرَوْنَها، وهَذِهِ القِراءَةُ تُرْوى عَنِ ابْنِ عامِرٍ والكِسائِيِّ كَأنَّهُما أرادا لَتُرَوُنَّها فَتَرَوْنَها، ولِذَلِكَ قَرَأ الثّانِيَةَ: (ثُمَّ لَتَرَوُنَّها) بِالفَتْحِ، وفي هَذِهِ الثّانِيَةِ دَلِيلٌ عَلى أنَّهم إذا أُرُوها رَأوْها، وفي قِراءَةِ العامَّةِ؛ الثّانِيَةُ تَكْرِيرٌ لِلتَّأْكِيدِ ولِسائِرِ الفَوائِدِ الَّتِي عَدَدْناها، واعْلَمْ أنَّ قِراءَةَ العامَّةِ أوْلى لِوَجْهَيْنِ: الأوَّلُ: قالَ الفَرّاءُ: قِراءَةُ العامَّةِ أشْبَهُ بِكَلامِ العَرَبِ لِأنَّهُ تَغْلِيظٌ، فَلا يَنْبَغِي أنَّ الجَحِيمَ لَفْظُهُ. الثّانِي: قالَ أبُو عَلِيٍّ: المَعْنى في: ﴿لَتَرَوُنَّ الجَحِيمَ﴾ لَتَرَوُنَّ عَذابَ الجَحِيمِ، ألا تَرى أنَّ الجَحِيمَ يَراها المُؤْمِنُونَ أيْضًا بِدَلالَةِ قَوْلِهِ: ﴿وإنْ مِنكم إلّا وارِدُها﴾ [مريم: ٧١] وإذا كانَ كَذَلِكَ كانَ الوَعِيدُ في رُؤْيَةِ عَذابِها لا في رُؤْيَةِ نَفْسِها، يَدُلُّ عَلى هَذا قَوْلُهُ: ﴿إذْ يَرَوْنَ العَذابَ﴾ [البقرة: ١٦٥] وقَوْلُهُ: ﴿وإذا رَأى الَّذِينَ ظَلَمُوا العَذابَ﴾ [النحل: ٨٥] وهَذا يَدُلُّ عَلى أنَّ لَتَرَوُنَّ أرْجَحُ مَن لَتُرَوُنَّ.',     source_page = '75',     updated_at  = datetime('now') WHERE id = 'QR:TE:ada31e072772e434a48b7616';
UPDATE qr_tafsir_entries SET content_ar = 'قَوْلُهُ تَعالى: ﴿ثُمَّ لَتُسْألُنَّ يَوْمَئِذٍ عَنِ النَّعِيمِ﴾ فِيهِ قَوْلانِ: المَسْألَةُ الأُولى: في أنَّ الَّذِي يُسْألُ عَنِ النَّعِيمِ مَن هو ؟ فِيهِ قَوْلانِ: أحَدُهُما: وهو الأظْهَرُ أنَّهُمُ الكُفّارُ، قالَ الحَسَنُ: لا يُسْألُ عَنِ النَّعِيمِ إلّا أهْلُ النّارِ ويَدُلُّ عَلَيْهِ وجْهانِ: الأوَّلُ: ما رُوِيَ أنَّ أبا بَكْرٍ لَمّا نَزَلَتْ هَذِهِ الآيَةُ، قالَ: «يا رَسُولَ اللَّهِ، أرَأيْتَ أكْلَةً أكَلْتُها مَعَكَ في بَيْتِ أبِي الهَيْثَمِ بْنِ التَّيِّهانِ مِن خُبْزِ شَعِيرٍ ولَحْمٍ وبُسْرٍ وماءٍ عَذْبٍ أنْ تَكُونَ مِنَ النَّعِيمِ الَّذِي نُسْألُ عَنْهُ ؟ فَقالَ عَلَيْهِ الصَّلاةُ والسَّلامُ: إنَّما ذَلِكَ لِلْكُفّارِ، ثُمَّ قَرَأ: ﴿وهَلْ نُجازِي إلّا الكَفُورَ﴾ [ سَبَأٍ»: ١٧] والثّانِي: وهو أنَّ ظاهِرَ الآيَةِ دَلَّ عَلى ما ذَكَرْناهُ، وذَلِكَ لِأنَّ الكُفّارَ ألْهاهُمُ التَّكاثُرُ بِالدُّنْيا والتَّفاخُرُ بِلَذّاتِها عَنْ طاعَةِ اللَّهِ تَعالى والِاشْتِغالِ بِشُكْرِهِ، فاللَّهُ تَعالى يَسْألُهم عَنْها يَوْمَ القِيامَةِ حَتّى يُظْهِرَ لَهم أنَّ الَّذِي ظَنُّوهُ سَبَبًا لِسَعادَتِهِمْ هو كانَ مِن أعْظَمِ أسْبابِ الشَّقاءِ لَهم في الآخِرَةِ. والقَوْلُ الثّانِي: أنَّهُ عامٌّ في حَقِّ المُؤْمِنِ والكافِرِ واحْتَجُّوا بِأحادِيثَ، رَوى أبُو هُرَيْرَةَ عَنِ النَّبِيِّ ﷺ أنَّهُ قالَ: «أوَّلُ ما يُسْألُ عَنْهُ العَبْدُ يَوْمَ القِيامَةِ عَنِ النَّعِيمِ فَيُقالُ لَهُ: ألَمْ نُصَحِّحْ لَكَ جِسْمَكَ ونَرْوِكَ مِنَ الماءِ البارِدِ» وقالَ مَحْمُودُ بْنُ لَبِيدٍ: لَمّا نَزَلَتْ هَذِهِ السُّورَةُ قالُوا: «يا رَسُولَ اللَّهِ عَنْ أيِّ نَعِيمٍ نُسْألُ ؟ إنَّما هُما الماءُ والتَّمْرُ وسُيُوفُنا عَلى عَواتِقِنا والعَدُوُّ حاضِرٌ، فَعَنْ أيِّ نَعِيمٍ نُسْألُ ؟ قالَ: إنَّ ذَلِكَ سَيَكُونُ» ورُوِيَ «عَنْ عُمَرَ أنَّهُ قالَ: أيُّ نَعِيمٍ نُسْألُ عَنْهُ يا رَسُولَ اللَّهِ وقَدْ أُخْرِجْنا مِن دِيارِنا وأمْوالِنا ؟ فَقالَ ﷺ: مَن أصْبَحَ آمِنًا في سِرْبِهِ مُعافًى في بَدَنِهِ وعِنْدَهُ قُوتُ يَوْمِهِ فَكَأنَّما حِيزَتْ لَهُ الدُّنْيا بِحَذافِيرِها» ورُوِيَ «أنَّ شابًّا أسْلَمَ في عَهْدِ رَسُولِ اللَّهِ ﷺ فَعَلَّمَهُ رَسُولُ اللَّهِ سُورَةَ ألْهاكم، ثُمَّ زَوَّجَهُ رَسُولُ اللَّهِ امْرَأةً فَلَمّا دَخَلَ عَلَيْها ورَأى الجَهازَ العَظِيمَ والنَّعِيمَ الكَثِيرَ خَرَجَ وقالَ: لا أُرِيدُ ذَلِكَ فَسَألَهُ النَّبِيُّ - عَلَيْهِ الصَّلاةُ والسَّلامُ - عَنْهُ فَقالَ: ألَسْتَ عَلَّمْتَنِي: ﴿ثُمَّ لَتُسْألُنَّ يَوْمَئِذٍ عَنِ النَّعِيمِ﴾ وأنا لا أُطِيقُ الجَوابَ عَنْ ذَلِكَ» . وعَنْ أنَسٍ لَمّا نَزَلَتِ الآيَةُ قامَ مُحْتاجٌ فَقالَ: هَلْ عَلَيَّ مِنَ النِّعْمَةِ شَيْءٌ ؟ قالَ: الظِّلُّ والنَّعْلانِ والماءُ البارِدُ. وأشْهَرُ الأخْبارِ في هَذا ما رُوِيَ أنَّهُ عَلَيْهِ الصَّلاةُ والسَّلامُ «خَرَجَ ذاتَ لَيْلَةٍ إلى المَسْجِدِ، فَلَمْ يَلْبَثْ أنْ جاءَ أبُو بَكْرٍ فَقالَ: ما أخْرَجَكَ يا أبا بَكْرٍ ؟ قالَ: الجُوعُ، قالَ: واللَّهِ ما أخْرَجَنِي إلّا الَّذِي أخْرَجَكَ، ثُمَّ دَخَلَ عُمَرُ فَقالَ مِثْلَ ذَلِكَ، فَقالَ: قُومُوا بِنا إلى مَنزِلِ أبِي الهَيْثَمِ، فَدَقَّ رَسُولُ اللَّهِ ﷺ البابَ وسَلَّمَ ثَلاثَ مَرّاتٍ فَلَمْ يُجِبْ أحَدٌ فانْصَرَفَ رَسُولُ اللَّهِ ﷺ فَخَرَجَتِ امْرَأتُهُ تَصِيحُ: كُنّا نَسْمَعُ صَوْتَكَ لَكِنْ أرَدْنا أنْ تَزِيدَ مِن سَلامِكَ فَقالَ لَها خَيْرًا، ثُمَّ قالَتْ: بِأبِي أنْتَ وأُمِّي إنَّ أبا الهَيْثَمِ خَرَجَ يَسْتَعْذِبُ لَنا الماءَ، ثُمَّ عَمَدَتْ إلى صاعٍ مِن شَعِيرٍ فَطَحَنَتْهُ وخَبَزَتْهُ ورَجَعَ أبُو الهَيْثَمِ فَذَبَحَ عَناقًا وأتاهم بِالرُّطَبِ فَأكَلُوا وشَرِبُوا فَقالَ عَلَيْهِ الصَّلاةُ والسَّلامُ: هَذا مِنَ النَّعِيمِ الَّذِي تُسْألُونَ عَنْهُ» ورُوِيَ أيْضًا: «لا تَزُولُ قَدَما عَبْدٍ حَتّى يُسْألَ عَنْ أرْبَعٍ عَنْ عُمُرِهِ ومالِهِ وشَبابِهِ وعَمَلِهِ» وعَنْ مُعاذٍ عَنِ النَّبِيِّ ﷺ «إنَّ العَبْدَ لَيُسْألُ يَوْمَ القِيامَةِ حَتّى عَنْ كُحْلِ عَيْنَيْهِ، وعَنْ فُتاتِ الطِّينَةِ بِأُصْبُعِهِ، وعَنْ لَمْسِ ثَوْبِ أخِيهِ» واعْلَمْ أنَّ الأوْلى أنْ يُقالَ: السُّؤالُ يَعُمُّ المُؤْمِنَ والكافِرَ، لَكِنَّ سُؤالَ الكافِرِ تَوْبِيخٌ؛ لِأنَّهُ تَرَكَ الشُّكْرَ، وسُؤالُ المُؤْمِنِ سُؤالُ تَشْرِيفٍ؛ لِأنَّهُ شَكَرَ وأطاعَ. * * * المَسْألَةُ الثّانِيَةُ: ذَكَرُوا في النَّعِيمِ المَسْئُولِ عَنْهُ وُجُوهًا: أحَدُها: ما رُوِيَ أنَّهُ خَمْسٌ: شِبَعُ البُطُونِ وبارِدُ الشَّرابِ ولَذَّةُ النَّوْمِ وإظْلالُ المَساكِنِ واعْتِدالُ الخَلْقِ. وثانِيها: قالَ ابْنُ مَسْعُودٍ: إنَّهُ الأمْنُ والصِّحَّةُ والفَراغُ. وثالِثُها: قالَ ابْنُ عَبّاسٍ: إنَّهُ الصِّحَّةُ وسائِرُ مَلاذِّ المَأْكُولِ والمَشْرُوبِ. ورابِعُها: قالَ بَعْضُهم: الِانْتِفاعُ بِإدْراكِ السَّمْعِ والبَصَرِ. وخامِسُها: قالَ الحَسَنُ بْنُ الفَضْلِ: تَخْفِيفُ الشَّرائِعِ وتَيْسِيرُ القُرْآنِ. وسادِسُها: قالَ ابْنُ عُمَرَ: إنَّهُ الماءُ البارِدُ. وسابِعُها: قالَ الباقِرُ: إنَّهُ العافِيَةُ، ويُرْوى أيْضًا عَنْ جابِرٍ الجُعْفِيِّ قالَ: دَخَلْتُ عَلى الباقِرِ فَقالَ: ما تَقُولُ أرْبابُ التَّأْوِيلِ في قَوْلِهِ: ﴿ثُمَّ لَتُسْألُنَّ يَوْمَئِذٍ عَنِ النَّعِيمِ﴾ ؟ فَقُلْتُ: يَقُولُونَ: الظِّلُّ والماءُ البارِدُ فَقالَ: لَوْ أنَّكَ أدْخَلْتَ بَيْتَكَ أحَدًا وأقْعَدْتَهُ في ظِلٍّ وأسْقَيْتَهُ ماءً بارِدًا أتَمُنُّ عَلَيْهِ ؟ فَقُلْتُ: لا، قالَ: فاللَّهُ أكْرَمُ مِن أنْ يُطْعِمَ عَبْدَهُ ويَسْقِيَهُ ثُمَّ يَسْألُهُ عَنْهُ، فَقُلْتُ: ما تَأْوِيلُهُ ؟ قالَ: النَّعِيمُ هو رَسُولُ اللَّهِ ﷺ أنْعَمَ اللَّهُ بِهِ عَلى هَذا العالَمِ فاسْتَنْقَذَهم بِهِ مِنَ الضَّلالَةِ، أما سَمِعْتَ قَوْلَهُ تَعالى: ﴿لَقَدْ مَنَّ اللَّهُ عَلى المُؤْمِنِينَ إذْ بَعَثَ فِيهِمْ رَسُولًا﴾ [آل عمران: ١٦٤] الآيَةَ. القَوْلُ الثّامِنُ: إنَّما يُسْألُونَ عَنِ الزّائِدِ مِمّا لا بُدَّ مِنهُ مِن مَطْعَمٍ ومَلْبَسٍ ومَسْكَنٍ. والتّاسِعُ: وهو الأوْلى أنَّهُ يَجِبُ حَمْلُهُ عَلى جَمِيعِ النِّعَمِ، ويَدُلُّ عَلَيْهِ وُجُوهٌ: أحَدُها: أنَّ الألِفَ واللّامَ يُفِيدانِ الِاسْتِغْراقَ. وثانِيها: أنَّهُ لَيْسَ صَرْفُ اللَّفْظِ إلى البَعْضِ أوْلى مِن صَرْفِهِ إلى الباقِي لا سِيَّما وقَدْ دَلَّ الدَّلِيلُ عَلى أنَّ المَطْلُوبَ مِن مَنافِعِ هَذِهِ الدُّنْيا اشْتِغالُ العَبْدِ بِعُبُودِيَّةِ اللَّهِ تَعالى. وثالِثُها: أنَّهُ تَعالى قالَ: ﴿يابَنِي إسْرائِيلَ اذْكُرُوا نِعْمَتِيَ الَّتِي أنْعَمْتُ عَلَيْكُمْ﴾ والمُرادُ مِنهُ جَمِيعُ النِّعَمِ مِن فَلْقِ البَحْرِ والإنْجاءِ مِن فِرْعَوْنَ وإنْزالِ المَنِّ والسَّلْوى فَكَذا هَهُنا. ورابِعُها: أنَّ النَّعِيمَ التّامَّ كالشَّيْءِ الواحِدِ الَّذِي لَهُ أبْعاضٌ وأعْضاءٌ فَإذا أُشِيرَ إلى النَّعِيمِ فَقَدْ دَخَلَ فِيهِ الكُلُّ، كَما أنَّ التِّرْياقَ اسْمٌ لِلْمَعْجُونِ المُرَكَّبِ مِنَ الأدْوِيَةِ الكَثِيرَةِ فَإذا ذُكِرَ التِّرْياقُ فَقَدْ دَخَلَ الكُلُّ فِيهِ. واعْلَمْ أنَّ النِّعَمَ أقْسامٌ فَمِنها ظاهِرَةٌ وباطِنَةٌ، ومِنها مُتَّصِلَةٌ ومُنْفَصِلَةٌ، ومِنها دِينِيَّةٌ ودُنْيَوِيَّةٌ، وقَدْ ذَكَرْنا أقْسامَ السَّعاداتِ بِحَسَبِ الجِنْسِ في تَفْسِيرِ أوَّلِ هَذِهِ السُّورَةِ، وأمّا تَعْدِيدُها بِحَسَبِ النَّوْعِ والشَّخْصِ فَغَيْرُ مُمْكِنٍ عَلى ما قالَهُ تَعالى: ﴿وإنْ تَعُدُّوا نِعْمَةَ اللَّهِ لا تُحْصُوها﴾ [إبراهيم: ٣٤] واسْتَعِنْ في مَعْرِفَةِ نِعَمِ اللَّهِ عَلَيْكَ في صِحَّةِ بَدَنِكَ بِالأطِبّاءِ، ثُمَّ هم أشَدُّ الخَلْقِ غَفْلَةً، وفي مَعْرِفَةِ نِعَمِ اللَّهِ عَلَيْكَ بِخَلْقِ السَّماواتِ والكَواكِبِ بِالمُنَجِّمِينَ، وهم أشَدُّ النّاسِ جَهْلًا بِالصّانِعِ، وفي مَعْرِفَةِ سُلْطانِ اللَّهِ بِالمُلُوكِ، ثُمَّ هم أجْهَلُ الخَلْقِ، وأمّا الَّذِي يُرْوى عَنِ ابْنِ عُمَرَ أنَّهُ الماءُ البارِدُ فَمَعْناهُ هَذا مِن جُمْلَتِهِ، ولَعَلَّهُ إنَّما خَصَّهُ بِالذِّكْرِ لِأنَّهُ أهْوَنُ مَوْجُودٍ وأعَزُّ مَفْقُودٍ، ومِنهُ قَوْلُ ابْنِ السَّمّاكِ لِلرَّشِيدِ: أرَأيْتَ لَوِ احْتَجْتَ إلى شَرْبَةِ ماءٍ في فَلاةٍ أكُنْتَ تَبْذُلُ فِيهِ نِصْفَ المُلْكِ ؟ وإذا شَرِقْتَ بِها أكُنْتَ تَبْذُلُ نِصْفَ المُلْكِ ؟ وإنِ احْتَبَسَ بَوْلُكَ أكُنْتَ تَبْذُلُ كُلَّ المُلْكِ ؟ فَلا تَغْتَرَّ بِمُلْكٍ كانَتِ الشَّرْبَةُ الواحِدَةُ مِنَ الماءِ قِيمَتَهُ مَرَّتَيْنِ. أوْ لِأنَّ أهْلَ النّارِ يَطْلُبُونَ الماءَ أشَدَّ مِن طَلَبِهِمْ لِغَيْرِهِ، قالَ تَعالى: ﴿أنْ أفِيضُوا عَلَيْنا مِنَ الماءِ﴾ [الأعراف: ٥٠] أوْ لِأنَّ السُّورَةَ نَزَلَتْ في المُتْرَفِينَ، وهُمُ المُخْتَصُّونَ بِالماءِ البارِدِ والظِّلِّ، والحَقُّ أنَّ السُّؤالَ يَعُمُّ المُؤْمِنَ والكافِرَ عَنْ جَمِيعِ النَّعِيمِ سَواءٌ كانَ مِمّا لا بُدَّ مِنهُ [ أوْ لا ]، ولَيْسَ كَذَلِكَ لِأنَّ كُلَّ ذَلِكَ يَجِبُ أنْ يَكُونَ مَصْرُوفًا إلى طاعَةِ اللَّهِ لا إلى مَعْصِيَتِهِ، فَيَكُونُ السُّؤالُ واقِعًا عَنِ الكُلِّ، ويُؤَكِّدُهُ ما رُوِيَ عَنْهُ - عَلَيْهِ الصَّلاةُ والسَّلامُ - أنَّهُ قالَ: «لا تَزُولُ قَدَما العَبْدِ يَوْمَ القِيامَةِ حَتّى يُسْألَ عَنْ أرْبَعٍ: عَنْ عُمُرِهِ فِيمَ أفْناهُ، وعَنْ شَبابِهِ فِيمَ أبْلاهُ، وعَنْ مالِهِ مِن أيْنَ اكْتَسَبَهُ وفِيمَ أنْفَقَهُ، وعَنْ عِلْمِهِ ماذا عَمِلَ بِهِ» فَكُلُّ النَّعِيمِ مِنَ اللَّهِ تَعالى داخِلٌ فِيما ذَكَرَهُ عَلَيْهِ الصَّلاةُ والسَّلامُ. * * * المَسْألَةُ الثّالِثَةُ: اخْتَلَفُوا في أنَّ هَذا السُّؤالَ أيْنَ يَكُونُ ؟ فالقَوْلُ الأوَّلُ: أنَّ هَذا السُّؤالَ إنَّما يَكُونُ في مَوْقِفِ الحِسابِ، فَإنْ قِيلَ: هَذا لا يَسْتَقِيمُ، لِأنَّهُ تَعالى أخْبَرَ أنَّ هَذا السُّؤالَ مُتَأخِّرٌ عَنْ مُشاهَدَةِ جَهَنَّمَ بِقَوْلِهِ: ﴿ثُمَّ لَتُسْألُنَّ﴾ ومَوْقِفُ السُّؤالِ مُتَقَدِّمٌ عَلى مُشاهَدَةِ جَهَنَّمَ ؟ قُلْنا: المُرادُ مِن قَوْلِهِ: ﴿ثُمَّ﴾ أيْ ثُمَّ أُخْبِرُكم أنَّكم تُسْألُونَ يَوْمَ القِيامَةِ، وهو كَقَوْلِهِ: ﴿فَكُّ رَقَبَةٍ﴾ ﴿أوْ إطْعامٌ في يَوْمٍ ذِي مَسْغَبَةٍ﴾ [البلد: ١٤] إلى قَوْلِهِ: ﴿ثُمَّ كانَ مِنَ الَّذِينَ آمَنُوا﴾ [البلد: ١٧] القَوْلُ الثّانِي: أنَّهم إذا دَخَلُوا النّارَ سُئِلُوا عَنِ النَّعِيمِ تَوْبِيخًا لَهم، كَما قالَ: ﴿كُلَّما أُلْقِيَ فِيها فَوْجٌ سَألَهم خَزَنَتُها﴾ [الملك: ٨] وقالَ: ﴿ما سَلَكَكم في سَقَرَ﴾ [المدثر: ٤٢] ولا شَكَّ أنَّ مَجِيءَ الرَّسُولِ نِعْمَةٌ مِنَ اللَّهِ، فَقَدْ سُئِلُوا عَنْهُ بَعْدَ دُخُولِهِمُ النّارَ، أوْ يُقالُ: إنَّهم إذا صارُوا في الجَحِيمِ وشاهَدُوها، يُقالُ لَهم: إنَّما حَلَّ بِكم هَذا العَذابُ لِأنَّكم في دارِ الدُّنْيا اشْتَغَلْتُمْ بِالنَّعِيمِ عَنِ العَمَلِ الَّذِي يُنْجِيكم مِن هَذِهِ النّارِ، ولَوْ صَرَفْتُمْ عُمُرَكم إلى طاعَةِ رَبِّكم لَكُنْتُمُ اليَوْمَ مِن أهْلِ النَّجاةِ الفائِزِينَ بِالدَّرَجاتِ، فَيَكُونُ ذَلِكَ مِنَ المَلائِكَةِ سُؤالًا عَنْ نَعِيمِهِمْ في الدُّنْيا، واللَّهُ سُبْحانَهُ وتَعالى أعْلَمُ، وصَلّى اللَّهُ عَلى سَيِّدِنا مُحَمَّدٍ وعَلى آلِهِ وصَحْبِهِ وسَلَّمَ.',     source_page = '78',     updated_at  = datetime('now') WHERE id = 'QR:TE:ffa5cc9530f94dcd9abc7059';
UPDATE qr_tafsir_entries SET content_ar = '(سُورَةُ العَصْرِ) ثَلاثُ آياتٍ، مَكِّيَّةٌ ﷽ ﴿والعَصْرِ﴾ ﷽ ﴿والعَصْرِ﴾ اعْلَمْ أنَّهم ذَكَرُوا في تَفْسِيرِ العَصْرِ أقْوالًا: الأوَّلُ: أنَّهُ الدَّهْرُ، واحْتَجَّ هَذا القائِلُ بِوُجُوهٍ: أحَدُها: ما رُوِيَ «عَنِ النَّبِيِّ ﷺ أنَّهُ أقْسَمَ بِالدَّهْرِ» ، «وكانَ - عَلَيْهِ السَّلامُ -يَقْرَأُ: والعَصْرِ ونَوائِبِ الدَّهْرِ» . إلّا أنّا نَقُولُ: هَذا مُفْسِدٌ لِلصَّلاةِ، فَلا نَقُولُ: إنَّهُ قَرَأهُ قُرْآنًا بَلْ تَفْسِيرًا، ولَعَلَّهُ تَعالى لَمْ يَذْكُرِ الدَّهْرَ لِعِلْمِهِ بِأنَّ المُلْحِدَ مُولَعٌ بِذِكْرِهِ وتَعْظِيمِهِ ومِن ذَلِكَ ذَكَرَهُ في: ﴿هَلْ أتى﴾ [ الإنْسانِ: ١] رَدًّا عَلى فَسادِ قَوْلِهِمْ بِالطَّبْعِ والدَّهْرِ. وثانِيها: أنَّ الدَّهْرَ مُشْتَمِلٌ عَلى الأعاجِيبِ لِأنَّهُ يَحْصُلُ فِيهِ السَّرّاءُ والضَّرّاءُ، والصِّحَّةُ والسُّقْمُ، والغِنى والفَقْرُ، بَلْ فِيهِ ما هو أعْجَبُ مِن كُلِّ عَجَبٍ، وهو أنَّ العَقْلَ لا يَقْوى عَلى أنْ يَحْكُمَ عَلَيْهِ بِالعَدَمِ، فَإنَّهُ مُجَزَّأٌ مُقَسَّمٌ بِالسَّنَةِ، والشَّهْرِ، واليَوْمِ، والسّاعَةِ، ومَحْكُومٌ عَلَيْهِ بِالزِّيادَةِ والنُّقْصانِ والمُطابَقَةِ، وكَوْنِهِ ماضِيًا ومُسْتَقْبَلًا، فَكَيْفَ يَكُونُ مَعْدُومًا ؟ ولا يُمْكِنُهُ أنْ يَحْكُمَ عَلَيْهِ بِالوُجُودِ لِأنَّ الحاضِرَ غَيْرُ قابِلٍ لِلْقِسْمَةِ والماضِيَ والمُسْتَقْبَلَ مَعْدُومانِ، فَكَيْفَ يُمْكِنُ الحُكْمُ عَلَيْهِ بِالوُجُودِ ؟ . وثالِثُها: أنَّ بَقِيَّةَ عُمُرِ المَرْءِ لا قِيمَةَ لَهُ، فَلَوْ ضَيَّعْتَ ألْفَ سَنَةٍ، ثُمَّ تُبْتَ في اللَّمْحَةِ الأخِيرَةِ مِنَ العُمُرِ بَقِيتَ في الجَنَّةِ أبَدَ الآبادِ فَعَلِمْتَ حِينَئِذٍ أنَّ أشْرَفَ الأشْياءِ حَياتُكَ في تِلْكَ اللَّمْحَةِ، فَكَأنَّ الدَّهْرَ والزَّمانَ مِن جُمْلَةِ أُصُولِ النِّعَمِ، فَلِذَلِكَ أقْسَمَ بِهِ ونَبَّهَ عَلى أنَّ اللَّيْلَ والنَّهارَ فُرْصَةٌ يُضَيِّعُها المُكَلَّفُ، وإلَيْهِ الإشارَةُ بِقَوْلِهِ: ﴿وهُوَ الَّذِي جَعَلَ اللَّيْلَ والنَّهارَ خِلْفَةً لِمَن أرادَ أنْ يَذَّكَّرَ أوْ أرادَ شُكُورًا﴾ [الفرقان: ٦٢] ورابِعُها: وهو أنَّ قَوْلَهُ تَعالى في سُورَةِ الأنْعامِ: ﴿قُلْ لِمَن ما في السَّماواتِ والأرْضِ قُلْ لِلَّهِ﴾ [الأنعام: ١٢] إشارَةٌ إلى المَكانِ والمَكانِيّاتِ، ثُمَّ قالَ: ﴿ولَهُ ما سَكَنَ في اللَّيْلِ والنَّهارِ﴾ [الأنعام: ١٣] وهو إشارَةٌ إلى الزَّمانِ والزَّمانِيّاتِ، وقَدْ بَيَّنّا هُناكَ أنَّ الزَّمانَ أعْلى وأشْرَفُ مِنَ المَكانِ، فَلَمّا كانَ كَذَلِكَ كانَ القَسَمُ بِالعَصْرِ قَسَمًا بِأشْرَفِ النِّصْفَيْنِ مِن مُلْكِ اللَّهِ ومَلَكُوتِهِ. وخامِسُها: أنَّهم كانُوا يُضِيفُونَ الخُسْرانَ إلى نَوائِبِ الدَّهْرِ، فَكَأنَّهُ تَعالى أقْسَمَ عَلى أنَّ الدَّهْرَ والعَصْرَ نِعْمَةٌ حاصِلَةٌ لا عَيْبَ فِيها، إنَّما الخاسِرُ المَعِيبُ هو الإنْسانُ. وسادِسُها: أنَّهُ تَعالى ذَكَرَ العَصْرَ الَّذِي بِمُضِيِّهِ يَنْتَقِصُ عُمُرُكُ، فَإذا لَمْ يَكُنْ في مُقابَلَتِهِ كَسْبٌ صارَ ذَلِكَ النُّقْصانُ عَيْنَ الخُسْرانِ، ولِذَلِكَ قالَ: ﴿لَفِي خُسْرٍ﴾ ومِنهُ قَوْلُ القائِلِ: إنّا لَنَفْرَحُ بِالأيّامِ نَقْطَعُها وكُلُّ يَوْمٍ مَضى نَقْصٌ مِنَ الأجَلِ فَكَأنَّ المَعْنى: والعَصْرِ العَجِيبِ أمْرُهُ حَيْثُ يَفْرَحُ الإنْسانُ بِمُضِيِّهِ لِظَنِّهِ أنَّهُ وجَدَ الرِّبْحَ مَعَ أنَّهُ هَدْمٌ لِعُمُرِهِ وإنَّهُ لَفي خُسْرٍ. والقَوْلُ الثّانِي: وهو قَوْلُ أبِي مُسْلِمٍ: المُرادُ بِالعَصْرِ أحَدُ طَرَفَيِ النَّهارِ، والسَّبَبُ فِيهِ وُجُوهٌ: أحَدُها: أنَّهُ أقْسَمَ تَعالى بِالعَصْرِ كَما أقْسَمَ بِالضُّحى لِما فِيهِما جَمِيعًا مِن دَلائِلِ القُدْرَةِ فَإنَّ كُلَّ بَكْرَةٍ كَأنَّها القِيامَةُ يَخْرُجُونَ مِنَ القُبُورِ وتَصِيرُ الأمْواتُ أحْياءً ويُقامُ المَوازِينُ، وكُلَّ عَشِيَّةٍ تُشْبِهُ تَخْرِيبَ الدُّنْيا بِالصَّعْقِ والمَوْتِ، وكُلُّ واحِدٍ مِن هاتَيْنِ الحالَتَيْنِ شاهِدُ عَدْلٍ، ثُمَّ إذا لَمْ يَحْكُمِ الحاكِمُ عَقِيبَ الشّاهِدَيْنِ عُدَّ خاسِرًا فَكَذا الإنْسانُ الغافِلُ عَنْهُما في خُسْرٍ. وثانِيها: قالَ الحَسَنُ رَحِمَهُ اللَّهُ: إنَّما أقْسَمَ بِهَذا الوَقْتِ تَنْبِيهًا عَلى أنَّ الأسْواقَ قَدْ دَنا وقْتُ انْقِطاعِها وانْتِهاءُ التِّجارَةِ والكَسْبِ فِيها، فَإذا لَمْ تَكْتَسِبْ ودَخَلْتَ الدّارَ وطافَ العِيالُ عَلَيْكَ يَسْألُكَ كُلُّ أحَدٍ ما هو حَقُّهُ فَحِينَئِذٍ تَخْجَلُ فَتَكُونُ مِنَ الخاسِرِينَ، فَكَذا نَقُولُ: والعَصْرِ؛ أيْ: عَصْرِ الدُّنْيا قَدْ دَنَتِ القِيامَةُ و(أنْتَ) بَعْدُ لَمْ تَسْتَعِدَّ وتَعْلَمْ أنَّكَ تُسْألُ غَدًا عَنِ النَّعِيمِ الَّذِي كُنْتَ فِيهِ في دُنْياكَ، وتُسْألُ في مُعامَلَتِكَ مَعَ الخَلْقِ، وكُلُّ أحَدٍ مِنَ المَظْلُومِينَ يَدَّعِي ما عَلَيْكَ فَإذًا أنْتَ خاسِرٌ، ونَظِيرُهُ: ﴿اقْتَرَبَ لِلنّاسِ حِسابُهم وهم في غَفْلَةٍ مُعْرِضُونَ﴾ [الأنبياء: ١] . وثالِثُها: أنَّ هَذا الوَقْتَ مُعَظَّمٌ، والدَّلِيلُ عَلَيْهِ قَوْلُهُ عَلَيْهِ السَّلامُ: «مَن حَلَفَ بَعْدَ العَصْرِ كاذِبًا لا يُكَلِّمُهُ اللَّهُ ولا يَنْظُرُ إلَيْهِ يَوْمَ القِيامَةِ» فَكَما أقْسَمَ في حَقِّ الرّابِحِ بِالضُّحى فَكَذا أقْسَمَ في حَقِّ الخاسِرِ بِالعَصْرِ وذَلِكَ لِأنَّهُ أقْسَمَ بِالضُّحى في حَقِّ الرّابِحِ وبَشَّرَ الرَّسُولُ أنَّ أمْرَهُ إلى الإقْبالِ وهَهُنا في حَقِّ الخاسِرِ تَوَعَّدَهُ أنْ أمْرَهُ إلى الإدْبارِ، ثُمَّ كَأنَّهُ يَقُولُ: بَعْضُ النَّهارِ باقٍ، فَيَحُثُّهُ عَلى التَّدارُكِ في البَقِيَّةِ بِالتَّوْبَةِ، وعَنْ بَعْضِ السَّلَفِ: تَعَلَّمْتُ مَعْنى السُّورَةِ مِن بائِعِ الثَّلْجِ كانَ يَصِيحُ ويَقُولُ: ارْحَمُوا مَن يَذُوبُ رَأْسُ مالِهِ، ارْحَمُوا مَن يَذُوبُ رَأْسُ مالِهِ فَقُلْتُ: هَذا مَعْنى: ﴿إنَّ الإنْسانَ لَفي خُسْرٍ﴾ يَمُرُّ بِهِ العَصْرُ فَيَمْضِي عُمُرُهُ ولا يَكْتَسِبُ فَإذًا هو خاسِرٌ. القَوْلُ الثّالِثُ: وهو قَوْلُ مُقاتِلٍ: أرادَ صَلاةَ العَصْرِ، وذَكَرُوا فِيهِ وُجُوهًا: أحَدُها: أنَّهُ تَعالى أقْسَمَ بِصَلاةِ العَصْرِ لِفَضْلِها بِدَلِيلِ قَوْلِهِ: ﴿والصَّلاةِ الوُسْطى﴾ [البقرة: ٢٣٨] صَلاةِ العَصْرِ في مُصْحَفِ حَفْصَةَ وقِيلَ في قَوْلِهِ: ﴿تَحْبِسُونَهُما مِن بَعْدِ الصَّلاةِ فَيُقْسِمانِ بِاللَّهِ﴾ [المائدة: ١٠٦] إنَّها صَلاةُ العَصْرِ. وثانِيها: قَوْلُهُ عَلَيْهِ السَّلامُ: «مَن فاتَتْهُ صَلاةُ العَصْرِ فَكَأنَّما وُتِرَ أهْلَهُ ومالَهُ» . وثالِثُها: أنَّ التَّكْلِيفَ في أدائِها أشَقُّ لِتَهافُتِ النّاسِ في تِجاراتِهِمْ ومَكاسِبِهِمْ آخِرَ النَّهارِ واشْتِغالِهِمْ بِمَعايِشِهِمْ. ورابِعُها: رُوِيَ «أنَّ امْرَأةً كانَتْ تَصِيحُ في سِكَكِ المَدِينَةِ وتَقُولُ: دُلُّونِي عَلى النَّبِيِّ ﷺ فَرَآها رَسُولُ اللَّهِ ﷺ فَسَألَها ماذا حَدَثَ ؟ قالَتْ: يا رَسُولَ اللَّهِ، إنَّ زَوْجِي غابَ عَنِّي فَزَنَيْتُ فَجاءَنِي ولَدٌ مِنَ الزِّنا فَألْقَيْتُ الوَلَدَ في دَنٍّ مِنَ الخَلِّ حَتّى ماتَ، ثُمَّ بِعْنا ذَلِكَ الخَلَّ فَهَلْ لِي مِن تَوْبَةٍ ؟ فَقالَ عَلَيْهِ السَّلامُ: أمّا الزِّنا فَعَلَيْكِ الرَّجْمُ، أمّا قَتْلُ الوَلَدِ فَجَزاؤُهُ جَهَنَّمُ، وأمّا بَيْعُ الخَلِّ فَقَدِ ارْتَكَبْتِ كَبِيرًا، لَكِنْ ظَنَنْتُ أنَّكِ تَرَكْتِ صَلاةَ العَصْرِ» فَفي هَذا الحَدِيثِ إشارَةٌ إلى تَفْخِيمِ أمْرِ هَذِهِ الصَّلاةِ. وخامِسُها: أنَّ صَلاةَ العَصْرِ بِها يَحْصُلُ خَتْمُ طاعاتِ النَّهارِ، فَهي كالتَّوْبَةِ، بِها يُخْتَمُ الأعْمالُ، فَكَما تَجِبُ الوَصِيَّةُ بِالتَّوْبَةِ كَذا بِصَلاةِ العَصْرِ لِأنَّ الأُمُورَ بِخَواتِيمِها، فَأقْسَمَ بِهَذِهِ الصَّلاةِ تَفْخِيمًا لِشَأْنِها، وزِيادَةَ تَوْصِيَةِ المُكَلَّفِ عَلى أدائِها وإشارَةً مِنهُ أنَّكَ إنْ أدَّيْتَها عَلى وجْهِها عادَ خُسْرانُكَ رِبْحًا، كَما قالَ: ﴿إلّا الَّذِينَ آمَنُوا﴾ وسادِسُها: قالَ النَّبِيُّ ﷺ: «ثَلاثَةٌ لا يَنْظُرُ اللَّهُ إلَيْهِمْ يَوْمَ القِيامَةِ ولا يُكَلِّمُهم ولا يُزَكِّيهِمْ [ عُدَّ ] مِنهم رَجُلٌ حَلَفَ بَعْدَ العَصْرِ كاذِبًا» . (فَإنْ قِيلَ) صَلاةُ العَصْرِ فِعْلُنا، فَكَيْفَ يَجُوزُ أنْ يُقالَ: أقْسَمَ اللَّهُ تَعالى بِهِ ؟ والجَوابُ: أنَّهُ لَيْسَ قِسْمًا مِن حَيْثُ إنَّها فِعْلُنا، بَلْ مِن حَيْثُ إنَّها أمْرٌ شَرِيفٌ تَعَبَّدَنا اللَّهُ تَعالى بِها. القَوْلُ الرّابِعُ: أنَّهُ قَسَمٌ بِزَمانِ الرَّسُولِ عَلَيْهِ السَّلامُ، واحْتَجُّوا عَلَيْهِ بِقَوْلِهِ عَلَيْهِ السَّلامُ: «إنَّما مَثَلُكم ومَثَلُ مَن كانَ قَبْلَكم مَثَلُ رَجُلٍ اسْتَأْجَرَ أجِيرًا، فَقالَ: مَن يَعْمَلُ مِنَ الفَجْرِ إلى الظُّهْرِ بِقِيراطٍ ؟ فَعَمِلَتِ اليَهُودُ، ثُمَّ قالَ: مَن يَعْمَلُ مِنَ الظُّهْرِ إلى العَصْرِ بِقِيراطٍ ؟ فَعَمِلَتِ النَّصارى، ثُمَّ قالَ: مَن يَعْمَلُ مِنَ العَصْرِ إلى المَغْرِبِ بِقِيراطَيْنِ ؟ فَعَمِلْتُمْ أنْتُمْ، فَغَضِبَتِ اليَهُودُ والنَّصارى، وقالُوا: نَحْنُ أكْثَرُ عَمَلًا وأقَلُّ أجْرًا ! فَقالَ اللَّهُ: وهَلْ نَقَصْتُ مِن أجْرِكم شَيْئًا ؟ قالُوا: لا، قالَ: فَهَذا فَضْلِي أُوتِيهِ مَن أشاءُ، فَكُنْتُمْ أقَلَّ عَمَلًا وأكْثَرَ أجْرًا» فَهَذا الخَبَرُ دَلَّ عَلى أنَّ العَصْرَ هو الزَّمانُ المُخْتَصُّ بِهِ وبِأُمَّتِهِ، فَلا جَرَمَ أقْسَمَ اللَّهُ بِهِ، فَقَوْلُهُ: ﴿والعَصْرِ﴾ أيْ والعَصْرِ الَّذِي أنْتَ فِيهِ فَهو تَعالى أقْسَمَ بِزَمانِهِ في هَذِهِ الآيَةِ وبِمَكانِهِ في قَوْلِهِ: ﴿وأنْتَ حِلٌّ بِهَذا البَلَدِ﴾ [البلد: ٢] وبِعُمُرِهِ في قَوْلِهِ: ﴿لَعَمْرُكَ﴾ [الحجر: ٧٢] فَكَأنَّهُ قالَ: وعَصْرِكَ وبَلَدِكَ وعُمُرِكَ، وذَلِكَ كُلُّهُ كالظَّرْفِ لَهُ، فَإذا وجَبَ تَعْظِيمُ حالِ الظَّرْفِ فَقِسْ حالَ المَظْرُوفِ، ثُمَّ وجَّهَ القَسَمَ، كَأنَّهُ تَعالى يَقُولُ: أنْتَ يا مُحَمَّدُ حَضَرْتَهم ودَعَوْتَهم، وهم أعْرَضُوا عَنْكَ وما التَفَتُوا إلَيْكَ، فَما أعْظَمَ خُسْرانَهم وما أجَلَّ خِذْلانَهم.',     source_page = '80',     updated_at  = datetime('now') WHERE id = 'QR:TE:ce75a7ca81de9c865cf7e7b9';
UPDATE qr_tafsir_entries SET content_ar = 'قَوْلُهُ تَعالى: ﴿إنَّ الإنْسانَ لَفي خُسْرٍ﴾ وفِيهِ مَسائِلُ: المَسْألَةُ الأُولى: الألِفُ واللّامُ في الإنْسانِ، يُحْتَمَلُ أنْ تَكُونَ لِلْجِنْسِ، وأنْ تَكُونَ لِلْمَعْهُودِ السّابِقِ، فَلِهَذا ذَكَرَ المُفَسِّرُونَ فِيهِ قَوْلَيْنِ: الأوَّلُ: أنَّ المُرادَ مِنهُ الجِنْسُ وهو كَقَوْلِهِمْ: كَثُرَ الدِّرْهَمُ في أيْدِي النّاسِ، ويَدُلُّ عَلى هَذا القَوْلِ اسْتِثْناءُ الَّذِينَ آمَنُوا مِنَ الإنْسانِ. والقَوْلُ الثّانِي: المُرادُ مِنهُ شَخْصٌ مُعَيَّنٌ، قالَ ابْنُ عَبّاسٍ: يُرِيدُ جَماعَةً مِنَ المُشْرِكِينَ كالوَلِيدِ بْنِ المُغِيرَةِ، والعاصِ بْنِ وائِلٍ، والأسْوَدِ بْنِ عَبْدِ المُطَّلِبِ. وقالَ مُقاتِلٌ: نَزَلَتْ في أبِي لَهَبٍ، وفي خَبَرٍ مَرْفُوعٍ إنَّهُ أبُو جَهْلٍ، ورُوِيَ أنَّ هَؤُلاءِ كانُوا يَقُولُونَ: إنَّ مُحَمَّدًا لَفي خُسْرٍ، فَأقْسَمَ تَعالى أنَّ الأمْرَ بِالضِّدِّ مِمّا يَتَوَهَّمُونَ. المَسْألَةُ الثّانِيَةُ: الخُسْرُ الخُسْرانُ، كَما قِيلَ: الكُفْرُ في الكُفْرانِ، ومَعْناهُ النُّقْصانُ وذَهابُ رَأْسِ المالِ، ثُمَّ فِيهِ تَفْسِيرانِ، وذَلِكَ لِأنّا إذا حَمَلْنا الإنْسانَ عَلى الجِنْسِ كانَ مَعْنى الخُسْرِ هَلاكَ نَفْسِهِ وعُمُرِهِ، إلّا المُؤْمِنَ العامِلَ فَإنَّهُ ما هَلَكَ عُمُرُهُ ومالُهُ: لِأنَّهُ اكْتَسَبَ بِهِما سَعادَةً أبَدِيَّةً، وإنْ حَمَلْنا لَفْظَ الإنْسانِ عَلى الكافِرِ كانَ المُرادُ كَوْنَهُ في الضَّلالَةِ والكُفْرِ إلّا مَن آمَنَ مِن هَؤُلاءِ، فَحِينَئِذٍ يَتَخَلَّصُ مِن ذَلِكَ الخَسارِ إلى الرِّبْحِ. المَسْألَةُ الثّالِثَةُ: إنَّما قالَ: ﴿لَفِي خُسْرٍ﴾ ولَمْ يَقُلْ: لَفي الخُسْرِ، لِأنَّ التَّنْكِيرَ يُفِيدُ التَّهْوِيلَ تارَةً والتَّحْقِيرَ أُخْرى، فَإنْ حَمَلْنا عَلى الأوَّلِ كانَ المَعْنى إنَّ الإنْسانَ لَفي خُسْرٍ عَظِيمٍ لا يَعْلَمُ كُنْهَهُ إلّا اللَّهُ، وتَقْرِيرُهُ أنَّ الذَّنْبَ يَعْظُمُ بِعِظَمِ مَن في حَقِّهِ الذَّنْبُ، أوْ لِأنَّهُ وقَعَ في مُقابَلَةِ النِّعَمِ العَظِيمَةِ، وكِلا الوَجْهَيْنِ حاصِلانِ في ذَنْبِ العَبْدِ في حَقِّ رَبِّهِ، فَلا جَرَمَ كانَ ذَلِكَ الذَّنْبُ في غايَةِ العِظَمِ، وإنْ حَمَلْناهُ عَلى الثّانِي كانَ المَعْنى أنَّ خُسْرانَ الإنْسانِ دُونَ خُسْرانِ الشَّيْطانِ، وفِيهِ بِشارَةٌ أنَّ في خَلْقِي مَن هو أعْصى مِنكَ، والتَّأْوِيلُ الصَّحِيحُ هو الأوَّلُ. المَسْألَةُ الرّابِعَةُ: لِقائِلٍ أنْ يَقُولَ: قَوْلُهُ: ﴿لَفِي خُسْرٍ﴾ يُفِيدُ التَّوْحِيدَ، مَعَ أنَّهُ في أنْواعٍ مِنَ الخُسْرِ. والجَوابُ: أنَّ الخُسْرَ الحَقِيقِيَّ هو حِرْمانُهُ عَنْ خِدْمَةِ رَبِّهِ، وأمّا البَواقِي وهو الحِرْمانُ عَنِ الجَنَّةِ، والوُقُوعُ في النّارِ، فَبِالنِّسْبَةِ إلى الأوَّلِ كالعَدَمِ، وهَذا كَما أنَّ الإنْسانَ في وُجُودِهِ فَوائِدُ، ثُمَّ قالَ: ﴿وما خَلَقْتُ الجِنَّ والإنْسَ إلّا لِيَعْبُدُونِ﴾ [الذاريات: ٥٦] أيْ لَمّا كانَ هَذا المَقْصُودُ أجَلَّ المَقاصِدِ كانَ سائِرُ المَقاصِدِ بِالنِّسْبَةِ إلَيْهِ كالعَدَمِ. واعْلَمْ أنَّ اللَّهَ تَعالى قَرَنَ بِهَذِهِ الآيَةِ قَرائِنَ تَدُلُّ عَلى مُبالَغَتِهِ تَعالى في بَيانِ كَوْنِ الإنْسانِ في خُسْرٍ: أحَدُها: قَوْلُهُ: ﴿لَفِي خُسْرٍ﴾ يُفِيدُ أنَّهُ كالمَغْمُورِ في الخُسْرانِ، وأنَّهُ أحاطَ بِهِ مِن كُلِّ جانِبٍ. وثانِيها: كَلِمَةُ ”إنَّ“ فَإنَّها لِلتَّأْكِيدِ. وثالِثُها: حَرْفُ اللّامِ في لَفي خُسْرٍ. وهَهُنا احْتِمالانِ: الأوَّلُ: في قَوْلِهِ تَعالى: ﴿لَفِي خُسْرٍ﴾ أيْ في طَرِيقِ الخُسْرِ، وهَذا كَقَوْلِهِ في أكْلِ أمْوالِ اليَتامى: ﴿إنَّما يَأْكُلُونَ في بُطُونِهِمْ نارًا﴾ [النساء: ١٠] لَمّا كانَتْ عاقِبَتُهُ النّارَ. الِاحْتِمالُ الثّانِي: أنَّ الإنْسانَ لا يَنْفَكُّ عَنْ خُسْرٍ، لِأنَّ الخُسْرَ هو تَضْيِيعُ رَأْسِ المالِ، ورَأْسُ مالِهِ هو عُمُرُهُ، وهو قَلَّما يَنْفَكُّ عَنْ تَضْيِيعِ عُمُرِهِ، وذَلِكَ لِأنَّ كُلَّ ساعَةٍ تَمُرُّ بِالإنْسانِ: فَإنْ كانَتْ مَصْرُوفَةً إلى المَعْصِيَةِ فَلا شَكَّ في الخُسْرانِ، وإنْ كانَتْ مَشْغُولَةً بِالمُباحاتِ فالخُسْرانُ أيْضًا حاصِلٌ، لِأنَّهُ كَما ذَهَبَ لَمْ يَبْقَ مِنهُ أثَرٌ، مَعَ أنَّهُ كانَ مُتَمَكِّنًا مِن أنْ يَعْمَلَ فِيهِ عَمَلًا يَبْقى أثَرُهُ دائِمًا، وإنْ كانَتْ مَشْغُولَةً بِالطّاعاتِ فَلا طاعَةَ إلّا ويُمْكِنُ الإتْيانُ بِها، أوْ بِغَيْرِها عَلى وجْهٍ أحْسَنَ مِن ذَلِكَ، لِأنَّ مَراتِبَ الخُضُوعِ والخُشُوعِ لِلَّهِ غَيْرُ مُتَناهِيَةٍ، فَإنَّ مَراتِبَ جَلالِ اللَّهِ وقَهْرِهِ غَيْرُ مُتَناهِيَةٍ، وكُلَّما كانَ عِلْمُ الإنْسانِ بِها أكْثَرَ كانَ خَوْفُهُ مِنهُ تَعالى أكْثَرَ، فَكانَ تَعْظِيمُهُ عِنْدَ الإتْيانِ بِالطّاعاتِ أتَمَّ وأكْمَلَ، وتَرْكُ الأعْلى والِاقْتِصارُ بِالأدْنى نَوْعُ خُسْرانٍ، فَثَبَتَ أنَّ الإنْسانَ لا يَنْفَكُّ البَتَّةَ عَنْ نَوْعِ خُسْرانٍ. واعْلَمْ أنَّ هَذِهِ الآيَةَ كالتَّنْبِيهِ عَلى أنَّ الأصْلَ في الإنْسانِ أنْ يَكُونَ في الخُسْرانِ والخَيْبَةِ، وتَقْرِيرُهُ أنَّ سَعادَةَ الإنْسانِ في حُبِّ الآخِرَةِ والإعْراضِ عَنِ الدُّنْيا، ثُمَّ إنَّ الأسْبابَ الدّاعِيَةَ إلى الآخِرَةِ خَفِيَّةٌ، والأسْبابَ الدّاعِيَةَ إلى حُبِّ الدُّنْيا ظاهِرَةٌ، وهي الحَواسُّ الخَمْسُ والشَّهْوَةُ والغَضَبُ، فَلِهَذا السَّبَبِ صارَ أكْثَرُ الخَلْقِ مُشْتَغِلِينَ بِحُبِّ الدُّنْيا مُسْتَغْرِقِينَ في طَلَبِها، فَكانُوا في الخُسْرانِ والبَوارِ، فَإنْ قِيلَ: إنَّهُ تَعالى قالَ في سُورَةِ التِّينِ: ﴿لَقَدْ خَلَقْنا الإنْسانَ في أحْسَنِ تَقْوِيمٍ﴾ ﴿ثُمَّ رَدَدْناهُ أسْفَلَ سافِلِينَ﴾ [التين: ٤، ٥] فَهُناكَ يَدُلُّ عَلى أنَّ الِابْتِداءَ مِنَ الكَمالِ، والِانْتِهاءَ إلى النُّقْصانِ، وهَهُنا يَدُلُّ عَلى أنَّ الِابْتِداءَ مِنَ النُّقْصانِ والِانْتِهاءَ إلى الكَمالِ، فَكَيْفَ وجْهُ الجَمْعِ ؟ قُلْنا: المَذْكُورُ في سُورَةِ التِّينِ أحْوالُ البَدَنِ، وهَهُنا أحْوالُ النَّفْسِ فَلا تَناقُضَ بَيْنَ القَوْلَيْنِ.',     source_page = '83',     updated_at  = datetime('now') WHERE id = 'QR:TE:2273ba4c92d1e19d7abb1d3a';
UPDATE qr_tafsir_entries SET content_ar = 'قَوْلُهُ تَعالى: ﴿إلّا الَّذِينَ آمَنُوا وعَمِلُوا الصّالِحاتِ﴾ . اعْلَمْ أنَّ الإيمانَ والأعْمالَ الصّالِحَةَ قَدْ تَقَدَّمَ تَفْسِيرُهُما مِرارًا، ثُمَّ هَهُنا مَسائِلُ: المَسْألَةُ الأُولى: احْتَجَّ مَن قالَ: العَمَلُ غَيْرُ داخِلٍ في مُسَمّى الإيمانِ، بِأنَّ اللَّهَ تَعالى عَطَفَ عَمَلَ الصّالِحاتِ عَلى الإيمانِ، ولَوْ كانَ عَمَلُ الصّالِحاتِ داخِلًا في مُسَمّى الإيمانِ لَكانَ ذَلِكَ تَكْرِيرًا ولا يُمْكِنُ أنْ يُقالَ: هَذا التَّكْرِيرُ واقِعٌ في القُرْآنِ، كَقَوْلِهِ تَعالى: ﴿وإذْ أخَذْنا مِنَ النَّبِيِّينَ مِيثاقَهم ومِنكَ ومِن نُوحٍ﴾ [الأحزاب: ٧] وقَوْلِهِ: ﴿ومَلائِكَتِهِ ورُسُلِهِ وجِبْرِيلَ ومِيكالَ﴾ [البقرة: ٩٨] لِأنّا نَقُولُ هُناكَ: إنَّما حَسُنَ، لِأنَّ إعادَتَهُ تَدُلُّ عَلى كَوْنِهِ أشْرَفَ أنْواعِ ذَلِكَ الكُلِّيِّ، وعَمَلُ الصّالِحاتِ لَيْسَ أشْرَفَ أنْواعِ الأُمُورِ المُسَمّاةِ بِالإيمانِ، فَبَطَلَ هَذا التَّأْوِيلُ. قالَ الحَلِيمِيُّ: هَذا التَّكْرِيرُ واقِعٌ لا مَحالَةَ، لِأنَّ الإيمانَ وإنْ لَمْ يَشْتَمِلْ عَلى عَمَلِ الصّالِحاتِ، لَكِنَّ قَوْلَهُ: ﴿وعَمِلُوا الصّالِحاتِ﴾ يَشْتَمِلُ عَلى الإيمانِ، فَيَكُونُ قَوْلُهُ: ﴿وعَمِلُوا الصّالِحاتِ﴾ مُغْنِيًا عَنْ ذِكْرِ قَوْلِهِ: (الَّذِينَ آمَنُوا) وأيْضًا فَقَوْلُهُ: ﴿وعَمِلُوا الصّالِحاتِ﴾ يَشْتَمِلُ عَلى قَوْلِهِ: ﴿وتَواصَوْا بِالحَقِّ وتَواصَوْا بِالصَّبْرِ﴾ فَوَجَبَ أنْ يَكُونَ ذَلِكَ تَكْرارًا، أجابَ الأوَّلُونَ وقالُوا: إنّا لا نَمْنَعُ وُرُودَ التَّكْرِيرِ لِأجْلِ التَّأْكِيدِ، لَكِنَّ الأصْلَ عَدَمُهُ، وهَذا القَدْرُ يَكْفِي في الِاسْتِدْلالِ. المَسْألَةُ الثّانِيَةُ: احْتَجَّ القاطِعُونَ بِوَعِيدِ الفُسّاقِ بِهَذِهِ الآيَةِ، قالُوا: الآيَةُ دَلَّتْ عَلى أنَّ الإنْسانَ في الخَسارَةِ مُطْلَقًا، ثُمَّ اسْتَثْنى: ﴿الَّذِينَ آمَنُوا وعَمِلُوا الصّالِحاتِ﴾ والمُعَلَّقُ عَلى الشَّرْطَيْنِ مَفْقُودٌ عِنْدَ فَقْدِ أحَدِهِما، فَعَلِمْنا أنَّ مَن لَمْ يَحْصُلْ لَهُ الإيمانُ والأعْمالُ الصّالِحَةُ لا بُدَّ وأنْ يَكُونَ في الخَسارِ في الدُّنْيا وفي الآخِرَةِ، ولَمّا كانَ المُسْتَجْمِعُ لِهاتَيْنِ الخَصْلَتَيْنِ في غايَةِ القِلَّةِ، وكانَ الخَسارُ لازِمًا لِمَن لَمْ يَكُنْ مُسْتَجْمِعًا لَهُما كانَ النّاجِي أقَلَّ مِنَ الهالِكِ، ثُمَّ لَوْ كانَ النّاجِي أكْثَرَ كانَ الخَوْفُ عَظِيمًا حَتّى لا تَكُونَ أنْتَ مِنَ القَلِيلِ، كَيْفَ والنّاجِي أقَلُّ ؟ أفَلا يَنْبَغِي أنْ يَكُونَ الخَوْفُ أشَدَّ ! المَسْألَةُ الثّالِثَةُ: أنَّ هَذا الِاسْتِثْناءَ فِيهِ أُمُورٌ ثَلاثَةٌ: أحَدُها: أنَّهُ تَسْلِيَةٌ لِلْمُؤْمِنِ مَن فَوْتِ عُمُرِهِ وشَبابِهِ، لِأنَّ العَمَلَ قَدْ أوْصَلَهُ إلى خَيْرٍ مِن عُمُرِهِ وشَبابِهِ. وثانِيها: أنَّهُ تَنْبِيهٌ عَلى أنَّ كُلَّ ما دَعاكَ إلى طاعَةِ اللَّهِ فَهو الصَّلاحُ، وكُلَّ ما شَغَلَكَ عَنِ اللَّهِ بِغَيْرِهِ فَهو الفَسادُ. وثالِثُها: قالَتِ المُعْتَزِلَةُ: تَسْمِيَةُ الأعْمالِ بِالصّالِحاتِ تَنْبِيهٌ عَلى أنَّ وجْهَ حُسْنِها لَيْسَ هو الأمْرَ عَلى ما يَقُولُهُ الأشْعَرِيَّةُ، لَكِنَّ الأمْرَ إنَّما ورَدَ لِكَوْنِها في أنْفُسِها مُشْتَمِلَةً عَلى وُجُوهِ الصَّلاحِ، وأجابَتِ الأشْعَرِيَّةُ بِأنَّ اللَّهَ تَعالى وصَفَها بِكَوْنِها صالِحَةً، ولَمْ يُبَيِّنْ أنَّها صالِحَةٌ بِسَبَبِ وُجُوهٍ عائِدَةٍ إلَيْها أوْ بِسَبَبِ الأمْرِ. المَسْألَةُ الرّابِعَةُ: لِسائِلٍ أنْ يَسْألَ فَيَقُولَ: إنَّهُ في جانِبِ الخُسْرِ ذَكَرَ الحُكْمَ ولَمْ يَذْكُرِ السَّبَبَ وفي جانِبِ الرِّبْحِ ذَكَرَ السَّبَبَ، وهو الإيمانُ والعَمَلُ الصّالِحُ، ولَمْ يَذْكُرِ الحُكْمَ فَما الفَرْقُ ؟ قُلْنا: إنَّهُ لَمْ يَذْكُرْ سَبَبَ الخُسْرِ لِأنَّ الخُسْرَ كَما يَحْصُلُ بِالفِعْلِ، وهو الإقْدامُ عَلى المَعْصِيَةِ يَحْصُلُ بِالتَّرْكِ، وهو عَدَمُ الإقْدامِ عَلى الطّاعَةِ، أمّا الرِّبْحُ فَلا يَحْصُلُ إلّا بِالفِعْلِ، فَلِهَذا ذَكَرَ سَبَبَ الرِّبْحِ وهو العَمَلُ، وفِيهِ وجْهٌ آخَرُ، وهو أنَّهُ تَعالى في جانِبِ الخُسْرِ أبْهَمَ ولَمْ يُفَصِّلْ، وفي جانِبِ الرِّبْحِ فَصَّلَ وبَيَّنَ، وهَذا هو اللّائِقُ بِالكَرَمِ. * أمّا قَوْلُهُ تَعالى: ﴿وتَواصَوْا بِالحَقِّ وتَواصَوْا بِالصَّبْرِ﴾ . فاعْلَمْ أنَّهُ تَعالى لَمّا بَيَّنَ في أهْلِ الِاسْتِثْناءِ أنَّهم بِإيمانِهِمْ وعَمَلِهِمُ الصّالِحِ خَرَجُوا عَنْ أنْ يَكُونُوا في خُسْرٍ وصارُوا أرْبابَ السَّعادَةِ مِن حَيْثُ إنَّهم تَمَسَّكُوا بِما يُؤَدِّيهِمْ إلى الفَوْزِ بِالثَّوابِ والنَّجاةِ مِنَ العِقابِ وصَفَهم بَعْدَ ذَلِكَ بِأنَّهم قَدْ صارُوا لِشِدَّةِ مَحَبَّتِهِمْ لِلطّاعَةِ لا يَقْتَصِرُونَ عَلى ما يَخُصُّهم بَلْ يُوصُونَ غَيْرَهم بِمِثْلِ طَرِيقَتِهِمْ لِيَكُونُوا أيْضًا سَبَبًا لِطاعاتِ الغَيْرِ كَما يَنْبَغِي أنْ يَكُونَ عَلَيْهِ أهْلُ الدِّينِ وعَلى هَذا الوَجْهِ قالَ تَعالى: ﴿ياأيُّها الَّذِينَ آمَنُوا قُوا أنْفُسَكم وأهْلِيكم نارًا﴾ [التحريم: ٦] فالتَّواصِي بِالحَقِّ يَدْخُلُ فِيهِ سائِرُ الدِّينِ مِن عِلْمٍ وعَمَلٍ، والتَّواصِي بِالصَّبْرِ يَدْخُلُ فِيهِ حَمْلُ النَّفْسِ عَلى مَشَقَّةِ التَّكْلِيفِ في القِيامِ بِما يَجِبُ، وفي اجْتِنابِهِمْ ما يَحْرُمُ؛ إذِ الإقْدامُ عَلى المَكْرُوهِ والإحْجامُ عَنِ المُرادِ كِلاهُما شاقٌّ شَدِيدٌ، وهَهُنا مَسائِلُ: المَسْألَةُ الأُولى: هَذِهِ الآيَةُ فِيها وعِيدٌ شَدِيدٌ، وذَلِكَ لِأنَّهُ تَعالى حَكَمَ بِالخَسارِ عَلى جَمِيعِ النّاسِ إلّا مَن كانَ آتِيًا بِهَذِهِ الأشْياءِ الأرْبَعَةِ، وهي الإيمانُ والعَمَلُ الصّالِحُ والتَّواصِي بِالحَقِّ والتَّواصِي بِالصَّبْرِ، فَدَلَّ ذَلِكَ عَلى أنَّ النَّجاةَ مُعَلَّقَةٌ بِمَجْمُوعِ هَذِهِ الأُمُورِ وإنَّهُ كَما يَلْزَمُ المُكَلَّفَ تَحْصِيلُ ما يَخُصُّ نَفْسَهُ فَكَذَلِكَ يَلْزَمُهُ في غَيْرِهِ أُمُورٌ، مِنها الدُّعاءُ إلى الدِّينِ، والنَّصِيحَةُ، والأمْرُ بِالمَعْرُوفِ والنَّهْيُ عَنِ المُنْكَرِ، وأنْ يُحِبَّ لَهُ ما يُحِبُّ لِنَفْسِهِ، ثُمَّ كَرَّرَ التَّواصِيَ لِيُضَمِّنَ الأوَّلَ الدُّعاءَ إلى اللَّهِ، والثّانِيَ الثَّباتَ عَلَيْهِ، والأوَّلُ الأمْرُ بِالمَعْرُوفِ والثّانِي النَّهْيُ عَنِ المُنْكَرِ، ومِنهُ قَوْلُهُ: ﴿وانْهَ عَنِ المُنْكَرِ واصْبِرْ﴾ [لقمان: ١٧] وقالَ عُمَرُ: رَحِمَ اللَّهُ مَن أهْدى إلَيَّ عُيُوبِي. المَسْألَةُ الثّانِيَةُ: دَلَّتِ الآيَةُ عَلى أنَّ الحَقَّ ثَقِيلٌ، وأنَّ المِحَنَ تُلازِمُهُ، فَلِذَلِكَ قَرَنَ بِهِ التَّواصِيَ. المَسْألَةُ الثّالِثَةُ: إنَّما قالَ: (وتَواصَوْا) ولَمْ يَقُلْ: ويَتَواصَوْنَ؛ لِئَلّا يَقَعَ أمْرًا بَلِ الغَرَضُ مَدْحُهم بِما صَدَرَ عَنْهم في الماضِي، وذَلِكَ يُفِيدُ رَغْبَتَهم في الثَّباتِ عَلَيْهِ في المُسْتَقْبَلِ. المَسْألَةُ الرّابِعَةُ: قَرَأ أبُو عَمْرٍو: ”بِالصَّبْرِ“ بِشَمِّ الباءِ شَيْئًا مِنَ الحَرْفِ لا يُشْبَعُ، قالَ أبُو عَلِيٍّ: وهَذا مِمّا يَجُوزُ في الوَقْفِ، ولا يَكُونُ في الوَصْلِ إلّا عَلى إجْراءِ الوَصْلِ مَجْرى الوَقْفِ، وهَذا لا يَكادُ يَكُونُ في القِراءَةِ، وعَلى هَذا ما يُرْوى عَنْ سَلّامِ بْنِ المُنْذِرِ أنَّهُ قَرَأ، ”والعَصِرْ“ بِكَسْرِ الصّادِ ولَعَلَّهُ وقَفَ لِانْقِطاعِ نَفَسٍ أوْ لِعارِضٍ مَنَعَهُ مِن إدْراجِ القِراءَةِ، وعَلى هَذا يُحْمَلُ لا عَلى إجْراءِ الوَصْلِ مَجْرى الوَقْفِ، واللَّهُ سُبْحانَهُ وتَعالى أعْلَمُ، وصَلّى اللَّهُ عَلى سَيِّدِنا مُحَمَّدٍ وعَلى آلِهِ وصَحْبِهِ وسَلَّمَ.',     source_page = '85',     updated_at  = datetime('now') WHERE id = 'QR:TE:cad4e2558e6a075813cd4a5d';
UPDATE qr_tafsir_entries SET content_ar = '(سُورَةُ الهُمَزَةِ) تِسْعُ آياتٍ، مَكِّيَّةٌ بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ ﴿ويْلٌ لِكُلِّ هُمَزَةٍ لُمَزَةٍ﴾ بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ ﴿ويْلٌ لِكُلِّ هُمَزَةٍ لُمَزَةٍ﴾ فِيهِ مَسائِلُ: المَسْألَةُ الأُولى: الوَيْلُ لَفْظَةُ الذَّمِّ والسُّخْطِ، وهي كَلِمَةُ كُلِّ مَكْرُوبٍ يَتَوَلَّوْنَ فَيَدْعُو بِالوَيْلِ وأصْلُهُ ويْ لِفُلانٍ ثُمَّ كَثُرَتْ في كَلامِهِمْ فَوُصِلَتْ بِاللّامِ، ورُوِيَ أنَّهُ جَبَلٌ في جَهَنَّمَ. إنْ قِيلَ: لِمَ قالَ هَهُنا: (ويْلٌ) وفي مَوْضِعٍ آخَرَ: ﴿ولَكُمُ الوَيْلُ﴾ ؟ [ الأنْبِياءِ: ١٨] قُلْنا: لِأنَّ ثَمَّةَ قالُوا: ﴿ياوَيْلَنا إنّا كُنّا ظالِمِينَ﴾ [الأنبياء: ١٤] فَقالَ: ﴿ولَكُمُ الوَيْلُ﴾ وهَهُنا نَكَّرَ لِأنَّهُ لا يَعْلَمُ كُنْهَهُ إلّا اللَّهُ، وقِيلَ: في ويْلٍ إنَّها كَلِمَةُ تَقْبِيحٍ، ووَيْسٌ اسْتِصْغارٌ ووَيْحٌ تَرَحُّمٌ، فَنَبَّهَ بِهَذا عَلى قُبْحِ هَذا الفِعْلِ، واخْتَلَفُوا في الوَعِيدِ الَّذِي في هَذِهِ السُّورَةِ هَلْ يَتَناوَلُ كُلَّ مَن يَتَمَسَّكُ بِهَذِهِ الطَّرِيقَةِ في الأفْعالِ الرَّدِيئَةِ أوْ هو مَخْصُوصٌ بِأقْوامٍ مُعَيَّنِينَ، أمّا المُحَقِّقُونَ فَقالُوا: إنَّهُ عامٌّ لِكُلِّ مَن يَفْعَلُ هَذا الفِعْلَ كائِنًا مَن كانَ وذَلِكَ لِأنَّ خُصُوصَ السَّبَبِ لا يَقْدَحُ في عُمُومِ اللَّفْظِ وقالَ آخَرُونَ: إنَّهُ مُخْتَصٌّ بِأُناسٍ مُعَيَّنِينَ، ثُمَّ قالَ عَطاءٌ والكَلْبِيُّ: نَزَلَتْ في الأخْنَسِ بْنِ شَرِيقٍ كانَ يَلْمِزُ النّاسَ ويَغْتابُهم وخاصَّةً رَسُولَ اللَّهِ ﷺ، وقالَ مُقاتِلٌ: نَزَلَتْ في الوَلِيدِ بْنِ المُغِيرَةِ كانَ يَغْتابُ النَّبِيَّ ﷺ مِن ورائِهِ ويَطْعَنُ عَلَيْهِ في وجْهِهِ، وقالَ مُحَمَّدُ بْنُ إسْحاقَ: ما زِلْنا نَسْمَعُ أنَّ هَذِهِ السُّورَةَ نَزَلَتْ في أُمَيَّةَ بْنِ خَلَفٍ، قالَ الفَرّاءُ: وكَوْنُ اللَّفْظِ عامًّا لا يُنافِي أنْ يَكُونَ المُرادُ مِنهُ شَخْصًا مُعَيَّنًا، كَما أنَّ إنْسانًا لَوْ قالَ لَكَ: لا أزُورُكَ أبَدًا. فَتَقُولُ أنْتَ: كُلُّ مَن لَمْ يَزُرْنِي لا أزُورُهُ. وأنْتَ إنَّما تُرِيدُهُ بِهَذِهِ الجُمْلَةِ العامَّةِ وهَذا هو المُسَمّى في أُصُولِ الفِقْهِ بِتَخْصِيصِ العامِّ بِقَرِينَةِ العُرْفِ. المَسْألَةُ الثّانِيَةُ: الهَمْزُ الكَسْرُ قالَ تَعالى: ﴿هَمّازٍ مَشّاءٍ﴾ [القلم: ١١] واللَّمْزُ الطَّعْنُ والمُرادُ الكَسْرُ مِن أعْراضِ النّاسِ والغَضُّ مِنهم والطَّعْنُ فِيهِمْ، قالَ تَعالى: ﴿ولا تَلْمِزُوا أنْفُسَكُمْ﴾ [الحجرات: ١١] وبِناءُ فِعْلِهِ يَدُلُّ عَلى أنَّ ذَلِكَ عادَةٌ مِنهُ قَدْ ضَرِيَ بِها ونَحْوُهُما اللُّعَنَةُ والضُّحَكَةُ، وقُرِئَ: ”ويْلٌ لِكُلِّ هُمْزَةٍ لُمْزَةٍ“ بِسُكُونِ المِيمِ وهي المَسْخَرَةُ الَّتِي تَأْتِي بِالأوابِدِ والأضاحِيكِ فَيُضْحَكُ مِنهُ ويُشْتَمُ، ولِلْمُفَسِّرِينَ ألْفاظًا: أحَدُها: قالَ ابْنُ عَبّاسٍ: الهُمَزَةُ المُغْتابُ، واللُّمَزَةُ العَيّابُ. وثانِيها: قالَ أبُو زَيْدٍ: الهُمَزَةُ بِاليَدِ واللُّمَزَةُ بِاللِّسانِ. وثالِثُها: قالَ أبُو العالِيَةِ: الهُمَزَةُ بِالمُواجَهَةِ واللُّمَزَةُ بِظَهْرِ الغَيْبِ. ورابِعُها: الهُمَزَةُ جَهْرًا واللُّمَزَةُ سِرًّا بِالحاجِبِ والعَيْنِ. وخامِسُها: الهُمَزَةُ واللُّمَزَةُ الَّذِي يُلَقِّبُ النّاسَ بِما يَكْرَهُونَ وكانَ الوَلِيدُ بْنُ المُغِيرَةِ يَفْعَلُ ذَلِكَ، لَكِنَّهُ لا يَلِيقُ بِمَنصِبِ الرِّياسَةِ إنَّما ذَلِكَ مِن عادَةِ السُّقّاطِ ويَدْخُلُ فِيهِ مَن يُحاكِي النّاسَ بِأقْوالِهِمْ وأفْعالِهِمْ وأصْواتِهِمْ لِيَضْحَكُوا. وقَدْ حَكى الحَكَمُ بْنُ العاصِ مِشْيَةَ النَّبِيِّ ﷺ فَنَفاهُ عَنِ المَدِينَةِ ولَعَنَهُ. وسادِسُها: قالَ الحَسَنُ: الهُمَزَةُ الَّذِي يَهْمِزُ جَلِيسَهُ يَكْسِرُ عَلَيْهِ عَيْنَهُ واللُّمَزَةُ الَّذِي يَذْكُرُ أخاهُ بِالسُّوءِ ويَعِيبُهُ. وسابِعُها: عَنْ أبِي الجَوْزاءِ قالَ: قُلْتُ لِابْنِ عَبّاسٍ: ﴿ويْلٌ لِكُلِّ هُمَزَةٍ لُمَزَةٍ﴾ مَن هَؤُلاءِ الَّذِينَ يَذُمُّهُمُ اللَّهُ بِالوَيْلِ فَقالَ: هُمُ المَشّاءُونَ بِالنَّمِيمَةِ المُفَرِّقُونَ بَيْنَ الأحِبَّةِ النّاعِتُونَ لِلنّاسِ بِالعَيْبِ. واعْلَمْ أنَّ جَمِيعَ هَذِهِ الوُجُوهِ مُتَقارِبَةٌ راجِعَةٌ إلى أصْلٍ واحِدٍ وهو الطَّعْنُ وإظْهارُ العَيْبِ، ثُمَّ هَذا عَلى قِسْمَيْنِ: فَإنَّهُ إمّا أنْ يَكُونَ بِالجِدِّ كَما يَكُونُ عِنْدَ الحَسَدِ والحِقْدِ، وإمّا أنْ يَكُونَ بِالهَزْلِ كَما يَكُونُ عِنْدَ السُّخْرِيَةِ والإضْحاكِ، وكُلُّ واحِدٍ مِنَ القِسْمَيْنِ، إمّا أنْ يَكُونَ في أمْرٍ يَتَعَلَّقُ بِالدِّينِ، وهو ما يَتَعَلَّقُ بِالصُّورَةِ أوِ المَشْيِ أوِ الجُلُوسِ، وأنْواعُهُ كَثِيرَةٌ وهي غَيْرُ مَضْبُوطَةٍ، ثُمَّ إظْهارُ العَيْبِ في هَذِهِ الأقْسامِ الأرْبَعَةِ قَدْ يَكُونُ لِحاضِرٍ، وقَدْ يَكُونُ لِغائِبٍ، وعَلى التَّقْدِيرَيْنِ فَقَدْ يَكُونُ بِاللَّفْظِ، وقَدْ يَكُونُ بِإشارَةِ الرَّأْسِ والعَيْنِ وغَيْرِهِما، وكُلُّ ذَلِكَ داخِلٌ تَحْتَ النَّهْيِ والزَّجْرِ، إنَّما البَحْثُ في أنَّ اللَّفْظَ بِحَسَبِ اللُّغَةِ مَوْضُوعٌ لِماذا، فَما كانَ اللَّفْظُ مَوْضُوعًا لَهُ كانَ مَنهِيًّا بِحَسَبِ اللَّفْظِ، وما لَمْ يَكُنِ اللَّفْظُ مَوْضُوعًا لَهُ كانَ داخِلًا تَحْتَ النَّهْيِ بِحَسَبِ القِياسِ الجَلِيِّ، ولَمّا كانَ الرَّسُولُ أعْظَمَ النّاسِ مَنصِبًا في الدِّينِ كانَ الطَّعْنُ فِيهِ عَظِيمًا عِنْدَ اللَّهِ، فَلا جَرَمَ قالَ: ﴿ويْلٌ لِكُلِّ هُمَزَةٍ لُمَزَةٍ﴾ .',     source_page = '86',     updated_at  = datetime('now') WHERE id = 'QR:TE:95750a138d5fe7c5fe478360';
UPDATE qr_tafsir_entries SET content_ar = 'ثُمَّ قالَ تَعالى: ﴿الَّذِي جَمَعَ مالًا وعَدَّدَهُ﴾ وفِيهِ مَسْألَتانِ: المَسْألَةُ الأُولى: (الَّذِي) بَدَلٌ مِن كُلٍّ أوْ نَصْبٌ عَلى ذَمٍّ، وإنَّما وصَفَهُ اللَّهُ تَعالى بِهَذا الوَصْفِ لِأنَّهُ يَجْرِي مَجْرى السَّبَبِ والعِلَّةِ في الهَمْزِ واللَّمْزِ وهو إعْجابُهُ بِما جَمَعَ مِنَ المالِ، وظَنُّهُ أنَّ الفَضْلَ فِيهِ لِأجْلِ ذَلِكَ فَيَسْتَنْقِصُ غَيْرَهُ. المَسْألَةُ الثّانِيَةُ: قَرَأ حَمْزَةُ والكِسائِيُّ وابْنُ عامِرٍ ”جَمَّعَ“ بِالتَّشْدِيدِ والباقُونَ بِالتَّخْفِيفِ، والمَعْنى في جَمَّعَ وجَمَعَ واحِدٌ مُتَقارِبٌ، والفَرْقُ أنَّ ”جَمَّعَ“ بِالتَّشْدِيدِ يُفِيدُ أنَّهُ جَمَعَهُ مِن هَهُنا وهَهُنا، وأنَّهُ لَمْ يَجْمَعْهُ في يَوْمٍ واحِدٍ، ولا في يَوْمَيْنِ، ولا في شَهْرٍ ولا في شَهْرَيْنِ، يُقالُ: فُلانٌ يُجَمِّعُ الأمْوالَ أيْ يَجْمَعُها مِن هَهُنا وهَهُنا، وأمّا جَمَعَ بِالتَّخْفِيفِ، فَلا يُفِيدُ ذَلِكَ، وأمّا قَوْلُهُ: (مالًا) فالتَّنْكِيرُ فِيهِ يَحْتَمِلُ وجْهَيْنِ: أحَدُهُما: أنْ يُقالَ: المالُ اسْمٌ لِكُلِّ ما في الدُّنْيا كَما قالَ: ﴿المالُ والبَنُونَ زِينَةُ الحَياةِ الدُّنْيا﴾ [الكهف: ٤٩] فَمالُ الإنْسانِ الواحِدِ بِالنِّسْبَةِ إلى مالِ كُلِّ الدُّنْيا حَقِيرٌ، فَكَيْفَ يَلِيقُ بِهِ أنْ يَفْتَخِرَ بِذَلِكَ القَلِيلِ. والثّانِي: أنْ يَكُونَ المُرادُ مِنهُ التَّعْظِيمَ؛ أيْ: مالٌ بَلَغَ في الخُبْثِ والفَسادِ أقْصى النِّهاياتِ. فَكَيْفَ يَلِيقُ بِالعاقِلِ أنْ يَفْتَخِرَ بِهِ ؟ أمّا قَوْلُهُ: (وعَدَّدَهُ) فَفِيهِ وُجُوهٌ: أحَدُها أنَّهُ مَأْخُوذٌ مِنَ العُدَّةِ وهي الذَّخِيرَةُ يُقالُ: أعْدَدْتُ الشَّيْءَ لِكَذا وعَدَدْتُهُ إذا أمْسَكْتَهُ لَهُ وجَعَلْتَهُ عُدَّةً وذَخِيرَةً لِحَوادِثِ الدَّهْرِ. وثانِيها: عَدَّدَهُ أيْ: أحْصاهُ وجاءَ التَّشْدِيدُ لِكَثْرَةِ المَعْدُودِ كَما يُقالُ: فُلانٌ يُعَدِّدُ فَضائِلَ فُلانٍ، ولِهَذا قالَ السُّدِّيُّ: وعَدَّدَهُ أيْ أحْصاهُ يَقُولُ: هَذا لِي وهَذا لِي يُلْهِيهِ مالُهُ بِالنَّهارِ فَإذا جاءَ اللَّيْلُ كانَ يُخْفِيهِ. وثالِثُها: عَدَّدَهُ أيْ كَثَّرَهُ يُقالُ: في بَنِي فُلانٍ عَدَدٌ أيْ كَثْرَةٌ، وهَذانِ القَوْلانِ الأخِيرانِ راجِعانِ إلى مَعْنى العَدَدِ، والقَوْلُ الثّالِثُ إلى مَعْنى العُدَّةِ، وقَرَأ بَعْضُهم ”وعَدَدَهُ“ بِالتَّخْفِيفِ وفِيهِ وجْهانِ: أحَدُهُما: أنْ يَكُونَ المَعْنى: جَمَعَ المالَ وضَبَطَ عَدَدَهُ وأحْصاهُ. وثانِيهِما: جَمَعَ مالَهُ وعَدَدَ قَوْمِهِ الَّذِينَ يَنْصُرُونَهُ مِن قَوْلِكَ: فُلانٌ ذُو عَدَدٍ وعُدَدٍ إذا كانَ لَهُ عَدَدٌ وافِرٌ مِنَ الأنْصارِ، والرَّجُلُ مَتى كانَ كَذَلِكَ كانَ أدْخَلَ في التَّفاخُرِ.',     source_page = '88',     updated_at  = datetime('now') WHERE id = 'QR:TE:ec218845c97cbfc1e1304e20';
UPDATE qr_tafsir_entries SET content_ar = 'ثُمَّ وصَفَهُ تَعالى بِضَرْبٍ آخَرَ مِنَ الجَهْلِ فَقالَ: ﴿يَحْسَبُ أنَّ مالَهُ أخْلَدَهُ﴾ . واعْلَمْ أنْ أخْلَدَهُ وخَلَّدَهُ بِمَعْنًى واحِدٍ، ثُمَّ في التَّفْسِيرِ وُجُوهٌ: أحَدُها: يُحْتَمَلُ أنْ يَكُونَ المَعْنى طُولَ المالِ أمَّلَهُ، حَتّى أصْبَحَ لِفَرْطِ غَفْلَتِهِ وطُولِ أمَلِهِ، يَحْسَبُ أنَّ مالَهُ تَرَكَهُ خالِدًا في الدُّنْيا لا يَمُوتُ وإنَّما قالَ: (أخْلَدَهُ) ولَمْ يَقُلْ: يُخَلِّدُهُ؛ لِأنَّ المُرادَ يَحْسَبُ هَذا الإنْسانُ أنَّ المالَ ضَمِنَ لَهُ الخُلُودَ وأعْطاهُ الأمانَ مِنَ المَوْتِ وكَأنَّهُ حُكْمٌ قَدْ فُرِغَ مِنهُ، ولِذَلِكَ ذَكَرَهُ عَلى الماضِي. قالَ الحَسَنُ: ما رَأيْتُ يَقِينًا لا شَكَّ فِيهِ أشْبَهَ بِشَكٍّ لا يَقِينَ فِيهِ كالمَوْتِ. وثانِيها: يَعْمَلُ الأعْمالَ المُحْكَمَةَ كَتَشْيِيدِ البُنْيانِ بِالآجُرِّ والجِصِّ، عَمَلَ مَن يَظُنُّ أنَّهُ يَبْقى حَيًّا أوْ لِأجْلِ أنْ يُذْكَرَ بِسَبَبِهِ بَعْدَ المَوْتِ. وثالِثُها: أحَبَّ المالَ حُبًّا شَدِيدًا حَتّى اعْتَقَدَ أنَّهُ: إنِ انْتَقَصَ مالِي أمُوتُ، فَلِذَلِكَ يَحْفَظُهُ مِنَ النُّقْصانِ لِيَبْقى حَيًّا، وهَذا غَيْرُ بَعِيدٍ مِنِ اعْتِقادِ البَخِيلِ. ورابِعُها: أنَّ هَذا تَعْرِيضٌ بِالعَمَلِ الصّالِحِ وأنَّهُ هو الَّذِي يُخَلِّدُ صاحِبَهُ في الدُّنْيا بِالذِّكْرِ الجَمِيلِ وفي الآخِرَةِ في النَّعِيمِ المُقِيمِ. أمّا قَوْلُهُ تَعالى: (كَلّا) فَفِيهِ وجْهانِ: أحَدُهُما: أنَّهُ رَدْعٌ لَهُ عَنْ حُسْبانِهِ أيْ: لَيْسَ الأمْرُ كَما يَظُنُّ أنَّ المالَ يُخَلِّدُهُ بَلِ العِلْمُ والصَّلاحُ، ومِنهُ قَوْلُ عَلِيٍّ عَلَيْهِ السَّلامُ: ماتَ خُزّانُ المالِ وهم أحْياءٌ والعُلَماءُ باقُونَ ما بَقِيَ الدَّهْرُ والقَوْلُ الثّانِي مَعْناهُ: حَقًّا (لَيُنْبَذَنَّ) واللّامُ في: (لَيُنْبَذَنَّ) جَوابُ القَسَمِ المُقَدَّرِ فَدَلَّ ذَلِكَ عَلى حُصُولِ مَعْنى القَسَمِ في ”كَلّا“ . أمّا قَوْلُهُ تَعالى: ﴿لَيُنْبَذَنَّ في الحُطَمَةِ﴾ ﴿وما أدْراكَ ما الحُطَمَةُ﴾ فَإنَّما ذَكَرَهُ بِلَفْظِ النَّبْذِ الدّالِّ عَلى الإهانَةِ، لِأنَّ الكافِرَ كانَ يَعْتَقِدُ أنَّهُ مِن أهْلِ الكَرامَةِ، وقُرِئَ ”لَيُنْبَذانِ“ أيْ هو ومالُهُ، و”لَيُنْبَذُنَّ“ بِضَمِّ الذّالِ أيْ هو وأنْصارُهُ، وأمّا: (الحُطَمَةِ) فَقالَ المُبَرِّدُ: إنَّها النّارُ الَّتِي تَحْطِمُ كُلَّ مَن وقَعَ فِيها ورَجُلٌ حُطَمَةٌ أيْ شَدِيدُ الأكْلِ يَأْتِي عَلى زادِ القَوْمِ، وأصْلُ الحَطْمِ في اللُّغَةِ الكَسْرُ، ويُقالُ: شَرُّ الرِّعاءِ الحُطَمَةُ، يُقالُ: راعٍ حُطَمَةٌ وحُطَمٌ بِغَيْرِ هاءٍ كَأنَّهُ يَحْطِمُ الماشِيَةَ أيْ يَكْسِرُها عِنْدَ سَوْقِها لِعُنْفِهِ، قالَ المُفَسِّرُونَ: الحُطَمَةُ اسْمٌ مِن أسْماءِ النّارِ وهي الدَّرَكَةُ الثّانِيَةُ مِن دَرَكاتِ النّارِ، وقالَ مُقاتِلٌ: هي تَحْطِمُ العِظامَ وتَأْكُلُ اللُّحُومَ حَتّى تَهْجُمَ عَلى القُلُوبِ، ورُوِيَ عَنِ النَّبِيِّ ﷺ أنَّهُ قالَ: «إنِ المَلَكَ لَيَأْخُذُ الكافِرَ فَيَكْسِرُهُ عَلى صُلْبِهِ كَما تُوضَعُ الخَشَبَةُ عَلى الرُّكْبَةِ فَتُكْسَرُ، ثُمَّ يُرْمى بِهِ في النّارِ» .',     source_page = '89',     updated_at  = datetime('now') WHERE id = 'QR:TE:920edcc78b1281980e9a1017';
UPDATE qr_tafsir_entries SET content_ar = '(سُورَةُ الفِيلِ) خَمْسُ آياتٍ، مَكِّيَّةٌ ﷽ ﴿ألَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأصْحابِ الفِيلِ﴾ ﷽ ﴿ألَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأصْحابِ الفِيلِ﴾ رُوِيَ أنَّ أبْرَهَةَ بْنَ الصَّبّاحِ الأشْرَمِ مَلِكَ اليَمَنِ مِن قِبَلِ أصْحَمَةَ النَّجاشِيِّ بَنى كَنِيسَةً بِصَنْعاءَ وسَمّاها القُلَّيْسَ وأرادَ أنْ يَصْرِفَ إلَيْها الحاجَّ فَخَرَجَ مِن بَنِي كِنانَةَ رَجُلٌ وتَغَوَّطَ فِيها لَيْلًا فَأغْضَبَهُ ذَلِكَ. وقِيلَ: أجَّجَتْ رُفْقَةٌ مِنَ العَرَبِ نارًا فَحَمَلَتْها الرِّيحُ فَأحْرَقَتْها فَحَلَفَ لَيَهْدِمَنَّ الكَعْبَةَ فَخَرَجَ بِالحَبَشَةِ ومَعَهُ فِيلٌ اسْمُهُ مَحْمُودٌ وكانَ قَوِيًّا عَظِيمًا، وثَمانِيَةٌ أُخْرى، وقِيلَ: اثْنا عَشَرَ، وقِيلَ: ألْفٌ، فَلَمّا بَلَغَ قَرِيبًا مِن مَكَّةَ خَرَجَ إلَيْهِ عَبْدُ المُطَّلِبِ وعَرَضَ عَلَيْهِ ثُلُثَ أمْوالِ تِهامَةَ لِيَرْجِعَ فَأبى وعَبَّأ جَيْشَهُ، وقَدَّمَ الفِيلَ فَكانُوا كُلَّما وجَّهُوهُ إلى جِهَةِ الحَرَمِ بَرَكَ ولَمْ يَبْرَحْ، وإذا وجَّهُوهُ إلى جِهَةِ اليَمَنِ أوْ إلى سائِرِ الجِهاتِ هَرْوَلَ، ثُمَّ إنَّ أبْرَهَةَ أخَذَ لِعَبْدِ المُطَّلِبِ مِائَتَيْ بَعِيرٍ فَخَرَجَ إلَيْهِمْ فِيها فَعَظُمَ في عَيْنِ أبْرَهَةَ وكانَ رَجُلًا جَسِيمًا وسِيمًا، وقِيلَ: هَذا سَيِّدُ قُرَيْشٍ، وصاحِبُ عِيرِ مَكَّةَ فَلَمّا ذَكَرَ حاجَتَهُ، قالَ: سَقَطْتَ مِن عَيْنِي جِئْتُ لِأهْدِمَ البَيْتَ الَّذِي هو دِينُكَ ودِينُ آبائِكَ فَألْهاكَ عَنْهُ ذَوْدٌ أُخِذَ لَكَ، فَقالَ أنا رَبُّ الإبِلِ ولِلْبَيْتِ رَبٌّ سَيَمْنَعُكَ عَنْهُ، ثُمَّ رَجَعَ وأتى البَيْتَ وأخَذَ بِحَلْقَتِهِ وهو يَقُولُ: لاهُمَّ إنَّ المَرْءَ يَمْـ ـنَعُ حِلَّهُ فامْنَعْ حَلالَكْ وانْصُرْ عَلى آلِ الصَّلِيـ ∗∗∗ ـبِ وعابِدِيهِ اليَوْمَ آلَكْ لا يَغْلِبَنَّ صَلِيبُهم ∗∗∗ ومِحالُهم عَدْوًا مِحالَكْ إنْ كُنْتَ تارِكَهم وكَعْـ ∗∗∗ ـبَتَنا فَأْمُرْ ما بَدا لَكْ ويَقُولُ: يا رَبِّ لا أرْجُو لَهم سِواكا ∗∗∗ يا رَبِّ فامْنَعْ عَنْهم حِماكا فالتَفَتَ وهو يَدْعُو، فَإذا هو بِطَيْرٍ مِن نَحْوِ اليَمَنِ، فَقالَ: واللَّهِ إنَّها لَطَيْرٌ غَرِيبَةٌ ما هي بِنَجْدِيَّةٍ ولا تِهامِيَّةٍ، وكانَ مَعَ كُلِّ طائِرٍ حَجَرٌ في مِنقارِهِ وحَجَرانِ في رِجْلَيْهِ أكْبَرَ مِنَ العَدَسَةِ وأصْغَرَ مِنَ الحِمِّصَةِ. وعَنِ ابْنِ عَبّاسٍ أنَّهُ رَأى مِنها عِنْدَ أُمِّ هانِئٍ نَحْوَ قَفِيزٍ مُخَطَّطَةٍ بِحُمْرَةٍ كالجَزَعِ الظَّفارِيِّ، فَكانَ الحَجَرُ يَقَعُ عَلى رَأْسِ الرَّجُلِ فَيَخْرُجُ مِن دُبُرِهِ، وعَلى كُلِّ حَجَرٍ اسْمُ مَن يَقَعُ عَلَيْهِ فَهَلَكُوا في كُلِّ طَرِيقٍ ومَنهَلٍ، ودَوّى أبْرَهَةُ فَتَساقَطَتْ أنامِلُهُ، وما ماتَ حَتّى انْصَدَعَ صَدْرُهُ عَنْ قَلْبِهِ، وانْفَلَتَ وزِيرُهُ أبُو يَكْسُومَ وطائِرٌ يُحَلِّقُ فَوْقَهُ، حَتّى بَلَغَ النَّجاشِيَّ فَقَصَّ عَلَيْهِ القِصَّةَ، فَلَمّا أتَمَّها وقَعَ عَلَيْهِ الحَجَرُ وخَرَّ مَيِّتًا بَيْنَ يَدَيْهِ. وعَنْ عائِشَةَ قالَتْ: ”رَأيْتُ قائِدَ الفِيلِ وسائِسَهُ أعْمَيَيْنِ مُقْعَدَيْنِ يَسْتَطْعِمانِ“ ثُمَّ في الآيَةِ سُؤالاتٌ: الأوَّلُ: لِمَ قالَ: (ألَمْ تَرَ) مَعَ أنَّ هَذِهِ الواقِعَةَ وقَعَتْ قَبْلَ المَبْعَثِ بِزَمانٍ طَوِيلٍ ؟ الجَوابُ: المُرادُ مِنَ الرُّؤْيَةِ العِلْمُ والتَّذْكِيرُ، وهو إشارَةٌ إلى أنَّ الخَبَرَ بِهِ مُتَواتِرٌ فَكانَ العِلْمُ الحاصِلُ بِهِ ضَرُورِيًّا مُساوِيًا في القُوَّةِ والجَلاءِ لِلرُّؤْيَةِ، ولِهَذا السَّبَبِ قالَ لِغَيْرِهِ عَلى سَبِيلِ الذَّمِّ: ﴿ألَمْ يَرَوْا كَمْ أهْلَكْنا قَبْلَهم مِنَ القُرُونِ﴾ [يس: ٣١] لا يُقالُ: فَلِمَ قالَ: ﴿ألَمْ تَعْلَمْ أنَّ اللَّهَ عَلى كُلِّ شَيْءٍ قَدِيرٌ﴾ [البقرة: ١٠٦] لِأنّا نَقُولُ: الفَرْقُ أنَّ ما لا يُتَصَوَّرُ إدْراكُهُ لا يُسْتَعْمَلُ فِيهِ إلّا العِلْمُ لِكَوْنِهِ قادِرًا، وأمّا الَّذِي يُتَصَوَّرُ إدْراكُهُ كَفِرارِ الفِيلِ، فَإنَّهُ يَجُوزُ أنْ يُسْتَعْمَلَ فِيهِ الرُّؤْيَةُ. السُّؤالُ الثّانِي: لِمَ قالَ: ﴿ألَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ﴾ ولَمْ يَقُلْ: ألَمْ تَرَ ما فَعَلَ رَبُّكَ ؟ الجَوابُ: لِأنَّ الأشْياءَ لَها ذَواتٌ، ولَها كَيْفِيّاتٌ بِاعْتِبارِها يَدُلُّ عَلى مُداوَمَتِها، وهَذِهِ الكَيْفِيَّةُ هي الَّتِي يُسَمِّيها المُتَكَلِّمُونَ وجْهَ الدَّلِيلِ، واسْتِحْقاقُ المَدْحِ إنَّما يَحْصُلُ بِرُؤْيَةِ هَذِهِ الكَيْفِيّاتِ لا بِرُؤْيَةِ الذَّواتِ ولِهَذا قالَ: ﴿أفَلَمْ يَنْظُرُوا إلى السَّماءِ فَوْقَهم كَيْفَ بَنَيْناها﴾ [ق: ٦] ولا شَكَّ أنَّ هَذِهِ الواقِعَةَ كانَتْ دالَّةً عَلى قُدْرَةِ الصّانِعِ وعِلْمِهِ وحِكْمَتِهِ، وكانَتْ دالَّةً عَلى شَرَفِ مُحَمَّدٍ ﷺ، وذَلِكَ لِأنَّ مَذْهَبَنا أنَّهُ يَجُوزُ تَقْدِيمُ المُعْجِزاتِ عَلى زَمانِ البَعْثَةِ تَأْسِيسًا لِنُبُوَّتِهِمْ وإرْهاصًا لَها، ولِذَلِكَ قالُوا: كانَتِ الغَمامَةُ تُظِلُّهُ، وعِنْدَ المُعْتَزِلَةِ، أنَّ ذَلِكَ لا يَجُوزُ، فَلا جَرَمَ زَعَمُوا أنَّهُ لا بُدَّ وأنْ يُقالَ: كانَ في ذَلِكَ الزَّمانِ نَبِيٌّ (أوْ خَطِيبٌ) كَخالِدِ بْنِ سِنانٍ أوْ قُسِّ بْنِ ساعِدَةَ، ثُمَّ قالُوا: ولا يَجِبُ أنْ يَشْتَهِرَ وُجُودُهُما ويَبْلُغَ إلى حَدِّ التَّواتُرِ، لِاحْتِمالِ أنَّهُ كانَ مَبْعُوثًا إلى جَمْعٍ قَلِيلِينَ، فَلا جَرَمَ لَمْ يَشْتَهِرْ خَبَرُهُ. واعْلَمْ أنَّ قِصَّةَ الفِيلِ واقِعَةٌ عَلى المُلْحِدِينَ جِدًّا، لِأنَّهم ذَكَرُوا في الزَّلازِلِ والرِّياحِ والصَّواعِقِ وسائِرِ الأشْياءِ الَّتِي عَذَّبَ اللَّهُ تَعالى بِها الأُمَمَ أعْذارًا ضَعِيفَةً، أمّا هَذِهِ الواقِعَةُ فَلا تَجْرِي فِيها تِلْكَ الأعْذارُ، لِأنَّها لَيْسَ في شَيْءٍ مِنَ الطَّبائِعِ والحِيَلِ أنْ يُقْبِلَ طَيْرٌ مَعَها حِجارَةٌ، فَتَقْصِدُ قَوْمًا دُونَ قَوْمٍ فَتَقْتُلُهم، ولا يُمْكِنُ أنْ يُقالَ: إنَّهُ كَسائِرِ الأحادِيثِ الضَّعِيفَةِ لِأنَّهُ لَمْ يَكُنْ بَيْنَ عامِ الفِيلِ ومَبْعَثِ الرَّسُولِ إلّا نَيِّفٌ وأرْبَعُونَ سَنَةً، ويَوْمَ تَلا الرَّسُولُ هَذِهِ السُّورَةَ كانَ قَدْ بَقِيَ بِمَكَّةَ جَمْعٌ شاهَدُوا تِلْكَ الواقِعَةَ، ولَوْ كانَ النَّقْلُ ضَعِيفًا لَشافَهُوهُ بِالتَّكْذِيبِ، فَلَمّا لَمْ يَكُنْ كَذَلِكَ عَلِمْنا أنَّهُ لا سَبَبَ لِلطَّعْنِ فِيهِ. السُّؤالُ الثّالِثُ: لِمَ قالَ: (فَعَلَ) ولَمْ يَقُلْ: جَعَلَ ولا خَلَقَ ولا عَمِلَ ؟ الجَوابُ: لِأنَّ خَلَقَ يُسْتَعْمَلُ لِابْتِداءِ الفِعْلِ، وجَعَلَ لِلْكَيْفِيّاتِ. قالَ تَعالى: ﴿خَلَقَ السَّماواتِ والأرْضَ وجَعَلَ الظُّلُماتِ والنُّورَ﴾ [الأنعام: ١] وعَمِلَ بَعْدَ الطَّلَبِ وفَعَلَ عامٌّ فَكانَ أوْلى لِأنَّهُ تَعالى خَلَقَ الطُّيُورَ وجَعَلَ طَبْعَ الفِيلِ عَلى خِلافِ ما كانَتْ عَلَيْهِ، وسَألُوهُ أنْ يَحْفَظَ البَيْتَ، ولَعَلَّهُ كانَ فِيهِمْ مَن يَسْتَحِقُّ الإجابَةَ، فَلَوْ ذَكَرَ الألْفاظَ الثَّلاثَةَ لَطالَ الكَلامُ فَذَكَرَ لَفْظًا يَشْمَلُ الكُلَّ. السُّؤالُ الرّابِعُ: لِمَ قالَ: رَبُّكَ، ولَمْ يَقُلْ: الرَّبُّ ؟ الجَوابُ: مِن وُجُوهٍ: أحَدُها: كَأنَّهُ تَعالى قالَ: إنَّهم لَمّا شاهَدُوا هَذا الِانْتِقامَ ثُمَّ لَمْ يَتْرُكُوا عِبادَةَ الأوْثانِ، وأنْتَ يا مُحَمَّدُ ما شاهَدْتَهُ ثُمَّ اعْتَرَفْتَ بِالشُّكْرِ والطّاعَةِ، فَكَأنَّكَ أنْتَ الَّذِي رَأيْتَ ذَلِكَ الِانْتِقامَ، فَلا جَرَمَ تَبَرَّأْتُ عَنْهم واخْتَرْتُكَ مِنَ الكُلِّ، فَأقُولُ: رَبُّكَ، أيْ أنا لَكَ ولَسْتُ لَهم بَلْ عَلَيْهِمْ. وثانِيها: كَأنَّهُ تَعالى قالَ: إنَّما فَعَلْتُ بِأصْحابِ الفِيلِ ذَلِكَ تَعْظِيمًا لَكَ وتَشْرِيفًا لِمَقْدَمِكَ، فَأنا كُنْتُ مُرَبِّيًا لَكَ قَبْلَ قَوْمِكِ، فَكَيْفَ أتْرُكُ تَرْبِيَتَكَ بَعْدَ ظُهُورِكَ، فَفِيهِ بِشارَةٌ لَهُ - عَلَيْهِ السَّلامُ - بِأنَّهُ سَيَظْفَرُ. السُّؤالُ الخامِسُ: قَوْلُهُ: ﴿ألَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ﴾ مَذْكُورٌ في مَعْرِضِ التَّعَجُّبِ، وهَذِهِ الأشْياءُ بِالنِّسْبَةِ إلى قُدْرَةِ اللَّهِ تَعالى لَيْسَتْ عَجِيبَةً، فَما السَّبَبُ لِهَذا التَّعَجُّبِ ؟ الجَوابُ: مِن وُجُوهٍ: أحَدُها: أنَّ الكَعْبَةَ تَبَعٌ لِمُحَمَّدٍ ﷺ، وذَلِكَ لِأنَّ العِلْمَ يُؤَدّى بِدُونِ المَسْجِدِ أمّا لا مَسْجِدَ بِدُونِ العالِمِ، فالعالِمُ هو الدُّرُّ والمَسْجِدُ هو الصَّدَفُ، ثُمَّ الرَّسُولُ الَّذِي هو الدُّرُّ هَمَزَهُ الوَلِيدُ ولَمَزَهُ حَتّى ضاقَ قَلْبُهُ، فَكَأنَّهُ تَعالى يَقُولُ: إنَّ المَلِكَ العَظِيمَ لَمّا طَعَنَ في المَسْجِدِ هَزَمْتُهُ وأفْنَيْتُهُ، فَمَن طَعَنَ فِيكَ وأنْتَ المَقْصُودُ مِنَ الكُلِّ ألا أُفْنِيهِ وأُعْدِمُهُ ! إنَّ هَذا لَعَجِيبٌ. وثانِيها: أنَّ الكَعْبَةَ قِبْلَةُ صَلاتِكَ، وقَلْبُكَ قِبْلَةُ مَعْرِفَتِكَ، ثُمَّ أنا حَفِظْتُ قِبْلَةَ عَمَلِكَ عَنِ الأعْداءِ، أفَلا نَسْعى في حِفْظِ قِبْلَةِ دِينِكَ عَنِ الآثامِ والمَعاصِي ! . السُّؤالُ السّادِسُ: لِمَ قالَ: ﴿بِأصْحابِ الفِيلِ﴾ ولَمْ يَقُلْ: أرْبابُ الفِيلِ أوْ مُلّاكُ الفِيلِ ؟ الجَوابُ: لِأنَّ الصّاحِبَ يَكُونُ مِنَ الجِنْسِ، فَقَوْلُهُ: ﴿بِأصْحابِ الفِيلِ﴾ يَدُلُّ عَلى أنَّ أُولَئِكَ الأقْوامَ كانُوا مِن جِنْسِ الفِيلِ في البَهِيمِيَّةِ وعَدَمِ الفَهْمِ والعَقْلِ، بَلْ فِيهِ دَقِيقَةٌ، وهي: أنَّهُ إذا حَصَلَتِ المُصاحَبَةُ بَيْنَ شَخْصَيْنِ، فَيُقالُ لِلْأدْوَنِ: إنَّهُ صاحِبُ الأعْلى، ولا يُقالُ لِلْأعْلى: إنَّهُ صاحِبُ الأدْوَنِ، ولِذَلِكَ يُقالُ لِمَن صَحِبَ الرَّسُولَ عَلَيْهِ السَّلامُ: إنَّهُمُ الصَّحابَةُ، فَقَوْلُهُ: ﴿بِأصْحابِ الفِيلِ﴾ يَدُلُّ عَلى أنَّ أُولَئِكَ الأقْوامَ كانُوا أقَلَّ حالًا وأدْوَنَ مَنزِلَةً مِنَ الفِيلِ، وهو المُرادُ مِن قَوْلِهِ تَعالى: ﴿بَلْ هم أضَلُّ﴾ [الأعراف: ١٧٩] ومِمّا يُؤَكِّدُ ذَلِكَ أنَّهم كُلَّما وجَّهُوا الفِيلَ إلى جِهَةِ الكَعْبَةِ كانَ يَتَحَوَّلُ عَنْهُ ويَفِرُّ عَنْهُ، كَأنَّهُ كانَ يَقُولُ: لا طاعَةَ لِمَخْلُوقٍ في مَعْصِيَةِ الخالِقِ عَزْمِي حَمِيدٌ فَلا أتْرُكُهُ وهم ما كانُوا يَتْرُكُونَ تِلْكَ العَزِيمَةَ الرَّدِيَّةَ فَدَلَّ ذَلِكَ عَلى أنَّ الفِيلَ كانَ أحْسَنَ حالًا مِنهم. السُّؤالُ السّابِعُ: ألَيْسَ أنَّ كُفّارَ قُرَيْشٍ كانُوا مَلَأُوا الكَعْبَةَ مِنَ الأوْثانِ مِن قَدِيمِ الدَّهْرِ، ولا شَكَّ أنَّ ذَلِكَ كانَ أقْبَحَ مِن تَخْرِيبِ جُدْرانِ الكَعْبَةِ، فَلِمَ سَلَّطَ اللَّهُ العَذابَ عَلى مَن قَصَدَ التَّخْرِيبَ، ولَمْ يُسَلِّطِ العَذابَ عَلى مَن مَلَأها مِنَ الأوْثانِ ؟ والجَوابُ: لِأنَّ وضْعَ الأوْثانِ فِيها تَعَدٍّ عَلى حَقِّ اللَّهِ تَعالى، وتَخْرِيبَها تَعَدٍّ عَلى حَقِّ الخَلْقِ، ونَظِيرُهُ قاطِعُ الطَّرِيقِ، والباغِي والقاتِلُ يُقْتَلُونَ مَعَ أنَّهم مُسْلِمُونَ، ولا يُقْتَلُ الشَّيْخُ الكَبِيرُ والأعْمى وصاحِبُ الصَّوْمَعَةِ والمَرْأةُ، وإنْ كانُوا كُفّارًا، لِأنَّهُ لا يَتَعَدّى ضَرَرُهم إلى الخَلْقِ. السُّؤالُ الثّامِنُ: كَيْفَ القَوْلُ في إعْرابِ هَذِهِ الآيَةِ ؟ الجَوابُ: قالَ الزَّجّاجُ: كَيْفَ في مَوْضِعِ نَصْبٍ بِفِعْلٍ لا بِقَوْلِهِ: (ألَمْ تَرَ) لِأنَّ كَيْفَ مِن حُرُوفِ الِاسْتِفْهامِ.',     source_page = '91',     updated_at  = datetime('now') WHERE id = 'QR:TE:8c4523d9f4d96ffca1f6184f';
UPDATE qr_tafsir_entries SET content_ar = 'واعْلَمْ أنَّهُ تَعالى ذَكَرَ ما فَعَلَ بِهِمْ. فَقالَ: ﴿ألَمْ يَجْعَلْ كَيْدَهم في تَضْلِيلٍ﴾ وفِيهِ مَسائِلُ: المَسْألَةُ الأُولى: اعْلَمْ أنَّ الكَيْدَ هو إرادَةٌ مُضِرَّةٌ بِالغَيْرِ عَلى الخُفْيَةِ، إنْ قِيلَ: فَلِمَ سَمّاهُ كَيْدًا وأمْرُهُ كانَ ظاهِرًا، فَإنَّهُ كانَ يُصَرِّحُ أنَّهُ يَهْدِمُ البَيْتَ ؟ قُلْنا: نَعَمْ، لَكِنَّ الَّذِي كانَ في قَلْبِهِ شَرٌّ مِمّا أظْهَرَ، لِأنَّهُ كانَ يُضْمِرُ الحَسَدَ لِلْعَرَبِ، وكانَ يُرِيدُ صَرْفَ الشَّرَفِ الحاصِلِ لَهم بِسَبَبِ الكَعْبَةِ مِنهم ومِن بَلَدِهِمْ إلى نَفْسِهِ وإلى بَلْدَتِهِ. المَسْألَةُ الثّانِيَةُ: قالَتِ المُعْتَزِلَةُ: إضافَةُ الكَيْدِ إلَيْهِمْ دَلِيلٌ عَلى أنَّهُ تَعالى لا يَرْضى بِالقَبِيحِ، إذْ لَوْ رَضِيَ لَأضافَهُ إلى ذاتِهِ، كَقَوْلِهِ: ”الصَّوْمُ لِي“ والجَوابُ: أنَّهُ ثَبَتَ في عِلْمِ النَّحْوِ أنَّهُ يَكْفِي في حُسْنِ الإضافَةِ أدْنى سَبَبٍ، فَلِمَ لا يَكْفِي في حُسْنِ هَذِهِ الإضافَةِ وُقُوعُهُ مُطابِقًا لِإرادَتِهِمْ واخْتِيارِهِمْ ؟ المَسْألَةُ الثّالِثَةُ: ﴿فِي تَضْلِيلٍ﴾ أيْ في تَضْيِيعٍ وإبْطالٍ يُقالُ: ضَلَّلَ كَيْدَهُ إذا جَعَلَهُ ضالًّا ضائِعًا ونَظِيرُهُ قَوْلُهُ تَعالى: ﴿وما دُعاءُ الكافِرِينَ إلّا في ضَلالٍ﴾ [ غافِرٍ: ٥٠] وقِيلَ لِامْرِئِ القَيْسِ: المَلِكُ الضَّلِيلُ: لِأنَّهُ ضَلَّلَ مُلْكَ أبِيهِ أيْ ضَيَّعَهُ. بِمَعْنى أنَّهم كادُوا البَيْتَ أوَّلًا بِبِناءِ القُلَّيْسِ وأرادُوا أنْ يَفْتَتِحُوا أمْرَهُ بِصَرْفِ وُجُوهِ الحاجِّ إلَيْهِ، فَضَلَّلَ كَيْدَهم بِإيقاعِ الحَرِيقِ فِيهِ، ثُمَّ كادُوهُ ثانِيًا بِإرادَةِ هَدْمِهِ فَضَلَّلَ بِإرْسالِ الطَّيْرِ عَلَيْهِمْ، ومَعْنى حَرْفِ الظَّرْفِ كَما يُقالُ: سَعْيُ فُلانٍ في ضَلالٍ، أيْ سَعْيُهم كانَ قَدْ ظَهَرَ لِكُلِّ عاقِلٍ أنَّهُ كانَ ضَلالٌ وخَطَأٌ. * * * ثُمَّ قالَ تَعالى: ﴿وأرْسَلَ عَلَيْهِمْ طَيْرًا أبابِيلَ﴾ وفِيهِ سُؤالاتٌ: السُّؤالُ الأوَّلُ: لِمَ قالَ: (طَيْرًا) عَلى التَّنْكِيرِ ؟ والجَوابُ: إمّا لِلتَّحْقِيرِ فَإنَّهُ مَهْما كانَ أحْقَرَ كانَ صُنْعُ اللَّهِ أعْجَبَ وأكْبَرَ، أوْ لِلتَّفْخِيمِ كَأنَّهُ يَقُولُ: طَيْرًا وأيُّ طَيْرٍ تَرْمِي بِحِجارَةٍ صَغِيرَةٍ فَلا تُخْطِئُ المَقْتَلَ. السُّؤالُ الثّانِي: ما الأبابِيلُ ؟ الجَوابُ: أمّا أهْلُ اللُّغَةِ قالَ أبُو عُبَيْدَةَ: أبابِيلُ جَماعَةٌ في تَفْرِقَةٍ، يُقالُ: جاءَتْ الخَيْلُ أبابِيلَ أبابِيلَ مِن هَهُنا وهَهُنا، وهَلْ لِهَذِهِ اللَّفْظَةِ واحِدٌ أمْ لا ؟ فِيهِ قَوْلانِ: الأوَّلُ: وهو قَوْلُ الأخْفَشِ والفَرّاءِ: أنَّهُ لا واحِدَ لَها وهو مِثْلُ الشَّماطِيطِ والعَبادِيدِ، لا واحِدَ لَها. والثّانِي: أنَّهُ لَهُ واحِدٌ، ثُمَّ عَلى هَذا القَوْلِ ذَكَرُوا ثَلاثَةَ أوْجُهٍ: أحَدُها: زَعَمَ أبُو جَعْفَرٍ الرُّؤاسِيُّ وكانَ ثِقَةً مَأْمُونًا أنَّهُ سَمِعَ واحِدَها إبّالَةٌ، وفي أمْثالِهِمْ: ضِغْثٌ عَلى إبّالَةٍ، وهي الحُزْمَةُ الكَبِيرَةُ سُمِّيَتِ الجَماعَةُ مِنَ الطَّيْرِ في نِظامِها بِالإبّالَةِ. وثانِيها: قالَ الكِسائِيُّ: كُنْتُ أسْمَعُ النَّحْوِيِّينَ يَقُولُونَ: إبُولٌ وأبابِيلُ كَعُجُولٍ وعَجاجِيلَ. وثالِثُها: قالَ الفَرّاءُ: ولَوْ قالَ قائِلٌ: واحِدُ الأبابِيلِ إيبالَةٌ كانَ صَوابًا كَما قالَ: دِينارٌ ودَنانِيرُ. السُّؤالُ الثّالِثُ: ما صِفَةُ تِلْكَ الطَّيْرِ ؟ الجَوابُ: رَوى ابْنُ سِيرِينَ عَنِ ابْنِ عَبّاسٍ قالَ: كانَتْ طَيْرًا لَها خَراطِيمُ كَخَراطِيمِ الفِيلِ وأكُفٌّ كَأكُفِّ الكِلابِ، ورَوى عَطاءٌ عَنْهُ قالَ: طَيْرٌ سُودٌ جاءَتْ مِن قِبَلِ البَحْرِ فَوْجًا فَوْجًا، ولَعَلَّ السَّبَبَ أنَّها أُرْسِلَتْ إلى قَوْمٍ كانَ في صُورَتِهِمْ سَوادُ اللَّوْنِ وفي سِرِّهِمْ سَوادُ الكُفْرِ والمَعْصِيَةِ، وعَنْ سَعِيدِ بْنِ جُبَيْرٍ أنَّها بِيضٌ صِغارٌ ولَعَلَّ السَّبَبَ أنَّ ظُلْمَةَ الكُفْرِ انْهَزَمَتْ بِها، والبَياضُ ضِدُّ السَّوادِ، وقِيلَ: كانَتْ خُضْرًا ولَها رُؤُوسٌ مِثْلُ رُؤُوسِ السِّباعِ، وأقُولُ: إنَّها لَمّا كانَتْ أفْواجًا، فَلَعَلَّ كُلَّ فَوْجٍ مِنها كانَ عَلى شَكْلٍ آخَرَ فَكُلُّ أحَدٍ وصَفَ ما رَأى، وقِيلَ: كانَتْ بَلْقاءَ كالخَطاطِيفِ.',     source_page = '95',     updated_at  = datetime('now') WHERE id = 'QR:TE:76fa873b4b1c6d2142ec3043';
UPDATE qr_tafsir_entries SET content_ar = 'ثُمَّ قالَ تَعالى: ﴿تَرْمِيهِمْ بِحِجارَةٍ مِن سِجِّيلٍ﴾ وفِيهِ مَسائِلُ: المَسْألَةُ الأُولى: قَرَأ أبُو حَيْوَةَ: يَرْمِيهِمْ أيِ اللَّهُ أوِ الطَّيْرُ لِأنَّهُ اسْمُ جَمْعٍ مُذَكَّرٌ، وإنَّما يُؤَنَّثُ عَلى المَعْنى. المَسْألَةُ الثّانِيَةُ: ذَكَرُوا في كَيْفِيَّةِ الرَّمْيِ وُجُوهًا: أحَدُها: قالَ مُقاتِلٌ: كانَ كُلُّ طائِرٍ يَحْمِلُ ثَلاثَةَ أحْجارٍ، واحِدٌ في مِنقارِهِ واثْنانِ في رِجْلَيْهِ يَقْتُلُ كُلُّ واحِدٍ رَجُلًا، مَكْتُوبٌ عَلى كُلِّ حَجَرٍ اسْمُ صاحِبِهِ ما وقَعَ مِنها حَجَرٌ عَلى مَوْضِعٍ إلّا خَرَجَ مِنَ الجانِبِ الآخَرِ، وإنْ وقَعَ عَلى رَأْسِهِ خَرَجَ مِن دُبُرِهِ. وثانِيها: رَوى عِكْرِمَةُ عَنِ ابْنِ عَبّاسٍ، قالَ: لَمّا أرْسَلَ اللَّهُ الحِجارَةَ عَلى أصْحابِ الفِيلِ لَمْ يَقَعْ حَجَرٌ عَلى أحَدٍ مِنهم إلّا نَفِطَ جِلْدُهُ وثارَ بِهِ الجُدَرِيُّ، وهو قَوْلُ سَعِيدِ بْنِ جُبَيْرٍ، وكانَتْ تِلْكَ الأحْجارُ أصْغَرُها مِثْلُ العَدَسَةِ، وأكْبَرُها مِثْلُ الحِمِّصَةِ. واعْلَمْ أنَّ مِنَ النّاسِ مَن أنْكَرَ ذَلِكَ، وقالَ: لَوْ جَوَّزْنا أنْ يَكُونَ في الحِجارَةِ الَّتِي تَكُونُ مِثْلَ العَدَسَةِ مِنَ الثِّقَلِ ما يَقْوى بِهِ عَلى أنْ يَنْفُذَ مِن رَأْسِ الإنْسانِ ويَخْرُجَ مِن أسْفَلِهِ، لَجَوَّزْنا أنْ يَكُونَ الجَبَلُ العَظِيمُ خالِيًا عَنِ الثِّقَلِ وأنْ يَكُونَ في وزْنِ التِّبْنَةِ، وذَلِكَ يَرْفَعُ الأمانَ عَنِ المُشاهَداتِ، فَإنَّهُ مَتى جازَ ذَلِكَ فَلْيَجُزْ أنْ يَكُونَ بِحَضْرَتِنا شُمُوسٌ وأقْمارٌ ولا نَراها، وأنْ يَحْصُلَ الإدْراكُ في عَيْنِ الضَّرِيرِ حَتّى يَكُونَ هو بِالمُشْرِقِ ويَرى بُقْعَةً في الأنْدَلُسِ، وكُلُّ ذَلِكَ مُحالٌ. واعْلَمْ أنَّ ذَلِكَ جائِزٌ عَلى مَذْهَبِنا إلّا أنَّ العادَةَ جارِيَةٌ بِأنَّها لا تَقَعُ. المَسْألَةُ الثّالِثَةُ: ذَكَرُوا في السِّجِّيلِ وُجُوهًا: أحَدُها: أنَّ السِّجِّيلَ كَأنَّهُ عَلَمٌ لِلدِّيوانِ الَّذِي كُتِبَ فِيهِ عَذابُ الكُفّارِ، كَما أنَّ سِجِّينًا عَلَمٌ لِدِيوانِ أعْمالِهِمْ، كَأنَّهُ قِيلَ: بِحِجارَةٍ مِن جُمْلَةِ العَذابِ المَكْتُوبِ المُدَوَّنِ، واشْتِقاقُهُ مِنَ الإسْجالِ، وهو الإرْسالُ، ومِنهُ السِّجِلُّ الدَّلْوُ المَمْلُوءُ ماءً، وإنَّما سُمِّيَ ذَلِكَ الكِتابُ بِهَذا الِاسْمِ لِأنَّهُ كُتِبَ فِيهِ العَذابُ، والعَذابُ مَوْصُوفٌ بِالإرْسالِ لِقَوْلِهِ تَعالى: ﴿وأرْسَلَ عَلَيْهِمْ طَيْرًا أبابِيلَ﴾ وقَوْلِهِ: ﴿فَأرْسَلْنا عَلَيْهِمُ الطُّوفانَ﴾ [الأعراف: ١٣٣] فَقَوْلُهُ: ﴿مِن سِجِّيلٍ﴾ أيْ مِمّا كَتَبَهُ اللَّهُ في ذَلِكَ الكِتابِ. وثانِيها: قالَ ابْنُ عَبّاسٍ: سِجِّيلٌ مَعْناهُ سَنْكِ وكِلْ، يَعْنِي بَعْضُهُ حَجَرٌ وبَعْضُهُ طِينٌ. وثالِثُها: قالَ أبُو عُبَيْدَةَ: السِّجِّيلُ الشَّدِيدُ. ورابِعُها: السِّجِّيلُ اسْمٌ لِسَماءِ الدُّنْيا. وخامِسُها: السِّجِّيلُ حِجارَةٌ مِن جَهَنَّمَ، فَإنَّ سِجِّيلَ اسْمٌ مِن أسْماءِ جَهَنَّمَ فَأُبْدِلَتِ النُّونُ بِاللّامِ.',     source_page = '96',     updated_at  = datetime('now') WHERE id = 'QR:TE:b7cbcae2ed51eb32f1de2bff';
UPDATE qr_tafsir_entries SET content_ar = '(سُورَةُ قُرَيْشٍ) وهِيَ أرْبَعُ آياتٍ مَكِّيَّةٌ ﷽ ﴿لِإيلافِ قُرَيْشٍ﴾ ﴿إيلافِهِمْ رِحْلَةَ الشِّتاءِ والصَّيْفِ﴾ ﷽ ﴿لِإيلافِ قُرَيْشٍ﴾ ﴿إيلافِهِمْ﴾ اعْلَمْ أنَّ هَهُنا مَسائِلَ: المَسْألَةُ الأُولى: اللّامُ في قَوْلِهِ: (لِإيلافِ) تَحْتَمِلُ وُجُوهًا ثَلاثَةً: فَإنَّها إمّا أنْ تَكُونَ مُتَعَلِّقَةً بِالسُّورَةِ الَّتِي قَبْلَها أوْ بِالآيَةِ الَّتِي بَعْدَها، أوْ لا تَكُونَ مُتَعَلِّقَةً لا بِما قَبْلَها، ولا بِما بَعْدَها. أمّا الوَجْهُ الأوَّلُ: وهو أنْ تَكُونَ مُتَعَلِّقَةً بِما قَبْلَها، فَفِيهِ احْتِمالاتٌ: الأوَّلُ: وهو قَوْلُ الزَّجّاجِ وأبِي عُبَيْدَةَ أنَّ التَّقْدِيرَ: ﴿فَجَعَلَهم كَعَصْفٍ مَأْكُولٍ﴾ لِإلْفِ قُرَيْشٍ أيْ أهْلَكَ اللَّهُ أصْحابَ الفِيلِ لِتَبْقى قُرَيْشٌ، وما قَدْ ألِفُوا مِن رِحْلَةِ الشِّتاءِ والصَّيْفِ، فَإنْ قِيلَ: هَذا ضَعِيفٌ لِأنَّهم إنَّما جُعِلُوا: ﴿كَعَصْفٍ مَأْكُولٍ﴾ لِكُفْرِهِمْ ولَمْ يُجْعَلُوا كَذَلِكَ لِتَأْلِيفِ قُرَيْشٍ. قُلْنا: هَذا السُّؤالُ ضَعِيفٌ لِوُجُوهٍ: أحَدُها: أنّا لا نُسَلِّمُ أنَّ اللَّهَ تَعالى إنَّما فَعَلَ بِهِمْ ذَلِكَ لِكُفْرِهِمْ، فَإنَّ الجَزاءَ عَلى الكُفْرِ مُؤَخَّرٌ لِلْقِيامَةِ، قالَ تَعالى: ﴿اليَوْمَ تُجْزى كُلُّ نَفْسٍ بِما كَسَبَتْ﴾ [غافر: ١٧] وقالَ: ﴿ولَوْ يُؤاخِذُ اللَّهُ النّاسَ بِما كَسَبُوا ما تَرَكَ عَلى ظَهْرِها مِن دابَّةٍ﴾ [فاطر: ٤٥] ولِأنَّهُ تَعالى لَوْ فَعَلَ بِهِمْ ذَلِكَ لِكُفْرِهِمْ، لَكانَ قَدْ فَعَلَ ذَلِكَ بِجَمِيعِ الكُفّارِ، بَلْ إنَّما فَعَلَ ذَلِكَ بِهِمْ: ﴿لِإيلافِ قُرَيْشٍ﴾ ولِتَعْظِيمِ مَنصِبِهِمْ وإظْهارِ قَدْرِهِمْ. وثانِيها: هَبْ أنَّ زَجْرَهم عَنِ الكُفْرِ مَقْصُودٌ لَكِنْ لا يُنافِي كَوْنَ شَيْءٍ آخَرَ مَقْصُودٍ حَتّى يَكُونَ الحُكْمُ واقِعًا بِمَجْمُوعِ الأمْرَيْنِ مَعًا. وثالِثُها: هَبْ أنَّهم أُهْلِكُوا لِكُفْرِهِمْ فَقَطْ، إلّا أنَّ ذَلِكَ الإهْلاكَ لَمّا أدّى إلى إيلافِ قُرَيْشٍ، جازَ أنْ يُقالَ: أُهْلِكُوا لِإيلافِ قُرَيْشٍ، كَقَوْلِهِ تَعالى: ﴿لِيَكُونَ لَهم عَدُوًّا وحَزَنًا﴾ [القصص: ٨] وهم لَمْ يَلْتَقِطُوهُ لِذَلِكَ، لَكِنْ لَمّا آلَ الأمْرُ إلَيْهِ حَسُنَ أنْ يُمَهِّدَ عَلَيْهِ الِالتِقاطَ. الِاحْتِمالُ الثّانِي: أنْ يَكُونَ التَّقْدِيرُ: ”ألَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأصْحابِ الفِيلِ لِإيلافِ قُرَيْشٍ“ كَأنَّهُ تَعالى قالَ: كُلُّ ما فَعَلْنا بِهِمْ فَقَدْ فَعَلْناهُ، لِإيلافِ قُرَيْشٍ، فَإنَّهُ تَعالى جَعَلَ كَيْدَهم في تَضْلِيلٍ وأرْسَلَ عَلَيْهِمْ طَيْرًا أبابِيلَ، حَتّى صارُوا كَعَصْفٍ مَأْكُولٍ، فَكُلُّ ذَلِكَ إنَّما كانَ لِأجْلِ إيلافِ قُرَيْشٍ. الِاحْتِمالُ الثّالِثُ: أنْ تَكُونَ اللّامُ في قَوْلِهِ: (لِإيلافِ) بِمَعْنى إلى كَأنَّهُ قالَ: فَعَلْنا كُلَّ ما فَعَلْنا في السُّورَةِ المُتَقَدِّمَةِ إلى نِعْمَةٍ أُخْرى عَلَيْهِمْ وهي إيلافُهم: ﴿رِحْلَةَ الشِّتاءِ والصَّيْفِ﴾ تَقُولُ: نِعْمَةُ اللَّهِ نِعْمَةٌ، ونِعْمَةٌ لِنِعْمَةٍ سَواءٌ في المَعْنى، هَذا قَوْلُ الفَرّاءِ، فَهَذِهِ احْتِمالاتٌ ثَلاثَةٌ تَوَجَّهَتْ عَلى تَقْدِيرِ تَعْلِيقِ اللّامِ بِالسُّورَةِ الَّتِي قَبْلَ هَذِهِ، وبَقِيَ مِن مَباحِثِ هَذا القَوْلِ أمْرانِ: الأوَّلُ: أنَّ لِلنّاسِ في تَعْلِيقِ هَذِهِ اللّامِ بِالسُّورَةِ المُتَقَدِّمَةِ قَوْلَيْنِ: أحَدُهُما: أنْ جَعَلُوا السُّورَتَيْنِ سُورَةً واحِدَةً واحْتَجُّوا عَلَيْهِ بِوُجُوهٍ: أحَدُها: أنَّ السُّورَتَيْنِ لا بُدَّ وأنْ تَكُونَ كُلُّ واحِدَةٍ مِنهُما مُسْتَقِلَّةً بِنَفْسِها، ومَطْلَعُ هَذِهِ السُّورَةِ لَمّا كانَ مُتَعَلِّقًا بِالسُّورَةِ المُتَقَدِّمَةِ وجَبَ أنْ لا تَكُونَ سُورَةً مُسْتَقِلَّةً. وثانِيها: أنَّ أُبَيَّ بْنَ كَعْبٍ جَعَلَهُما في مُصْحَفِهِ سُورَةً واحِدَةً. وثالِثُها: ما رُوِيَ أنَّ عُمَرَ قَرَأ في صَلاةِ المَغْرِبِ في الرَّكْعَةِ الأُولى والتِّينِ، وفي الثّانِيَةِ ألَمْ تَرَ ولِإيلافِ قُرَيْشٍ مَعًا، مِن غَيْرِ فَصْلٍ بَيْنَهُما بِبِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ. القَوْلُ الثّانِي: وهو المَشْهُورُ المُسْتَفِيضُ أنَّ هَذِهِ السُّورَةَ مُنْفَصِلَةٌ عَنْ سُورَةِ الفِيلِ، وأمّا تَعَلُّقُ أوَّلِ هَذِهِ السُّورَةِ بِما قَبْلَها فَلَيْسَ بِحُجَّةٍ عَلى ما قالُوهُ، لِأنَّ القُرْآنَ كُلَّهُ كالسُّورَةِ الواحِدَةِ وكالآيَةِ الواحِدَةِ يُصَدِّقُ بَعْضُها بَعْضًا ويُبَيِّنُ بَعْضُها مَعْنى بَعْضٍ، ألا تَرى أنَّ الآياتِ الدّالَّةَ عَلى الوَعِيدِ مُطْلَقَةٌ، ثُمَّ إنَّها مُتَعَلِّقَةٌ بِآياتِ التَّوْبَةِ وبِآياتِ العَفْوِ عِنْدَ مَن يَقُولُ بِهِ، وقَوْلُهُ: ﴿إنّا أنْزَلْناهُ﴾ [القدر: ١] مُتَعَلِّقٌ بِما قَبْلَهُ مِن ذِكْرِ القُرْآنِ، وأمّا قَوْلُهُ: إنَّ أُبَيًّا لَمْ يَفْصِلْ بَيْنَهُما فَهو مُعارَضٌ بِإطْباقِ الكُلِّ عَلى الفَصْلِ بَيْنَهُما، وأمّا قِراءَةُ عُمَرَ فَإنَّها لا تَدُلُّ عَلى أنَّهُما سُورَةٌ واحِدَةٌ لِأنَّ الإمامَ قَدْ يَقْرَأُ سُورَتَيْنِ. البَحْثُ الثّانِي: فِيما يَتَعَلَّقُ بِهَذا القَوْلِ: بَيانُ أنَّهُ لِمَ صارَ ما فَعَلَهُ اللَّهُ بِأصْحابِ الفِيلِ سَبَبًا لِإيلافِ قُرَيْشٍ ؟ فَنَقُولُ: لا شَكَّ أنَّ مَكَّةَ كانَتْ خالِيَةً عَنِ الزَّرْعِ والضَّرْعِ عَلى ما قالَ تَعالى: ﴿بِوادٍ غَيْرِ ذِي زَرْعٍ﴾ [إبراهيم: ٣٧] إلى قَوْلِهِ: ﴿فاجْعَلْ أفْئِدَةً مِنَ النّاسِ تَهْوِي إلَيْهِمْ وارْزُقْهم مِنَ الثَّمَراتِ﴾ [إبراهيم: ٣٧] فَكانَ أشْرافُ أهْلِ مَكَّةَ يَرْتَحِلُونَ لِلتِّجارَةِ هاتَيْنِ الرِّحْلَتَيْنِ، ويَأْتُونَ لِأنْفُسِهِمْ ولِأهْلِ بَلَدِهِمْ بِما يَحْتاجُونَ إلَيْهِ مِنَ الأطْعِمَةِ والثِّيابِ، وهم إنَّما كانُوا يَرْبَحُونَ في أسْفارِهِمْ، ولِأنَّ مُلُوكَ النَّواحِي كانُوا يُعَظِّمُونَ أهْلَ مَكَّةَ، ويَقُولُونَ: هَؤُلاءِ جِيرانُ بَيْتِ اللَّهِ وسُكّانُ حَرَمِهِ ووُلاةُ الكَعْبَةِ حَتّى إنَّهم كانُوا يُسَمُّونَ أهْلَ مَكَّةَ أهْلَ اللَّهِ، فَلَوْ تَمَّ لِلْحَبَشَةِ ما عَزَمُوا عَلَيْهِ مِن هَدْمِ الكَعْبَةِ، لَزالَ عَنْهم هَذا العِزُّ ولَبَطَلَتْ تِلْكَ المَزايا في التَّعْظِيمِ والِاحْتِرامِ، ولَصارَ سُكّانُ مَكَّةَ كَسُكّانِ سائِرِ النَّواحِي يُتَخَطَّفُونَ مِن كُلِّ جانِبٍ ويُتَعَرَّضُ لَهم في نُفُوسِهِمْ وأمْوالِهِمْ، فَلَمّا أهْلَكَ اللَّهُ أصْحابَ الفِيلِ ورَدَّ كَيْدَهم في نَحْرِهِمُ ازْدادَ وقْعُ أهْلِ مَكَّةَ في القُلُوبِ، وازْدادَ تَعْظِيمُ مُلُوكِ الأطْرافِ لَهم فازْدادَتْ تِلْكَ المَنافِعُ والمَتاجِرُ، فَلِهَذا قالَ اللَّهُ تَعالى: ﴿ألَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأصْحابِ الفِيلِ﴾ [الفيل: ١] ﴿لِإيلافِ قُرَيْشٍ﴾ . . . ﴿رِحْلَةَ الشِّتاءِ والصَّيْفِ﴾ . والوَجْهُ الثّانِي فِيما يَدُلُّ عَلى صِحَّةِ هَذا القَوْلِ: أنَّ قَوْلَهُ تَعالى في آخِرِ هَذِهِ السُّورَةِ: ﴿فَلْيَعْبُدُوا رَبَّ هَذا البَيْتِ الَّذِي﴾ إشارَةٌ إلى أوَّلِ سُورَةِ الفِيلِ، كَأنَّهُ قالَ: فَلْيَعْبُدُوا رَبَّ هَذا البَيْتِ، الَّذِي قَصَدَهُ أصْحابُ الفِيلِ، ثُمَّ إنَّ رَبَّ البَيْتِ دَفَعَهم عَنْ مَقْصُودِهِمْ لِأجْلِ إيلافِكم ونَفْعِكم لِأنَّ الأمْرَ بِالعِبادَةِ إنَّما يَحْسُنُ مُرَتَّبًا عَلى إيصالِ المَنفَعَةِ، فَهَذا يَدُلُّ عَلى تَعَلُّقِ أوَّلِ هَذِهِ السُّورَةِ بِالسُّورَةِ المُتَقَدِّمَةِ. القَوْلُ الثّانِي: وهو أنَّ اللّامَ في: (لِإيلافِ) مُتَعَلِّقَةٌ بِقَوْلِهِ: (فَلْيَعْبُدُوا) وهو قَوْلُ الخَلِيلِ وسِيبَوَيْهِ والتَّقْدِيرُ: فَلْيَعْبُدُوا رَبَّ هَذا البَيْتِ، لِإيلافِ قُرَيْشٍ. أيْ لِيَجْعَلُوا عِبادَتَهم شُكْرًا لِهَذِهِ النِّعْمَةِ واعْتِرافًا بِها، فَإنْ قِيلَ: فَلِمَ دَخَلَتِ الفاءُ في قَوْلِهِ: (فَلْيَعْبُدُوا) ؟ قُلْنا: لِما في الكَلامِ مِن مَعْنى الشَّرْطِ، وذَلِكَ لِأنَّ نِعَمَ اللَّهِ عَلَيْهِمْ لا تُحْصى، فَكَأنَّهُ قِيلَ: إنْ لَمْ يَعْبُدُوهُ لِسائِرِ نِعَمِهِ فَلْيَعْبُدُوهُ لِهَذِهِ الواحِدَةِ الَّتِي هي نِعْمَةٌ ظاهِرَةٌ. القَوْلُ الثّالِثُ: أنْ تَكُونَ هَذِهِ اللّامُ غَيْرَ مُتَعَلِّقَةٍ، لا بِما قَبْلَها ولا بِما بَعْدَها، قالَ الزَّجّاجُ: قالَ قَوْمٌ: هَذِهِ اللّامُ لامُ التَّعَجُّبِ، كَأنَّ المَعْنى: اعْجَبُوا لِإيلافِ قُرَيْشٍ، وذَلِكَ لِأنَّهم كُلَّ يَوْمٍ يَزْدادُونَ غَيًّا وجَهْلًا وانْغِماسًا في عِبادَةِ الأوْثانِ، واللَّهُ تَعالى يُؤَلِّفُ شَمْلَهم ويَدْفَعُ الآفاتِ عَنْهم، ويُنَظِّمُ أسْبابَ مَعايِشِهِمْ، وذَلِكَ لا شَكَّ أنَّهُ في غايَةِ التَّعَجُّبِ مِن عَظِيمِ حِلْمِ اللَّهِ وكَرَمِهِ، ونَظِيرُهُ في اللُّغَةِ قَوْلُكَ: لِزَيْدٍ وما صَنَعْنا بِهِ ! ولِزَيْدٍ وكَرامَتِنا إيّاهُ ! وهَذا اخْتِيارُ الكِسائِيِّ والأخْفَشِ والفَرّاءِ. * * * المَسْألَةُ الثّانِيَةُ: ذَكَرُوا في الإيلافِ ثَلاثَةَ أوْجُهٍ: أحَدُها: أنَّ الإيلافَ هو الإلْفُ. قالَ عُلَماءُ اللُّغَةِ: ألِفْتُ الشَّيْءَ وألَفْتُهُ إلْفًا وإلافًا وإيلافًا بِمَعْنًى واحِدٍ، أيْ لَزِمْتُهُ فَيَكُونُ المَعْنى لِإلْفِ قُرَيْشٍ هاتَيْنِ الرِّحْلَتَيْنِ فَتَتَّصِلا ولا تَنْقَطِعا، وقَرَأ أبُو جَعْفَرٍ: ”لِإلْفِ قُرَيْشٍ“ وقَرَأ الآخَرُونَ: ”لِإلافِ قُرَيْشٍ“، وقَرَأ عِكْرِمَةُ: ”لِيلافِ قُرَيْشٍ“ . وثانِيها: أنْ يَكُونَ هَذا مِن قَوْلِكَ: لَزِمْتُ مَوْضِعَ كَذا وألْزَمَنِيهِ اللَّهُ، كَذا تَقُولُ: ألِفْتُ كَذا، وألَفَنِيهِ اللَّهُ ويَكُونُ المَعْنى إثْباتَ الأُلْفَةِ بِالتَّدْبِيرِ الَّذِي فِيهِ لُطْفٌ. ألِفَ بِنَفْسِهِ إلْفًا وآلَفَهُ غَيْرُهُ إيلافًا، والمَعْنى أنَّ هَذِهِ الإلْفَةَ إنَّما حَصَلَتْ في قُرَيْشٍ بِتَدْبِيرِ اللَّهِ وهو كَقَوْلِهِ: ﴿ولَكِنَّ اللَّهَ ألَّفَ بَيْنَهُمْ﴾ [الأنفال: ٦٣] وقالَ: ﴿فَألَّفَ بَيْنَ قُلُوبِكم فَأصْبَحْتُمْ بِنِعْمَتِهِ إخْوانًا﴾ [آل عمران: ١٠٣] وقَدْ تَكُونُ المَسَرَّةُ سَبَبًا لِلْمُؤانَسَةِ والِاتِّفاقِ، كَما وقَعَتْ عِنْدَ انْهِزامِ أصْحابِ الفِيلِ لِقُرَيْشٍ، فَيَكُونُ المَصْدَرُ هَهُنا مُضافًا إلى المَفْعُولِ ويَكُونُ المَعْنى لِأجْلِ أنْ يَجْعَلَ اللَّهُ قُرَيْشًا مُلازِمِينَ لِرِحْلَتَيْهِمْ. وثالِثُها: أنْ يَكُونَ الإيلافُ هو التَّهْيِئَةُ والتَّجْهِيزُ وهو قَوْلُ الفَرّاءِ وابْنِ الأعْرابِيِّ، فَيَكُونُ المَصْدَرُ عَلى هَذا القَوْلِ مُضافًا إلى الفاعِلِ، والمَعْنى: لِتَجْهِيزِ قُرَيْشٍ رِحْلَتَيْها حَتّى تَتَّصِلا ولا تَنْقَطِعا، وقَرَأ أبُو جَعْفَرٍ ”لِيلافِ“ بِغَيْرِ هَمْزٍ فَحَذَفَ هَمْزَةَ الإفْعالِ حَذْفًا كُلِّيًّا وهو كَمَذْهَبِهِ في ”يَسْتَهْزِءُونَ“ وقَدْ مَرَّ تَقْرِيرُهُ. المَسْألَةُ الثّالِثَةُ: التَّكْرِيرُ في قَوْلِهِ: ﴿لِإيلافِ قُرَيْشٍ﴾ ﴿إيلافِهِمْ﴾ هو أنَّهُ أطْلَقَ الإيلافَ أوَّلًا ثُمَّ جَعَلَ المُقَيَّدَ بَدَلًا لِذَلِكَ المُطْلَقِ تَفْخِيمًا لِأمْرِ الإيلافِ وتَذْكِيرًا لِعَظِيمِ المِنَّةِ فِيهِ، والأقْرَبُ أنْ يَكُونَ قَوْلُهُ: ﴿لِإيلافِ قُرَيْشٍ﴾ عامًّا يَجْمَعُ كُلَّ مُؤانَسَةٍ ومُوافَقَةٍ كانَ بَيْنَهم، فَيَدْخُلُ فِيهِ مَقامُهم وسِيَرُهم وجَمِيعُ أحْوالِهِمْ، ثُمَّ خَصَّ إيلافِ الرِّحْلَتَيْنِ بِالذِّكْرِ لِسَبَبِ أنَّهُ قِوامُ مَعاشِهِمْ كَما في قَوْلِهِ: ﴿وجِبْرِيلَ ومِيكالَ﴾ [البقرة: ٩٨] وفائِدَةُ تَرْكِ واوِ العَطْفِ التَّنْبِيهُ عَلى أنَّهُ كُلُّ النِّعْمَةِ، تَقُولُ العَرَبُ: ألِفْتُ كَذا أيْ لَزِمْتُهُ، والإلْزامُ ضَرْبانِ: إلْزامٌ بِالتَّكْلِيفِ والأمْرِ، وإلْزامٌ بِالمَوَدَّةِ والمُؤانَسَةِ فَإنَّهُ إذا أحَبَّ المَرْءُ شَيْئًا لَزِمَهُ، ومِنهُ: ﴿وألْزَمَهم كَلِمَةَ التَّقْوى﴾ [الفتح: ٢٦] ، كَما أنَّ الإلْجاءَ ضَرْبانِ: أحَدُهُما: لِدَفْعِ الضَّرَرِ كالهَرَبِ مِنَ السَّبُعِ. والثّانِي: لِطَلَبِ النَّفْعِ العَظِيمِ، كَمَن يَجِدُ مالًا عَظِيمًا ولا مانِعَ مِن أخْذِهِ لا عَقْلًا ولا شَرْعًا ولا حِسًّا فَإنَّهُ يَكُونُ كالمُلْجَأِ إلى الأخْذِ، وكَذا الدَّواعِي الَّتِي تَكُونُ دُونَ الإلْجاءِ، مَرَّةً تَكُونُ لِدَفْعِ الضَّرَرِ وأُخْرى لِجَلْبِ النَّفْعِ، وهو المُرادُ في قَوْلِهِ: (إيلافِهِمْ) . المَسْألَةُ الرّابِعَةُ: اتَّفَقُوا عَلى أنَّ قُرَيْشًا ولَدُ النَّضْرِ بْنِ كِنانَةَ، قالَ عَلَيْهِ الصَّلاةُ والسَّلامُ: «إنّا بَنِي النَّضْرِ بْنِ كِنانَةَ لا نَقْفُوا أُمَّنا ولا نَنْتَفِي مِن أبِينا» وذَكَرُوا في سَبَبِ هَذِهِ التَّسْمِيَةِ وُجُوهًا: أحَدُها: أنَّهُ تَصْغِيرُ القِرْشِ وهو دابَّةٌ عَظِيمَةٌ في البَحْرِ تَعْبَثُ بِالسُّفُنِ، ولا تَنْطَلِقُ إلّا بِالنّارِ، وعَنْ مُعاوِيَةَ أنَّهُ سَألَ ابْنَ عَبّاسٍ: بِمَ سُمِّيَتْ قُرَيْشٌ ؟ قالَ: بِدابَّةٍ في البَحْرِ تَأْكُلُ ولا تُؤْكَلُ، تَعْلُو ولا تُعْلى، وأنْشَدَ: وقُرَيْشٌ هي الَّتِي تَسْكُنُ البَحْـ ـرَ بِها سُمِّيَتْ قُرَيْشٌ قُرَيْشا والتَّصْغِيرُ لِلتَّعْظِيمِ، ومَعْلُومٌ أنَّ قُرَيْشًا مَوْصُوفُونَ بِهَذِهِ الصِّفاتِ لِأنَّها تَلِي أمْرَ الأُمَّةِ، فَإنَّ الأئِمَّةَ مِن قُرَيْشٍ. وثانِيها: أنَّهُ مَأْخُوذٌ مِنَ القِرْشِ وهو الكَسْبُ لِأنَّهم كانُوا كاسِبِينَ بِتِجاراتِهِمْ وضَرْبِهِمْ في البِلادِ. وثالِثُها: قالَ اللَّيْثُ: كانُوا مُتَفَرِّقِينَ في غَيْرِ الحَرَمِ، فَجَمَعَهم قُصَيُّ بْنُ كِلابٍ في الحَرَمِ حَتّى اتَّخَذُوها مَسْكَنًا، فَسَمُّوها قُرَيْشًا لِأنَّ التَّقَرُّشَ هو التَّجَمُّعُ، يُقالُ: تَقَرَّشَ القَوْمُ إذا اجْتَمَعُوا، ولِذَلِكَ سُمِّيَ قُصَيٌّ مُجَمِّعًا، قالَ الشّاعِرُ: أبُوكم قُصَيٌّ كانَ يُدْعى مُجَمِّعًا ∗∗∗ بِهِ جَمَّعَ اللَّهُ القَبائِلَ مِن فِهْرِ ورابِعُها: أنَّهم كانُوا يَسُدُّونَ خَلَّةَ مَحاوِيجِ الحاجِّ، فَسُمُّوا بِذَلِكَ قُرَيْشًا، لِأنَّ القِرْشَ التَّفْتِيشُ قالَ ابْنُ حُرَّةَ: أيُّها الشّامِتُ المُقَرِّشُ عَنّا ∗∗∗ عِنْدَ عَمْرٍو وهَلْ لِذاكَ بَقاءُ قَوْلُهُ تَعالى: ﴿رِحْلَةَ الشِّتاءِ والصَّيْفِ﴾ فِيهِ مَسائِلُ: المَسْألَةُ الأُولى: قالَ اللَّيْثُ: الرِّحْلَةُ اسْمُ الِارْتِحالِ مِنَ القَوْمِ لِلْمَسِيرِ، وفي المُرادِ مِن هَذِهِ الرِّحْلَةِ قَوْلانِ: الأوَّلُ: وهو المَشْهُورُ، قالَ المُفَسِّرُونَ: كانَتْ لِقُرَيْشٍ رِحْلَتانِ رِحْلَةٌ بِالشِّتاءِ إلى اليَمَنِ لِأنَّ اليَمَنَ أدْفَأُ وبِالصَّيْفِ إلى الشَّأْمِ، وذَكَرَ عَطاءٌ عَنِ ابْنِ عَبّاسٍ أنَّ السَّبَبَ في ذَلِكَ هو أنَّ قُرَيْشًا إذا أصابَ واحِدًا مِنهم مَخْمَصَةٌ خَرَجَ هو وعِيالُهُ إلى مَوْضِعٍ وضَرَبُوا عَلى أنْفُسِهِمْ خِباءً حَتّى يَمُوتُوا، إلى أنْ جاءَ هاشِمُ بْنُ عَبْدِ مَنافٍ، وكانَ سَيِّدَ قَوْمِهِ، وكانَ لَهُ ابْنٌ يُقالُ لَهُ: أسَدٌ، وكانَ لَهُ تِرْبٌ مِن بَنِي مَخْزُومٍ يُحِبُّهُ ويَلْعَبُ مَعَهُ فَشَكا إلَيْهِ الضَّرَرَ والمَجاعَةَ فَدَخَلَ أسَدٌ عَلى أُمِّهِ يَبْكِي فَأرْسَلَتْ إلى أُولَئِكَ بِدَقِيقٍ وشَحْمٍ فَعاشُوا فِيهِ أيّامًا، ثُمَّ أتى تِرْبُ أسَدٍ إلَيْهِ مَرَّةً أُخْرى وشَكا إلَيْهِ مِنَ الجُوعِ فَقامَ هاشِمٌ خَطِيبًا في قُرَيْشٍ، فَقالَ: إنَّكم أجْدَبْتُمْ جَدْبًا تُقِلُّونَ فِيهِ وتَذِلُّونَ، وأنْتُمْ أهْلُ حَرَمِ اللَّهِ وأشْرافُ ولَدِ آدَمَ والنّاسُ لَكم تَبَعٌ. قالُوا: نَحْنُ تَبَعٌ لَكَ فَلَيْسَ عَلَيْكَ مِنّا خِلافٌ فَجَمَعَ كُلَّ بَنِي أبٍ عَلى الرِّحْلَتَيْنِ في الشِّتاءِ إلى اليَمَنِ وفي الصَّيْفِ إلى الشّامِ لِلتِّجاراتِ، فَما رَبِحَ الغَنِيُّ قَسَمَهُ بَيْنَهُ وبَيْنَ الفَقِيرِ حَتّى كانَ فَقِيرُهم كَغَنِيِّهِمْ، فَجاءَ الإسْلامُ وهم عَلى ذَلِكَ، فَلَمْ يَكُنْ في العَرَبِ بَنُو أبٍ أكْثَرَ مالًا ولا أعَزَّ مِن قُرَيْشٍ، قالَ الشّاعِرُ فِيهِمْ: الخالِطِينَ فَقِيرَهم بِغَنِيِّهِمْ ∗∗∗ حَتّى يَكُونَ فَقِيرُهم كالكافِي واعْلَمْ أنَّ وجْهَ النِّعْمَةِ والمِنَّةِ فِيهِ أنَّهُ لَوْ تَمَّ لِأصْحابِ الفِيلِ ما أرادُوا، لَتَرَكَ أهْلُ الأقْطارِ تَعْظِيمَهم وأيْضًا لَتَفَرَّقُوا وصارَ حالُهم كَحالِ اليَهُودِ المَذْكُورِينَ في قَوْلِهِ: ﴿وقَطَّعْناهم في الأرْضِ أُمَمًا﴾ [الأعراف: ١٦٨] واجْتِماعُ القَبِيلَةِ الواحِدَةِ في مَكانٍ واحِدٍ أدْخَلُ في النِّعْمَةِ مِن أنْ يَكُونَ الِاجْتِماعُ مِن قَبائِلَ شَتّى، ونَبَّهَ تَعالى أنَّ مِن شَرْطِ السَّفَرِ المُؤانَسَةَ والأُلْفَةَ، ومِنهُ قَوْلُهُ تَعالى: ﴿ولا جِدالَ في الحَجِّ﴾ [ البَقَرَةِ: ١٩٧] والسَّفَرُ أحْوَجُ إلى مَكارِمِ الأخْلاقِ مِنَ الإقامَةِ. القَوْلُ الثّانِي: أنَّ المُرادَ رِحْلَةُ النّاسِ إلى أهْلِ مَكَّةَ، فَرِحْلَةُ الشِّتاءِ والصَّيْفِ عُمْرَةُ رَجَبٍ وحَجُّ ذِي الحِجَّةِ لِأنَّهُ كانَ أحَدُهُما شِتاءً والآخَرُ صَيْفًا، ومَوْسِمُ مَنافِعِ مَكَّةَ يَكُونُ بِهِما، ولَوْ كانَ يَتِمُّ لِأصْحابِ الفِيلِ ما أرادُوا لَتَعَطَّلَتْ هَذِهِ المَنفَعَةُ. المَسْألَةُ الثّانِيَةُ: نَصْبُ الرِّحْلَةِ بِإيلافِهِمْ مَفْعُولًا بِهِ، وأرادَ رِحْلَتَيِ الشِّتاءِ والصَّيْفِ، فَأفْرَدَ لِأمْنِ الإلْباسِ كَقَوْلِهِ: كُلُوا في بَعْضِ بَطْنِكم، وقِيلَ: مَعْناهُ رِحْلَةُ الشِّتاءِ ورِحْلَةُ الصَّيْفِ، وقُرِئَ ”رِحْلَةُ“ بِضَمِّ الرّاءِ وهي الجِهَةُ.',     source_page = '97',     updated_at  = datetime('now') WHERE id = 'QR:TE:dfeae422456266558513a095';
UPDATE qr_tafsir_entries SET content_ar = 'ثُمَّ قالَ تَعالى: ﴿الَّذِي أطْعَمَهم مِن جُوعٍ﴾ وفي هَذا الإطْعامِ وُجُوهٌ: أحَدُها: أنَّهُ تَعالى لَمّا آمَنَهم بِالحَرَمِ حَتّى لا يَتَعَرَّضَ لَهم في رِحْلَتَيْهِمْ كانَ ذَلِكَ سَبَبَ إطْعامِهِمْ بَعْدَما كانُوا فِيهِ مِنَ الجُوعِ. ثانِيها: قالَ مُقاتِلٌ: شَقَّ عَلَيْهِمُ الذَّهابُ إلى اليَمَنِ والشّامِ في الشِّتاءِ والصَّيْفِ لِطَلَبِ الرِّزْقِ، فَقَذَفَ اللَّهُ تَعالى في قُلُوبِ الحَبَشَةِ أنْ يَحْمِلُوا الطَّعامَ في السُّفُنِ إلى مَكَّةَ فَحَمَلُوهُ، وجَعَلَ أهْلُ مَكَّةَ يَخْرُجُونَ إلَيْهِمْ بِالإبِلِ والخَمْرِ، ويَشْتَرُونَ طَعامَهم مِن جُدَّةَ عَلى مَسِيرَةِ لَيْلَتَيْنِ وتَتابَعَ ذَلِكَ، فَكَفاهُمُ اللَّهُ مَؤُونَةَ الرِّحْلَتَيْنِ. ثالِثُها: قالَ الكَلْبِيُّ: هَذِهِ الآيَةُ مَعْناها أنَّهم لَمّا كَذَّبُوا مُحَمَّدًا ﷺ دَعا عَلَيْهِمْ، فَقالَ: «اللَّهُمَّ اجْعَلْها عَلَيْهِمْ سِنِينَ كَسِنِي يُوسُفَ فاشْتَدَّ عَلَيْهِمُ القَحْطُ وأصابَهُمُ الجَهْدُ فَقالُوا: يا مُحَمَّدُ ادْعُ اللَّهَ فَإنّا مُؤْمِنُونَ، فَدَعا رَسُولُ اللَّهِ ﷺ فَأخْصَبَتِ البِلادُ وأخْصَبَ أهْلُ مَكَّةَ بَعْدَ القَحْطِ» ، فَذاكَ قَوْلُهُ: ﴿أطْعَمَهم مِن جُوعٍ﴾ ثُمَّ في الآيَةِ سُؤالاتٌ: السُّؤالُ الأوَّلُ: العِبادَةُ إنَّما وجَبَتْ لِأنَّهُ تَعالى أعْطى أُصُولَ النِّعَمِ، والإطْعامُ لَيْسَ مِن أُصُولِ النِّعَمِ، فَلِماذا عَلَّلَ وُجُوبَ العِبادَةِ بِالإطْعامِ ؟ والجَوابُ: مِن وُجُوهٍ: أحَدُها: أنَّهُ تَعالى لَمّا ذَكَرَ إنْعامَهُ عَلَيْهِمْ بِحَبْسِ الفِيلِ وإرْسالِ الطَّيْرِ وإهْلاكِ الحَبَشَةِ، وبَيَّنَ أنَّهُ تَعالى فَعَلَ ذَلِكَ لِإيلافِهِمْ، ثُمَّ أمَرَهم بِالعِبادَةِ، فَكَأنَّ السّائِلَ يَقُولُ: لَكِنْ نَحْنُ مُحْتاجُونَ إلى كَسْبِ الطَّعامِ والذَّبِّ عَنِ النَّفْسِ، فَلَوِ اشْتَغَلْنا بِالعِبادَةِ فَمَن ذا الَّذِي يُطْعِمُنا ؟ فَقالَ: الَّذِي أطْعَمَهم مِن جُوعٍ، قَبْلَ أنْ يَعْبُدُوهُ، ألا يُطْعِمُهم إذا عَبَدُوهُ. وثانِيها: أنَّهُ تَعالى بَعْدَ أنْ أعْطى العَبْدَ أُصُولَ النِّعَمِ أساءَ العَبْدُ إلَيْهِ، ثُمَّ إنَّهُ يُطْعِمُهم مَعَ ذَلِكَ، فَكَأنَّهُ تَعالى يَقُولُ: إذا لَمْ تَسْتَحِ مِن أُصُولِ النِّعَمِ ألا تَسْتَحِي مِن إحْسانِي إلَيْكَ بَعْدَ إساءَتِكَ ؟ ! وثالِثُها: إنَّما ذَكَرَ الإنْعامَ، لِأنَّ البَهِيمَةَ تُطِيعُ مَن يَعْلِفُها، فَكَأنَّهُ تَعالى يَقُولُ: لَسْتُ دُونَ البَهِيمَةِ. السُّؤالُ الثّانِي: ألَيْسَ أنَّهُ جَعَلَ الدُّنْيا مِلْكًا لَنا بِقَوْلِهِ: ﴿خَلَقَ لَكم ما في الأرْضِ جَمِيعًا﴾ [البقرة: ٢٩] فَكَيْفَ تَحْسُنُ المِنَّةُ عَلَيْنا بِأنْ أعْطانا مِلْكَنا ؟ الجَوابُ: انْظُرْ في الأشْياءِ الَّتِي لا بُدَّ مِنها قَبْلَ الأكْلِ حَتّى يَتِمَّ الطَّعامُ ويَتَهَيَّأ، وفي الأشْياءِ الَّتِي لا بُدَّ مِنها بَعْدَ الأكْلِ حَتّى يَتِمَّ الِانْتِفاعُ بِالطَّعامِ المَأْكُولِ، فَإنَّكَ تَعْلَمُ أنَّهُ لا بُدَّ مِنَ الأفْلاكِ والكَواكِبِ، ولا بُدَّ مِنَ العَناصِرِ الأرْبَعَةِ حَتّى يَتِمَّ ذَلِكَ الطَّعامُ، ولا بُدَّ مِن جُمْلَةِ الأعْضاءِ عَلى اخْتِلافِ أشْكالِها وصُوَرِها حَتّى يَتِمَّ الِانْتِفاعُ بِالطَّعامِ، وحِينَئِذٍ تَعْلَمُ أنَّ الإطْعامَ يُناسِبُ الأمْرَ بِالطّاعَةِ والعِبادَةِ. السُّؤالُ الثّالِثُ: المِنَّةُ بِالإطْعامِ لا تَلِيقُ بِمَن لَهُ شَيْءٌ مِنَ الكَرَمِ، فَكَيْفَ بِأكْرَمِ الأكْرَمِينَ ؟ الجَوابُ: لَيْسَ الغَرَضُ مِنهُ المِنَّةَ، بَلِ الإرْشادَ إلى الأصْلَحِ، لِأنَّهُ لَيْسَ المَقْصُودُ مِنَ الأكْلِ تَقْوِيَةَ الشَّهْوَةِ المانِعَةِ عَنِ الطّاعَةِ، بَلْ تَقْوِيَةَ البِنْيَةِ عَلى أداءِ الطّاعاتِ، فَكَأنَّ المَقْصُودَ مِنَ الأمْرِ بِالعِبادَةِ ذَلِكَ. السُّؤالُ الرّابِعُ: ما الفائِدَةُ في قَوْلِهِ: (مِن جُوعٍ) ؟ الجَوابُ: فِيهِ فَوائِدُ: أحَدُها: التَّنْبِيهُ عَلى أنَّ أمْرَ الجُوعِ شَدِيدٌ، ومِنهُ قَوْلُهُ تَعالى: ﴿وهُوَ الَّذِي يُنَزِّلُ الغَيْثَ مِن بَعْدِ ما قَنَطُوا﴾ [الشورى: ٢٨] وقَوْلُهُ ﷺ: «مَن أصْبَحَ آمِنًا في سِرْبِهِ» الحَدِيثَ. وثانِيها: تَذْكِيرُهُمُ الحالَةَ الأُولى الرَّدِيئَةَ المُؤْلِمَةَ وهي الجُوعُ حَتّى يَعْرِفُوا قَدْرَ النِّعْمَةِ الحاضِرَةِ. وثالِثُها: التَّنْبِيهُ عَلى أنَّ خَيْرَ الطَّعامِ ما سَدَّ الجَوْعَةَ: لِأنَّهُ لَمْ يَقُلْ: وأشْبَعَهم لِأنَّ الطَّعامَ يُزِيلُ الجُوعَ، أمّا الإشْباعُ فَإنَّهُ يُورِثُ البِطْنَةَ. * أمّا قَوْلُهُ تَعالى: ﴿وآمَنَهم مِن خَوْفٍ﴾ فَفي تَفْسِيرِهِ وُجُوهٌ: أحَدُها: أنَّهم كانُوا يُسافِرُونَ آمِنِينَ لا يَتَعَرَّضُ لَهم أحَدٌ، ولا يُغِيرُ عَلَيْهِمْ أحَدٌ لا في سَفَرِهِمْ، ولا في حَضَرِهِمْ، وكانَ غَيْرُهم لا يَأْمَنُونَ مِنَ الغارَةِ في السَّفَرِ والحَضَرِ، وهَذا مَعْنى قَوْلِهِ: ﴿أوَلَمْ يَرَوْا أنّا جَعَلْنا حَرَمًا آمِنًا﴾ [العنكبوت: ٦٧] . ثانِيها: أنَّهُ آمَنَهم مِن زَحْمَةِ أصْحابِ الفِيلِ. وثالِثُها: قالَ الضَّحّاكُ والرَّبِيعُ: وآمَنَهم مِن خَوْفِ الجُذامِ، فَلا يُصِيبُهم بِبَلْدَتِهِمْ الجُذامُ. ورابِعُها: آمَنَهم مِن خَوْفِ أنْ تَكُونَ الخِلافَةُ في غَيْرِهِمْ. وخامِسُها: آمَنَهم بِالإسْلامِ، فَقَدْ كانُوا في الكُفْرِ يَتَفَكَّرُونَ، فَيَعْلَمُونَ أنَّ الدِّينَ الَّذِي هم عَلَيْهِ لَيْسَ بِشَيْءٍ، إلّا أنَّهم ما كانُوا يَعْرِفُونَ الدِّينَ الَّذِي يَجِبُ عَلى العاقِلِ أنْ يَتَمَسَّكَ بِهِ. وسادِسُها: أطْعَمَهم مِن جُوعِ الجَهْلِ بِطَعامِ الوَحْيِ، وآمَنَهم مِن خَوْفِ الضَّلالِ بِبَيانِ الهُدى، كَأنَّهُ تَعالى يَقُولُ: يا أهْلَ مَكَّةَ كُنْتُمْ قَبْلَ مَبْعَثِ مُحَمَّدٍ تُسَمَّوْنَ جُهّالَ العَرَبِ وأجْلافَهم، ومَن كانَ يُنازِعُكم كانُوا يُسَمَّوْنَ أهْلَ الكِتابِ، ثُمَّ أنْزَلْتُ الوَحْيَ عَلى نَبِيِّكم، وعَلَّمْتُكُمُ الكِتابَ والحِكْمَةَ حَتّى صِرْتُمُ الآنَ تُسَمَّوْنَ أهْلَ العِلْمِ والقُرْآنِ، وأُولَئِكَ يُسَمَّوْنَ جُهّالَ اليَهُودِ والنَّصارى، ثُمَّ إطْعامُ الطَّعامِ الَّذِي يَكُونُ غِذاءَ الجَسَدِ يُوجِبُ الشُّكْرَ، فَإطْعامُ الطَّعامِ الَّذِي هو غِذاءُ الرُّوحِ، ألا يَكُونُ مُوجِبًا لِلشُّكْرِ ! وفي الآيَةِ سُؤالاتٌ: السُّؤالُ الأوَّلُ: لِمَ لَمْ يَقُلْ: عَنْ جُوعٍ وعَنْ خَوْفٍ ؟ قُلْنا: لِأنَّ مَعْنى ”عَنْ“ أنَّهُ جَعَلَ الجُوعَ بَعِيدًا عَنْهم، وهَذا يَقْتَضِي أنْ يَكُونَ ذَلِكَ التَّبْعِيدُ مَسْبُوقًا بِمُقاساةِ الجُوعِ زَمانًا، ثُمَّ يَصْرِفُهُ عَنْهُ، و”مِن“ لا تَقْتَضِي ذَلِكَ، بَلْ مَعْناهُ أنَّهم عِنْدَما يَجُوعُونَ يُطْعَمُونَ، وحِينَ ما يَخافُونَ يُؤَمَّنُونَ. السُّؤالُ الثّانِي: لِمَ قالَ: مِن جُوعٍ، مِن خَوْفٍ عَلى سَبِيلِ التَّنْكِيرِ ؟ الجَوابُ: المُرادُ مِنَ التَّنْكِيرِ التَّعْظِيمُ. أمّا الجُوعُ فَلِما رَوَيْنا: أنَّهُ أصابَتْهم شِدَّةٌ حَتّى أكَلُوا الجِيَفَ والعِظامَ المُحْرَقَةَ. وأمّا الخَوْفُ، فَهو الخَوْفُ الشَّدِيدُ الحاصِلُ مِن أصْحابِ الفِيلِ، ويُحْتَمَلُ أنْ يَكُونَ المُرادُ مِنَ التَّنْكِيرِ التَّحْقِيرَ، يَكُونُ المَعْنى أنَّهُ تَعالى لَمّا لَمْ يُجَوِّزْ لِغايَةِ كَرَمِهِ إبْقاءَهم في ذَلِكَ الجُوعِ القَلِيلِ والخَوْفِ القَلِيلِ، فَكَيْفَ يَجُوزُ في كَرَمِهِ لَوْ عَبَدُوهُ أنْ يُهْمِلَ أمْرَهم ؟ ! ويُحْتَمَلُ أنْ يَكُونَ المُرادُ أنَّهُ: ﴿أطْعَمَهم مِن جُوعٍ﴾ دُونَ جُوعٍ ﴿وآمَنَهم مِن خَوْفٍ﴾ دُونَ خَوْفٍ، لِيَكُونَ الجُوعُ الثّانِي، والخَوْفُ الثّانِي مُذَكِّرًا ما كانُوا فِيهِ أوَّلًا مِن أنْواعِ الجُوعِ والخَوْفِ، حَتّى يَكُونُوا شاكِرِينَ مِن وجْهٍ، وصابِرِينَ مِن وجْهٍ آخَرَ، فَيَسْتَحِقُّوا ثَوابَ الخَصْلَتَيْنِ. السُّؤالُ الثّالِثُ: أنَّهُ تَعالى إنَّما أطْعَمَهم وآمَنَهم إجابَةً لِدَعْوَةِ إبْراهِيمَ - عَلَيْهِ الصَّلاةُ والسَّلامُ - أمّا في الإطْعامِ فَهو قَوْلُهُ: ﴿وارْزُقْ أهْلَهُ﴾ [البقرة: ١٢٦] وأمّا الأمانُ فَهو قَوْلُهُ: ﴿اجْعَلْ هَذا البَلَدَ آمِنًا﴾ [إبراهيم: ٣٥] وإذا كانَ كَذَلِكَ كانَ ذَلِكَ مِنَّةً عَلى إبْراهِيمَ عَلَيْهِ السَّلامُ، فَكَيْفَ جَعَلَهُ مِنَّةً عَلى أُولَئِكَ الحاضِرِينَ ؟ والجَوابُ: أنَّ اللَّهَ تَعالى لَمّا قالَ: ﴿إنِّي جاعِلُكَ لِلنّاسِ إمامًا﴾ [البقرة: ١٢٤] قالَ إبْراهِيمُ: ﴿ومِن ذُرِّيَّتِي﴾ [ البَقَرَةِ: ١٢٤] فَقالَ اللَّهُ تَعالى: ﴿لا يَنالُ عَهْدِي الظّالِمِينَ﴾ [البقرة: ١٢٤] فَنادى إبْراهِيمُ بِهَذا الأدَبِ، فَحِينَ قالَ: ﴿رَبِّ اجْعَلْ هَذا بَلَدًا آمِنًا وارْزُقْ أهْلَهُ مِنَ الثَّمَراتِ﴾ [البقرة: ١٢٦] قَيَّدَهُ بِقَوْلِهِ: ﴿مَن آمَنَ مِنهم بِاللَّهِ﴾ [البقرة: ١٢٦] فَقالَ اللَّهُ: لا حاجَةَ إلى هَذا التَّقْيِيدِ، بَلْ ومَن كَفَرَ فَأُمَتِّعُهُ قَلِيلًا، فَكَأنَّهُ تَعالى قالَ: أمّا نِعْمَةُ الأمانِ فَهي دِينِيَّةٌ فَلا تَحْصُلُ إلّا لِمَن كانَ تَقِيًّا، وأمّا نِعْمَةُ الدُّنْيا فَهي تَصِلُ إلى البَرِّ والفاجِرِ والصّالِحِ والطّالِحِ، وإنْ كانَ كَذَلِكَ كانَ إطْعامُ الكافِرِ مِنَ الجُوعِ، وأمانُهُ مِنَ الخَوْفِ إنْعامًا مِنَ اللَّهِ ابْتِداءً عَلَيْهِ لا بِدَعْوَةِ إبْراهِيمَ، فَزالَ السُّؤالُ. واللَّهُ سُبْحانَهُ وتَعالى أعْلَمُ، وصَلّى اللَّهُ عَلى سَيِّدِنا مُحَمَّدٍ وعَلى آلِهِ وصَحْبِهِ وسَلَّمَ.',     source_page = '102',     updated_at  = datetime('now') WHERE id = 'QR:TE:22dc5e576d5012c894a26bdd';
UPDATE qr_tafsir_entries SET content_ar = '(سُورَةُ الماعُونِ) سَبْعُ آياتٍ، مَكِّيَّةٌ ﷽ ﴿أرَأيْتَ الَّذِي يُكَذِّبُ بِالدِّينِ﴾ ﷽ ﴿أرَأيْتَ الَّذِي يُكَذِّبُ بِالدِّينِ﴾ فِيهِ مَسائِلُ: المَسْألَةُ الأُولى: قَرَأ بَعْضُهم ”أرَيْتَ“ بِحَذْفِ الهَمْزَةِ، قالَ الزَّجّاجُ: وهَذا لَيْسَ بِالِاخْتِيارِ، لِأنَّ الهَمْزَةَ إنَّما طُرِحَتْ مِنَ المُسْتَقْبَلِ نَحْوَ يَرى وأرى وتَرى، فَأمّا رَأيْتُ فَلَيْسَ يَصِحُّ عَنِ العَرَبِ فِيها رَيْتُ، ولَكِنَّ حَرْفَ الِاسْتِفْهامِ لَمّا كانَ في أوَّلِ الكَلامِ سَهَّلَ إلْغاءَ الهَمْزَةِ، ونَظِيرُهُ: صاحَ هَلْ رَيْتَ أوْ سَمِعْتَ بِراعٍ رَدَّ في الضَّرْعِ ما قَرى في العِلابِ وقَرَأ ابْنُ مَسْعُودٍ ”أرَأيْتَكَ“ بِزِيادَةِ حَرْفِ الخِطابِ كَقَوْلِهِ: ﴿أرَأيْتَكَ هَذا الَّذِي كَرَّمْتَ عَلَيَّ﴾ [الإسراء: ٦٢] . المَسْألَةُ الثّانِيَةُ: قَوْلُهُ: (أرَأيْتَ) مَعْناهُ هَلْ عَرَفْتَ الَّذِي يُكَذِّبُ بِالجَزاءِ مَن هو، فَإنْ لَمْ تَعْرِفْهُ فَهو: ﴿الَّذِي يَدُعُّ اليَتِيمَ﴾ . واعْلَمْ أنَّ هَذا اللَّفْظَ وإنْ كانَ في صُورَةِ الِاسْتِفْهامِ، لَكِنَّ الغَرَضَ بِمِثْلِهِ المُبالَغَةُ في التَّعَجُّبِ كَقَوْلِكَ: أرَأيْتَ فُلانًا ماذا ارْتَكَبَ ولِماذا عَرَّضَ نَفْسَهُ ؟ ثُمَّ قِيلَ: إنَّهُ خِطابٌ لِلرَّسُولِ ﷺ، وقِيلَ: بَلْ خِطابٌ لِكُلِّ عاقِلٍ أيْ أرَأيْتَ يا عاقِلُ هَذا الَّذِي يُكَذِّبُ بِالدِّينِ بَعْدَ ظُهُورِ دَلائِلِهِ ووُضُوحِ تِبْيانِهِ أيَفْعَلُ ذَلِكَ لا لِغَرَضٍ، فَكَيْفَ يَلِيقُ بِالعاقِلِ جَرُّ العُقُوبَةِ الأبَدِيَّةِ إلى نَفْسِهِ مِن غَيْرِ غَرَضٍ أوْ لِأجْلِ الدُّنْيا، فَكَيْفَ يَلِيقُ بِالعاقِلِ أنْ يَبِيعَ الكَثِيرَ الباقِيَ بِالقَلِيلِ الفانِي. المَسْألَةُ الثّالِثَةُ: في الآيَةِ قَوْلانِ: أحَدُهُما: أنَّها مُخْتَصَّةٌ بِشَخْصٍ مُعَيَّنٍ، وعَلى هَذا القَوْلِ ذَكَرُوا أشْخاصًا، فَقالَ ابْنُ جُرَيْجٍ: نَزَلَتْ في أبِي سُفْيانَ كانَ يَنْحَرُ جَزُورَيْنِ في كُلِّ أُسْبُوعٍ، فَأتاهُ يَتِيمٌ فَسَألَهُ لَحْمًا فَقَرَعَهُ بِعَصاهُ، وقالَ مُقاتِلٌ: نَزَلَتْ في العاصِ بْنِ وائِلٍ السَّهْمِيِّ، وكانَ مِن صِفَتِهِ الجَمْعُ بَيْنَ التَّكْذِيبِ بِيَوْمِ القِيامَةِ والإتْيانِ بِالأفْعالِ القَبِيحَةِ، وقالَ السُّدِّيُّ: نَزَلَتْ في الوَلِيدِ بْنِ المُغِيرَةِ، وحَكى الماوَرْدِيُّ أنَّها نَزَلَتْ في أبِي جَهْلٍ، ورُوِيَ «أنَّهُ كانَ وصِيًّا لِيَتِيمٍ، فَجاءَهُ وهو عُرْيانٌ يَسْألُهُ شَيْئًا مِن مالِ نَفْسِهِ، فَدَفَعَهُ ولَمْ يَعْبَأْ بِهِ فَأيِسَ الصَّبِيُّ، فَقالَ لَهُ أكابِرُ قُرَيْشٍ: قُلْ لِمُحَمَّدٍ يَشْفَعْ لَكَ، وكانَ غَرَضُهُمُ الِاسْتِهْزاءَ ولَمْ يَعْرِفِ اليَتِيمُ ذَلِكَ، فَجاءَ إلى النَّبِيِّ ﷺ والتَمَسَ مِنهُ ذَلِكَ، وهو - عَلَيْهِ الصَّلاةُ والسَّلامُ - ما كانَ يَرُدُّ مُحْتاجًا فَذَهَبَ مَعَهُ إلى أبِي جَهْلٍ فَرَحَّبَ بِهِ وبَذَلَ المالَ لِلْيَتِيمِ فَعَيَّرَهُ قُرَيْشٌ، فَقالُوا: صَبَوْتَ، فَقالَ: لا واللَّهِ ما صَبَوْتُ، لَكِنْ رَأيْتُ عَنْ يَمِينِهِ وعَنْ يَسارِهِ حَرْبَةً خِفْتُ إنْ لَمْ أُجِبْهُ يَطْعَنْها فِيَّ» ، ورُوِيَ عَنِ ابْنِ عَبّاسٍ أنَّها نَزَلَتْ في مُنافِقٍ جَمَعَ بَيْنَ البُخْلِ والمُراءاةِ. والقَوْلُ الثّانِي: أنَّهُ عامٌّ لِكُلِّ مَن كانَ مُكَذِّبًا بِيَوْمِ الدِّينِ، وذَلِكَ لِأنَّ إقْدامَ الإنْسانِ عَلى الطّاعاتِ وإحْجامَهُ عَنِ المَحْظُوراتِ إنَّما يَكُونُ لِلرَّغْبَةِ في الثَّوابِ والرَّهْبَةِ عَنِ العِقابِ، فَإذا كانَ مُنْكِرًا لِلْقِيامَةِ لَمْ يَتْرُكْ شَيْئًا مِنَ المُشْتَهَياتِ واللَّذّاتِ، فَثَبَتَ أنَّ إنْكارَ القِيامَةِ كالأصْلِ لِجَمِيعِ أنْواعِ الكُفْرِ والمَعاصِي. المَسْألَةُ الرّابِعَةُ: في تَفْسِيرِ الدِّينِ وُجُوهٌ: أحَدُها: أنْ يَكُونَ المُرادُ مَن يُكَذِّبُ بِنَفْسِ الدِّينِ والإسْلامِ إمّا لِأنَّهُ كانَ مُنْكِرًا لِلصّانِعِ، أوْ لِأنَّهُ كانَ مُنْكِرًا لِلنُّبُوَّةِ، أوْ لِأنَّهُ كانَ مُنْكِرًا لِلْمَعادِ أوْ لِشَيْءٍ مِنَ الشَّرائِعِ، فَإنْ قِيلَ: كَيْفَ يُمْكِنُ حَمْلُهُ عَلى هَذا الوَجْهِ، ولا بُدَّ وأنْ يَكُونَ لِكُلِّ أحَدٍ دِينٌ ؟ والجَوابُ: مِن وُجُوهٍ: أحَدُها: أنَّ الدِّينَ المُطْلَقَ في اصْطِلاحِ أهْلِ الإسْلامِ والقُرْآنِ هو الإسْلامُ قالَ اللَّهُ تَعالى: ﴿إنَّ الدِّينَ عِنْدَ اللَّهِ الإسْلامُ﴾ [آل عمران: ١٩] أمّا سائِرُ المَذاهِبِ فَلا تُسَمّى دِينًا إلّا بِضَرْبٍ مِنَ التَّقْيِيدِ كَدِينِ النَّصارى واليَهُودِ. وثانِيها: أنْ يُقالَ: هَذِهِ المَقالاتُ الباطِلَةُ لَيْسَتْ بِدِينٍ، لِأنَّ الدِّينَ هو الخُضُوعُ لِلَّهِ وهَذِهِ المَذاهِبُ إنَّما هي خُضُوعٌ لِلشَّهْوَةِ أوْ لِلشُّبْهَةِ. وثالِثُها: وهو قَوْلُ أكْثَرِ المُفَسِّرِينَ: أنَّ المُرادَ أرَأيْتَ الَّذِي يُكَذِّبُ بِالحِسابِ والجَزاءِ، قالُوا: وحَمْلُهُ عَلى هَذا الوَجْهِ أوْلى لِأنَّ مَن يُنْكِرُ الإسْلامَ قَدْ يَأْتِي بِالأفْعالِ الحَمِيدَةِ ويَحْتَرِزُ عَنْ مَقابِحِها إذا كانَ مُقِرًّا بِالقِيامَةِ والبَعْثِ، أمّا المُقْدِمُ عَلى كُلِّ قَبِيحٍ مِن غَيْرِ مُبالاةٍ فَلَيْسَ هو إلّا المُنْكِرَ لِلْبَعْثِ والقِيامَةِ.',     source_page = '104',     updated_at  = datetime('now') WHERE id = 'QR:TE:6191729abf89cfeaa4d185f3';
UPDATE qr_tafsir_entries SET content_ar = 'ثُمَّ قالَ تَعالى: ﴿فَذَلِكَ الَّذِي يَدُعُّ اليَتِيمَ﴾ ﴿ولا يَحُضُّ عَلى طَعامِ المِسْكِينِ﴾ . واعْلَمْ أنَّهُ تَعالى ذَكَرَ في تَعْرِيفِ مَن يُكَذِّبُ بِالدِّينِ وصْفَيْنِ: أحَدُهُما: مِن بابِ الأفْعالِ وهو قَوْلُهُ: ﴿فَذَلِكَ الَّذِي يَدُعُّ اليَتِيمَ﴾ . والثّانِي: مِن بابِ التُّرُوكِ وهو قَوْلُهُ: ﴿ولا يَحُضُّ عَلى طَعامِ المِسْكِينِ﴾ والفاءُ في قَوْلِهِ ”فَذَلِكَ“ لِلسَّبَبِيَّةِ أيْ لَمّا كانَ كافِرًا مُكَذِّبًا كانَ كُفْرُهُ سَبَبًا لِدَعِّ اليَتِيمِ، وإنَّما اقْتَصَرَ عَلَيْهِما عَلى مَعْنى أنَّ الصّادِرَ عَمَّنْ يُكَذِّبُ بِالدِّينِ لَيْسَ إلّا ذَلِكَ، لِأنّا نَعْلَمُ أنَّ المُكَذِّبَ بِالدِّينِ لا يَقْتَصِرُ عَلى هَذَيْنِ بَلْ عَلى سَبِيلِ التَّمْثِيلِ، كَأنَّهُ تَعالى ذَكَرَ في كُلِّ واحِدٍ مِنَ القِسْمَيْنِ مِثالًا واحِدًا تَنْبِيهًا بِذِكْرِهِ عَلى سائِرِ القَبائِحِ، أوْ لِأجْلِ أنَّ هاتَيْنِ الخَصْلَتَيْنِ، كَما أنَّهُما قَبِيحانِ مُنْكَرانِ بِحَسَبِ الشَّرْعِ فَهُما أيْضًا مُسْتَنْكَرانِ بِحَسَبِ المُرُوءَةِ والإنْسانِيَّةِ، أمّا قَوْلُهُ: ﴿يَدُعُّ اليَتِيمَ﴾ فالمَعْنى أنَّهُ يَدْفَعُهُ بِعُنْفٍ وجَفْوَةٍ كَقَوْلِهِ: ﴿يَوْمَ يُدَعُّونَ إلى نارِ جَهَنَّمَ دَعًّا﴾ [الطور: ١٣] وحاصِلُ الأمْرِ في دَعِّ اليَتِيمِ أُمُورٌ: أحَدُها: دَفْعُهُ عَنْ حَقِّهِ ومالِهِ بِالظُّلْمِ. والثّانِي: تَرْكُ المُواساةِ مَعَهُ، وإنْ لَمْ تَكُنِ المُواساةُ واجِبَةً. وقَدْ يُذَمُّ المَرْءُ بِتَرْكِ النَّوافِلِ لا سِيَّما إذا أُسْنِدَ إلى النِّفاقِ وعَدَمِ الدِّينِ. والثّالِثُ: يَزْجُرُهُ ويَضْرِبُهُ ويَسْتَخِفُّ بِهِ، وقُرِئَ ”يَدَعُ“ أيْ يَتْرُكُهُ، ولا يَدْعُوهُ بِدَعْوَةٍ، أيْ يَدْعُوا جَمِيعَ الأجانِبِ ويَتْرُكُ اليَتِيمَ مَعَ أنَّهُ - عَلَيْهِ الصَّلاةُ والسَّلامُ - قالَ: «ما مِن مائِدَةٍ أعْظَمُ مِن مائِدَةٍ عَلَيْها يَتِيمٌ» وقُرِئَ ”يَدْعُو اليَتِيمَ“ أيْ يَدْعُوهُ رِياءً ثُمَّ لا يُطْعِمُهُ وإنَّما يَدْعُوهُ اسْتِخْدامًا أوْ قَهْرًا أوِ اسْتِطالَةً. واعْلَمْ أنَّ في قَوْلِهِ: (يَدُعُّ) بِالتَّشْدِيدِ فائِدَةً، وهي أنَّ ”يَدُعُّ“ بِالتَّشْدِيدِ مَعْناهُ أنَّهُ يَعْتادُ ذَلِكَ فَلا يَتَناوَلُ الوَعِيدَ مَن وُجِدَ مِنهُ ذَلِكَ ونَدِمَ عَلَيْهِ، ومِثْلُهُ قَوْلُهُ تَعالى: ﴿الَّذِينَ يَجْتَنِبُونَ كَبائِرَ الإثْمِ والفَواحِشَ إلّا اللَّمَمَ﴾ [النجم: ٣٢] سُمِّيَ ذَنْبُ المُؤْمِنِ لَمَمًا لِأنَّهُ كالطَّيْفِ والخَيالِ يَطْرَأُ ولا يَبْقى، لِأنَّ المُؤْمِنَ كَما يَفْرُغُ مِنَ الذَّنْبِ يَنْدَمُ، إنَّما المُكَذِّبُ هو الَّذِي يُصِرُّ عَلى الذَّنْبِ. أمّا قَوْلُهُ: ﴿ولا يَحُضُّ عَلى طَعامِ المِسْكِينِ﴾ فَفِيهِ وجْهانِ: أحَدُهُما: أنَّهُ لا يَحُضُّ نَفْسَهُ عَلى طَعامِ المِسْكِينِ، وإضافَةُ الطَّعامِ إلى المِسْكِينِ تَدُلُّ عَلى أنَّ ذَلِكَ الطَّعامَ حَقُّ المِسْكِينِ، فَكَأنَّهُ مَنَعَ المِسْكِينَ مِمّا هو حَقُّهُ، وذَلِكَ يَدُلُّ عَلى نِهايَةِ بُخْلِهِ وقَساوَةِ قَلْبِهِ وخَساسَةِ طَبْعِهِ. والثّانِي: لا يَحُضُّ غَيْرَهُ عَلى إطْعامِ ذَلِكَ المِسْكِينِ بِسَبَبِ أنَّهُ لا يَعْتَقِدُ في ذَلِكَ الفِعْلِ ثَوابًا، والحاصِلُ أنَّهُ تَعالى جَعَلَ عِلْمَ التَّكْذِيبِ بِالقِيامَةِ الإقْدامَ عَلى إيذاءِ الضَّعِيفِ ومَنعَ المَعْرُوفِ، يَعْنِي أنَّهُ لَوْ آمَنَ بِالجَزاءِ وأيْقَنَ بِالوَعِيدِ لَما صَدَرَ عَنْهُ ذَلِكَ، فَمَوْضِعُ الذَّنْبِ هو التَّكْذِيبُ بِالقِيامَةِ، وهَهُنا سُؤالانِ: السُّؤالُ الأوَّلُ: ألَيْسَ قَدْ لا يَحُضُّ المَرْءُ في كَثِيرٍ مِنَ الأحْوالِ ولا يَكُونُ آثِمًا ؟ الجَوابُ: لِأنَّ غَيْرَهُ يَنُوبُ مَنابَهُ أوْ لِأنَّهُ لا يُقْبَلُ قَوْلُهُ أوْ لِمَفْسَدَةٍ أُخْرى يَتَوَقَّعُها، أمّا هَهُنا فَذَكَرَ أنَّهُ لا يَفْعَلُ ذَلِكَ (إلّا) لِما أنَّهُ مُكَذِّبٌ بِالدِّينِ. السُّؤالُ الثّانِي: لِمَ لَمْ يَقُلْ: ولا يُطْعِمُ المِسْكِينَ ؟ والجَوابُ: إذا مَنَعَ اليَتِيمَ حَقَّهُ فَكَيْفَ يُطْعِمُ المِسْكِينَ مِن مالِ نَفْسِهِ، بَلْ هو بَخِيلٌ مِن مالِ غَيْرِهِ، وهَذا هو النِّهايَةُ في الخِسَّةِ، فَلِأنْ يَكُونَ بَخِيلًا بِمالِ نَفْسِهِ أوْلى، وضِدُّهُ في مَدْحِ المُؤْمِنِينَ: ﴿وتَواصَوْا بِالمَرْحَمَةِ﴾ ] البَلَدِ: ١٧ ]، ﴿وتَواصَوْا بِالحَقِّ﴾ [العصر: ٣] ، ﴿وتَواصَوْا بِالصَّبْرِ﴾ . [العصر: ٣] ﴿فَوَيْلٌ لِلْمُصَلِّينَ﴾ ﴿الَّذِينَ هم عَنْ صَلاتِهِمْ ساهُونَ﴾ * * * ثُمَّ قالَ تَعالى: ﴿فَوَيْلٌ لِلْمُصَلِّينَ﴾ ﴿الَّذِينَ هم عَنْ صَلاتِهِمْ ساهُونَ﴾ وفِيهِ مَسائِلُ: المَسْألَةُ الأُولى: في كَيْفِيَّةِ اتِّصالِ هَذِهِ الآيَةِ بِما قَبْلَها وُجُوهٌ: أحَدُها: أنَّهُ لا يَفْعَلُ إيذاءَ اليَتِيمِ والمَنعَ مِنَ الإطْعامِ دَلِيلًا عَلى النِّفاقِ، فالصَّلاةُ لا مَعَ الخُضُوعِ، والخُضُوعُ أوْلى، أنْ تَدُلَّ عَلى النِّفاقِ؛ لِأنَّ الإيذاءَ والمَنعَ مِنَ النَّفْعِ مُعامَلَةٌ مَعَ المَخْلُوقِ، أمّا الصَّلاةُ فَإنَّها خِدْمَةٌ لِلْخالِقِ. وثانِيها: كَأنَّهُ لَمّا ذَكَرَ إيذاءَ اليَتِيمِ وتَرْكَهُ لِلْحَضِّ كَأنَّ سائِلًا قالَ: ألَيْسَ إنَّ الصَّلاةَ تَنْهى عَنِ الفَحْشاءِ والمُنْكَرِ ؟ فَقالَ لَهُ: الصَّلاةُ كَيْفَ تَنْهاهُ عَنْ هَذا الفِعْلِ المُنْكَرِ وهي مَصْنُوعَةٌ مِن عَيْنِ الرِّياءِ والسَّهْوِ. وثالِثُها: كَأنَّهُ يَقُولُ: إقْدامُهُ عَلى إيذاءِ اليَتِيمِ وتَرْكُهُ لِلْحَضِّ، تَقْصِيرٌ فِيما يَرْجِعُ إلى الشَّفَقَةِ عَلى خَلْقِ اللَّهِ، وسَهْوُهُ في الصَّلاةِ تَقْصِيرٌ فِيما يَرْجِعُ إلى التَّعْظِيمِ لِأمْرِ اللَّهِ، فَلَمّا وقَعَ التَّقْصِيرُ في الأمْرَيْنِ فَقَدْ كَمُلَتْ شَقاوَتُهُ: فَلِهَذا قالَ: (فَوَيْلٌ) واعْلَمْ أنَّ هَذا اللَّفْظَ إنَّما يُسْتَعْمَلُ عِنْدَ الجَرِيمَةِ الشَّدِيدَةِ كَقَوْلِهِ: ﴿ويْلٌ لِلْمُطَفِّفِينَ﴾ [المطففين: ١] ﴿فَوَيْلٌ لَهم مِمّا كَتَبَتْ أيْدِيهِمْ﴾ [البقرة: ٧٩] ، ﴿ويْلٌ لِكُلِّ هُمَزَةٍ لُمَزَةٍ﴾ [الهمزة: ١] ويُرْوى أنَّ كُلَّ أحَدٍ يَنُوحُ في النّارِ بِحَسَبِ جَرِيمَتِهِ، فَقائِلٌ يَقُولُ: ويْلِي مِن حُبِّ الشَّرَفِ، وآخَرُ يَقُولُ: ويْلِي مِنَ الحَمِيَّةِ الجاهِلِيَّةِ، وآخَرُ يَقُولُ: ويْلِي مِن صَلاتِي، فَلِهَذا يُسْتَحَبُّ عِنْدَ سَماعِ مِثْلِ هَذِهِ الآيَةِ، أنْ يَقُولَ المَرْءُ ويْلِي إنْ لَمْ يُغْفَرْ لِي. المَسْألَةُ الثّانِيَةُ: الآيَةُ دالَّةٌ عَلى حُصُولِ التَّهْدِيدِ العَظِيمِ بِفِعْلِ ثَلاثَةِ أُمُورٍ: أحَدُها: السَّهْوُ عَنِ الصَّلاةِ. وثانِيها: فِعْلُ المُراءاةِ. وثالِثُها: مَنعُ الماعُونِ، وكُلُّ ذَلِكَ مِن بابِ الذُّنُوبِ، ولا يَصِيرُ المَرْءُ بِهِ مُنافِقًا، فَلِمَ حَكَمَ اللَّهُ بِمِثْلِ هَذا الوَعِيدِ عَلى فاعِلِ هَذِهِ الأفْعالِ ؟ ولِأجْلِ هَذا الإشْكالِ ذَكَرَ المُفَسِّرُونَ فِيهِ وُجُوهًا: أحَدُها: أنَّ قَوْلَهُ: ﴿فَوَيْلٌ لِلْمُصَلِّينَ﴾ أيْ فَوَيْلٌ لِلْمُصَلِّينَ مِنَ المُنافِقِينَ الَّذِينَ يَأْتُونَ بِهَذِهِ الأفْعالِ، وعَلى هَذا التَّقْدِيرِ تَدُلُّ الآيَةُ عَلى أنَّ الكافِرَ لَهُ مَزِيدُ عُقُوبَةٍ بِسَبَبِ إقْدامِهِ عَلى مَحْظُوراتِ الشَّرْعِ وتَرْكِهِ لِواجِباتِ الشَّرْعِ، وهو يَدُلُّ عَلى صِحَّةِ قَوْلِ الشّافِعِيِّ: إنَّ الكُفّارَ مُخاطَبُونَ بِفُرُوعِ الشَّرائِعِ، وهَذا الجَوابُ هو المُعْتَمَدُ. وثانِيها: ما رَواهُ عَطاءٌ عَنِ ابْنِ عَبّاسٍ أنَّهُ لَوْ قالَ اللَّهُ: في صَلاتِهِمْ ساهُونَ، لَكانَ هَذا الوَعِيدُ في المُؤْمِنِينَ لَكِنَّهُ قالَ: ﴿عَنْ صَلاتِهِمْ ساهُونَ﴾ والسّاهِي عَنِ الصَّلاةِ هو الَّذِي لا يَتَذَكَّرُها ويَكُونُ فارِغًا عَنْها، وهَذا القَوْلُ ضَعِيفٌ لِأنَّ السَّهْوَ عَنِ الصَّلاةِ لا يَجُوزُ أنْ يَكُونَ مُفَسَّرًا بِتَرْكِ الصَّلاةِ، لِأنَّهُ تَعالى أثْبَتَ لَهُمُ الصَّلاةَ بِقَوْلِهِ: ﴿فَوَيْلٌ لِلْمُصَلِّينَ﴾ وأيْضًا فالسَّهْوُ عَنِ الصَّلاةِ بِمَعْنى التَّرْكِ لا يَكُونُ نِفاقًا ولا كُفْرًا فَيَعُودُ الإشْكالُ، ويُمْكِنُ أنْ يُجابَ عَنِ الِاعْتِراضِ الأوَّلِ بِأنَّهُ تَعالى حَكَمَ عَلَيْهِمْ بِكَوْنِهِمْ مُصَلِّينَ نَظَرًا إلى الصُّورَةِ وبِأنَّهم نَسُوا الصَّلاةَ بِالكُلِّيَّةِ نَظَرًا إلى المَعْنى كَما قالَ: ﴿وإذا قامُوا إلى الصَّلاةِ قامُوا كُسالى يُراءُونَ النّاسَ ولا يَذْكُرُونَ اللَّهَ إلّا قَلِيلًا﴾ [النساء: ١٤٢] ويُجابُ عَنِ الِاعْتِراضِ الثّانِي بِأنَّ النِّسْيانَ عَنِ الصَّلاةِ هو أنْ يَبْقى ناسِيًا لِذِكْرِ اللَّهِ في جَمِيعِ أجْزاءِ الصَّلاةِ، وهَذا لا يَصْدُرُ إلّا عَنِ المُنافِقِ الَّذِي يَعْتَقِدُ أنَّهُ لا فائِدَةَ في الصَّلاةِ، أمّا المُسْلِمُ الَّذِي يَعْتَقِدُ فِيها فائِدَةً عَيْنِيَّةً يَمْتَنِعُ أنْ لا يَتَذَكَّرَ أمْرَ الدِّينِ والثَّوابَ والعِقابَ في شَيْءٍ مِن أجْزاءِ الصَّلاةِ، بَلْ قَدْ يَحْصُلُ لَهُ السَّهْوُ في الصَّلاةِ بِمَعْنى أنَّهُ يَصِيرُ ساهِيًا في بَعْضِ أجْزاءِ الصَّلاةِ، فَثَبَتَ أنَّ السَّهْوَ في الصَّلاةِ مِن أفْعالِ المُؤْمِنِ، والسَّهْوَ عَنِ الصَّلاةِ مِن أفْعالِ الكافِرِ. ثالِثُها: أنْ يَكُونَ مَعْنى: (ساهُونَ) أيْ لا يَتَعَهَّدُونَ أوْقاتَ صَلَواتِهِمْ ولا شَرائِطَها، ومَعْناهُ أنَّهُ لا يُبالِي سَواءٌ صَلّى أوْ لَمْ يُصَلِّ، وهو قَوْلُ سَعْدِ بْنِ أبِي وقّاصٍ ومَسْرُوقٍ والحَسَنِ ومُقاتِلٍ. المَسْألَةُ الثّالِثَةُ: اخْتَلَفُوا في سَهْوِ الرَّسُولِ - عَلَيْهِ الصَّلاةُ والسَّلامُ - في صَلاتِهِ، فَقالَ كَثِيرٌ مِنَ العُلَماءِ: إنَّهُ - عَلَيْهِ الصَّلاةُ والسَّلامُ - ما سَها، لَكِنَّ اللَّهَ تَعالى أذِنَ لَهُ في ذَلِكَ الفِعْلِ حَتّى يَفْعَلَ ما يَفْعَلُهُ السّاهِي فَيَصِيرَ ذَلِكَ بَيانًا لِذَلِكَ الشَّرْعِ بِالفِعْلِ، والبَيانُ بِالفِعْلِ أقْوى، ثُمَّ بِتَقْدِيرِ وُقُوعِ السَّهْوِ مِنهُ، فالسَّهْوُ عَلى أقْسامٍ: أحَدُها: سَهْوُ الرَّسُولِ والصَّحابَةِ وذَلِكَ مُنْجَبِرٌ تارَةً بِسُجُودِ السَّهْوِ وتارَةً بِالسُّنَنِ والنَّوافِلِ. والثّانِي: ما يَكُونُ في الصَّلاةِ مِنَ الغَفْلَةِ وعَدَمِ اسْتِحْضارِ المَعارِفِ والنِّيّاتِ. والثّالِثُ: التَّرْكُ لا إلى قَضاءٍ والإخْراجُ عَنِ الوَقْتِ، ومِن ذَلِكَ صَلاةُ المُنافِقِ وهي شَرٌّ مِن تَرْكِ الصَّلاةِ لِأنَّهُ يَسْتَهْزِئُ بِالدِّينِ بِتِلْكَ الصَّلاةِ. أمّا قَوْلُهُ تَعالى: ﴿الَّذِينَ هم يُراءُونَ﴾ فاعْلَمْ أنَّ الفَرْقَ بَيْنَ المُنافِقِ والمُرائِي: أنَّ المُنافِقَ هو المُظْهِرُ لِلْإيمانِ المُبْطِنُ لِلْكُفْرِ، والمُرائِي المُظْهِرُ ما لَيْسَ في قَلْبِهِ مِن زِيادَةِ خُشُوعٍ لِيَعْتَقِدَ فِيهِ مَن يَراهُ أنَّهُ مُتَدَيِّنٌ، أوْ تَقُولُ: المُنافِقُ لا يُصَلِّي سِرًّا والمُرائِي تَكُونُ صَلاتُهُ عِنْدَ النّاسِ أحْسَنَ. اعْلَمْ أنَّهُ يَجِبُ إظْهارُ الفَرائِضِ مِنَ الصَّلاةِ والزَّكاةِ لِأنَّها شَعائِرُ الإسْلامِ، وتارِكُها مُسْتَحِقٌّ لِلَّعْنِ فَيَجِبُ نَفْيُ التُّهْمَةِ بِالإظْهارِ. إنَّما الإخْفاءُ في النَّوافِلِ إلّا إذا أظْهَرَ النَّوافِلَ لِيُقْتَدى بِهِ، وعَنْ بَعْضِهِمْ أنَّهُ رَأى في المَسْجِدِ رَجُلًا يَسْجُدُ لِلشُّكْرِ وأطالَها، فَقالَ: ما أحْسَنَ هَذا لَوْ كانَ في بَيْتِكَ ! لَكِنَّ مَعَ هَذا قالُوا: لا يَتْرُكُ النَّوافِلَ حَياءً ولا يَأْتِي بِها رِياءً، وقَلَّما يَتَيَسَّرُ اجْتِنابُ الرِّياءِ، ولِهَذا قالَ عَلَيْهِ الصَّلاةُ والسَّلامُ: «الرِّياءُ أخْفى مِن دَبِيبِ النَّمْلَةِ السَّوْداءِ في اللَّيْلَةِ الظَّلْماءِ عَلى المَسْحِ الأسْوَدِ» فَإنْ قِيلَ: ما مَعْنى المُراءاةِ ؟ قُلْنا: هي مُفاعَلَةٌ مِنَ الإراءَةِ لِأنَّ المُرائِيَ يُرِي النّاسَ عَمَلَهُ، وهم يُرُونَهُ الثَّناءَ عَلَيْهِ والإعْجابَ بِهِ.',     source_page = '106',     updated_at  = datetime('now') WHERE id = 'QR:TE:63fe8fff639b44addc2597f3';
UPDATE qr_tafsir_entries SET content_ar = 'واعْلَمْ أنَّ قَوْلَهُ: ﴿عَنْ صَلاتِهِمْ ساهُونَ﴾ يُفِيدُ أمْرَيْنِ: إخْراجَها عَنِ الوَقْتِ، وكَوْنَ الإنْسانِ غافِلًا فِيها، قَوْلُهُ: ﴿الَّذِينَ هم يُراءُونَ﴾ يُفِيدُ المُراءاةَ، فَظَهَرَ أنَّ الصَّلاةَ يَجِبُ أنْ تَكُونَ خالِيَةً عَنْ هَذِهِ الأحْوالِ الثَّلاثَةِ. ثُمَّ لَمّا شَرَحَ أمْرَ الصَّلاةِ أعْقَبَهُ بِذِكْرِ الصِّلاتِ فَقالَ: ﴿ويَمْنَعُونَ الماعُونَ﴾ وفِيهِ أقْوالٌ: الأوَّلُ: وهو قَوْلُ أبِي بَكْرٍ وعَلِيٍّ وابْنِ عَبّاسٍ وابْنِ الحَنَفِيَّةِ وابْنِ عَمْرٍو والحَسَنِ وسَعِيدِ بْنِ جُبَيْرٍ وعِكْرِمَةَ وقَتادَةَ والضَّحّاكِ: هو الزَّكاةُ، وفي حَدِيثِ أُبَيٍّ: «مَن قَرَأ سُورَةَ (أرَأيْتَ) غَفَرَ اللَّهُ لَهُ إنْ كانَ لِلزَّكاةِ مُؤَدِّيًا» وذَلِكَ يُوهِمُ أنَّ (الماعُونَ) هو الزَّكاةُ، ولِأنَّ اللَّهَ تَعالى ذَكَرَهُ عَقِيبَ الصَّلاةِ، فالظّاهِرُ أنْ يَكُونَ ذَلِكَ هو الزَّكاةَ. والقَوْلُ الثّانِي: وهو قَوْلُ أكْثَرِ المُفَسِّرِينَ، أنَّ (الماعُونَ) اسْمٌ لِما لا يُمْنَعُ في العادَةِ ويَسْألُهُ الفَقِيرُ والغَنِيُّ، يُنْسَبُ مانِعُهُ إلى سُوءِ الخُلُقِ ولُؤْمِ الطَّبِيعَةِ كالفَأْسِ والقِدْرِ والدَّلْوِ والمِقْدَحَةِ والغِرْبالِ والقَدُّومِ، ويَدْخُلُ فِيهِ المِلْحُ والماءُ والنّارُ. فَإنَّهُ رُوِيَ: «ثَلاثَةٌ لا يَحِلُّ مَنعُها: الماءُ والنّارُ والمِلْحُ» ومِن ذَلِكَ أنْ يَلْتَمِسَ جارُكَ أنْ يَخْبِزَ في تَنُّورِكَ، أوْ يَضَعَ مَتاعَهُ عِنْدَكَ يَوْمًا أوْ نِصْفَ يَوْمٍ، وأصْحابُ هَذا القَوْلِ قالُوا: الماعُونُ فاعُولٌ مِنَ المَعَنِ. وهو الشَّيْءُ القَلِيلُ ومِنهُ ما لَهُ سَعْنَةٌ ولا مَعْنَةٌ أيْ كَثِيرٌ و(لا) قَلِيلٌ، وسُمِّيَتِ الزَّكاةُ ماعُونًا، لِأنَّهُ يُؤْخَذُ مِنَ المالِ رُبُعُ العُشْرِ، فَهو قَلِيلٌ مِن كَثِيرٍ، ويُسَمّى ما يُسْتَعارُ في العُرْفِ كالفَأْسِ والشَّفْرَةِ ماعُونًا، وعَلى هَذا التَّقْدِيرِ يَكُونُ مَعْنى الآيَةِ الزَّجْرَ عَنِ البُخْلِ بِهَذِهِ الأشْياءِ القَلِيلَةِ، فَإنَّ البُخْلَ بِها يَكُونُ في نِهايَةِ الدَّناءَةِ والرَّكاكَةِ، والمُنافِقُونَ كانُوا كَذَلِكَ، لِقَوْلِهِ تَعالى: ﴿الَّذِينَ يَبْخَلُونَ ويَأْمُرُونَ النّاسَ بِالبُخْلِ﴾ [الحديد: ٢٤] وقالَ: ﴿مَنّاعٍ لِلْخَيْرِ مُعْتَدٍ أثِيمٍ﴾ [القلم: ١٢] قالَ العُلَماءُ: ومِنَ الفَضائِلِ أنْ يَسْتَكْثِرَ الرَّجُلُ في مَنزِلِهِ مِمّا يَحْتاجُ إلَيْهِ الجِيرانُ، فَيُعِيرُهم ذَلِكَ ولا يَقْتَصِرُ عَلى الواجِبِ. والقَوْلُ الثّالِثُ: قالَ الفَرّاءُ: سَمِعْتُ بَعْضَ العَرَبِ يَقُولُ: الماعُونُ هو الماءُ وأنْشَدَنِي فِيهِ: يَمُجُّ بَعِيرُهُ الماعُونَ مَجًّا ولَعَلَّهُ خَصَّهُ بِذَلِكَ لِأنَّهُ أعَزُّ مَفْقُودٍ وأرْخَصُ مَوْجُودٍ، وأوَّلُ شَيْءٍ يَسْألُهُ أهْلُ النّارِ الماءُ، كَما قالَ: ﴿أنْ أفِيضُوا عَلَيْنا مِنَ الماءِ﴾ [الأعراف: ٥٠] وأوَّلُ لَذَّةٍ يَجِدُها أهْلُ الجَنَّةِ هو الماءُ، كَما قالَ: ﴿وسَقاهم رَبُّهُمْ﴾ [الإنسان: ٢١] . القَوْلُ الرّابِعُ: (الماعُونَ) حُسْنُ الِانْقِيادِ، يُقالُ: رَضِّ بَعِيرَكَ حَتّى يُعْطِيَكَ الماعُونَ، أيْ حَتّى يُعْطِيَكَ الطّاعَةَ. واعْلَمْ أنَّ الأوْلى أنْ يُحْمَلَ عَلى كُلِّ طاعَةٍ يَخِفُّ فِعْلُها؛ لِأنَّهُ أكْثَرُ فائِدَةً، ثُمَّ قالَ المُحَقِّقُونَ في المُلاءَمَةِ بَيْنَ قَوْلِهِ: (يُراءُونَ) وبَيْنَ قَوْلِهِ: ﴿ويَمْنَعُونَ الماعُونَ﴾ كَأنَّهُ تَعالى يَقُولُ: الصَّلاةُ لِي والماعُونُ لِلْخَلْقِ، فَما يَجِبُ جَعْلُهُ لِي يَعْرِضُونَهُ عَلى الخَلْقِ وما هو حَقُّ الخَلْقِ يَسْتُرُونَهُ عَنْهم فَكَأنَّهُ لا يُعامِلُ الخَلْقَ والرَّبَّ إلّا عَلى العَكْسِ، فَإنْ قِيلَ: لِمَ لَمْ يَذْكُرِ اللَّهُ اسْمَ الكافِرِ بِعَيْنِهِ ؟ فَإنْ قُلْتَ لِلسَّتْرِ عَلَيْهِ، قُلْتُ: لِمَ لَمْ يَسْتُرْ عَلى آدَمَ بَلْ قالَ: ﴿وعَصى آدَمُ رَبَّهُ﴾ ؟ والجَوابُ: أنَّهُ تَعالى ذَكَرَ زَلَّةَ آدَمَ لَكِنْ بَعْدَ مَوْتِهِ مَقْرُونًا بِالتَّوْبَةِ لِيَكُونَ لُطْفًا لِأوْلادِهِ، أنَّهُ أُخْرِجَ مِنَ الجَنَّةِ بِسَبَبِ الصَّغِيرَةِ فَكَيْفَ يَطْمَعُونَ في الدُّخُولِ مَعَ الكَبِيرَةِ ؟ وأيْضًا فَإنَّ وصْفَ تِلْكَ الزَّلَّةِ رِفْعَةٌ لَهُ فَإنَّهُ رَجُلٌ لَمْ يَصْدُرْ عَنْهُ إلّا تَلْكَ الزَّلَّةُ الواحِدَةُ ثُمَّ تابَ عَنْها مِثْلَ هَذِهِ التَّوْبَةِ. ولْنَخْتِمْ تَفْسِيرَ هَذِهِ السُّورَةِ بِالدُّعاءِ: إلَهَنا، هَذِهِ السُّورَةُ في ذِكْرِ المُنافِقِينَ والسُّورَةُ الَّتِي بَعْدَها في صِفَةِ مُحَمَّدٍ ﷺ، فَنَحْنُ وإنْ لَمْ نَصِلْ في الطّاعَةِ إلى مُحَمَّدٍ عَلَيْهِ الصَّلاةُ والسَّلامُ وإلى أصْحابِهِ، لَمْ نَصِلْ في الأفْعالِ القَبِيحَةِ إلى هَؤُلاءِ المُنافِقِينَ، فاعْفُ عَنّا بِفَضْلِكَ يا أرْحَمَ الرّاحِمِينَ، وصَلّى اللَّهُ عَلى سَيِّدِنا مُحَمَّدٍ، وعَلى آلِهِ وصَحِبَهُ وسَلَّمَ.',     source_page = '109',     updated_at  = datetime('now') WHERE id = 'QR:TE:13dcd50963a5151e29c99617';
UPDATE qr_tafsir_entries SET content_ar = '(سُورَةُ الكَوْثَرِ) . ثَلاثٌ آياتٍ، مَكِّيَّةٌ. بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ ﴿إنّا أعْطَيْناكَ الكَوْثَرَ﴾ . بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ ﴿إنّا أعْطَيْناكَ الكَوْثَرَ﴾ . اعْلَمْ أنَّ هَذِهِ السُّورَةَ عَلى اخْتِصارِها فِيها لِطائِفُ: إحْداها: أنَّ هَذِهِ السُّورَةَ كالمُقابِلَةِ لِلسُّورَةِ المُتَقَدِّمَةِ، وذَلِكَ لِأنَّ في السُّورَةِ المُتَقَدِّمَةِ وصَفَ اللَّهُ تَعالى المُنافِقَ بِأُمُورٍ أرْبَعَةٍ: أوَّلُها: البُخْلُ وهو المُرادُ مِن قَوْلِهِ: ﴿يَدُعُّ اليَتِيمَ﴾ ﴿ولا يَحُضُّ عَلى طَعامِ المِسْكِينِ﴾ [الماعون: ٣] . الثّانِي: تَرْكُ الصَّلاةِ وهو المُرادُ مِن قَوْلِهِ: ﴿الَّذِينَ هم عَنْ صَلاتِهِمْ ساهُونَ﴾ [الماعون: ٥] . والثّالِثُ: المُرَآةُ في الصَّلاةِ وهو المُرادُ مِن قَوْلِهِ: ﴿الَّذِينَ هم يُراءُونَ﴾ [الماعون: ٦] . والرّابِعُ: المَنعُ مِنَ الزَّكاةِ وهو المُرادُ مِن قَوْلِهِ: ﴿ويَمْنَعُونَ الماعُونَ﴾ [الماعون: ٧] فَذَكَرَ في هَذِهِ السُّورَةِ في مُقابَلَةِ تِلْكَ الصِّفاتِ الأرْبَعِ صِفاتٍ أرْبَعَةً، فَذَكَرَ في مُقابَلَةِ البُخْلِ قَوْلَهُ: ﴿إنّا أعْطَيْناكَ الكَوْثَرَ﴾ أيْ إنّا أعْطَيْناكَ الكَثِيرَ، فَأعْطِ أنْتَ الكَثِيرَ ولا تَبْخَلْ، وذَكَرَ في مُقابَلَةِ: ﴿الَّذِينَ هم عَنْ صَلاتِهِمْ ساهُونَ﴾ [الماعون: ٥] قَوْلَهُ: (فَصَلِّ) أيْ دُمْ عَلى الصَّلاةِ، وذَكَرَ في مُقابَلَةِ: ﴿الَّذِينَ هم يُراءُونَ﴾ قَوْلَهُ: (لِرَبِّكَ) أيِ ائْتِ بِالصَّلاةِ لِرِضا رَبِّكَ، لا لِمُراءاةِ النّاسِ، وذَكَرَ في مُقابَلَةِ: ﴿ويَمْنَعُونَ الماعُونَ﴾ قَوْلَهُ: (وانْحَرْ) وأرادَ بِهِ التَّصَدُّقَ بِلَحْمِ الأضاحِيِّ، فاعْتَبِرْ هَذِهِ المُناسَبَةَ العَجِيبَةَ، ثُمَّ خَتَمَ السُّورَةَ بِقَوْلِهِ: ﴿إنَّ شانِئَكَ هو الأبْتَرُ﴾ أيِ المُنافِقُ الَّذِي يَأْتِي بِتِلْكَ الأفْعالِ القَبِيحَةِ المَذْكُورَةِ في تِلْكَ السُّورَةِ سَيَمُوتُ ولا يَبْقى مِن دُنْياهُ أثَرٌ ولا خَبَرٌ، وأمّا أنْتَ فَيَبْقى لَكَ في الدُّنْيا الذِّكْرُ الجَمِيلُ، وفي الآخِرَةِ الثَّوابُ الجَزِيلُ. والوَجْهُ الثّانِي: في لَطائِفِ هَذِهِ السُّورَةِ أنَّ السّالِكِينَ إلى اللَّهِ تَعالى لَهم ثَلاثُ دَرَجاتٍ: أعْلاها: أنْ يَكُونُوا مُسْتَغْرِقِينَ بِقُلُوبِهِمْ وأرْواحِهِمْ في نُورِ جَلالِ اللَّهِ. وثانِيها: أنْ يَكُونُوا مُشْتَغِلِينَ بِالطّاعاتِ والعِباداتِ البَدَنِيَّةِ. وثالِثُها: أنْ يَكُونُوا في مَقامِ مَنعِ النَّفْسِ عَنِ الِانْصِبابِ إلى اللَّذّاتِ المَحْسُوسَةِ والشَّهَواتِ العاجِلَةِ، فَقَوْلُهُ: ﴿إنّا أعْطَيْناكَ الكَوْثَرَ﴾ إشارَةٌ إلى المَقامِ الأوَّلِ وهو كَوْنُ رُوحِهِ القُدُسِيَّةِ مُتَمَيِّزَةً عَنْ سائِرِ الأرْواحِ البَشَرِيَّةِ بِالكَمِّ والكَيْفِ، أمّا بِالكَمِّ فَلِأنَّها أكْثَرُ مُقَدِّماتٍ، وأمّا بِالكَيْفِ فَلِأنَّها أسْرَعُ انْتِقالًا مِن تِلْكَ المُقَدِّماتِ إلى النَّتائِجِ مِن سائِرِ الأرْواحِ، وأمّا قَوْلُهُ: ﴿فَصَلِّ لِرَبِّكَ﴾ فَهو إشارَةٌ إلى المَرْتَبَةِ الثّانِيَةِ، وقَوْلُهُ: (وانْحَرْ) إشارَةٌ إلى المَرْتَبَةِ الثّالِثَةِ، فَإنَّ مَنعَ النَّفْسِ عَنِ اللَّذّاتِ العاجِلَةِ جارٍ مُجْرى النَّحْرِ والذَّبْحِ، ثُمَّ قالَ: ﴿إنَّ شانِئَكَ هو الأبْتَرُ﴾ ومَعْناهُ أنَّ النَّفْسَ الَّتِي تَدْعُوكَ إلى طَلَبِ هَذِهِ المَحْسُوساتِ والشَّهَواتِ العاجِلَةِ، أنَّها دائِرَةٌ فانِيَةٌ، وإنَّما الباقِياتُ الصّالِحاتُ خَيْرٌ عِنْدَ رَبِّكَ، وهي السَّعاداتُ الرُّوحانِيَّةُ والمَعارِفُ الرَّبّانِيَّةُ الَّتِي هي باقِيَةٌ أبَدِيَّةٌ، ولْنَشْرَعِ الآنَ في التَّفْسِيرِ. قَوْلُهُ تَعالى: ﴿إنّا أعْطَيْناكَ الكَوْثَرَ﴾ اعْلَمْ أنَّ فِيهِ فَوائِدَ: الفائِدَةُ الأُولى: أنَّ هَذِهِ السُّورَةَ كالتَّتِمَّةِ لِما قَبْلَها مِنَ السُّوَرِ، وكالأصْلِ لِما بَعْدَها مِنَ السُّوَرِ أمّا أنَّها كالتَّتِمَّةِ لِما قَبْلَها مِنَ السُّوَرِ؛ فَلِأنَّ اللَّهَ تَعالى جَعَلَ سُورَةَ: (والضُّحى) في مَدْحِ مُحَمَّدٍ عَلَيْهِ الصَّلاةُ والسَّلامُ وتَفْصِيلِ أحْوالِهِ، فَذَكَرَ في أوَّلِ السُّورَةِ ثَلاثَةَ أشْياءَ تَتَعَلَّقُ بِنُبُوَّتِهِ: أوَّلُها: قَوْلُهُ: ﴿ما ودَّعَكَ رَبُّكَ وما قَلى﴾ [الضحى: ٢] . وثانِيها: قَوْلُهُ: ﴿ولَلْآخِرَةُ خَيْرٌ لَكَ مِنَ الأُولى﴾ [الضحى: ٣] . وثالِثُها: ﴿ولَسَوْفَ يُعْطِيكَ رَبُّكَ فَتَرْضى﴾ [الضحى: ٤] ثُمَّ خَتَمَ هَذِهِ السُّورَةَ بِذِكْرِ ثَلاثَةِ أحْوالٍ مِن أحْوالِهِ عَلَيْهِ السَّلامُ فِيما يَتَعَلَّقُ بِالدُّنْيا وهي قَوْلُهُ: ( ﴿ألَمْ يَجِدْكَ يَتِيمًا فَآوى﴾ ﴿ووَجَدَكَ ضالًّا فَهَدى﴾ ﴿ووَجَدَكَ عائِلًا فَأغْنى﴾ . [الضحى: ٦] . ثُمَّ ذَكَرَ في سُورَةِ: (ألَمْ نَشْرَحْ) أنَّهُ شَرَّفَهُ بِثَلاثَةِ أشْياءَ: أوَّلُها: ﴿ألَمْ نَشْرَحْ لَكَ صَدْرَكَ﴾ [الشرح: ١] . وثانِيها: ﴿ووَضَعْنا عَنْكَ وِزْرَكَ﴾ ﴿الَّذِي أنْقَضَ ظَهْرَكَ﴾ ، [الشرح: ٣] . وثالِثُها: ﴿ورَفَعْنا لَكَ ذِكْرَكَ﴾ [الشرح: ٤] . ثُمَّ إنَّهُ تَعالى شَرَّفَهُ في سُورَةِ التِّينِ بِثَلاثَةِ أنْواعٍ مِنَ التَّشْرِيفِ: أوَّلُها: أنَّهُ أقْسَمَ بِبَلَدِهِ وهو قَوْلُهُ: ﴿وهَذا البَلَدِ الأمِينِ﴾ [التين: ٣] . وثانِيها: أنَّهُ أخْبَرَ عَنْ خَلاصِ أُمَّتِهِ عَنِ النّارِ وهو قَوْلُهُ: ﴿إلّا الَّذِينَ آمَنُوا﴾ [التين: ٦] . وثالِثُها: وُصُولُهم إلى الثَّوابِ وهو قَوْلُهُ: ﴿فَلَهم أجْرٌ غَيْرُ مَمْنُونٍ﴾ [التين: ٦] . ثُمَّ شَرَّفَهُ في سُورَةِ ”اقْرَأْ“ بِثَلاثَةِ أنْواعٍ مِنَ التَّشْرِيفاتِ: أوَّلُها: ﴿اقْرَأْ بِاسْمِ رَبِّكَ﴾ [العلق: ١] أيِ اقْرَأِ القُرْآنَ عَلى الحَقِّ مُسْتَعِينًا بِاسْمِ رَبِّكَ. وثانِيها: أنَّهُ قَهَرَ خَصْمَهُ بِقَوْلِهِ: ﴿فَلْيَدْعُ نادِيَهُ سَنَدْعُ الزَّبانِيَةَ﴾ [العلق: ١٩] . وثالِثُها: أنَّهُ خَصَّهُ بِالقُرْبَةِ التّامَّةِ وهو: ﴿واسْجُدْ واقْتَرِبْ﴾ [العلق: ١٩] . وشَرَّفَهُ في سُورَةِ القَدْرِ بِلَيْلَةِ القَدْرِ الَّتِي لَها ثَلاثَةُ أنْواعٍ مِنَ الفَضِيلَةِ: أوَّلُها: كَوْنُها: ﴿خَيْرٌ مِن ألْفِ شَهْرٍ﴾ [القدر: ٣] . وثانِيها: نُزُولُ: ﴿المَلائِكَةُ والرُّوحُ فِيها﴾ [القدر: ٤] . وثالِثُها: كَوْنُها: ﴿سَلامٌ هي حَتّى مَطْلَعِ الفَجْرِ﴾ [القدر: ٥] . * * * وشَرَّفَهُ في سُورَةِ: (لَمْ يَكُنْ) بِأنْ شَرَّفَ أُمَّتَهُ بِثَلاثَةِ تَشْرِيفاتٍ: أوَّلُها: أنَّهم: ﴿خَيْرُ البَرِيَّةِ﴾ [البينة: ٧] وثانِيها أنَّ: ﴿جَزاؤُهم عِنْدَ رَبِّهِمْ جَنّاتُ﴾ [البينة: ٨] . وثالِثُها: ﴿رَضِيَ اللَّهُ عَنْهُمْ﴾ . وشَرَّفَهُ في سُورَةِ ”إذا زُلْزِلَتْ“ بِثَلاثِ تَشْرِيفاتٍ: أوَّلُها: قَوْلُهُ: ﴿يَوْمَئِذٍ تُحَدِّثُ أخْبارَها﴾ [الزلزلة: ٤] وذَلِكَ يَقْتَضِي أنَّ الأرْضَ تَشْهَدُ يَوْمَ القِيامَةِ لِأُمَّتِهِ بِالطّاعَةِ والعُبُودِيَّةِ. والثّانِي: قَوْلُهُ: ﴿يَوْمَئِذٍ يَصْدُرُ النّاسُ أشْتاتًا لِيُرَوْا أعْمالَهُمْ﴾ [الزلزلة: ٦] وذَلِكَ يَدُلُّ عَلى أنَّهُ تُعْرَضُ عَلَيْهِمْ طاعاتُهم فَيَحْصُلُ لَهُمُ الفَرَحُ والسُّرُورُ. وثالِثُها: قَوْلُهُ: ﴿فَمَن يَعْمَلْ مِثْقالَ ذَرَّةٍ خَيْرًا يَرَهُ﴾ [الزلزلة: ٧] ومَعْرِفَةُ اللَّهِ لا شَكَّ أنَّها أعْظَمُ مِن كُلِّ عَظِيمٍ فَلا بُدَّ وأنْ يَصِلُوا إلى ثَوابِها، ثُمَّ شَرَّفَهُ في سُورَةِ العادِياتِ بِأنْ أقْسَمَ بِخَيْلِ الغُزاةِ مِن أُمَّتِهِ فَوَصَفَ تِلْكَ الخَيْلَ بِصِفاتٍ ثَلاثٍ: ﴿والعادِياتِ ضَبْحًا﴾ ﴿فالمُورِياتِ قَدْحًا﴾ ﴿فالمُغِيراتِ صُبْحًا﴾ [العاديات: ١] . ثُمَّ شَرَّفَ أُمَّتَهُ في سُورَةِ (القارِعَةِ) بِأُمُورٍ ثَلاثَةٍ: أوَّلُها: ﴿فَمَن ثَقُلَتْ مَوازِينُهُ﴾ . وثانِيها: أنَّهم ﴿فِي عِيشَةٍ راضِيَةٍ﴾ . وثالِثُها: أنَّهم يَرَوْنَ أعْداءَهم في ﴿نارٌ حامِيَةٌ﴾ . ثُمَّ شَرَّفَهُ في سُورَةِ (ألْهاكم) بِأنْ بَيَّنَ أنَّ المُعْرِضِينَ عَنْ دِينِهِ وشَرْعِهِ يَصِيرُونَ مُعَذَّبِينَ مِن ثَلاثَةِ أوْجُهٍ: أوَّلُها: أنَّهم يَرَوْنَ الجَحِيمَ. وثانِيها: أنَّهم يَرَوْنَها عَيْنَ اليَقِينِ. وثالِثُها: أنَّهم يُسْألُونَ عَنِ النَّعِيمِ. ثُمَّ شَرَّفَ أُمَّتَهُ في سُورَةِ (والعَصْرِ) بِأُمُورٍ ثَلاثَةٍ: أوَّلُها: الإيمانُ: ﴿إلّا الَّذِينَ آمَنُوا﴾ [التين: ٦] . وثانِيها: ﴿وعَمِلُوا الصّالِحاتِ﴾ . وثالِثُها: إرْشادُ الخَلْقِ إلى الأعْمالِ الصّالِحَةِ، وهو التَّواصِي بِالحَقِّ، والتَّواصِي بِالصَّبْرِ. ثُمَّ شَرَّفَهُ في سُورَةِ الهُمَزَةِ بِأنْ ذَكَرَ أنَّ مَن هَمَزَ ولَمَزَ، فَلَهُ ثَلاثَةُ أنْواعٍ مِنَ العَذابِ: أوَّلُها: أنَّهُ لا يَنْتَفِعُ بِدُنْياهُ البَتَّةَ، وهو قَوْلُهُ: ﴿يَحْسَبُ أنَّ مالَهُ أخْلَدَهُ﴾ ﴿كَلّا﴾ [الهمزة: ٣، ٤] . وثانِيها: أنَّهُ يُنْبَذُ في الحُطَمَةِ. وثالِثُها: أنَّهُ يُغْلَقُ عَلَيْهِ تِلْكَ الأبْوابُ حَتّى لا يَبْقى لَهُ رَجاءٌ في الخُرُوجِ، وهو قَوْلُهُ: ﴿إنَّها عَلَيْهِمْ مُؤْصَدَةٌ﴾ . [الهمزة: ٨] . ثُمَّ شَرَّفَهُ في سُورَةِ (الفِيلِ) بِأنْ رَدَّ كَيْدَ أعْدائِهِ في نَحْرِهِمْ مِن ثَلاثَةِ أوْجُهٍ: أوَّلُها: جَعَلَ كَيْدَهم في تَضْلِيلٍ. وثانِيها: أرْسَلَ عَلَيْهِمْ طَيْرًا أبابِيلَ. وثالِثُها: (جَعَلَهم كَعَصْفٍ مَأْكُولٍ) . ثُمَّ شَرَّفَهُ في سُورَةِ قُرَيْشٍ بِأنَّهُ راعى مَصْلَحَةَ أسْلافِهِ مِن ثَلاثَةِ أوْجُهٍ: أوَّلُها: جَعَلَهم مُؤْتَلِفِينَ مُتَوافِقِينَ ﴿لِإيلافِ قُرَيْشٍ﴾ . وثانِيها: ﴿أطْعَمَهم مِن جُوعٍ﴾ . وثالِثُها: أنَّهُ (آمَنَهم مِن خَوْفٍ) . وشَرَّفَهُ في سُورَةِ الماعُونِ، بِأنْ وصَفَ المُكَذِّبِينَ بِدِينِهِ بِثَلاثَةِ أنْواعٍ مِنَ الصِّفاتِ المَذْمُومَةِ: أوَّلُها: الدَّناءَةُ واللُّؤْمُ، وهو قَوْلُهُ: ﴿يَدُعُّ اليَتِيمَ﴾ ﴿ولا يَحُضُّ عَلى طَعامِ المِسْكِينِ﴾ [الماعون: ٣] . وثانِيها: تَرْكُ تَعْظِيمِ الخالِقِ، وهو قَوْلُهُ: ﴿عَنْ صَلاتِهِمْ ساهُونَ﴾ ﴿الَّذِينَ هم يُراءُونَ﴾ [الماعون: ٥] . وثالِثُها: تَرْكُ انْتِفاعِ الخَلْقِ، وهو قَوْلُهُ: ﴿ويَمْنَعُونَ الماعُونَ﴾ [الماعون: ٦] . * * * ثُمَّ إنَّهُ سُبْحانَهُ وتَعالى لَمّا شَرَّفَهُ في هَذِهِ السُّوَرِ مِن هَذِهِ الوُجُوهِ العَظِيمَةِ، قالَ بَعْدَها: ﴿إنّا أعْطَيْناكَ الكَوْثَرَ﴾ أيْ: إنّا أعْطَيْناكَ هَذِهِ المَناقِبَ المُتَكاثِرَةَ المَذْكُورَةَ في السُّوَرِ المُتَقَدِّمَةِ الَّتِي كُلُّ واحِدَةٍ مِنها أعْظَمُ مِن مُلْكِ الدُّنْيا بِحَذافِيرِها، فاشْتَغِلْ أنْتَ بِعِبادَةِ هَذا الرَّبِّ، وبِإرْشادِ عِبادِهِ إلى ما هو الأصْلَحُ لَهم، أمّا عِبادَةُ الرَّبِّ فَإمّا بِالنَّفْسِ، وهو قَوْلُهُ: ﴿فَصَلِّ لِرَبِّكَ﴾ وإمّا بِالمالِ، وهو قَوْلُهُ: (وانْحَرْ) وأمّا إرْشادُ عِبادِهِ إلى ما هو الأصْلَحُ لَهم في دِينِهِمْ ودُنْياهم، فَهو قَوْلُهُ: ﴿ياأيُّها الكافِرُونَ﴾ ﴿لا أعْبُدُ ما تَعْبُدُونَ﴾ [الكافرون: ٢] فَثَبَتَ أنَّ هَذِهِ السُّورَةَ كالتَّتِمَّةِ لِما قَبْلَها مِنَ السُّورِ، وأمّا أنَّها كالأصْلِ لِما بَعْدَها، فَهو أنَّهُ تَعالى يَأْمُرُهُ بَعْدَ هَذِهِ السُّورَةِ بِأنْ يُكَفِّرَ جَمِيعَ أهْلِ الدُّنْيا بِقَوْلِهِ: ﴿ياأيُّها الكافِرُونَ﴾ ﴿لا أعْبُدُ ما تَعْبُدُونَ﴾ ومَعْلُومٌ أنَّ عَسْفَ النّاسِ عَلى مَذاهِبِهِمْ وأدْيانِهِمْ أشَدُّ مِن عَسْفِهِمْ عَلى أرْواحِهِمْ وأمْوالِهِمْ، وذَلِكَ أنَّهم يَبْذُلُونَ أمْوالَهم وأرْواحَهم في نُصْرَةِ أدْيانِهِمْ، فَلا جَرَمَ كانَ الطَّعْنُ في مَذاهِبِ النّاسِ يُثِيرُ مِنَ العَداوَةِ والغَضَبِ ما لا يُثِيرُ سائِرُ المَطاعِنِ، فَلَمّا أمَرَهُ بِأنْ يُكَفِّرَ جَمِيعَ أهْلِ الدُّنْيا، ويُبْطِلَ أدْيانَهم لَزِمَ أنْ يَصِيرَ جَمِيعُ أهْلِ الدُّنْيا في غايَةِ العَداوَةِ لَهُ، وذَلِكَ مِمّا يَحْتَرِفُ عَنْهُ كُلُّ أحَدٍ مِنَ الخَلْقِ فَلا يَكادُ يُقْدِمُ عَلَيْهِ، وانْظُرْ إلى مُوسى عَلَيْهِ السَّلامُ كَيْفَ كانَ يَخافُ مِن فِرْعَوْنَ وعَسْكَرِهِ، وأمّا هَهُنا فَإنَّ مُحَمَّدًا عَلَيْهِ السَّلامُ لَمّا كانَ مَبْعُوثًا إلى جَمِيعِ أهْلِ الدُّنْيا، كانَ كُلُّ واحِدٍ مِنَ الخَلْقِ، كَفِرْعَوْنَ بِالنِّسْبَةِ إلَيْهِ، فَدَبَّرَ تَعالى في إزالَةِ هَذا الخَوْفِ الشَّدِيدِ تَدْبِيرًا لَطِيفًا، وهو أنَّهُ قَدَّمَ عَلى تِلْكَ السُّورَةِ، هَذِهِ السُّورَةَ فَإنَّ قَوْلَهُ: ( ﴿إنّا أعْطَيْناكَ الكَوْثَرَ﴾ يُزِيلُ عَنْهُ ذَلِكَ الخَوْفَ مِن وُجُوهٍ: أحَدُها: أنَّ قَوْلَهُ: ﴿إنّا أعْطَيْناكَ الكَوْثَرَ﴾ أيِ الخَيْرَ الكَثِيرَ في الدُّنْيا والدِّينِ، فَيَكُونُ ذَلِكَ وعْدًا مِنَ اللَّهِ إيّاهُ بِالنُّصْرَةِ والحِفْظِ، وهو كَقَوْلِهِ: ﴿ياأيُّها النَّبِيُّ حَسْبُكَ اللَّهُ﴾ [الأنفال: ٦٤] وقَوْلِهِ: ﴿واللَّهُ يَعْصِمُكَ مِنَ النّاسِ﴾ [المائدة: ٦٧] وقَوْلِهِ: ﴿إلّا تَنْصُرُوهُ فَقَدْ نَصَرَهُ اللَّهُ﴾ [التوبة: ٤٠] ومَن كانَ اللَّهُ تَعالى ضامِنًا لِحِفْظِهِ، فَإنَّهُ لا يَخْشى أحَدًا. وثانِيها: أنَّهُ تَعالى لَمّا قالَ: ﴿إنّا أعْطَيْناكَ الكَوْثَرَ﴾ وهَذا اللَّفْظُ يَتَناوَلُ خَيْراتِ الدُّنْيا وخَيْراتِ الآخِرَةِ، وأنَّ خَيْراتِ الدُّنْيا ما كانَتْ واصِلَةً إلَيْهِ حِينَ كانَ بِمَكَّةَ، والخُلْفُ في كَلامِ اللَّهِ تَعالى مُحالٌ، فَوَجَبَ في حِكْمَةِ اللَّهِ تَعالى إبْقاؤُهُ في دارِ الدُّنْيا إلى حَيْثُ يَصِلُ إلَيْهِ تِلْكَ الخَيْراتُ، فَكانَ ذَلِكَ كالبِشارَةِ لَهُ والوَعْدِ بِأنَّهم لا يَقْتُلُونَهُ، ولا يَقْهَرُونَهُ، ولا يَصِلُ إلَيْهِ مَكْرُهم بَلْ يَصِيرُ أمْرُهُ كُلَّ يَوْمٍ في الِازْدِيادِ والقُوَّةِ. وثالِثُها: أنَّهُ عَلَيْهِ السَّلامُ لَمّا كَفَّرَهم وزَيَّفَ أدْيانَهم ودَعاهم إلى الإيمانِ اجْتَمَعُوا عِنْدَهُ، وقالُوا: إنْ كُنْتَ تَفْعَلُ هَذا طَلَبًا لِلْمالِ فَنُعْطِيكَ مِنَ المالِ ما تَصِيرُ بِهِ أغْنى النّاسِ، وإنْ كانَ مَطْلُوبُكَ الزَّوْجَةَ نُزَوِّجُكَ أكْرَمَ نِسائِنا، وإنْ كانَ مَطْلُوبُكَ الرِّياسَةَ فَنَحْنُ نَجْعَلُكَ رَئِيسًا عَلى أنْفُسِنا، فَقالَ اللَّهُ تَعالى: ﴿إنّا أعْطَيْناكَ الكَوْثَرَ﴾ أيْ لَمّا أعْطاكَ خالِقُ السَّماواتِ والأرْضِ خَيْراتِ الدُّنْيا والآخِرَةِ، فَلا تَغْتَرَّ بِمالِهِمْ ومُراعاتِهِمْ. ورابِعُها: أنَّ قَوْلَهُ تَعالى: ﴿إنّا أعْطَيْناكَ الكَوْثَرَ﴾ يُفِيدُ أنَّ اللَّهَ تَعالى تَكَلَّمَ مَعَهُ لا بِواسِطَةٍ، فَهَذا يَقُومُ مَقامَ قَوْلِهِ: ﴿وكَلَّمَ اللَّهُ مُوسى تَكْلِيمًا﴾ [النساء: ١٦٤] بَلْ هَذا أشْرَفُ؛ لِأنَّ المَوْلى إذا شافَهَ عَبْدَهُ بِالتِزامِ التَّرْبِيَةِ والإحْسانِ كانَ ذَلِكَ أعْلى مِمّا إذا شافَهَهُ في غَيْرِ هَذا المَعْنى، بَلْ يُفِيدُ قُوَّةً في القَلْبِ ويُزِيلُ الجُبْنَ عَنِ النَّفْسِ، فَثَبَتَ أنَّ مُخاطَبَةَ اللَّهِ إيّاهُ بِقَوْلِهِ: ﴿إنّا أعْطَيْناكَ الكَوْثَرَ﴾ مِمّا يُزِيلُ الخَوْفَ عَنِ القَلْبِ والجُبْنَ عَنِ النَّفْسِ، فَقَدَّمَ هَذِهِ السُّورَةَ عَلى سُورَةِ: ﴿قُلْ ياأيُّها الكافِرُونَ﴾ [الكافرون: ١] حَتّى يُمْكِنَهُ الِاشْتِغالُ بِذَلِكَ التَّكْلِيفِ الشّاقِّ والإقْدامِ عَلى تَكْفِيرِ جَمِيعِ العالَمِ، وإظْهارِ البَراءَةِ عَنْ مَعْبُودِهِمْ فَلَمّا امْتَثَلْتَ أمْرِي، فانْظُرْ كَيْفَ أنْجَزْتُ لَكَ الوَعْدَ، وأعْطَيْتُكَ كَثْرَةَ الأتْباعِ والأشْياعِ، إنَّ أهْلَ الدُّنْيا يَدْخُلُونَ في دِينِ اللَّهِ أفْواجًا، ثُمَّ إنَّهُ لَمّا تَمَّ أمْرُ الدَّعْوَةِ وإظْهارِ الشَّرِيعَةِ، شَرَعَ في بَيانِ ما يَتَعَلَّقُ بِأحْوالِ القَلْبِ والباطِنِ؛ وذَلِكَ لِأنَّ الطّالِبَ إمّا أنْ يَكُونَ طَلَبُهُ مَقْصُورًا عَلى الدُّنْيا، أوْ يَكُونَ طالِبًا لِلْآخِرَةِ، أمّا طالِبُ الدُّنْيا فَلَيْسَ لَهُ إلّا الخَسارُ والذُّلُّ والهَوانُ، ثُمَّ يَكُونُ مَصِيرُهُ إلى النّارِ، وهو المُرادُ مِن سُورَةِ تَبَّتْ، وأمّا طالِبُ الآخِرَةِ فَأعْظَمُ أحْوالِهِ أنْ تَصِيرَ نَفْسُهُ كالمِرْآةِ الَّتِي تَنْتَقِشُ فِيها صُوَرُ المَوْجُوداتِ، وقَدْ ثَبَتَ في العُلُومِ العَقْلِيَّةِ أنَّ طَرِيقَ الخَلْقِ في مَعْرِفَةِ الصّانِعِ عَلى وجْهَيْنِ: مِنهم مَن عَرَفَ الصّانِعَ، ثُمَّ تَوَسَّلَ بِمَعْرِفَتِهِ إلى مَعْرِفَةِ مَخْلُوقاتِهِ، وهَذا هو الطَّرِيقُ الأشْرَفُ الأعْلى، ومِنهم مَن عَكَسَ وهو طَرِيقُ الجُمْهُورِ. ثُمَّ إنَّهُ سُبْحانَهُ خَتَمَ كِتابَهُ الكَرِيمَ بِتِلْكَ الطَّرِيقِ الَّتِي هي أشْرَفُ الطَّرِيقَيْنِ، فَبَدَأ بِذِكْرِ صِفاتِ اللَّهِ وشَرْحِ جَلالِهِ، وهو سُورَةُ: ﴿قُلْ هو اللَّهُ أحَدٌ﴾ [الإخلاص: ١] ثُمَّ أتْبَعَهُ بِذِكْرِ مَراتِبِ مَخْلُوقاتِهِ في سُورَةِ: ﴿قُلْ أعُوذُ بِرَبِّ الفَلَقِ﴾ [الفلق: ١] ثُمَّ خَتَمَ الأمْرَ بِذِكْرِ مَراتِبِ النَّفْسِ الإنْسانِيَّةِ، وعِنْدَ ذَلِكَ خَتَمَ الكِتابَ، وهَذِهِ الجُمْلَةُ إنَّما يَتَّضِحُ تَفْصِيلُها عِنْدَ تَفْسِيرِ هَذِهِ السُّورَةِ عَلى التَّفْصِيلِ، فَسُبْحانَ مَن أرْشَدَ العُقُولَ إلى مَعْرِفَةِ هَذِهِ الأسْرارِ الشَّرِيفَةِ المُودَعَةِ في كِتابِهِ الكَرِيمِ. الفائِدَةُ الثّانِيَةُ في قَوْلِهِ: ﴿إنّا أعْطَيْناكَ الكَوْثَرَ﴾ هي أنَّ كَلِمَةَ: (إنّا) تارَةً يُرادُ بِها الجَمْعُ وتارَةً يُرادُ بِها التَّعْظِيمُ. أمّا الأوَّلُ: فَقَدْ دَلَّ عَلى أنَّ الإلَهَ واحِدٌ، فَلا يُمْكِنُ حَمْلُهُ عَلى الجَمْعِ، إلّا إذا أُرِيدَ أنَّ هَذِهِ العَطِيَّةَ مِمّا سَعى في تَحْصِيلِها المَلائِكَةُ وجِبْرِيلُ ومِيكائِيلُ والأنْبِياءُ المُتَقَدِّمُونَ، حِينَ سَألَ إبْراهِيمُ إرْسالَكَ، فَقالَ: ﴿رَبَّنا وابْعَثْ فِيهِمْ رَسُولًا مِنهُمْ﴾ [البقرة: ١٢٩] وقالَ مُوسى: رَبِّ اجْعَلْنِي مِن أُمَّةِ أحْمَدَ. وهو المُرادُ مِن قَوْلِهِ: ﴿وما كُنْتَ بِجانِبِ الغَرْبِيِّ إذْ قَضَيْنا إلى مُوسى الأمْرَ﴾ [القصص: ٤٤] وبَشَّرَ بِكَ المَسِيحُ في قَوْلِهِ: ﴿ومُبَشِّرًا بِرَسُولٍ يَأْتِي مِن بَعْدِي اسْمُهُ أحْمَدُ﴾ [الصف: ٦] . وأمّا الثّانِي: وهو أنْ يَكُونَ ذَلِكَ مَحْمُولًا عَلى التَّعْظِيمِ، فَفِيهِ تَنْبِيهٌ عَلى عَظَمَةِ العَطِيَّةِ لِأنَّ الواهِبَ هو جَبّارُ السَّماواتِ والأرْضِ والمَوْهُوبَ مِنهُ، هو المُشارُ إلَيْهِ بِكافِ الخِطابِ في قَوْلِهِ تَعالى: ﴿إنّا أعْطَيْناكَ﴾ والهِبَةُ هي الشَّيْءُ المُسَمّى بِالكَوْثَرِ، وهو ما يُفِيدُ المُبالَغَةَ في الكَثْرَةِ، ولَمّا أشْعَرَ اللَّفْظُ بِعِظَمِ الواهِبِ والمَوْهُوبِ مِنهُ والمَوْهُوبِ، فَيا لَها مِن نِعْمَةٍ ما أعْظَمَها، وما أجَلَّها، ويا لَهُ مِن تَشْرِيفٍ ما أعْلاهُ. * * * الفائِدَةُ الثّالِثَةُ: أنَّ الهَدِيَّةَ وإنْ كانَتْ قَلِيلَةً لَكِنَّها بِسَبَبِ كَوْنِها واصِلَةً مِنَ المُهْدِي العَظِيمِ تَصِيرُ عَظِيمَةً، ولِذَلِكَ فَإنَّ المَلِكَ العَظِيمَ إذا رَمى تُفّاحَةً لِبَعْضِ عَبِيدِهِ عَلى سَبِيلِ الإكْرامِ يُعَدُّ ذَلِكَ إكْرامًا عَظِيمًا، لا لِأنَّ لَذَّةَ الهَدِيَّةِ في نَفْسِها، بَلْ لِأنَّ صُدُورَها مِنَ المُهْدِي العَظِيمِ يُوجِبُ كَوْنَها عَظِيمَةً، فَهَهُنا الكَوْثَرُ وإنْ كانَ في نَفْسِهِ في غايَةِ الكَثْرَةِ، لَكِنَّهُ بِسَبَبِ صُدُورِهِ مِن مَلِكِ الخَلائِقِ يَزْدادُ عَظْمَةً وكَمالًا. الفائِدَةُ الرّابِعَةُ: أنَّهُ لَمّا قالَ: (أعْطَيْناكَ) قَرَنَ بِهِ قَرِينَةً دالَّةً عَلى أنَّهُ لا يَسْتَرْجِعُها، وذَلِكَ لِأنَّ مِن مَذْهَبِ أبِي حَنِيفَةَ أنَّهُ يَجُوزُ لِلْأجْنَبِيِّ أنْ يَسْتَرْجِعَ مَوْهُوبَهُ، فَإنْ أخَذَ عِوَضًا وإنْ قَلَّ لَمْ يَجُزْ لَهُ ذَلِكَ الرُّجُوعُ؛ لِأنَّ مَن وهَبَ شَيْئًا يُساوِي ألْفَ دِينارٍ إنْسانًا، ثُمَّ طَلَبَ مِنهُ مُشْطًا يُساوِي فَلْسًا فَأعْطاهُ، سَقَطَ حَقُّ الرُّجُوعِ فَهَهُنا لَمّا قالَ: ﴿إنّا أعْطَيْناكَ الكَوْثَرَ﴾ طَلَبَ مِنهُ الصَّلاةَ والنَّحْرَ، وفائِدَتُهُ إسْقاطُ حَقِّ الرُّجُوعِ. الفائِدَةُ الخامِسَةُ: أنَّهُ بَنى الفِعْلَ عَلى المُبْتَدَأِ، وذَلِكَ يُفِيدُ التَّأْكِيدَ، والدَّلِيلُ عَلَيْهِ أنَّكَ لَمّا ذَكَرْتَ الِاسْمَ المُحَدَّثَ عَنْهُ عَرَفَ العَقْلُ أنَّهُ يُخْبِرُ عَنْهُ بِأمْرٍ فَيَصْبِرُ مُشْتاقًا إلى مَعْرِفَةِ أنَّهُ بِماذا يُخْبِرُ عَنْهُ، فَإذا ذَكَرَ ذَلِكَ الخَبَرَ قَبِلَهُ قَبُولَ العاشِقِ لِمَعْشُوقِهِ، فَيَكُونُ ذَلِكَ أبْلَغَ في التَّحْقِيقِ ونَفْيِ الشُّبْهَةِ ومِن هَهُنا تَعْرِفُ الفَخامَةَ في قَوْلِهِ: ﴿فَإنَّها لا تَعْمى الأبْصارُ﴾ [الحج: ٤٦] فَإنَّهُ أكْثَرُ فَخامَةً مِمّا لَوْ قالَ: فَإنَّ الأبْصارَ لا تَعْمى، ومِمّا يُحَقِّقُ قَوْلَنا قَوْلُ المَلِكِ العَظِيمِ لِمَن يَعِدُهُ ويَضْمَنُ لَهُ: أنا أُعْطِيكَ، أنا أكْفِيكَ، أنا أقُومُ بِأمْرِكَ، وذَلِكَ إذا كانَ المَوْعُودُ بِهِ أمْرًا عَظِيمًا قَلَّما تَقَعُ المُسامَحَةُ بِهِ فَعِظَمُهُ يُورِثُ الشَّكَّ في الوَفاءِ بِهِ، فَإذا أُسْنِدَ إلى المُتَكَفِّلِ العَظِيمِ، فَحِينَئِذٍ يَزُولُ ذَلِكَ الشَّكُّ، وهَذِهِ الآيَةُ مِن هَذا البابِ لِأنَّ الكَوْثَرَ شَيْءٌ عَظِيمٌ، قَلَّما تَقَعُ المُسامَحَةُ بِهِ، فَلَمّا قَدَّمَ المُبْتَدَأ، وهو قَوْلُهُ: (إنّا) صارَ ذَلِكَ الإسْنادُ مُزِيلًا لِذَلِكَ الشَّكِّ ودافِعًا لِتِلْكَ الشُّبْهَةِ. الفائِدَةُ السّادِسَةُ: أنَّهُ تَعالى صَدَّرَ الجُمْلَةَ بِحَرْفِ التَّأْكِيدِ الجارِي مُجْرى القَسَمِ، وكَلامُ الصّادِقِ مَصُونٌ عَنِ الخُلْفِ، فَكَيْفَ إذا بالَغَ في التَّأْكِيدِ ؟ الفائِدَةُ السّابِعَةُ: قالَ: (أعْطَيْناكَ) ولَمْ يَقُلْ: سَنُعْطِيكَ لِأنَّ قَوْلَهُ: (أعْطَيْناكَ) يَدُلُّ عَلى أنَّ هَذا الإعْطاءَ كانَ حاصِلًا في الماضِي، وهَذا فِيهِ أنْواعٌ مِنَ الفَوائِدِ: إحْداها: أنَّ مَن كانَ في الزَّمانِ الماضِي أبَدًا عَزِيزًا مَرْعِيَّ الجانِبِ مَقْضِيَّ الحاجَّةِ أشْرَفُ مِمَّنْ سَيَصِيرُ كَذَلِكَ، ولِهَذا قالَ عَلَيْهِ السَّلامُ: «كُنْتُ نَبِيًّا وآدَمُ بَيْنَ الماءِ والطِّينِ» . وثانِيها: أنَّها إشارَةٌ إلى أنَّ حُكْمَ اللَّهِ بِالإسْعادِ والإشْقاءِ والإغْناءِ والإفْقارِ، لَيْسَ أمْرًا يَحْدُثُ الآنَ، بَلْ كانَ حاصِلًا في الأزَلِ. وثالِثُها: كَأنَّهُ يَقُولُ: إنّا قَدْ هَيَّأْنا أسْبابَ سَعادَتِكَ قَبْلَ دُخُولِكَ في الوُجُودِ فَكَيْفَ نُهْمِلُ أمْرَكَ بَعْدَ وُجُودِكَ واشْتِغالِكَ بِالعُبُودِيَّةِ ؟ . ورابِعُها: كَأنَّهُ تَعالى يَقُولُ: نَحْنُ ما اخْتَرْناكَ وما فَضَّلْناكَ، لِأجْلِ طاعَتِكَ، وإلّا كانَ يَجِبُ أنْ لا نُعْطِيَكَ إلّا بَعْدَ إقْدامِكَ عَلى الطّاعَةِ، بَلْ إنَّما اخْتَرْناكَ بِمُجَرَّدِ الفَضْلِ والإحْسانِ مِنّا إلَيْكَ مِن غَيْرِ مُوجِبٍ، وهو إشارَةٌ إلى قَوْلِهِ عَلَيْهِ الصَّلاةُ والسَّلامُ: «قَبِلَ مَن قَبِلَ لا لِعِلَّةٍ، ورَدَّ مَن رَدَّ لا لِعِلَّةٍ» . * * * الفائِدَةُ الثّامِنَةُ: قالَ: (أعْطَيْناكَ) ولَمْ يَقُلْ أعْطَيْنا الرَّسُولَ أوِ النَّبِيَّ أوِ العالِمَ أوِ المُطِيعَ؛ لِأنَّهُ لَوْ قالَ ذَلِكَ لَأشْعَرَ أنَّ تِلْكَ العَطِيَّةَ وقَعَتْ مُعَلَّلَةً بِذَلِكَ الوَصْفِ، فَلَمّا قالَ: (أعْطَيْناكَ) عُلِمَ أنَّ تِلْكَ العَطِيَّةَ غَيْرُ مُعَلَّلَةٍ بِعِلَّةٍ أصْلًا بَلْ هي مَحْضُ الِاخْتِيارِ والمَشِيئَةِ، كَما قالَ: ﴿نَحْنُ قَسَمْنا﴾ [الزخرف: ٣٢] ، ﴿اللَّهُ يَصْطَفِي مِنَ المَلائِكَةِ رُسُلًا ومِنَ النّاسِ﴾ [الحج: ٧٥] . الفائِدَةُ التّاسِعَةُ: قالَ أوَّلًا: ﴿إنّا أعْطَيْناكَ﴾ ثُمَّ قالَ ثانِيًا: ﴿فَصَلِّ لِرَبِّكَ وانْحَرْ﴾ وهَذا يَدُلُّ عَلى أنَّ إعْطاءَهُ لِلتَّوْفِيقِ والإرْشادِ سابِقٌ عَلى طاعاتِنا، وكَيْفَ لا يَكُونُ كَذَلِكَ وإعْطاؤُهُ إيّانا صِفَتُهُ، وطاعَتُنا لَهُ صِفَتُنا، وصِفَةُ الخَلْقِ لا تَكُونُ مُؤَثِّرَةً في صِفَةِ الخالِقِ إنَّما المُؤَثِّرُ هو صِفَةُ الخالِقِ في صِفَةِ الخَلْقِ، ولِهَذا نُقِلَ عَنِ الواسِطِيِّ أنَّهُ قالَ: لا أعْبُدُ رَبًّا يُرْضِيهِ طاعَتِي ويُسْخِطُهُ مَعْصِيَتِي، ومَعْناهُ أنَّ رِضاهُ وسُخْطَهُ قَدِيمانِ وطاعَتِي ومَعْصِيَتِي مُحْدَثَتانِ والمُحْدَثُ لا أثَرَ لَهُ في قَدِيمٍ، بَلْ رِضاهُ عَنِ العَبْدِ هو الَّذِي حَمَلَهُ عَلى طاعَتِهِ فِيما لا يَزالُ، وكَذا القَوْلُ في السُّخْطِ والمَعْصِيَةِ. الفائِدَةُ العاشِرَةُ: قالَ: ﴿أعْطَيْناكَ الكَوْثَرَ﴾ ولَمْ يَقُلْ: آتَيْناكَ الكَوْثَرَ، والسَّبَبُ فِيهِ أمْرانِ: الأوَّلُ: أنَّ الإيتاءَ يُحْتَمَلُ أنْ يَكُونَ واجِبًا وأنْ يَكُونَ تَفَضُّلًا، وأمّا الإعْطاءُ فَإنَّهُ بِالتَّفَضُّلِ أشْبَهُ فَقَوْلُهُ: ﴿إنّا أعْطَيْناكَ الكَوْثَرَ﴾ يَعْنِي: هَذِهِ الخَيْراتُ الكَثِيرَةُ وهي الإسْلامُ والقُرْآنُ والنُّبُوَّةُ والذِّكْرُ الجَمِيلُ في الدُّنْيا والآخِرَةِ، مَحْضُ التَّفَضُّلِ مِنّا إلَيْكَ ولَيْسَ مِنهُ شَيْءٌ عَلى سَبِيلِ الِاسْتِحْقاقِ والوُجُوبِ، وفِيهِ بِشارَةٌ مِن وجْهَيْنِ: أحَدُهُما: أنَّ الكَرِيمَ إذا شَرَعَ في التَّرْبِيَةِ عَلى سَبِيلِ التَّفَضُّلِ، فالظّاهِرُ أنَّهُ لا يُبْطِلُها، بَلْ كانَ كُلَّ يَوْمٍ يَزِيدُ فِيها الثّانِي: أنَّ ما يَكُونُ سَبَبَ الِاسْتِحْقاقِ، فَإنَّهُ يَتَقَدَّرُ بِقَدْرِ الِاسْتِحْقاقِ، وفِعْلُ العَبْدِ مُتَناهٍ، فَيَكُونُ الِاسْتِحْقاقُ الحاصِلُ بِسَبَبِهِ مُتَناهِيًا، أمّا التَّفَضُّلُ فَإنَّهُ نَتِيجَةُ كَرَمِ اللَّهِ غَيْرُ مُتَناهٍ، فَيَكُونُ تَفَضُّلُهُ أيْضًا غَيْرَ مُتَناهٍ، فَلَمّا دَلَّ قَوْلُهُ: (أعْطَيْناكَ) عَلى أنَّهُ تَفَضُّلٌ لا اسْتِحْقاقٌ أشْعَرَ ذَلِكَ بِالدَّوامِ والتَّزايُدِ أبَدًا. فَإنْ قِيلَ: ألَيْسَ قالَ: ﴿سَبْعًا مِنَ المَثانِي والقُرْآنَ﴾ [الحجر: ٨٧] ؟ قُلْنا: الجَوابُ مِن وجْهَيْنِ: الأوَّلُ: أنَّ الإعْطاءَ يُوجِبُ التَّمْلِيكَ، والمِلْكُ سَبَبُ الِاخْتِصاصِ، والدَّلِيلُ عَلَيْهِ أنَّهُ لَمّا قالَ سُلَيْمانُ: ﴿هَبْ لِي مُلْكًا﴾ [ص: ٣٥] فَقالَ: ﴿هَذا عَطاؤُنا فامْنُنْ أوْ أمْسِكْ﴾ [ص: ٣٩] ولِهَذا السَّبَبِ مَن حَمَلَ الكَوْثَرَ عَلى الحَوْضِ قالَ: الأُمَّةُ تَكُونُ أضْيافًا لَهُ، أمّا الإيتاءُ فَإنَّهُ لا يُفِيدُ المِلْكَ، فَلِهَذا قالَ في القُرْآنِ: (آتَيْناكَ) [الحجر: ٨٧] فَإنَّهُ لا يَجُوزُ لِلنَّبِيِّ أنْ يَكْتُمَ شَيْئًا مِنهُ. الثّانِي: أنَّ الشَّرِكَةَ في القُرْآنِ شَرِكَةٌ في العُلُومِ ولا عَيْبَ فِيها، أمّا الشَّرِكَةُ في النَّهْرِ، فَهي شَرِكَةٌ في الأعْيانِ وهي عَيْبٌ. الوَجْهُ الثّانِي: في بَيانِ أنَّ الإعْطاءَ ألْيَقُ بِهَذا المَقامِ مِنَ الإيتاءِ، هو أنَّ الإعْطاءَ يُسْتَعْمَلُ في القَلِيلِ والكَثِيرِ، قالَ اللَّهُ تَعالى: ﴿وأعْطى قَلِيلًا وأكْدى﴾ [النجم: ٣٤] أمّا الإيتاءُ، فَلا يُسْتَعْمَلُ إلّا في الشَّيْءِ العَظِيمِ، قالَ اللَّهُ تَعالى: ﴿وآتاهُ اللَّهُ المُلْكَ﴾ [البقرة: ٢٥٢] ﴿ولَقَدْ آتَيْنا داوُدَ مِنّا فَضْلًا﴾ [سبأ: ١٠] والأتِيُّ السَّيْلُ المُنْصَبُّ، إذا ثَبَتَ هَذا فَقَوْلُهُ: ﴿إنّا أعْطَيْناكَ الكَوْثَرَ﴾ يُفِيدُ تَعْظِيمَ حالِ مُحَمَّدٍ ﷺ مِن وُجُوهٍ: أحَدُها: يَعْنِي: هَذا الحَوْضُ كالشَّيْءِ القَلِيلِ الحَقِيرِ بِالنِّسْبَةِ إلى ما هو مُدَّخَرٌ لَكَ مِنَ الدَّرَجاتِ العالِيَةِ والمَراتِبِ الشَّرِيفَةِ، فَهو يَتَضَمَّنُ البِشارَةَ بِأشْياءَ هي أعْظَمُ مِن هَذا المَذْكُورِ. وثانِيها: أنَّ الكَوْثَرَ إشارَةٌ إلى الماءِ، كَأنَّهُ تَعالى يَقُولُ: الماءُ في الدُّنْيا دُونَ الطَّعامِ، فَإذا كانَ نَعِيمُ الماءِ كَوْثَرًا، فَكَيْفَ سائِرُ النَّعِيمِ ؟ . وثالِثُها: أنَّ نَعِيمَ الماءِ إعْطاءٌ ونَعِيمَ الجَنَّةِ إيتاءٌ. ورابِعُها: كَأنَّهُ تَعالى يَقُولُ: هَذا الَّذِي أعْطَيْتُكَ، وإنْ كانَ كَوْثَرًا لَكِنَّهُ في حَقِّكَ إعْطاءٌ لا إيتاءٌ؛ لِأنَّهُ دُونَ حَقِّكَ، وفي العادَةِ أنَّ المُهْدِي إذا كانَ عَظِيمًا فالهَدِيَّةُ وإنْ كانَتْ عَظِيمَةً، إلّا أنَّهُ يُقالُ: إنَّها حَقِيرَةٌ أيْ هي حَقِيرَةٌ بِالنِّسْبَةِ إلى عَظَمَةِ المُهْدى لَهُ فَكَذا هَهُنا. وخامِسُها: أنْ نَقُولَ: إنَّما قالَ فِيما أعْطاهُ مِنَ الكَوْثَرِ أعْطَيْناكَ؛ لِأنَّهُ دُنْيا، والقُرْآنُ إيتاءٌ لِأنَّهُ دِينٌ. وسادِسُها: كَأنَّهُ يَقُولُ: جَمِيعُ ما نِلْتَ مِنِّي عَطِيَّةٌ وإنْ كانَتْ كَوْثَرًا إلّا أنَّ الأعْظَمَ مِن ذَلِكَ الكَوْثَرِ أنْ تَبْقى مُظَفَّرًا وخَصْمُكَ أبْتَرُ، فَإنّا أعْطَيْناكَ بِالتَّقْدِمَةِ هَذا الكَوْثَرَ، أمّا الذِّكْرُ الباقِي والظَّفَرُ عَلى العَدُوِّ فَلا يَحْسُنُ إعْطاؤُهُ إلّا بَعْدَ التَّقْدِمَةِ بِطاعَةٍ تَحْصُلُ مِنكَ: ﴿فَصَلِّ لِرَبِّكَ وانْحَرْ﴾ أيْ فاعْبُدْ لِي وسَلِ الظَّفَرَ بَعْدَ العِبادَةِ فَإنِّي أوْجَبْتُ عَلى كَرَمِي أنَّ بَعْدَ كُلِّ فَرِيضَةٍ دَعْوَةً مُسْتَجابَةً، كَذا رُوِيَ في الحَدِيثِ المُسْنَدِ، فَحِينَئِذٍ أسْتَجِيبُ فَيَصِيرُ خَصْمُكَ أبْتَرَ وهو الإيتاءُ، فَهَذا ما يَخْطُرُ بِالبالِ في تَفْسِيرِ قَوْلِهِ تَعالى: ﴿إنّا أعْطَيْناكَ﴾ أمّا الكَوْثَرُ فَهو في اللُّغَةِ فَوَعْلٌ مِنَ الكَثْرَةِ وهو المُفْرِطُ في الكَثْرَةِ، قِيلَ لِأعْرابِيَّةٍ رَجَعَ ابْنُها مِنَ السَّفَرِ، بِمَ آبَ ابْنُكم ؟ قالَتْ: آبَ بِكَوْثَرٍ، أيْ بِالعَدَدِ الكَثِيرِ، ويُقالُ لِلرَّجُلِ الكَثِيرِ العَطاءِ: كَوْثَرٌ، قالَ الكُمَيْتُ: وأنْتَ كَثِيرٌ يا ابْنَ مَرْوانَ طَيِّبُ وكانَ أبُوكَ ابْنُ الفَضائِلِ كَوْثَرا ويُقالُ لِلْغُبارِ إذا سَطَعَ وكَثُرَ كَوْثَرٌ هَذا مَعْنى الكَوْثَرِ في اللُّغَةِ، واخْتَلَفَ المُفَسِّرُونَ فِيهِ عَلى وُجُوهٍ: الأوَّلُ: وهو المَشْهُورُ والمُسْتَفِيضُ عِنْدَ السَّلَفِ والخَلَفِ أنَّهُ نَهْرٌ في الجَنَّةِ، رَوى أنَسٌ عَنِ النَّبِيِّ ﷺ قالَ: ( «رَأيْتُ نَهْرًا في الجَنَّةِ حافَتاهُ قِبابُ اللُّؤْلُؤِ المُجَوَّفِ فَضَرَبْتُ بِيَدِي إلى مَجْرى الماءِ فَإذا أنا بِمِسْكٍ أذْفَرَ، فَقُلْتُ: ما هَذا ؟ قِيلَ: الكَوْثَرُ الَّذِي أعْطاكَ اللَّهُ» ) وفي رِوايَةِ أنَسٍ: «أشَدُّ بَياضًا مِنَ اللَّبَنِ وأحْلى مِنَ العَسَلِ، فِيهِ طُيُورٌ خُضْرٌ لَها أعْناقٌ كَأعْناقِ البُخْتِ مَن أكَلَ مِن ذَلِكَ الطَّيْرِ وشَرِبَ مِن ذَلِكَ الماءِ فازَ بِالرِّضْوانِ» ، ولَعَلَّهُ إنَّما سُمِّيَ ذَلِكَ النَّهْرُ كَوْثَرًا إمّا لِأنَّهُ أكْثَرُ أنْهارِ الجَنَّةِ ماءً وخَيْرًا، أوْ لِأنَّهُ انْفَجَرَ مِنهُ أنْهارُ الجَنَّةِ، كَما رُوِيَ أنَّهُ ما في الجَنَّةِ بُسْتانٌ إلّا وفِيهِ مِنَ الكَوْثَرِ نَهْرٌ جارٍ، أوْ لِكَثْرَةِ الَّذِينَ يَشْرَبُونَ مِنها، أوْ لِكَثْرَةِ ما فِيها مِنَ المَنافِعِ عَلى ما قالَ عَلَيْهِ السَّلامُ: «إنَّهُ نَهْرٌ وعَدَنِيهِ رَبِّي فِيهِ خَيْرٌ كَثِيرٌ» القَوْلُ الثّانِي: أنَّهُ حَوْضٌ والأخْبارُ فِيهِ مَشْهُورَةٌ ووَجْهُ التَّوْفِيقِ بَيْنَ هَذا القَوْلِ، والقَوْلِ الأوَّلِ أنْ يُقالَ: لَعَلَّ النَّهْرَ يَنْصَبُّ في الحَوْضِ أوْ لَعَلَّ الأنْهارَ إنَّما تَسِيلُ مِن ذَلِكَ الحَوْضِ فَيَكُونُ ذَلِكَ الحَوْضُ كالمَنبَعِ والقَوْلُ الثّالِثُ: الكَوْثَرُ أوْلادُهُ قالُوا: لِأنَّ هَذِهِ السُّورَةَ إنَّما نَزَلَتْ رَدًّا عَلى مَن عابَهُ عَلَيْهِ السَّلامُ بِعَدَمِ الأوْلادِ، فالمَعْنى أنَّهُ يُعْطِيهِ نَسْلًا يَبْقَوْنَ عَلى مَرِّ الزَّمانِ، فانْظُرْ كَمْ قُتِلَ مِن أهْلِ البَيْتِ، ثُمَّ العالَمُ مُمْتَلِئٌ مِنهم، ولَمْ يَبْقَ مِن بَنِي أُمَيَّةَ في الدُّنْيا أحَدٌ يُعْبَأُ بِهِ، ثُمَّ انْظُرْ كَمْ كانَ فِيهِمْ مِنَ الأكابِرِ مِنَ العُلَماءِ كالباقِرِ والصّادِقِ والكاظِمِ والرِّضا عَلَيْهِمُ السَّلامُ والنَّفْسُ الزَّكِيَّةُ وأمْثالُهم. القَوْلُ الرّابِعُ: الكَوْثَرُ عُلَماءُ أُمَّتِهِ وهو لَعَمْرِي الخَيْرُ الكَثِيرِ؛ لِأنَّهم كَأنْبِياءِ بَنِي إسْرائِيلَ، وهم يُحِبُّونَ ذِكْرَ رَسُولِ اللَّهِ ﷺ ويَنْشُرُونَ آثارَ دِينِهِ وأعْلامَ شَرْعِهِ، ووَجْهُ التَّشْبِيهِ أنَّ الأنْبِياءَ كانُوا مُتَّفِقِينَ عَلى أُصُولِ مَعْرِفَةِ اللَّهِ مُخْتَلِفِينَ في الشَّرِيعَةِ رَحْمَةً عَلى الخَلْقِ لِيَصِلَ كُلُّ أحَدٍ إلى ما هو صَلاحُهُ، كَذا عُلَماءُ أُمَّتِهِ مُتَّفِقُونَ بِأسْرِهِمْ عَلى أُصُولِ شَرْعِهِ، لَكِنَّهم مُخْتَلِفُونَ في فُرُوعِ الشَّرِيعَةِ رَحْمَةً عَلى الخَلْقِ، ثُمَّ الفَضِيلَةُ مِن وجْهَيْنِ: أحَدُهُما: أنَّهُ يُرْوى أنَّهُ يُجاءُ يَوْمَ القِيامَةِ بِكُلِّ نَبِيٍّ ويَتْبَعُهُ أُمَّتُهُ فَرُبَّما يَجِيءُ الرَّسُولُ ومَعَهُ الرَّجُلُ والرَّجُلانِ، ويُجاءُ بِكُلِّ عالِمٍ مِن عُلَماءِ أُمَّتِهِ ومَعَهُ الأُلُوفُ الكَثِيرَةُ فَيَجْتَمِعُونَ عِنْدَ الرَّسُولِ فَرُبَّما يَزِيدُ عَدَدُ مُتَّبِعِي بَعْضِ العُلَماءِ عَلى عَدَدِ مُتَّبِعِي ألْفٍ مِنَ الأنْبِياءِ. الوَجْهُ الثّانِي: أنَّهم كانُوا مُصِيبِينَ لِاتِّباعِهِمُ النُّصُوصَ المَأْخُوذَةَ مِنَ الوَحْيِ، وعُلَماءُ هَذِهِ الأُمَّةِ يَكُونُونَ مُصِيبِينَ مَعَ كَدِّ الِاسْتِنْباطِ والِاجْتِهادِ، أوْ عَلى قَوْلِ البَعْضِ: إنْ كانَ بَعْضُهم مُخْطِئًا لَكِنَّ المُخْطِئَ يَكُونُ أيْضًا مَأْجُورًا القَوْلُ الخامِسُ: الكَوْثَرُ هي النُّبُوَّةُ، ولا شَكَّ أنَّها الخَيْرُ الكَثِيرُ؛ لِأنَّها المَنزِلَةُ الَّتِي هي ثانِيَةُ الرُّبُوبِيَّةِ؛ ولِهَذا قالَ: ﴿مَن يُطِعِ الرَّسُولَ فَقَدْ أطاعَ اللَّهَ﴾ [النساء: ٨٠] وهو شَطْرُ الإيمانِ بَلْ هي كالغُصْنِ في مَعْرِفَةِ اللَّهِ تَعالى؛ لِأنَّ مَعْرِفَةَ النُّبُوَّةِ لا بُدَّ وأنْ يَتَقَدَّمَها مَعْرِفَةُ ذاتِ اللَّهِ وعِلْمِهِ وقُدْرَتِهِ وحِكْمَتِهِ، ثُمَّ إذا حَصَلَتْ مَعْرِفَةُ النُّبُوَّةِ فَحِينَئِذٍ يُسْتَفادُ مِنها مَعْرِفَةُ بَقِيَّةِ الصِّفاتِ كالسَّمْعِ والبَصَرِ والصِّفاتِ الخَيْرِيَّةِ، والوِجْدانِيَّةِ عَلى قَوْلِ بَعْضِهِمْ، تَمَّ لِرَسُولِنا الحَظُّ الأوْفَرُ مِن هَذِهِ المَنقَبَةِ؛ لِأنَّهُ المَذْكُورُ قَبْلَ سائِرِ الأنْبِياءِ والمَبْعُوثُ بَعْدَهم، ثُمَّ هو مَبْعُوثٌ إلى الثَّقَلَيْنِ، وهو الَّذِي يُحْشَرُ قَبْلَ كُلِّ الأنْبِياءِ، ولا يَجُوزُ وُرُودُ الشَّرْعِ عَلى نَسْخِهِ، وفَضائِلُهُ أكْثَرُ مِن أنْ تُعَدَّ وتُحْصى، ولْنَذْكُرْ هَهُنا قَلِيلًا مِنها، فَنَقُولُ: * * * إنَّ كِتابَ آدَمَ عَلَيْهِ السَّلامُ كانَ كَلِماتٍ عَلى ما قالَ تَعالى: ﴿فَتَلَقّى آدَمُ مِن رَبِّهِ كَلِماتٍ﴾ [البقرة: ٣٧] وكِتابَ إبْراهِيمَ أيْضًا كانَ كَلِماتٍ عَلى ما قالَ: ﴿وإذِ ابْتَلى إبْراهِيمَ رَبُّهُ بِكَلِماتٍ﴾ [البقرة: ١٢٤] وكِتابَ مُوسى كانَ صُحُفًا، كَما قالَ: ﴿صُحُفِ إبْراهِيمَ ومُوسى﴾ [الأعلى: ١٩] أمّا كِتابُ مُحَمَّدٍ عَلَيْهِ السَّلامُ، فَإنَّهُ هو الكِتابُ المُهَيْمِنُ عَلى الكُلِّ، قالَ: ﴿ومُهَيْمِنًا عَلَيْهِ﴾ [المائدة: ٤٨] وأيْضًا فَإنَّ آدَمَ عَلَيْهِ السَّلامُ إنَّما تَحَدّى بِالأسْماءِ المَنثُورَةِ فَقالَ: ﴿أنْبِئُونِي بِأسْماءِ هَؤُلاءِ﴾ [البقرة: ٣١] ومُحَمَّدٌ عَلَيْهِ الصَّلاةُ والسَّلامُ إنَّما تَحَدّى بِالمَنظُومِ: ﴿قُلْ لَئِنِ اجْتَمَعَتِ الإنْسُ والجِنُّ﴾ [الإسراء: ٨٨] وأمّا نُوحٌ عَلَيْهِ السَّلامُ، فَإنَّ اللَّهَ أكْرَمَهُ بِأنْ أمْسَكَ سَفِينَتَهُ عَلى الماءِ، وفَعَلَ في مُحَمَّدٍ ﷺ ما هو أعْظَمُ مِنهُ، رُوِيَ «أنَّ النَّبِيَّ عَلَيْهِ الصَّلاةُ والسَّلامُ: كانَ عَلى شَطِّ ماءٍ، ومَعَهُ عِكْرِمَةُ بْنُ أبِي جَهْلٍ، فَقالَ: لَئِنْ كُنْتَ صادِقًا فادْعُ ذَلِكَ الحَجَرَ الَّذِي هو في الجانِبِ الآخَرِ فَلْيَسْبَحْ ولا يَغْرَقْ، فَأشارَ الرَّسُولُ إلَيْهِ، فانْقَلَعَ الحَجَرُ الَّذِي أشارَ إلَيْهِ مِن مَكانِهِ، وسَبَحَ حَتّى صارَ بَيْنَ يَدَيِ الرَّسُولِ عَلَيْهِ السَّلامُ، وسَلَّمَ عَلَيْهِ، وشَهِدَ لَه…',     source_page = '110', 